def _workflow_attempt_write_fence(session: Any, job_id: str, order_id: str, *, source_failure: str | None = None) -> bool:
    """Fence workflow-owned writes with the queue-captured revision and attempt."""
    workflow_attempt_id = _workflow_ocr_attempt_id.get()
    expected_workflow_revision = _workflow_ocr_revision.get()
    return lock_actual_write_ownership(
        session,
        job_id=job_id,
        workflow_attempt_id=workflow_attempt_id,
        order_id=order_id,
        expected_workflow_revision=expected_workflow_revision,
        source_failure=source_failure,
    )


def _capture_selected_order_config(session: Any, order: Order) -> dict[str, Any]:
    from src.services.workflow_attempt_guard_service import _order_execution_input

    return _order_execution_input(session, order, lock=True)["configured_input"]


def _capture_synchronous_cache_write_input(order_id: str, *, write_session: Any = None, for_materialization: bool = False) -> dict[str, Any] | None:
    """Capture the exact operator-read inputs required for a later cache CAS."""
    with (nullcontext(write_session) if write_session is not None else session_scope()) as session:
        from src.services.initial_saved_import_service import get_binding, execution_input, processing_input
        from src.services.initial_saved_source_service import source_receipt
        imported = get_binding(session, order_id)
        if imported is not None:
            captured = processing_input(session, imported) if for_materialization else execution_input(session, imported)
            snapshot = imported["snapshot"]
            return {"order_id": order_id, "workflow_revision": snapshot["workflow"]["revision"],
                    "workflow_meta": deepcopy(snapshot["workflow"]["secondary_actions_json"]),
                    "draft_id": snapshot["draft"]["id"], "evidence_run_id": snapshot["workflow"]["evidence_run_id"],
                    "draft_base_evidence_run_id": snapshot["draft"]["base_evidence_run_id"],
                    "evidence": snapshot["evidence"], "draft": snapshot["draft"],
                    "configured_input": captured["configured_input"], "physical_menu_entries": captured["physical_menu_entries"],
                    "input_versions": {"order_lines": snapshot["lines"], "draft": snapshot["draft"], "evidence": snapshot["evidence"]},
                    "initial_saved_import": captured["initial_saved_import"],
                    "initial_saved_source_receipt": source_receipt(snapshot)}
        order = session.get(Order, order_id)
        workflow = session.get(OrderWorkflowState, order_id)
        if order is None or workflow is None or not isinstance(workflow.revision, int):
            return None
        if not _normalize_sheet_week_value(order.week_code):
            return None
        evidence_run_id = str(workflow.evidence_run_id or "").strip()
        evidence = session.get(OrderOcrEvidenceRun, evidence_run_id) if evidence_run_id else None
        if evidence is None or evidence.order_id != order_id:
            return None
        rejection = ocr_evidence_service.evidence_run_selectability_error(evidence)
        if rejection == "evidence_unusable":
            return None
        if rejection is not None:
            raise ocr_evidence_service.SelectedEvidenceRejected(rejection)
        if evidence.template_version_id != workflow.template_version_id:
            return None
        draft_id = str(workflow.draft_id or "").strip() or None
        draft_base_evidence_run_id = None
        draft = None
        if draft_id:
            draft = session.get(OrderSheetDraft, draft_id)
            if draft is None or draft.order_id != order_id:
                return None
            draft_base_evidence_run_id = str(draft.base_evidence_run_id or "").strip() or None
            if draft_base_evidence_run_id != evidence_run_id:
                return None
            if draft.template_version_id != evidence.template_version_id:
                return None
            draft_payload = draft.draft_sheet_json
            if not isinstance(draft_payload, dict) or any(
                draft_payload.get(key) and draft_payload[key] != evidence_run_id
                for key in ("base_evidence_run_id", "evidence_run_id")
            ):
                return None
        cache = session.get(OrderOcrCache, order_id)
        pdf_receipt = capture_selected_pdf_receipt(session, order)
        input_versions = synchronous_input_versions(order, evidence, draft, cache)
        input_versions["selected_pdf_receipt"] = pdf_receipt
        return {
            "order_id": order_id,
            "order_lines_updated_at": order.lines_updated_at,
            "workflow_revision": workflow.revision,
            "workflow_meta": deepcopy(workflow.secondary_actions_json or {}),
            "evidence_run_id": evidence_run_id,
            "draft_id": draft_id,
            "draft_base_evidence_run_id": draft_base_evidence_run_id,
            "cache_exists": cache is not None,
            "cache_updated_at": cache.updated_at if cache is not None else None,
            "input_versions": input_versions,
            "evidence": deepcopy(ocr_evidence_service._serialize_evidence_run(evidence, include_payload=True)),
            "draft": deepcopy(draft_sheet_service._serialize_draft(draft)) if draft is not None else None,
            "selected_pdf_receipt": pdf_receipt,
            "configured_input": _capture_selected_order_config(session, order),
            "physical_menu_entries": _json_snapshot(_build_position_menu_entries_safe(order.week_code, order.facility_code, session=session)),
        }


def _synchronous_cache_write_fence(
    session: Any,
    order_id: str,
    write_input: dict[str, Any] | None,
    *, source_failure: str | None = None,
) -> bool:
    if not isinstance(write_input, dict) or write_input.get("order_id") != order_id:
        return False
    if write_input.get("initial_saved_import") is not None:
        from src.services.workflow_attempt_guard_service import lock_order_execution_input, lock_current_execution_write
        from src.services.initial_saved_import_service import materialization_input_matches
        try:
            if not materialization_input_matches(session, order_id, write_input):
                return False
            if write_input.get("physical_menu_entries") and not snapshots_equal(
                    write_input["physical_menu_entries"], _json_snapshot(_build_position_menu_entries_safe(
                        session.get(Order, order_id).week_code, session.get(Order, order_id).facility_code, session=session))):
                return False
            if "output_ocr_menu_defaults" in write_input:
                names = list(dict.fromkeys(str(entry.get("menu_name") or "").strip() for entry in write_input["output_ocr_menu_entries"]))
                if not snapshots_equal(write_input["output_ocr_menu_defaults"], menu_service.resolve_menu_defaults_in_session(
                        session, names, session.get(Order, order_id).facility_code)[0] if names else {}):
                    return False
            return (lock_order_execution_input(session, order_id) is not None
                    and lock_current_execution_write(session, order_id))
        except (ValueError, KeyError):
            return False
    order = session.get(Order, order_id)
    if order is None or not config_service.captured_processing_config_matches(order.facility_code, write_input.get("configured_input")):
        return False
    if not snapshots_equal(write_input.get("physical_menu_entries"), _build_position_menu_entries_safe(order.week_code, order.facility_code, session=session)):
        return False
    if "output_ocr_menu_defaults" in write_input:
        entries = write_input.get("output_ocr_menu_entries")
        if not isinstance(entries, list):
            return False
        names = list(dict.fromkeys(str(entry.get("menu_name") or "").strip() for entry in entries))
        if not snapshots_equal(write_input["output_ocr_menu_defaults"], menu_service.resolve_menu_defaults_in_session(session, names, order.facility_code)[0] if names else {}):
            return False
    return lock_current_synchronous_cache_write(
        session,
        source_failure=source_failure,
        order_id=order_id,
        expected_order_lines_updated_at=write_input.get("order_lines_updated_at"),
        expected_workflow_revision=write_input.get("workflow_revision"),
        expected_evidence_run_id=write_input.get("evidence_run_id"),
        expected_draft_id=write_input.get("draft_id"),
        expected_draft_base_evidence_run_id=write_input.get("draft_base_evidence_run_id"),
        expected_cache_exists=write_input.get("cache_exists") is True,
        expected_cache_updated_at=write_input.get("cache_updated_at"),
        expected_input_versions=write_input.get("input_versions"),
    )


def _synchronous_draft_input_matches(write_input: dict[str, Any] | None, draft: Any) -> bool:
    if not isinstance(write_input, dict):
        return False
    captured_draft = write_input.get("draft")
    return isinstance(draft, dict) and isinstance(captured_draft, dict) and draft == captured_draft


@contextmanager
def workflow_ocr_write_context(workflow_attempt_id: str | None, expected_workflow_revision: int | None, job_id: str | None = None, order_id: str | None = None):
    attempt_token = _workflow_ocr_attempt_id.set(workflow_attempt_id)
    revision_token = _workflow_ocr_revision.set(expected_workflow_revision)
    job_token = _workflow_ocr_job_id.set(job_id)
    order_token = _workflow_ocr_order_id.set(order_id)
    try:
        with workflow_execution_context(job_id, order_id, workflow_attempt_id, expected_workflow_revision):
            yield
    finally:
        _workflow_ocr_order_id.reset(order_token)
        _workflow_ocr_job_id.reset(job_token)
        _workflow_ocr_revision.reset(revision_token)
        _workflow_ocr_attempt_id.reset(attempt_token)


def _authored_geometry_page(configured_input):
    template = (configured_input.get("facility") or {}).get("fax_template") if isinstance(configured_input, dict) else None
    page = template.get("page") if isinstance(template, dict) else None
    if type(page) is not int or page <= 0:
        raise ValueError("geometry_template_page_required")
    return page


def geometry_source_digest(selected_pdf_receipt, configured_input, order_input_identity, *, physical_entries=None, session=None):
    if not isinstance(selected_pdf_receipt, dict) or not isinstance(configured_input, dict) or not isinstance(order_input_identity, dict):
        raise ValueError("geometry_source_proof_required")
    layout = (configured_input.get("facility") or {}).get("fax_template")
    if not isinstance(layout, dict) or not layout or not selected_pdf_receipt.get("sha256"):
        raise ValueError("geometry_source_proof_required")
    page = _authored_geometry_page(configured_input)
    facility = order_input_identity.get("facility_code")
    week = order_input_identity.get("week_code")
    if not facility or not week:
        raise ValueError("geometry_source_identity_missing")
    if physical_entries is not None:
        entries = deepcopy(physical_entries)
    elif session is not None:
        entries = _build_position_menu_entries_safe(week, facility, session=session)
    else:
        entries = _build_position_menu_entries_safe(week, facility)
    if not entries:
        raise ValueError("geometry_physical_menu_missing")
    physical_keys = hakodate_physical_menu_row_service.physical_row_keys_from_entries(entries)
    physical_rows = ["__".join(key) for key in physical_keys]
    inputs = {"selected_pdf_receipt": selected_pdf_receipt, "configured_input": configured_input, "order_input_identity": order_input_identity, "page": page, "layout": layout, "physical_menu_entries": entries, "physical_menu_row_ids": physical_rows}
    return hashlib.sha256(canonical_snapshot_json(inputs).encode()).hexdigest()


def _validate_geometry_source(source, selected_pdf_receipt, configured_input, order_input_identity, *, session=None):
    if not isinstance(source, dict) or not source.get("geometry_source_digest") or not isinstance(source.get("physical_menu_entries"), list):
        raise ValueError("geometry_source_proof_required")
    if source["geometry_source_digest"] != geometry_source_digest(selected_pdf_receipt, configured_input, order_input_identity, physical_entries=source["physical_menu_entries"]):
        raise ValueError("geometry_source_input_changed")
    session_kwargs = {"session": session} if session is not None else {}
    if source["geometry_source_digest"] != geometry_source_digest(selected_pdf_receipt, configured_input, order_input_identity, **session_kwargs):
        raise ValueError("geometry_source_input_changed")


def _normalize_operator_quad_override(
    value: object,
    *,
    render_width: int | None = None,
    selected_pdf_receipt: dict[str, Any] | None = None,
    configured_input: dict[str, Any] | None = None,
    order_input_identity: dict[str, Any] | None = None,
    session: Any = None,
) -> tuple[list[list[float]] | None, str | None]:
    if not isinstance(value, dict):
        return None, None
    source = value.get("source_receipt")
    configured_digest = hashlib.sha256(canonical_snapshot_json(configured_input).encode("utf-8")).hexdigest()
    if not isinstance(source, dict) or selected_pdf_receipt is None or not snapshots_equal(source.get("selected_pdf_receipt"), selected_pdf_receipt) or configured_input is None or source.get("configured_input_digest") != configured_digest:
        raise ValueError("quad_source_input_changed")
    if order_input_identity is None or not snapshots_equal(source.get("order_input_identity"), order_input_identity):
        raise ValueError("quad_source_input_changed")
    session_kwargs = {"session": session} if session is not None else {}
    _validate_geometry_source(source, selected_pdf_receipt, configured_input, order_input_identity, **session_kwargs)
    coordinate_space = value.get("coordinate_space")
    if render_width is not None and isinstance(coordinate_space, dict):
        mode = str(coordinate_space.get("mode") or "").strip()
        width = coordinate_space.get("width")
        try:
            width_value = int(width)
        except (TypeError, ValueError):
            return None, None
        if mode != "render_width" or width_value != int(render_width):
            return None, None
    quad = value.get("quad_px")
    if not isinstance(quad, list) or len(quad) != 4:
        return None, None
    normalized: list[list[float]] = []
    for point in quad:
        if not isinstance(point, list | tuple) or len(point) != 2:
            return None, None
        try:
            x = float(point[0])
            y = float(point[1])
        except (TypeError, ValueError):
            return None, None
        if x < 0 or y < 0:
            return None, None
        if render_width is not None and x > float(render_width) + 1.0:
            return None, None
        normalized.append([round(x, 2), round(y, 2)])
    source = str(value.get("quad_source") or "operator_manual").strip() or "operator_manual"
    if not any(token in source.lower() for token in ("operator", "manual", "user_adjusted", "quad_override")):
        source = f"operator_{source}"
    return normalized, source


def _validate_axis_source(value, selected_pdf_receipt, configured_input, order_input_identity, *, session=None):
    source = value.get("source_receipt")
    digest = hashlib.sha256(canonical_snapshot_json(configured_input).encode()).hexdigest()
    if not isinstance(source, dict) or selected_pdf_receipt is None or configured_input is None or not snapshots_equal(source.get("selected_pdf_receipt"), selected_pdf_receipt) or source.get("configured_input_digest") != digest or not snapshots_equal(source.get("order_input_identity"), order_input_identity):
        raise ValueError("axis_source_input_changed")
    session_kwargs = {"session": session} if session is not None else {}
    _validate_geometry_source(source, selected_pdf_receipt, configured_input, order_input_identity, **session_kwargs)


def _normalize_operator_header_axis_override(value: object, *, selected_pdf_receipt=None, configured_input=None, order_input_identity=None, session=None) -> dict[str, Any] | None:
    if not isinstance(value, dict):
        return None
    session_kwargs = {"session": session} if session is not None else {}
    _validate_axis_source(value, selected_pdf_receipt, configured_input, order_input_identity, **session_kwargs)
    return deepcopy(value)


def _normalize_operator_row_axis_override(value: object, *, selected_pdf_receipt=None, configured_input=None, order_input_identity=None, session=None) -> dict[str, Any] | None:
    if not isinstance(value, dict):
        return None
    session_kwargs = {"session": session} if session is not None else {}
    _validate_axis_source(value, selected_pdf_receipt, configured_input, order_input_identity, **session_kwargs)
    # Validate geometry in the shared pipeline; never silently replace saved input
    # with automatic estimation, including older edits lacking day boundaries.
    return deepcopy(value)


def _parse_sheet_week_value(value: object) -> tuple[str | None, date | None, date | None]:
    return sheet_week_service.parse_sheet_week_value(value)


def _normalize_sheet_week_value(value: object) -> str | None:
    return sheet_week_service.normalize_sheet_week_value(value)


def _coerce_auto_week_value_to_calendar(value: object) -> str | None:
    return sheet_week_service.coerce_to_calendar_week_value(value)


def _preserve_explicit_auto_week_for_order(order: Order | dict[str, Any] | None) -> bool:
    if isinstance(order, dict):
        message_id = order.get("message_id")
    else:
        message_id = getattr(order, "message_id", None)
    return _is_split_page_ingest_message(str(message_id or "").strip() or None)


def _normalize_auto_week_value_for_order(order: Order | dict[str, Any] | None, value: object) -> str | None:
    normalized = _normalize_sheet_week_value(value)
    if not normalized:
        return None
    if _preserve_explicit_auto_week_for_order(order):
        return normalized
    return _coerce_auto_week_value_to_calendar(normalized) or normalized


def _normalize_sheet_week_candidate(value: object) -> str | None:
    normalized_week = _normalize_sheet_week_value(value)
    if normalized_week and "@" in normalized_week:
        return normalized_week
    return _to_sheet_month_id(value) or str(value or "").strip() or None


def _resolve_system_managed_order_week_code(
    order: Order | dict[str, Any] | None,
    proposed_week_code: object,
) -> str | None:
    if isinstance(order, dict):
        current_week_code = order.get("week_code")
    else:
        current_week_code = getattr(order, "week_code", None)
    current_week_value = _normalize_sheet_week_candidate(current_week_code)
    proposed_week_value = _normalize_sheet_week_candidate(proposed_week_code)
    current_explicit_week = _normalize_sheet_week_value(current_week_value)
    if current_explicit_week and "@" in current_explicit_week:
        return current_explicit_week
    return proposed_week_value or current_week_value


def _apply_system_managed_order_week_code(
    order: Order,
    proposed_week_code: object,
) -> str | None:
    resolved_week_code = _resolve_system_managed_order_week_code(order, proposed_week_code)
    if resolved_week_code and str(order.week_code or "").strip() != resolved_week_code:
        order.week_code = resolved_week_code
    return resolved_week_code


def _format_sheet_week_label(value: object) -> str:
    return sheet_week_service.format_sheet_week_label(value)


def _week_sheet_name_from_week_value(value: object) -> str | None:
    _month_id, start_date, end_date = _parse_sheet_week_value(value)
    if not isinstance(start_date, date) or not isinstance(end_date, date):
        return None
    return f"{start_date.month}月{start_date.day}日～{end_date.month}月{end_date.day}日"


def _clip_entries_to_sheet_week_range(entries: list[dict[str, Any]], week_value: object) -> list[dict[str, Any]]:
    month_id, start_date, end_date = _parse_sheet_week_value(week_value)
    if not month_id or not isinstance(start_date, date) or not isinstance(end_date, date):
        return entries
    clipped: list[dict[str, Any]] = []
    for entry in entries:
        menu_date = _normalize_entry_date(entry.get("menu_date"))
        if not isinstance(menu_date, date):
            continue
        if start_date <= menu_date <= end_date:
            clipped.append(entry)
    return clipped


def _prefer_week_scoped_ocr_entries(
    entries: list[dict[str, Any]] | None,
    week_value: object,
) -> list[dict[str, Any]]:
    normalized_entries = [dict(item) for item in (entries or []) if isinstance(item, dict)]
    if not normalized_entries:
        return []
    clipped_entries = _clip_entries_to_sheet_week_range(normalized_entries, week_value)
    if clipped_entries:
        return clipped_entries
    return normalized_entries


def _update_ocr_execution_job(job_id: str, **updates: Any) -> dict[str, Any] | None:
    attempt = _workflow_ocr_attempt_id.get()
    if attempt is not None:
        if updates.get("status") in {"done", "failed", "error", "completed", "success"}:
            updates.pop("status", None)
            updates.pop("error_message", None)
        if updates.get("metrics") is None:
            updates.pop("metrics", None)
        updated, accepted = update_job_for_workflow_attempt(
            job_id, attempt, order_id=_workflow_ocr_order_id.get(),
            expected_workflow_revision=_workflow_ocr_revision.get(), **updates,
        )
        return updated if accepted else None
    return update_job(job_id, actual_order_id=(current_nonworkflow_execution() or {}).get("order_id"), **updates)


def _run_roi_ocr_pipeline(
    *,
    job_id: str,
    pdf_bytes: bytes,
    facility_id: str | None,
    input_reference: str | None,
    preferred_template_id: str | None,
    preferred_template_ids: list[str] | None = None,
) -> str | None:
    try:
        logger.info(
            "ROI OCR pipeline start job_id={} facility_id={} template_id={} template_ids={} input_reference={}",
            job_id,
            facility_id,
            preferred_template_id,
            preferred_template_ids,
            input_reference,
        )
        output = run_ocr_pipeline(
            pdf_bytes=pdf_bytes,
            job_id=job_id,
            facility_id=facility_id,
            input_reference=input_reference,
            preferred_template_id=preferred_template_id,
            preferred_template_ids=preferred_template_ids,
            force_upload=True,
            wait_for_output=False,
        )
        output_ref = output.get("output_reference")
        logger.info(
            "ROI OCR pipeline queued job_id={} output_ref={}",
            job_id,
            output_ref,
        )
        _update_ocr_execution_job(
            job_id,
            status="running",
            template_id=output.get("template_id"),
            output_reference=output_ref,
            error_message=None,
            metrics=None,
        )
        event_type = "ocr_job_started"
        record_event(
            event_type,
            actor="system",
            target=job_id,
            fac=facility_id,
            metadata={"template_id": output.get("template_id"), "output_ref": output_ref},
        )
        return output_ref
    except Exception as exc:  # noqa: BLE001
        logger.exception(f"ROI OCR pipeline failed (job_id={job_id}): {exc}")
        _update_ocr_execution_job(job_id, status="failed", error_message=str(exc))
        record_event(
            "ocr_job_failed",
            actor="system",
            target=job_id,
            fac=facility_id,
            metadata={"error": str(exc)},
        )
        return None


def _resolve_preferred_template_ids(facility_config: dict[str, Any] | None) -> tuple[str | None, list[str]]:
    if not isinstance(facility_config, dict):
        return None, []
    authored = config_service._validate_authored_facility_config(facility_config, None)
    template_id = authored["fax_template"].get("template_id")
    return (template_id, [template_id]) if template_id else (None, [])


def _load_facility_config_with_master_fallback(
    facility_id: str | None,
    *,
    log_context: str,
) -> dict[str, Any] | None:
    normalized_facility_id = str(facility_id or "").strip()
    if not normalized_facility_id:
        return None
    facility_config = None
    try:
        facility_config = config_service.get_facility_config(normalized_facility_id)
    except Exception as exc:  # noqa: BLE001
        logger.warning(log_context, facility_id=normalized_facility_id, error=str(exc))
    if isinstance(facility_config, dict):
        return facility_config
    return None


def _materialize_facility_template_for_template_id(
    facility_config: dict[str, Any], template_id: str | None,
) -> dict[str, Any] | None:
    if not isinstance(facility_config, dict):
        return None
    try:
        authored = config_service._validate_authored_facility_config(facility_config, template_id)
    except ValueError:
        return None
    return deepcopy(authored["fax_template"])


def _read_order_authored_facility_config(order_id: str, facility_id: str | None = None) -> dict[str, Any]:
    from src.services import canonical_facility_lineage as lineage
    from src.services.canonical_facility_store import CanonicalStoreError
    from src.services.workflow_attempt_guard_service import current_workflow_execution

    try:
        configured_execution = current_nonworkflow_execution() is not None or current_workflow_execution() is not None
        if configured_execution and facility_id is not None:
            return config_service.get_authored_facility_config(facility_id)
        with session_scope() as session, session.no_autoflush:
            order = session.get(Order, order_id)
            if order is None:
                raise ValueError("order_not_found")
            owner = str(order.facility_code or "").strip()
            if not owner:
                raise ValueError("facility_missing")
            if facility_id is not None and owner != facility_id:
                raise ValueError("configured_execution_facility_mismatch")
            if configured_execution:
                return config_service.get_authored_facility_config(owner)
            selected_id = str(order.template_version_id or "").strip()
            projection = lineage.read_projection(session, selected_id) if selected_id else None
            if projection is None:
                raise ValueError("original_template_projection_missing")
            receipt = lineage.verify_projection(projection)
            if receipt["facility_id"] != owner:
                raise ValueError("original_template_configured_source_mismatch")
            return config_service.validate_selected_authored_facility_config(owner, receipt["authored_version"])
    except CanonicalStoreError as exc:
        raise ValueError(str(exc)) from exc


def _resolve_effective_sheet_template(
    *,
    order_id: str | None,
    facility_id: str | None,
    facility_config: dict[str, Any] | None = None,
    ocr_payload: dict[str, Any] | None = None,
    draft_template_id: str | None = None,
    allow_workflow_resolution: bool = True,
    log_context: str,
) -> tuple[dict[str, Any] | None, dict[str, Any] | None, str | None, str | None]:
    normalized_facility_id = str(facility_id or "").strip() or None
    if not normalized_facility_id:
        return None, None, None, "facility_missing"
    resolved_facility_config = facility_config
    try:
        if resolved_facility_config is None:
            resolved_facility_config = (
                _read_order_authored_facility_config(order_id, normalized_facility_id)
                if order_id else config_service.get_authored_facility_config(normalized_facility_id)
            )
        if not isinstance(resolved_facility_config, dict):
            return None, None, None, "facility_not_found"
        if resolved_facility_config.get("facility_id") != normalized_facility_id:
            return resolved_facility_config, None, None, "configured_execution_facility_mismatch"
        authored = config_service._validate_authored_facility_config(resolved_facility_config, None)
    except ValueError as exc:
        return resolved_facility_config, None, None, str(exc)
    template = deepcopy(authored["fax_template"])
    return resolved_facility_config, template, template.get("template_id"), None


