def delete_orders_by_message_prefix(prefix: str) -> int:
    if not prefix:
        return 0
    removed = 0
    with session_scope() as session:
        orders = (
            session.execute(select(Order).where(Order.message_id.like(f"{prefix}%")))
            .scalars()
            .all()
        )
        for order in orders:
            session.execute(delete(LabelRow).where(LabelRow.order_id == order.id))
            session.execute(delete(Bag).where(Bag.order_id == order.id))
            session.execute(delete(DeliveryNote).where(DeliveryNote.order_id == order.id))
            session.execute(delete(OrderCriticalDecision).where(OrderCriticalDecision.order_id == order.id))
            session.execute(delete(OrderCurrentState).where(OrderCurrentState.order_id == order.id))
            session.execute(delete(OrderWorkflowState).where(OrderWorkflowState.order_id == order.id))
            session.execute(delete(OrderConfirmedSnapshot).where(OrderConfirmedSnapshot.order_id == order.id))
            session.execute(delete(OrderSheetDraft).where(OrderSheetDraft.order_id == order.id))
            session.execute(delete(OrderSheetPatchCandidate).where(OrderSheetPatchCandidate.order_id == order.id))
            session.execute(delete(OrderOcrEvidenceRun).where(OrderOcrEvidenceRun.order_id == order.id))
            session.execute(delete(OrderOcrRevision).where(OrderOcrRevision.order_id == order.id))
            session.execute(delete(OrderOcrCache).where(OrderOcrCache.order_id == order.id))
            session.execute(delete(OrderVersion).where(OrderVersion.order_id == order.id))
            session.execute(delete(OrderDocument).where(OrderDocument.order_id == order.id))
            session.execute(delete(OrderMenuSnapshot).where(OrderMenuSnapshot.order_id == order.id))
            session.execute(delete(OrderLine).where(OrderLine.order_id == order.id))
            session.execute(delete(Order).where(Order.id == order.id))
            removed += 1
        if removed:
            session.execute(delete(IngestJob).where(IngestJob.id.like(f"{prefix}%")))
            session.execute(delete(UploadedPdfAttempt).where(UploadedPdfAttempt.uploaded_pdf_id.in_(
                select(UploadedPdf.id).where(UploadedPdf.message_id.like(f"{prefix}%"))
            )))
            session.execute(delete(UploadedPdf).where(UploadedPdf.message_id.like(f"{prefix}%")))
    if removed:
        _invalidate_orders_cache()
    return removed


def find_order_by_message_id(message_id: str) -> dict | None:
    token = str(message_id or "").strip()
    if not token:
        return None
    with session_scope() as session:
        order = (
            session.execute(
                select(Order)
                .where(Order.message_id == token)
                .order_by(Order.received_at.desc(), Order.id.desc())
            )
            .scalars()
            .first()
        )
        if not order:
            return None
        return {
            "id": order.id,
            "message_id": order.message_id,
            "facility_id": order.facility_code,
            "week_id": order.week_code,
            "status": order.status,
            "received_at": order.received_at.isoformat() if order.received_at else None,
        }


def _make_order_id() -> str:
    return f"ORD{uuid4().hex[:8]}"


def _make_document_id() -> str:
    return f"DOC{uuid4().hex[:8]}"


def _make_order_version_id() -> str:
    return f"ORV{uuid4().hex[:8]}"


def _make_line_id() -> str:
    return f"OLN{uuid4().hex[:10]}"


def _existing_line_ids(candidate_ids: set[str], *, exclude_order_id: str | None = None) -> set[str]:
    normalized = {str(item or "").strip() for item in candidate_ids if str(item or "").strip()}
    if not normalized:
        return set()
    with session_scope() as session:
        query = select(OrderLine.id).where(OrderLine.id.in_(normalized))
        if exclude_order_id:
            query = query.where(OrderLine.order_id != exclude_order_id)
        rows = session.execute(query).scalars().all()
    return {str(item or "").strip() for item in rows if str(item or "").strip()}


def _ensure_unique_line_ids(
    lines: list[dict] | None,
    *,
    exclude_order_id: str | None = None,
) -> list[dict]:
    if not isinstance(lines, list):
        return []
    initial_candidates = {
        str(raw.get("id") or "").strip()
        for raw in lines
        if isinstance(raw, dict) and str(raw.get("id") or "").strip()
    }
    existing_ids = _existing_line_ids(initial_candidates, exclude_order_id=exclude_order_id)
    normalized: list[dict] = []
    used_ids: set[str] = set()
    for raw in lines:
        if not isinstance(raw, dict):
            continue
        line = dict(raw)
        candidate = str(line.get("id") or "").strip()
        if not candidate or candidate in used_ids or candidate in existing_ids:
            candidate = _make_line_id()
            while candidate in used_ids or candidate in existing_ids:
                candidate = _make_line_id()
            line["id"] = candidate
        else:
            line["id"] = candidate
        used_ids.add(candidate)
        normalized.append(line)
    return normalized


def _line_digest(rows: list[dict]) -> str:
    normalized = []
    for row in rows:
        normalized.append(
            {
                "date": str(row.get("date") or ""),
                "daypart": row.get("daypart") or "",
                "menu_name": row.get("menu_name") or "",
                "diet_type": row.get("diet_type") or "",
                "area_id": row.get("area_id") or "",
                "bag_type": row.get("bag_type") or "",
                "quantity_original": row.get("quantity_original"),
                "quantity_corrected": row.get("quantity_corrected"),
                "change_note": row.get("change_note") or "",
            }
        )
    normalized.sort(
        key=lambda item: (
            item["date"],
            item["menu_name"],
            item["diet_type"],
            item["area_id"],
            item["bag_type"],
            str(item["quantity_original"]),
            str(item["quantity_corrected"]),
            item["change_note"],
        )
    )
    payload = json.dumps(normalized, ensure_ascii=True, sort_keys=True)
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


_MENU_TRANSLATION = str.maketrans(
    "０１２３４５６７８９ＡＢＣＤＥＦＧＨＩＪＫＬＭＮＯＰＱＲＳＴＵＶＷＸＹＺａｂｃｄｅｆｇｈｉｊｋｌｍｎｏｐｑｒｓｔｕｖｗｘｙｚ",
    "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz",
)


def _normalize_menu_text(text: str) -> str:
    normalized = text.translate(_MENU_TRANSLATION)
    normalized = unicodedata.normalize("NFKC", normalized)
    normalized = re.sub(r"\s+", "", normalized)
    normalized = normalized.replace("・", "").replace("／", "/")
    return normalized.strip().lower()


def _match_menu_name(
    raw: str, candidates: list[str], normalized_candidates: dict[str, str], min_ratio: float
) -> tuple[str, float]:
    if not raw or not candidates:
        return raw, 0.0
    raw_norm = _normalize_menu_text(raw)
    if not raw_norm:
        return raw, 0.0
    best_name = raw
    best_ratio = 0.0
    for candidate in candidates:
        candidate_norm = normalized_candidates.get(candidate, "")
        if not candidate_norm:
            continue
        if raw_norm == candidate_norm:
            return candidate, 1.0
        ratio = SequenceMatcher(None, raw_norm, candidate_norm).ratio()
        if ratio > best_ratio:
            best_ratio = ratio
            best_name = candidate
    if best_ratio >= min_ratio:
        return best_name, best_ratio
    return raw, best_ratio


def _apply_menu_matching(
    lines: list[dict],
    week_id: Optional[str],
    facility_id: Optional[str],
    min_ratio: float,
    *, session: Any = None,
) -> list[dict]:
    session_kwargs = {"session": session} if session is not None else {}
    items = _collect_menu_items_for_week(week_id, facility_id, allow_unresolved=True, **session_kwargs)
    if not items:
        return lines
    candidates = [item.get("name") for item in items if item.get("name")]
    if not candidates:
        return lines
    normalized_candidates = {name: _normalize_menu_text(name) for name in candidates}
    for line in lines:
        raw = line.get("menu_name")
        if not raw:
            continue
        matched, ratio = _match_menu_name(raw, candidates, normalized_candidates, min_ratio)
        if matched != raw:
            line["menu_name"] = matched
            line["menu_match_ratio"] = ratio
    return lines


def _normalize_daypart_key(value: object) -> str:
    if value is None:
        return ""
    text = str(value).strip()
    if not text:
        return ""
    normalized = _normalize_sheet_text(text)
    if not normalized:
        return ""
    lowered = normalized.lower()
    if "breakfast" in lowered or lowered == "morning":
        return "朝"
    if "lunch" in lowered or lowered == "noon":
        return "昼"
    if "dinner" in lowered or "supper" in lowered or lowered in {"evening", "night"}:
        return "夕"
    if "朝" in normalized:
        return "朝"
    if "昼" in normalized:
        return "昼"
    if "夕" in normalized or "夜" in normalized:
        return "夕"
    return normalized


def _canonical_daypart_key(value: object) -> str:
    if value is None:
        return ""
    normalized = _normalize_sheet_text(value)
    if not normalized:
        return ""
    lowered = normalized.lower()
    if lowered in {"朝", "朝食", "breakfast", "morning"}:
        return "朝"
    if lowered in {"昼", "昼食", "lunch", "noon"}:
        return "昼"
    if lowered in {"夕", "夕食", "夜", "夜食", "dinner", "supper", "evening", "night"}:
        return "夕"
    return ""


_DAYPART_SORT_ORDER = {"朝": 0, "昼": 1, "夕": 2}


def _daypart_sort_components(value: object) -> tuple[int, str]:
    normalized = _normalize_daypart_key(value)
    if not normalized:
        return 99, ""
    return _DAYPART_SORT_ORDER.get(normalized, 50), normalized


def _normalize_entry_date(value: object) -> date | None:
    if isinstance(value, date):
        try:
            if pd.isna(value):
                return None
        except Exception:
            pass
        return value
    if not value:
        return None
    try:
        parsed = date.fromisoformat(str(value))
        try:
            if pd.isna(parsed):
                return None
        except Exception:
            pass
        return parsed
    except Exception:
        try:
            parsed = pd.to_datetime(value)
            if pd.isna(parsed):
                return None
            parsed_date = parsed.date()
            if pd.isna(parsed_date):
                return None
            return parsed_date
        except Exception:
            return None


def _load_menu_payloads_for_week(
    week_id: str | None,
    facility_id: str | None = None,
    *, allow_unresolved: bool = False, session: Any = None,
) -> list[tuple[str, dict[str, Any]]]:
    payloads: list[tuple[str, dict[str, Any]]] = []
    seen_months: set[str] = set()
    for month_id in _sheet_week_month_ids(week_id):
        if not month_id or month_id in seen_months:
            continue
        seen_months.add(month_id)
        session_kwargs = {"session": session} if session is not None else {}
        payload = (
            menu_service.get_menu_for_facility(month_id, facility_id, allow_unresolved=allow_unresolved, **session_kwargs)
            if facility_id
            else menu_service.get_menu(month_id, allow_unresolved=allow_unresolved, **session_kwargs)
        )
        if isinstance(payload, dict):
            payloads.append((month_id, payload))
    return payloads


def _collect_menu_items_for_week(
    week_id: str | None,
    facility_id: str | None = None,
    *, allow_unresolved: bool = False, session: Any = None,
) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str, str, str]] = set()
    session_kwargs = {"session": session} if session is not None else {}
    for _month_id, payload in _load_menu_payloads_for_week(week_id, facility_id, allow_unresolved=allow_unresolved, **session_kwargs):
        raw_items = payload.get("items")
        if not isinstance(raw_items, list):
            continue
        for item in raw_items:
            if not isinstance(item, dict):
                continue
            name = str(item.get("name") or "").strip()
            key = (
                name,
                str(item.get("daypart") or "").strip(),
                str(item.get("category") or "").strip(),
                str(item.get("diet_type") or "").strip(),
                str(item.get("facility_override") or "").strip(),
            )
            if not name or key in seen:
                continue
            seen.add(key)
            items.append(dict(item))
    return items


def _collect_menu_entries_for_week(
    week_id: str | None,
    facility_id: str | None = None,
    *, session: Any = None,
) -> list[dict[str, Any]]:
    entries: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str, int, str]] = set()
    for month_id in _sheet_week_month_ids(week_id):
        raw_entries = menu_service.get_menu_entries_for_facility(month_id, facility_id, session=session) if session is not None else menu_service.get_menu_entries_for_facility(month_id, facility_id)
        for entry in raw_entries:
            if not isinstance(entry, dict):
                continue
            menu_date = str(entry.get("menu_date") or "").strip()
            daypart = str(entry.get("daypart") or "").strip()
            menu_name = str(entry.get("name") or "").strip()
            slot_index_raw = entry.get("slot_index")
            try:
                slot_index = int(slot_index_raw) if slot_index_raw is not None else -1
            except Exception:
                slot_index = -1
            diet_type = str(entry.get("diet_type") or "").strip()
            dedupe_key = (menu_date, daypart, _normalize_menu_text(menu_name), slot_index, diet_type)
            if not menu_name or dedupe_key in seen:
                continue
            seen.add(dedupe_key)
            entries.append(dict(entry))
    month_id, start_date, end_date = _parse_sheet_week_value(week_id)
    if not month_id or not isinstance(start_date, date) or not isinstance(end_date, date):
        return entries
    filtered: list[dict[str, Any]] = []
    for entry in entries:
        menu_date = _normalize_entry_date(entry.get("menu_date"))
        if isinstance(menu_date, date) and start_date <= menu_date <= end_date:
            filtered.append(entry)
    return filtered


def _build_position_menu_entries(week_id: str, facility_id: str | None = None, *, session: Any = None) -> list[dict]:
    month_ids = _sheet_week_month_ids(week_id)
    if not month_ids:
        return []
    variants_by_physical_slot: dict[tuple[str, str, int], dict[str, dict]] = {}
    order_index = 0
    for month_id in month_ids:
        raw_entries = menu_service.get_menu_entries_for_facility(month_id, facility_id, session=session) if session is not None else menu_service.get_menu_entries_for_facility(month_id, facility_id)
        if not isinstance(raw_entries, list):
            continue
        for raw in raw_entries:
            if not isinstance(raw, dict):
                continue
            menu_name = str(raw.get("name") or "").strip()
            if not menu_name:
                raise ValueError("physical_menu_variant_name_required")
            menu_date = _normalize_entry_date(raw.get("menu_date"))
            daypart_key = _normalize_daypart_key(raw.get("daypart"))
            slot_index_raw = raw.get("slot_index")
            if type(slot_index_raw) is not int or slot_index_raw < 0:
                raise ValueError("physical_menu_slot_identity_required")
            slot_index = slot_index_raw
            physical_key = (
                menu_date.isoformat() if isinstance(menu_date, date) else "",
                daypart_key,
                slot_index,
            )
            hakodate_physical_menu_row_service.physical_row_key_from_entry({"menu_date": menu_date, "daypart_key": daypart_key, "slot_index": slot_index})
            payload = {
                **deepcopy(raw),
                "menu_name": menu_name,
                "menu_date": menu_date,
                "daypart_key": daypart_key,
                "category": str(raw.get("category") or "").strip() or None,
                "slot_index": slot_index,
                "order": order_index,
            }
            diet = menu_service.normalize_diet_type(raw.get("diet_type"))
            if not isinstance(diet, str) or not diet:
                raise ValueError("physical_menu_diet_identity_required")
            payload["diet_type"] = diet
            variants = variants_by_physical_slot.setdefault(physical_key, {})
            if diet in variants:
                raise ValueError("physical_menu_row_duplicate")
            variants[diet] = payload
            order_index += 1
    entries: list[dict] = []
    for variants in variants_by_physical_slot.values():
        regular = variants.get("regular")
        if regular is None:
            continue
        # Logical diet variants never create a physical slot or replace its name.
        physical_entry = deepcopy(regular)
        if len(variants) > 1:
            physical_entry["diet_variants"] = deepcopy(variants)
        entries.append(physical_entry)
    entries.sort(
        key=lambda item: (
            item.get("menu_date") or date.min,
            _daypart_sort_components(item.get("daypart_key"))[0],
            _daypart_sort_components(item.get("daypart_key"))[1],
            int(item.get("slot_index") or 0),
            int(item.get("order") or 0),
        )
    )
    return _clip_entries_to_sheet_week_range(entries, week_id)


def _build_position_menu_entries_safe(week_id: str, facility_id: str | None = None, *, session: Any = None) -> list[dict]:
    if session is not None:
        return _build_position_menu_entries(week_id, facility_id, session=session)
    return _build_position_menu_entries(week_id, facility_id)


def _source_uses_weekly_menu_shell(source: str | None) -> bool:
    return str(source or "").strip() in {
        "weekly_menu",
        "weekly_menu+ocr_payload",
        "weekly_menu+payload_row",
        "weekly_menu_skeleton",
        "weekly_menu_blocked",
        "hakodate_weekly_menu_template",
        "forced_weekly_menu",
    }


def _resolve_sheet_payload_for_menu_entries(payload: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(payload, dict):
        return None
    edited = payload.get("_edited_ocr")
    if isinstance(edited, dict):
        latest = _select_edited_sheet_revision(payload)
        llm_review = latest.get("llm_review") if isinstance(latest, dict) else None
        output_payload = llm_review.get("output_payload") if isinstance(llm_review, dict) else None
        if isinstance(output_payload, dict):
            return output_payload
        raw_output = edited.get("raw_output") if latest is not None else None
        if isinstance(raw_output, dict):
            return raw_output
    raw_output = payload.get("raw_output")
    if isinstance(raw_output, dict):
        return raw_output
    return payload


def _extract_entry_date_from_sheet_cell(value: object, received_at: datetime, *, date_policy: dict | None = None, explicit_week: str | None = None) -> date | None:
    return parse_date_string(value.isoformat() if isinstance(value, date) else value,
        received_at, policy=date_policy, explicit_week=explicit_week)


def _build_position_menu_entries_from_ocr_payload(
    *,
    payload: dict[str, Any] | None,
    template: dict[str, Any],
    received_at: datetime,
    explicit_week: str | None = None,
) -> list[dict]:
    explicit_week = require_explicit_ingest_week(explicit_week)
    def _fallback_structured_entries() -> list[dict]:
        return _build_position_menu_entries_from_structured_tables(
            payload=source_payload,
            template=template,
            received_at=received_at,
            explicit_week=explicit_week,
        )

    source_payload = _resolve_sheet_payload_for_menu_entries(payload)
    if not isinstance(source_payload, dict):
        return []
    sheet_rows = _extract_sheet_rows_from_payload_uncanonicalized(source_payload, template)
    if not sheet_rows:
        return _fallback_structured_entries()
    fields = _row_fields_from_template(template)
    if not fields:
        return []
    header = _sheet_header_from_template(fields, template)
    helper_semantics = _resolve_helper_column_semantics(fields=fields, header=header)
    slot_label_idx = next(
        (idx for idx, semantic in helper_semantics.items() if semantic == "slot_label"),
        None,
    )
    row_classification = fax_extractor.classify_structured_projection_rows(
        rows=sheet_rows,
        fields=fields,
    )
    if not bool(row_classification.get("accepted")):
        return _fallback_structured_entries()
    row_kinds = [
        str(item or "").strip()
        for item in (row_classification.get("row_kinds") or [])
    ]

    date_idx = next(
        (idx for idx, field in enumerate(fields) if _normalize_sheet_text(field).lower().startswith("date")),
        None,
    )
    daypart_idx = next(
        (idx for idx, field in enumerate(fields) if _normalize_sheet_text(field).lower() in {"daypart", "meal", "time"}),
        None,
    )
    menu_idx = next(
        (
            idx
            for idx, field in enumerate(fields)
            if _normalize_sheet_text(field).lower() in {"menu", "menuname", "menu_name"}
        ),
        None,
    )
    if menu_idx is None:
        return []

    large_cell_mode = bool(template.get("large_cell_mode", False))
    fill_forward_roles = set(template.get("fill_forward_roles") or [])
    if large_cell_mode:
        fill_forward_roles.update({"date", "daypart"})
    fill_forward_roles.discard("menu_name")
    fill_missing_date_with_hint = bool(template.get("fill_missing_date_with_hint", False))
    if "fill_missing_date_with_first_seen" in template:
        fill_missing_date_with_first_seen = bool(template.get("fill_missing_date_with_first_seen"))
    else:
        fill_missing_date_with_first_seen = large_cell_mode

    date_candidates = _collect_sheet_dates_from_payload(source_payload, received_at, template, explicit_week=explicit_week)
    default_date = min(date_candidates) if date_candidates else None
    first_date_in_table: date | None = None
    carry_forward: dict[str, Any] = {role: None for role in fill_forward_roles}
    carry_forward_daypart_date: date | None = None
    raw_entries: list[dict[str, Any]] = []

    for row_idx, row in enumerate(sheet_rows):
        row_kind = row_kinds[row_idx] if row_idx < len(row_kinds) else "menu_row"
        row_values = list(row) if isinstance(row, list) else []
        raw_date = row_values[date_idx] if date_idx is not None and date_idx < len(row_values) else ""
        raw_daypart = (
            row_values[daypart_idx] if daypart_idx is not None and daypart_idx < len(row_values) else ""
        )
        raw_menu_name = row_values[menu_idx] if menu_idx < len(row_values) else ""
        raw_slot_label = (
            row_values[slot_label_idx]
            if isinstance(slot_label_idx, int) and slot_label_idx < len(row_values)
            else ""
        )
        menu_name = str(raw_menu_name or "").strip()
        menu_date = _extract_entry_date_from_sheet_cell(raw_date, received_at, explicit_week=explicit_week)
        raw_daypart_token = str(raw_daypart or "").strip()
        daypart = _canonical_daypart_key(raw_daypart_token) or None

        base = {
            "date": menu_date,
            "daypart": daypart or None,
            "menu_name": menu_name or None,
        }
        current_row_date = base.get("date") if isinstance(base.get("date"), date) else None
        if (
            "daypart" in fill_forward_roles
            and isinstance(current_row_date, date)
            and isinstance(carry_forward_daypart_date, date)
            and current_row_date != carry_forward_daypart_date
        ):
            carry_forward["daypart"] = None
        for role in fill_forward_roles:
            if role not in base:
                continue
            value = base.get(role)
            if role == "daypart" and raw_daypart_token:
                if value:
                    carry_forward[role] = value
                    carry_forward_daypart_date = current_row_date
                continue
            if value:
                carry_forward[role] = value
                if role == "daypart":
                    carry_forward_daypart_date = current_row_date
            else:
                base[role] = carry_forward.get(role)

        if isinstance(base.get("date"), date) and first_date_in_table is None:
            first_date_in_table = base.get("date")
        if base.get("date") is None and fill_missing_date_with_hint and default_date is not None:
            base["date"] = default_date
        if base.get("date") is None and first_date_in_table is not None and fill_missing_date_with_first_seen:
            base["date"] = first_date_in_table

        if row_kind != "menu_row":
            continue
        if not base.get("menu_name"):
            continue
        raw_entries.append(
            {
                "menu_name": str(base.get("menu_name") or "").strip(),
                "menu_date": base.get("date") if isinstance(base.get("date"), date) else None,
                "daypart_key": _canonical_daypart_key(base.get("daypart")),
                "raw_daypart_token": raw_daypart_token,
                "category": normalize_aux_semantic_display_value(raw_slot_label, "slot_label") or None,
                "slot_index": row_idx,
                "order": row_idx,
                "source_order": row_idx,
            }
        )

    if not raw_entries:
        return []

    entries = [dict(item) for item in raw_entries]

    structured_tables = fax_extractor._collect_structured_tables(source_payload)
    structured_daypart_blocks: dict[int, tuple[int, str]] = {}
    if structured_tables and daypart_idx is not None:
        header_rows_raw = template.get("header_rows", 0)
        try:
            template_header_rows = max(0, int(header_rows_raw))
        except Exception:
            template_header_rows = 0
        block_counter = 0
        for table_payload in structured_tables:
            if not isinstance(table_payload, dict):
                continue
            raw_rows = table_payload.get("rows")
            inferred_header_rows = 0
            if isinstance(raw_rows, list) and len(raw_rows) >= len(sheet_rows):
                inferred_header_rows = max(0, len(raw_rows) - len(sheet_rows))
            header_rows = max(template_header_rows, inferred_header_rows)
            raw_cells = table_payload.get("cells")
            if not isinstance(raw_cells, list) or not raw_cells:
                continue
            for raw_cell in raw_cells:
                if not isinstance(raw_cell, dict):
                    continue
                try:
                    col_index = int(raw_cell.get("col_index"))
                    row_index = int(raw_cell.get("row_index"))
                except Exception:
                    continue
                if col_index != daypart_idx or row_index < header_rows:
                    continue
                try:
                    row_span = max(1, int(raw_cell.get("row_span") or 1))
                except Exception:
                    row_span = 1
                raw_token = str(raw_cell.get("text") or "").strip()
                start = row_index - header_rows
                for offset in range(row_span):
                    structured_daypart_blocks[start + offset] = (block_counter, raw_token)
                block_counter += 1
            if structured_daypart_blocks:
                break

    by_date: dict[date | None, list[int]] = {}
    for idx, entry in enumerate(entries):
        by_date.setdefault(entry.get("menu_date"), []).append(idx)

    for indexes in by_date.values():
        if not indexes:
            continue
        if not structured_daypart_blocks:
            last_valid = ""
            for idx in indexes:
                daypart_key = _canonical_daypart_key(entries[idx].get("daypart_key"))
                if daypart_key:
                    entries[idx]["daypart_key"] = daypart_key
                    last_valid = daypart_key
                elif last_valid:
                    entries[idx]["daypart_key"] = last_valid
                else:
                    entries[idx]["daypart_key"] = ""

            next_valid = ""
            for idx in reversed(indexes):
                daypart_key = _canonical_daypart_key(entries[idx].get("daypart_key"))
                if daypart_key:
                    next_valid = daypart_key
                elif next_valid:
                    entries[idx]["daypart_key"] = next_valid
            if not all(bool(_canonical_daypart_key(entries[idx].get("daypart_key"))) for idx in indexes):
                chosen_sequence = _choose_canonical_daypart_sequence(
                    supported_by_block={
                        position: supported
                        for position, supported in (
                            (
                                position,
                                _canonical_daypart_key(entries[idx].get("daypart_key")),
                            )
                            for position, idx in enumerate(indexes)
                        )
                        if supported
                    },
                    block_count=len(indexes),
                )
                for position, idx in enumerate(indexes):
                    if _canonical_daypart_key(entries[idx].get("daypart_key")):
                        continue
                    if position < len(chosen_sequence):
                        entries[idx]["daypart_key"] = chosen_sequence[position]
            continue
        block_indexes: dict[int, int] = {}
        blocks: list[dict[str, Any]] = []
        current_block_key: object | None = None
        for idx in indexes:
            entry = entries[idx]
            source_order = int(entry.get("source_order") or 0)
            structured_block = structured_daypart_blocks.get(source_order)
            if structured_block is not None:
                block_key: object = ("structured", structured_block[0])
                raw_token = structured_block[1]
            else:
                raw_token = str(entry.get("raw_daypart_token") or "").strip()
                block_key = ("raw", raw_token) if raw_token else ("raw-empty", idx)
            block_idx = block_indexes.get(block_key)
            if block_idx is None:
                block_idx = len(blocks)
                block_indexes[block_key] = block_idx
                blocks.append(
                    {
                        "raw_token": raw_token,
                        "entry_indexes": [idx],
                    }
                )
            else:
                blocks[block_idx].setdefault("entry_indexes", []).append(idx)

        supported_by_block = {
            block_idx: supported
            for block_idx, block in enumerate(blocks)
            for supported in [_canonical_daypart_key(block.get("raw_token"))]
            if supported
        }
        chosen_sequence = _choose_canonical_daypart_sequence(
            supported_by_block=supported_by_block,
            block_count=len(blocks),
        )
        for block_idx, block in enumerate(blocks):
            assigned_daypart = supported_by_block.get(block_idx) or (
                chosen_sequence[block_idx] if block_idx < len(chosen_sequence) else ""
            )
            if not assigned_daypart:
                continue
            for entry_idx in block.get("entry_indexes") or []:
                entries[entry_idx]["daypart_key"] = assigned_daypart

    return entries


def _looks_like_structural_menu_text(value: object) -> bool:
    text = str(value or "").strip()
    if not text:
        return False
    collapsed = re.sub(r"\s+", "", text)
    if len(collapsed) < 3:
        return False
    if _canonical_daypart_key(text):
        return False
    if collapsed in {"日付", "区分", "献立", "メニュー", "menu", "備考", "備考欄"}:
        return False
    if re.fullmatch(r"品[×xX*＊]\d+", collapsed):
        return False
    if re.fullmatch(r"\d{1,4}(?:[/-]\d{1,2}){0,2}", collapsed):
        return False
    if re.fullmatch(r"[A-Za-z]{1,3}\d*", collapsed):
        return False
    if re.fullmatch(r"[#＃$＄¥￥@＠%％&＆*＊+\-ー_~〜0-9０-９主副高品第朝昼夕タ月火水木金土日曜()（）]+", collapsed):
        return False
    return bool(re.search(r"[A-Za-z一-龯ぁ-んァ-ヶ]", text))


def _build_position_menu_entries_from_structured_tables(
    *,
    payload: dict[str, Any] | None,
    template: dict[str, Any],
    received_at: datetime,
    explicit_week: str | None = None,
) -> list[dict]:
    explicit_week = require_explicit_ingest_week(explicit_week)
    if not isinstance(payload, dict):
        return []
    fields = _row_fields_from_template(template)
    quantity_pairs = _parse_resolved_column_mapping_pairs(payload, fields) if fields else []
    quantity_source_indexes = [source_col_index for source_col_index, _field in quantity_pairs if source_col_index >= 0]
    structural_limit = min(quantity_source_indexes) if quantity_source_indexes else None
    tables = _collect_structured_tables_from_payload(payload)
    if not tables:
        return []

    default_dates = _collect_sheet_dates_from_payload(payload, received_at, template, explicit_week=explicit_week)
    default_date = min(default_dates) if default_dates else None
    entries: list[dict[str, Any]] = []
    seen_identities: set[tuple[str, str, str]] = set()

    for table_payload in tables:
        if not isinstance(table_payload, dict):
            continue
        matrix = None
        raw_rows = table_payload.get("rows")
        if isinstance(raw_rows, list) and raw_rows:
            matrix = fax_extractor._normalize_table_matrix_rows(raw_rows)
        if matrix is None:
            raw_cells = table_payload.get("cells")
            if isinstance(raw_cells, list) and raw_cells:
                matrix = fax_extractor._matrix_from_structured_cells(
                    raw_cells,
                    row_count_hint=table_payload.get("row_count")
                    if isinstance(table_payload.get("row_count"), int)
                    else table_payload.get("n_row"),
                    col_count_hint=table_payload.get("col_count")
                    if isinstance(table_payload.get("col_count"), int)
                    else table_payload.get("n_col"),
                )
        if not matrix:
            continue

        current_date = default_date
        carry_daypart = ""
        for row_idx, row in enumerate(fax_extractor._normalize_table_matrix_rows(matrix)):
            if not isinstance(row, list):
                continue
            limit = structural_limit if isinstance(structural_limit, int) and structural_limit > 0 else len(row)
            structural_cells = [_field_value_to_str(cell).strip() for cell in row[:limit]]
            if not any(structural_cells):
                continue

            row_date: date | None = None
            row_daypart = ""
            remaining: list[str] = []
            for cell_index, cell in enumerate(structural_cells):
                if not cell:
                    continue
                is_date_field = cell_index < len(fields) and fields[cell_index].startswith("date")
                if row_date is None and is_date_field:
                    parsed_date = _extract_entry_date_from_sheet_cell(cell, received_at, explicit_week=explicit_week)
                    if parsed_date:
                        row_date = parsed_date
                        continue
                if not row_daypart:
                    normalized_daypart = _canonical_daypart_key(cell)
                    if normalized_daypart:
                        row_daypart = normalized_daypart
                        continue
                remaining.append(cell)

            if row_date is not None:
                current_date = row_date
            effective_date = row_date or current_date
            if row_daypart:
                carry_daypart = row_daypart
            effective_daypart = row_daypart or carry_daypart
            menu_name = next((cell for cell in reversed(remaining) if _looks_like_structural_menu_text(cell)), "")
            slot_label = next(
                (
                    normalized
                    for cell in remaining
                    for normalized in [normalize_aux_semantic_display_value(cell, "slot_label")]
                    if normalized and cell != menu_name
                ),
                "",
            )
            if not isinstance(effective_date, date) or not effective_daypart or not menu_name:
                continue

            identity = (
                effective_date.isoformat(),
                effective_daypart,
                _normalize_menu_text(menu_name),
            )
            if identity in seen_identities:
                continue
            seen_identities.add(identity)
            entries.append(
                {
                    "menu_name": menu_name,
                    "menu_date": effective_date,
                    "daypart_key": effective_daypart,
                    "category": slot_label or None,
                    "slot_index": 0,
                    "order": len(entries),
                    "source_order": row_idx,
                    "source_row_index": row_idx,
                    "source": "ocr_table_reconstructed",
                }
            )
    return entries


def _merge_weekly_menu_entries_with_ocr_tail(
    weekly_entries: list[dict[str, Any]] | None,
    ocr_entries: list[dict[str, Any]] | None,
) -> list[dict[str, Any]]:
    base_entries = [dict(item) for item in (weekly_entries or []) if isinstance(item, dict)]
    if not base_entries:
        return [dict(item) for item in (ocr_entries or []) if isinstance(item, dict)]
    return base_entries


def _overlay_payload_dayparts_onto_sheet_rows(
    *,
    rows: list[dict[str, Any]] | None,
    fields: list[str] | None,
    payload_rows: list[list[str]] | None,
) -> tuple[list[dict[str, Any]], int]:
    if not rows or not fields or not payload_rows:
        return [dict(item) for item in (rows or []) if isinstance(item, dict)], 0
    date_idx, daypart_idx, _menu_idx, _quantity_indexes = _resolve_structural_row_field_indexes(fields)
    if date_idx is None or daypart_idx is None:
        return [dict(item) for item in (rows or []) if isinstance(item, dict)], 0

    cloned_rows = [dict(item) for item in rows if isinstance(item, dict)]
    row_groups: dict[str, list[int]] = {}
    for idx, row in enumerate(cloned_rows):
        values = row.get("values") if isinstance(row.get("values"), list) else []
        date_key = _normalize_sheet_date_key(values[date_idx] if date_idx < len(values) else "")
        if not date_key:
            continue
        row_groups.setdefault(date_key, []).append(idx)

    payload_groups: dict[str, list[str]] = {}
    current_payload_date_key = ""
    for row in payload_rows:
        if not isinstance(row, list):
            continue
        date_key = _normalize_sheet_date_key(row[date_idx] if date_idx < len(row) else "")
        if date_key:
            current_payload_date_key = date_key
        elif current_payload_date_key:
            date_key = current_payload_date_key
        if not date_key:
            continue
        payload_groups.setdefault(date_key, []).append(
            _canonical_daypart_key(row[daypart_idx] if daypart_idx < len(row) else "")
        )

    overlaid = 0
    for date_key, row_indexes in row_groups.items():
        candidate_dayparts = payload_groups.get(date_key) or []
        if len(candidate_dayparts) != len(row_indexes):
            continue
        if not any(candidate_dayparts):
            continue
        existing_dayparts = []
        for row_idx in row_indexes:
            values = cloned_rows[row_idx].get("values") if isinstance(cloned_rows[row_idx].get("values"), list) else []
            existing_dayparts.append(
                _canonical_daypart_key(values[daypart_idx] if daypart_idx < len(values) else "")
            )
        existing_supported = {item for item in existing_dayparts if item}
        candidate_supported = {item for item in candidate_dayparts if item}
        if len(existing_supported) > 1:
            continue
        if len(candidate_supported) <= len(existing_supported):
            continue
        for position, row_idx in enumerate(row_indexes):
            next_daypart = candidate_dayparts[position]
            if not next_daypart:
                continue
            values = list(cloned_rows[row_idx].get("values") or [])
            while len(values) <= daypart_idx:
                values.append("")
            if values[daypart_idx] == next_daypart:
                cloned_rows[row_idx]["values"] = values
                continue
            values[daypart_idx] = next_daypart
            cloned_rows[row_idx]["values"] = values
            overlaid += 1
    return cloned_rows, overlaid


def _build_sheet_menu_entries(
    *,
    order_id: str | None = None,
    week_id: str,
    facility_id: str | None,
    order_lines: list[dict[str, Any]] | None = None,
    ocr_payload: dict[str, Any] | None,
    template: dict[str, Any],
    received_at: datetime,
) -> tuple[list[dict], str]:
    entries = _build_position_menu_entries_safe(week_id, facility_id)
    if entries:
        return entries, "weekly_menu"
    return [], "menu_missing"


def _merge_missing_weekly_menu_entries_from_ocr_payload(
    *,
    entries: list[dict],
    week_id: str,
    payload: dict[str, Any] | None,
    template: dict[str, Any],
    received_at: datetime,
) -> list[dict]:
    normalized_entries = [dict(item) for item in entries if isinstance(item, dict)]
    if not normalized_entries or not isinstance(payload, dict):
        return normalized_entries

    payload_entries = _prefer_week_scoped_ocr_entries(
        _build_position_menu_entries_from_ocr_payload(
            payload=payload,
            template=template,
            received_at=received_at,
            explicit_week=require_explicit_ingest_week(week_id),
        ),
        week_id,
    )
    if not payload_entries:
        return normalized_entries

    weekly_dates = {
        item.get("menu_date")
        for item in normalized_entries
        if isinstance(item.get("menu_date"), date)
    }
    if not weekly_dates:
        return normalized_entries

    rescued_entries: list[dict] = []
    rescued_identities = {
        _sheet_row_identity(
            item.get("menu_date"),
            item.get("daypart_key"),
            item.get("menu_name"),
        )
        for item in normalized_entries
    }
    for item in payload_entries:
        menu_date = item.get("menu_date")
        if not isinstance(menu_date, date):
            continue
        if menu_date in weekly_dates:
            continue
        identity = _sheet_row_identity(
            item.get("menu_date"),
            item.get("daypart_key"),
            item.get("menu_name"),
        )
        if identity in rescued_identities:
            continue
        rescued_identities.add(identity)
        rescued_entries.append(dict(item))

    if not rescued_entries:
        return normalized_entries

    merged = normalized_entries + rescued_entries
    merged.sort(
        key=lambda item: (
            item.get("menu_date") or date.min,
            _daypart_sort_components(item.get("daypart_key"))[0],
            _daypart_sort_components(item.get("daypart_key"))[1],
            int(item.get("slot_index") or 0),
            int(item.get("source_order") or item.get("order") or 0),
        )
    )
    return merged


def _filter_position_menu_entries_by_dates(
    entries: list[dict],
    target_dates: set[date] | None,
    *,
    min_anchor_dates: int = 2,
) -> list[dict]:
    if not entries or not target_dates:
        return list(entries)
    normalized_dates = {item for item in target_dates if isinstance(item, date)}
    if not normalized_dates:
        return list(entries)

    entry_dates = {
        item.get("menu_date")
        for item in entries
        if isinstance(item, dict) and isinstance(item.get("menu_date"), date)
    }
    matched_dates = sorted(item for item in normalized_dates if item in entry_dates)
    if len(matched_dates) < max(1, int(min_anchor_dates)):
        # Single-date anchors are often OCR noise; keep original monthly scope.
        return list(entries)

    filtered = [
        item
        for item in entries
        if isinstance(item, dict)
        and isinstance(item.get("menu_date"), date)
        and item.get("menu_date") in set(matched_dates)
    ]
    if not filtered:
        return list(entries)

    min_date = matched_dates[0]
    max_date = matched_dates[-1]
    span_days = (max_date - min_date).days
    if 1 < span_days <= 10:
        range_filtered = [
            item
            for item in entries
            if isinstance(item, dict)
            and isinstance(item.get("menu_date"), date)
            and min_date <= item.get("menu_date") <= max_date
        ]
        if len(range_filtered) >= len(filtered):
            filtered = range_filtered
    return filtered


def _select_dominant_date_cluster(
    dates: set[date] | None,
    *,
    max_gap_days: int = 2,
    min_cluster_size: int = 3,
    min_cluster_share: float = 0.6,
) -> set[date]:
    normalized = sorted(item for item in (dates or set()) if isinstance(item, date))
    if len(normalized) <= 1:
        return set(normalized)

    clusters: list[list[date]] = []
    current: list[date] = []
    for item in normalized:
        if not current:
            current = [item]
            continue
        prev = current[-1]
        if (item - prev).days <= max(1, int(max_gap_days)):
            current.append(item)
        else:
            clusters.append(current)
            current = [item]
    if current:
        clusters.append(current)
    if len(clusters) <= 1:
        return set(normalized)

    best = max(clusters, key=lambda cluster: (len(cluster), cluster[-1]))
    if (
        len(best) >= max(1, int(min_cluster_size))
        and (len(best) / len(normalized)) >= float(min_cluster_share)
    ):
        return set(best)
    return set(normalized)




def _build_reparse_position_menu_entries(
    *,
    week_id: str | None,
    facility_id: str | None = None,
    lines: list[dict[str, Any]] | None,
    rows: list[list[Any]] | None,
    parsed_output: dict[str, Any] | None,
    existing_lines: list[dict[str, Any]] | None = None,
    extra_payload_dates: set[date] | None = None,
    received_at: datetime,
    template: dict[str, Any],
) -> list[dict]:
    week_id = require_explicit_ingest_week(week_id)
    lines_for_scope = list(lines or [])
    payload_dates: set[date] = {
        item for item in (extra_payload_dates or set()) if isinstance(item, date)
    }
    existing_line_dates = _collect_line_dates_for_position_scope(existing_lines)
    line_dates = _collect_line_dates_for_position_scope(lines_for_scope)
    if isinstance(parsed_output, dict):
        payload_dates = {
            item
            for item in _collect_sheet_dates_from_payload(parsed_output, received_at, template, explicit_week=require_explicit_ingest_week(week_id))
            if isinstance(item, date)
        }
    payload_dates |= _collect_sheet_dates_from_rows(
        rows, received_at=received_at, fields=_get_row_fields(template), explicit_week=require_explicit_ingest_week(week_id),
    )
    observed_payload_dates = {
        item for item in payload_dates if isinstance(item, date)
    }
    if len(existing_line_dates) >= 2:
        lower = min(existing_line_dates) - timedelta(days=1)
        upper = max(existing_line_dates) + timedelta(days=1)
        existing_min = min(existing_line_dates)
        existing_max = max(existing_line_dates)
        existing_span_days = (existing_max - existing_min).days
        entry_dates_for_scope: set[date] = set()
        if week_id:
            entry_dates_for_scope = {
                item.get("menu_date")
                for item in _build_position_menu_entries_safe(week_id, facility_id)
                if isinstance(item, dict) and isinstance(item.get("menu_date"), date)
            }
        payload_dates_in_scope = {
            item for item in observed_payload_dates if item in entry_dates_for_scope
        }
        payload_dates_inside_existing = {
            item for item in payload_dates_in_scope if lower <= item <= upper
        }
        payload_dates_outside_existing = {
            item for item in payload_dates_in_scope if item < lower or item > upper
        }
        dominant_payload_dates = _select_dominant_date_cluster(payload_dates_in_scope)
        dominant_payload_dates_inside_existing = {
            item for item in dominant_payload_dates if lower <= item <= upper
        }
        dominant_payload_dates_outside_existing = {
            item for item in dominant_payload_dates if item < lower or item > upper
        }
        payload_scope_span_days = 0
        if dominant_payload_dates:
            payload_scope_span_days = (
                max(dominant_payload_dates) - min(dominant_payload_dates)
            ).days
        payload_suggests_week_scope = (
            len(dominant_payload_dates) >= 5
            and len(dominant_payload_dates_outside_existing) >= 3
            and 5 <= payload_scope_span_days <= 10
        )
        existing_scope_is_partial = (
            existing_span_days <= 2 or len(existing_line_dates) <= 3
        )
        allow_payload_scope_override = (
            payload_suggests_week_scope
            and (
                len(dominant_payload_dates_outside_existing)
                > (len(dominant_payload_dates_inside_existing) * 2)
                or existing_scope_is_partial
            )
        )
        if allow_payload_scope_override:
            logger.warning(
                "Reparse existing anchors look stale; prefer payload date anchors",
                existing_dates=[item.isoformat() for item in sorted(existing_line_dates)],
                payload_inside_existing=[item.isoformat() for item in sorted(payload_dates_inside_existing)],
                payload_outside_existing=[item.isoformat() for item in sorted(payload_dates_outside_existing)],
                dominant_payload_dates=[item.isoformat() for item in sorted(dominant_payload_dates)],
                dominant_payload_inside_existing=[
                    item.isoformat() for item in sorted(dominant_payload_dates_inside_existing)
                ],
                dominant_payload_outside_existing=[
                    item.isoformat() for item in sorted(dominant_payload_dates_outside_existing)
                ],
                payload_scope_span_days=payload_scope_span_days,
                existing_scope_is_partial=existing_scope_is_partial,
            )
            # Parsed line dates can still be stale (carried from old scope). When
            # payload anchors are strong enough to override existing scope, defer
            # to payload-driven positioning.
            lines_for_scope = []
        # When persisted lines already define a week scope, ignore parsed line-date
        # anchors that are clearly outside that scope (typical LLM date drift).
        if (
            not allow_payload_scope_override
            and line_dates
            and any(item < lower or item > upper for item in line_dates)
        ):
            logger.warning(
                "Reparse parsed line dates out of existing scope; fallback to existing anchors",
                existing_dates=[item.isoformat() for item in sorted(existing_line_dates)],
                parsed_line_dates=[item.isoformat() for item in sorted(line_dates)],
            )
            lines_for_scope = []
        if not allow_payload_scope_override:
            payload_dates = {
                item for item in observed_payload_dates if lower <= item <= upper
            } | existing_line_dates
        else:
            # Use full in-scope payload anchors when overriding stale/partial
            # existing scope. Keeping only "outside" anchors can drop valid
            # leading/trailing week dates.
            payload_dates = dominant_payload_dates or _select_dominant_date_cluster(
                payload_dates_in_scope or observed_payload_dates
            )
    else:
        payload_dates = observed_payload_dates | existing_line_dates
    return _build_position_entries_for_lines(
        week_id=week_id,
        facility_id=facility_id,
        lines=lines_for_scope,
        payload_dates=payload_dates,
    )


def _collect_line_dates_for_position_scope(lines: list[dict[str, Any]] | None) -> set[date]:
    dates: set[date] = set()
    for line in lines or []:
        if not isinstance(line, dict):
            continue
        parsed = _parse_date_value(line.get("date"))
        if isinstance(parsed, date):
            dates.add(parsed)
    return dates


def _collect_source_row_indexes_for_position_scope(lines: list[dict[str, Any]] | None) -> list[int]:
    indexes: set[int] = set()
    for line in lines or []:
        if not isinstance(line, dict):
            continue
        source_idx_raw = line.get("source_row_index")
        try:
            source_idx = int(source_idx_raw) if source_idx_raw is not None else -1
        except Exception:
            source_idx = -1
        if source_idx >= 0:
            indexes.add(source_idx)
    return sorted(indexes)


def _expand_scoped_entries_for_source_row_span(
    *,
    entries: list[dict],
    scoped_entries: list[dict],
    lines: list[dict[str, Any]] | None,
    max_extension_rows: int = 32,
) -> list[dict]:
    if not entries or not scoped_entries:
        return list(scoped_entries)
    source_indexes = _collect_source_row_indexes_for_position_scope(lines)
    if not source_indexes:
        return list(scoped_entries)
    max_source_row_index = source_indexes[-1]
    if max_source_row_index < 0:
        return list(scoped_entries)
    needed_count = max_source_row_index + 1
    span_density = len(source_indexes) / max(needed_count, 1)
    min_span_density = min(
        _read_reparse_float_env(
            "OCR_REPARSE_SOURCE_ROW_SPAN_MIN_DENSITY",
            0.85,
            min_value=0.0,
        ),
        1.0,
    )
    if span_density < min_span_density:
        return list(scoped_entries)
    overflow_rows = needed_count - len(scoped_entries)
    if overflow_rows <= 0:
        return list(scoped_entries)
    if overflow_rows > max_extension_rows:
        return list(scoped_entries)

    first_entry = scoped_entries[0]
    start_idx: int | None = None
    for idx, item in enumerate(entries):
        if item is first_entry:
            start_idx = idx
            break
    if start_idx is None:
        try:
            start_idx = entries.index(first_entry)
        except ValueError:
            return list(scoped_entries)

    end_idx = start_idx + needed_count
    if end_idx > len(entries):
        return list(scoped_entries)
    return list(entries[start_idx:end_idx])


def _build_position_entries_for_lines(
    *,
    week_id: str | None,
    facility_id: str | None = None,
    lines: list[dict[str, Any]] | None,
    payload_dates: set[date] | None = None,
) -> list[dict]:
    if not week_id:
        return []
    entries = _build_position_menu_entries_safe(week_id, facility_id)
    if not entries:
        return []

    line_dates = _collect_line_dates_for_position_scope(lines)
    line_count = len([line for line in (lines or []) if isinstance(line, dict)])
    line_scope_suspicious = False
    if line_dates:
        if len(line_dates) == 1:
            anchor_date = next(iter(line_dates))
            anchor_row_count = sum(
                1
                for item in entries
                if isinstance(item, dict) and item.get("menu_date") == anchor_date
            )
            # If parsed lines are much larger than one-day menu slots, parsed date anchors
            # likely collapsed into a single day; prefer broader payload anchors.
            if anchor_row_count > 0 and line_count > anchor_row_count * 2:
                line_scope_suspicious = True
        # Line dates are parsed from user-edited/apply inputs and are reliable;
        # allow single-date anchors for strict week/day scope alignment.
        filtered = _filter_position_menu_entries_by_dates(
            entries,
            line_dates,
            min_anchor_dates=1,
        )
        if filtered and not (line_scope_suspicious and len(filtered) < len(entries)):
            return _expand_scoped_entries_for_source_row_span(
                entries=entries,
                scoped_entries=filtered,
                lines=lines,
            )

    if payload_dates:
        # A single payload anchor is still safer than month-wide index drift.
        filtered = _filter_position_menu_entries_by_dates(entries, payload_dates)
        if not filtered or len(filtered) == len(entries):
            filtered = _filter_position_menu_entries_by_dates(
                entries,
                payload_dates,
                min_anchor_dates=1,
            )
        if filtered:
            scoped_entries = list(filtered)
            if not line_scope_suspicious:
                scoped_entries = _expand_scoped_entries_for_source_row_span(
                    entries=entries,
                    scoped_entries=filtered,
                    lines=lines,
                )
            return scoped_entries
    return entries


def _resolve_llm_expected_row_count(
    *,
    menu_expected_row_count: int,
    fallback_expected_row_count: int = 0,
    pipeline_rows: list[list[str]] | None = None,
    observed_rows: list[list[str]] | None = None,
    anchor_date_count: int = 0,
) -> int:
    expected = int(menu_expected_row_count) if menu_expected_row_count and menu_expected_row_count > 0 else 0
    if expected <= 0:
        expected = (
            int(fallback_expected_row_count)
            if fallback_expected_row_count and fallback_expected_row_count > 0
            else 0
        )

    pipeline_count = len([row for row in (pipeline_rows or []) if isinstance(row, list)])
    observed_count = len([row for row in (observed_rows or []) if isinstance(row, list)])
    partial_anchor_max = _read_reparse_int_env(
        "OCR_REPARSE_PARTIAL_ANCHOR_MAX_ROWS",
        24,
        min_value=1,
    )
    partial_anchor_min_gap = _read_reparse_int_env(
        "OCR_REPARSE_PARTIAL_ANCHOR_MIN_GAP_ROWS",
        12,
        min_value=1,
    )
    if pipeline_count <= 0:
        if expected <= 0:
            return observed_count
        # If menu scope is clearly over-broad (for example month-wide 224 rows)
        # while observed rows are week-sized and no reliable pipeline rows exist,
        # use observed row count to avoid false row-coverage failures.
        if observed_count > 0 and expected >= observed_count * 3:
            return observed_count
        # Existing anchors can also be too narrow (for example stale 1-2 day
        # scope after a failed save). When observed OCR rows are significantly
        # larger than this small expectation, trust observed rows.
        if (
            observed_count > 0
            and expected <= partial_anchor_max
            and observed_count >= (expected + partial_anchor_min_gap)
        ):
            return observed_count
        return expected
    if expected <= 0:
        return pipeline_count

    # Existing persisted anchors can be partial (for example only 1-2 dates kept
    # after a previous failed reparse). In that case menu expectation becomes too
    # small and row-coverage gating misses obvious shortfalls. When pipeline rows
    # are significantly larger than this small expectation, trust observable rows.
    if (
        expected <= partial_anchor_max
        and pipeline_count >= (expected + partial_anchor_min_gap)
    ):
        return pipeline_count

    weak_anchor_max_dates = _read_reparse_int_env(
        "OCR_REPARSE_WEAK_ANCHOR_MAX_DATES",
        1,
        min_value=0,
    )
    weak_anchor_min_gap = _read_reparse_int_env(
        "OCR_REPARSE_WEAK_ANCHOR_MIN_GAP_ROWS",
        8,
        min_value=1,
    )
    weak_anchor_observed_delta = _read_reparse_int_env(
        "OCR_REPARSE_WEAK_ANCHOR_OBSERVED_DELTA_ROWS",
        3,
        min_value=0,
    )
    if (
        pipeline_count > 0
        and expected > pipeline_count
        and int(anchor_date_count) <= weak_anchor_max_dates
        and (expected - pipeline_count) >= weak_anchor_min_gap
    ):
        observed_is_close = (
            observed_count <= 0
            or abs(observed_count - pipeline_count) <= weak_anchor_observed_delta
        )
        if observed_is_close:
            return max(pipeline_count, observed_count)

    # When menu expectation is month-wide but OCR/pipeline rows are week-scoped,
    # avoid over-rejecting by preferring the observable pipeline row count.
    if expected >= pipeline_count * 2:
        return pipeline_count
    return expected


class LegacyPositionMappingDisabledError(RuntimeError):
    pass


class LegacyOcrEvidenceFallbackDisabledError(RuntimeError):
    pass


def _raise_legacy_position_mapping_disabled() -> None:
    raise LegacyPositionMappingDisabledError(
        "legacy source_row_index menu position mapping is disabled; "
        "saved semantic sheets must preserve their own date/daypart/menu values"
    )


def _apply_menu_position_mapping(
    lines: list[dict],
    week_id: str | None,
    *,
    facility_id: str | None = None,
    entries_override: list[dict] | None = None,
) -> tuple[list[dict], int]:
    _ = (lines, week_id, facility_id, entries_override)
    _raise_legacy_position_mapping_disabled()


def _apply_menu_position_mapping_safe(
    lines: list[dict[str, Any]],
    week_id: str | None,
    *,
    facility_id: str | None = None,
    entries_override: list[dict[str, Any]] | None = None,
) -> tuple[list[dict[str, Any]], int]:
    _ = entries_override
    return _apply_menu_position_mapping(lines, week_id, facility_id=facility_id)


def _build_canonical_menu_key(
    *,
    menu_date: object,
    daypart: object,
    menu_name: object,
) -> tuple[str, str, str] | None:
    parsed_date = _parse_date_value(menu_date)
    daypart_key = _normalize_daypart_key(daypart)
    menu_raw = str(menu_name or "").strip()
    menu_key = _normalize_menu_text(menu_raw) if menu_raw else ""
    if not isinstance(parsed_date, date) or not daypart_key or not menu_key:
        return None
    return parsed_date.isoformat(), daypart_key, menu_key


def _parse_strict_numeric_cell(value: object) -> float | None:
    text = str(value or "").translate(_MENU_TRANSLATION)
    cleaned = re.sub(r"[\s　]+", "", text)
    cleaned = cleaned.replace(",", "").strip("()[]（）")
    if not cleaned:
        return None
    if not re.fullmatch(r"-?\d+(?:\.\d+)?", cleaned):
        return None
    try:
        parsed = float(cleaned)
    except ValueError:
        return None
    if not float(parsed).is_integer():
        return None
    return _coerce_sheet_quantity_upper_bound(parsed)


def _read_sheet_quantity_max_abs() -> float:
    try:
        max_abs = float(os.getenv("OCR_SHEET_MAX_QTY", "999"))
    except Exception:
        max_abs = 999.0
    if max_abs <= 0:
        return 0.0
    return max_abs


def _coerce_sheet_quantity_upper_bound(value: float | int | None) -> float | None:
    if value is None:
        return None
    try:
        parsed = float(value)
    except Exception:
        return None
    if parsed < 0:
        return None
    if not float(parsed).is_integer():
        return None
    current = int(round(parsed))
    max_abs = _read_sheet_quantity_max_abs()
    if max_abs > 0 and current > max_abs:
        return None
    return float(current)


def _collect_numeric_source_rows_for_reparse(
    *,
    rows: list[list[str]],
    template: dict[str, Any],
    rows_are_body_only: bool = False,
) -> set[int]:
    if not rows:
        return set()
    columns = template.get("columns")
    if not isinstance(columns, list):
        return set()
    quantity_indexes = sorted(
        {
            int(col.get("index"))
            for col in columns
            if isinstance(col, dict)
            and col.get("role") in {"quantity", "quantity_change"}
            and isinstance(col.get("index"), int)
        }
    )
    if not quantity_indexes:
        return set()
    header_rows_raw = template.get("header_rows", 0)
    try:
        header_rows = max(0, int(header_rows_raw))
    except Exception:
        header_rows = 0
    effective_header_rows = 0 if rows_are_body_only else header_rows
    numeric_rows: set[int] = set()
    for source_row_index, row in enumerate(rows[effective_header_rows:]):
        if not isinstance(row, list):
            continue
        for col_idx in quantity_indexes:
            if col_idx < 0 or col_idx >= len(row):
                continue
            qty = _parse_strict_numeric_cell(row[col_idx])
            if qty is None:
                continue
            numeric_rows.add(source_row_index)
            break
    return numeric_rows


def _template_quantity_column_indexes(template: dict[str, Any]) -> list[int]:
    return [item["index"] for item in _template_quantity_columns(template)]


def _template_quantity_columns(template: dict[str, Any]) -> list[dict[str, str | int]]:
    columns = template.get("columns")
    if not isinstance(columns, list):
        return []
    unique_by_index: dict[int, dict[str, str | int]] = {}
    for col in columns:
        if not isinstance(col, dict):
            continue
        if col.get("role") not in {"quantity", "quantity_change"}:
            continue
        index_raw = col.get("index")
        if not isinstance(index_raw, int):
            continue
        item = {
            "index": int(index_raw),
            "diet_type": str(col.get("diet_type") or "").strip(),
            "area_id": str(col.get("area_id") or "").strip(),
            "bag_type": str(col.get("bag_type") or "").strip(),
        }
        unique_by_index[int(index_raw)] = item
    return [unique_by_index[idx] for idx in sorted(unique_by_index.keys())]


def _template_structural_column_indexes(template: dict[str, Any]) -> list[int]:
    columns = template.get("columns")
    if not isinstance(columns, list):
        return []
    roles = {"date", "daypart", "menu", "menu_name"}
    structural_indexes: set[int] = set()
    for col in columns:
        if not isinstance(col, dict):
            continue
        if str(col.get("role") or "").strip() not in roles:
            continue
        index_raw = col.get("index")
        if not isinstance(index_raw, int):
            continue
        structural_indexes.add(int(index_raw))
    return sorted(structural_indexes)


def _row_has_structural_data(
    row: list[str],
    structural_indexes: list[int],
) -> bool:
    for col_index in structural_indexes:
        if col_index < 0 or col_index >= len(row):
            continue
        if str(row[col_index]).strip():
            return True
    return False


def _should_project_quantity_rows_to_structural_rows(
    *,
    rows: list[list[str]],
    structural_rows: list[list[str]],
    template: dict[str, Any],
) -> bool:
    normalized_rows = [list(row) for row in rows if isinstance(row, list)]
    normalized_structural_rows = [list(row) for row in structural_rows if isinstance(row, list)]
    if not normalized_rows or not normalized_structural_rows:
        return False
    max_row_overflow = max(2, int(len(normalized_structural_rows) * 0.1))
    if len(normalized_rows) > len(normalized_structural_rows) + max_row_overflow:
        return False
    if _rows_look_like_quantity_only(
        rows=normalized_rows,
        template=template,
        rows_are_body_only=True,
    ):
        return True
    structural_indexes = _template_structural_column_indexes(template)
    if not structural_indexes:
        return False
    rows_with_structural_data = sum(
        1
        for row in normalized_rows
        if _row_has_structural_data(row=row, structural_indexes=structural_indexes)
    )
    if rows_with_structural_data <= 0:
        return len(normalized_rows) <= len(normalized_structural_rows)
    structural_ratio = float(rows_with_structural_data) / float(len(normalized_rows))
    if len(normalized_rows) < len(normalized_structural_rows):
        return structural_ratio <= 0.2
    return structural_ratio < 0.1


def _analyze_quantity_pair_similarity(
    *,
    rows: list[list[str]],
    left_index: int,
    right_index: int,
) -> dict[str, Any]:
    overlap = 0
    equal_count = 0
    non_zero_overlap = 0
    distinct_pairs: set[tuple[str, str]] = set()
    sample_rows: list[int] = []
    for row_idx, row in enumerate(rows):
        if not isinstance(row, list):
            continue
        if left_index < 0 or right_index < 0:
            continue
        if left_index >= len(row) or right_index >= len(row):
            continue
        left_qty = _parse_strict_numeric_cell(row[left_index])
        right_qty = _parse_strict_numeric_cell(row[right_index])
        if left_qty is None or right_qty is None:
            continue
        overlap += 1
        if abs(left_qty) > 1e-9 or abs(right_qty) > 1e-9:
            non_zero_overlap += 1
        left_repr = _format_merged_quantity_cell(left_qty)
        right_repr = _format_merged_quantity_cell(right_qty)
        distinct_pairs.add((left_repr, right_repr))
        if abs(left_qty - right_qty) <= 1e-9:
            equal_count += 1
            if len(sample_rows) < 12:
                sample_rows.append(row_idx)
    equal_ratio = float(equal_count) / float(overlap) if overlap > 0 else 0.0
    return {
        "overlap": overlap,
        "equal_count": equal_count,
        "equal_ratio": equal_ratio,
        "non_zero_overlap": non_zero_overlap,
        "distinct_pairs": len(distinct_pairs),
        "sample_row_indexes": sample_rows,
    }


def _detect_mirrored_quantity_column_anomalies(
    *,
    rows: list[list[str]],
    quantity_columns: list[dict[str, str | int]],
    reference_rows: list[list[str]] | None = None,
) -> list[dict[str, Any]]:
    if len(quantity_columns) < 2:
        return []
    min_overlap = _read_reparse_int_env("OCR_REPARSE_COLUMN_MIRROR_MIN_OVERLAP", 10, min_value=2)
    min_non_zero_overlap = _read_reparse_int_env(
        "OCR_REPARSE_COLUMN_MIRROR_MIN_NONZERO_OVERLAP",
        4,
        min_value=1,
    )
    min_equal_ratio = _read_reparse_float_env(
        "OCR_REPARSE_COLUMN_MIRROR_MIN_EQUAL_RATIO",
        0.98,
        min_value=0.0,
    )
    if min_equal_ratio > 1.0:
        min_equal_ratio = 1.0
    min_distinct_pairs = _read_reparse_int_env(
        "OCR_REPARSE_COLUMN_MIRROR_MIN_DISTINCT_PAIRS",
        3,
        min_value=1,
    )

    anomalies: list[dict[str, Any]] = []
    for left_pos, left_col in enumerate(quantity_columns):
        left_index_raw = left_col.get("index")
        left_index = int(left_index_raw) if isinstance(left_index_raw, int) else -1
        left_area = str(left_col.get("area_id") or "").strip().lower()
        left_diet = str(left_col.get("diet_type") or "").strip().lower()
        left_bag = str(left_col.get("bag_type") or "").strip().lower()
        if left_index < 0 or not left_area:
            continue
        for right_col in quantity_columns[left_pos + 1 :]:
            right_index_raw = right_col.get("index")
            right_index = int(right_index_raw) if isinstance(right_index_raw, int) else -1
            right_area = str(right_col.get("area_id") or "").strip().lower()
            right_diet = str(right_col.get("diet_type") or "").strip().lower()
            right_bag = str(right_col.get("bag_type") or "").strip().lower()
            if right_index < 0 or not right_area:
                continue
            if left_area == right_area:
                continue
            if left_diet != right_diet or left_bag != right_bag:
                continue

            stats = _analyze_quantity_pair_similarity(
                rows=rows,
                left_index=left_index,
                right_index=right_index,
            )
            overlap = int(stats.get("overlap") or 0)
            equal_ratio = float(stats.get("equal_ratio") or 0.0)
            non_zero_overlap = int(stats.get("non_zero_overlap") or 0)
            distinct_pairs = int(stats.get("distinct_pairs") or 0)
            if overlap < min_overlap:
                continue
            if non_zero_overlap < min_non_zero_overlap:
                continue
            if distinct_pairs < min_distinct_pairs:
                continue
            if equal_ratio < min_equal_ratio:
                continue

            if isinstance(reference_rows, list) and reference_rows:
                reference_stats = _analyze_quantity_pair_similarity(
                    rows=reference_rows,
                    left_index=left_index,
                    right_index=right_index,
                )
                ref_overlap = int(reference_stats.get("overlap") or 0)
                ref_equal_ratio = float(reference_stats.get("equal_ratio") or 0.0)
                ref_non_zero_overlap = int(reference_stats.get("non_zero_overlap") or 0)
                ref_distinct_pairs = int(reference_stats.get("distinct_pairs") or 0)
                # When reference rows show the same mirror pattern, treat it as valid
                # sheet structure and avoid false positives.
                if (
                    ref_overlap >= min_overlap
                    and ref_non_zero_overlap >= min_non_zero_overlap
                    and ref_distinct_pairs >= min_distinct_pairs
                    and ref_equal_ratio >= min_equal_ratio
                ):
                    continue

            anomalies.append(
                {
                    "index": right_index,
                    "reason": "mirrored_sibling_columns",
                    "mirror_with_index": left_index,
                    "pair_signature": {
                        "diet_type": str(left_col.get("diet_type") or ""),
                        "bag_type": str(left_col.get("bag_type") or ""),
                        "left_area_id": str(left_col.get("area_id") or ""),
                        "right_area_id": str(right_col.get("area_id") or ""),
                    },
                    "overlap": overlap,
                    "equal_count": int(stats.get("equal_count") or 0),
                    "equal_ratio": round(equal_ratio, 4),
                    "non_zero_overlap": non_zero_overlap,
                    "distinct_pairs": distinct_pairs,
                    "sample_row_indexes": list(stats.get("sample_row_indexes") or []),
                    "thresholds": {
                        "min_overlap": min_overlap,
                        "min_non_zero_overlap": min_non_zero_overlap,
                        "min_equal_ratio": min_equal_ratio,
                        "min_distinct_pairs": min_distinct_pairs,
                    },
                }
            )
    return anomalies


def _format_merged_quantity_cell(value: float) -> str:
    if abs(value - round(value)) < 1e-9:
        return str(int(round(value)))
    return f"{value:.4f}".rstrip("0").rstrip(".")


def _merge_llm_quantity_only_rows_with_pipeline(
    *,
    llm_rows: list[list[str]],
    pipeline_rows: list[list[str]],
    template: dict[str, Any],
) -> tuple[list[list[str]], dict[str, int]]:
    stats = {
        "pipeline_rows": len(pipeline_rows),
        "llm_rows": len(llm_rows),
        "rows_with_qty": 0,
        "quantity_cells_updated": 0,
    }
    if not llm_rows or not pipeline_rows:
        return llm_rows, stats
    quantity_indexes = _template_quantity_column_indexes(template)
    if not quantity_indexes:
        return llm_rows, stats

    merged_rows: list[list[str]] = [list(row) if isinstance(row, list) else [] for row in pipeline_rows]
    for row_index, llm_row in enumerate(llm_rows):
        if not isinstance(llm_row, list):
            continue
        while row_index >= len(merged_rows):
            merged_rows.append([])
        target_row = merged_rows[row_index]
        row_has_qty = False
        for col_index in quantity_indexes:
            if col_index < 0 or col_index >= len(llm_row):
                continue
            qty = _parse_strict_numeric_cell(llm_row[col_index])
            if qty is None:
                continue
            while len(target_row) <= col_index:
                target_row.append("")
            target_row[col_index] = _format_merged_quantity_cell(qty)
            stats["quantity_cells_updated"] += 1
            row_has_qty = True
        if row_has_qty:
            stats["rows_with_qty"] += 1
    return merged_rows, stats


def _rows_look_like_quantity_only(
    *,
    rows: list[list[str]],
    template: dict[str, Any],
    rows_are_body_only: bool = False,
) -> bool:
    if not rows:
        return False
    columns = template.get("columns")
    if not isinstance(columns, list):
        return False
    quantity_indexes = sorted(
        {
            int(col.get("index"))
            for col in columns
            if isinstance(col, dict)
            and col.get("role") in {"quantity", "quantity_change"}
            and isinstance(col.get("index"), int)
        }
    )
    if not quantity_indexes:
        return False
    structural_indexes = sorted(
        {
            int(col.get("index"))
            for col in columns
            if isinstance(col, dict)
            and col.get("role") in {"date", "daypart", "menu_name"}
            and isinstance(col.get("index"), int)
        }
    )
    if not structural_indexes:
        return False
    header_rows_raw = template.get("header_rows", 0)
    try:
        header_rows = max(0, int(header_rows_raw))
    except Exception:
        header_rows = 0
    effective_header_rows = 0 if rows_are_body_only else header_rows
    data_rows = [row for row in rows[effective_header_rows:] if isinstance(row, list)]
    if not data_rows:
        return False

    rows_with_qty = 0
    rows_with_empty_structure = 0
    for row in data_rows:
        has_qty = False
        for col_idx in quantity_indexes:
            if col_idx < 0 or col_idx >= len(row):
                continue
            if _parse_strict_numeric_cell(row[col_idx]) is not None:
                has_qty = True
                break
        if has_qty:
            rows_with_qty += 1
        structure_values = [
            str(row[col_idx]).strip()
            for col_idx in structural_indexes
            if col_idx >= 0 and col_idx < len(row)
        ]
        if not any(structure_values):
            rows_with_empty_structure += 1
    if rows_with_qty == 0:
        return False
    # Treat as quantity-only when most rows have quantity cells but all structural
    # columns (date/daypart/menu) are blank.
    return rows_with_empty_structure >= max(1, int(len(data_rows) * 0.7))


def _read_reparse_float_env(name: str, default: float, *, min_value: float | None = None) -> float:
    raw = str(os.getenv(name, str(default))).strip()
    try:
        value = float(raw)
    except Exception:
        value = float(default)
    if min_value is not None and value < min_value:
        value = float(min_value)
    return value


def _read_reparse_int_env(name: str, default: int, *, min_value: int | None = None) -> int:
    raw = str(os.getenv(name, str(default))).strip()
    try:
        value = int(raw)
    except Exception:
        value = int(default)
    if min_value is not None and value < min_value:
        value = int(min_value)
    return value


def _read_reparse_bool_env(name: str, default: bool) -> bool:
    raw = str(os.getenv(name, "1" if default else "0")).strip().lower()
    if raw in {"1", "true", "yes", "on"}:
        return True
    if raw in {"0", "false", "no", "off"}:
        return False
    return bool(default)


def _read_reparse_stage_timeout_seconds(processing_stage: str) -> float:
    normalized_stage = re.sub(r"[^a-z0-9]+", "_", str(processing_stage or "").strip().lower()).strip("_")
    stale_budget = max((get_ocr_job_stale_minutes() * 60) - 60, 60)
    default_timeout = float(min(max(stale_budget, 60), 600))
    if normalized_stage:
        specific_name = f"OCR_REPARSE_{normalized_stage.upper()}_TIMEOUT_SECONDS"
        specific_value = os.getenv(specific_name)
        if specific_value is not None:
            try:
                parsed = float(str(specific_value).strip())
                return max(parsed, 30.0)
            except Exception:
                pass
    return _read_reparse_float_env(
        "OCR_REPARSE_STAGE_TIMEOUT_SECONDS",
        default_timeout,
        min_value=30.0,
    )


def _run_reparse_with_heartbeat(
    job_id: str,
    *,
    processing_stage: str,
    func,
    result_state: str = "processing",
    metrics_patch: dict[str, Any] | None = None,
    timeout_marks_job_failed: bool = True,
    timeout_seconds_override: float | None = None,
):
    interval_seconds = _read_reparse_float_env(
        "OCR_REPARSE_HEARTBEAT_SECONDS",
        45.0,
        min_value=5.0,
    )
    if timeout_seconds_override is None:
        stage_timeout_seconds = _read_reparse_stage_timeout_seconds(processing_stage)
    else:
        stage_timeout_seconds = max(float(timeout_seconds_override), 0.01)
    done_event = threading.Event()
    result_holder: dict[str, Any] = {}
    error_holder: dict[str, BaseException] = {}

    def _run_func() -> None:
        try:
            result_holder["value"] = func()
        except BaseException as exc:  # noqa: BLE001
            error_holder["error"] = exc
        finally:
            done_event.set()

    captured_context = copy_context()
    worker = threading.Thread(
        target=lambda: captured_context.run(_run_func),
        name=f"reparse-stage-{job_id}-{processing_stage}",
        daemon=True,
    )
    worker.start()
    started_at = time.monotonic()
    while not done_event.wait(interval_seconds):
        elapsed = time.monotonic() - started_at
        if stage_timeout_seconds > 0 and elapsed >= stage_timeout_seconds:
            timeout_error = f"reparse_stage_timeout:{processing_stage}>{int(stage_timeout_seconds)}s"
            if timeout_marks_job_failed:
                try:
                    _update_reparse_job_progress(
                        job_id,
                        status="failed",
                        processing_stage=f"{processing_stage}_timeout",
                        result_state="hard_failed",
                        error_message=timeout_error,
                        metrics_patch={
                            **dict(metrics_patch or {}),
                            "error": timeout_error,
                            "stage_timeout_seconds": float(stage_timeout_seconds),
                        },
                    )
                except Exception as exc:  # noqa: BLE001
                    logger.debug(
                        "Reparse timeout update skipped job_id={} stage={} error={}",
                        job_id,
                        processing_stage,
                        str(exc),
                    )
            raise TimeoutError(timeout_error)
        try:
            _update_reparse_job_progress(
                job_id,
                status="running",
                processing_stage=processing_stage,
                result_state=result_state,
                metrics_patch=metrics_patch,
            )
        except Exception as exc:  # noqa: BLE001
            logger.debug(
                "Reparse heartbeat update skipped job_id={} stage={} error={}",
                job_id,
                processing_stage,
                str(exc),
            )
    if "error" in error_holder:
        raise error_holder["error"]
    return result_holder.get("value")


def _resolve_reparse_soft_warning_codes() -> set[str]:
    raw = str(
        os.getenv(
            "OCR_REPARSE_SOFT_WARNING_CODES",
            "sheet_column_anomaly",
        )
        or ""
    ).strip()
    if not raw:
        return set()
    return {
        token.strip().lower()
        for token in raw.split(",")
        if token and token.strip()
    }


def _is_soft_warning_validation_error(error_code: str | None) -> bool:
    if not _read_reparse_bool_env("OCR_REPARSE_ENABLE_SOFT_WARNINGS", True):
        return False
    normalized = str(error_code or "").strip().lower()
    if not normalized:
        return False
    return normalized in _resolve_reparse_soft_warning_codes()


def _coerce_quantity_with_custom_max(value: float | int | None, *, max_abs: float) -> float | None:
    if value is None:
        return None
    try:
        parsed = float(value)
    except Exception:
        return None
    if parsed < 0:
        return None
    if not float(parsed).is_integer():
        return None
    current = int(round(parsed))
    if max_abs > 0 and current > max_abs:
        return None
    return float(current)


def _coerce_reparse_quantity_value(value: object, *, max_abs: float) -> float | None:
    if value is None:
        return None
    try:
        parsed = float(value)
    except Exception:
        return None
    if parsed < 0:
        return None
    # Meal counts are integers; OCR/LLM can emit split digits like "2.1".
    if not float(parsed).is_integer():
        scaled = parsed * 10.0
        if 0 < parsed < 10 and abs(scaled - round(scaled)) < 1e-9:
            parsed = float(round(scaled))
        else:
            return None
    return _coerce_quantity_with_custom_max(parsed, max_abs=max_abs)


def _sanitize_reparse_line_quantities(lines: list[dict[str, Any]]) -> tuple[list[dict[str, Any]], dict[str, int]]:
    max_abs = _read_reparse_float_env(
        "OCR_REPARSE_MAX_QTY",
        _read_sheet_quantity_max_abs(),
        min_value=1.0,
    )
    stats = {
        "max_abs_qty": int(max_abs),
        "lines_in": len(lines),
        "lines_out": 0,
        "quantity_adjusted": 0,
        "quantity_dropped": 0,
        "lines_dropped": 0,
    }
    sanitized: list[dict[str, Any]] = []
    for raw in lines:
        if not isinstance(raw, dict):
            continue
        line = dict(raw)
        for key in ("quantity_corrected", "quantity_original"):
            if key not in line:
                continue
            original = line.get(key)
            if original is None:
                continue
            coerced = _coerce_reparse_quantity_value(original, max_abs=max_abs)
            if coerced is None:
                line[key] = None
                stats["quantity_dropped"] += 1
                continue
            if isinstance(original, (int, float)) and abs(float(original) - coerced) < 1e-9:
                line[key] = coerced
                continue
            line[key] = coerced
            stats["quantity_adjusted"] += 1
        if line.get("quantity_corrected") is None and line.get("quantity_original") is None:
            stats["lines_dropped"] += 1
            continue
        sanitized.append(line)
    stats["lines_out"] = len(sanitized)
    return sanitized, stats


def _coerce_usage_int(value: object) -> int:
    try:
        parsed = int(value)
    except Exception:
        return 0
    return parsed if parsed > 0 else 0


def _extract_usage_from_provider_debug(provider_debug: dict[str, Any] | None) -> dict[str, int]:
    if not isinstance(provider_debug, dict):
        return {}

    usage_raw = provider_debug.get("usage")
    if not isinstance(usage_raw, dict):
        attempts = provider_debug.get("attempts")
        if isinstance(attempts, list) and attempts:
            last_attempt = attempts[-1]
            if isinstance(last_attempt, dict):
                usage_raw = last_attempt.get("usage")
    if not isinstance(usage_raw, dict):
        return {}

    prompt_tokens = _coerce_usage_int(usage_raw.get("prompt_tokens"))
    completion_tokens = _coerce_usage_int(usage_raw.get("completion_tokens"))
    total_tokens = _coerce_usage_int(usage_raw.get("total_tokens"))
    cached_content_tokens = _coerce_usage_int(usage_raw.get("cached_content_tokens"))

    if total_tokens <= 0:
        total_tokens = prompt_tokens + completion_tokens
    return {
        "prompt_tokens": prompt_tokens,
        "completion_tokens": completion_tokens,
        "total_tokens": total_tokens,
        "cached_content_tokens": cached_content_tokens,
    }


def _resolve_reparse_cost_rates(
    *,
    provider: str,
    model: str | None,
) -> tuple[float, float]:
    normalized_provider = str(provider or "").strip().lower()
    normalized_model = str(model or "").strip().lower()
    if normalized_provider == "gemini":
        if "pro" in normalized_model:
            input_rate = _read_reparse_float_env(
                "OCR_REPARSE_COST_GEMINI_PRO_INPUT_USD_PER_1M",
                1.25,
                min_value=0.0,
            )
            output_rate = _read_reparse_float_env(
                "OCR_REPARSE_COST_GEMINI_PRO_OUTPUT_USD_PER_1M",
                10.0,
                min_value=0.0,
            )
        else:
            input_rate = _read_reparse_float_env(
                "OCR_REPARSE_COST_GEMINI_FLASH_INPUT_USD_PER_1M",
                0.30,
                min_value=0.0,
            )
            output_rate = _read_reparse_float_env(
                "OCR_REPARSE_COST_GEMINI_FLASH_OUTPUT_USD_PER_1M",
                2.50,
                min_value=0.0,
            )
    elif normalized_provider == "openai":
        input_rate = _read_reparse_float_env(
            "OCR_REPARSE_COST_OPENAI_INPUT_USD_PER_1M",
            5.0,
            min_value=0.0,
        )
        output_rate = _read_reparse_float_env(
            "OCR_REPARSE_COST_OPENAI_OUTPUT_USD_PER_1M",
            15.0,
            min_value=0.0,
        )
    else:
        input_rate = _read_reparse_float_env(
            "OCR_REPARSE_COST_INPUT_USD_PER_1M",
            0.0,
            min_value=0.0,
        )
        output_rate = _read_reparse_float_env(
            "OCR_REPARSE_COST_OUTPUT_USD_PER_1M",
            0.0,
            min_value=0.0,
        )
    return input_rate, output_rate


def _estimate_reparse_llm_cost(
    *,
    provider: str | None,
    model: str | None,
    provider_debug: dict[str, Any] | None,
) -> dict[str, Any] | None:
    normalized_provider = str(provider or "").strip().lower()
    if normalized_provider not in {"gemini", "openai"}:
        return None

    usage = _extract_usage_from_provider_debug(provider_debug)
    if not usage or usage.get("total_tokens", 0) <= 0:
        return None

    input_rate, output_rate = _resolve_reparse_cost_rates(
        provider=normalized_provider,
        model=model,
    )
    estimated_cost: float | None = None
    if input_rate > 0.0 or output_rate > 0.0:
        estimated_cost = (
            (float(usage.get("prompt_tokens", 0)) * input_rate)
            + (float(usage.get("completion_tokens", 0)) * output_rate)
        ) / 1_000_000.0

    soft_limit = _read_reparse_float_env(
        "OCR_REPARSE_COST_SOFT_LIMIT_USD",
        0.10,
        min_value=0.0,
    )
    hard_limit = _read_reparse_float_env(
        "OCR_REPARSE_COST_HARD_LIMIT_USD",
        1.00,
        min_value=0.0,
    )

    over_soft = (
        estimated_cost is not None
        and soft_limit > 0.0
        and estimated_cost > soft_limit
    )
    over_hard = (
        estimated_cost is not None
        and hard_limit > 0.0
        and estimated_cost > hard_limit
    )
    return {
        "provider": normalized_provider,
        "model": str(model or "").strip() or None,
        "usage": usage,
        "pricing": {
            "input_usd_per_1m_tokens": input_rate,
            "output_usd_per_1m_tokens": output_rate,
        },
        "estimated_cost_usd": estimated_cost,
        "soft_limit_usd": soft_limit,
        "hard_limit_usd": hard_limit,
        "over_soft_limit": bool(over_soft),
        "over_hard_limit": bool(over_hard),
    }


def _quantity_column_non_empty_counts(
    *,
    rows: list[list[str]],
    quantity_indexes: list[int],
) -> dict[int, int]:
    counts: dict[int, int] = {idx: 0 for idx in quantity_indexes}
    for row in rows:
        if not isinstance(row, list):
            continue
        for idx in quantity_indexes:
            if idx < 0 or idx >= len(row):
                continue
            if _parse_strict_numeric_cell(row[idx]) is not None:
                counts[idx] = counts.get(idx, 0) + 1
    return counts


def _evaluate_quantity_only_rows_quality(
    *,
    rows: list[list[str]],
    template: dict[str, Any],
    expected_row_count: int,
    reference_rows: list[list[str]] | None,
) -> tuple[str | None, dict[str, Any] | None]:
    normalized_rows = [list(row) for row in rows if isinstance(row, list)]
    row_count = len(normalized_rows)
    effective_expected = max(int(expected_row_count or 0), 0)
    if effective_expected <= 0 and isinstance(reference_rows, list):
        effective_expected = max(len([row for row in reference_rows if isinstance(row, list)]), 0)
    if effective_expected <= 0:
        return None, None

    row_coverage_ratio = float(row_count) / float(effective_expected) if effective_expected > 0 else 1.0
    missing_tail_rows = max(effective_expected - row_count, 0)
    min_coverage_ratio = _read_reparse_float_env(
        "OCR_REPARSE_ROW_COVERAGE_MIN_RATIO",
        0.98,
        min_value=0.0,
    )
    max_missing_tail = _read_reparse_int_env(
        "OCR_REPARSE_MAX_MISSING_TAIL_ROWS",
        0,
        min_value=0,
    )

    detail: dict[str, Any] = {
        "expected_row_count": int(effective_expected),
        "actual_row_count": int(row_count),
        "row_coverage_ratio": round(row_coverage_ratio, 4),
        "missing_tail_rows": int(missing_tail_rows),
        "min_coverage_ratio": float(min_coverage_ratio),
        "max_missing_tail_rows": int(max_missing_tail),
    }

    if row_coverage_ratio < min_coverage_ratio or missing_tail_rows > max_missing_tail:
        detail["quality_issue"] = "row_coverage"
        return "sheet_row_coverage_low", detail

    extra_rows = max(row_count - effective_expected, 0)
    max_extra_rows = _read_reparse_int_env(
        "OCR_REPARSE_MAX_EXTRA_ROWS",
        0,
        min_value=0,
    )
    detail["extra_rows"] = int(extra_rows)
    detail["max_extra_rows"] = int(max_extra_rows)
    if extra_rows > max_extra_rows:
        detail["quality_issue"] = "row_overfill"
        return "sheet_row_overfill", detail

    if str(os.getenv("OCR_REPARSE_ENABLE_COLUMN_ANOMALY_GATE", "1")).strip().lower() in {"0", "false", "no", "off"}:
        return None, detail

    quantity_columns = _template_quantity_columns(template)
    quantity_indexes: list[int] = []
    for item in quantity_columns:
        index_raw = item.get("index")
        if not isinstance(index_raw, int):
            continue
        if index_raw < 0:
            continue
        quantity_indexes.append(index_raw)
    reference_normalized = (
        [list(row) for row in reference_rows if isinstance(row, list)]
        if isinstance(reference_rows, list)
        else []
    )
    if not quantity_indexes:
        return None, detail

    llm_counts = _quantity_column_non_empty_counts(
        rows=normalized_rows,
        quantity_indexes=quantity_indexes,
    )
    detail["column_non_empty"] = {
        "llm": {str(idx): int(llm_counts.get(idx, 0)) for idx in quantity_indexes},
    }

    anomaly_columns: list[dict[str, Any]] = []
    if not reference_normalized:
        detail["column_reference_missing"] = True
    else:
        detail["column_reference_missing"] = False
        ref_counts = _quantity_column_non_empty_counts(
            rows=reference_normalized,
            quantity_indexes=quantity_indexes,
        )
        detail["column_non_empty"]["reference"] = {
            str(idx): int(ref_counts.get(idx, 0)) for idx in quantity_indexes
        }
        min_ratio = _read_reparse_float_env("OCR_REPARSE_COLUMN_NONEMPTY_MIN_RATIO", 0.25, min_value=0.0)
        max_ratio = _read_reparse_float_env("OCR_REPARSE_COLUMN_NONEMPTY_MAX_RATIO", 3.0, min_value=0.1)
        if max_ratio < min_ratio:
            max_ratio = min_ratio
        min_reference_count = _read_reparse_int_env(
            "OCR_REPARSE_COLUMN_RATIO_MIN_REFERENCE_COUNT",
            6,
            min_value=1,
        )
        enable_unexpected_nonempty = _read_reparse_bool_env(
            "OCR_REPARSE_ENABLE_COLUMN_UNEXPECTED_NONEMPTY_GATE",
            False,
        )
        unexpected_abs = _read_reparse_int_env("OCR_REPARSE_COLUMN_UNEXPECTED_NONEMPTY_ABS", 4, min_value=1)
        unexpected_ratio = _read_reparse_float_env(
            "OCR_REPARSE_COLUMN_UNEXPECTED_NONEMPTY_RATIO",
            0.12,
            min_value=0.0,
        )

        expected_for_threshold = max(effective_expected, len(reference_normalized))
        unexpected_threshold = max(unexpected_abs, int(expected_for_threshold * unexpected_ratio))
        ratio_skipped_low_reference: dict[str, int] = {}
        for idx in quantity_indexes:
            llm_count = int(llm_counts.get(idx, 0))
            ref_count = int(ref_counts.get(idx, 0))
            if ref_count <= 0:
                if enable_unexpected_nonempty and llm_count >= unexpected_threshold:
                    anomaly_columns.append(
                        {
                            "index": idx,
                            "reason": "unexpected_non_empty",
                            "llm_non_empty": llm_count,
                            "reference_non_empty": ref_count,
                            "threshold": unexpected_threshold,
                        }
                    )
                continue
            if ref_count < min_reference_count:
                ratio_skipped_low_reference[str(idx)] = ref_count
                continue
            ratio = float(llm_count) / float(ref_count)
            if ratio < min_ratio or ratio > max_ratio:
                anomaly_columns.append(
                    {
                        "index": idx,
                        "reason": "non_empty_ratio_out_of_range",
                        "llm_non_empty": llm_count,
                        "reference_non_empty": ref_count,
                        "ratio": round(ratio, 4),
                        "min_ratio": min_ratio,
                        "max_ratio": max_ratio,
                    }
                )
        detail["column_ratio_min_reference_count"] = int(min_reference_count)
        detail["column_ratio_skipped_low_reference"] = ratio_skipped_low_reference
        detail["column_unexpected_nonempty_enabled"] = bool(enable_unexpected_nonempty)

    enable_mirror_gate = _read_reparse_bool_env("OCR_REPARSE_ENABLE_COLUMN_MIRROR_GATE", True)
    mirrored_column_anomalies: list[dict[str, Any]] = []
    if enable_mirror_gate:
        mirrored_column_anomalies = _detect_mirrored_quantity_column_anomalies(
            rows=normalized_rows,
            quantity_columns=quantity_columns,
            reference_rows=reference_normalized if reference_normalized else None,
        )
    if mirrored_column_anomalies:
        anomaly_columns.extend(mirrored_column_anomalies)
    detail["column_mirror_anomaly_count"] = len(mirrored_column_anomalies)

    if "reference" not in detail["column_non_empty"]:
        detail["column_non_empty"]["reference"] = {}

    detail["column_anomaly_count"] = len(anomaly_columns)
    if anomaly_columns:
        detail["quality_issue"] = "column_anomaly"
        detail["column_anomalies"] = anomaly_columns[:20]
        return "sheet_column_anomaly", detail
    return None, detail


def _is_reparse_quality_improved(
    *,
    before_error: str | None,
    before_detail: dict[str, Any] | None,
    after_error: str | None,
    after_detail: dict[str, Any] | None,
) -> bool:
    if before_error and not after_error:
        return True
    if not before_error:
        return False
    if before_error != after_error:
        return False
    if not isinstance(before_detail, dict) or not isinstance(after_detail, dict):
        return False

    before_coverage = float(before_detail.get("row_coverage_ratio") or 0.0)
    after_coverage = float(after_detail.get("row_coverage_ratio") or 0.0)
    before_missing_tail = int(before_detail.get("missing_tail_rows") or 0)
    after_missing_tail = int(after_detail.get("missing_tail_rows") or 0)
    before_extra_rows = int(before_detail.get("extra_rows") or 0)
    after_extra_rows = int(after_detail.get("extra_rows") or 0)
    before_col_anomaly = int(before_detail.get("column_anomaly_count") or 0)
    after_col_anomaly = int(after_detail.get("column_anomaly_count") or 0)

    if after_coverage > before_coverage:
        return True
    if after_missing_tail < before_missing_tail:
        return True
    if after_extra_rows < before_extra_rows:
        return True
    if after_col_anomaly < before_col_anomaly:
        return True
    return False




def _compact_line_debug_item(line: dict[str, Any]) -> dict[str, Any]:
    qty_corrected = line.get("quantity_corrected")
    qty_original = line.get("quantity_original")
    quantity = qty_corrected if qty_corrected is not None else qty_original
    return {
        "source_row_index": line.get("source_row_index"),
        "date": str(line.get("date") or ""),
        "daypart": str(line.get("daypart") or ""),
        "menu_name": str(line.get("menu_name") or ""),
        "diet_type": str(line.get("diet_type") or ""),
        "area_id": str(line.get("area_id") or ""),
        "bag_type": str(line.get("bag_type") or ""),
        "quantity": quantity,
    }


def _validate_reparse_lines_against_weekly_menu(
    *,
    lines: list[dict[str, Any]],
    week_id: str | None,
    facility_id: str | None = None,
    ocr_rows: list[list[str]] | None,
    template: dict[str, Any],
    entries_override: list[dict[str, Any]] | None = None,
    rows_are_body_only: bool = False,
) -> tuple[str | None, dict[str, Any] | None]:
    if not lines:
        return None, None
    entries: list[dict[str, Any]]
    if isinstance(entries_override, list):
        entries = [item for item in entries_override if isinstance(item, dict)]
    else:
        if not week_id:
            return None, None
        entries = _build_position_menu_entries_safe(week_id, facility_id)
    if not entries:
        return None, None

    weekly_key_set: set[tuple[str, str, str]] = set()
    weekly_keys_by_source_row: dict[int, set[tuple[str, str, str]]] = {}
    for idx, entry in enumerate(entries):
        if "diet_variants" in entry and not entry.get("menu_name"):
            raise ValueError("physical_menu_common_name_unresolved")
        variants = entry.get("diet_variants")
        logical_entries = list(variants.values()) if isinstance(variants, dict) else [entry]
        keys = {
            key for logical_entry in logical_entries
            if (key := _build_canonical_menu_key(
                menu_date=logical_entry.get("menu_date"),
                daypart=logical_entry.get("daypart_key"),
                menu_name=logical_entry.get("menu_name"),
            )) is not None
        }
        weekly_key_set.update(keys)
        weekly_keys_by_source_row[idx] = keys

    if not weekly_key_set:
        return None, None

    invalid_lines: list[int] = []
    mismatch_source_rows: list[int] = []
    missing_source_rows: list[int] = []
    line_keys_by_source_row: dict[int, set[tuple[str, str, str]]] = {}
    line_samples: list[dict[str, Any]] = []
    for idx, line in enumerate(lines):
        line_key = _build_canonical_menu_key(
            menu_date=line.get("date"),
            daypart=line.get("daypart"),
            menu_name=line.get("menu_name"),
        )
        if len(line_samples) < 8:
            line_samples.append(_compact_line_debug_item(line))
        if line_key is None or line_key not in weekly_key_set:
            invalid_lines.append(idx)
            continue
        source_row_raw = line.get("source_row_index")
        try:
            source_row_index = int(source_row_raw) if source_row_raw is not None else None
        except Exception:
            source_row_index = None
        if source_row_index is not None and source_row_index >= 0:
            line_keys_by_source_row.setdefault(source_row_index, set()).add(line_key)

    numeric_source_rows = _collect_numeric_source_rows_for_reparse(
        rows=[list(item) for item in (ocr_rows or []) if isinstance(item, list)],
        template=template,
        rows_are_body_only=rows_are_body_only,
    )
    for source_row_index in sorted(numeric_source_rows):
        expected_keys = weekly_keys_by_source_row.get(source_row_index)
        if not expected_keys:
            continue
        actual_keys = line_keys_by_source_row.get(source_row_index) or set()
        if not actual_keys:
            missing_source_rows.append(source_row_index)
            continue
        if not expected_keys.intersection(actual_keys):
            mismatch_source_rows.append(source_row_index)

    if not invalid_lines and not mismatch_source_rows and not missing_source_rows:
        return None, None

    detail = {
        "week_id": week_id,
        "weekly_entry_count": len(entries),
        "line_count": len(lines),
        "invalid_line_indexes": invalid_lines[:40],
        "source_row_mismatches": mismatch_source_rows[:40],
        "source_row_missing": missing_source_rows[:40],
        "numeric_source_rows_checked": sorted(numeric_source_rows)[:80],
        "line_sample": line_samples,
    }
    if invalid_lines or mismatch_source_rows:
        return "sheet_canonical_mismatch", detail
    if _rows_look_like_quantity_only(
        rows=[list(row) for row in (ocr_rows or []) if isinstance(row, list)],
        template=template,
        rows_are_body_only=rows_are_body_only,
    ):
        return None, None
    return "sheet_suspicious_blank_row", detail


def _collect_filled_source_rows_from_lines(
    lines: list[dict[str, Any]] | None,
) -> list[int]:
    indexes: set[int] = set()
    for line in lines or []:
        if not isinstance(line, dict):
            continue
        quantity_value = line.get("quantity_corrected")
        if quantity_value is None or quantity_value == "":
            quantity_value = line.get("quantity_original")
        if _parse_strict_numeric_cell(quantity_value) is None:
            continue
        source_row_raw = line.get("source_row_index")
        try:
            source_row_index = int(source_row_raw) if source_row_raw is not None else -1
        except Exception:
            source_row_index = -1
        if source_row_index >= 0:
            indexes.add(source_row_index)
    return sorted(indexes)


def _validate_reparse_blank_anchor_drift(
    *,
    lines: list[dict[str, Any]],
    structural_fields: list[str] | None,
    structural_rows: list[list[str]] | None,
    reference_rows: list[list[str]] | None,
    reference_fields: list[str] | None = None,
) -> tuple[str | None, dict[str, Any] | None]:
    normalized_structural_rows = [list(row) for row in (structural_rows or []) if isinstance(row, list)]
    normalized_reference_rows = [list(row) for row in (reference_rows or []) if isinstance(row, list)]
    if not lines or not normalized_structural_rows or not normalized_reference_rows:
        return None, None

    resolved_structural_fields = [
        str(field or "").strip()
        for field in (structural_fields or [])
        if str(field or "").strip()
    ]
    resolved_reference_fields = [
        str(field or "").strip()
        for field in ((reference_fields or structural_fields) or [])
        if str(field or "").strip()
    ]
    if not resolved_structural_fields:
        return None, None

    block_anchor_hints = _build_reparse_block_anchor_hints(
        structural_fields=resolved_structural_fields,
        structural_rows=normalized_structural_rows,
        first_pass_fields=resolved_reference_fields or resolved_structural_fields,
        first_pass_rows=normalized_reference_rows,
    )
    blank_anchor_row_indexes = sorted(
        {
            int(item)
            for item in (block_anchor_hints.get("unmatched_structural_row_indexes") or [])
            if isinstance(item, int) or (isinstance(item, str) and item.isdigit())
        }
    )
    if not blank_anchor_row_indexes:
        blank_anchor_row_indexes = sorted(
            {
                int(item)
                for item in (block_anchor_hints.get("structural_blank_anchor_row_indexes") or [])
                if isinstance(item, int) or (isinstance(item, str) and item.isdigit())
            }
        )
    if not blank_anchor_row_indexes:
        return None, None

    filled_source_rows = _collect_filled_source_rows_from_lines(lines)
    offending_rows = sorted(set(filled_source_rows) & set(blank_anchor_row_indexes))
    if not offending_rows:
        return None, None

    offending_blocks: list[dict[str, Any]] = []
    for block in (block_anchor_hints.get("blocks") or []):
        if not isinstance(block, dict):
            continue
        try:
            row_start = int(block.get("row_start"))
            row_end = int(block.get("row_end"))
        except Exception:
            continue
        block_offending = [idx for idx in offending_rows if row_start <= idx <= row_end]
        if not block_offending:
            continue
        offending_blocks.append(
            {
                "date_mmdd": block.get("date_mmdd"),
                "daypart": block.get("daypart"),
                "row_start": row_start,
                "row_end": row_end,
                "offending_source_rows": block_offending,
            }
        )

    return "sheet_blank_anchor_drift", {
        "quality_issue": "blank_anchor_drift",
        "offending_source_rows": offending_rows[:80],
        "offending_rows": offending_rows[:80],
        "blank_anchor_row_indexes": blank_anchor_row_indexes[:160],
        "filled_source_rows": filled_source_rows[:160],
        "offending_blocks": offending_blocks[:40],
    }


def _realign_quantity_only_rows_to_structural_blank_anchors(
    *,
    rows: list[list[str]],
    template: dict[str, Any],
    structural_fields: list[str] | None,
    structural_rows: list[list[str]] | None,
    reference_rows: list[list[str]] | None,
    reference_fields: list[str] | None = None,
) -> tuple[list[list[str]], dict[str, Any] | None]:
    normalized_rows = [list(row) for row in (rows or []) if isinstance(row, list)]
    normalized_structural_rows = [list(row) for row in (structural_rows or []) if isinstance(row, list)]
    normalized_reference_rows = [list(row) for row in (reference_rows or []) if isinstance(row, list)]
    if not normalized_rows or not normalized_structural_rows or not normalized_reference_rows:
        return normalized_rows, None

    quantity_indexes = _template_quantity_column_indexes(template)
    if not quantity_indexes:
        return normalized_rows, None

    resolved_structural_fields = [
        str(field or "").strip()
        for field in (structural_fields or [])
        if str(field or "").strip()
    ]
    resolved_reference_fields = [
        str(field or "").strip()
        for field in ((reference_fields or structural_fields) or [])
        if str(field or "").strip()
    ]
    if not resolved_structural_fields:
        return normalized_rows, None

    block_anchor_hints = _build_reparse_block_anchor_hints(
        structural_fields=resolved_structural_fields,
        structural_rows=normalized_structural_rows,
        first_pass_fields=resolved_reference_fields or resolved_structural_fields,
        first_pass_rows=normalized_reference_rows,
    )
    unmatched_structural_row_indexes = {
        int(item)
        for item in (block_anchor_hints.get("unmatched_structural_row_indexes") or [])
        if isinstance(item, int) or (isinstance(item, str) and item.isdigit())
    }
    used_structural_blank_fallback = not bool(unmatched_structural_row_indexes)
    if not unmatched_structural_row_indexes:
        unmatched_structural_row_indexes = {
            int(item)
            for item in (block_anchor_hints.get("structural_blank_anchor_row_indexes") or [])
            if isinstance(item, int) or (isinstance(item, str) and item.isdigit())
        }
    blocks = block_anchor_hints.get("blocks") or []
    if not unmatched_structural_row_indexes or not isinstance(blocks, list):
        return normalized_rows, None

    realigned_rows = [list(row) for row in normalized_rows]
    stats: dict[str, Any] = {
        "blocks_evaluated": 0,
        "blocks_realigned": 0,
        "rows_shifted": 0,
        "quantity_cells_shifted": 0,
        "skipped_blocks": [],
    }

    def _row_quantity_vector(row: list[str]) -> dict[int, str]:
        vector: dict[int, str] = {}
        for col_index in quantity_indexes:
            if col_index < 0 or col_index >= len(row):
                continue
            qty = _parse_strict_numeric_cell(row[col_index])
            if qty is None:
                continue
            vector[col_index] = _format_merged_quantity_cell(qty)
        return vector

    def _clear_row_quantities(row: list[str]) -> int:
        cleared_cells = 0
        for col_index in quantity_indexes:
            if col_index < 0 or col_index >= len(row):
                continue
            if row[col_index]:
                row[col_index] = ""
                cleared_cells += 1
        return cleared_cells

    for block in blocks:
        if not isinstance(block, dict):
            continue
        try:
            row_start = int(block.get("row_start"))
            row_end = int(block.get("row_end"))
        except Exception:
            continue
        if row_start < 0 or row_end < row_start:
            continue
        if row_end >= len(realigned_rows):
            continue
        block_indexes = list(range(row_start, row_end + 1))
        blank_anchor_rows = [
            idx for idx in block_indexes if idx in unmatched_structural_row_indexes
        ]
        if not blank_anchor_rows:
            continue
        target_indexes = [idx for idx in block_indexes if idx not in unmatched_structural_row_indexes]
        if not target_indexes:
            continue

        clear_made = False
        for row_index in blank_anchor_rows:
            if row_index < 0 or row_index >= len(realigned_rows):
                continue
            row = realigned_rows[row_index]
            clear_made = bool(clear_made or any(row[col_index] for col_index in quantity_indexes if 0 <= col_index < len(row)))

        candidate_vectors: list[tuple[int, dict[int, str]]] = []
        candidate_pattern: list[bool] = []
        for row_index in block_indexes:
            vector = _row_quantity_vector(realigned_rows[row_index])
            if 0 <= row_index < len(realigned_rows):
                candidate_pattern.append(bool(vector))
            if vector:
                candidate_vectors.append((row_index, vector))
        structural_pattern = [row_index in target_indexes for row_index in block_indexes]
        stats["blocks_evaluated"] = int(stats.get("blocks_evaluated") or 0) + 1
        if candidate_pattern == structural_pattern:
            if not clear_made:
                continue
            cleared_cells = 0
            for row_index in blank_anchor_rows:
                if 0 <= row_index < len(realigned_rows):
                    cleared_cells += _clear_row_quantities(realigned_rows[row_index])
            stats["blocks_realigned"] = int(stats.get("blocks_realigned") or 0) + 1
            stats["rows_shifted"] = int(stats.get("rows_shifted") or 0) + len(blank_anchor_rows)
            stats["quantity_cells_shifted"] = int(stats.get("quantity_cells_shifted") or 0) + cleared_cells
            continue
        if len(candidate_vectors) != len(target_indexes):
            if (
                used_structural_blank_fallback
                and clear_made
                and len(candidate_vectors) > 1
                and len(candidate_vectors) >= len(target_indexes)
            ):
                cleared_cells = 0
                for row_index in blank_anchor_rows:
                    if 0 <= row_index < len(realigned_rows):
                        cleared_cells += _clear_row_quantities(realigned_rows[row_index])
                stats["blocks_realigned"] = int(stats.get("blocks_realigned") or 0) + 1
                stats["rows_shifted"] = int(stats.get("rows_shifted") or 0) + len(blank_anchor_rows)
                stats["quantity_cells_shifted"] = int(stats.get("quantity_cells_shifted") or 0) + cleared_cells
                continue
            skipped = stats.setdefault("skipped_blocks", [])
            if isinstance(skipped, list):
                skipped.append(
                    {
                        "date_mmdd": block.get("date_mmdd"),
                        "daypart": block.get("daypart"),
                        "row_start": row_start,
                        "row_end": row_end,
                        "reason": "filled_count_mismatch",
                        "filled_rows": len(candidate_vectors),
                        "target_rows": len(target_indexes),
                    }
                )
            continue

        for row_index in block_indexes:
            target_row = realigned_rows[row_index]
            for col_index in quantity_indexes:
                if 0 <= col_index < len(target_row):
                    target_row[col_index] = ""

        block_shifted_rows = 0
        block_shifted_cells = 0
        for (source_row_index, quantity_vector), target_row_index in zip(candidate_vectors, target_indexes):
            target_row = realigned_rows[target_row_index]
            for col_index, value in quantity_vector.items():
                while len(target_row) <= col_index:
                    target_row.append("")
                target_row[col_index] = value
                block_shifted_cells += 1
            if source_row_index != target_row_index:
                block_shifted_rows += 1
        if block_shifted_cells <= 0:
            continue
        stats["blocks_realigned"] = int(stats.get("blocks_realigned") or 0) + 1
        stats["rows_shifted"] = int(stats.get("rows_shifted") or 0) + block_shifted_rows
        stats["quantity_cells_shifted"] = int(stats.get("quantity_cells_shifted") or 0) + block_shifted_cells

    if int(stats.get("blocks_realigned") or 0) <= 0:
        return normalized_rows, None
    skipped_blocks = stats.get("skipped_blocks")
    if isinstance(skipped_blocks, list):
        stats["skipped_blocks"] = skipped_blocks[:20]
    return realigned_rows, stats


def _project_quantity_only_rows_onto_structural_rows(
    *,
    rows: list[list[str]],
    template: dict[str, Any],
    structural_fields: list[str] | None,
    structural_rows: list[list[str]] | None,
) -> tuple[list[list[str]], dict[str, Any] | None]:
    normalized_rows = [list(row) for row in (rows or []) if isinstance(row, list)]
    normalized_structural_rows = [list(row) for row in (structural_rows or []) if isinstance(row, list)]
    resolved_fields = [str(field or "").strip() for field in (structural_fields or []) if str(field or "").strip()]
    if not normalized_rows or not normalized_structural_rows or not resolved_fields:
        return normalized_rows, None
    if not _should_project_quantity_rows_to_structural_rows(
        rows=normalized_rows,
        structural_rows=normalized_structural_rows,
        template=template,
    ):
        return normalized_rows, None

    quantity_indexes = _template_quantity_column_indexes(template)
    if not quantity_indexes:
        return normalized_rows, None

    target_width = max(
        len(resolved_fields),
        max((len(row) for row in normalized_structural_rows), default=0),
        max((len(row) for row in normalized_rows), default=0),
    )
    projected_rows: list[list[str]] = []
    rows_with_projected_quantity = 0
    quantity_cells_copied = 0
    padded_blank_rows = 0

    for row_index, structural_row in enumerate(normalized_structural_rows):
        target_row = list(structural_row)
        if len(target_row) < target_width:
            target_row.extend([""] * (target_width - len(target_row)))
        source_row = normalized_rows[row_index] if row_index < len(normalized_rows) else []
        if len(source_row) < target_width:
            source_row = list(source_row) + [""] * (target_width - len(source_row))
        copied_in_row = False
        for col_index in quantity_indexes:
            if col_index < 0 or col_index >= target_width:
                continue
            value = str(source_row[col_index] or "").strip()
            if target_row[col_index] != value:
                target_row[col_index] = value
            if value:
                copied_in_row = True
                quantity_cells_copied += 1
        if copied_in_row:
            rows_with_projected_quantity += 1
        elif row_index >= len(normalized_rows):
            padded_blank_rows += 1
        projected_rows.append(target_row)

    return projected_rows, {
        "projected_row_count": len(projected_rows),
        "source_row_count": len(normalized_rows),
        "structural_row_count": len(normalized_structural_rows),
        "rows_with_projected_quantity": rows_with_projected_quantity,
        "quantity_cells_copied": quantity_cells_copied,
        "padded_blank_rows": padded_blank_rows,
    }


def _validate_reparse_date_anchor_stability(
    *,
    previous_lines: list[dict[str, Any]] | None,
    candidate_lines: list[dict[str, Any]] | None,
) -> tuple[str | None, dict[str, Any] | None]:
    previous_dates = sorted(_collect_line_dates_for_position_scope(previous_lines))
    candidate_dates = sorted(_collect_line_dates_for_position_scope(candidate_lines))
    if len(previous_dates) < 2 or len(candidate_dates) < 2:
        return None, None

    previous_set = set(previous_dates)
    candidate_set = set(candidate_dates)
    overlap_dates = sorted(previous_set & candidate_set)
    overlap_prev_ratio = len(overlap_dates) / len(previous_set) if previous_set else 0.0
    overlap_candidate_ratio = len(overlap_dates) / len(candidate_set) if candidate_set else 0.0

    previous_start = previous_dates[0]
    previous_end = previous_dates[-1]
    candidate_start = candidate_dates[0]
    candidate_end = candidate_dates[-1]
    start_shift_days = abs((candidate_start - previous_start).days)
    end_shift_days = abs((candidate_end - previous_end).days)

    severe_shift = start_shift_days > 1 or end_shift_days > 1
    low_overlap = overlap_prev_ratio < 0.5 and overlap_candidate_ratio < 0.5
    if severe_shift and low_overlap:
        return "sheet_date_anchor_drift", {
            "previous_dates": [item.isoformat() for item in previous_dates],
            "candidate_dates": [item.isoformat() for item in candidate_dates],
            "overlap_dates": [item.isoformat() for item in overlap_dates],
            "overlap_prev_ratio": round(overlap_prev_ratio, 4),
            "overlap_candidate_ratio": round(overlap_candidate_ratio, 4),
            "start_shift_days": start_shift_days,
            "end_shift_days": end_shift_days,
        }

    return None, None


def _parse_date_value(value):
    if value is None:
        return None
    if isinstance(value, date):
        try:
            if pd.isna(value):
                return None
        except Exception:
            pass
        return value
    try:
        parsed = pd.to_datetime(value)
        if pd.isna(parsed):
            return None
        parsed_date = parsed.date()
        if pd.isna(parsed_date):
            return None
        return parsed_date
    except Exception:
        return None


def _normalize_received_at(value):
    if hasattr(value, "isoformat"):
        return value
    try:
        return pd.to_datetime(value)
    except Exception:
        return pd.Timestamp.utcnow()


def _derive_ingest_week_hint(payload: IngestEmailPayload) -> str | None:
    return require_explicit_ingest_week(payload.week_hint)


def _is_split_page_ingest_message(message_id: str | None) -> bool:
    token = str(message_id or "").strip()
    return ":split:" in token


def _serialize_ingest_existing_order_preview(
    session,
    order: Order,
    *,
    match_reason: str,
    effective_week_hint: str | None,
    incoming_message_id: str | None,
    incoming_received_at,
) -> dict[str, Any]:
    current_document = None
    if str(order.current_document_id or "").strip():
        current_document = session.get(OrderDocument, order.current_document_id)
    prior_document = None
    superseded_ids = order.superseded_document_ids or []
    if superseded_ids:
        prior_document = session.get(OrderDocument, str(superseded_ids[-1] or "").strip())
    normalized_incoming_received_at = _normalize_received_at(incoming_received_at)
    normalized_week_code = _resolve_system_managed_order_week_code(order, effective_week_hint) or order.week_code
    return {
        "match_reason": match_reason,
        "order_id": order.id,
        "facility_code": order.facility_code,
        "week_code": normalized_week_code,
        "week_label": _format_sheet_week_label(normalized_week_code) or _to_sheet_month_id(normalized_week_code),
        "status": order.status,
        "line_count": len(order.lines or []),
        "current_document_id": order.current_document_id,
        "current_message_id": order.message_id,
        "superseded_document_count": len(superseded_ids),
        "existing_document": {
            "id": current_document.id if current_document else order.current_document_id,
            "storage_uri": current_document.storage_uri if current_document else order.document_uri,
            "message_id": current_document.source_email_id if current_document else order.message_id,
            "received_at": current_document.received_at.isoformat() if current_document and current_document.received_at else None,
        },
        "prior_document": {
            "id": prior_document.id,
            "storage_uri": prior_document.storage_uri,
            "message_id": prior_document.source_email_id,
            "received_at": prior_document.received_at.isoformat() if prior_document.received_at else None,
        }
        if prior_document
        else None,
        "incoming_document": {
            "message_id": str(incoming_message_id or "").strip() or None,
            "received_at": normalized_incoming_received_at.isoformat()
            if normalized_incoming_received_at is not None
            else None,
        },
        "will_supersede": True,
    }


def _find_existing_order_for_ingest(
    session,
    payload: IngestEmailPayload,
    *,
    effective_week_hint: str | None = None,
) -> tuple[Order | None, str | None, str | None]:
    normalized_week_hint = effective_week_hint if effective_week_hint is not None else _derive_ingest_week_hint(payload)
    if payload.order_id:
        explicit_order = session.get(Order, payload.order_id)
        if explicit_order is None:
            raise ValueError("ocr_order_input_missing")
        return explicit_order, "explicit_order_id", normalized_week_hint
    existing_for_message = session.execute(
        select(Order).where(Order.message_id == payload.message_id)
    ).scalar_one_or_none()
    if existing_for_message is not None:
        return existing_for_message, "message_id", normalized_week_hint
    if _is_split_page_ingest_message(payload.message_id):
        return None, None, normalized_week_hint
    if payload.facility_hint and normalized_week_hint:
        existing_for_facility_week = session.execute(
            select(Order).where(
                Order.facility_code == payload.facility_hint,
                Order.week_code == normalized_week_hint,
            )
        ).scalar_one_or_none()
        if existing_for_facility_week is not None:
            return existing_for_facility_week, "facility_week", normalized_week_hint
    return None, None, normalized_week_hint


def preview_existing_order_for_ingest(payload: IngestEmailPayload) -> dict[str, Any] | None:
    with session_scope() as session:
        existing, match_reason, effective_week_hint = _find_existing_order_for_ingest(session, payload)
        if existing is None or not match_reason:
            return None
        return _serialize_ingest_existing_order_preview(
            session,
            existing,
            match_reason=match_reason,
            effective_week_hint=effective_week_hint,
            incoming_message_id=payload.message_id,
            incoming_received_at=payload.received_at,
        )


def require_existing_ingest_selection(session, payload: IngestEmailPayload):
    from src.services.ingest_facility_selection_service import validate_selection, require_order_selection
    selection = validate_selection(payload.facility_selection, payload.facility_hint, payload.week_hint)
    existing, _, _ = _find_existing_order_for_ingest(session, payload)
    if existing is not None:
        existing = session.get(Order, existing.id, populate_existing=True, with_for_update=True)
        if existing is None:
            raise ValueError("ingest_order_selection_target_changed")
        require_order_selection(session, existing, selection)


def _snapshot_order_lines(session, order_id: str) -> list[dict[str, Any]]:
    rows = session.execute(
        select(OrderLine)
        .where(OrderLine.order_id == order_id)
        .order_by(OrderLine.date, OrderLine.daypart, OrderLine.id)
    ).scalars().all()
    return [
        {
            "id": line.id,
            "line_id": line.line_id,
            "date": line.date.isoformat() if line.date else None,
            "daypart": line.daypart,
            "menu_name": line.menu_name,
            "diet_type": line.diet_type,
            "area_id": line.area_id,
            "bag_type": line.bag_type,
            "quantity_original": line.quantity_original,
            "quantity_corrected": line.quantity_corrected,
            "change_note": line.change_note,
        }
        for line in rows
    ]


def _next_order_version_no(session, order_id: str) -> int:
    current = session.execute(
        select(func.max(OrderVersion.version_no)).where(OrderVersion.order_id == order_id)
    ).scalar()
    return int(current or 0) + 1


def _ensure_legacy_current_order_version(session, order: Order) -> None:
    if not str(order.current_document_id or "").strip():
        return
    existing = session.execute(
        select(OrderVersion.id).where(OrderVersion.order_id == order.id).limit(1)
    ).scalar()
    if existing:
        return
    session.add(
        OrderVersion(
            id=_make_order_version_id(),
            order_id=order.id,
            version_no=1,
            document_id=order.current_document_id,
            message_id=order.message_id,
            storage_uri=order.document_uri,
            facility_code=order.facility_code,
            week_code=order.week_code,
            received_at=_normalize_received_at(order.received_at),
            line_snapshot=_snapshot_order_lines(session, order.id),
            is_current=True,
            created_at=datetime.utcnow(),
        )
    )
    session.flush()


def _record_current_order_version(session, order: Order, document: OrderDocument) -> None:
    existing = session.execute(
        select(OrderVersion).where(OrderVersion.document_id == document.id)
    ).scalars().first()
    if existing is not None:
        existing.order_id = order.id
        existing.message_id = document.source_email_id
        existing.storage_uri = document.storage_uri
        existing.facility_code = order.facility_code
        existing.week_code = order.week_code
        existing.received_at = _normalize_received_at(document.received_at)
        existing.line_snapshot = _snapshot_order_lines(session, order.id)
        existing.is_current = True
    else:
        session.execute(
            update(OrderVersion)
            .where(OrderVersion.order_id == order.id)
            .values(is_current=False)
        )
        session.add(
            OrderVersion(
                id=_make_order_version_id(),
                order_id=order.id,
                version_no=_next_order_version_no(session, order.id),
                document_id=document.id,
                message_id=document.source_email_id,
                storage_uri=document.storage_uri,
                facility_code=order.facility_code,
                week_code=order.week_code,
                received_at=_normalize_received_at(document.received_at),
                line_snapshot=_snapshot_order_lines(session, order.id),
                is_current=True,
                created_at=datetime.utcnow(),
            )
        )
    session.flush()


def _resolve_order_document_selection(
    session,
    order: Order,
    selected_document_id: str | None = None,
) -> tuple[str | None, dict[str, Any]]:
    def _received_at_value(value: Any) -> str | None:
        return value.isoformat() if hasattr(value, "isoformat") else (str(value).strip() or None if value else None)

    normalized_document_id = str(selected_document_id or "").strip()
    if normalized_document_id:
        versions = session.execute(
            select(OrderVersion).where(
                OrderVersion.order_id == order.id,
                OrderVersion.document_id == normalized_document_id,
            )
        ).scalars().all()
        if len(versions) != 1:
            return None, {"error": "document_ambiguous" if versions else "document_not_found"}
        version = versions[0]
        if not version:
            return None, {"error": "document_not_found"}
        return str(version.storage_uri or "").strip() or None, {
            "selected_document_id": str(version.document_id or "").strip() or None,
            "selected_document_version": version.version_no,
            "selected_document_is_current": bool(version.is_current),
            "selected_document_received_at": _received_at_value(version.received_at),
            "selected_version_input": deepcopy({column.key: getattr(version, column.key) for column in version.__table__.columns}),
        }
    current_versions = session.execute(
        select(OrderVersion).where(
            OrderVersion.order_id == order.id,
            OrderVersion.is_current.is_(True),
        )
    ).scalars().all()
    if len(current_versions) > 1:
        return None, {"error": "document_ambiguous"}
    current_version = current_versions[0] if current_versions else None
    if current_version:
        return str(current_version.storage_uri or "").strip() or None, {
            "selected_document_id": str(current_version.document_id or "").strip() or None,
            "selected_document_version": current_version.version_no,
            "selected_document_is_current": bool(current_version.is_current),
            "selected_document_received_at": _received_at_value(current_version.received_at),
            "selected_version_input": deepcopy({column.key: getattr(current_version, column.key) for column in current_version.__table__.columns}),
        }
    return str(order.document_uri or "").strip() or None, {
        "selected_document_id": str(order.current_document_id or "").strip() or None,
        "selected_document_version": None,
        "selected_document_is_current": True,
        "selected_document_received_at": _received_at_value(order.received_at),
    }


def _capture_nonworkflow_order_execution(job_id: str, order_id: str, selected_document_id: str | None) -> dict[str, Any]:
    with session_scope() as session:
        order = session.get(Order, order_id)
        if order is None:
            raise ValueError("order_not_found")
        input_reference, input_error = _resolve_order_document_selection(session, order, selected_document_id)
        if not input_reference:
            raise ValueError(input_error.get("error") or "ocr_input_required")
        expected_order = deepcopy({column.key: getattr(order, column.key) for column in order.__table__.columns})
    return capture_nonworkflow_execution(
        job_id, order_id=order_id, input_reference=input_reference, expected_order=expected_order,
        selected_version_input=input_error.get("selected_version_input"),
    )


def _captured_order_document_selection(session, order, selected_document_id):
    boundary = current_nonworkflow_execution()
    job_id = _workflow_ocr_job_id.get() or (boundary or {}).get("job_id")
    if not job_id or not _workflow_attempt_write_fence(session, job_id, order.id):
        return None, {"error": "selected_document_input_changed"}
    if boundary is not None:
        if boundary.get("order_id") != order.id:
            return None, {"error": "selected_document_input_changed"}
        selected = boundary.get("selected_version_input")
        uri = boundary.get("input_reference")
    else:
        job = session.get(OcrJob, job_id)
        selected = (job.metrics or {}).get("selected_version_input") if job is not None else None
        uri = job.input_reference if job is not None else None
    if selected_document_id and (not selected or selected.get("document_id") != selected_document_id):
        return None, {"error": "selected_document_input_missing"}
    if selected is not None:
        return selected["storage_uri"], {
            "selected_document_id": selected["document_id"], "selected_document_version": selected["version_no"],
            "selected_document_is_current": selected["is_current"],
            "selected_document_received_at": selected["received_at"],
        }
    receipt = processing_start_pdf_receipt()
    if not isinstance(receipt, dict) or receipt.get("order_id") != order.id or not uri:
        return None, {"error": "selected_document_input_missing"}
    original = processing_start_read_input()
    document = original.get("document")
    if not isinstance(document, dict) or document.get("id") != receipt.get("document_id") or document.get("storage_uri") != uri:
        return None, {"error": "selected_document_input_changed"}
    return uri, {"selected_document_id": document["id"], "selected_document_version": None}


def _captured_reparse_read_input(order_id, *, write_session=None):
    job_id = _workflow_ocr_job_id.get() or (current_nonworkflow_execution() or {}).get("job_id")
    with (nullcontext(write_session) if write_session is not None else session_scope()) as session:
        if not job_id or not _workflow_attempt_write_fence(session, job_id, order_id):
            return None
        boundary = current_nonworkflow_execution()
        if boundary is not None:
            if boundary.get("order_id") != order_id:
                return None
            return processing_start_read_input()
        job = session.get(OcrJob, job_id)
        return deepcopy((job.metrics or {}).get("reparse_read_input")) if job is not None else None


def _resolve_reparse_own_week(*, captured_week, received_at, lines, own_payload):
    return _normalize_sheet_week_value(captured_week)


def _persist_ingest_pipeline_evidence(session: Any, order: Order, pipeline_result: dict[str, Any], document_status: str) -> dict[str, Any]:
    execution_input = current_nonworkflow_execution()
    if execution_input is None:
        raise ValueError("ocr_execution_input_required")
    persistable = _classify_owned_evidence_payload(pipeline_result).get("persistable")
    evidence = persist_ocr_evidence_run(
        order.id, {**pipeline_result, "first_pass_result_applied": document_status == "success"}, schema_version="v1_legacy",
        producer_version="ocr_pipeline_ingest", source="ocr-ingest-first-pass",
        status="ready" if persistable and document_status == "success" else "diagnostic_only",
        result_disposition="pipeline_result" if document_status == "success" else "rejected",
        workflow_job_id=execution_input["job_id"], refresh_workflow=False,
        write_session=session,
    )
    if not isinstance(evidence, dict) or not evidence.get("id"):
        raise ValueError("first_pass_own_evidence_persist_failed")
    return evidence


def _complete_first_pass_job_in_session(session, order, document, execution_input, evidence, *, applied):
    if not _workflow_attempt_write_fence(session, execution_input["job_id"], order.id):
        raise ValueError("ocr_execution_owner_changed")
    job = session.get(OcrJob, execution_input["job_id"])
    if job is None or not evidence.get("id"):
        raise ValueError("first_pass_own_evidence_persist_failed")
    job.status = "done" if applied else "failed"
    job.error_message = None if applied else "first_pass_output_rejected"
    job.updated_at = datetime.utcnow()
    job.metrics = {
        **(job.metrics or {}), "evidence_run_id": evidence["id"], "adopted": False,
        "processing_stage": "evidence_ready" if applied else "rejected_review_saved",
        "result_state": "evidence_ready" if applied else "review_required",
    }
    receipt = {
        "job_id": job.id, "execution_id": execution_input["execution_id"],
        "document_id": document.id, "evidence_run_id": evidence["id"],
        "status": job.status, "result_state": job.metrics["result_state"],
    }
    job.metrics = {**job.metrics, "first_pass_terminal_receipt": deepcopy(receipt)}
    from src.services.ingest_delivery_successor_service import accept
    accept(session, job, execution_input, evidence, receipt, order)
    return receipt


def create_order_from_ingest(
    payload: IngestEmailPayload,
    lines: Optional[list[dict]] = None,
    ocr_attempts: int = 1,
    document_status: str = "success",
    error_message: Optional[str] = None,
    execution_input: dict[str, Any] | None = None,
    pipeline_result: dict[str, Any] | None = None,
    registration_job_id: str | None = None,
    save_result_cache: bool = False,
    mapping_policy: dict[str, Any] | None = None,
):
    require_explicit_ingest_week(payload.week_hint)
    from src.services.ingest_facility_selection_service import (
        validate_selection, require_order_selection, materialize_selection,
    )
    selection = validate_selection(payload.facility_selection, payload.facility_hint, payload.week_hint)
    if lines is not None and not isinstance(mapping_policy, dict):
        raise ValueError("first_pass_mapping_policy_missing")
    if lines is not None and (
        not isinstance(pipeline_result, dict)
        or (pipeline_result.get("_first_pass_recognizer") or {}).get("mapped_lines") != [
            {key: value.isoformat() if isinstance(value, (datetime, date)) else value for key, value in line.items()}
            for line in lines
        ]
    ):
        raise ValueError("first_pass_recognizer_lines_mismatch")
    if isinstance(pipeline_result, dict) and lines is None and document_status == "success":
        document_status = "error"
        error_message = error_message or "first_pass_output_not_applied"
    with session_scope() as session:
        received_at = _normalize_received_at(payload.received_at)
        from src.services.ingest_job_service import current_ingest_lease, lock_ingest_lease
        ingest_lease = execution_input.get("ingest_lease") if execution_input is not None else current_ingest_lease()
        if ingest_lease is not None and not lock_ingest_lease(session, ingest_lease):
            raise ValueError("ingest_attempt_changed")
        if ingest_lease is None or (ingest_lease.get("payload") or {}).get("facility_selection") != selection:
            raise ValueError("ingest_facility_selection_owner_changed")
        effective_week_hint = _derive_ingest_week_hint(payload)
        if execution_input is None and lines is None:
            # Serialize the existing registration keys before a new parent exists.
            keys = ["ingest-message:" + payload.message_id]
            if payload.facility_hint and effective_week_hint and not _is_split_page_ingest_message(payload.message_id):
                keys.append("ingest-facility-week:" + payload.facility_hint + ":" + effective_week_hint)
            if session.bind.dialect.name == "postgresql":
                for key in sorted(keys):
                    session.execute(select(func.pg_advisory_xact_lock(func.hashtextextended(key, 0))))
            elif session.bind.dialect.name == "sqlite":
                if payload.uploaded_pdf_id:
                    claim = session.execute(update(UploadedPdf).where(UploadedPdf.id == payload.uploaded_pdf_id).values(message_id=UploadedPdf.message_id))
                elif registration_job_id:
                    claim = session.execute(update(OcrJob).where(OcrJob.id == registration_job_id).values(status=OcrJob.status))
                else:
                    raise ValueError("ingest_registration_source_required")
                if claim.rowcount != 1:
                    raise ValueError("ingest_registration_source_missing")
        existing, match_reason, effective_week_hint = _find_existing_order_for_ingest(
            session, payload, effective_week_hint=effective_week_hint,
        )
        if existing is not None:
            require_order_selection(session, existing, selection)
            selected_projection_id = existing.template_version_id
        else:
            if execution_input is not None:
                raise ValueError("ingest_registered_order_missing")
            selected_projection_id = materialize_selection(session, selection)
        if ingest_lease is not None and payload.order_id is not None and (existing is None or existing.id != payload.order_id):
            raise ValueError("ingest_registered_order_changed")
        if execution_input is None and existing is not None:
            if lock_order_execution_input(session, existing.id) is None:
                raise ValueError("ocr_order_input_missing")
        if lines is not None and execution_input is None:
            raise ValueError("ocr_execution_input_required")
        if lines is not None and not isinstance(pipeline_result, dict):
            raise ValueError("first_pass_pipeline_result_missing")
        if execution_input is not None:
            if current_nonworkflow_execution() is not execution_input:
                raise ValueError("ocr_execution_input_required")
            target = existing
            if target is not None:
                if not _workflow_attempt_write_fence(session, execution_input["job_id"], target.id):
                    raise ValueError("ocr_execution_owner_changed")
            elif execution_input.get("order_id") is not None or not lock_nonworkflow_execution_job(session, execution_input):
                raise ValueError("ocr_execution_owner_changed")
        existing_document = (
            session.execute(
                select(OrderDocument)
                .where(OrderDocument.source_email_id == payload.message_id)
                .order_by(OrderDocument.received_at.desc(), OrderDocument.id.desc())
            )
            .scalars()
            .first()
        )
        continuation_document = None
        if ingest_lease is not None and payload.order_document_id is not None and (existing_document is None or existing_document.id != payload.order_document_id):
            raise ValueError("ingest_registered_source_changed")
        terminal_without_result = execution_input is not None and pipeline_result is None and document_status in {"skipped", "error"}
        if terminal_without_result and lines is not None:
            raise ValueError("non_ocr_terminal_result_invalid")
        if existing_document is not None and execution_input is not None and (isinstance(pipeline_result, dict) or terminal_without_result):
            captured_document = execution_input["orders"][existing.id].get("document") if existing is not None else None
            if (
                existing is None or not isinstance(captured_document, dict)
                or captured_document.get("id") != existing_document.id
                or existing.current_document_id != existing_document.id
                or captured_document.get("storage_uri") != payload.pdf_uri
                or captured_document.get("source_email_id") != payload.message_id
            ):
                raise ValueError("first_pass_registered_input_changed")
            if captured_document.get("status") != "processing":
                raise ValueError("first_pass_document_already_completed")
            continuation_document = existing_document
        if existing_document is not None and continuation_document is None:
            existing_order = existing
            if existing_order is not None:
                historical_document_ids = {
                    str(document_id or "").strip()
                    for document_id in (existing_order.superseded_document_ids or [])
                    if str(document_id or "").strip()
                }
                current_document_id = str(existing_order.current_document_id or "").strip()
                if existing_document.id == current_document_id or existing_document.id in historical_document_ids:
                    needs_context_update = (
                        (not str(existing_order.week_code or "").strip() and str(effective_week_hint or "").strip())
                        or (not str(existing_order.facility_code or "").strip() and str(payload.facility_hint or "").strip())
                    )
                    if needs_context_update:
                        pass
                    else:
                        if ingest_lease is not None and execution_input is None:
                            if existing_document.id != current_document_id or existing_document.storage_uri != payload.pdf_uri:
                                raise ValueError("ingest_registered_source_changed")
                            existing_document.status = "processing"
                            existing_document.error_message = "ocr_pending"
                        _ensure_legacy_current_order_version(session, existing_order)
                        if existing_document.id == current_document_id:
                            _record_current_order_version(session, existing_order, existing_document)
                        if execution_input is not None:
                            advance_nonworkflow_order_input(session, execution_input, existing_order)
                        serialized = serialize_order(existing_order, allow_unresolved_menu_amount=True)
                        serialized["ingest_registration_receipt"] = {"order_id": existing_order.id, "document_id": existing_document.id}
                        if isinstance(pipeline_result, dict):
                            serialized["first_pass_evidence"] = _persist_ingest_pipeline_evidence(
                                session, existing_order, pipeline_result, document_status,
                            )
                        return serialized
        doc_id = continuation_document.id if continuation_document is not None else _make_document_id()
        document = continuation_document if continuation_document is not None else OrderDocument(
            id=doc_id,
            facility_code=payload.facility_hint,
            week_code=effective_week_hint,
            storage_uri=payload.pdf_uri,
            source_email_id=payload.message_id,
            received_at=received_at,
            ocr_attempts=ocr_attempts,
            status=document_status,
            error_message=error_message,
        )
        if continuation_document is not None:
            document.ocr_attempts = ocr_attempts
            document.status = document_status
            document.error_message = error_message
            order = existing
            if not terminal_without_result:
                order.facility_code = payload.facility_hint
                _apply_system_managed_order_week_code(order, effective_week_hint)
        else:
            session.add(document)
        if existing and continuation_document is None:
            order = existing
            _ensure_legacy_current_order_version(session, order)
            if order.current_document_id:
                prior = order.superseded_document_ids or []
                order.superseded_document_ids = prior + [order.current_document_id]
            order.facility_code = payload.facility_hint
            _apply_system_managed_order_week_code(order, effective_week_hint)
            order.document_uri = payload.pdf_uri
            order.message_id = payload.message_id
            order.received_at = received_at
            order.status = "要確認"
            order.current_document_id = doc_id
            order.archived_at = None
            order.archived_by = None
            logger.info("Order superseded and updated", order_id=order.id, match_reason=match_reason)
        elif existing is None:
            order = Order(
                id=_make_order_id(),
                template_version_id=selected_projection_id,
                facility_code=payload.facility_hint,
                week_code=effective_week_hint,
                document_uri=payload.pdf_uri,
                message_id=payload.message_id,
                received_at=received_at,
                status="要確認",
                current_document_id=doc_id,
            )
            session.add(order)
            if execution_input is not None:
                execution_input.setdefault("created_order_ids", []).append(order.id)
            logger.info("Order created", order_id=order.id)
        session.flush()
        if lines is not None:
            policy = mapping_policy
            min_ratio = float(policy.get("menu_match_min_ratio", 0.72))
            week_id = effective_week_hint
            if week_id:
                lines = _apply_menu_matching(lines, week_id, payload.facility_hint, min_ratio, session=session)
            lines = _ensure_unique_line_ids(lines)
            session.execute(delete(OrderLine).where(OrderLine.order_id == order.id))
            for line in lines:
                session.add(
                    OrderLine(
                        id=line.get("id") or _make_line_id(),
                        order_id=order.id,
                        line_id=line.get("line_id"),
                        date=_parse_date_value(line.get("date")),
                        daypart=line.get("daypart"),
                        menu_name=line.get("menu_name"),
                        diet_type=line.get("diet_type"),
                        area_id=line.get("area_id"),
                        bag_type=line.get("bag_type"),
                        quantity_original=line.get("quantity_original"),
                        quantity_corrected=line.get("quantity_corrected"),
                        change_note=line.get("change_note"),
                    )
                )
            order.lines_updated_at = datetime.utcnow()
        session.flush()
        _record_current_order_version(session, order, document)
        session.refresh(order)
        if execution_input is not None:
            advance_nonworkflow_order_input(session, execution_input, order)
            current_state = session.get(OrderCurrentState, order.id)
            if current_state is not None:
                session.delete(current_state)
        serialized = serialize_order(order, allow_unresolved_menu_amount=True)
        serialized["ingest_registration_receipt"] = {"order_id": order.id, "document_id": document.id}
        serialized["first_pass_result_applied"] = lines is not None and document_status == "success"
        if terminal_without_result:
            job = session.get(OcrJob, execution_input["job_id"])
            if job is None:
                raise ValueError("ocr_execution_owner_changed")
            skipped = document_status == "skipped"
            job.status = "done" if skipped else "failed"
            job.error_message = None if skipped else error_message
            job.updated_at = datetime.utcnow()
            job.metrics = {
                **(job.metrics or {}), "processing_stage": "registration_skipped" if skipped else "hard_failed",
                "result_state": "skipped" if skipped else "hard_failed", "adopted": False,
                "skip_reason": error_message if skipped else None,
            }
            serialized["non_ocr_terminal_receipt"] = {
                "job_id": job.id, "execution_id": execution_input["execution_id"],
                "document_id": document.id, "status": job.status,
                "result_state": "skipped" if skipped else "hard_failed",
            }
        if isinstance(pipeline_result, dict):
            serialized["first_pass_evidence"] = _persist_ingest_pipeline_evidence(
                session, order, pipeline_result, document_status,
            )
            evidence = serialized["first_pass_evidence"]
            applied = serialized["first_pass_result_applied"] and evidence.get("selectable") is True
            if save_result_cache and applied:
                cache_result = _save_order_ocr_cache(
                    order.id, {**pipeline_result, "_ocr_execution": deepcopy(evidence["payload_json"]["_ocr_execution"])},
                    job_id=execution_input["job_id"], persist_evidence=False,
                    refresh_workflow=False, write_session=session,
                )
                if cache_result is None:
                    raise ValueError("first_pass_cache_persist_failed")
            serialized["first_pass_terminal_receipt"] = _complete_first_pass_job_in_session(
                session, order, document, execution_input, evidence, applied=applied,
            )
    _invalidate_orders_cache()
    if execution_input is None:
        _invalidate_current_sheet_state_after_order_lines_write(serialized["id"])
    try:
        workflow_state_service.refresh_workflow_state(serialized["id"])
    except Exception as exc:  # noqa: BLE001
        logger.warning("Workflow state refresh failed after ingest create", order_id=serialized.get("id"), error=str(exc))
    return serialized


_orders_cache_lock = threading.Lock()
_orders_cache: dict[str, tuple[float, list[dict]]] = {}


def _invalidate_orders_cache() -> None:
    with _orders_cache_lock:
        _orders_cache.clear()


def invalidate_orders_cache() -> None:
    _invalidate_orders_cache()


def _invalidate_current_sheet_state_after_order_lines_write(order_id: str) -> None:
    normalized_order_id = str(order_id or "").strip()
    if not normalized_order_id:
        return
    order_current_state_service.delete_current_state(normalized_order_id)


def _normalize_order_list_limit(limit: int | None) -> int | None:
    if limit is None:
        return None
    try:
        normalized = int(limit)
    except (TypeError, ValueError):
        return None
    if normalized <= 0:
        return None
    return min(normalized, 1000)


def _parse_order_list_cursor_received_at(value: str | None) -> datetime | None:
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is not None:
        return parsed.astimezone(timezone.utc).replace(tzinfo=None)
    return parsed


def _normalize_order_list_cursor_id(value: str | None) -> str:
    return str(value or "").strip()


def _fetch_orders(
    status: Optional[str],
    *,
    include_archived: bool = True,
    limit: int | None = None,
    before_received_at: str | None = None,
    before_id: str | None = None,
) -> list[dict]:
    normalized_limit = _normalize_order_list_limit(limit)
    cursor_received_at = _parse_order_list_cursor_received_at(before_received_at)
    cursor_id = _normalize_order_list_cursor_id(before_id)
    with session_scope() as session:
        query = select(
            Order.id,
            Order.facility_code,
            Order.week_code,
            Order.status,
            Order.document_uri,
            Order.message_id,
            Order.received_at,
            Order.current_document_id,
            Order.superseded_document_ids,
            Order.lines_updated_at,
            Order.archived_at,
            Order.archived_by,
        )
        if status:
            query = query.where(Order.status == status)
        if not include_archived:
            query = query.where(Order.archived_at.is_(None))
        if cursor_received_at is not None:
            if cursor_id:
                query = query.where(
                    or_(
                        Order.received_at < cursor_received_at,
                        (Order.received_at == cursor_received_at) & (Order.id < cursor_id),
                    )
                )
            else:
                query = query.where(Order.received_at < cursor_received_at)
        query = query.order_by(Order.received_at.desc(), Order.id.desc())
        if normalized_limit is not None:
            query = query.limit(normalized_limit)
        rows = session.execute(query).mappings().all()
        payloads: list[dict[str, Any]] = []
        for row in rows:
            week_code = row["week_code"]
            week_month_id = _to_sheet_month_id(week_code)
            week_value = _normalize_sheet_week_value(week_code) or week_month_id
            week_label = _format_sheet_week_label(week_code) or week_month_id
            archived_at = row["archived_at"]
            payloads.append(
                {
                    "id": row["id"],
                    "ocr_job_id": f"OCR-{row['id']}",
                    "facility": row["facility_code"],
                    "week": week_month_id,
                    "week_value": week_value,
                    "week_label": week_label,
                    "status": row["status"],
                    "document": row["document_uri"],
                    "message_id": row["message_id"],
                    "received_at": row["received_at"],
                    "document_id": row["current_document_id"],
                    "superseded_document_ids": row["superseded_document_ids"] or [],
                    "lines_updated_at": row["lines_updated_at"],
                    "archived_at": archived_at,
                    "archived_by": row["archived_by"],
                    "is_archived": bool(archived_at),
                }
            )
        if not status or status == "アップロード済み":
            upload_query = select(
                UploadedPdf.id,
                UploadedPdf.message_id,
                UploadedPdf.original_filename,
                UploadedPdf.storage_uri,
                UploadedPdf.received_at,
                UploadedPdf.facility_hint,
                UploadedPdf.week_hint,
                UploadedPdf.facility_name,
                UploadedPdf.status,
                UploadedPdf.current_stage,
                UploadedPdf.current_order_id,
                UploadedPdf.current_document_id,
                UploadedPdf.last_error_code,
                UploadedPdf.last_error_message,
            ).where(UploadedPdf.current_order_id.is_(None))
            if cursor_received_at is not None:
                if cursor_id:
                    upload_cursor_id = cursor_id.removeprefix("UPLOAD-")
                    upload_query = upload_query.where(
                        or_(
                            UploadedPdf.received_at < cursor_received_at,
                            (UploadedPdf.received_at == cursor_received_at) & (UploadedPdf.id < upload_cursor_id),
                        )
                    )
                else:
                    upload_query = upload_query.where(UploadedPdf.received_at < cursor_received_at)
            uploaded_rows = (
                session.execute(
                    upload_query.order_by(UploadedPdf.received_at.desc(), UploadedPdf.id.desc()).limit(
                        min(200, normalized_limit) if normalized_limit is not None else 200
                    )
                )
                .mappings()
                .all()
            )
            for upload in uploaded_rows:
                upload_status = str(upload["status"] or "").strip().lower()
                if upload_status == "completed" and upload["current_document_id"]:
                    continue
                week_hint = str(upload["week_hint"] or "").strip()
                week_month_id = _to_sheet_month_id(week_hint)
                week_value = _normalize_sheet_week_value(week_hint) or week_month_id or week_hint
                week_label = _format_sheet_week_label(week_hint) or week_month_id or week_hint
                stage = str(upload["current_stage"] or "uploaded").strip() or "uploaded"
                headline = "PDFアップロード済み"
                if stage == "ingest_running":
                    headline = "取り込み処理中"
                elif upload_status in {"retry_wait", "error"}:
                    headline = "取り込み要確認"
                payloads.append(
                    {
                        "id": f"UPLOAD-{upload['id']}",
                        "uploaded_pdf_id": upload["id"],
                        "source_kind": "uploaded_pdf",
                        "ocr_job_id": None,
                        "facility": upload["facility_hint"],
                        "facility_name": upload["facility_name"],
                        "week": week_month_id,
                        "week_value": week_value,
                        "week_label": week_label,
                        "status": "アップロード済み",
                        "document": upload["storage_uri"],
                        "message_id": upload["message_id"],
                        "received_at": upload["received_at"],
                        "document_id": upload["current_document_id"],
                        "superseded_document_ids": [],
                        "lines_updated_at": None,
                        "archived_at": None,
                        "archived_by": None,
                        "is_archived": False,
                        "workflow_state": {
                            "state": "uploaded",
                            "headline": headline,
                            "primary_action": "取り込み状況を確認",
                            "blockers_json": [],
                            "warnings_json": [upload["last_error_code"]] if upload["last_error_code"] else [],
                        },
                        "upload_stage": stage,
                        "upload_status": upload["status"],
                        "upload_error": upload["last_error_message"],
                        "original_filename": upload["original_filename"],
                    }
                )
        payloads.sort(key=_order_list_sort_key, reverse=True)
        if normalized_limit is not None:
            payloads = payloads[:normalized_limit]
        return payloads


def build_order_list_cursor(orders: list[dict]) -> dict[str, str] | None:
    if not orders:
        return None
    last = orders[-1]
    received_at = last.get("received_at")
    order_id = str(last.get("id") or "").strip()
    if not order_id:
        raise ValueError("order_list_cursor_identity_required")
    if not isinstance(received_at, datetime):
        if received_at is None or isinstance(received_at, str) and not received_at.strip():
            raise ValueError("order_list_cursor_datetime_required")
        if not isinstance(received_at, str):
            raise ValueError("order_list_cursor_datetime_invalid")
        raw_received_at = received_at.strip()
        try:
            date.fromisoformat(raw_received_at)
        except ValueError:
            pass
        else:
            raise ValueError("order_list_cursor_datetime_invalid")
        try:
            received_at = datetime.fromisoformat(raw_received_at.replace("Z", "+00:00"))
        except ValueError as exc:
            raise ValueError("order_list_cursor_datetime_invalid") from exc
    return {"received_at": received_at.isoformat(), "id": order_id}


def _order_list_sort_key(item: dict[str, Any]) -> tuple[datetime, str]:
    received_at = item.get("received_at")
    if isinstance(received_at, str):
        try:
            received_at = datetime.fromisoformat(received_at)
        except ValueError:
            received_at = None
    return (
        received_at if isinstance(received_at, datetime) else datetime.min,
        str(item.get("id") or ""),
    )


def list_orders(
    status: Optional[str] = None,
    *,
    include_archived: bool = True,
    limit: int | None = None,
):
    normalized_limit = _normalize_order_list_limit(limit)
    key = f"{status or '__all__'}|archived:{1 if include_archived else 0}|limit:{normalized_limit or 'all'}"
    now = time.time()
    cached: list[dict] | None = None
    cached_at = 0.0
    with _orders_cache_lock:
        entry = _orders_cache.get(key)
        if entry:
            cached_at, cached = entry
    if cached is not None and now - cached_at < 30:
        return cached
    with ThreadPoolExecutor(max_workers=1) as executor:
        future = executor.submit(_fetch_orders, status, include_archived=include_archived, limit=normalized_limit)
        try:
            orders = future.result(timeout=5)
        except TimeoutError:
            return cached or []
        except Exception:
            raise
    with _orders_cache_lock:
        _orders_cache[key] = (time.time(), orders)
    return orders


def list_orders_page(
    status: Optional[str] = None,
    *,
    include_archived: bool = True,
    limit: int | None = None,
    before_received_at: str | None = None,
    before_id: str | None = None,
) -> dict[str, Any]:
    normalized_limit = _normalize_order_list_limit(limit)
    cursor_received_at = _parse_order_list_cursor_received_at(before_received_at)
    cursor_id = _normalize_order_list_cursor_id(before_id)
    if cursor_received_at is None and cursor_id:
        cursor_id = ""
    has_cursor = cursor_received_at is not None
    if not has_cursor:
        orders = list_orders(status=status, include_archived=include_archived, limit=normalized_limit)
    else:
        orders = _fetch_orders(
            status,
            include_archived=include_archived,
            limit=normalized_limit,
            before_received_at=cursor_received_at.isoformat(),
            before_id=cursor_id,
        )
    has_more = normalized_limit is not None and len(orders) >= normalized_limit
    return {
        "orders": orders,
        "next_cursor": build_order_list_cursor(orders) if has_more else None,
        "has_more": has_more,
    }


def refresh_orders_cache(
    status: Optional[str] = None,
    *,
    include_archived: bool = True,
    limit: int | None = None,
) -> int:
    normalized_limit = _normalize_order_list_limit(limit)
    orders = _fetch_orders(status, include_archived=include_archived, limit=normalized_limit)
    key = f"{status or '__all__'}|archived:{1 if include_archived else 0}|limit:{normalized_limit or 'all'}"
    with _orders_cache_lock:
        _orders_cache[key] = (time.time(), orders)
    return len(orders)


def _order_week_group_value(order: Order) -> str:
    return _normalize_sheet_week_value(order.week_code) or _to_sheet_month_id(order.week_code) or ""


def _set_orders_archived_state(
    orders: list[Order],
    *,
    archived: bool,
    archived_by: str | None = None,
) -> tuple[list[str], datetime | None]:
    changed_order_ids: list[str] = []
    effective_archived_at = datetime.utcnow() if archived else None
    effective_archived_by = str(archived_by or "").strip() or None
    for order in orders:
        order_id = str(order.id or "").strip()
        if not order_id:
            continue
        if archived:
            if order.archived_at is not None:
                continue
            order.archived_at = effective_archived_at
            order.archived_by = effective_archived_by
        else:
            if order.archived_at is None:
                continue
            order.archived_at = None
            order.archived_by = None
        changed_order_ids.append(order_id)
    return changed_order_ids, effective_archived_at


def archive_order(
    order_id: str,
    *,
    archived_by: str | None = None,
) -> tuple[dict[str, Any] | None, str | None]:
    normalized_order_id = str(order_id or "").strip()
    if not normalized_order_id:
        return None, "order_not_found"
    with session_scope() as session:
        order = session.get(Order, normalized_order_id)
        if order is None:
            return None, "order_not_found"
        changed_order_ids, archived_at = _set_orders_archived_state(
            [order],
            archived=True,
            archived_by=archived_by,
        )
    _invalidate_orders_cache()
    return (
        {
            "order_id": normalized_order_id,
            "archived": True,
            "changed": bool(changed_order_ids),
            "archived_at": archived_at.isoformat() if archived_at else None,
            "archived_by": str(archived_by or "").strip() or None,
        },
        None,
    )


def unarchive_order(order_id: str) -> tuple[dict[str, Any] | None, str | None]:
    normalized_order_id = str(order_id or "").strip()
    if not normalized_order_id:
        return None, "order_not_found"
    with session_scope() as session:
        order = session.get(Order, normalized_order_id)
        if order is None:
            return None, "order_not_found"
        changed_order_ids, _ = _set_orders_archived_state([order], archived=False)
    _invalidate_orders_cache()
    return (
        {
            "order_id": normalized_order_id,
            "archived": False,
            "changed": bool(changed_order_ids),
            "archived_at": None,
            "archived_by": None,
        },
        None,
    )


def _purge_order_runtime_state_in_session(session, order_ids: list[str]) -> dict[str, int]:
    normalized_order_ids = [str(item or "").strip() for item in order_ids if str(item or "").strip()]
    if not normalized_order_ids:
        return {}
    orders = session.execute(select(Order).where(Order.id.in_(normalized_order_ids))).scalars().all()
    document_ids: set[str] = set()
    for order in orders:
        current_document_id = str(order.current_document_id or "").strip()
        if current_document_id:
            document_ids.add(current_document_id)
        for document_id in order.superseded_document_ids or []:
            normalized_document_id = str(document_id or "").strip()
            if normalized_document_id:
                document_ids.add(normalized_document_id)
    documents = (
        session.execute(select(OrderDocument).where(OrderDocument.id.in_(sorted(document_ids)))).scalars().all()
        if document_ids
        else []
    )
    upload_message_ids: set[str] = set()
    upload_message_prefixes: set[str] = set()

    def add_upload_message_id(raw_value: object) -> None:
        token = str(raw_value or "").strip()
        if not token.startswith("upload:sha256:"):
            return
        upload_message_ids.add(token)
        if ":split:" in token:
            upload_message_prefixes.add(token.split(":split:", 1)[0])
        else:
            upload_message_prefixes.add(token)

    for order in orders:
        add_upload_message_id(order.message_id)
    for document in documents:
        add_upload_message_id(document.source_email_id)

    upload_pdf_filters = []
    if upload_message_ids:
        upload_pdf_filters.append(UploadedPdf.message_id.in_(sorted(upload_message_ids)))
    for prefix in sorted(upload_message_prefixes):
        upload_pdf_filters.append(UploadedPdf.message_id.like(f"{prefix}%"))

    uploaded_pdf_ids: list[str] = []
    if upload_pdf_filters:
        uploaded_pdf_ids = [
            str(item or "").strip()
            for item in session.execute(select(UploadedPdf.id).where(or_(*upload_pdf_filters))).scalars().all()
            if str(item or "").strip()
        ]

    ingest_job_filters = []
    if upload_message_ids:
        ingest_job_filters.append(IngestJob.id.in_(sorted(upload_message_ids)))
    for prefix in sorted(upload_message_prefixes):
        ingest_job_filters.append(IngestJob.id.like(f"{prefix}%"))

    statements = [
        ("label_rows", delete(LabelRow).where(LabelRow.order_id.in_(normalized_order_ids))),
        ("bags", delete(Bag).where(Bag.order_id.in_(normalized_order_ids))),
        ("delivery_notes", delete(DeliveryNote).where(DeliveryNote.order_id.in_(normalized_order_ids))),
        (
            "order_critical_decisions",
            delete(OrderCriticalDecision).where(OrderCriticalDecision.order_id.in_(normalized_order_ids)),
        ),
        (
            "order_current_states",
            delete(OrderCurrentState).where(OrderCurrentState.order_id.in_(normalized_order_ids)),
        ),
        (
            "order_workflow_states",
            delete(OrderWorkflowState).where(OrderWorkflowState.order_id.in_(normalized_order_ids)),
        ),
        (
            "order_confirmed_snapshots",
            delete(OrderConfirmedSnapshot).where(OrderConfirmedSnapshot.order_id.in_(normalized_order_ids)),
        ),
        (
            "order_sheet_patch_candidates",
            delete(OrderSheetPatchCandidate).where(OrderSheetPatchCandidate.order_id.in_(normalized_order_ids)),
        ),
        ("order_sheet_drafts", delete(OrderSheetDraft).where(OrderSheetDraft.order_id.in_(normalized_order_ids))),
        (
            "order_ocr_evidence_runs",
            delete(OrderOcrEvidenceRun).where(OrderOcrEvidenceRun.order_id.in_(normalized_order_ids)),
        ),
        ("order_ocr_revisions", delete(OrderOcrRevision).where(OrderOcrRevision.order_id.in_(normalized_order_ids))),
        ("order_ocr_cache", delete(OrderOcrCache).where(OrderOcrCache.order_id.in_(normalized_order_ids))),
        (
            "order_menu_snapshots",
            delete(OrderMenuSnapshot).where(OrderMenuSnapshot.order_id.in_(normalized_order_ids)),
        ),
        ("order_lines", delete(OrderLine).where(OrderLine.order_id.in_(normalized_order_ids))),
        ("ocr_jobs", delete(OcrJob).where(OcrJob.order_id.in_(normalized_order_ids))),
    ]
    if uploaded_pdf_ids:
        statements.append(
            (
                "uploaded_pdf_attempts",
                delete(UploadedPdfAttempt).where(UploadedPdfAttempt.uploaded_pdf_id.in_(uploaded_pdf_ids)),
            )
        )
    if upload_pdf_filters:
        statements.append(("uploaded_pdfs", delete(UploadedPdf).where(or_(*upload_pdf_filters))))
    if ingest_job_filters:
        statements.append(("ingest_jobs", delete(IngestJob).where(or_(*ingest_job_filters))))
    counts: dict[str, int] = {}
    for name, statement in statements:
        result = session.execute(statement)
        counts[name] = int(result.rowcount or 0)
    return counts


def archive_orders_for_week(
    week_value: str,
    *,
    order_ids: list[str] | None = None,
    archived_by: str | None = None,
    purge_runtime_state: bool = False,
) -> tuple[dict[str, Any] | None, str | None]:
    normalized_week = str(week_value or "").strip()
    if not normalized_week or normalized_week == "unresolved":
        return None, "invalid_week"
    normalized_order_ids = [str(item or "").strip() for item in (order_ids or []) if str(item or "").strip()]
    now = datetime.utcnow()
    with session_scope() as session:
        if normalized_order_ids:
            matched = session.execute(select(Order).where(Order.id.in_(normalized_order_ids))).scalars().all()
            matched_ids = {str(order.id or "") for order in matched}
            if matched_ids != set(normalized_order_ids):
                return None, "week_not_found"
        else:
            matched = [
                order
                for order in session.execute(select(Order)).scalars().all()
                if _order_week_group_value(order) == normalized_week
            ]
        if not matched:
            return None, "week_not_found"
        archived_order_ids, archived_at = _set_orders_archived_state(
            matched,
            archived=True,
            archived_by=archived_by,
        )
        purge_counts = (
            _purge_order_runtime_state_in_session(session, [str(order.id or "") for order in matched])
            if purge_runtime_state
            else {}
        )
    _invalidate_orders_cache()
    return (
        {
            "week_value": normalized_week,
            "archived_count": len(archived_order_ids),
            "archived_order_ids": archived_order_ids,
            "archived_at": archived_at.isoformat() if archived_at else now.isoformat(),
            "archived_by": str(archived_by or "").strip() or None,
            "purged_runtime_state": bool(purge_runtime_state),
            "purge_counts": purge_counts,
        },
        None,
    )


def unarchive_orders_for_week(
    week_value: str,
    *,
    order_ids: list[str] | None = None,
) -> tuple[dict[str, Any] | None, str | None]:
    normalized_week = str(week_value or "").strip()
    if not normalized_week or normalized_week == "unresolved":
        return None, "invalid_week"
    normalized_order_ids = [str(item or "").strip() for item in (order_ids or []) if str(item or "").strip()]
    with session_scope() as session:
        if normalized_order_ids:
            matched = session.execute(select(Order).where(Order.id.in_(normalized_order_ids))).scalars().all()
            matched_ids = {str(order.id or "") for order in matched}
            if matched_ids != set(normalized_order_ids):
                return None, "week_not_found"
        else:
            matched = [
                order
                for order in session.execute(select(Order)).scalars().all()
                if _order_week_group_value(order) == normalized_week
            ]
        if not matched:
            return None, "week_not_found"
        restored_order_ids, _ = _set_orders_archived_state(matched, archived=False)
    _invalidate_orders_cache()
    return (
        {
            "week_value": normalized_week,
            "restored_count": len(restored_order_ids),
            "restored_order_ids": restored_order_ids,
        },
        None,
    )


def list_orders_by_line_date(
    target_date: date,
    facility_id: Optional[str] = None,
    status: Optional[str] = None,
) -> list[dict]:
    with session_scope() as session:
        query = (
            select(Order, func.count(OrderLine.id).label("line_count"))
            .join(OrderLine, Order.id == OrderLine.order_id)
            .where(OrderLine.date == target_date)
            .group_by(Order.id)
        )
        if facility_id:
            query = query.where(Order.facility_code == facility_id)
        if status:
            query = query.where(Order.status == status)
        rows = session.execute(query).all()
        result: list[dict] = []
        for order, line_count in rows:
            payload = serialize_order_summary(order)
            payload["line_count"] = int(line_count or 0)
            result.append(payload)
        result.sort(key=lambda item: (item.get("received_at") or "", item.get("id") or ""), reverse=True)
        return result


def update_lines(
    order_id: str,
    lines: list,
    *,
    expected_lines_updated_at: str | None = None,
    enforce_conflict_guard: bool = False,
) -> bool | tuple[bool, str | None]:
    event_context: dict[str, Any] | None = None
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return (False, "order_not_found") if enforce_conflict_guard else False
        if enforce_conflict_guard:
            conflict = _lines_timestamp_conflict_detail(
                current_lines_updated_at=order.lines_updated_at,
                expected_lines_updated_at=expected_lines_updated_at,
            )
            if conflict is not None:
                return False, conflict["error"]
        normalized_lines = _ensure_unique_line_ids(lines)
        # wipe existing
        session.execute(delete(OrderLine).where(OrderLine.order_id == order_id))
        for line in normalized_lines:
            session.add(
                OrderLine(
                    id=line.get("id") or _make_line_id(),
                    order_id=order_id,
                    line_id=line.get("line_id"),
                    date=_parse_date_value(line.get("date")),
                    daypart=line.get("daypart"),
                    menu_name=line.get("menu_name"),
                    diet_type=line.get("diet_type"),
                    area_id=line.get("area_id"),
                    bag_type=line.get("bag_type"),
                    quantity_original=line.get("quantity_original"),
                    quantity_corrected=line.get("quantity_corrected"),
                    change_note=line.get("change_note"),
                )
            )
        order.lines_updated_at = datetime.utcnow()
        logger.info("Order lines updated", order_id=order_id)
        event_context = {
            "fac": order.facility_code,
            "wek": order.week_code,
            "line_count": len(normalized_lines),
        }
    if event_context:
        record_event(
            "order_lines_update",
            actor="system",
            target=order_id,
            fac=event_context.get("fac"),
            wek=event_context.get("wek"),
            metadata={"line_count": event_context.get("line_count", 0)},
        )
    _invalidate_orders_cache()
    _invalidate_current_sheet_state_after_order_lines_write(order_id)
    try:
        workflow_state_service.refresh_workflow_state(order_id)
    except Exception as exc:  # noqa: BLE001
        logger.warning("Workflow state refresh failed after lines update", order_id=order_id, error=str(exc))
    return (True, None) if enforce_conflict_guard else True


def _is_blank_menu_value(value: object) -> bool:
    if value is None:
        return True
    if isinstance(value, str):
        return value.strip() == ""
    return False


def _build_menu_snapshot(order: Order, *, session: Any = None) -> dict:
    session_kwargs = {"session": session} if session is not None else {}
    return _build_menu_snapshot_from_lines(
        facility_code=order.facility_code,
        week_code=order.week_code,
        lines=[
            {
                "menu_name": line.menu_name,
                "daypart": line.daypart,
            }
            for line in (order.lines or [])
        ],
        **session_kwargs,
    )


def _build_menu_snapshot_from_lines(
    *,
    facility_code: str | None,
    week_code: str | None,
    lines: list[dict[str, Any]] | None,
    session: Any = None,
) -> dict:
    names = sorted(
        {
            str(line.get("menu_name") or "").strip()
            for line in (lines or [])
            if isinstance(line, dict) and str(line.get("menu_name") or "").strip()
        }
    )
    items: list[dict] = []
    if week_code:
        items = _collect_menu_items_for_week(week_code, facility_code, session=session) if session is not None else _collect_menu_items_for_week(week_code, facility_code)
    item_map: dict[str, list[dict]] = {}
    for item in items:
        name = str(item.get("name") or "").strip()
        if name:
            item_map.setdefault(name, []).append(item)
    defaults = menu_service.resolve_menu_defaults_in_session(session, names, facility_code)[0] if session is not None else menu_service.resolve_menu_defaults(names, facility_code)
    line_seed_fields = {
        "daypart": "daypart",
        "menu_category": "category",
        "menu_qty_per_serving": "qty_per_serving",
        "menu_unit_type": "unit_type",
        "menu_bag_max_qty": "bag_max_qty",
        "menu_bag_max_unit": "bag_max_unit",
        "menu_temp_type": "temp_type",
        "condiments": "condiments",
    }
    line_seed_values: dict[str, dict[str, object]] = {}
    for line in (lines or []):
        if not isinstance(line, dict):
            continue
        name = str(line.get("menu_name") or "").strip()
        if not name:
            continue
        name_payload = line_seed_values.setdefault(name, {})
        for source_field, target_field in line_seed_fields.items():
            value = line.get(source_field)
            if _is_blank_menu_value(value):
                continue
            bucket = name_payload.setdefault(target_field, set())
            if isinstance(value, list):
                bucket.add(json.dumps(value, ensure_ascii=False, sort_keys=True))
            else:
                bucket.add(value)
    snapshot_items: dict[str, dict] = {}
    for name in names:
        line_contexts = [line for line in (lines or []) if isinstance(line, dict) and str(line.get("menu_name") or "").strip() == name]
        item_candidates = item_map.get(name, [])
        item = {}
        if len(item_candidates) == 1:
            item = item_candidates[0]
        elif item_candidates and line_contexts:
            line_dayparts = {str(line.get("daypart") or "").strip() for line in line_contexts if str(line.get("daypart") or "").strip()}
            exact_items = [
                candidate
                for candidate in item_candidates
                if str(candidate.get("daypart") or "").strip() in line_dayparts
            ]
            if len(exact_items) == 1:
                item = exact_items[0]
        fallback = defaults.get(name, {})
        payload: dict[str, object] = {}
        for field in (
            "unit_type",
            "qty_per_serving",
            "temp_type",
            "daypart",
            "category",
            "bag_max_qty",
            "bag_max_unit",
            "condiments",
        ):
            seed_values = line_seed_values.get(name, {}).get(field)
            if isinstance(seed_values, set) and len(seed_values) == 1:
                seeded = next(iter(seed_values))
                if field == "condiments" and isinstance(seeded, str):
                    try:
                        value = json.loads(seeded)
                    except Exception:
                        value = seeded
                else:
                    value = seeded
            else:
                value = None
            if _is_blank_menu_value(value):
                value = item.get(field)
            if _is_blank_menu_value(value):
                value = fallback.get(field)
            if value is not None:
                payload[field] = value
        snapshot_items[name] = payload
    return {
        "version": 1,
        "generated_at": datetime.utcnow().isoformat(),
        "menu_items": snapshot_items,
    }


def get_order_menu_snapshot(order_id: str) -> dict | None:
    with session_scope() as session:
        snapshot = (
            session.execute(
                select(OrderMenuSnapshot).where(OrderMenuSnapshot.order_id == order_id)
            )
            .scalars()
            .first()
        )
        if not snapshot:
            return None
        return snapshot.snapshot_json


def get_latest_confirmed_snapshot(order_id: str) -> dict[str, Any] | None:
    normalized_order_id = str(order_id or "").strip()
    if not normalized_order_id:
        return None
    with session_scope() as session:
        snapshot = (
            session.query(OrderConfirmedSnapshot)
            .filter(OrderConfirmedSnapshot.order_id == normalized_order_id)
            .order_by(OrderConfirmedSnapshot.confirmed_at.desc(), OrderConfirmedSnapshot.id.desc())
            .first()
        )
        if not snapshot:
            return None
        return {
            "id": snapshot.id,
            "order_id": snapshot.order_id,
            "draft_id": snapshot.draft_id,
            "snapshot_digest": snapshot.snapshot_digest,
            "snapshot_json": snapshot.snapshot_json if isinstance(snapshot.snapshot_json, dict) else {},
            "confirmed_by": snapshot.confirmed_by,
            "confirmed_at": snapshot.confirmed_at.isoformat() if isinstance(snapshot.confirmed_at, datetime) else None,
            "created_at": snapshot.created_at.isoformat() if isinstance(snapshot.created_at, datetime) else None,
        }


