def _daily_bag_rule_amounts(line: dict[str, Any], quantity: float) -> dict[str, float] | None:
    menu_name = str(line.get("menu_name") or "").strip()
    diet = bucket_diet_type_for_aggregation(line.get("diet_type")) or ""
    for rule in _DAILY_BAG_UNIT_RULES:
        if not any(name in menu_name for name in rule["names"]):
            continue
        per_serving_key = "soft_per_serving" if diet in {"soft", "mixer"} else "regular_per_serving"
        per_serving = rule.get(per_serving_key)
        if per_serving is None:
            return None
        amounts = {str(rule["unit"]): round(quantity * float(per_serving), 4)}
        hidden_per_serving = rule.get("hidden_per_serving")
        if hidden_per_serving is not None:
            hidden_unit = str(rule.get("hidden_unit") or "g")
            amounts[hidden_unit] = round(amounts.get(hidden_unit, 0.0) + quantity * float(hidden_per_serving), 4)
        return amounts
    return None


def _format_amount_label(totals: dict[str, float] | None) -> str | None:
    if not isinstance(totals, dict):
        return None
    entries: list[tuple[str, float]] = []
    for unit, raw_value in totals.items():
        try:
            value = float(raw_value)
        except (TypeError, ValueError):
            continue
        if not math.isfinite(value) or value < 0:
            continue
        entries.append((str(unit or ""), value))
    if not entries:
        return None
    entries.sort(key=lambda item: item[0])
    return " + ".join(f"{_format_amount_number(value)}{unit}" for unit, value in entries)


def _format_basis_label(per_serving: dict[str, float] | None) -> str | None:
    if not isinstance(per_serving, dict):
        return None
    entries: list[tuple[str, float]] = []
    for unit, raw_value in per_serving.items():
        try:
            value = float(raw_value)
        except (TypeError, ValueError):
            continue
        if not math.isfinite(value) or value < 0:
            continue
        entries.append((str(unit or ""), value))
    if not entries:
        return None
    entries.sort(key=lambda item: item[0])
    return " + ".join(
        f"{_format_amount_number(value)}{unit}/人" if unit else f"{_format_amount_number(value)}/人"
        for unit, value in entries
    )


def _merge_amount_totals(base: dict[str, float], incoming: dict[str, float] | None) -> dict[str, float]:
    if not isinstance(incoming, dict):
        return base
    for unit, raw_value in incoming.items():
        try:
            value = float(raw_value)
        except (TypeError, ValueError):
            continue
        if not math.isfinite(value) or value < 0:
            continue
        base[str(unit or "")] = round(base.get(str(unit or ""), 0.0) + value, 4)
    return base


def _build_condiment_amount_key(date_value: object, daypart: object) -> str:
    return f"condiment__{_normalize_bag_summary_date(date_value)}__{_normalize_daypart_key(daypart)}"


def _build_non_condiment_amount_key(
    date_value: object,
    daypart: object,
    menu_name: object,
    diet_type: object,
    area_id: object,
) -> str:
    return "__".join(
        [
            "normal",
            _normalize_bag_summary_date(date_value),
            _normalize_daypart_key(daypart),
            _normalize_sheet_text(menu_name),
            _normalize_sheet_diet(diet_type) or _normalize_sheet_text(diet_type).lower() or "unknown",
            _normalize_sheet_area(area_id) or "X",
        ]
    )


def _build_daily_bag_amount_stats(lines: list[dict[str, Any]]) -> dict[str, Any]:
    condiment_totals: dict[str, dict[str, float]] = {}
    non_condiment_stats: dict[str, dict[str, dict[str, float]]] = {}
    menu_category_by_group: dict[str, str] = {}
    for line in lines:
        quantity_raw = (
            line.get("quantity_corrected")
            if line.get("quantity_corrected") is not None
            else line.get("quantity_original")
        )
        try:
            quantity = float(quantity_raw)
        except (TypeError, ValueError):
            continue
        if not math.isfinite(quantity) or quantity <= 0:
            continue
        rule_amounts = _daily_bag_rule_amounts(line, quantity)
        if rule_amounts:
            amount_by_unit = rule_amounts
        else:
            unit = _normalize_output_unit(line.get("menu_unit_type") or line.get("actual_unit_type"))
            if not unit:
                continue
            amount_raw = None
            per_serving = line.get("menu_qty_per_serving")
            try:
                if per_serving is not None:
                    per_serving_value = float(per_serving)
                    if math.isfinite(per_serving_value) and per_serving_value >= 0:
                        amount_raw = per_serving_value * quantity
            except (TypeError, ValueError):
                amount_raw = None
            if amount_raw is None:
                amount_raw = line.get("actual_amount")
            try:
                amount = float(amount_raw)
            except (TypeError, ValueError):
                continue
            if not math.isfinite(amount) or amount < 0:
                continue
            amount_by_unit = {unit: amount}
        if _normalize_sheet_text(line.get("bag_type")).lower() == "condiment":
            key = _build_condiment_amount_key(line.get("date"), line.get("daypart"))
            totals = condiment_totals.get(key, {})
            for unit, amount in amount_by_unit.items():
                totals[unit] = round(totals.get(unit, 0.0) + amount, 4)
            condiment_totals[key] = totals
            continue
        key = _build_non_condiment_amount_key(
            line.get("date"),
            line.get("daypart"),
            line.get("menu_name"),
            line.get("diet_type"),
            line.get("area_id"),
        )
        menu_category = str(line.get("menu_category") or "").strip()
        if menu_category and key not in menu_category_by_group:
            menu_category_by_group[key] = menu_category
        unit_stats = non_condiment_stats.get(key, {})
        for unit, amount in amount_by_unit.items():
            current = unit_stats.get(unit, {"amount": 0.0, "quantity": 0.0})
            current["amount"] = round(current.get("amount", 0.0) + amount, 4)
            current["quantity"] = round(current.get("quantity", 0.0) + quantity, 4)
            unit_stats[unit] = current
        non_condiment_stats[key] = unit_stats
    per_serving_by_group: dict[str, dict[str, float]] = {}
    for key, unit_stats in non_condiment_stats.items():
        per_serving: dict[str, float] = {}
        for unit, stat in unit_stats.items():
            try:
                amount = float(stat.get("amount", 0.0))
                quantity = float(stat.get("quantity", 0.0))
            except (TypeError, ValueError):
                continue
            if not math.isfinite(amount) or not math.isfinite(quantity) or quantity <= 0:
                continue
            per_serving[unit] = round(amount / quantity, 6)
        if per_serving:
            per_serving_by_group[key] = per_serving
    return {
        "condiment_totals": condiment_totals,
        "per_serving_by_group": per_serving_by_group,
        "menu_category_by_group": menu_category_by_group,
    }


def _resolve_daily_bag_amount_totals(bag: dict[str, Any], stats: dict[str, Any]) -> dict[str, float] | None:
    bag_type = _normalize_sheet_text(bag.get("bag_type")).lower()
    if bag_type == "condiment":
        return stats.get("condiment_totals", {}).get(
            _build_condiment_amount_key(bag.get("date"), bag.get("daypart"))
        )
    try:
        quantity = float(bag.get("quantity"))
    except (TypeError, ValueError):
        return None
    if not math.isfinite(quantity) or quantity < 0:
        return None
    per_serving = stats.get("per_serving_by_group", {}).get(
        _build_non_condiment_amount_key(
            bag.get("date"),
            bag.get("daypart"),
            bag.get("menu_name"),
            bag.get("diet_type"),
            bag.get("area_id"),
        )
    )
    if not isinstance(per_serving, dict):
        return None
    totals: dict[str, float] = {}
    for unit, raw_value in per_serving.items():
        try:
            value = float(raw_value)
        except (TypeError, ValueError):
            continue
        if not math.isfinite(value) or value < 0:
            continue
        totals[unit] = round(value * quantity, 4)
    return totals or None


def _resolve_daily_bag_basis_label(bag: dict[str, Any], stats: dict[str, Any]) -> str | None:
    bag_type = _normalize_sheet_text(bag.get("bag_type")).lower()
    if bag_type == "condiment":
        return None
    per_serving = stats.get("per_serving_by_group", {}).get(
        _build_non_condiment_amount_key(
            bag.get("date"),
            bag.get("daypart"),
            bag.get("menu_name"),
            bag.get("diet_type"),
            bag.get("area_id"),
        )
    )
    return _format_basis_label(per_serving)


def _resolve_daily_bag_menu_category(bag: dict[str, Any], stats: dict[str, Any]) -> str | None:
    bag_type = _normalize_sheet_text(bag.get("bag_type")).lower()
    if bag_type == "condiment":
        return "付属品"
    return stats.get("menu_category_by_group", {}).get(
        _build_non_condiment_amount_key(
            bag.get("date"),
            bag.get("daypart"),
            bag.get("menu_name"),
            bag.get("diet_type"),
            bag.get("area_id"),
        )
    )


def _resolve_facility_label_for_code(facility_config: dict[str, Any]) -> str:
    facility_code = str(facility_config.get("facility_id") or "").strip()
    if not facility_code:
        return "未確定"
    facility_name = str(facility_config.get("facility_name") or "").strip()
    return f"{facility_name} ({facility_code})" if facility_name else facility_code


def _safe_per_serving_value(line: dict[str, Any]) -> float | None:
    raw = line.get("menu_qty_per_serving")
    if raw is None:
        quantity_raw = (
            line.get("quantity_corrected")
            if line.get("quantity_corrected") is not None
            else line.get("quantity_original")
        )
        amount_raw = line.get("actual_amount")
        try:
            quantity_value = float(quantity_raw)
            amount_value = float(amount_raw)
        except (TypeError, ValueError):
            return None
        if not math.isfinite(quantity_value) or quantity_value <= 0:
            return None
        if not math.isfinite(amount_value) or amount_value < 0:
            return None
        return round(amount_value / quantity_value, 6)
    try:
        value = float(raw)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(value) or value < 0:
        return None
    return round(value, 6)


def _safe_line_quantity_value(line: dict[str, Any]) -> float:
    raw = line.get("quantity_corrected")
    if raw is None:
        raw = line.get("quantity_original")
    try:
        value = float(raw)
    except (TypeError, ValueError):
        return 0.0
    if not math.isfinite(value) or value < 0:
        return 0.0
    return value


def _build_daily_output_variant_basis_label(unit_type: str, qty_per_serving: float | None) -> str | None:
    if qty_per_serving is None:
        return None
    unit = _normalize_output_unit(unit_type)
    return _format_basis_label({unit: qty_per_serving} if unit else {"": qty_per_serving})


def _list_daily_output_override_editor_rows(
    target_date: date,
    *,
    daypart: str,
    menu_name: str,
    menu_category: str | None = None,
    original_adoptions: list[dict] | None = None,
) -> dict[str, Any]:
    normalized_daypart = daily_output_override_service.normalize_override_daypart(daypart)
    normalized_menu_name = daily_output_override_service.normalize_override_menu_name(menu_name)
    normalized_category = daily_output_override_service.normalize_override_category(menu_category)
    if not normalized_daypart or not normalized_menu_name:
        raise ValueError("daypart and menu_name are required")

    row_map: dict[tuple[str, str], dict[str, Any]] = {}
    overrides = daily_output_override_service.list_overrides(
        output_date=target_date,
        menu_name=menu_name,
        daypart=normalized_daypart,
        menu_category=normalized_category or None,
    )
    override_map = {
        (
            str(item.get("facility_id") or "").strip(),
            str(item.get("diet_type") or "").strip() or "unknown",
        ): item
        for item in overrides
    }
    if original_adoptions is None:
        raise ValueError("daily output editor originals missing")
    originals_by_id = {item["order"]["id"]: item for item in original_adoptions}
    orders = [item["order"] for item in original_adoptions]
    from src.services.output_builder import build_order_lines_for_outputs

    for order_summary in orders:
        order_id = str(order_summary.get("id") or "").strip()
        if not order_id:
            continue
        order_payload = originals_by_id[order_id]["order"]
        if not isinstance(order_payload, dict):
            continue
        facility_code = str(order_payload.get("facility") or "").strip()
        accepted_candidate = originals_by_id[order_id]["candidate"]
        facility_label = _resolve_facility_label_for_code(
            accepted_candidate["configured_input"]["facility"],
        )
        lines = build_order_lines_for_outputs(order_payload, accepted_candidate=accepted_candidate)
        for line in lines:
            line_date = _normalize_entry_date(line.get("date"))
            if line_date != target_date:
                continue
            line_daypart = daily_output_override_service.normalize_override_daypart(line.get("daypart"))
            line_menu_name = daily_output_override_service.normalize_override_menu_name(line.get("menu_name"))
            line_category = daily_output_override_service.normalize_override_category(line.get("menu_category"))
            if line_daypart != normalized_daypart or line_menu_name != normalized_menu_name:
                continue
            if normalized_category and line_category != normalized_category:
                continue
            source_diet = daily_output_override_service.normalize_override_diet_type(line.get("diet_type")) or "unknown"
            row_key = (facility_code, source_diet)
            row = row_map.get(row_key)
            if row is None:
                row = {
                    "facility_id": facility_code,
                    "facility_label": facility_label,
                    "diet_type": source_diet,
                    "order_count": 0,
                    "total_quantity": 0.0,
                    "current_basis_label": None,
                    "current_qty_per_serving": None,
                    "current_unit_type": None,
                    "requires_intervention": False,
                    "current_variants": [],
                    "_variants": {},
                    "_order_ids": set(),
                    "override": None,
                }
                row_map[row_key] = row
            row["total_quantity"] += _safe_line_quantity_value(line)
            row["_order_ids"].add(order_id)
            per_serving_value = _safe_per_serving_value(line)
            unit_type = _normalize_output_unit(line.get("menu_unit_type") or line.get("actual_unit_type"))
            variant_key = (
                str(line.get("menu_name") or "").strip(),
                line_daypart,
                line_category,
                unit_type,
                per_serving_value,
            )
            variant = row["_variants"].get(variant_key)
            if variant is None:
                variant = {
                    "menu_name": str(line.get("menu_name") or "").strip(),
                    "daypart": line_daypart,
                    "menu_category": line_category,
                    "unit_type": unit_type,
                    "qty_per_serving": per_serving_value,
                    "basis_label": _build_daily_output_variant_basis_label(unit_type, per_serving_value),
                    "order_ids": set(),
                }
                row["_variants"][variant_key] = variant
            variant["order_ids"].add(order_id)

    rows: list[dict[str, Any]] = []
    for (facility_code, source_diet), row in row_map.items():
        variants = []
        for variant in row.pop("_variants").values():
            order_ids = sorted(list(variant.pop("order_ids")))
            variants.append({**variant, "order_ids": order_ids})
        variants.sort(
            key=lambda item: (
                item.get("menu_name") or "",
                item.get("unit_type") or "",
                item.get("qty_per_serving") or 0,
            )
        )
        row["current_variants"] = variants
        row["requires_intervention"] = len(variants) > 1
        row["order_count"] = len(row.pop("_order_ids"))
        row["total_quantity"] = round(float(row.get("total_quantity") or 0.0), 4)
        if len(variants) == 1:
            variant = variants[0]
            row["current_basis_label"] = variant.get("basis_label")
            row["current_qty_per_serving"] = variant.get("qty_per_serving")
            row["current_unit_type"] = variant.get("unit_type")
        existing_override = override_map.get((facility_code, source_diet))
        if existing_override:
            row["override"] = existing_override
        rows.append(row)

    rows.sort(key=lambda item: (item.get("facility_label") or "", item.get("diet_type") or ""))
    return {
        "date": target_date.isoformat(),
        "daypart": normalized_daypart,
        "menu_name": menu_name,
        "menu_category": normalized_category or "",
        "rows": rows,
    }


_daily_override_boundary = ContextVar("daily_override_boundary", default=None)


def _override_conflict():
    raise ValueError(json.dumps({"code": "daily_output_original_conflict", "detail": "表示後に対象注文または正本・単位設定が変更されました。開き直してください。"}, ensure_ascii=False))


@contextmanager
def _daily_override_transaction():
    with session_scope() as session:
        dialect = session.get_bind().dialect.name
        if dialect == "sqlite":
            session.connection().exec_driver_sql("BEGIN IMMEDIATE")
        elif dialect == "postgresql":
            from src.models.order_output_artifact import OrderBaggingResult, OrderOutputBundle
            # Membership inserts/deletes must be excluded, not merely existing rows.
            models = (Order, OrderLine, OrderWorkflowState, OrderSheetDraft,
                      OrderOcrEvidenceRun, OrderOcrCache, OrderConfirmedSnapshot,
                      OrderVersion, OrderDocument, OrderBaggingResult, OrderOutputBundle,
                      Bag, DailyOutputPortionOverride)
            preparer = session.get_bind().dialect.identifier_preparer
            names = sorted({preparer.format_table(model.__table__) for model in models})
            session.connection().exec_driver_sql("LOCK TABLE " + ", ".join(names) + " IN SHARE ROW EXCLUSIVE MODE")
        else:
            raise ValueError("daily output ownership locking unsupported")
        with daily_output_override_service.use_write_session(session):
            yield session


@contextmanager
def _daily_override_read_transaction():
    with session_scope() as session:
        dialect = session.get_bind().dialect.name
        if dialect == "sqlite":
            session.connection().exec_driver_sql("BEGIN")
        elif dialect == "postgresql":
            session.connection().exec_driver_sql("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY")
        else:
            raise ValueError("daily output read snapshot unsupported")
        with daily_output_override_service.use_write_session(session):
            yield session


def _daily_override_snapshot(session, target_date, *, daypart, menu_name, menu_category=None):
    from src.services.output_builder import _capture_accepted_output_read
    identities = session.execute(
        select(Order.id).join(OrderLine, Order.id == OrderLine.order_id)
        .where(OrderLine.date == target_date).distinct().order_by(Order.id)
    ).scalars().all()
    originals = [_capture_accepted_output_read(identity, session) for identity in identities]
    editor = _list_daily_output_override_editor_rows(
        target_date, daypart=daypart, menu_name=menu_name, menu_category=menu_category,
        original_adoptions=originals)
    overrides = daily_output_override_service.list_overrides(
        output_date=target_date, menu_name=menu_name, daypart=daypart, menu_category=menu_category)
    content = {"date": target_date.isoformat(), "daypart": editor["daypart"],
               "menu_name": editor["menu_name"], "menu_category": editor["menu_category"],
               "orders": _json_snapshot(originals), "overrides": overrides}
    digest = hashlib.sha256(json.dumps(content, sort_keys=True, ensure_ascii=False,
                                    separators=(",", ":")).encode("utf-8")).hexdigest()
    editor["original_receipt"] = {"date": content["date"], "daypart": content["daypart"],
                                  "menu_name": content["menu_name"], "menu_category": content["menu_category"],
                                  "order_ids": [item["order"]["id"] for item in originals], "digest": digest}
    return editor, originals


def list_daily_output_override_editor_rows(target_date, *, daypart, menu_name, menu_category=None):
    with _daily_override_read_transaction() as session:
        editor, _ = _daily_override_snapshot(session, target_date, daypart=daypart,
                                             menu_name=menu_name, menu_category=menu_category)
        return editor


def _owned_daily_override_write(function):
    @wraps(function)
    def owned(*args, original_receipt=None, **kwargs):
        if not isinstance(original_receipt, dict):
            _override_conflict()
        if (set(original_receipt) != {"date", "daypart", "menu_name", "menu_category", "order_ids", "digest"}
            or not isinstance(original_receipt.get("digest"), str)
            or not original_receipt.get("daypart") or not original_receipt.get("menu_name")):
            _override_conflict()
        target_date = _normalize_entry_date(original_receipt.get("date"))
        if target_date is None:
            _override_conflict()
        with _daily_override_transaction() as session:
            try:
                editor, originals = _daily_override_snapshot(
                    session, target_date, daypart=original_receipt.get("daypart"),
                    menu_name=original_receipt.get("menu_name"), menu_category=original_receipt.get("menu_category"))
            except ValueError:
                _override_conflict()
            if not snapshots_equal(editor["original_receipt"], original_receipt):
                _override_conflict()
            if "output_date" in kwargs and (kwargs["output_date"] != target_date
                or kwargs.get("menu_name") != editor["menu_name"]
                or daily_output_override_service.normalize_override_daypart(kwargs.get("daypart")) != editor["daypart"]
                or daily_output_override_service.normalize_override_category(kwargs.get("menu_category")) != editor["menu_category"]):
                _override_conflict()
            if function.__name__ == "delete_daily_output_portion_override":
                identity = args[0] if args else kwargs.get("override_id")
                if not any(row.get("override", {}).get("id") == identity
                           for row in editor["rows"] if isinstance(row.get("override"), dict)):
                    _override_conflict()
            from src.services.output_builder import _capture_output_adoption, _capture_accepted_output_read
            write_originals = []
            for read_original in originals:
                order_id = read_original["order"]["id"]
                try:
                    write_original = _capture_output_adoption(order_id, session)
                    if (not snapshots_equal(write_original["candidate"], read_original["candidate"])
                            or not snapshots_equal(write_original["write_input"].get("configured_input"),
                                                   read_original["candidate"]["configured_input"])
                            or not snapshots_equal(_capture_accepted_output_read(order_id, session), read_original)):
                        _override_conflict()
                except ValueError:
                    _override_conflict()
                write_originals.append(write_original)
            token = _daily_override_boundary.set((session, write_originals, editor))
            try:
                return function(*args, **kwargs)
            except ValueError as exc:
                try:
                    detail = json.loads(str(exc))
                except (TypeError, ValueError):
                    _override_conflict()
                if not isinstance(detail, dict):
                    _override_conflict()
                raise
            finally:
                _daily_override_boundary.reset(token)
    return owned


def _rebuild_bags_for_override_scope(target_date: date, facility_id: str, *, write_session=None, original_adoptions: list[dict] | None = None) -> list[str]:
    return _rebuild_bags_for_override_scopes(target_date, [facility_id], write_session=write_session, original_adoptions=original_adoptions)


def _rebuild_bags_for_override_scopes(target_date: date, facility_ids: list[str], *, write_session=None, original_adoptions: list[dict] | None = None) -> list[str]:
    affected_order_ids: list[str] = []
    from src.services.output_builder import rebuild_bags

    boundary = _daily_override_boundary.get()
    if boundary is not None and write_session is None:
        write_session = boundary[0]
        wanted = {str(item["id"]) for facility_id in facility_ids
                  for item in list_orders_by_line_date(target_date, facility_id=facility_id, status=None)}
        original_adoptions = [item for item in boundary[1] if item["order"]["id"] in wanted]

    if write_session is None or not isinstance(original_adoptions, list) or not original_adoptions:
        raise ValueError("output original ownership input missing")
    originals = {}
    for original in original_adoptions:
        order_id = original["order"]["id"]
        if order_id in originals:
            raise ValueError("output original ownership input ambiguous")
        originals[order_id] = original

    seen_order_ids: set[str] = set()
    for facility_id in facility_ids:
        facility_code = str(facility_id or "").strip()
        if not facility_code:
            continue
        summaries = list_orders_by_line_date(target_date, facility_id=facility_code, status=None)
        for summary in summaries:
            order_id = str(summary.get("id") or "").strip()
            if not order_id or order_id in seen_order_ids:
                continue
            if order_id not in originals:
                raise ValueError("output original ownership input missing")
            seen_order_ids.add(order_id)
            affected_order_ids.append(order_id)
    if set(originals) != seen_order_ids:
        raise ValueError("output original ownership scope mismatch")
    for order_id in sorted(affected_order_ids):
        rebuild_bags(order_id, write_session=write_session, original_adoption=originals[order_id])
    return affected_order_ids


def _require_daily_output_override_binding() -> None:
    if _daily_override_boundary.get() is None:
        _override_conflict()


@_owned_daily_override_write
def upsert_daily_output_portion_override(
    *,
    output_date: date,
    facility_id: str,
    menu_name: str,
    diet_type: str | None,
    daypart: str | None,
    menu_category: str | None,
    unit_type: str,
    qty_per_serving: float,
    note: str | None = None,
    updated_by: str | None = None,
    acknowledge_ambiguous: bool = False,
) -> dict[str, Any]:
    _require_daily_output_override_binding()
    editor = _daily_override_boundary.get()[2]
    normalized_diet = daily_output_override_service.normalize_override_diet_type(diet_type) or "unknown"
    target_row = next(
        (
            row
            for row in editor.get("rows") or []
            if str(row.get("facility_id") or "").strip() == facility_id
            and str(row.get("diet_type") or "").strip() == normalized_diet
        ),
        None,
    )
    if target_row is None:
        raise ValueError(
            json.dumps(
                {
                    "code": "daily_output_override_target_not_found",
                    "facility_id": facility_id,
                    "diet_type": normalized_diet,
                },
                ensure_ascii=False,
            )
        )
    if target_row and target_row.get("requires_intervention") and not acknowledge_ambiguous:
        raise ValueError(
            json.dumps(
                {
                    "code": "daily_output_override_ambiguous",
                    "facility_id": facility_id,
                    "diet_type": normalized_diet,
                    "candidates": target_row.get("current_variants") or [],
                },
                ensure_ascii=False,
            )
        )
    override = daily_output_override_service.upsert_override(
        output_date=output_date,
        facility_id=facility_id,
        menu_name=menu_name,
        diet_type=normalized_diet,
        daypart=daypart,
        menu_category=menu_category,
        unit_type=unit_type,
        qty_per_serving=qty_per_serving,
        note=note,
        updated_by=updated_by,
    )
    affected_order_ids = _rebuild_bags_for_override_scope(output_date, facility_id)
    return {
        "override": override,
        "affected_order_ids": affected_order_ids,
    }


@_owned_daily_override_write
def upsert_daily_output_portion_override_bulk(
    *,
    output_date: date,
    menu_name: str,
    daypart: str | None,
    menu_category: str | None,
    unit_type: str,
    qty_per_serving: float,
    note: str | None = None,
    updated_by: str | None = None,
) -> dict[str, Any]:
    _require_daily_output_override_binding()
    editor = _daily_override_boundary.get()[2]
    rows = list(editor.get("rows") or [])
    if not rows:
        raise ValueError(
            json.dumps(
                {
                    "code": "daily_output_override_target_not_found",
                    "menu_name": menu_name,
                    "daypart": str(daypart or ""),
                },
                ensure_ascii=False,
            )
        )
    blocking_rows = [
        {
            "facility_id": str(row.get("facility_id") or "").strip(),
            "facility_label": str(row.get("facility_label") or "").strip(),
            "diet_type": str(row.get("diet_type") or "").strip() or "unknown",
            "candidates": row.get("current_variants") or [],
        }
        for row in rows
        if row.get("requires_intervention")
    ]
    if blocking_rows:
        raise ValueError(
            json.dumps(
                {
                    "code": "daily_output_override_bulk_requires_intervention",
                    "rows": blocking_rows,
                },
                ensure_ascii=False,
            )
        )
    operations = [
        {
            "output_date": output_date,
            "facility_id": str(row.get("facility_id") or "").strip(),
            "menu_name": menu_name,
            "diet_type": row.get("diet_type"),
            "daypart": daypart,
            "menu_category": menu_category,
            "unit_type": unit_type,
            "qty_per_serving": qty_per_serving,
            "note": note,
            "updated_by": updated_by,
        }
        for row in rows
        if str(row.get("facility_id") or "").strip()
    ]
    overrides = daily_output_override_service.upsert_overrides(operations=operations)
    facility_ids = sorted({str(item.get("facility_id") or "").strip() for item in overrides if str(item.get("facility_id") or "").strip()})
    affected_order_ids = _rebuild_bags_for_override_scopes(output_date, facility_ids)
    return {
        "overrides": overrides,
        "affected_order_ids": affected_order_ids,
        "updated_count": len(overrides),
    }


@_owned_daily_override_write
def delete_daily_output_portion_override(override_id: str) -> dict[str, Any] | None:
    _require_daily_output_override_binding()
    deleted = daily_output_override_service.delete_override(override_id)
    if not deleted:
        return None
    output_date = _normalize_entry_date(deleted.get("output_date"))
    facility_id = str(deleted.get("facility_id") or "").strip()
    affected_order_ids: list[str] = []
    if output_date and facility_id:
        affected_order_ids = _rebuild_bags_for_override_scope(output_date, facility_id)
    return {
        "override": deleted,
        "affected_order_ids": affected_order_ids,
    }


def _daily_bag_source_ref_meta(bag: dict[str, Any]) -> dict[str, Any]:
    refs = bag.get("source_refs")
    if not isinstance(refs, list):
        refs = bag.get("_source_refs")
    if not isinstance(refs, list) or not refs:
        return {}

    confidences: list[float] = []
    tiers: list[str] = []
    value_sources: set[str] = set()
    edited_values: set[bool] = set()
    cell_image_ref: str | None = None
    normalized_refs: list[dict[str, Any]] = []
    for ref in refs:
        if not isinstance(ref, dict):
            continue
        normalized_ref = {
            "source_row_index": ref.get("source_row_index"),
            "source_col_index": ref.get("source_col_index"),
            "source_field": ref.get("source_field"),
            "quantity": ref.get("quantity"),
            "value_source": ref.get("value_source"),
            "was_user_edited": ref.get("was_user_edited"),
            "ocr_confidence": ref.get("ocr_confidence"),
            "ocr_confidence_tier": ref.get("ocr_confidence_tier"),
            "cell_image_ref": ref.get("cell_image_ref"),
        }
        normalized_refs.append(normalized_ref)
        confidence = _daily_audit_float(ref.get("ocr_confidence"))
        if confidence is not None:
            confidences.append(confidence)
        tier = str(ref.get("ocr_confidence_tier") or "").strip()
        if tier:
            tiers.append(tier)
        value_source = str(ref.get("value_source") or "").strip()
        if value_source:
            value_sources.add(value_source)
        was_user_edited = ref.get("was_user_edited")
        if isinstance(was_user_edited, bool):
            edited_values.add(was_user_edited)
        if not cell_image_ref:
            candidate_image_ref = str(ref.get("cell_image_ref") or "").strip()
            cell_image_ref = candidate_image_ref or None

    tier_rank = {"low": 0, "weak": 0, "medium": 1, "mid": 1, "high": 2, "strict": 2}
    worst_tier = None
    if tiers:
        worst_tier = min(tiers, key=lambda item: tier_rank.get(str(item).strip().lower(), 99))
    value_source: str | None
    if len(value_sources) == 1:
        value_source = next(iter(value_sources))
    elif len(value_sources) > 1:
        value_source = "mixed"
    else:
        value_source = None
    was_user_edited: bool | None
    if edited_values == {True}:
        was_user_edited = True
    elif edited_values == {False}:
        was_user_edited = False
    elif edited_values:
        was_user_edited = True
    else:
        was_user_edited = None
    return {
        "value_source": value_source,
        "was_user_edited": was_user_edited,
        "ocr_confidence": min(confidences) if confidences else None,
        "ocr_confidence_tier": worst_tier,
        "cell_image_ref": cell_image_ref,
        "source_refs": normalized_refs,
    }


def get_daily_bag_summary(
    target_date: date,
    facility_id: Optional[str] = None,
    status: Optional[str] = None,
    *,
    include_expanded_copy: bool = True,
) -> dict[str, Any]:
    orders = list_orders_by_line_date(target_date, facility_id=facility_id, status=status)
    groups: dict[tuple[str, str], dict[str, Any]] = {}
    from src.services.output_builder import build_bag_payload_for_outputs, build_order_lines_for_outputs

    for order_summary in orders:
        order_id = str(order_summary.get("id") or "").strip()
        if not order_id:
            continue
        order_payload = get_order_by_id(order_id)
        if not isinstance(order_payload, dict):
            continue
        from src.services.output_builder import _accepted_output_candidate
        accepted_candidate = _accepted_output_candidate(order_payload)
        order_lines = build_order_lines_for_outputs(
            order_payload,
            include_expanded_copy=include_expanded_copy,
            accepted_candidate=accepted_candidate,
        )
        amount_stats = _build_daily_bag_amount_stats(order_lines)
        bag_rows = build_bag_payload_for_outputs(order_payload, order_lines=order_lines, accepted_candidate=accepted_candidate)
        if not bag_rows:
            continue
        facility_label = _resolve_facility_label_for_code(
            accepted_candidate["configured_input"]["facility"],
        )

        for bag in bag_rows:
            if _normalize_bag_summary_date(bag.get("date")) != target_date.isoformat():
                continue
            group_daypart = str(bag.get("daypart") or _normalize_daypart_key(bag.get("daypart")) or "-").strip() or "-"
            menu_category = str(_resolve_daily_bag_menu_category(bag, amount_stats) or "-").strip() or "-"
            menu_name = str(bag.get("menu_name") or "-").strip() or "-"
            menu_key = (group_daypart, menu_category, menu_name)
            menu_group = groups.get(menu_key)
            if menu_group is None:
                menu_group = {
                    "daypart": group_daypart,
                    "daypart_key": _normalize_daypart_key(group_daypart),
                    "menu_category": menu_category,
                    "menu_name": menu_name,
                    "diet_groups": {},
                }
                groups[menu_key] = menu_group

            diet_key = bucket_diet_type_for_aggregation(bag.get("diet_type")) or "unknown"
            diet_group = menu_group["diet_groups"].get(diet_key)
            if diet_group is None:
                diet_group = {
                    "diet_type": diet_key,
                    "total_quantity": 0.0,
                    "total_amounts": {},
                    "calculation_basis_labels": set(),
                    "bag_type_groups": {},
                }
                menu_group["diet_groups"][diet_key] = diet_group

            try:
                quantity = float(bag.get("quantity"))
            except (TypeError, ValueError):
                quantity = 0.0
            if math.isfinite(quantity):
                diet_group["total_quantity"] = round(diet_group["total_quantity"] + quantity, 4)

            amount_totals = _resolve_daily_bag_amount_totals(bag, amount_stats)
            _merge_amount_totals(diet_group["total_amounts"], amount_totals)
            basis_label = _resolve_daily_bag_basis_label(bag, amount_stats)
            if basis_label:
                diet_group["calculation_basis_labels"].add(basis_label)

            bag_type_key = _normalize_sheet_text(bag.get("bag_type")).lower() or "standard"
            bag_type_group = diet_group["bag_type_groups"].get(bag_type_key)
            if bag_type_group is None:
                bag_type_group = {
                    "bag_type": bag_type_key,
                    "bag_count": 0,
                    "total_quantity": 0.0,
                    "total_amounts": {},
                    "breakdowns": {},
                }
                diet_group["bag_type_groups"][bag_type_key] = bag_type_group
            bag_type_group["bag_count"] += 1
            if math.isfinite(quantity):
                bag_type_group["total_quantity"] = round(bag_type_group["total_quantity"] + quantity, 4)
            _merge_amount_totals(bag_type_group["total_amounts"], amount_totals)

            amount_label = _format_amount_label(amount_totals) or "計算不可"
            breakdown = bag_type_group["breakdowns"].get(amount_label)
            if breakdown is None:
                breakdown = {
                    "amount_label": amount_label,
                    "count": 0,
                    "order_refs": [],
                }
                bag_type_group["breakdowns"][amount_label] = breakdown
            breakdown["count"] += 1
            breakdown["order_refs"].append(
                {
                    "order_id": order_id,
                    "facility_label": facility_label,
                    "area_id": bag.get("area_id"),
                    "quantity": quantity if math.isfinite(quantity) else None,
                    **_daily_bag_source_ref_meta(bag),
                }
            )

    preferred_diet_order = [
        "regular",
        "soft",
        "mixer",
        "forbidden",
        "tea",
        "business",
        "diabetes",
        "pregnancy",
        "sesame_allergy",
        "change_1",
        "change_2",
        "1600kcal",
        "placeholder",
        "unknown",
    ]
    diet_sort_index = {value: idx for idx, value in enumerate(preferred_diet_order)}
    bag_sort_order = {"large": 0, "medium": 1, "small": 2, "standard": 3, "condiment": 4}

    normalized_groups: list[dict[str, Any]] = []
    for menu_group in groups.values():
        diet_groups: list[dict[str, Any]] = []
        for diet_group in menu_group["diet_groups"].values():
            bag_type_groups: list[dict[str, Any]] = []
            for bag_type_group in diet_group["bag_type_groups"].values():
                breakdowns = list(bag_type_group["breakdowns"].values())
                breakdowns.sort(key=lambda item: (item.get("amount_label") == "計算不可", item.get("amount_label") or ""))
                bag_type_groups.append(
                    {
                        "bag_type": bag_type_group["bag_type"],
                        "bag_count": bag_type_group["bag_count"],
                        "total_quantity": bag_type_group["total_quantity"],
                        "total_amounts": bag_type_group["total_amounts"],
                        "total_amount_label": _format_amount_label(bag_type_group["total_amounts"]),
                        "breakdowns": breakdowns,
                    }
                )
            bag_type_groups.sort(
                key=lambda item: (
                    bag_sort_order.get(str(item.get("bag_type") or ""), 50),
                    str(item.get("bag_type") or ""),
                )
            )
            diet_groups.append(
                {
                    "diet_type": diet_group["diet_type"],
                    "total_quantity": diet_group["total_quantity"],
                    "total_amounts": diet_group["total_amounts"],
                    "total_amount_label": _format_amount_label(diet_group["total_amounts"]),
                    "calculation_basis_label": " / ".join(sorted(diet_group["calculation_basis_labels"]))
                    if diet_group["calculation_basis_labels"]
                    else None,
                    "bag_type_groups": bag_type_groups,
                }
            )
        diet_groups.sort(
            key=lambda item: (
                diet_sort_index.get(str(item.get("diet_type") or ""), 99),
                str(item.get("diet_type") or ""),
            )
        )
        normalized_groups.append(
            {
                "daypart": menu_group["daypart"],
                "daypart_key": menu_group["daypart_key"],
                "menu_category": menu_group["menu_category"],
                "menu_name": menu_group["menu_name"],
                "diet_groups": diet_groups,
            }
        )
    normalized_groups.sort(
        key=lambda item: (
            _daypart_sort_components(item.get("daypart"))[0],
            _daypart_sort_components(item.get("daypart"))[1],
            str(item.get("menu_category") or ""),
            str(item.get("menu_name") or ""),
        )
    )
    return {
        "date": target_date.isoformat(),
        "status": status,
        "facility_id": facility_id,
        "order_count": len(orders),
        "groups": normalized_groups,
    }


def _daily_audit_float(value: object) -> float | None:
    try:
        resolved = float(value)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(resolved):
        return None
    return resolved


def _daily_audit_num_text(value: object) -> str:
    resolved = _daily_audit_float(value)
    if resolved is None:
        return "-"
    if float(resolved).is_integer():
        return str(int(resolved))
    return f"{resolved:.3f}".rstrip("0").rstrip(".")


def _daily_audit_median(values: list[float]) -> float | None:
    cleaned = sorted(value for value in values if math.isfinite(value))
    if not cleaned:
        return None
    midpoint = len(cleaned) // 2
    if len(cleaned) % 2:
        return cleaned[midpoint]
    return (cleaned[midpoint - 1] + cleaned[midpoint]) / 2.0


def _daily_audit_mad(values: list[float], median: float) -> float:
    deviations = [abs(value - median) for value in values if math.isfinite(value)]
    resolved = _daily_audit_median(deviations)
    return float(resolved or 0.0)


def _daily_audit_severity(score: float) -> str:
    if score >= 3.0:
        return "high"
    if score >= 1.75:
        return "medium"
    return "low"


def _daily_audit_gemini_key() -> str:
    return (
        str(os.getenv("GEMINI_API_KEY") or "").strip()
        or str(os.getenv("GOOGLE_API_KEY") or "").strip()
        or str(os.getenv("GOOGLE_GENERATIVE_AI_API_KEY") or "").strip()
    )


def _daily_audit_extract_gemini_text(payload: dict[str, Any]) -> tuple[str, str | None]:
    candidates = payload.get("candidates") if isinstance(payload, dict) else []
    candidate = candidates[0] if isinstance(candidates, list) and candidates and isinstance(candidates[0], dict) else {}
    parts = candidate.get("content", {}).get("parts", []) if isinstance(candidate.get("content"), dict) else []
    text = "".join(str(part.get("text") or "") for part in parts if isinstance(part, dict)).strip()
    finish_reason = str(candidate.get("finishReason") or "").strip() or None
    return text, finish_reason


def _daily_audit_parse_gemini_json(text: str) -> dict[str, Any]:
    raw = str(text or "").strip()
    if raw.startswith("```"):
        fenced = re.search(r"```(?:json)?\s*(.*?)```", raw, flags=re.DOTALL | re.IGNORECASE)
        if fenced:
            raw = fenced.group(1).strip()
    try:
        parsed = json.loads(raw)
        return parsed if isinstance(parsed, dict) else {}
    except json.JSONDecodeError:
        start = raw.find("{")
        end = raw.rfind("}")
        if start >= 0 and end > start:
            parsed = json.loads(raw[start : end + 1])
            return parsed if isinstance(parsed, dict) else {}
        raise


def _daily_audit_fallback_ai_items(findings: list[dict[str, Any]]) -> list[dict[str, str]]:
    items: list[dict[str, str]] = []
    for finding in findings[:16]:
        finding_id = str(finding.get("finding_id") or "").strip()
        if not finding_id:
            continue
        severity = str(finding.get("severity") or "medium").strip().lower()
        priority = "high" if severity == "high" else ("medium" if severity == "medium" else "low")
        summary = str(finding.get("message") or finding.get("title") or "数量確認候補です。").strip()
        action = str(
            finding.get("suggested_action")
            or "日別出力の施設別内訳と元注文シートを確認してください。"
        ).strip()
        items.append(
            {
                "finding_id": finding_id,
                "priority": priority,
                "summary": summary[:120],
                "operator_action": action[:120],
            }
        )
    return items


def _daily_audit_compact_gemini_findings(findings: list[dict[str, Any]]) -> list[dict[str, Any]]:
    compact: list[dict[str, Any]] = []
    for finding in findings[:16]:
        target = finding.get("target") if isinstance(finding.get("target"), dict) else {}
        compact.append(
            {
                "id": str(finding.get("finding_id") or "").strip(),
                "severity": str(finding.get("severity") or "").strip(),
                "rule": str(finding.get("rule_code") or "").strip(),
                "message": str(finding.get("message") or finding.get("title") or "").strip()[:160],
                "action": str(finding.get("suggested_action") or "").strip()[:120],
                "target": {
                    key: target.get(key)
                    for key in ("daypart", "menu_name", "diet_type", "quantity", "facility_label", "order_id")
                    if target.get(key) not in (None, "")
                },
            }
        )
    return compact


def _daily_audit_run_gemini(*, findings: list[dict[str, Any]], target_date: date) -> dict[str, Any]:
    api_key = _daily_audit_gemini_key()
    if not api_key:
        return {
            "status": "unavailable",
            "error": "gemini_api_key_missing",
            "items": [],
        }
    if not findings:
        return {
            "status": "skipped",
            "items": [],
        }
    model = str(os.getenv("DAILY_OUTPUT_AUDIT_GEMINI_MODEL") or "gemini-2.5-flash").strip()
    timeout = _daily_audit_float(os.getenv("DAILY_OUTPUT_AUDIT_GEMINI_TIMEOUT_SECONDS")) or 120.0
    clipped_findings = findings[:16]
    max_tokens = int(_daily_audit_float(os.getenv("DAILY_OUTPUT_AUDIT_GEMINI_MAX_TOKENS")) or 1024)
    retry_max_tokens = int(_daily_audit_float(os.getenv("DAILY_OUTPUT_AUDIT_GEMINI_RETRY_MAX_TOKENS")) or 2048)
    if retry_max_tokens < max_tokens:
        retry_max_tokens = max_tokens
    system_prompt = (
        "You are a quantity audit assistant for Japanese meal order daily output.\n"
        "Use only the provided rule-based findings and daily-output quantities.\n"
        "Do not invent hidden source data. Do not treat OCR as ground truth.\n"
        "Return exactly one minified JSON object. Do not repeat the schema. Do not use markdown.\n"
        "For every input finding, return exactly one item with the same finding_id.\n"
        "Keep summary and operator_action under 35 Japanese characters each.\n"
        'JSON shape: {"items":[{"finding_id":"id","priority":"high|medium|low","summary":"短文","operator_action":"短文"}],"notes":""}.'
    )
    user_payload = {
        "date": target_date.isoformat(),
        "findings": _daily_audit_compact_gemini_findings(clipped_findings),
    }
    body = {
        "system_instruction": {"parts": [{"text": system_prompt}]},
        "contents": [
            {
                "parts": [
                    {
                        "text": (
                            "Create concise operator guidance for these findings. "
                            "Output JSON only.\n"
                            f"{json.dumps(user_payload, ensure_ascii=False, separators=(',', ':'))}"
                        )
                    }
                ]
            }
        ],
        "generationConfig": {
            "temperature": 0,
            "maxOutputTokens": max_tokens,
            "responseMimeType": "application/json",
        },
    }
    parse_errors: list[str] = []
    attempts: list[dict[str, Any]] = []
    for attempt, attempt_tokens in enumerate([max_tokens, retry_max_tokens], start=1):
        body["generationConfig"]["maxOutputTokens"] = attempt_tokens
        request = urllib.request.Request(
            f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent?key={api_key}",
            data=json.dumps(body).encode("utf-8"),
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        try:
            with urllib.request.urlopen(request, timeout=timeout) as response:
                raw = response.read().decode("utf-8")
        except (TimeoutError, socket.timeout):
            return {"status": "failed", "error": f"gemini_timeout_after_{timeout:.0f}s", "items": []}
        except urllib.error.HTTPError as exc:
            try:
                detail = exc.read().decode("utf-8")
            except Exception:
                detail = str(exc)
            return {"status": "failed", "error": f"gemini_http_{exc.code}", "detail": detail[:1000], "items": []}
        except Exception as exc:  # noqa: BLE001
            return {"status": "failed", "error": str(exc), "items": []}
        try:
            parsed_response = json.loads(raw)
            text, finish_reason = _daily_audit_extract_gemini_text(parsed_response)
            attempts.append(
                {
                    "attempt": attempt,
                    "max_output_tokens": attempt_tokens,
                    "finish_reason": finish_reason,
                    "response_chars": len(text),
                }
            )
            payload = _daily_audit_parse_gemini_json(text) if text else {}
            return {
                "status": "completed",
                "model": model,
                "items": payload.get("items") if isinstance(payload.get("items"), list) else [],
                "notes": str(payload.get("notes") or "").strip(),
                "attempts": attempts,
            }
        except Exception as exc:  # noqa: BLE001
            parse_errors.append(str(exc))
            finish_reason = attempts[-1].get("finish_reason") if attempts else None
            truncated = str(finish_reason or "").upper() in {"MAX_TOKENS", "LENGTH", "STOP_SEQUENCE"}
            if attempt == 1 and truncated and retry_max_tokens > attempt_tokens:
                continue
            if truncated:
                return {
                    "status": "completed",
                    "model": model,
                    "items": _daily_audit_fallback_ai_items(clipped_findings),
                    "notes": "Gemini応答が途中で切れたため、ルールベース監査の要約で補助欄を生成しました。",
                    "attempts": attempts,
                    "fallback_reason": "gemini_output_truncated",
                }
            break
    return {
        "status": "failed",
        "error": "gemini_output_invalid",
        "detail": "; ".join(parse_errors)[-1000:],
        "items": [],
        "attempts": attempts,
    }


def get_daily_bag_audit(
    target_date: date,
    facility_id: Optional[str] = None,
    status: Optional[str] = None,
    *,
    use_ai: bool = False,
    summary: dict[str, Any] | None = None,
) -> dict[str, Any]:
    try:
        if summary is None:
            summary = get_daily_bag_summary(
                target_date,
                facility_id=facility_id,
                status=status,
                include_expanded_copy=False,
            )
    except ValueError as exc:
        detail = str(exc)
        return {
            "date": target_date.isoformat(),
            "status": status,
            "facility_id": facility_id,
            "source": "daily_bag_summary",
            "rule_based": {
                "status": "blocked",
                "error": "daily_bag_summary_blocked",
                "detail": detail,
                "finding_count": 0,
                "cell_count": 0,
                "summary_by_severity": {"high": 0, "medium": 0, "low": 0},
                "summary_by_rule": {},
                "findings": [],
            },
            "ai": {
                "status": "blocked",
                "error": "daily_bag_summary_blocked",
                "detail": detail,
                "items": [],
            },
        }
    groups = summary.get("groups") if isinstance(summary.get("groups"), list) else []
    findings: list[dict[str, Any]] = []
    cells: list[dict[str, Any]] = []
    group_totals_by_diet: dict[str, list[tuple[str, float]]] = {}
    facility_values_by_key: dict[tuple[str, str, str], list[float]] = {}

    for group_index, group in enumerate(groups):
        daypart = str(group.get("daypart") or group.get("daypart_key") or "-").strip() or "-"
        category = str(group.get("menu_category") or "-").strip() or "-"
        menu_name = str(group.get("menu_name") or "-").strip() or "-"
        group_key = f"{daypart}::{category}::{menu_name}"
        for diet in group.get("diet_groups") or []:
            diet_type = bucket_diet_type_for_aggregation(diet.get("diet_type")) or "unknown"
            total_quantity = _daily_audit_float(diet.get("total_quantity")) or 0.0
            group_totals_by_diet.setdefault(diet_type, []).append((group_key, total_quantity))
            facility_totals: dict[tuple[str, str], dict[str, Any]] = {}
            for bag_type_group in diet.get("bag_type_groups") or []:
                for breakdown in bag_type_group.get("breakdowns") or []:
                    for order_ref in breakdown.get("order_refs") or []:
                        if not isinstance(order_ref, dict):
                            continue
                        quantity = _daily_audit_float(order_ref.get("quantity"))
                        if quantity is None:
                            continue
                        order_id = str(order_ref.get("order_id") or "").strip()
                        facility_label = str(order_ref.get("facility_label") or "").strip()
                        area_id = str(order_ref.get("area_id") or "").strip()
                        facility_key = facility_label or order_id or "unknown"
                        bucket = facility_totals.setdefault(
                            (facility_key, order_id),
                            {
                                "facility_label": facility_label,
                                "order_id": order_id,
                                "quantity": 0.0,
                                "areas": set(),
                                "value_source": str(order_ref.get("value_source") or "").strip(),
                                "was_user_edited": order_ref.get("was_user_edited"),
                                "ocr_confidence": order_ref.get("ocr_confidence"),
                                "ocr_confidence_tier": order_ref.get("ocr_confidence_tier"),
                                "cell_image_ref": order_ref.get("cell_image_ref"),
                                "source_refs": order_ref.get("source_refs") if isinstance(order_ref.get("source_refs"), list) else [],
                            },
                        )
                        bucket["quantity"] = round(float(bucket.get("quantity") or 0.0) + quantity, 4)
                        if area_id:
                            bucket["areas"].add(area_id)
                        current_confidence = _daily_audit_float(bucket.get("ocr_confidence"))
                        next_confidence = _daily_audit_float(order_ref.get("ocr_confidence"))
                        if next_confidence is not None and (
                            current_confidence is None or next_confidence < current_confidence
                        ):
                            bucket["ocr_confidence"] = next_confidence
                            bucket["ocr_confidence_tier"] = order_ref.get("ocr_confidence_tier")
                        if isinstance(order_ref.get("source_refs"), list):
                            bucket["source_refs"].extend(order_ref.get("source_refs") or [])
            for (_facility_key, _order_id), bucket in facility_totals.items():
                quantity = float(bucket.get("quantity") or 0.0)
                cell = {
                    "cell_id": f"daily-audit-{group_index}-{diet_type}-{len(cells)}",
                    "date": target_date.isoformat(),
                    "daypart": daypart,
                    "menu_category": category,
                    "menu_name": menu_name,
                    "diet_type": diet_type,
                    "facility_label": bucket.get("facility_label") or "",
                    "order_id": bucket.get("order_id") or "",
                    "area_ids": sorted(str(item) for item in (bucket.get("areas") or set()) if str(item).strip()),
                    "quantity": quantity,
                    "value_source": bucket.get("value_source") or None,
                    "was_user_edited": bucket.get("was_user_edited"),
                    "ocr_confidence": bucket.get("ocr_confidence"),
                    "ocr_confidence_tier": bucket.get("ocr_confidence_tier"),
                    "cell_image_ref": bucket.get("cell_image_ref"),
                    "source_refs": bucket.get("source_refs") or [],
                }
                cells.append(cell)
                facility_values_by_key.setdefault((str(cell["facility_label"]), diet_type, daypart), []).append(quantity)

    finding_seq = 0

    def add_finding(
        *,
        rule_code: str,
        severity: str,
        title: str,
        message: str,
        score: float,
        target: dict[str, Any],
        reference_values: list[str] | None = None,
        suggested_action: str | None = None,
    ) -> None:
        nonlocal finding_seq
        finding_seq += 1
        findings.append(
            {
                "finding_id": f"daily-audit-{finding_seq}",
                "rule_code": rule_code,
                "severity": severity,
                "title": title,
                "message": message,
                "score": round(float(score), 4),
                "target": target,
                "reference_values": reference_values or [],
                "suggested_action": suggested_action or "日別出力の施設別内訳と元注文シートを確認してください。",
            }
        )

    for diet_type, values in group_totals_by_diet.items():
        quantities = [value for _key, value in values if value > 0]
        if len(quantities) < 3:
            continue
        median = _daily_audit_median(quantities)
        if median is None or median <= 0:
            continue
        mad = _daily_audit_mad(quantities, median)
        tolerance = max(6.0, mad * 3.0, median * 0.08)
        for group_key, quantity in values:
            if quantity <= 0:
                continue
            delta = abs(quantity - median)
            if delta <= tolerance:
                continue
            daypart, category, menu_name = group_key.split("::", 2)
            score = delta / max(tolerance, 1.0)
            add_finding(
                rule_code="same_day_diet_total_outlier",
                severity=_daily_audit_severity(score),
                title="同日同区分の合計から外れています",
                message=(
                    f"{daypart} / {menu_name} / {diet_type} が {_daily_audit_num_text(quantity)}。"
                    f"同日同区分の中央値 {_daily_audit_num_text(median)} から外れています。"
                ),
                score=score,
                target={
                    "date": target_date.isoformat(),
                    "daypart": daypart,
                    "menu_category": category,
                    "menu_name": menu_name,
                    "diet_type": diet_type,
                    "quantity": quantity,
                },
                reference_values=[_daily_audit_num_text(value) for value in quantities[:12]],
            )

    for (facility_label, diet_type, daypart), quantities in facility_values_by_key.items():
        positive_values = [value for value in quantities if value > 0]
        if len(positive_values) < 3:
            continue
        median = _daily_audit_median(positive_values)
        if median is None or median <= 0:
            continue
        tolerance = max(5.0, _daily_audit_mad(positive_values, median) * 3.0, median * 0.25)
        for cell in cells:
            if (
                cell.get("facility_label") != facility_label
                or cell.get("diet_type") != diet_type
                or cell.get("daypart") != daypart
            ):
                continue
            quantity = _daily_audit_float(cell.get("quantity")) or 0.0
            delta = abs(quantity - median)
            if quantity <= 0 or delta <= tolerance:
                continue
            score = delta / max(tolerance, 1.0)
            add_finding(
                rule_code="facility_same_day_outlier",
                severity=_daily_audit_severity(score),
                title="同施設内の数量から外れています",
                message=(
                    f"{facility_label} / {daypart} / {cell.get('menu_name')} / {diet_type} が"
                    f" {_daily_audit_num_text(quantity)}。同施設同日同区分の中央値"
                    f" {_daily_audit_num_text(median)} から外れています。"
                ),
                score=score,
                target=cell,
                reference_values=[_daily_audit_num_text(value) for value in positive_values[:12]],
                suggested_action="この施設の該当セルをFAX cropまたは注文シートで確認してください。",
            )

    for cell in cells:
        value_source = str(cell.get("value_source") or "").strip().lower()
        was_user_edited = cell.get("was_user_edited")
        confidence = _daily_audit_float(cell.get("ocr_confidence"))
        if value_source not in {"ocr", "hakodate", "ocr_adopted"}:
            continue
        if was_user_edited is True:
            continue
        if confidence is None or confidence >= 0.35:
            continue
        score = 1.0 + (0.35 - confidence) * 4.0
        add_finding(
            rule_code="low_confidence_unedited_ocr",
            severity=_daily_audit_severity(score),
            title="低信頼OCR値が未編集のまま採用されています",
            message=(
                f"{cell.get('facility_label') or cell.get('order_id')} / {cell.get('daypart')} / "
                f"{cell.get('menu_name')} / {cell.get('diet_type')} のOCR信頼度が {confidence:.2f} です。"
            ),
            score=score,
            target=cell,
            reference_values=[f"ocr_confidence={confidence:.2f}"],
            suggested_action="OCR値をそのまま採用したセルです。FAX画像とシート値を確認してください。",
        )

    findings.sort(
        key=lambda item: (
            {"high": 0, "medium": 1, "low": 2}.get(str(item.get("severity") or ""), 9),
            -float(item.get("score") or 0.0),
            str(item.get("rule_code") or ""),
        )
    )
    ai = _daily_audit_run_gemini(findings=findings, target_date=target_date) if use_ai else {
        "status": "not_requested",
        "items": [],
    }
    summary_by_severity: dict[str, int] = {"high": 0, "medium": 0, "low": 0}
    summary_by_rule: dict[str, int] = {}
    for finding in findings:
        severity = str(finding.get("severity") or "low")
        summary_by_severity[severity] = summary_by_severity.get(severity, 0) + 1
        rule_code = str(finding.get("rule_code") or "unknown")
        summary_by_rule[rule_code] = summary_by_rule.get(rule_code, 0) + 1
    return {
        "date": target_date.isoformat(),
        "status": status,
        "facility_id": facility_id,
        "source": "daily_bag_summary",
        "rule_based": {
            "status": "completed",
            "finding_count": len(findings),
            "cell_count": len(cells),
            "summary_by_severity": summary_by_severity,
            "summary_by_rule": summary_by_rule,
            "findings": findings[:120],
        },
        "ai": ai,
    }


def get_bag_summary(order_id: str):
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return None, "order_not_found"
        bags = (
            session.execute(select(Bag).where(Bag.order_id == order_id))
            .scalars()
            .all()
        )
        payload = [
            {
                "id": bag.id,
                "confirmed_snapshot_id": bag.confirmed_snapshot_id,
                "output_bundle_id": bag.output_bundle_id,
                "source_saved_sheet_id": bag.source_saved_sheet_id,
                "template_version_id": bag.template_version_id,
                "date": bag.date.isoformat() if bag.date else None,
                "daypart": bag.daypart,
                "menu_name": bag.menu_name,
                "diet_type": bag.diet_type,
                "area_id": bag.area_id,
                "bag_type": bag.bag_type,
                "quantity": bag.quantity,
            }
            for bag in bags
        ]
    should_rebuild = False
    rebuild_reason: str | None = None
    order_payload = get_order_by_id(order_id)
    applied_overrides: list[dict[str, Any]] = []
    order_lines: list[dict[str, Any]] | None = None
    accepted_candidate = None
    if isinstance(order_payload, dict):
        from src.services.output_builder import _accepted_output_candidate
        accepted_candidate = _accepted_output_candidate(order_payload)
        should_rebuild, rebuild_reason = _bag_summary_requires_rebuild(order_payload, payload, accepted_candidate=accepted_candidate)
        try:
            from src.services.output_builder import build_order_lines_for_outputs
            order_lines = build_order_lines_for_outputs(order_payload, accepted_candidate=accepted_candidate)
            applied_overrides = daily_output_override_service.collect_applied_override_summaries(order_lines)
        except ValueError:
            raise
        except Exception:
            applied_overrides = []
    elif not payload:
        should_rebuild = True
        rebuild_reason = "missing_bags"
    if should_rebuild:
        # Read paths should not materialize or rewrite Bag rows.
        # Serve a transient payload from current order lines instead.
        try:
            from src.services.output_builder import build_bag_payload_for_outputs, build_order_lines_for_outputs

            if isinstance(order_payload, dict):
                if order_lines is None:
                    order_lines = build_order_lines_for_outputs(order_payload, accepted_candidate=accepted_candidate)
                payload = build_bag_payload_for_outputs(order_payload, order_lines=order_lines, accepted_candidate=accepted_candidate)
            logger.info(
                "Bag summary served from transient lines",
                order_id=order_id,
                reason=rebuild_reason,
                bag_count=len(payload),
            )
        except ValueError:
            raise
        except Exception as exc:  # noqa: BLE001
            logger.warning(
                "Bag transient rebuild failed",
                order_id=order_id,
                reason=rebuild_reason,
                error=str(exc),
            )
    payload.sort(
        key=lambda row: (
            row.get("date") or "",
            row.get("daypart") or "",
            row.get("menu_name") or "",
            row.get("diet_type") or "",
            row.get("area_id") or "",
            row.get("bag_type") or "",
        )
    )
    return {
        "order_id": order_id,
        "generated": bool(payload),
        "bags": payload,
        "applied_portion_overrides": applied_overrides,
    }, None


def _load_cached_ocr(message_id: Optional[str]) -> Optional[dict]:
    if not message_id:
        return None
    candidates = []
    dump_dir = os.getenv("OCR_DEBUG_DUMP_DIR")
    if dump_dir:
        candidates.append(Path(dump_dir))
    candidates.append(Path(__file__).resolve().parents[1] / "tmp")
    for base in candidates:
        path = base / f"ocr_{message_id}.json"
        if path.exists():
            try:
                return json.loads(path.read_text(encoding="utf-8"))
            except Exception:  # noqa: BLE001
                return None
    return None


def _load_pipeline_raw_text(order_id: str, message_id: Optional[str]) -> Optional[str]:
    _ = message_id
    execution = current_nonworkflow_execution() or {}
    job_id = _workflow_ocr_job_id.get() or execution.get("job_id")
    captured_order_id = _workflow_ocr_order_id.get() or execution.get("order_id")
    if not job_id or captured_order_id != order_id:
        return None
    job = get_ocr_job(job_id)
    if not job:
        return None
    output_ref = job.get("output_reference")
    if not output_ref:
        return None
    try:
        payload = load_bytes_from_uri(output_ref)
        parsed = json.loads(payload.decode("utf-8"))
        validate_own_pipeline_result(parsed, output_ref)
    except Exception:  # noqa: BLE001
        return None
    table_raw = parsed.get("table_raw")
    if isinstance(table_raw, str) and table_raw.strip():
        return table_raw
    try:
        return json.dumps(parsed, ensure_ascii=False, indent=2)
    except TypeError:
        return None


def _payload_has_hakodate_target_cells(payload: dict[str, Any]) -> bool:
    return bool(_extract_hakodate_target_cells_from_payload(payload))


def _payload_has_hakodate_evidence_records(payload: dict[str, Any], *, order_id: str) -> bool:
    return bool(_extract_hakodate_ocr_evidence_records_from_payload(payload, order_id=order_id))


def _hakodate_owned_source(configured_input, pdf_receipt, synchronous_write_input=None, *, original_input=None):
    execution = current_nonworkflow_execution() or {}
    start = original_input if original_input is not None else synchronous_write_input if synchronous_write_input is not None else processing_start_read_input()
    entries = start.get("physical_menu_entries")
    order = (start.get("input_versions") or {}).get("order") if "input_versions" in start else start.get("order")
    if not isinstance(order, dict) or not snapshots_equal(start.get("configured_input"), configured_input) or not isinstance(entries, list) or not entries:
        raise ValueError("hakodate_original_expectation_required")
    from src.services.hakodate_step_review_pipeline_service import canonical_target_semantics
    plan = hakodate_cell_ocr_batch_service.capture_original_target_plan(configured_input=configured_input, physical_menu_entries=entries, week_code=order["week_code"])
    expected = hakodate_cell_ocr_batch_service.expected_sheet_cells_from_target_regions(plan)
    semantics = _json_snapshot(canonical_target_semantics(plan))
    if "expected_sheet_cells" in start or "expected_target_semantics" in start:
        if not snapshots_equal(start.get("expected_sheet_cells"), expected) or not snapshots_equal(start.get("expected_target_semantics"), semantics) or not snapshots_equal(start.get("selected_pdf_receipt"), pdf_receipt):
            raise ValueError("hakodate_original_expectation_changed")
    return {"selected_pdf_receipt": _json_snapshot(pdf_receipt), "page": _authored_geometry_page(configured_input), "configured_input_digest": hashlib.sha256(canonical_snapshot_json(configured_input).encode()).hexdigest(), "physical_menu_digest": hashlib.sha256(canonical_snapshot_json(entries).encode()).hexdigest(), "expected_sheet_cells": expected, "expected_target_semantics": semantics, "job_id": _workflow_ocr_job_id.get() or execution.get("job_id"), "execution_id": execution.get("execution_id"), "workflow_attempt_id": _workflow_ocr_attempt_id.get(), "workflow_revision": (synchronous_write_input or {}).get("workflow_revision", _workflow_ocr_revision.get()), "evidence_run_id": (synchronous_write_input or {}).get("evidence_run_id")}


def _validate_hakodate_target_identities(targets):
    from openpyxl.utils.cell import coordinate_from_string, column_index_from_string
    for target in targets:
        try:
            column, row = coordinate_from_string(target["sheet_cell"])
        except (KeyError, TypeError, ValueError):
            raise ValueError("hakodate_target_identity_invalid")
        if type(target.get("worksheet_row")) is not int or type(target.get("worksheet_col")) is not int or target["worksheet_row"] != row or target["worksheet_col"] != column_index_from_string(column):
            raise ValueError("hakodate_target_identity_invalid")
        bbox = target.get("bbox")
        if not isinstance(bbox, list) or len(bbox) != 4 or any(type(value) not in {int, float} or not math.isfinite(value) for value in bbox):
            raise ValueError("hakodate_target_geometry_invalid")


def _validate_hakodate_recognition_review(payload, records, verified_inputs):
    from io import BytesIO
    from PIL import Image
    from src.services.hakodate_recognizer_input_evidence import contact_crop_evidence
    originals = json.loads(verified_inputs["records"])
    if not isinstance(originals, list) or any(not isinstance(row, dict) for row in originals):
        raise ValueError("hakodate_recognizer_input_evidence_invalid")
    if "hakodate_recognition_review" in payload:
        review = payload["hakodate_recognition_review"]
        if not isinstance(review, dict) or type(review.get("count")) is not int or not isinstance(review.get("cells"), list):
            raise ValueError("hakodate_recognition_review_invalid")
    has_input = any("recognizer_input_evidence" in row for row in originals)
    has_payload_input = any("recognizer_input_evidence" in (row.get("engine_metadata", {}).get("recognizer_output") or {}) for row in records)
    if not has_input and not has_payload_input:
        # Older artifacts do not establish pixel evidence.
        if "hakodate_recognition_review" in payload and payload["hakodate_recognition_review"] != {"cells": [], "count": 0}:
            raise ValueError("hakodate_recognition_review_invalid")
        return
    by_cell = {row.get("sheet_cell"): row for row in originals}
    if len(by_cell) != len(originals) or len(originals) != len(records):
        raise ValueError("hakodate_recognizer_input_evidence_invalid")
    contact_bytes = verified_inputs["contact_sheet"]
    with Image.open(BytesIO(contact_bytes)) as contact:
        for record in records:
            metadata = record.get("engine_metadata") or {}
            original = by_cell.get(metadata.get("sheet_cell"))
            if not isinstance(original, dict):
                raise ValueError("hakodate_recognizer_input_evidence_invalid")
            if metadata.get("source") == "operator":
                if metadata.get("operator_output") != original:
                    raise ValueError("recognition_operator_record_mismatch")
                continue
            if metadata.get("recognizer_output") != original:
                raise ValueError("hakodate_recognizer_input_evidence_changed")
            evidence = original.get("recognizer_input_evidence")
            hakodate_ocr_evidence_service.recognition_input_issue(original)
            if not isinstance(evidence, dict):
                raise ValueError("hakodate_recognizer_input_evidence_invalid")
            x0, y0, x1, y1 = evidence["bbox"]
            observed = contact_crop_evidence(contact, [[x0, y0], [x1, y0], [x1, y1], [x0, y1]])
            if evidence != observed or original.get("ocr_contact_crop_box") != evidence["bbox"]:
                raise ValueError("hakodate_recognizer_input_evidence_changed")
    expected = hakodate_ocr_evidence_service.recognition_review(records)
    if payload.get("hakodate_recognition_review") != expected:
        raise ValueError("hakodate_recognition_review_invalid")


def _validate_hakodate_owned_artifacts(payload, expected_source, *, allow_review=False):
    source = payload.get("hakodate_repair_source_receipt") if isinstance(payload, dict) else None
    if not isinstance(source, dict) or not snapshots_equal(source, expected_source):
        raise ValueError("hakodate_artifact_source_mismatch")
    pipeline = payload.get("hakodate_canonical_pipeline") or {}
    review = payload.get("hakodate_recognition_review")
    review_outcome = (allow_review and isinstance(review, dict)
                     and type(review.get("count")) is int and review["count"] > 0
                     and isinstance(pipeline, dict) and pipeline.get("status") == "blocked")
    if not isinstance(pipeline, dict) or (pipeline.get("status") != "ready" and not review_outcome) or pipeline.get("version") != HAKODATE_CANONICAL_PIPELINE_VERSION:
        raise ValueError("hakodate_canonical_outcome_required")
    expected = pipeline.get("expected_sheet_cells")
    if not snapshots_equal(expected_source.get("expected_sheet_cells"), expected):
        raise ValueError("hakodate_expected_cells_changed")
    if not isinstance(expected, list) or not expected or any(not isinstance(cell, str) or not cell for cell in expected) or len(set(expected)) != len(expected):
        raise ValueError("hakodate_expected_cells_missing")
    targets = _extract_hakodate_target_cells_from_payload(payload)
    _validate_hakodate_target_identities(targets)
    from src.services.hakodate_step_review_pipeline_service import canonical_target_semantics
    if any(not isinstance(cell.get("metadata"), dict) for cell in targets):
        raise ValueError("hakodate_target_semantics_changed")
    regions = [{**cell.get("metadata", {}), "sheet_cell": cell.get("sheet_cell"), "worksheet_row": cell.get("worksheet_row"), "worksheet_col": cell.get("worksheet_col"), "field": cell.get("semantic_field")} for cell in targets]
    if not expected_source.get("expected_target_semantics") or not snapshots_equal(canonical_target_semantics(regions), expected_source["expected_target_semantics"]):
        raise ValueError("hakodate_target_semantics_changed")
    preprocessing = payload.get("hakodate_preprocessing") or {}
    if not isinstance(preprocessing, dict):
        raise ValueError("hakodate_own_artifact_invalid")
    evidence_container = payload.get("hakodate_ocr_evidence") or {}
    if not isinstance(evidence_container, dict):
        raise ValueError("hakodate_own_artifact_invalid")
    raw_records = _first_hakodate_payload_list(payload, [("hakodate_ocr_evidence", "records"), ("hakodate_ocr_evidence_records",)])
    record_evidence_ids = [record.get("evidence_id") for record in raw_records]
    if any(not isinstance(identity, str) or not identity for identity in record_evidence_ids) or len(set(record_evidence_ids)) != len(record_evidence_ids):
        raise ValueError("hakodate_own_record_identity_missing")
    records = _extract_hakodate_ocr_evidence_records_from_payload(payload, order_id=expected_source["selected_pdf_receipt"]["order_id"])
    recognizer_regions = []
    for record in records:
        metadata = record.get("engine_metadata") or {}
        if metadata.get("source") == "operator":
            authored = metadata.get("operator_output")
            if (not metadata.get("edited_by") or not isinstance(authored, dict)
                    or authored.get("recognition_source") != "operator"
                    or authored.get("operator_value") != record.get("raw_text")):
                raise ValueError("recognition_operator_record_mismatch")
            recognizer_regions.append(authored)
        else:
            recognizer_regions.append(metadata.get("recognizer_output"))
    if not snapshots_equal(canonical_target_semantics(recognizer_regions), expected_source["expected_target_semantics"]):
        raise ValueError("hakodate_record_semantics_changed")
    target_ids = [cell.get("sheet_cell") for cell in targets]
    record_ids = [(record.get("engine_metadata") or {}).get("sheet_cell") for record in records]
    if len(target_ids) != len(expected) or len(record_ids) != len(expected) or set(target_ids) != set(expected) or set(record_ids) != set(expected):
        raise ValueError("hakodate_own_artifacts_incomplete")
    from src.services.hakodate_source_receipt import validate_receipts
    validate_receipts(
        [cell.get("source_receipt") for cell in targets]
        + [(record.get("engine_metadata") or {}).get("source_receipt") for record in records],
        source,
    )
    from src.services import canonical_ocr_artifact_service
    verified_inputs = canonical_ocr_artifact_service.validate_payload(payload)
    _validate_hakodate_recognition_review(payload, records, verified_inputs)
    if not allow_review and isinstance(review, dict) and review.get("count", 0) > 0:
        raise ValueError("hakodate_ocr_quantity_unresolved")


def _validate_selected_hakodate_artifacts(evidence, captured):
    """Validate an explicitly selected persisted result, not the new command's job."""
    payload = evidence.get("payload_json") if isinstance(evidence, dict) else None
    source = (payload or {}).get("hakodate_repair_source_receipt")
    execution = (payload or {}).get("_ocr_execution")
    if not isinstance(source, dict) or not isinstance(execution, dict) or execution.get("evidence_run_id") != evidence.get("id"):
        raise ValueError("hakodate_selected_evidence_lineage_missing")
    original_source = (evidence.get("artifact_manifest_json") or {}).get("original_hakodate_source")
    if not isinstance(original_source, dict):
        raise ValueError("hakodate_original_expectation_required")
    _validate_hakodate_owned_artifacts(payload, original_source)
    original = execution.get("processing_start_input")
    if not isinstance(original, dict) or not snapshots_equal(original.get("physical_menu_entries"), captured.get("physical_menu_entries")):
        raise ValueError("hakodate_original_expectation_required")
    expected = _hakodate_owned_source(captured["configured_input"], captured["selected_pdf_receipt"], original_input=original)
    for key in ("selected_pdf_receipt", "page", "configured_input_digest", "physical_menu_digest", "expected_sheet_cells", "expected_target_semantics"):
        if not snapshots_equal(source.get(key), expected[key]):
            raise ValueError("hakodate_artifact_source_mismatch")
    for source_key, execution_key in (("job_id", "job_id"), ("execution_id", "nonworkflow_execution_id"), ("workflow_attempt_id", "workflow_attempt_id"), ("workflow_revision", "workflow_revision")):
        if not snapshots_equal(source.get(source_key), execution.get(execution_key)):
            raise ValueError("hakodate_selected_evidence_lineage_mismatch")
    if not source.get("job_id") or not (source.get("execution_id") or source.get("workflow_attempt_id")):
        raise ValueError("hakodate_selected_evidence_lineage_missing")
    _validate_hakodate_owned_artifacts(payload, {**source, "physical_menu_digest": expected["physical_menu_digest"], "expected_sheet_cells": expected["expected_sheet_cells"]})


def _validate_hakodate_original_execution(payload):
    execution = payload.get("_ocr_execution") if isinstance(payload, dict) else None
    start = execution.get("processing_start_input") if isinstance(execution, dict) else None
    if not isinstance(start, dict) or not isinstance(start.get("configured_input"), dict) or not execution.get("job_id"):
        raise ValueError("hakodate_original_expectation_required")
    expected = _hakodate_owned_source(start["configured_input"], execution.get("selected_pdf_receipt"), original_input=start)
    expected.update(job_id=execution["job_id"], execution_id=execution.get("nonworkflow_execution_id"), workflow_attempt_id=execution.get("workflow_attempt_id"), workflow_revision=execution.get("workflow_revision"), evidence_run_id=start.get("evidence_run_id"))
    _validate_hakodate_owned_artifacts(payload, expected)


def _classify_owned_evidence_payload(payload):
    expected = None
    if isinstance(payload, dict) and isinstance(payload.get("hakodate_canonical_pipeline"), dict) and payload.get("_ocr_execution") is None:
        expected = _hakodate_owned_source(processing_start_configured_input(), processing_start_pdf_receipt())
    return ocr_evidence_service.classify_evidence_payload(payload, expected_hakodate_source=expected)


def _payload_has_current_hakodate_canonical_pipeline(payload: dict[str, Any] | None) -> bool:
    if not isinstance(payload, dict):
        return False
    pipeline = payload.get("hakodate_canonical_pipeline")
    if not isinstance(pipeline, dict):
        return False
    version = str(pipeline.get("version") or "").strip()
    return version == HAKODATE_CANONICAL_PIPELINE_VERSION


def _hakodate_version_matches_current(value: object) -> bool:
    version = str(value or "").strip()
    return version == HAKODATE_CANONICAL_PIPELINE_VERSION


def _payload_has_hakodate_output_content(payload: dict[str, Any] | None, *, order_id: str) -> bool:
    if not isinstance(payload, dict):
        return False
    if _payload_has_hakodate_target_cells(payload):
        return True
    if _payload_has_hakodate_evidence_records(payload, order_id=order_id):
        return True
    return isinstance(payload.get("hakodate_overlay"), dict)


def _hakodate_document_context(order_id: str) -> dict[str, Any] | None:
    try:
        with session_scope() as session:
            order = session.get(Order, order_id)
            if not order:
                return None
            document_uri = str(order.document_uri or "").strip()
            if not document_uri:
                return None
            return {
                "document_uri": document_uri,
                "facility_id": str(order.facility_code or "").strip() or None,
                "week_id": str(order.week_code or "").strip() or None,
            }
    except Exception as exc:  # noqa: BLE001
        logger.warning("Hakodate document context lookup failed", order_id=order_id, error=str(exc))
        return None


def save_order_hakodate_canonical_manifest_item(
    order_id: str,
    item: dict[str, Any],
) -> tuple[dict[str, Any] | None, str | None]:
    _ = item
    return {
        "order_id": order_id,
        "deprecated": True,
        "replacement": "live_order_facility_source_workbook",
    }, "hakodate_manifest_deprecated"


def get_order_hakodate_canonical_manifest_item(order_id: str) -> tuple[dict[str, Any] | None, str | None]:
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return None, "order_not_found"
        facility_id = str(order.facility_code or "").strip()
    payload = _load_order_ocr_cache(order_id)
    pipeline = payload.get("hakodate_canonical_pipeline") if isinstance(payload, dict) else None
    return {
        "order_id": order_id,
        "facility_id": facility_id,
        "manifest_item": None,
        "has_manifest_item": False,
        "manifest_deprecated": True,
        "live_source": "live_order_facility_source_workbook",
        "hakodate_canonical_pipeline": pipeline if isinstance(pipeline, dict) else None,
    }, None


def _hakodate_best_method_draft_sheet(order_id: str, *, synchronous_write_input: dict[str, Any] | None = None) -> dict[str, Any] | None:
    processing_input = processing_start_read_input() if synchronous_write_input is None else None
    if synchronous_write_input is not None and "hakodate_base_sheet" in synchronous_write_input:
        base_sheet, error = deepcopy(synchronous_write_input["hakodate_base_sheet"]), None
    else:
        base_sheet, error = _build_hakodate_weekly_menu_base_sheet(order_id, synchronous_write_input=synchronous_write_input, processing_read_input=processing_input)
    if error:
        logger.warning("Hakodate best method draft fallback failed", order_id=order_id, error=error)
    if not isinstance(base_sheet, dict):
        return None
    order = {"lines": deepcopy(synchronous_write_input["input_versions"]["order_lines"] if synchronous_write_input is not None else processing_input["lines"])}
    order_lines = order.get("lines") if isinstance(order, dict) and isinstance(order.get("lines"), list) else []
    if not order_lines:
        return base_sheet
    fields = [str(field or "").strip() for field in (base_sheet.get("fields") or [])]
    rows = [list(row) for row in (base_sheet.get("rows") or []) if isinstance(row, list)]
    original_input = synchronous_write_input if synchronous_write_input is not None else processing_input
    configured = original_input.get("configured_input") if isinstance(original_input, dict) else None
    template = (configured.get("facility") or {}).get("fax_template") if isinstance(configured, dict) else None
    quantity_index = _build_sheet_quantity_index(fields, template=template)
    if not fields or not rows or not quantity_index:
        return base_sheet
    date_idx = fields.index("date_mmdd") if "date_mmdd" in fields else (fields.index("date") if "date" in fields else -1)
    daypart_idx = fields.index("daypart") if "daypart" in fields else -1
    menu_idx = fields.index("menu") if "menu" in fields else (fields.index("menu_name") if "menu_name" in fields else -1)
    if date_idx < 0 or daypart_idx < 0 or menu_idx < 0:
        return base_sheet
    row_lookup: dict[tuple[str, str, str], int] = {}
    for row_index, row in enumerate(rows):
        key = _hakodate_sheet_identity(
            row[date_idx] if date_idx < len(row) else "",
            row[daypart_idx] if daypart_idx < len(row) else "",
            row[menu_idx] if menu_idx < len(row) else "",
        )
        if all(key) and key not in row_lookup:
            row_lookup[key] = row_index
    for line in order_lines:
        if not isinstance(line, dict):
            continue
        qty = line.get("quantity_corrected")
        if qty is None:
            qty = line.get("quantity_original")
        if qty is None:
            continue
        try:
            qty_float = float(qty)
        except Exception:
            continue
        col_idx = _resolve_quantity_column_index(
            quantity_index=quantity_index,
            diet_key=line.get("diet_type"),
            area_key=line.get("area_id"),
        )
        if col_idx is None:
            continue
        row_index = row_lookup.get(_hakodate_sheet_identity(line.get("date"), line.get("daypart"), line.get("menu_name")))
        if row_index is None:
            continue
        while len(rows[row_index]) <= col_idx:
            rows[row_index].append("")
        rows[row_index][col_idx] = _numeric_string_add(str(rows[row_index][col_idx] or ""), qty_float)
    seeded = deepcopy(base_sheet)
    seeded["rows"] = rows
    seeded["source"] = "hakodate_confirmed_lines_seed_sheet"
    return seeded


def _estimate_hakodate_template_bbox_from_rendered_image(image: Any) -> list[float]:
    import cv2
    import numpy as np

    height, width = image.shape[:2]
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    binary = cv2.threshold(gray, 180, 255, cv2.THRESH_BINARY_INV)[1]
    horizontal = cv2.morphologyEx(
        binary,
        cv2.MORPH_OPEN,
        cv2.getStructuringElement(cv2.MORPH_RECT, (80, 1)),
    )
    vertical = cv2.morphologyEx(
        binary,
        cv2.MORPH_OPEN,
        cv2.getStructuringElement(cv2.MORPH_RECT, (1, 80)),
    )
    combined = cv2.bitwise_or(horizontal, vertical)
    count, labels, stats, _centroids = cv2.connectedComponentsWithStats(combined, 8)
    best_bbox: list[float] | None = None
    best_score = 0.0
    for label in range(1, count):
        x, y, w, h, area = [int(value) for value in stats[label]]
        if w < width * 0.35 or h < height * 0.35:
            continue
        score = float(area) * float(w) * float(h)
        if score > best_score:
            best_score = score
            best_bbox = [float(x), float(y), float(x + w), float(y + h)]
    if best_bbox is None:
        raise ValueError("hakodate_template_bbox_not_found")
    return best_bbox


def _build_live_hakodate_manifest_item(
    *,
    order_id: str,
    facility_id: str,
    output_dir: Path,
    render_width: int = 1864,
    document_uri_override: str | None = None,
    pdf_bytes_override: bytes | None = None,
    configured_input: dict[str, Any] | None = None,
    synchronous_write_input: dict[str, Any] | None = None,
    review_start_input: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if review_start_input is None and synchronous_write_input is None and (current_nonworkflow_execution() is not None or _workflow_ocr_job_id.get()):
        review_start_input = processing_start_read_input()
    if synchronous_write_input is None and review_start_input is None:
        raise ValueError("geometry_start_input_required")
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            raise ValueError("order_not_found")
        original_input = synchronous_write_input or review_start_input
        original_pdf = original_input.get("selected_pdf_receipt") or (original_input.get("input_versions") or {}).get("selected_pdf_receipt")
        if original_pdf is None and (current_nonworkflow_execution() is not None or _workflow_ocr_job_id.get()):
            original_pdf = processing_start_pdf_receipt()
        if original_pdf is None and pdf_bytes_override is not None:
            from src.services.storage_service import verify_selected_pdf_bytes
            original_pdf = verify_selected_pdf_bytes(pdf_bytes_override).selected_pdf_receipt
        if not isinstance(original_pdf, dict):
            raise ValueError("selected_pdf_source_required")
        document_uri = original_pdf["storage_uri"]
        if document_uri_override is not None and document_uri_override != document_uri:
            raise ValueError("selected_pdf_input_mismatch")
        if pdf_bytes_override is None:
            from src.services.storage_service import load_selected_pdf_bytes

            if current_nonworkflow_execution() is not None or _workflow_ocr_job_id.get():
                receipt = processing_start_pdf_receipt()
            else:
                receipt = original_pdf
            pdf_bytes_override = load_selected_pdf_bytes(document_uri, receipt)
        week_code = str(order.week_code or "").strip()
        workflow = session.get(OrderWorkflowState, order_id)
        workflow_meta = {}
        if workflow is not None and isinstance(workflow.secondary_actions_json, dict):
            raw_meta = workflow.secondary_actions_json.get("workflow_v2")
            workflow_meta = dict(raw_meta) if isinstance(raw_meta, dict) else {}
        selected_template_id = str(workflow_meta.get("template_id") or "").strip() or None
        if review_start_input is not None:
            week_code = review_start_input["order"]["week_code"]
            raw_meta = ((review_start_input["workflow"] or {}).get("secondary_actions_json") or {}).get("workflow_v2")
            workflow_meta = deepcopy(raw_meta) if isinstance(raw_meta, dict) else {}
            selected_template_id = str(workflow_meta.get("template_id") or "").strip() or None
        if synchronous_write_input is not None:
            original_order = synchronous_write_input["input_versions"]["order"]
            week_code = original_order["week_code"]
            raw_meta = synchronous_write_input["workflow_meta"].get("workflow_v2")
            workflow_meta = deepcopy(raw_meta) if isinstance(raw_meta, dict) else {}
            selected_template_id = str(workflow_meta.get("template_id") or "").strip() or None
        from src.services.storage_service import verify_selected_pdf_bytes
        verified_input = verify_selected_pdf_bytes(pdf_bytes_override)
        if configured_input is not None:
            quad_configured_input = deepcopy(configured_input)
        elif current_nonworkflow_execution() is not None or _workflow_ocr_job_id.get():
            from src.services.workflow_attempt_guard_service import processing_start_configured_input
            quad_configured_input = processing_start_configured_input()
        else:
            quad_configured_input = deepcopy(original_input["configured_input"])
        quad_override_px, quad_override_source = _normalize_operator_quad_override(
            workflow_meta.get("quad_override"),
            render_width=render_width,
            selected_pdf_receipt=verified_input.selected_pdf_receipt,
            configured_input=quad_configured_input,
            order_input_identity={"facility_code": facility_id, "week_code": week_code},
            session=session,
        )
        axis_source = {"selected_pdf_receipt": verified_input.selected_pdf_receipt, "configured_input": quad_configured_input, "order_input_identity": {"facility_code": facility_id, "week_code": week_code}, "session": session}
        header_axis_override = _normalize_operator_header_axis_override(workflow_meta.get("header_axis_override"), **axis_source)
        row_axis_override = _normalize_operator_row_axis_override(workflow_meta.get("row_axis_override"), **axis_source)
    if not document_uri:
        raise ValueError("document_missing")
    week_sheet_name = _week_sheet_name_from_week_value(week_code) or week_code
    if not week_sheet_name:
        raise ValueError("week_unresolved")

    structure_dir = output_dir / "_structure_template"
    structure_dir.mkdir(parents=True, exist_ok=True)
    from src.services.storage_service import verify_selected_pdf_bytes

    verify_selected_pdf_bytes(pdf_bytes_override)
    materialized_fax_pdf = structure_dir / f"{order_id}_fax.pdf"
    materialized_fax_pdf.write_bytes(pdf_bytes_override)
    fax_pdf_for_registration = str(materialized_fax_pdf)
    facility_config = deepcopy(quad_configured_input["facility"])
    config_service._validate_authored_facility_config(facility_config, selected_template_id)
    if not isinstance(facility_config, dict):
        raise ValueError("facility_config_missing")
    structure_xlsx = master_order_form_template_service.build_facility_template_xlsx(
        facility_config=facility_config,
        output_path=structure_dir / f"{facility_id}_{order_id}_master_facility_template.xlsx",
        week_value=week_code,
        week_menu_entries=deepcopy((synchronous_write_input or review_start_input)["physical_menu_entries"]),
    )
    structure_pdf = structure_dir / f"{structure_xlsx.stem}.pdf"
    template_sheet_name = master_order_form_template_service.FACILITY_TEMPLATE_SHEET_NAME
    render_workbook_path_to_pdf(
        structure_xlsx,
        output_path=structure_pdf,
        sheet_name=template_sheet_name,
    )
    from src.services.hakodate_fixed_quad_registration_service import (
        build_fixed_quad_template_registration,
        registration_template_axes_from_workbook,
        render_pdf_page_to_bgr,
    )

    # The accepted Hakodate runtime treats step2_png as the rectified FAX canvas,
    # not as the template image. Keep the runtime contract identical to the
    # locally accepted manifest by generating that rectified canvas here.
    accepted_canvas_width = 2362
    accepted_canvas_height = 4273
    template_image = render_pdf_page_to_bgr(str(structure_pdf), width=accepted_canvas_width)
    template_bbox = _estimate_hakodate_template_bbox_from_rendered_image(template_image)
    template_axes_x, template_axes_y = registration_template_axes_from_workbook(
        structure_xlsx,
        sheet_name=template_sheet_name,
        canvas_width=accepted_canvas_width,
        canvas_height=accepted_canvas_height,
        table_bbox=template_bbox,
    )
    registration_dir = structure_dir / f"{facility_id}_{order_id}_fixed_quad"
    verify_selected_pdf_bytes(pdf_bytes_override)
    registration, _images = build_fixed_quad_template_registration(
        facility_code=facility_id,
        order_id=order_id,
        fax_pdf=fax_pdf_for_registration,
        template_pdf=str(structure_pdf),
        quad_px=quad_override_px,
        manifest_template_bbox=template_bbox,
        canvas_width=accepted_canvas_width,
        canvas_height=accepted_canvas_height,
        render_width=render_width,
        quad_source=quad_override_source,
        output_dir=registration_dir,
        template_axes_x=template_axes_x,
        template_axes_y=template_axes_y,
        template_workbook_path=structure_xlsx,
        template_sheet_name=template_sheet_name,
        page=_authored_geometry_page(quad_configured_input),
    )
    step2_png = Path(registration.outputs["step2"])
    from src.services.hakodate_step_review_pipeline_service import canonical_target_semantics
    original_plan = hakodate_cell_ocr_batch_service.capture_original_target_plan(configured_input=quad_configured_input, physical_menu_entries=original_input["physical_menu_entries"], week_code=week_code)
    return {
        "order_id": order_id,
        "facility_code": facility_id,
        "facility_id": facility_id,
        "fax_pdf": fax_pdf_for_registration,
        "week_code": week_code,
        "_verified_pdf_bytes": pdf_bytes_override,
        "configured_input": deepcopy(quad_configured_input),
        "original_physical_draft": hakodate_cell_ocr_batch_service.original_physical_draft(physical_menu_entries=original_input["physical_menu_entries"], week_code=week_code),
        "original_expected_sheet_cells": hakodate_cell_ocr_batch_service.expected_sheet_cells_from_target_regions(original_plan),
        "original_target_semantics": _json_snapshot(canonical_target_semantics(original_plan)),
        "selected_page": _authored_geometry_page(quad_configured_input),
        "selected_pdf_receipt": deepcopy(verified_input.selected_pdf_receipt),
        "template_xlsx": str(structure_xlsx),
        "template_pdf": str(structure_pdf),
        "template_sheet_name": template_sheet_name,
        "fax_template_id": selected_template_id,
        "template_id": selected_template_id,
        "step2_png": str(step2_png),
        "template_bbox": template_bbox,
        "template_axes_x": template_axes_x,
        "template_axes_y": template_axes_y,
        "quad_px": registration.quad_px,
        "quad_source": registration.quad_source,
        "quad_override": deepcopy(workflow_meta.get("quad_override")),
        "header_axis_override": header_axis_override,
        "row_axis_override": row_axis_override,
        "week_sheet_name": week_sheet_name,
        "source": "live_order_master_facility_template",
    }


def build_hakodate_header_axis_review(order_id: str, *, source_receipt: dict, start_input: dict) -> dict[str, Any]:
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            raise ValueError("order_not_found")
        facility_id = str(source_receipt["order_input_identity"]["facility_code"] or "").strip()
    if not facility_id:
        raise ValueError("facility_missing")
    _validate_geometry_source(source_receipt, source_receipt["selected_pdf_receipt"], start_input["configured_input"], source_receipt["order_input_identity"])
    with tempfile.TemporaryDirectory(prefix=f"hakodate_header_review_{order_id}_") as tmp:
        output_dir = Path(tmp)
        runtime_item = _build_live_hakodate_manifest_item(
            order_id=order_id,
            facility_id=facility_id,
            output_dir=output_dir,
            render_width=1864,
            document_uri_override=source_receipt["selected_pdf_receipt"]["storage_uri"],
            pdf_bytes_override=_load_axis_review_pdf(source_receipt),
            configured_input=start_input["configured_input"],
            review_start_input=start_input,
        )
        rectified_fax = hakodate_cell_ocr_batch_service.cv2.imread(runtime_item["step2_png"])
        if rectified_fax is None:
            raise ValueError("header_axis_review_rectified_canvas_missing")
        template_xs = [int(value) for value in runtime_item.get("template_axes_x") or []]
        template_ys = [int(value) for value in runtime_item.get("template_axes_y") or []]
        week_sheet_name = str(runtime_item.get("week_sheet_name") or "").strip() or hakodate_cell_ocr_batch_service.WEEK_SHEET_NAME
        worksheet = hakodate_assignment_service._worksheet_for_manifest_structure_template(  # noqa: SLF001
            item=runtime_item,
            facility_id=facility_id,
            week_sheet_name=week_sheet_name,
        )
        fax_template = hakodate_cell_ocr_batch_service._fax_template_for_manifest_item(runtime_item, facility_id)  # noqa: SLF001
        aligned_xs, aligned_ys, axis_evidence, _axis_match_image = hakodate_cell_ocr_batch_service._align_axes(  # noqa: SLF001
            rectified_fax=rectified_fax,
            template_xs=template_xs,
            template_ys=template_ys,
            worksheet=worksheet,
            fax_template=fax_template,
            header_axis_override=runtime_item.get("header_axis_override")
            if isinstance(runtime_item.get("header_axis_override"), dict)
            else None,
            row_axis_override=runtime_item.get("row_axis_override")
            if isinstance(runtime_item.get("row_axis_override"), dict)
            else None,
            diagnostic_only=True,
        )
        image = hakodate_cell_ocr_batch_service._draw_header_intersections_overlay(  # noqa: SLF001
            image=_axis_match_image,
            axis_evidence=axis_evidence,
        ).convert("RGB")
        match = axis_evidence.get("header_intersection_x_match") if isinstance(axis_evidence, dict) else {}
        if not isinstance(match, dict):
            match = {}
        header_roi = match.get("header_roi")
        if not isinstance(header_roi, list) or len(header_roi) != 4:
            table_bbox = runtime_item.get("template_bbox") or [0, 0, image.width, min(image.height, 360)]
            x0, y0, x1, y1 = [int(round(float(value))) for value in table_bbox]
            header_roi = [x0, max(0, y0 - 24), x1, min(image.height, y0 + 260)]
        x0, y0, x1, y1 = [int(round(float(value))) for value in header_roi]
        pad = 36
        crop_box = [
            max(0, x0 - pad),
            max(0, y0 - pad),
            min(image.width, x1 + pad),
            min(image.height, y1 + pad),
        ]
        crop = image.crop(tuple(crop_box))
        buf = io.BytesIO()
        crop.save(buf, format="PNG")
        corrected_xs = match.get("corrected_xs")
        if not isinstance(corrected_xs, list) or len(corrected_xs) < 2:
            clusters = match.get("fax_x_clusters")
            if isinstance(clusters, list):
                corrected_xs = [cluster.get("value") for cluster in clusters if isinstance(cluster, dict)]
        if not isinstance(corrected_xs, list):
            corrected_xs = []
        xs: list[float] = []
        for raw in corrected_xs:
            if type(raw) in (int, float) and math.isfinite(raw):
                xs.append(float(raw))
        y_clusters = match.get("fax_y_clusters")
        y_levels: list[float] = []
        if isinstance(y_clusters, list):
            for cluster in y_clusters:
                if not isinstance(cluster, dict):
                    continue
                try:
                    y_levels.append(round(float(cluster.get("value")), 3))
                except (TypeError, ValueError):
                    continue
        _validate_geometry_source(source_receipt, source_receipt["selected_pdf_receipt"], start_input["configured_input"], source_receipt["order_input_identity"])
        return {
            "order_id": order_id,
            "status": "ready" if match.get("used") else "needs_correction",
            "error_detail": None if match.get("used") else match.get("reason"),
            "image_png_base64": base64.b64encode(buf.getvalue()).decode("ascii"),
            "image_size": [crop.width, crop.height],
            "crop_box": crop_box,
            "canvas_size": [image.width, image.height],
            "x_positions": xs,
            "y_levels": y_levels,
            "axis_evidence": match,
            "saved_override": runtime_item.get("header_axis_override"),
            "coordinate_space": {"mode": "template_canvas", "width": image.width, "height": image.height},
            "source": "hakodate_header_axis_review",
        }


def _load_axis_review_pdf(source_receipt):
    from src.services.storage_service import load_selected_pdf_bytes
    receipt = source_receipt["selected_pdf_receipt"]
    return load_selected_pdf_bytes(receipt["storage_uri"], receipt)


def build_hakodate_row_axis_review(order_id: str, *, source_receipt: dict, start_input: dict) -> dict[str, Any]:
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            raise ValueError("order_not_found")
        facility_id = str(source_receipt["order_input_identity"]["facility_code"] or "").strip()
    if not facility_id:
        raise ValueError("facility_missing")
    _validate_geometry_source(source_receipt, source_receipt["selected_pdf_receipt"], start_input["configured_input"], source_receipt["order_input_identity"])
    with tempfile.TemporaryDirectory(prefix=f"hakodate_row_review_{order_id}_") as tmp:
        output_dir = Path(tmp)
        runtime_item = _build_live_hakodate_manifest_item(
            order_id=order_id,
            facility_id=facility_id,
            output_dir=output_dir,
            render_width=1864,
            document_uri_override=source_receipt["selected_pdf_receipt"]["storage_uri"],
            pdf_bytes_override=_load_axis_review_pdf(source_receipt),
            configured_input=start_input["configured_input"],
            review_start_input=start_input,
        )
        rectified_fax = hakodate_cell_ocr_batch_service.cv2.imread(runtime_item["step2_png"])
        if rectified_fax is None:
            raise ValueError("row_axis_review_rectified_canvas_missing")
        template_xs = [int(value) for value in runtime_item.get("template_axes_x") or []]
        template_ys = [int(value) for value in runtime_item.get("template_axes_y") or []]
        week_sheet_name = str(runtime_item.get("week_sheet_name") or "").strip() or hakodate_cell_ocr_batch_service.WEEK_SHEET_NAME
        worksheet = hakodate_assignment_service._worksheet_for_manifest_structure_template(  # noqa: SLF001
            item=runtime_item,
            facility_id=facility_id,
            week_sheet_name=week_sheet_name,
        )
        fax_template = hakodate_cell_ocr_batch_service._fax_template_for_manifest_item(runtime_item, facility_id)  # noqa: SLF001
        aligned_xs, aligned_ys, axis_evidence, _axis_match_image = hakodate_cell_ocr_batch_service._align_axes(  # noqa: SLF001
            rectified_fax=rectified_fax,
            template_xs=template_xs,
            template_ys=template_ys,
            worksheet=worksheet,
            fax_template=fax_template,
            header_axis_override=runtime_item.get("header_axis_override")
            if isinstance(runtime_item.get("header_axis_override"), dict)
            else None,
            row_axis_override=runtime_item.get("row_axis_override")
            if isinstance(runtime_item.get("row_axis_override"), dict)
            else None,
            diagnostic_only=True,
        )
        image = hakodate_cell_ocr_batch_service._draw_row_intersections_overlay(  # noqa: SLF001
            image=_axis_match_image,
            axis_evidence=axis_evidence,
        ).convert("RGB")
        match = axis_evidence["row_intersection_y_match"]
        diagnostic_error = match.get("reason") if match.get("diagnostic_only") else None
        if diagnostic_error is None:
            try:
                hakodate_cell_ocr_batch_service._validate_menu_day_boundaries(runtime_item["original_physical_draft"], match)
            except ValueError as exc:
                diagnostic_error = str(exc)
        from src.services import ocr_row_recovery_service, master_order_form_template_service
        days = ocr_row_recovery_service.calendar_contract(
            master_order_form_template_service.validated_body_row_plan(worksheet)
        )
        structural = match.get("structural_match") or {}
        day_source = match.get("canonical_day_source") or structural.get("canonical_day_source") or {}
        buf = io.BytesIO()
        image.save(buf, format="PNG")
        match = axis_evidence.get("row_intersection_y_match") if isinstance(axis_evidence, dict) else {}
        if not isinstance(match, dict):
            match = {}
        corrected_ys = match.get("corrected_ys")
        if not isinstance(corrected_ys, list) or len(corrected_ys) < 2:
            corrected_ys = list(aligned_ys)
        ys: list[float] = []
        for raw in corrected_ys:
            try:
                ys.append(round(float(raw), 3))
            except (TypeError, ValueError):
                continue
        _validate_geometry_source(source_receipt, source_receipt["selected_pdf_receipt"], start_input["configured_input"], source_receipt["order_input_identity"])
        return {
            "order_id": order_id,
            "status": "needs_correction" if diagnostic_error else "ready",
            "error_detail": diagnostic_error,
            "calendar_days": days,
            "boundary_diagnostics": {
                "expected": day_source.get("canonical_date_column_boundary_indexes"),
                "actual": day_source.get("observed_date_column_boundary_indexes"),
                "missing": match.get("missing_date_column_boundary_indexes"),
                "extra": match.get("extra_date_column_boundary_indexes"),
            },
            "body_day_boundary_indexes": (match.get("structural_match") or {}).get("body_day_boundary_indexes"),
            "header_band_count": len(master_order_form_template_service.TEMPLATE_HEADER_EDGE_ROWS),
            "image_png_base64": base64.b64encode(buf.getvalue()).decode("ascii"),
            "image_size": [image.width, image.height],
            "canvas_size": [image.width, image.height],
            "y_positions": ys,
            "x_levels": [round(float(value), 3) for value in aligned_xs],
            "axis_evidence": match,
            "row_height_quality": match.get("row_height_quality") if isinstance(match.get("row_height_quality"), dict) else None,
            "saved_override": runtime_item.get("row_axis_override"),
            "coordinate_space": {"mode": "template_canvas", "width": image.width, "height": image.height},
            "source": "hakodate_row_axis_review",
        }


def _hakodate_overlay_fingerprint(
    *,
    target_cells: list[dict[str, Any]],
    assignments: list[dict[str, Any]],
) -> str:
    return hashlib.sha256(
        json.dumps(
            {
                "target_cells": [
                    {
                        "target_cell_id": item.get("target_cell_id"),
                        "sheet_cell": item.get("sheet_cell"),
                        "bbox": item.get("bbox"),
                        "center": item.get("center"),
                    }
                    for item in target_cells
                    if isinstance(item, dict)
                ],
                "assignments": [
                    {
                        "target_cell_id": item.get("target_cell_id"),
                        "sheet_cell": item.get("sheet_cell"),
                        "assigned_value": item.get("assigned_value"),
                    }
                    for item in assignments
                    if isinstance(item, dict)
                ],
            },
            ensure_ascii=False,
            sort_keys=True,
            default=str,
        ).encode("utf-8")
    ).hexdigest()


def _persist_hakodate_recognition_checkpoint(**kwargs):
    from src.services.hakodate_ocr_checkpoint_service import persist_recognizer_checkpoint

    execution = current_nonworkflow_execution()
    job_id = execution["job_id"] if execution is not None else _workflow_ocr_job_id.get()
    if not job_id:
        raise ValueError("recognition_checkpoint_job_required")
    checkpoint = persist_recognizer_checkpoint(**kwargs)
    updated = _update_reparse_job_progress(
        job_id, processing_stage="recognition", result_state="processing",
        metrics_patch={"recognition_checkpoint": checkpoint, "recovery_action": "review_recognition_cells"},
    )
    if updated is None:
        raise ValueError("recognition_checkpoint_job_ownership_changed")
    return checkpoint


def _hakodate_canonical_payload_from_manifest_item(
    *,
    order_id: str,
    facility_id: str | None,
    item: dict[str, Any],
    document_uri_override: str | None = None,
    pdf_bytes_override: bytes | None = None,
    configured_input: dict[str, Any] | None = None,
    synchronous_write_input: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    draft_sheet = _hakodate_best_method_draft_sheet(order_id, synchronous_write_input=synchronous_write_input)
    if not isinstance(draft_sheet, dict):
        raise ValueError("hakodate_best_method_draft_sheet_missing")
    captured = synchronous_write_input if synchronous_write_input is not None else processing_start_read_input()
    if synchronous_write_input is not None:
        captured = {
            **captured,
            "order": captured["input_versions"]["order"],
            "workflow": {"secondary_actions_json": captured["workflow_meta"]},
        }
    meta = ((captured.get("workflow") or {}).get("secondary_actions_json") or {}).get("workflow_v2") or {}
    recognition_override = meta.get("recognition_override")
    resume_options = {}
    with tempfile.TemporaryDirectory(prefix=f"hakodate_canonical_{order_id}_") as tmp:
        output_dir = Path(tmp)
        runtime_item = dict(item)
        if recognition_override is not None:
            from src.services import ocr_recognition_recovery_service as recovery
            from src.services.storage_service import load_selected_pdf_bytes
            if (not isinstance(recognition_override, dict)
                    or recognition_override.get("source") != "operator"
                    or not recognition_override.get("edited_by")):
                raise ValueError("recognition_operator_identity_required")
            receipt = (captured["input_versions"]["selected_pdf_receipt"]
                       if synchronous_write_input is not None else processing_start_pdf_receipt())
            if not isinstance(receipt, dict):
                raise ValueError("selected_pdf_source_required")
            runtime_item = recovery.current_item(
                recognition_override["checkpoint"], captured,
                {"selected_pdf_receipt": receipt}, order_id,
            )
            if document_uri_override is not None and document_uri_override != receipt["storage_uri"]:
                raise ValueError("selected_pdf_input_mismatch")
            runtime_item["_verified_pdf_bytes"] = (
                pdf_bytes_override if pdf_bytes_override is not None
                else load_selected_pdf_bytes(receipt["storage_uri"], receipt)
            )
            resume_options = {
                "recognition_checkpoint": recognition_override["checkpoint"],
                "operator_values": recovery.operator_values(
                    recognition_override.get("values"), runtime_item["original_expected_sheet_cells"],
                ),
            }
        elif not all(str(runtime_item.get(key) or "").strip() for key in ("fax_pdf", "template_pdf", "step2_png")):
            if not facility_id:
                raise ValueError("facility_missing")
            runtime_item = _build_live_hakodate_manifest_item(
                order_id=order_id,
                facility_id=facility_id,
                output_dir=output_dir,
                render_width=1864,
                document_uri_override=document_uri_override,
                pdf_bytes_override=pdf_bytes_override,
                configured_input=configured_input,
                synchronous_write_input=synchronous_write_input,
            )
        else:
            raise ValueError("hakodate_manifest_selected_pdf_receipt_required")
        from src.services.storage_service import verify_selected_pdf_bytes
        verify_selected_pdf_bytes(runtime_item["_verified_pdf_bytes"], runtime_item["selected_pdf_receipt"])
        original_source = _hakodate_owned_source(runtime_item["configured_input"], runtime_item["selected_pdf_receipt"], synchronous_write_input)
        runtime_item["original_expected_sheet_cells"] = deepcopy(original_source["expected_sheet_cells"])
        runtime_item["original_target_semantics"] = deepcopy(original_source["expected_target_semantics"])
        result, _review_page = hakodate_cell_ocr_batch_service.build_hakodate_best_method_for_manifest_item(
            item=runtime_item,
            page=_authored_geometry_page(runtime_item["configured_input"]),
            draft_sheet=draft_sheet,
            output_dir=output_dir,
            render_width=1864,
            checkpoint_callback=_persist_hakodate_recognition_checkpoint if synchronous_write_input is None else None,
            **resume_options,
        )
        runtime_metrics_raw = getattr(result, "metrics", None)
        runtime_metrics = dict(runtime_metrics_raw) if isinstance(runtime_metrics_raw, dict) else {}
        expected_cells = list(result.expected_sheet_cells)
        if not expected_cells or expected_cells != original_source["expected_sheet_cells"] or runtime_metrics.get("expected_sheet_cells") != expected_cells:
            raise ValueError("hakodate_expected_cells_changed")
        outputs = dict(result.outputs or {})
        regions_path = outputs.get("ocr_regions")
        records_path = outputs.get("records")
        if not regions_path:
            raise ValueError("hakodate_canonical_regions_missing")
        regions = json.loads(Path(regions_path).read_text(encoding="utf-8"))
        if not isinstance(regions, list):
            raise ValueError("hakodate_canonical_representation_invalid")
        if any(not isinstance(region, dict) for region in regions):
            raise ValueError("hakodate_canonical_representation_invalid")
        _validate_hakodate_target_identities(regions)
        digit_records: list[dict[str, Any]] = []
        if records_path and Path(records_path).exists():
            loaded_records = json.loads(Path(records_path).read_text(encoding="utf-8"))
            if isinstance(loaded_records, list):
                if any(not isinstance(item, dict) for item in loaded_records):
                    raise ValueError("hakodate_canonical_representation_invalid")
                digit_records = loaded_records
        canonical_regions: list[dict[str, Any]] = []
        raw_evidence_records: list[dict[str, Any]] = []
        for index, region in enumerate(regions):
            if not isinstance(region, dict):
                continue
            copied = dict(region)
            copied["source"] = "operator" if recognition_override is not None else "hakodate_best_method_pipeline"
            canonical_regions.append(copied)
        if not digit_records:
            raise ValueError("hakodate_own_recognizer_records_missing")
        owned_source = _hakodate_owned_source(runtime_item["configured_input"], runtime_item["selected_pdf_receipt"], synchronous_write_input)
        owned_source["expected_sheet_cells"] = deepcopy(expected_cells)
        from src.services.hakodate_source_receipt import source_reference
        cell_source = source_reference(owned_source)
        from src.services import canonical_ocr_artifact_service
        artifact_packet = canonical_ocr_artifact_service.persist_outputs(
            order_id=order_id, outputs=outputs, source_receipt=owned_source,
            expected_sheet_cells=expected_cells, producer_version=HAKODATE_CANONICAL_PIPELINE_VERSION,
            workspace=output_dir,
        )
        outputs = {key: receipt["uri"] for key, receipt in artifact_packet["outputs"].items()}
        evidence_source_records = digit_records
        for index, region in enumerate(evidence_source_records):
            accepted_candidate = region.get("recognizer_accepted_candidate")
            accepted_candidate = accepted_candidate if isinstance(accepted_candidate, dict) else {}
            if recognition_override is not None:
                cell = region.get("sheet_cell")
                values = resume_options["operator_values"]
                if (cell not in values or region.get("recognition_source") != "operator"
                        or region.get("operator_value") != values[cell]):
                    raise ValueError("recognition_operator_record_mismatch")
                raw_value = values[cell]
            elif "recognizer_raw_text" in region:
                raw_value = region["recognizer_raw_text"]
            elif "raw_text" in region:
                raw_value = region["raw_text"]
            else:
                raw_value = region.get("ocr_text")
            raw_text = str(raw_value if raw_value is not None else "")
            confidence_source = (
                accepted_candidate.get("score")
                if str(region.get("recognizer_decision_source") or "").strip() == "topk_digits"
                else region.get("recognizer_score")
            )
            box = region.get("bbox")
            center = None
            if isinstance(box, list) and len(box) == 4:
                try:
                    center = [(float(box[0]) + float(box[2])) / 2.0, (float(box[1]) + float(box[3])) / 2.0]
                except Exception:
                    center = None
            raw_evidence_records.append(
                {
                    "text": raw_text,
                    "normalized_value": raw_text,
                    "bbox": box,
                    "center": center,
                    "confidence": confidence_source,
                    "evidence_id": f"hakodate-cell-{index}",
                    "engine_metadata": {
                        "source_region_id": region.get("region_id"),
                        "source_receipt": dict(cell_source),
                        "sheet_cell": region.get("sheet_cell"),
                        "ocr_contact_slot_index": region.get("ocr_contact_slot_index"),
                        "source_artifact": "best_method_records",
                        "recognizer_output": deepcopy(region),
                        "recognizer_score": region.get("recognizer_score"),
                        "recognizer_decision_source": region.get("recognizer_decision_source"),
                        "recognizer_accepted_candidate": accepted_candidate or None,
                    },
                }
            )
            if recognition_override is not None:
                raw_evidence_records[-1]["engine_metadata"] = {
                    "source": "operator", "edited_by": recognition_override["edited_by"],
                    "created_at": recognition_override["created_at"],
                    "source_receipt": dict(cell_source), "sheet_cell": region["sheet_cell"],
                    "source_artifact": "best_method_records", "operator_output": deepcopy(region),
                }
        target_cells = hakodate_ocr_evidence_service.target_cells_from_regions(canonical_regions)
        for cell in target_cells:
            cell["source"] = "operator" if recognition_override is not None else "hakodate_best_method_pipeline"
            cell["source_receipt"] = dict(cell_source)
        evidence_records = hakodate_ocr_evidence_service.evidence_from_records(
            raw_evidence_records,
            run_id=f"{order_id}:hakodate-best-method",
            engine=str(result.ocr_engine or hakodate_cell_ocr_batch_service.DEFAULT_CELL_OCR_ENGINE),
            source_scope="operator_cell_review" if recognition_override is not None else "hakodate_cell_crop_batch",
            raw_payload_ref=outputs["records"],
            retain_empty_records=True,
        )
        recognition_review = hakodate_ocr_evidence_service.recognition_review(evidence_records)
        _validate_hakodate_owned_artifacts(
            {
                "hakodate_recognition_review": recognition_review,
                "hakodate_repair_source_receipt": owned_source,
                "hakodate_canonical_pipeline": {
                    "status": "ready", "version": HAKODATE_CANONICAL_PIPELINE_VERSION,
                    "expected_sheet_cells": expected_cells, "requested_order_id": order_id,
                    "outputs": outputs, "artifact_packet": artifact_packet,
                },
                "hakodate_overlay": {"uri": outputs["overlay"], "sheet_review_base_uri": outputs["sheet_review_base"]},
                "hakodate_preprocessing": {"target_cell_map": target_cells},
                "hakodate_ocr_evidence": {"records": evidence_records},
                "hakodate_ocr_evidence_records": evidence_records,
            },
            _hakodate_owned_source(runtime_item["configured_input"], runtime_item["selected_pdf_receipt"], synchronous_write_input),
            allow_review=True,
        )
        canonical_blockers: list[str] = []
        if not target_cells:
            canonical_blockers.append("hakodate_target_cell_map_missing")
        if not evidence_records:
            canonical_blockers.append("hakodate_ocr_evidence_missing")
        assignment_result = (
            hakodate_ocr_evidence_service.assign_evidence_to_target_cells(
                evidence_records=evidence_records,
                target_cells=target_cells,
            )
            if target_cells and evidence_records
            else {
                "assignments": [],
                "blockers": [],
                "summary": {"assigned_target_count": 0},
            }
        )
        canonical_blockers.extend(
            str(item).strip()
            for item in (assignment_result.get("blockers") or [])
            if str(item).strip()
        )
        assigned_target_count = int((assignment_result.get("summary") or {}).get("assigned_target_count") or 0)
        if assigned_target_count <= 0:
            canonical_blockers.append("hakodate_assignment_missing")
        canonical_blockers = list(dict.fromkeys(item for item in canonical_blockers if item))
        overlay_fingerprint = _hakodate_overlay_fingerprint(
            target_cells=target_cells,
            assignments=[
                item
                for item in (assignment_result.get("assignments") or [])
                if isinstance(item, dict)
            ],
        )
        overlay_uri = outputs["overlay"]
        sheet_review_base_uri = outputs["sheet_review_base"]
        return {
            "hakodate_recognition_review": recognition_review,
            "hakodate_repair_source_receipt": owned_source,
            "hakodate_preprocessing": {
                "target_cell_map": target_cells,
                "source": "hakodate_best_method_pipeline",
                "quality_gate": {
                    "ok": not canonical_blockers,
                    "target_cell_count": len(target_cells),
                    "evidence_record_count": len(evidence_records),
                    "assigned_target_count": assigned_target_count,
                    "blockers": canonical_blockers,
                },
            },
            "hakodate_ocr_evidence_records": evidence_records,
            "hakodate_ocr_evidence": {"records": deepcopy(evidence_records)},
            "hakodate_overlay": {
                "uri": overlay_uri,
                "sheet_review_base_uri": sheet_review_base_uri,
                "fingerprint": overlay_fingerprint,
                "producer": "hakodate_best_method_pipeline",
                "version": HAKODATE_CANONICAL_PIPELINE_VERSION,
                "generated_at": datetime.utcnow().isoformat(),
                "content_type": "image/png",
            }
            if overlay_uri
            else None,
            "hakodate_canonical_pipeline": {
                "producer": "hakodate_cell_ocr_batch_service.build_hakodate_best_method_for_manifest_item",
                "version": HAKODATE_CANONICAL_PIPELINE_VERSION,
                "expected_sheet_cells": expected_cells,
                "status": "ready" if not canonical_blockers else "blocked",
                "blockers": canonical_blockers,
                "source": str(runtime_item.get("source") or "live_order_facility_source_workbook"),
                "manifest_path": None,
                "manifest_order_id": None,
                "manifest_facility_code": None,
                "requested_order_id": order_id,
                "requested_facility_id": facility_id,
                "draft_sheet_source": "processing_start_physical_menu",
                "week_sheet_name": runtime_item.get("week_sheet_name"),
                "template_bbox": runtime_item.get("template_bbox"),
                "target_cell_count": len(target_cells),
                "evidence_record_count": len(evidence_records),
                "assigned_target_count": assigned_target_count,
                "metrics": runtime_metrics,
                "outputs": outputs,
                "artifact_packet": artifact_packet,
            },
            "metrics": runtime_metrics,
        }


def _augment_hakodate_ocr_payload_artifacts(
    *,
    order_id: str,
    payload: dict[str, Any],
    template: dict[str, Any] | None,
    force_hakodate: bool = False,
    selected_pdf_receipt: dict[str, Any] | None = None,
    configured_input: dict[str, Any] | None = None,
    synchronous_write_input: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if not isinstance(template, dict):
        return payload
    if (
        not force_hakodate
        and hakodate_assignment_service.resolve_quantity_assignment_strategy(template) != "hakodate"
    ):
        return payload
    next_payload = dict(payload)
    pipeline = next_payload.get("hakodate_canonical_pipeline")
    if not force_hakodate and isinstance(pipeline, dict) and pipeline.get("version") != HAKODATE_CANONICAL_PIPELINE_VERSION:
        next_payload["hakodate_canonical_pipeline"] = {"status": "blocked", "blockers": ["hakodate_canonical_version_required"]}
        return next_payload
    try:
        if (
            not force_hakodate
            and _payload_has_current_hakodate_canonical_pipeline(next_payload)
            and _payload_has_hakodate_target_cells(next_payload)
            and _payload_has_hakodate_evidence_records(
                next_payload,
                order_id=order_id,
            )
        ):
            receipt = selected_pdf_receipt if selected_pdf_receipt is not None else processing_start_pdf_receipt()
            _validate_hakodate_owned_artifacts(next_payload, _hakodate_owned_source(configured_input, receipt, synchronous_write_input))
            return next_payload
    except ValueError as exc:
        next_payload["hakodate_canonical_pipeline"] = {"status": "blocked", "blockers": [str(exc)]}
        return next_payload
    try:
        original_order = synchronous_write_input["input_versions"]["order"] if synchronous_write_input is not None else processing_start_read_input()["order"]
        facility_id = str(original_order.get("facility_code") or "").strip() or None
        from src.services.storage_service import load_selected_pdf_bytes
        receipt = selected_pdf_receipt if selected_pdf_receipt is not None else processing_start_pdf_receipt()
        own_pdf_bytes = load_selected_pdf_bytes(receipt["storage_uri"], receipt)
        canonical_payload = _hakodate_canonical_payload_from_manifest_item(
            order_id=order_id,
            facility_id=facility_id,
            item={"source": "live_order_facility_source_workbook"},
            document_uri_override=receipt["storage_uri"],
            pdf_bytes_override=own_pdf_bytes,
            configured_input=configured_input,
            synchronous_write_input=synchronous_write_input,
        )
    except Exception as exc:  # noqa: BLE001
        logger.warning("Hakodate canonical live pipeline failed", order_id=order_id, error=str(exc))
        next_payload["hakodate_canonical_pipeline"] = {
            "producer": "hakodate_cell_ocr_batch_service.build_hakodate_best_method_for_manifest_item",
            "status": "blocked",
            "blockers": ["hakodate_canonical_pipeline_failed"],
            "source": "live_order_facility_source_workbook",
            "manifest_path": None,
            "error": str(exc),
        }
        return next_payload
    if not isinstance(canonical_payload, dict):
        next_payload["hakodate_canonical_pipeline"] = {
            "producer": "hakodate_cell_ocr_batch_service.build_hakodate_best_method_for_manifest_item",
            "status": "blocked",
            "blockers": ["hakodate_canonical_pipeline_failed"],
            "source": "live_order_facility_source_workbook",
            "manifest_path": None,
        }
        return next_payload
    for key in ("hakodate_preprocessing", "hakodate_target_cell_map", "hakodate_ocr_evidence", "hakodate_ocr_evidence_records"):
        next_payload.pop(key, None)
    try:
        if not _payload_has_hakodate_target_cells(canonical_payload) or not _payload_has_hakodate_evidence_records(canonical_payload, order_id=order_id):
            next_payload["hakodate_canonical_pipeline"] = {"status": "blocked", "blockers": ["hakodate_own_artifacts_incomplete"]}
            return next_payload
        _validate_hakodate_owned_artifacts(canonical_payload, _hakodate_owned_source(configured_input, receipt, synchronous_write_input), allow_review=True)
    except ValueError as exc:
        next_payload["hakodate_canonical_pipeline"] = {"status": "blocked", "blockers": [str(exc)]}
        return next_payload
    for key, value in canonical_payload.items():
        if value is not None:
            next_payload[key] = value
    return next_payload


def _preserve_hakodate_artifacts_if_missing(
    *,
    order_id: str,
    next_payload: dict[str, Any],
    existing_payload: dict[str, Any],
) -> dict[str, Any]:
    """Prevent lightweight read payloads from deleting reusable Hakodate artifacts."""
    if not isinstance(existing_payload, dict):
        return next_payload
    preserved = dict(next_payload)
    if preserved.get("hakodate_artifacts_reset_at"):
        return preserved
    if not _payload_has_hakodate_target_cells(preserved) and _payload_has_hakodate_target_cells(existing_payload):
        existing_preprocessing = existing_payload.get("hakodate_preprocessing")
        if isinstance(existing_preprocessing, dict):
            next_preprocessing = dict(preserved.get("hakodate_preprocessing") or {})
            for key in ("target_cell_map", "target_cells", "source", "quality_gate"):
                if key not in next_preprocessing and key in existing_preprocessing:
                    next_preprocessing[key] = deepcopy(existing_preprocessing[key])
            if next_preprocessing:
                preserved["hakodate_preprocessing"] = next_preprocessing
        for key in ("hakodate_target_cell_map",):
            if key not in preserved and key in existing_payload:
                preserved[key] = deepcopy(existing_payload[key])
    if (
        not _payload_has_hakodate_evidence_records(preserved, order_id=order_id)
        and _payload_has_hakodate_evidence_records(existing_payload, order_id=order_id)
    ):
        for key in ("hakodate_ocr_evidence", "hakodate_ocr_evidence_records"):
            if key not in preserved and key in existing_payload:
                preserved[key] = deepcopy(existing_payload[key])
    return preserved


def _save_order_ocr_cache(
    order_id: str,
    payload: dict,
    *,
    job_id: str | None = None,
    synchronous_write_input: dict[str, Any] | None = None,
    augment_hakodate_artifacts: bool = True,
    preserve_existing_artifacts: bool = True,
    persist_evidence: bool = True,
    refresh_workflow: bool = True,
    write_session: Any = None,
) -> dict[str, Any] | None:
    normalized_job_id = str(job_id or "").strip()
    if normalized_job_id and synchronous_write_input is not None:
        return None
    if not normalized_job_id and not isinstance(synchronous_write_input, dict):
        return None
    if not normalized_job_id:
        # A synchronous snapshot CAS authorizes this cache repair only. Evidence
        # persistence remains an async job-owned write with its own fence.
        persist_evidence = False
    evidence_payload = deepcopy(payload) if isinstance(payload, dict) else None
    persisted_evidence = None
    next_payload = dict(payload) if isinstance(payload, dict) else {}
    if synchronous_write_input is not None:
        captured_config = deepcopy(synchronous_write_input["configured_input"])
    else:
        from src.services.workflow_attempt_guard_service import processing_start_configured_input
        captured_config = processing_start_configured_input()
    config_service._validate_authored_facility_config(captured_config["facility"], None)
    template = deepcopy(captured_config["facility"]["fax_template"])
    if template is None:
        raise ValueError("authored_fax_template_unresolved")
    annotated_payload = _annotate_payload_with_template_field_schema(next_payload, template)
    if isinstance(annotated_payload, dict):
        next_payload = annotated_payload
    if augment_hakodate_artifacts:
        next_payload = _augment_hakodate_ocr_payload_artifacts(
            order_id=order_id,
            payload=next_payload,
            template=template,
            selected_pdf_receipt=(synchronous_write_input or {}).get("selected_pdf_receipt"),
            configured_input=captured_config,
            synchronous_write_input=synchronous_write_input,
        )
    if (next_payload.get("hakodate_canonical_pipeline") or {}).get("status") == "blocked":
        return None
    try:
        with (nullcontext(write_session) if write_session is not None else session_scope()) as session:
            if normalized_job_id:
                write_allowed = _workflow_attempt_write_fence(session, normalized_job_id, order_id)
            else:
                write_allowed = _synchronous_cache_write_fence(
                    session,
                    order_id,
                    synchronous_write_input,
                )
            if not write_allowed:
                return None
            if _payload_has_hakodate_output_content(next_payload, order_id=order_id):
                receipt = (synchronous_write_input or {}).get("selected_pdf_receipt") or processing_start_pdf_receipt()
                _validate_hakodate_owned_artifacts(next_payload, _hakodate_owned_source(captured_config, receipt, synchronous_write_input))
                preserve_existing_artifacts = False
            if persist_evidence and not _payload_has_hakodate_output_content(next_payload, order_id=order_id):
                persisted_evidence = persist_ocr_evidence_run(
                    order_id, evidence_payload,
                    schema_version="v1_legacy", producer_version="legacy-cache-mirror/v1",
                    source="legacy-cache-mirror", workflow_job_id=normalized_job_id,
                    refresh_workflow=False, write_session=session,
                )
                if persisted_evidence is None:
                    session.rollback()
                    return None
            cache = session.get(OrderOcrCache, order_id)
            if not cache:
                cache = OrderOcrCache(order_id=order_id)
                session.add(cache)
            existing_payload = cache.payload if isinstance(cache.payload, dict) else {}
            if normalized_job_id:
                # Preserve operator edits as their original lineage, never as this run's result.
                next_payload.pop("_edited_ocr", None)
                if isinstance(existing_payload.get("_edited_ocr"), dict):
                    next_payload["_edited_ocr"] = deepcopy(existing_payload["_edited_ocr"])
            if preserve_existing_artifacts and (
                isinstance(existing_payload, dict)
                and _payload_has_page_artifacts(existing_payload)
                and not _payload_has_page_artifacts(next_payload)
            ):
                for preserved_key in ("pages", "combined", "engine", "template_id", "facility_id"):
                    preserved_value = existing_payload.get(preserved_key)
                    if preserved_key not in next_payload and preserved_value is not None:
                        next_payload[preserved_key] = preserved_value
            if preserve_existing_artifacts:
                for preserved_key in ("_edited_ocr", "_reparse_debug"):
                    preserved_value = existing_payload.get(preserved_key)
                    if isinstance(preserved_value, dict) and preserved_key not in next_payload:
                        next_payload[preserved_key] = preserved_value
                next_payload = _preserve_hakodate_artifacts_if_missing(
                    order_id=order_id,
                    next_payload=next_payload,
                    existing_payload=existing_payload,
                )
            cache.payload = next_payload
            cache.updated_at = datetime.utcnow()
            execution_input = current_nonworkflow_execution()
            if execution_input is not None:
                advance_nonworkflow_order_input(session, execution_input, session.get(Order, order_id))
    except Exception as exc:  # noqa: BLE001
        logger.warning("Order OCR cache save failed", order_id=order_id, error=str(exc))
        return None
    if persist_evidence and _payload_has_hakodate_output_content(next_payload, order_id=order_id):
        persist_evidence = False
    if refresh_workflow and write_session is None:
        try:
            workflow_state_service.refresh_workflow_state(order_id)
        except Exception as exc:  # noqa: BLE001
            logger.warning("Workflow state refresh failed after OCR cache save", order_id=order_id, error=str(exc))
    return persisted_evidence if isinstance(persisted_evidence, dict) else {}


def _load_order_ocr_cache(order_id: str) -> Optional[dict]:
    try:
        with session_scope() as session:
            cache = session.get(OrderOcrCache, order_id)
            if not cache:
                return None
            return cache.payload if isinstance(cache.payload, dict) else None
    except Exception as exc:  # noqa: BLE001
        logger.warning("Order OCR cache load failed", order_id=order_id, error=str(exc))
        return None


def get_cached_ocr_payload(order_id: str) -> Optional[dict]:
    return evidence_manifest_service.ensure_evidence_manifest(_load_order_ocr_cache(order_id))


def persist_ocr_evidence_run(
    order_id: str,
    payload: dict[str, Any] | None,
    *,
    schema_version: str = "v1_legacy",
    producer_version: str | None = None,
    status: str = "ready",
    source: str | None = None,
    workflow_job_id: str | None = None,
    refresh_workflow: bool = True,
    result_disposition: str | None = None,
    write_session: Any = None,
) -> Optional[dict]:
    normalized_job_id = str(workflow_job_id or "").strip()
    workflow_attempt_id = _workflow_ocr_attempt_id.get()
    expected_workflow_revision = _workflow_ocr_revision.get()
    if (workflow_attempt_id is not None or expected_workflow_revision is not None) and not normalized_job_id:
        return None
    with (nullcontext(write_session) if write_session is not None else session_scope()) as session:
        if normalized_job_id:
            write_allowed = _workflow_attempt_write_fence(session, normalized_job_id, order_id)
        else:
            write_allowed = lock_actual_write_ownership(
                session,
                job_id=None,
                workflow_attempt_id=None,
                order_id=order_id,
                expected_workflow_revision=None,
            )
        if not write_allowed:
            return None
        captured_config = processing_start_configured_input() if normalized_job_id else None
        if status == "ready" and isinstance(payload, dict) and _payload_has_hakodate_output_content(payload, order_id=order_id):
            _validate_hakodate_owned_artifacts(payload, _hakodate_owned_source(captured_config, processing_start_pdf_receipt()))
        order = session.get(Order, order_id)
        facility_id = str(getattr(order, "facility_code", "") or "").strip() if order is not None else ""
        from src.services.workflow_attempt_guard_service import processing_start_read_input

        original_order = processing_start_read_input().get("order") or {}
        captured_template_version_id = str(original_order.get("template_version_id") or "").strip()
        if (not captured_template_version_id or order is None
                or original_order.get("id") != order.id
                or original_order.get("facility_code") != facility_id
                or order.template_version_id != captured_template_version_id):
            raise ValueError("original_template_capture_missing_or_mismatched")
    prepared_payload = dict(payload) if isinstance(payload, dict) else payload
    template = captured_config["facility"]["fax_template"] if captured_config is not None else None
    if isinstance(prepared_payload, dict):
        annotated_payload = _annotate_payload_with_template_field_schema(prepared_payload, template)
        if isinstance(annotated_payload, dict):
            prepared_payload = annotated_payload
    persisted = ocr_evidence_service.persist_evidence_run(
        order_id=order_id,
        payload=prepared_payload,
        schema_version=schema_version,
        producer_version=producer_version,
        status=status,
        source=source,
        workflow_attempt_id=workflow_attempt_id,
        workflow_job_id=normalized_job_id or None,
        expected_workflow_revision=expected_workflow_revision,
        template_version_id=captured_template_version_id,
        result_disposition=result_disposition,
        write_session=write_session,
    )
    if persisted is not None and refresh_workflow and write_session is None:
        try:
            workflow_state_service.refresh_workflow_state(order_id)
        except Exception as exc:  # noqa: BLE001
            logger.warning("Workflow state refresh failed after evidence persist", order_id=order_id, error=str(exc))
    return persisted


def get_latest_ocr_evidence_run(order_id: str, *, backfill_from_cache: bool = False) -> Optional[dict]:
    if backfill_from_cache:
        raise LegacyOcrEvidenceFallbackDisabledError(
            "legacy OCR cache backfill is disabled; use an explicit repair command instead"
        )
    latest = ocr_evidence_service.get_latest_evidence_run(order_id)
    return latest


def _resolve_active_ocr_evidence_run(order_id: str) -> Optional[dict]:
    return ocr_evidence_service.get_selected_evidence_run(order_id)


def _load_active_ocr_payload(order_id: str) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    active_evidence = _resolve_active_ocr_evidence_run(order_id)
    payload = active_evidence.get("payload_json") if isinstance(active_evidence, dict) else None
    if not isinstance(payload, dict):
        return None, active_evidence
    template = _resolve_order_fax_template(order_id)
    prepared_payload = evidence_manifest_service.ensure_evidence_manifest(dict(payload))
    if template is None:
        raise ValueError("authored_fax_template_unresolved")
    prepared_payload = _restore_payload_raw_ocr_surface(
        prepared_payload,
        strip_legacy_surface=True,
    )
    prepared_payload = _annotate_payload_with_template_field_schema(prepared_payload, template)
    prepared_payload = _augment_payload_with_candidate_resolution(order_id, prepared_payload)
    if not isinstance(prepared_payload, dict):
        return None, active_evidence
    return evidence_manifest_service.ensure_evidence_manifest(dict(prepared_payload)), active_evidence


def get_ocr_evidence_run(evidence_run_id: str) -> Optional[dict]:
    return ocr_evidence_service.get_evidence_run(evidence_run_id)


def persist_sheet_draft(
    *,
    order_id: str,
    draft_sheet_json: dict[str, Any] | None,
    draft_state: str = "draft_ready",
    blockers: list[str] | None = None,
    warnings: list[str] | None = None,
    latest_patch_candidate_id: str | None = None,
    edited_by: str | None = None,
    workflow_job_id: str | None = None,
    evidence_run_id: str | None = None,
    synchronous_write_input: dict[str, Any] | None = None,
    write_session: Any = None,
) -> Optional[dict]:
    if not isinstance(draft_sheet_json, dict):
        return None
    captured_job_id = workflow_job_id or _workflow_ocr_job_id.get()
    if _workflow_ocr_attempt_id.get() is not None and not captured_job_id:
        return None
    if not captured_job_id and synchronous_write_input is None:
        return None
    selected_evidence_id = evidence_run_id or str(draft_sheet_json.get("base_evidence_run_id") or "").strip()
    if not selected_evidence_id and isinstance(synchronous_write_input, dict):
        selected_evidence_id = synchronous_write_input.get("evidence_run_id")
    if isinstance(synchronous_write_input, dict):
        if selected_evidence_id != synchronous_write_input.get("evidence_run_id"):
            return None
        latest_evidence = synchronous_write_input.get("evidence")
    else:
        latest_evidence = get_ocr_evidence_run(selected_evidence_id) if selected_evidence_id else None
    if not isinstance(latest_evidence, dict) or latest_evidence.get("order_id") != order_id:
        return None
    template_resolution_id = None
    if isinstance(latest_evidence, dict):
        payload_json = latest_evidence.get("payload_json")
        if isinstance(payload_json, dict):
            resolution = payload_json.get("template_resolution")
            if isinstance(resolution, dict):
                template_resolution_id = (
                    str(resolution.get("resolved_template_id") or resolution.get("template_id") or "").strip() or None
                )
    persisted = draft_sheet_service.persist_sheet_draft(
        order_id=order_id,
        draft_sheet_json=draft_sheet_json,
        base_evidence_run_id=(latest_evidence or {}).get("id") if isinstance(latest_evidence, dict) else None,
        template_version_id=(latest_evidence or {}).get("template_version_id") if isinstance(latest_evidence, dict) else None,
        base_template_resolution_id=template_resolution_id,
        draft_state=draft_state,
        blockers=blockers,
        warnings=warnings,
        latest_patch_candidate_id=latest_patch_candidate_id,
        edited_by=edited_by,
        workflow_attempt_id=_workflow_ocr_attempt_id.get(),
        workflow_job_id=captured_job_id,
        expected_workflow_revision=_workflow_ocr_revision.get(),
        synchronous_write_input=synchronous_write_input,
        write_session=write_session,
    )
    if persisted is not None and write_session is None:
        try:
            workflow_state_service.refresh_workflow_state(
                order_id,
                refresh_draft_from_semantic=False,
            )
        except Exception as exc:  # noqa: BLE001
            logger.warning("Workflow state refresh failed after draft persist", order_id=order_id, error=str(exc))
    return persisted


def _dedupe_str_tokens(values: list[object] | None) -> list[str]:
    deduped: list[str] = []
    seen: set[str] = set()
    for value in values or []:
        token = str(value or "").strip()
        if token and token not in seen:
            seen.add(token)
            deduped.append(token)
    return deduped


def _slice_monthly_menu_entries_for_week(
    entries: object,
    *,
    week_start: date | None,
    week_end: date | None,
) -> list[dict[str, Any]]:
    normalized_entries = [item for item in (entries or []) if isinstance(item, dict)]
    if not isinstance(week_start, date) or not isinstance(week_end, date):
        return normalized_entries
    sliced: list[dict[str, Any]] = []
    for item in normalized_entries:
        menu_date = _parse_date_value(item.get("menu_date"))
        if isinstance(menu_date, date) and week_start <= menu_date <= week_end:
            sliced.append(item)
    return sliced


def _build_monthly_menu_diagnostics(
    *,
    week_id: str | None,
    facility_id: str | None,
) -> dict[str, Any]:
    normalized_week_id = str(week_id or "").strip() or None
    month_id, week_start, week_end = _parse_sheet_week_value(normalized_week_id)
    diagnostics: dict[str, Any] = {
        "month_id": month_id,
        "resolved_week_id": normalized_week_id,
        "order_codes": [],
        "row_codes": [],
        "global_entries_count": 0,
        "facility_entries_count": 0,
    }
    if not month_id:
        return diagnostics
    target_month_ids = _sheet_week_month_ids(normalized_week_id) or ([month_id] if month_id else [])
    try:
        global_menus: dict[str, dict[str, Any]] = {}
        facility_menus: dict[str, dict[str, Any]] = {}
        for target_month_id in target_month_ids:
            global_payload = menu_service.get_menu(target_month_id)
            if isinstance(global_payload, dict):
                global_menus[target_month_id] = global_payload
            facility_payload = (
                menu_service.get_menu_for_facility(target_month_id, facility_id)
                if str(facility_id or "").strip()
                else global_payload
            )
            if isinstance(facility_payload, dict):
                facility_menus[target_month_id] = facility_payload
    except Exception as exc:  # noqa: BLE001
        logger.warning(
            "Monthly menu diagnostics lookup failed",
            month_id=month_id,
            week_id=normalized_week_id,
            facility_id=facility_id,
            error=str(exc),
        )
        diagnostics["order_codes"] = ["monthly_menu_lookup_failed"]
        return diagnostics
    if len(global_menus) != len(target_month_ids):
        diagnostics["order_codes"] = ["monthly_menu_object_missing"]
        return diagnostics

    global_entries: list[dict[str, Any]] = []
    for target_month_id in target_month_ids:
        global_entries.extend(
            _slice_monthly_menu_entries_for_week(
                global_menus.get(target_month_id, {}).get("entries"),
                week_start=week_start,
                week_end=week_end,
            )
        )
    diagnostics["global_entries_count"] = len(global_entries)
    if not global_entries:
        diagnostics["order_codes"] = ["menu_entries_missing"]
        return diagnostics

    facility_entries: list[dict[str, Any]] = []
    for target_month_id in target_month_ids:
        facility_entries.extend(
            _slice_monthly_menu_entries_for_week(
                facility_menus.get(target_month_id, {}).get("entries") if isinstance(facility_menus.get(target_month_id), dict) else [],
                week_start=week_start,
                week_end=week_end,
            )
        )
    diagnostics["facility_entries_count"] = len(facility_entries)
    if str(facility_id or "").strip() and (len(facility_menus) != len(target_month_ids) or not facility_entries):
        diagnostics["order_codes"] = ["monthly_menu_facility_scope_missing"]
    return diagnostics


def _split_sheet_source(source: object) -> tuple[str | None, str | None]:
    normalized = str(source or "").strip()
    if not normalized:
        return None, None
    if "+" not in normalized:
        return normalized, None
    seed_source, enrichment_source = [item.strip() or None for item in normalized.split("+", 1)]
    return seed_source, enrichment_source


def _draft_fields_look_generic(fields: object) -> bool:
    if not isinstance(fields, list) or not fields:
        return False
    normalized = [str(field or "").strip() for field in fields if str(field or "").strip()]
    if not normalized:
        return False
    return all(re.fullmatch(r"col\d+", token) for token in normalized)


def _sheet_row_identity_key(fields: list[str], row: list[Any]) -> tuple[str, str, str] | None:
    if not isinstance(fields, list) or not isinstance(row, list):
        return None
    try:
        date_idx = fields.index("date_mmdd")
        daypart_idx = fields.index("daypart")
        menu_idx = fields.index("menu")
    except ValueError:
        return None
    parts = []
    for idx in (date_idx, daypart_idx, menu_idx):
        if idx >= len(row):
            return None
        token = str(row[idx] or "").strip()
        if not token:
            return None
        parts.append(token)
    return tuple(parts)


def _explicit_draft_row_identities(sheet: dict, rows: list) -> tuple[str, list[str]]:
    key = "physical_menu_row_ids" if "physical_menu_row_ids" in sheet else "row_ids"
    values = sheet.get(key)
    if not isinstance(values, list) or len(values) != len(rows):
        raise ValueError("saved_draft_row_identity_missing")
    if any(not isinstance(value, str) or not value.strip() or value != value.strip() for value in values):
        raise ValueError("saved_draft_row_identity_invalid")
    if len(set(values)) != len(values):
        raise ValueError("saved_draft_row_identity_duplicate")
    return key, values


def _merge_saved_draft_into_semantic_sheet(
    current_sheet: dict[str, Any] | None,
    fresh_sheet: dict[str, Any] | None,
    *,
    append_unmatched_current_rows: bool = True,
    merge_current_warnings: bool = True,
) -> dict[str, Any] | None:
    if not isinstance(current_sheet, dict) or not isinstance(fresh_sheet, dict):
        raise ValueError("saved_draft_row_identity_missing")
    current_fields = [str(field).strip() for field in (current_sheet.get("fields") or []) if str(field).strip()]
    fresh_fields = [str(field).strip() for field in (fresh_sheet.get("fields") or []) if str(field).strip()]
    fresh_rows = [list(row) for row in (fresh_sheet.get("rows") or []) if isinstance(row, list)]
    if not current_fields or not fresh_fields or not fresh_rows or not current_sheet.get("rows"):
        raise ValueError("saved_draft_row_identity_missing")
    if current_sheet.get("fields") != current_fields or fresh_sheet.get("fields") != fresh_fields or len(set(current_fields)) != len(current_fields) or len(set(fresh_fields)) != len(fresh_fields):
        raise ValueError("saved_draft_row_identity_field_invalid")
    if any(not isinstance(row, list) for row in (current_sheet.get("rows") or [])) or any(not isinstance(row, list) for row in (fresh_sheet.get("rows") or [])):
        raise ValueError("saved_draft_row_identity_invalid")
    if any(len(row) != len(current_fields) for row in (current_sheet.get("rows") or [])) or any(len(row) != len(fresh_fields) for row in fresh_rows):
        raise ValueError("saved_draft_row_identity_incomplete_row")

    current_rows = [list(row) for row in current_sheet["rows"]]
    current_identity_kind, current_keys = _explicit_draft_row_identities(current_sheet, current_rows)
    fresh_identity_kind, fresh_keys = _explicit_draft_row_identities(fresh_sheet, fresh_rows)
    if current_identity_kind != fresh_identity_kind:
        raise ValueError("saved_draft_row_identity_incompatible")
    # Row IDs remain presentation identities; physical IDs, when declared, own
    # the join. Neither identity is reconstructed from a name or row position.
    _, current_row_ids = _explicit_draft_row_identities({"row_ids": current_sheet.get("row_ids")}, current_rows)
    _, fresh_row_ids = _explicit_draft_row_identities({"row_ids": fresh_sheet.get("row_ids")}, fresh_rows)

    current_index = {field: idx for idx, field in enumerate(current_fields)}
    fresh_index = {field: idx for idx, field in enumerate(fresh_fields)}
    if any(field not in fresh_index for field in current_fields):
        raise ValueError("saved_draft_row_identity_unmapped_edit")
    authoritative_shell = (
        _fresh_sheet_has_authoritative_weekly_shell(fresh_sheet)
        and _fields_compatible_for_authoritative_weekly_shell_rebase(current_fields, fresh_fields)
    )
    shell_fields = {"date_mmdd", "daypart", "menu"} if authoritative_shell else set()
    current_quantity_fields = [field for field in current_fields if field.startswith("qty.")]
    fresh_quantity_fields = [field for field in fresh_fields if field.startswith("qty.")]
    shared_quantity_fields = [
        field
        for field in current_quantity_fields
        if field.startswith("qty.") and field in fresh_index
    ]
    current_by_key: dict[str, tuple[list[Any], str]] = {}
    for idx, row in enumerate(current_rows):
        row_key = current_keys[idx]
        row_id = current_row_ids[idx]
        current_by_key[row_key] = (row, row_id)

    unmatched_keys = set(current_keys) - set(fresh_keys)
    if unmatched_keys and (not append_unmatched_current_rows or current_identity_kind == "physical_menu_row_ids"):
        raise ValueError("saved_draft_row_identity_unresolved")
    fresh_labels = {_sheet_row_identity_key(fresh_fields, row) for row in fresh_rows}
    if any(_sheet_row_identity_key(current_fields, current_by_key[key][0]) in fresh_labels for key in unmatched_keys):
        raise ValueError("saved_draft_row_identity_ambiguous")

    merged_rows: list[list[Any]] = []
    merged_row_ids: list[str] = []
    matched_keys: set[str] = set()
    for idx, fresh_row in enumerate(fresh_rows):
        row_key = fresh_keys[idx]
        merged_row = list(fresh_row)
        merged_row_id = fresh_row_ids[idx]
        if row_key in current_by_key:
            current_row, current_row_id = current_by_key[row_key]
            if current_identity_kind == "row_ids" and _sheet_row_identity_key(current_fields, current_row) != _sheet_row_identity_key(fresh_fields, fresh_row):
                raise ValueError("saved_draft_row_identity_changed")
            matched_keys.add(row_key)
            for field_name in fresh_quantity_fields:
                if field_name in shared_quantity_fields:
                    continue
                fresh_idx = fresh_index[field_name]
                merged_row[fresh_idx] = ""
            for field_name, current_idx in current_index.items():
                fresh_idx = fresh_index[field_name]
                current_value = current_row[current_idx]
                if field_name.startswith("qty."):
                    merged_row[fresh_idx] = current_value
                elif _is_aux_sheet_field(field_name):
                    continue
                elif field_name in shell_fields:
                    continue
                else:
                    merged_row[fresh_idx] = current_value
            merged_row_id = current_row_id
        merged_rows.append(merged_row)
        merged_row_ids.append(merged_row_id)

    if append_unmatched_current_rows:
        for row_key, (current_row, current_row_id) in current_by_key.items():
            if row_key in matched_keys:
                continue
            appended = [""] * len(fresh_fields)
            for field_name, current_idx in current_index.items():
                fresh_idx = fresh_index[field_name]
                appended[fresh_idx] = current_row[current_idx]
            merged_rows.append(appended)
            merged_row_ids.append(current_row_id)

    if len(set(merged_row_ids)) != len(merged_row_ids):
        raise ValueError("saved_draft_row_identity_duplicate")

    merged_warnings: list[str] = []
    warning_sources: list[Any] = []
    if merge_current_warnings:
        warning_sources.extend(list(current_sheet.get("warnings") or []))
    warning_sources.extend(list(fresh_sheet.get("warnings") or []))
    for warning in warning_sources:
        token = str(warning or "").strip()
        if token and token not in merged_warnings:
            merged_warnings.append(token)

    merged = dict(fresh_sheet)
    merged["rows"] = merged_rows
    merged["row_ids"] = merged_row_ids
    merged["warnings"] = merged_warnings
    if current_identity_kind == "physical_menu_row_ids":
        for sheet in (current_sheet, fresh_sheet):
            if "physical_menu_row_count" in sheet and (type(sheet["physical_menu_row_count"]) is not int or sheet["physical_menu_row_count"] != len(sheet["physical_menu_row_ids"])):
                raise ValueError("saved_draft_row_identity_invalid")
        if "physical_menu_row_count" in current_sheet and "physical_menu_row_count" not in merged:
            if len(current_keys) != len(fresh_keys):
                raise ValueError("saved_draft_row_identity_unresolved")
            merged["physical_menu_row_count"] = current_sheet["physical_menu_row_count"]
    ui_mode = str(current_sheet.get("ui_mode") or fresh_sheet.get("ui_mode") or "").strip()
    if ui_mode:
        merged["ui_mode"] = ui_mode
    return merged


_SEMANTIC_REFRESH_PRUNE_BLOCKERS = {
    "week_unresolved",
    "menu_entries_missing",
    "sheet_fields_not_found",
    "sheet_fields_duplicate",
    "sheet_template_field_invalid",
    "sheet_quantity_columns_missing",
    "sheet_quantity_column_unmapped",
    "sheet_week_dates_incomplete",
    "week_menu_date_mismatch",
    "sheet_date_mismatch",
    "sheet_canonical_mismatch",
    "sheet_suspicious_blank_row",
    "ocr_evidence_recovery_required",
    "template_resolution_blocked",
    "template_unresolved",
    "auto_apply_blocked",
}


def _fresh_sheet_has_authoritative_weekly_shell(sheet: dict[str, Any] | None) -> bool:
    if not isinstance(sheet, dict):
        return False
    if not _source_uses_weekly_menu_shell(sheet.get("source")):
        return False
    fields = [str(field).strip() for field in (sheet.get("fields") or []) if str(field).strip()]
    rows = _sanitize_semantic_sheet_rows(
        rows_payload=sheet.get("rows"),
        fields=fields,
    )
    required = ["date_mmdd", "daypart", "menu"]
    index = {field: idx for idx, field in enumerate(fields)}
    if any(field not in index for field in required):
        return False
    if not rows:
        return False
    last_required_idx = max(index[field] for field in required)
    for row in rows:
        if len(row) <= last_required_idx:
            return False
        if any(str(row[index[field]] or "").strip() == "" for field in required):
            return False
    return True


def _is_display_only_sheet_field(field: object) -> bool:
    return _is_aux_sheet_field(field) or _is_sheet_note_field(field)


def _fields_compatible_for_authoritative_weekly_shell_rebase(
    current_fields: list[str],
    fresh_fields: list[str],
) -> bool:
    if not current_fields or not fresh_fields:
        return False
    shell_fields = {"date_mmdd", "daypart", "menu"}
    current_core = {
        field
        for field in current_fields
        if field in shell_fields or field.startswith("qty.")
    }
    fresh_core = {
        field
        for field in fresh_fields
        if field in shell_fields or field.startswith("qty.")
    }
    if current_core != fresh_core:
        return False
    for field in current_fields:
        if field in shell_fields or field.startswith("qty.") or _is_display_only_sheet_field(field):
            continue
        return False
    for field in fresh_fields:
        if field in shell_fields or field.startswith("qty.") or _is_display_only_sheet_field(field):
            continue
        return False
    return True




def _draft_requires_authoritative_aux_rebase(
    current_sheet: dict[str, Any] | None,
    fresh_sheet: dict[str, Any] | None,
) -> bool:
    if not isinstance(current_sheet, dict) or not isinstance(fresh_sheet, dict):
        return False
    if not _fresh_sheet_has_authoritative_weekly_shell(fresh_sheet):
        return False
    current_fields = [str(field).strip() for field in (current_sheet.get("fields") or []) if str(field).strip()]
    fresh_fields = [str(field).strip() for field in (fresh_sheet.get("fields") or []) if str(field).strip()]
    if not _fields_compatible_for_authoritative_weekly_shell_rebase(current_fields, fresh_fields):
        return False
    aux_fields = [
        field
        for field in fresh_fields
        if _is_aux_sheet_field(field) and field in current_fields
    ]
    if not aux_fields:
        return False
    current_rows = _sanitize_semantic_sheet_rows(
        rows_payload=current_sheet.get("rows"),
        fields=current_fields,
    )
    fresh_rows = _sanitize_semantic_sheet_rows(
        rows_payload=fresh_sheet.get("rows"),
        fields=fresh_fields,
    )
    if not current_rows or not fresh_rows:
        return False
    current_index = {field: idx for idx, field in enumerate(current_fields)}
    fresh_index = {field: idx for idx, field in enumerate(fresh_fields)}
    current_by_key: dict[tuple[str, str, str], list[str]] = {}
    for row in current_rows:
        row_key = _sheet_row_identity_key(current_fields, row)
        if row_key is None:
            continue
        current_by_key[row_key] = row
    for fresh_row in fresh_rows:
        row_key = _sheet_row_identity_key(fresh_fields, fresh_row)
        if row_key is None or row_key not in current_by_key:
            continue
        current_row = current_by_key[row_key]
        for field in aux_fields:
            current_idx = current_index.get(field)
            fresh_idx = fresh_index.get(field)
            if current_idx is None or fresh_idx is None:
                continue
            current_value = (
                _field_value_to_str(current_row[current_idx]).strip()
                if current_idx < len(current_row)
                else ""
            )
            fresh_value = (
                _field_value_to_str(fresh_row[fresh_idx]).strip()
                if fresh_idx < len(fresh_row)
                else ""
            )
            if fresh_value and current_value != fresh_value:
                return True
    return False


def _draft_requires_authoritative_schema_upgrade(
    current_sheet: dict[str, Any] | None,
    fresh_sheet: dict[str, Any] | None,
) -> bool:
    if not isinstance(current_sheet, dict) or not isinstance(fresh_sheet, dict):
        return False
    current_fields = [str(field).strip() for field in (current_sheet.get("fields") or []) if str(field).strip()]
    fresh_fields = [str(field).strip() for field in (fresh_sheet.get("fields") or []) if str(field).strip()]
    if not _fields_compatible_for_authoritative_weekly_shell_rebase(current_fields, fresh_fields):
        return False
    return current_fields != fresh_fields or _draft_requires_authoritative_aux_rebase(
        current_sheet,
        fresh_sheet,
    )


def _should_prune_unmatched_rows_on_semantic_refresh(draft: dict[str, Any] | None) -> bool:
    if not isinstance(draft, dict):
        return False
    draft_state = str(draft.get("draft_state") or "").strip().lower()
    if draft_state == "auto_apply_blocked":
        return True
    blockers = {
        str(item).strip()
        for item in (draft.get("blockers_json") or [])
        if str(item).strip()
    }
    return bool(blockers & _SEMANTIC_REFRESH_PRUNE_BLOCKERS)


def _filter_blockers_for_semantic_refresh(blockers: list[str] | None) -> list[str]:
    preserved: list[str] = []
    seen: set[str] = set()
    for item in blockers or []:
        token = str(item or "").strip()
        if not token or token in _SEMANTIC_REFRESH_PRUNE_BLOCKERS or token in seen:
            continue
        seen.add(token)
        preserved.append(token)
    return preserved


def _merge_current_draft_quantity_values_into_semantic_sheet(
    current_sheet: dict[str, Any] | None,
    fresh_sheet: dict[str, Any] | None,
    *,
    copy_shared_quantity_values: bool = False,
) -> dict[str, Any] | None:
    if not isinstance(current_sheet, dict) or not isinstance(fresh_sheet, dict):
        raise ValueError("saved_draft_row_identity_missing")

    current_fields = [str(field).strip() for field in (current_sheet.get("fields") or []) if str(field).strip()]
    fresh_fields = [str(field).strip() for field in (fresh_sheet.get("fields") or []) if str(field).strip()]
    current_rows = [list(row) for row in (current_sheet.get("rows") or []) if isinstance(row, list)]
    fresh_rows = [list(row) for row in (fresh_sheet.get("rows") or []) if isinstance(row, list)]
    if not current_fields or not fresh_fields or not current_rows or not fresh_rows:
        raise ValueError("saved_draft_row_identity_missing")
    current_kind, current_keys = _explicit_draft_row_identities(current_sheet, current_rows)
    fresh_kind, fresh_keys = _explicit_draft_row_identities(fresh_sheet, fresh_rows)
    if current_kind != fresh_kind or set(current_keys) != set(fresh_keys):
        raise ValueError("saved_draft_row_identity_unresolved")
    # Both legacy flag values preserve exact shared fields. The flag never
    # authorizes a positional pairing between different quantity fields.
    return _merge_saved_draft_into_semantic_sheet(
        current_sheet, fresh_sheet, append_unmatched_current_rows=False,
        merge_current_warnings=False,
    )


def _maybe_refresh_semantic_sheet_draft(
    order_id: str,
    draft: dict[str, Any] | None,
) -> dict[str, Any] | None:
    synchronous_write_input = _capture_synchronous_cache_write_input(order_id)
    if not _synchronous_draft_input_matches(synchronous_write_input, draft):
        return None
    if not isinstance(draft, dict):
        return draft
    if _draft_record_has_forced_repair_mode(draft):
        return draft
    draft_sheet_json = draft.get("draft_sheet_json")
    if not isinstance(draft_sheet_json, dict):
        return draft
    fresh_sheet = _build_best_available_semantic_draft(
        order_id, use_saved_draft=False, evidence_run_override=synchronous_write_input["evidence"],
    )
    if not isinstance(fresh_sheet, dict) or _draft_fields_look_generic(fresh_sheet.get("fields")):
        return draft
    clean_saved_draft = apply_gate_service.has_clean_saved_draft(draft)
    prune_unmatched_rows = _should_prune_unmatched_rows_on_semantic_refresh(draft)
    try:
        merged_sheet = _merge_saved_draft_into_semantic_sheet(
            draft_sheet_json,
            fresh_sheet,
            append_unmatched_current_rows=not prune_unmatched_rows,
            merge_current_warnings=False,
        )
    except ValueError as exc:
        if not str(exc).startswith("saved_draft_row_identity_"):
            raise
        blocked = deepcopy(draft)
        blocked["draft_state"] = "draft_blocked"
        blocked["blockers_json"] = [*list(blocked.get("blockers_json") or []), str(exc)]
        return blocked
    if not isinstance(merged_sheet, dict):
        return draft
    current_blockers = [str(item).strip() for item in (draft.get("blockers_json") or []) if str(item).strip()]
    current_warning_rows = [str(item).strip() for item in (draft.get("warnings_json") or []) if str(item).strip()]
    next_blockers = _filter_blockers_for_semantic_refresh(
        current_blockers
    )
    if prune_unmatched_rows:
        next_warnings = [str(item).strip() for item in (merged_sheet.get("warnings") or []) if str(item).strip()]
    else:
        next_warnings = list(current_warning_rows)
        merged_sheet["warnings"] = list(next_warnings)
    if (
        draft_sheet_json.get("fields") == merged_sheet.get("fields")
        and draft_sheet_json.get("header") == merged_sheet.get("header")
        and draft_sheet_json.get("rows") == merged_sheet.get("rows")
        and (
            prune_unmatched_rows is False
            or [str(item).strip() for item in (draft_sheet_json.get("warnings") or []) if str(item).strip()] == next_warnings
        )
        and current_blockers == next_blockers
        and current_warning_rows == next_warnings
    ):
        return draft
    refreshed = persist_sheet_draft(
        order_id=order_id,
        draft_sheet_json=merged_sheet,
        draft_state=str(draft.get("draft_state") or "draft_ready").strip() or "draft_ready",
        blockers=next_blockers,
        warnings=next_warnings,
        latest_patch_candidate_id=str(draft.get("latest_patch_candidate_id") or "").strip() or None,
        edited_by="semantic-sheet-refresh",
        synchronous_write_input=synchronous_write_input,
    )
    return refreshed if isinstance(refreshed, dict) else None


def get_latest_sheet_draft(
    order_id: str,
    *,
    backfill_from_revision: bool = True,
    upgrade_generic_from_sheet: bool = False,
) -> Optional[dict]:
    # `get_latest_sheet_draft` is the persisted-draft read path only.
    # Current semantic/editor surfaces must use `get_current_sheet_context`.
    _ = backfill_from_revision
    _ = upgrade_generic_from_sheet
    return draft_sheet_service.get_selected_sheet_draft(order_id)


def get_cached_hakodate_assignment_preview(order_id: str, *, captured_input: dict | None = None) -> Optional[dict[str, Any]]:
    try:
        assignment, assignment_error = build_order_hakodate_assignment(
            order_id,
            strategy="hakodate",
            allow_artifact_repair=False,
            synchronous_write_input=captured_input,
        )
        if isinstance(assignment, dict) and not assignment_error:
            return assignment
    except ValueError:
        return None
    return None


def _load_latest_hakodate_overlay_source(
    order_id: str,
    *, captured_input: dict | None = None,
) -> tuple[dict[str, Any], str | None, bool]:
    try:
        captured_input = captured_input if captured_input is not None else _capture_synchronous_cache_write_input(order_id)
    except ocr_evidence_service.SelectedEvidenceRejected:
        raise
    except ValueError:
        return {}, None, False
    if captured_input is None:
        return {}, None, False
    latest_evidence = captured_input["evidence"]
    try:
        _validate_selected_hakodate_artifacts(latest_evidence, captured_input)
    except ValueError as exc:
        raise ocr_evidence_service.SelectedEvidenceRejected(str(exc)) from exc
    latest_payload = latest_evidence.get("payload_json") if isinstance(latest_evidence, dict) else None
    if (
        isinstance(latest_payload, dict)
        and _payload_has_current_hakodate_canonical_pipeline(latest_payload)
        and _payload_has_hakodate_target_cells(latest_payload)
    ):
        return (
            evidence_manifest_service.ensure_evidence_manifest(dict(latest_payload)),
            str(latest_evidence.get("id") or "").strip() or None,
            True,
        )
    return {}, None, False


def ensure_hakodate_evidence_draft_current(
    order_id: str,
    *,
    edited_by: str | None = None,
    synchronous_write_input: dict[str, Any] | None = None,
) -> tuple[Optional[dict], Optional[str]]:
    """Keep visible sheet surfaces on the Hakodate evidence projection when it exists."""
    if not isinstance(synchronous_write_input, dict):
        return None, "synchronous_input_missing"
    selected_evidence = synchronous_write_input["evidence"]
    selected_payload = selected_evidence.get("payload_json")
    if not (
        isinstance(selected_payload, dict)
        and _payload_has_current_hakodate_canonical_pipeline(selected_payload)
        and _payload_has_hakodate_target_cells(selected_payload)
        and _payload_has_hakodate_evidence_records(selected_payload, order_id=order_id)
    ):
        return None, "hakodate_ocr_evidence_missing"
    current_draft = synchronous_write_input.get("draft")
    if _draft_payload_has_hakodate_evidence_projection(current_draft):
        return current_draft, None

    switched_draft, switch_error = switch_draft_to_latest_evidence(
        order_id,
        edited_by=edited_by or "auto-hakodate-evidence-current-draft",
        synchronous_write_input=synchronous_write_input,
        evidence_run_override=selected_evidence,
    )
    if isinstance(switched_draft, dict):
        return switched_draft, None
    if switch_error and switch_error not in {"order_not_found", "facility_missing", "facility_not_found", "template_unresolved"}:
        return None, switch_error

    projected_bundle, projected_error = build_order_hakodate_projected_sheet(
        order_id,
        strategy="hakodate",
        evidence_run_override=selected_evidence,
        synchronous_write_input=synchronous_write_input,
    )
    draft_payload = (
        projected_bundle.get("projected_sheet")
        if isinstance(projected_bundle, dict) and isinstance(projected_bundle.get("projected_sheet"), dict)
        else None
    )
    if isinstance(draft_payload, dict):
        persisted = _persist_sheet_draft_with_base_evidence(
            order_id=order_id,
            draft_sheet_json=draft_payload,
            draft_state="draft_blocked" if draft_payload.get("blockers") else "draft_ready",
            blockers=[str(item).strip() for item in (draft_payload.get("blockers") or []) if str(item).strip()],
            warnings=[str(item).strip() for item in (draft_payload.get("warnings") or []) if str(item).strip()],
            evidence_run_override=selected_evidence,
            synchronous_write_input=synchronous_write_input,
            edited_by=edited_by or "auto-hakodate-evidence-current-draft",
        )
        if isinstance(persisted, dict):
            return persisted, None
    if projected_error in {"order_not_found", "facility_missing", "facility_not_found", "template_unresolved"}:
        return None, projected_error
    return None, "hakodate_current_sheet_sync_failed"


def get_hakodate_pipeline_job_status(order_id: str) -> dict[str, Any]:
    normalized_order_id = str(order_id or "").strip()
    job = get_latest_order_job(normalized_order_id) if normalized_order_id else None
    if not isinstance(job, dict):
        return {**describe_ocr_job_state(None), "job_status": None}
    request_mode = get_job_request_mode(job)
    if request_mode and request_mode not in {"ocr_rerun", "ocr_reparse", "llm_reparse"}:
        return {**describe_ocr_job_state(None), "job_status": None}
    state = describe_ocr_job_state(job)
    metrics = job.get("metrics")
    metrics = metrics if isinstance(metrics, dict) else {}
    return {
        **state,
        "job_status": _recorded_hospital_job_status(job, state),
        "request_mode": request_mode or None,
        "processing_stage": str(metrics.get("processing_stage") or "").strip() or None,
        "result_state": str(metrics.get("result_state") or "").strip() or None,
        "error": (
            str(metrics.get("error") or "").strip()
            or str(job.get("error_message") or "").strip()
            or None
        ),
        "output_reference": str(job.get("output_reference") or "").strip() or None,
    }


def get_cached_hakodate_overlay_preview(order_id: str) -> dict[str, Any]:
    job_status = get_hakodate_pipeline_job_status(order_id)
    try:
        captured_input = _capture_synchronous_cache_write_input(order_id)
        if captured_input is None:
            raise ValueError("synchronous_input_missing")
    except ValueError as exc:
        return {"status": "blocked", "blockers": [str(exc)], "overlay_url": None, "overlay_uri": None, "assignment": None, "job_status": job_status}
    try:
        overlay_payload, evidence_run_id, has_latest_hakodate_evidence = _load_latest_hakodate_overlay_source(order_id, captured_input=captured_input)
    except ocr_evidence_service.SelectedEvidenceRejected as exc:
        return {"status": "blocked", "blockers": [str(exc)], "overlay_url": None, "overlay_uri": None, "assignment": None, "job_status": job_status}
    if not isinstance(overlay_payload, dict):
        return {
            "status": "blocked",
            "blockers": ["hakodate_overlay_artifact_missing"],
            "message": _describe_hakodate_overlay_blocker("hakodate_overlay_artifact_missing"),
            "overlay_url": None,
            "overlay_uri": None,
            "assignment": None,
            "source_evidence_run_id": evidence_run_id,
            "job_status": job_status,
        }
    overlay = overlay_payload.get("hakodate_overlay")
    if not isinstance(overlay, dict):
        return {
            "status": "blocked",
            "blockers": ["hakodate_overlay_artifact_missing"],
            "message": _describe_hakodate_overlay_blocker("hakodate_overlay_artifact_missing"),
            "overlay_url": None,
            "overlay_uri": None,
            "assignment": get_cached_hakodate_assignment_preview(order_id, captured_input=captured_input),
            "source_evidence_run_id": evidence_run_id,
            "latest_hakodate_evidence": has_latest_hakodate_evidence,
            "job_status": job_status,
        }
    overlay_producer = str(overlay.get("producer") or "").strip()
    overlay_uri = str(overlay.get("uri") or "").strip()
    overlay_fingerprint = str(overlay.get("fingerprint") or "").strip()
    overlay_version = str(overlay.get("version") or "").strip()
    if (
        overlay_producer != "hakodate_best_method_pipeline"
        or not _hakodate_version_matches_current(
            overlay_version,
        )
    ):
        return {
            "status": "blocked",
            "blockers": ["hakodate_overlay_render_unavailable"],
            "message": _describe_hakodate_overlay_blocker("hakodate_overlay_render_unavailable"),
            "overlay_url": None,
            "overlay_uri": overlay_uri or None,
            "assignment": None,
            "source_evidence_run_id": evidence_run_id,
            "latest_hakodate_evidence": has_latest_hakodate_evidence,
            "job_status": job_status,
        }
    if not overlay_uri or not overlay_fingerprint:
        return {
            "status": "blocked",
            "blockers": ["hakodate_overlay_artifact_missing"],
            "message": _describe_hakodate_overlay_blocker("hakodate_overlay_artifact_missing"),
            "overlay_url": None,
            "overlay_uri": overlay_uri or None,
            "assignment": get_cached_hakodate_assignment_preview(order_id, captured_input=captured_input),
            "source_evidence_run_id": evidence_run_id,
            "latest_hakodate_evidence": has_latest_hakodate_evidence,
            "job_status": job_status,
        }
    assignment = get_cached_hakodate_assignment_preview(order_id, captured_input=captured_input)
    if not isinstance(assignment, dict):
        return {
            "status": "blocked",
            "blockers": ["hakodate_assignment_preview_missing"],
            "message": _describe_hakodate_overlay_blocker("hakodate_assignment_unavailable"),
            "overlay_url": None,
            "overlay_uri": overlay_uri,
            "assignment": None,
            "source_evidence_run_id": evidence_run_id,
            "latest_hakodate_evidence": has_latest_hakodate_evidence,
            "job_status": job_status,
        }
    overlay_url = _signed_url_from_uri(overlay_uri)
    if not overlay_url:
        return {
            "status": "blocked",
            "blockers": ["hakodate_overlay_render_unavailable"],
            "message": _describe_hakodate_overlay_blocker("hakodate_overlay_render_unavailable"),
            "overlay_url": None,
            "overlay_uri": overlay_uri,
            "assignment": assignment,
            "source_evidence_run_id": evidence_run_id,
            "latest_hakodate_evidence": has_latest_hakodate_evidence,
            "job_status": job_status,
        }
    try:
        current_authority = _capture_synchronous_cache_write_input(order_id)
        if current_authority is None or any(not snapshots_equal(captured_input.get(key), value) for key, value in current_authority.items()):
            raise ValueError("synchronous_input_conflict")
    except ValueError as exc:
        return {"status": "blocked", "blockers": [str(exc)], "overlay_url": None, "overlay_uri": overlay_uri, "assignment": None, "source_evidence_run_id": evidence_run_id, "job_status": job_status}
    return {
        "status": "ready",
        "blockers": list(assignment.get("blockers") or []),
        "message": "",
        "overlay_uri": overlay_uri,
        "overlay_url": overlay_url,
        "assignment": assignment,
        "source_evidence_run_id": evidence_run_id,
        "latest_hakodate_evidence": has_latest_hakodate_evidence,
        "job_status": job_status,
    }


def get_hakodate_overlay_preview(order_id: str) -> dict[str, Any]:
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return {
                "status": "blocked",
                "blockers": ["order_not_found"],
                "message": "order not found",
                "overlay_url": None,
                "overlay_uri": None,
                "assignment": None,
            }
        document_uri = str(order.document_uri or "").strip() or None
    return _build_hakodate_overlay_preview(
        order_id=order_id,
        document_uri=document_uri,
    )


