def _candidate_preview_signature(
    order_id: str,
    payload: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if not isinstance(payload, dict):
        return None
    flattened = flatten_current_sheet_payload(order_id, payload, include_meta=False)
    if not isinstance(flattened, dict):
        return None
    return {
        "sheet_digest": _sheet_digest(
            fields=flattened.get("fields"),
            header=flattened.get("header"),
            rows_payload=flattened.get("rows"),
            row_ids=flattened.get("row_ids"),
        ),
        "source": str(flattened.get("source") or "").strip() or None,
        "draft_state": str(flattened.get("draft_state") or "").strip() or None,
        "warnings": tuple(_dedupe_str_tokens(flattened.get("warnings") or [])),
        "blockers": tuple(_dedupe_str_tokens(flattened.get("blockers") or [])),
    }


def resolve_candidate_evidence_preview_contract(
    order_id: str,
    *,
    candidate_evidence_run: dict[str, Any] | None = None,
    candidate_evidence_run_id: str | None = None,
    current_sheet_context: dict[str, Any] | None = None,
    current_sheet_context_supplied: bool = False,
) -> dict[str, Any]:
    normalized_order_id = str(order_id or "").strip()
    resolved_candidate_evidence_run_id = (
        str(candidate_evidence_run_id or "").strip()
        or str((candidate_evidence_run or {}).get("id") or "").strip()
        or None
    )
    resolved_candidate_evidence_run = (
        candidate_evidence_run
        if isinstance(candidate_evidence_run, dict)
        else get_ocr_evidence_run(resolved_candidate_evidence_run_id or "")
    )
    result: dict[str, Any] = {
        "order_id": normalized_order_id,
        "candidate_evidence_run_id": resolved_candidate_evidence_run_id,
        "status": "candidate_not_found",
        "error": "candidate_not_found",
        "previewable": False,
        "has_material_diff": False,
        "preview_draft": None,
        "draft_payload": None,
    }
    if not normalized_order_id or not isinstance(resolved_candidate_evidence_run, dict):
        return result

    current_context = (
        current_sheet_context
        if current_sheet_context_supplied or isinstance(current_sheet_context, dict)
        else get_current_sheet_context(
            normalized_order_id,
            refresh_draft_from_semantic=True,
            upgrade_generic_from_sheet=True,
            backfill_from_revision=False,
        )
    )
    current_base_evidence_run_id = (
        str((current_context or {}).get("base_evidence_run_id") or "").strip() or None
    )
    if current_base_evidence_run_id and current_base_evidence_run_id == resolved_candidate_evidence_run_id:
        return {
            **result,
            "status": "already_current",
            "error": "already_current",
        }

    draft_payload, build_error = _build_best_available_semantic_draft_with_error(
        normalized_order_id,
        use_saved_draft=False,
        evidence_run_override=resolved_candidate_evidence_run,
    )
    if not isinstance(draft_payload, dict):
        return {
            **result,
            "status": "candidate_preview_blocked",
            "error": build_error or "candidate_preview_unavailable",
        }

    transient = _build_transient_draft_record(normalized_order_id, draft_payload)
    if not isinstance(transient, dict):
        return {
            **result,
            "status": "candidate_preview_blocked",
            "error": "candidate_preview_unavailable",
            "draft_payload": draft_payload,
        }

    current_signature = _candidate_preview_signature(normalized_order_id, current_context)
    candidate_signature = _candidate_preview_signature(normalized_order_id, transient)
    if current_signature is not None and current_signature == candidate_signature:
        return {
            **result,
            "status": "already_current",
            "error": "already_current",
            "draft_payload": draft_payload,
        }

    return {
        **result,
        "status": "previewable",
        "error": None,
        "previewable": True,
        "has_material_diff": True,
        "preview_draft": transient,
        "draft_payload": draft_payload,
    }


def build_initial_sheet_draft(order_id: str) -> Optional[dict]:
    payload, error = get_ocr_sheet(order_id, use_saved_draft=False)
    if error:
        raise ValueError(error)
    return payload


def _build_transient_draft_record(
    order_id: str,
    sheet_payload: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if not isinstance(sheet_payload, dict):
        return None
    blockers = _dedupe_str_tokens(sheet_payload.get("blockers") or [])
    warnings = _dedupe_str_tokens(sheet_payload.get("warnings") or [])
    draft_state = str(
        sheet_payload.get("draft_state")
        or ("draft_blocked" if blockers else "draft_ready")
    ).strip() or ("draft_blocked" if blockers else "draft_ready")
    return {
        "id": None,
        "order_id": order_id,
        "base_evidence_run_id": sheet_payload.get("base_evidence_run_id"),
        "base_template_resolution_id": str(sheet_payload.get("base_template_resolution_id") or "").strip() or None,
        "base_menu_snapshot_id": None,
        "draft_sheet_json": sheet_payload,
        "draft_state": draft_state,
        "blockers_json": blockers,
        "warnings_json": warnings,
        "latest_patch_candidate_id": None,
        "edited_by": None,
        "edited_at": None,
        "created_at": None,
    }


def candidate_sheet_state(
    order_id: str,
    *,
    candidate_evidence_run_id: str | None,
    current_sheet_context: dict[str, Any] | None = None,
    current_sheet_context_supplied: bool = False,
) -> dict[str, Any]:
    normalized_candidate_evidence_run_id = str(candidate_evidence_run_id or "").strip() or None
    current_context = (
        current_sheet_context
        if current_sheet_context_supplied or isinstance(current_sheet_context, dict)
        else get_current_sheet_context(
            order_id,
            refresh_draft_from_semantic=True,
            upgrade_generic_from_sheet=True,
            backfill_from_revision=False,
        )
    )
    current_sheet_revision_id = (
        _current_sheet_revision_id_from_payload(current_context)
        or (None if current_sheet_context_supplied else _current_sheet_revision_id(order_id=order_id))
    )
    current_payload = (
        flatten_current_sheet_payload(order_id, current_context, include_meta=False)
        if isinstance(current_context, dict)
        else None
    )
    current_base_evidence_run_id = (
        str((current_context or {}).get("base_evidence_run_id") or "").strip()
        or str((current_payload or {}).get("base_evidence_run_id") or "").strip()
        or None
    )
    result: dict[str, Any] = {
        "candidate_evidence_run_id": normalized_candidate_evidence_run_id,
        "current_sheet_revision_id": current_sheet_revision_id or None,
        "current_base_evidence_run_id": current_base_evidence_run_id,
        "candidate_preview_available": False,
        "candidate_preview_error": "candidate_not_found" if not normalized_candidate_evidence_run_id else None,
        "candidate_has_meaningful_diff": False,
        "candidate_preview_draft": None,
    }
    if not normalized_candidate_evidence_run_id:
        return result
    contract = resolve_candidate_evidence_preview_contract(
        order_id,
        candidate_evidence_run_id=normalized_candidate_evidence_run_id,
        current_sheet_context=current_context,
        current_sheet_context_supplied=True,
    )
    result["candidate_preview_available"] = bool(contract.get("previewable"))
    result["candidate_preview_error"] = str(contract.get("error") or "").strip() or None
    result["candidate_has_meaningful_diff"] = bool(contract.get("has_material_diff"))
    preview_draft = contract.get("preview_draft") if isinstance(contract.get("preview_draft"), dict) else None
    if isinstance(preview_draft, dict):
        draft_payload = (
            preview_draft.get("draft_sheet_json")
            if isinstance(preview_draft.get("draft_sheet_json"), dict)
            else None
        )
        preview_base_evidence_run_id = (
            str(preview_draft.get("base_evidence_run_id") or "").strip()
            or str((draft_payload or {}).get("base_evidence_run_id") or "").strip()
            or normalized_candidate_evidence_run_id
            or None
        )
        if preview_base_evidence_run_id:
            preview_draft["base_evidence_run_id"] = preview_base_evidence_run_id
            if isinstance(draft_payload, dict):
                draft_payload["base_evidence_run_id"] = preview_base_evidence_run_id
        preview_draft["current_sheet_revision_id"] = current_sheet_revision_id or None
    result["candidate_preview_draft"] = preview_draft
    return result


def _draft_is_reparse_candidate_only(draft: dict[str, Any] | None) -> bool:
    if not isinstance(draft, dict):
        return False
    draft_payload = (
        draft.get("draft_sheet_json")
        if isinstance(draft.get("draft_sheet_json"), dict)
        else draft
    )
    source = str((draft_payload or {}).get("source") or "").strip()
    edited_by = str(draft.get("edited_by") or "").strip()
    latest_patch_candidate_id = str(draft.get("latest_patch_candidate_id") or "").strip()
    return (
        source == "reparse_candidate"
        or edited_by == "reparse-reject-candidate"
        or latest_patch_candidate_id == "reparse-candidate"
    )


_AUTO_REBUILT_DRAFT_EDITORS = {
    "facility-schema-rebase",
    "facility-selection-refresh",
    "facility-template-columns-save",
    "semantic-sheet-refresh",
    "semantic-sheet-upgrade",
    "legacy-revision-backfill",
    "rerun-ocr-evidence",
}
_AUTHORITATIVE_CURRENT_SHEET_EDITORS = {
    "manual-weekly-menu-overwrite",
    "manual-facility-schema-overwrite",
    "switch-evidence",
}
_AUTHORITATIVE_CURRENT_SHEET_SOURCES = {
    "edited_sheet_exact",
    "hakodate_ocr_evidence_sheet",
    "manual_draft",
    "draft_sheet",
}
_NON_AUTHORITATIVE_CURRENT_SHEET_SOURCES = {
    "ocr_evidence",
    "legacy_cache",
    "edited_sheet",
    "review_blocked",
    "weekly_menu",
    "weekly_menu+ocr_payload",
    "weekly_menu_blocked",
    "ocr_sheet",
    "reparse_candidate",
}

_FORCED_WEEKLY_MENU_REPAIR_MODE = "forced_weekly_menu_overwrite"
_FORCED_FACILITY_SCHEMA_REPAIR_MODE = "forced_facility_schema_overwrite"
_FORCED_REPAIR_MODES = {
    _FORCED_WEEKLY_MENU_REPAIR_MODE,
    _FORCED_FACILITY_SCHEMA_REPAIR_MODE,
}


def _draft_payload_repair_mode(draft_payload: dict[str, Any] | None) -> str | None:
    if not isinstance(draft_payload, dict):
        return None
    direct_mode = str(draft_payload.get("repair_mode") or "").strip()
    if direct_mode:
        return direct_mode
    repair_metadata = draft_payload.get("repair_metadata")
    if isinstance(repair_metadata, dict):
        return str(repair_metadata.get("mode") or "").strip() or None
    return None


def _draft_record_has_forced_repair_mode(draft_record: dict[str, Any] | None) -> bool:
    if not isinstance(draft_record, dict):
        return False
    draft_payload = (
        draft_record.get("draft_sheet_json")
        if isinstance(draft_record.get("draft_sheet_json"), dict)
        else draft_record
    )
    return _draft_payload_repair_mode(draft_payload) in _FORCED_REPAIR_MODES


def _draft_record_has_semantic_sheet_contract(
    draft_record: dict[str, Any] | None,
) -> bool:
    if not isinstance(draft_record, dict):
        return False
    draft_payload = (
        draft_record.get("draft_sheet_json")
        if isinstance(draft_record.get("draft_sheet_json"), dict)
        else draft_record
    )
    if not isinstance(draft_payload, dict):
        return False
    fields = list(draft_payload.get("fields") or [])
    rows = draft_payload.get("rows")
    if not apply_gate_service.sheet_fields_are_semantic(fields):
        return False
    return isinstance(rows, list) and len(rows) > 0


def _draft_record_is_selected_saved_sheet(draft_record: dict[str, Any] | None) -> bool:
    if not isinstance(draft_record, dict) or draft_record.get("draft_state") != "saved":
        return False
    order_id = draft_record.get("order_id")
    if not order_id or not draft_record.get("id"):
        return False
    selected = draft_sheet_service.get_selected_sheet_draft(order_id)
    return isinstance(selected, dict) and snapshots_equal(selected, draft_record)


def _draft_record_is_authoritative_current_sheet(
    draft_record: dict[str, Any] | None,
) -> bool:
    if not isinstance(draft_record, dict):
        return False
    if not str(draft_record.get("id") or "").strip():
        return False
    if _draft_is_reparse_candidate_only(draft_record):
        return False
    if (draft_record.get("draft_sheet_json") or {}).get("adopted") is False:
        return False
    if draft_record.get("draft_state") == "saved":
        return _draft_record_is_selected_saved_sheet(draft_record)
    if _draft_record_has_forced_repair_mode(draft_record):
        return True
    draft_payload = (
        draft_record.get("draft_sheet_json")
        if isinstance(draft_record.get("draft_sheet_json"), dict)
        else draft_record
    )
    source = str((draft_payload or {}).get("source") or "").strip()
    edited_by = str(draft_record.get("edited_by") or "").strip()
    has_semantic_sheet_contract = _draft_record_has_semantic_sheet_contract(draft_record)
    if edited_by in _AUTO_REBUILT_DRAFT_EDITORS:
        return False
    if edited_by in _AUTHORITATIVE_CURRENT_SHEET_EDITORS:
        return True
    if source in _AUTHORITATIVE_CURRENT_SHEET_SOURCES:
        return True
    if source in _NON_AUTHORITATIVE_CURRENT_SHEET_SOURCES:
        return has_semantic_sheet_contract
    if has_semantic_sheet_contract:
        return True
    return apply_gate_service.has_clean_saved_draft(draft_record)


def _blank_quantity_values_in_sheet_payload(
    sheet_payload: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if not isinstance(sheet_payload, dict):
        return None
    fields = [
        str(field).strip()
        for field in (sheet_payload.get("fields") or [])
        if str(field).strip()
    ]
    quantity_indexes = [
        idx for idx, field in enumerate(fields) if field.startswith("qty.")
    ]
    if not quantity_indexes:
        return dict(sheet_payload)
    blanked_rows: list[list[Any]] = []
    for row in (sheet_payload.get("rows") or []):
        if not isinstance(row, list):
            continue
        current = list(row)
        for idx in quantity_indexes:
            while len(current) <= idx:
                current.append("")
            current[idx] = ""
        blanked_rows.append(current)
    blanked = dict(sheet_payload)
    blanked["rows"] = blanked_rows
    return blanked


def _load_latest_quantity_preservation_source_draft(
    order_id: str,
    *,
    fallback_draft: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    if isinstance(fallback_draft, dict):
        if _draft_record_is_authoritative_current_sheet(fallback_draft):
            return fallback_draft
    normalized_order_id = str(order_id or "").strip()
    if not normalized_order_id:
        return fallback_draft if isinstance(fallback_draft, dict) else None
    selected = draft_sheet_service.get_selected_sheet_draft(normalized_order_id)
    return selected if _draft_record_is_authoritative_current_sheet(selected) else None


def _load_current_sheet_facility_template(
    facility_id: str | None,
    *,
    order_id: str | None = None,
    ocr_payload: dict[str, Any] | None = None,
    draft_template_id: str | None = None,
) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    facility_config, template, _template_id, _template_error = _resolve_effective_sheet_template(
        order_id=order_id,
        facility_id=facility_id,
        ocr_payload=ocr_payload,
        draft_template_id=draft_template_id,
        allow_workflow_resolution=False,
        log_context="Facility config lookup failed for current sheet template",
    )
    return facility_config, template


def _current_sheet_schema_snapshot_for_facility(
    facility_id: str | None,
    *,
    order_id: str | None = None,
    ocr_payload: dict[str, Any] | None = None,
    draft_template_id: str | None = None,
) -> dict[str, Any] | None:
    _facility_config, template = _load_current_sheet_facility_template(
        facility_id,
        order_id=order_id,
        ocr_payload=ocr_payload,
        draft_template_id=draft_template_id,
    )
    if not isinstance(template, dict):
        return None
    fields, _field_index = _build_sheet_fields_and_indexes(template)
    if not fields:
        return None
    return {
        "fields": fields,
        "header": _sheet_header_from_template(fields, template),
    }


def _resolve_draft_record_base_evidence_run(
    draft_record: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if not isinstance(draft_record, dict):
        return None
    evidence_run_id = str(draft_record.get("base_evidence_run_id") or "").strip()
    if not evidence_run_id:
        return None
    evidence_run = get_ocr_evidence_run(evidence_run_id)
    return evidence_run if isinstance(evidence_run, dict) else None


def _resolve_evidence_run_template_resolution_id(
    evidence_run: dict[str, Any] | None,
) -> str | None:
    if not isinstance(evidence_run, dict):
        return None
    payload_json = evidence_run.get("payload_json")
    if not isinstance(payload_json, dict):
        return None
    resolution = payload_json.get("template_resolution")
    if not isinstance(resolution, dict):
        return None
    return (
        str(resolution.get("resolved_template_id") or resolution.get("template_id") or "").strip()
        or None
    )


def _persist_sheet_draft_with_base_evidence(
    *,
    order_id: str,
    draft_sheet_json: dict[str, Any],
    draft_state: str = "draft_ready",
    blockers: list[str] | None = None,
    warnings: list[str] | None = None,
    latest_patch_candidate_id: str | None = None,
    edited_by: str | None = None,
    evidence_run_override: dict[str, Any] | None = None,
    base_evidence_run_id_override: str | None = None,
    base_template_resolution_id_override: str | None = None,
    workflow_job_id: str | None = None,
    synchronous_write_input: dict[str, Any] | None = None,
    write_session: Any = None,
) -> dict[str, Any] | None:
    if isinstance(synchronous_write_input, dict):
        captured_evidence = synchronous_write_input.get("evidence")
        if not isinstance(captured_evidence, dict):
            return None
        if evidence_run_override is not None and evidence_run_override != captured_evidence:
            return None
        if base_evidence_run_id_override and base_evidence_run_id_override != captured_evidence.get("id"):
            return None
        evidence_run_override = captured_evidence
    base_evidence_run_id = str(base_evidence_run_id_override or "").strip() or None
    base_template_resolution_id = str(base_template_resolution_id_override or "").strip() or None
    template_version_id = None
    if not isinstance(evidence_run_override, dict) and base_evidence_run_id:
        evidence_run_override = get_ocr_evidence_run(base_evidence_run_id)
    if isinstance(evidence_run_override, dict):
        evidence_id = str(evidence_run_override.get("id") or "").strip()
        if not evidence_id or (base_evidence_run_id and base_evidence_run_id != evidence_id):
            return None
        base_evidence_run_id = evidence_id
        template_version_id = str(evidence_run_override.get("template_version_id") or "").strip() or None
        evidence_resolution_id = _resolve_evidence_run_template_resolution_id(evidence_run_override)
        if base_template_resolution_id and base_template_resolution_id != evidence_resolution_id:
            return None
        base_template_resolution_id = evidence_resolution_id
    if not isinstance(evidence_run_override, dict) or evidence_run_override.get("order_id") != order_id:
        return None
    captured_job_id = workflow_job_id or _workflow_ocr_job_id.get()
    if _workflow_ocr_attempt_id.get() is not None and not captured_job_id:
        return None
    if not captured_job_id and synchronous_write_input is None:
        return None
    return draft_sheet_service.persist_sheet_draft(
        order_id=order_id,
        draft_sheet_json=draft_sheet_json,
        base_evidence_run_id=base_evidence_run_id,
        template_version_id=template_version_id,
        base_template_resolution_id=base_template_resolution_id,
        draft_state=draft_state,
        blockers=blockers,
        warnings=warnings,
        latest_patch_candidate_id=latest_patch_candidate_id,
        edited_by=edited_by,
        workflow_attempt_id=_workflow_ocr_attempt_id.get(),
        workflow_job_id=captured_job_id,
        expected_workflow_revision=_workflow_ocr_revision.get(),
        synchronous_write_input=synchronous_write_input,
        write_session=write_session,
    )


def _draft_payload_has_hakodate_evidence_projection(draft_record: dict[str, Any] | None) -> bool:
    if not isinstance(draft_record, dict):
        return False
    payload = draft_record.get("draft_sheet_json")
    if not isinstance(payload, dict):
        payload = draft_record
    projection = payload.get("hakodate_evidence_projection")
    if not isinstance(projection, dict):
        return False
    version = str(projection.get("version") or payload.get("hakodate_projection_version") or "").strip()
    if version and version != HAKODATE_EVIDENCE_PROJECTION_VERSION:
        return False
    metrics = projection.get("metrics")
    return str(payload.get("source") or "").strip() == "hakodate_ocr_evidence_sheet" and isinstance(metrics, dict)


def _rebase_draft_record_to_facility_schema(
    order_id: str,
    draft_record: dict[str, Any] | None,
    *,
    edited_by: str,
    synchronous_write_input: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if not _synchronous_draft_input_matches(synchronous_write_input, draft_record):
        return None
    if not isinstance(draft_record, dict):
        return None
    if _draft_record_has_forced_repair_mode(draft_record):
        return draft_record
    draft_sheet_json = (
        draft_record.get("draft_sheet_json")
        if isinstance(draft_record.get("draft_sheet_json"), dict)
        else draft_record
    )
    if not isinstance(draft_sheet_json, dict):
        return draft_record
    rebase_required, rebuilt_sheet = _draft_record_requires_current_sheet_semantic_rebase(
        order_id,
        draft_record,
        evidence_run_override=synchronous_write_input["evidence"],
        synchronous_write_input=synchronous_write_input,
    )
    if not rebase_required:
        return draft_record
    clean_saved_draft = apply_gate_service.has_clean_saved_draft(draft_record)
    try:
        _explicit_draft_row_identities(draft_sheet_json, draft_sheet_json.get("rows") or [])
        _explicit_draft_row_identities({"row_ids": draft_sheet_json.get("row_ids")}, draft_sheet_json.get("rows") or [])
        if rebuilt_sheet is None:
            rebuilt_sheet = _build_fresh_semantic_sheet_for_draft_rebase(
                order_id, draft_record, evidence_run_override=synchronous_write_input["evidence"],
                synchronous_write_input=synchronous_write_input,
            )
        if not isinstance(rebuilt_sheet, dict):
            return None
        rebased_sheet = _merge_saved_draft_into_semantic_sheet(
            draft_sheet_json,
            rebuilt_sheet,
            append_unmatched_current_rows=(
                not _should_prune_unmatched_rows_on_semantic_refresh(draft_record)
            ),
            merge_current_warnings=not clean_saved_draft,
        )
    except ValueError as exc:
        if not str(exc).startswith("saved_draft_row_identity_"):
            raise
        blocked = deepcopy(draft_record)
        blocked["draft_state"] = "draft_blocked"
        blocked["blockers_json"] = [*list(blocked.get("blockers_json") or []), str(exc)]
        return blocked
    if not isinstance(rebased_sheet, dict):
        return draft_record
    if clean_saved_draft:
        rebased_sheet = dict(rebased_sheet)
        rebased_sheet["warnings"] = []
    evidence_run_override = synchronous_write_input["evidence"]
    current_blockers = [str(item).strip() for item in (draft_record.get("blockers_json") or []) if str(item).strip()]
    current_warnings = [str(item).strip() for item in (draft_record.get("warnings_json") or []) if str(item).strip()]
    next_blockers = _filter_blockers_for_semantic_refresh(current_blockers)
    next_warnings = (
        [str(item).strip() for item in (rebased_sheet.get("warnings") or []) if str(item).strip()]
        if not clean_saved_draft
        else []
    )
    if (
        draft_sheet_json.get("fields") == rebased_sheet.get("fields")
        and draft_sheet_json.get("header") == rebased_sheet.get("header")
        and draft_sheet_json.get("rows") == rebased_sheet.get("rows")
        and draft_sheet_json.get("row_ids") == rebased_sheet.get("row_ids")
        and draft_sheet_json.get("physical_menu_row_ids") == rebased_sheet.get("physical_menu_row_ids")
        and draft_sheet_json.get("physical_menu_row_count") == rebased_sheet.get("physical_menu_row_count")
        and current_blockers == next_blockers
        and current_warnings == next_warnings
    ):
        return draft_record
    persisted = _persist_sheet_draft_with_base_evidence(
        order_id=order_id,
        draft_sheet_json=rebased_sheet,
        draft_state=str(draft_record.get("draft_state") or "draft_ready").strip() or "draft_ready",
        blockers=next_blockers,
        warnings=next_warnings,
        latest_patch_candidate_id=str(draft_record.get("latest_patch_candidate_id") or "").strip() or None,
        edited_by=edited_by,
        evidence_run_override=evidence_run_override,
        base_evidence_run_id_override=str(draft_record.get("base_evidence_run_id") or "").strip() or None,
        base_template_resolution_id_override=str(draft_record.get("base_template_resolution_id") or "").strip() or None,
        synchronous_write_input=synchronous_write_input,
    )
    return persisted if isinstance(persisted, dict) else None


def _rebuild_current_sheet_for_facility_schema(
    order_id: str,
    *,
    edited_by: str,
    blank_quantities: bool = False,
    synchronous_write_input: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    if _workflow_ocr_job_id.get() is None:
        if synchronous_write_input is None:
            synchronous_write_input = _capture_synchronous_cache_write_input(order_id)
        if not isinstance(synchronous_write_input, dict):
            return None
        current_draft_before_rebuild = synchronous_write_input.get("draft")
    else:
        current_draft_before_rebuild = draft_sheet_service.get_selected_sheet_draft(order_id)
    quantity_preservation_draft = (
        current_draft_before_rebuild if isinstance(synchronous_write_input, dict)
        else _load_latest_quantity_preservation_source_draft(
            order_id, fallback_draft=current_draft_before_rebuild,
        )
    )
    current_draft_sheet = (
        quantity_preservation_draft.get("draft_sheet_json")
        if isinstance(quantity_preservation_draft, dict)
        and isinstance(quantity_preservation_draft.get("draft_sheet_json"), dict)
        else None
    )
    evidence_run_override = (
        synchronous_write_input["evidence"] if isinstance(synchronous_write_input, dict)
        else _resolve_draft_record_base_evidence_run(current_draft_before_rebuild)
    )
    if isinstance(synchronous_write_input, dict) and isinstance(quantity_preservation_draft, dict):
        rebuilt_sheet = _build_fresh_semantic_sheet_for_draft_rebase(
            order_id, quantity_preservation_draft,
            evidence_run_override=evidence_run_override,
            synchronous_write_input=synchronous_write_input,
        )
    else:
        rebuilt_sheet = _build_best_available_semantic_draft(
            order_id,
            use_saved_draft=False,
            evidence_run_override=evidence_run_override,
        )
    if not isinstance(rebuilt_sheet, dict):
        return None
    draft_sheet_to_persist = _merge_current_draft_quantity_values_into_semantic_sheet(
        current_draft_sheet, rebuilt_sheet,
    )
    if blank_quantities:
        draft_sheet_to_persist = _blank_quantity_values_in_sheet_payload(draft_sheet_to_persist)
    if not isinstance(draft_sheet_to_persist, dict):
        raise ValueError("saved_draft_row_identity_missing")
    clean_preservation_source = apply_gate_service.has_clean_saved_draft(
        quantity_preservation_draft
        if isinstance(quantity_preservation_draft, dict)
        else current_draft_before_rebuild
    )
    if clean_preservation_source:
        draft_sheet_to_persist = dict(draft_sheet_to_persist)
        draft_sheet_to_persist["warnings"] = []
    return _persist_sheet_draft_with_base_evidence(
        order_id=order_id,
        draft_sheet_json=draft_sheet_to_persist,
        draft_state="draft_ready",
        blockers=[],
        warnings=(
            []
            if clean_preservation_source
            else [
                str(item).strip()
                for item in (draft_sheet_to_persist.get("warnings") or [])
                if str(item).strip()
            ]
        ),
        edited_by=edited_by,
        evidence_run_override=evidence_run_override,
        base_evidence_run_id_override=(
            str((current_draft_before_rebuild or {}).get("base_evidence_run_id") or "").strip() or None
        ),
        base_template_resolution_id_override=(
            str((current_draft_before_rebuild or {}).get("base_template_resolution_id") or "").strip() or None
        ),
        synchronous_write_input=synchronous_write_input,
    )


def _current_sheet_context_uses_canonical_snapshot(
    *,
    refresh_draft_from_semantic: bool,
    upgrade_generic_from_sheet: bool,
    backfill_from_revision: bool,
) -> bool:
    return bool(refresh_draft_from_semantic and upgrade_generic_from_sheet and not backfill_from_revision)


def _build_fresh_semantic_sheet_for_draft_rebase(
    order_id: str,
    draft_record: dict[str, Any] | None,
    *,
    evidence_run_override: dict[str, Any] | None = None,
    synchronous_write_input: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    # Structural rebase is not OCR adoption: only the identity-checked merge may
    # supply quantities and remarks from the captured operator draft.
    if synchronous_write_input is None:
        from src.services.workflow_attempt_guard_service import capture_current_sheet_input, bind_current_sheet_input, validate_current_sheet_input
        captured = capture_current_sheet_input(order_id)
        if captured.get("sheet_source_unavailable"):
            raise ValueError(captured["sheet_source_unavailable"])
        with session_scope() as session:
            current = session.get(OrderSheetDraft, (captured.get("draft") or {}).get("id"))
            if current is None or draft_sheet_service._serialize_draft(current) != draft_record:
                raise ValueError("current_sheet_input_changed")
            if evidence_run_override is not None:
                evidence = session.get(OrderOcrEvidenceRun, (captured.get("evidence") or {}).get("id"))
                if evidence is None or ocr_evidence_service._serialize_evidence_run(evidence, include_payload=True) != evidence_run_override:
                    raise ValueError("synchronous_evidence_conflict")
        rebuilt_sheet, error = _build_hakodate_weekly_menu_base_sheet(order_id, processing_read_input=captured)
        if error:
            raise ValueError(error)
        with session_scope() as session:
            validate_current_sheet_input(session, order_id, bind_current_sheet_input(rebuilt_sheet, captured))
        return rebuilt_sheet
    if not _synchronous_draft_input_matches(synchronous_write_input, draft_record):
        raise ValueError("synchronous_input_missing")
    if evidence_run_override is not None and evidence_run_override != synchronous_write_input["evidence"]:
        raise ValueError("synchronous_evidence_conflict")
    rebuilt_sheet, error = _build_hakodate_weekly_menu_base_sheet(
        order_id, synchronous_write_input=synchronous_write_input,
    )
    if error:
        raise ValueError(error)
    return rebuilt_sheet if isinstance(rebuilt_sheet, dict) else None


def _draft_record_requires_current_sheet_semantic_rebase(
    order_id: str,
    draft_record: dict[str, Any] | None,
    *,
    evidence_run_override: dict[str, Any] | None = None,
    synchronous_write_input: dict[str, Any] | None = None,
) -> tuple[bool, dict[str, Any] | None]:
    if not isinstance(draft_record, dict):
        return False, None
    if _draft_record_is_selected_saved_sheet(draft_record):
        return False, None
    if _draft_record_has_forced_repair_mode(draft_record):
        return False, None
    draft_sheet_json = (
        draft_record.get("draft_sheet_json")
        if isinstance(draft_record.get("draft_sheet_json"), dict)
        else draft_record
    )
    if not isinstance(draft_sheet_json, dict):
        return False, None
    if str(draft_sheet_json.get("source") or "").strip() == "hakodate_ocr_evidence_sheet":
        return False, None
    if apply_gate_service.has_clean_saved_draft(draft_record):
        return False, None
    rebuilt_sheet = _build_fresh_semantic_sheet_for_draft_rebase(
        order_id, draft_record, evidence_run_override=evidence_run_override,
        synchronous_write_input=synchronous_write_input,
    )
    if not isinstance(rebuilt_sheet, dict):
        return False, None
    # Read paths must not rewrite blocked review drafts. Those rows are the
    # operator-facing review artifact until an explicit rebuild path replaces them.
    draft_state = str(draft_record.get("draft_state") or "").strip().lower()
    current_blockers = _dedupe_str_tokens(draft_record.get("blockers_json") or [])
    if draft_state == "auto_apply_blocked" or current_blockers:
        return False, rebuilt_sheet
    schema_rebase_required = _draft_requires_authoritative_schema_upgrade(
        draft_sheet_json,
        rebuilt_sheet,
    )
    if schema_rebase_required:
        return True, rebuilt_sheet
    return False, rebuilt_sheet


def _persisted_current_state_is_reusable(
    payload: dict[str, Any] | None,
    *,
    order_id: str,
    refresh_draft_from_semantic: bool,
) -> bool:
    if not isinstance(payload, dict):
        return False
    draft_id = str(payload.get("draft_id") or "").strip()
    if not draft_id:
        return False
    latest_draft = draft_sheet_service.get_selected_sheet_draft(order_id)
    if not _draft_record_is_authoritative_current_sheet(latest_draft):
        return False
    latest_draft_id = str((latest_draft or {}).get("id") or "").strip()
    if not latest_draft_id or latest_draft_id != draft_id:
        return False
    saved_payload = latest_draft.get("draft_sheet_json") or {}
    if any(not snapshots_equal(payload.get(key), saved_payload.get(key)) for key in ("fields", "rows", "row_ids")):
        return False
    latest_draft_template_version_id = str((latest_draft or {}).get("template_version_id") or "").strip() or None
    persisted_template_version_id = str(payload.get("template_version_id") or "").strip() or None
    if latest_draft_template_version_id and latest_draft_template_version_id != persisted_template_version_id:
        return False
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return False
        current_lines_updated_at = order.lines_updated_at
        current_facility_id = str(order.facility_code or "").strip() or None
        current_order_template_version_id = str(order.template_version_id or "").strip() or None
    if current_order_template_version_id and current_order_template_version_id != persisted_template_version_id:
        return False
    persisted_order_payload = payload.get("order_payload")
    persisted_lines_updated_at = _parse_iso_datetime_value(
        (persisted_order_payload or {}).get("lines_updated_at")
    )
    current_lines_updated_at_norm = _normalize_compare_timestamp(
        current_lines_updated_at.isoformat() if isinstance(current_lines_updated_at, datetime) else None
    )
    persisted_lines_updated_at_norm = _normalize_compare_timestamp(
        persisted_lines_updated_at.isoformat()
        if isinstance(persisted_lines_updated_at, datetime)
        else str(persisted_lines_updated_at or "").strip() or None
    )
    if current_lines_updated_at_norm != persisted_lines_updated_at_norm:
        return False
    latest_evidence = _resolve_active_ocr_evidence_run(order_id)
    latest_evidence_run_id = str((latest_evidence or {}).get("id") or "").strip() or None
    persisted_evidence_run_id = str(payload.get("base_evidence_run_id") or payload.get("evidence_run_id") or "").strip() or None
    if latest_evidence_run_id != persisted_evidence_run_id:
        return False
    current_schema = _current_sheet_schema_snapshot_for_facility(
        current_facility_id,
        order_id=order_id,
        draft_template_id=str((latest_draft or {}).get("base_template_resolution_id") or "").strip() or None,
    )
    if isinstance(current_schema, dict):
        persisted_fields = [
            str(field).strip()
            for field in (payload.get("fields") or [])
            if str(field).strip()
        ]
        current_fields = [
            str(field).strip()
            for field in (current_schema.get("fields") or [])
            if str(field).strip()
        ]
        persisted_header = [str(item) for item in (payload.get("header") or [])]
        current_header = [str(item) for item in (current_schema.get("header") or [])]
        if persisted_fields != current_fields or persisted_header != current_header:
            return False
    if refresh_draft_from_semantic:
        rebase_required, _rebuilt_sheet = _draft_record_requires_current_sheet_semantic_rebase(
            order_id,
            latest_draft,
        )
        if rebase_required:
            return False
    return True


def _resolve_current_sheet_context_week_id(
    *,
    order_id: str,
    order_payload: dict[str, Any] | None,
    draft_payload: dict[str, Any] | None,
    facility_id: str | None,
) -> str | None:
    payload = order_payload if isinstance(order_payload, dict) else {}
    for key in ("stored_week_value", "week_code", "week_value", "week"):
        if key in payload:
            return _normalize_sheet_week_value(payload[key])
    return None


def _blocked_current_sheet_context(order_id: str, reason: str) -> dict[str, Any]:
    return {
        "order_id": order_id, "resolved_week_id": None,
        "draft_id": None,
        "current_sheet_revision_id": _current_sheet_revision_id_from_artifact(
            fields=[], header=[], rows_payload=[], row_ids=[],
        ),
        "fields": [], "header": [], "rows": [], "row_ids": [],
        "blockers": [reason], "warnings": [],
        "draft_record": {"blockers_json": [reason]},
        "draft_payload": None, "has_persisted_draft": False,
        "authoritative_persisted_draft": False, "clean_saved_draft": False,
    }


def _unresolved_order_week_context(order_id: str) -> dict[str, Any] | None:
    with session_scope() as session:
        order = session.get(Order, order_id)
        if order is None or _normalize_sheet_week_value(order.week_code):
            return None
    return _blocked_current_sheet_context(order_id, "week_unresolved")


def _current_sheet_template_read_boundary(order_id: str) -> tuple[bool, dict[str, Any] | None]:
    unresolved = _unresolved_order_week_context(order_id)
    if unresolved is not None:
        return True, unresolved
    try:
        _read_order_authored_facility_config(order_id)
    except ValueError as exc:
        reason = str(exc)
        if reason == "order_not_found":
            return True, None
        return True, _blocked_current_sheet_context(order_id, reason)
    return False, None


def _build_current_sheet_context_uncached(
    order_id: str,
    *,
    refresh_draft_from_semantic: bool = True,
    upgrade_generic_from_sheet: bool = True,
    backfill_from_revision: bool = False,
    allow_state_mutation: bool = False,
) -> dict[str, Any] | None:
    normalized_order_id = str(order_id or "").strip()
    if not normalized_order_id:
        return None
    from src.services.workflow_attempt_guard_service import capture_current_sheet_input, bind_current_sheet_input
    publication_input = capture_current_sheet_input(normalized_order_id)
    stopped, blocked_context = _current_sheet_template_read_boundary(normalized_order_id)
    if stopped:
        return _bind_blocked_current_sheet_context(normalized_order_id, blocked_context, publication_input)
    if publication_input.get("sheet_source_unavailable"):
        return _bind_blocked_current_sheet_context(
            normalized_order_id,
            _blocked_current_sheet_context(normalized_order_id, publication_input["sheet_source_unavailable"]),
            publication_input,
        )
    synchronous_write_input = (
        _capture_synchronous_cache_write_input(normalized_order_id) if allow_state_mutation else None
    )
    if allow_state_mutation and synchronous_write_input is None:
        return _bind_blocked_current_sheet_context(normalized_order_id, _unresolved_order_week_context(normalized_order_id), publication_input)
    order_payload = get_order_by_id(normalized_order_id, allow_unresolved_menu_amount=True)
    latest_draft = (
        synchronous_write_input.get("draft") if isinstance(synchronous_write_input, dict)
        else draft_sheet_service.get_selected_sheet_draft(normalized_order_id)
    )
    if not _draft_record_is_authoritative_current_sheet(latest_draft):
        latest_draft = None
    current_record = latest_draft if isinstance(latest_draft, dict) else None
    if isinstance(current_record, dict) and refresh_draft_from_semantic:
        rebase_required, _rebuilt_sheet = _draft_record_requires_current_sheet_semantic_rebase(
            normalized_order_id,
            current_record,
            evidence_run_override=(
                synchronous_write_input["evidence"] if isinstance(synchronous_write_input, dict) else None
            ),
            synchronous_write_input=synchronous_write_input,
        )
        if rebase_required and allow_state_mutation:
            refreshed_record = _rebase_draft_record_to_facility_schema(
                normalized_order_id,
                current_record,
                edited_by="current-sheet-refresh",
                synchronous_write_input=synchronous_write_input,
            )
            if not isinstance(refreshed_record, dict):
                raise ValueError("current_sheet_materialization_rejected")
            identity_blockers = [item for item in (refreshed_record.get("blockers_json") or []) if isinstance(item, str) and item.startswith("saved_draft_row_identity_")]
            if identity_blockers:
                raise ValueError(identity_blockers[0])
            current_record = refreshed_record
    if current_record is None:
        try:
            initial = build_initial_sheet_draft(normalized_order_id)
        except ValueError as exc:
            return _bind_blocked_current_sheet_context(
                normalized_order_id, _blocked_current_sheet_context(normalized_order_id, str(exc)), publication_input,
            )
        if isinstance(initial, dict):
            current_record = _build_transient_draft_record(normalized_order_id, initial)
    if not isinstance(current_record, dict):
        return None

    draft_payload = (
        current_record.get("draft_sheet_json")
        if isinstance(current_record.get("draft_sheet_json"), dict)
        else current_record
    )
    if not isinstance(draft_payload, dict):
        return None

    selected_saved_sheet = _draft_record_is_selected_saved_sheet(current_record)
    if not selected_saved_sheet and upgrade_generic_from_sheet and _draft_fields_look_generic(draft_payload.get("fields")):
        semantic_current = build_initial_sheet_draft(normalized_order_id)
        if isinstance(semantic_current, dict) and not _draft_fields_look_generic(semantic_current.get("fields")):
            draft_payload = dict(semantic_current)

    materialized_record = _materialize_current_sheet_record(
        normalized_order_id,
        draft_record=current_record,
        draft_payload=draft_payload,
    )
    if not isinstance(materialized_record, dict):
        return None

    raw_source = str(
        draft_payload.get("source") or current_record.get("draft_state") or "draft"
    ).strip() or "draft"
    fields = (
        deepcopy(draft_payload.get("fields") or [])
        if selected_saved_sheet
        else [str(field).strip() for field in (draft_payload.get("fields") or []) if str(field).strip()]
    )
    rows = deepcopy(draft_payload.get("rows")) if isinstance(draft_payload.get("rows"), list) else []
    row_ids = deepcopy(draft_payload.get("row_ids")) if isinstance(draft_payload.get("row_ids"), list) else []
    warnings = _dedupe_str_tokens(
        list(draft_payload.get("warnings") or []) + list(current_record.get("warnings_json") or [])
    )
    blockers = _dedupe_str_tokens(current_record.get("blockers_json") or [])
    physical_source_missing = publication_input.get("physical_menu_entries") == []
    if physical_source_missing:
        blockers = _dedupe_str_tokens([*blockers, "current_sheet_source_unavailable"])
    try:
        quantity_field_identities_for_fields(
            publication_input["configured_input"]["facility"]["fax_template"], fields,
        )
    except QuantitySchemaError as exc:
        blockers = _dedupe_str_tokens([*blockers, str(exc)])
    clean_saved_draft = apply_gate_service.has_clean_saved_draft(current_record)
    facility_id = str((order_payload or {}).get("facility") or "").strip() or None
    template_version_id = (
        str(materialized_record.get("template_version_id") or "").strip()
        or str(current_record.get("template_version_id") or "").strip()
        or str((order_payload or {}).get("template_version_id") or "").strip()
        or None
    )
    resolved_week_id = _resolve_current_sheet_context_week_id(
        order_id=normalized_order_id,
        order_payload=order_payload,
        draft_payload=draft_payload,
        facility_id=facility_id,
    )
    if not resolved_week_id:
        raise ValueError("week_unresolved")
    header = list(draft_payload.get("header") or []) if isinstance(draft_payload.get("header"), list) else []
    if len(header) < len(fields) and not selected_saved_sheet:
        header.extend([_field_label(field) for field in fields[len(header) :]])
    has_authoritative_persisted_draft = bool(
        str(materialized_record.get("id") or "").strip()
        and _draft_record_is_authoritative_current_sheet(materialized_record)
    )
    source = raw_source
    if facility_id and fields and not _draft_fields_look_generic(fields) and not clean_saved_draft and not selected_saved_sheet:
        current_schema = _current_sheet_schema_snapshot_for_facility(
            facility_id,
            order_id=normalized_order_id,
            draft_template_id=str(current_record.get("base_template_resolution_id") or "").strip() or None,
        )
        schema_fields = [
            str(field).strip()
            for field in ((current_schema or {}).get("fields") or [])
            if str(field).strip()
        ]
        schema_header = list((current_schema or {}).get("header") or [])
        if schema_fields == fields and schema_header:
            header = schema_header
    menu_diagnostics = (
        dict(draft_payload.get("menu_diagnostics"))
        if isinstance(draft_payload.get("menu_diagnostics"), dict)
        else _build_monthly_menu_diagnostics(
            week_id=resolved_week_id,
            facility_id=facility_id,
        )
    )
    seed_source, enrichment_source = _split_sheet_source(raw_source)
    current_sheet_revision_id = _current_sheet_revision_id_from_artifact(
        draft_id=str(materialized_record.get("id") or "").strip() or None,
        fields=fields,
        header=header,
        rows_payload=rows,
        row_ids=row_ids,
    )
    return bind_current_sheet_input({
        "order_id": normalized_order_id,
        "order_payload": order_payload,
        "draft_record": materialized_record,
        "source_draft_record": current_record,
        "draft_payload": draft_payload,
        **({"sheet_unavailable": True} if physical_source_missing else {}),
        "draft_id": str(materialized_record.get("id") or "").strip() or None,
        "template_version_id": template_version_id,
        "source": source,
        "fields": fields,
        "header": header,
        "rows": rows,
        "row_ids": row_ids,
        "warnings": warnings,
        "blockers": blockers,
        "sheet_projection": (
            dict(draft_payload.get("sheet_projection"))
            if isinstance(draft_payload.get("sheet_projection"), dict)
            else _sheet_projection_status_payload(
                source=source,
                warnings=warnings,
                payload_mapping_block_reason=None,
                payload_rows_present=False,
            )
        ),
        "has_persisted_draft": bool(str(materialized_record.get("id") or "").strip()),
        "authoritative_persisted_draft": has_authoritative_persisted_draft,
        "clean_saved_draft": clean_saved_draft,
        "base_evidence_run_id": str(materialized_record.get("base_evidence_run_id") or "").strip() or None,
        "current_sheet_revision_id": current_sheet_revision_id,
        "resolved_week_id": resolved_week_id,
        "facility_id": facility_id,
        "menu_diagnostics": menu_diagnostics,
        "row_diagnostics": list(draft_payload.get("row_diagnostics") or [])
        if isinstance(draft_payload.get("row_diagnostics"), list)
        else [],
        "repair_mode": _draft_payload_repair_mode(draft_payload),
        "repair_metadata": (
            dict(draft_payload.get("repair_metadata"))
            if isinstance(draft_payload.get("repair_metadata"), dict)
            else {}
        ),
        "seed_source": seed_source,
        "enrichment_source": enrichment_source,
        "has_semantic_fields": bool(fields) and not _draft_fields_look_generic(fields),
    }, publication_input)


def _bind_blocked_current_sheet_context(order_id: str, context: dict[str, Any] | None, captured: dict[str, Any]) -> dict[str, Any] | None:
    if context is None:
        return None
    from src.services.workflow_attempt_guard_service import bind_current_sheet_input, validate_current_sheet_input
    selected = draft_sheet_service.get_selected_sheet_draft(order_id)
    if _draft_record_is_selected_saved_sheet(selected):
        payload = deepcopy(selected["draft_sheet_json"])
        context = dict(context)
        if captured.get("sheet_source_unavailable"):
            context["blockers"] = _dedupe_str_tokens([
                *context.get("blockers", []), captured["sheet_source_unavailable"],
            ])
        context.update({key: deepcopy(payload.get(key, [])) for key in ("fields", "header", "rows", "row_ids")})
        context.update(
            draft_id=selected["id"], draft_record=deepcopy(selected), source_draft_record=deepcopy(selected),
            draft_payload=payload, has_persisted_draft=True, authoritative_persisted_draft=True,
            template_version_id=selected["template_version_id"], base_evidence_run_id=selected["base_evidence_run_id"],
            sheet_unavailable=True, source=payload.get("source"),
            order_payload=get_order_by_id(order_id, allow_unresolved_menu_amount=True),
            facility_id=(captured.get("order") or {}).get("facility_code"),
            resolved_week_id=_normalize_sheet_week_value((captured.get("order") or {}).get("week_code")),
        )
        context["current_sheet_revision_id"] = _current_sheet_revision_id_from_artifact(
            draft_id=selected["id"], fields=context["fields"], header=context["header"],
            rows_payload=context["rows"], row_ids=context["row_ids"],
        )
    bound = bind_current_sheet_input(context, captured)
    with session_scope() as session:
        validate_current_sheet_input(session, order_id, bound)
    return bound


def _initial_saved_sheet_context(order_id, boundary_input):
    from src.services.initial_saved_import_service import sheet_context
    from src.services.workflow_attempt_guard_service import bind_current_sheet_input, validate_current_sheet_input

    context = sheet_context({"snapshot": {key: boundary_input[key] for key in ("order", "draft")}})
    context["order_payload"] = get_order_by_id(order_id, allow_unresolved_menu_amount=True)
    bound = bind_current_sheet_input(context, boundary_input)
    with session_scope() as session:
        validate_current_sheet_input(session, order_id, bound)
    return bound


def refresh_current_sheet_context(
    order_id: str,
    *,
    refresh_draft_from_semantic: bool = True,
    upgrade_generic_from_sheet: bool = True,
    backfill_from_revision: bool = False,
    publish_snapshot: bool = True,
) -> dict[str, Any] | None:
    normalized_order_id = str(order_id or "").strip()
    if not normalized_order_id:
        return None
    from src.services.workflow_attempt_guard_service import capture_current_sheet_input
    boundary_input = capture_current_sheet_input(normalized_order_id)
    if boundary_input.get("initial_saved_import") is not None:
        return _initial_saved_sheet_context(normalized_order_id, boundary_input)
    stopped, blocked_context = _current_sheet_template_read_boundary(normalized_order_id)
    if stopped:
        return _bind_blocked_current_sheet_context(normalized_order_id, blocked_context, boundary_input)
    context = _build_current_sheet_context_uncached(
        normalized_order_id,
        refresh_draft_from_semantic=refresh_draft_from_semantic,
        upgrade_generic_from_sheet=upgrade_generic_from_sheet,
        backfill_from_revision=backfill_from_revision,
        allow_state_mutation=True,
    )
    if (isinstance(context, dict) and context.get("blockers")
            and context.get("resolved_week_id") is None and context.get("draft_payload") is None):
        return context
    if publish_snapshot and _current_sheet_context_uses_canonical_snapshot(
        refresh_draft_from_semantic=refresh_draft_from_semantic,
        upgrade_generic_from_sheet=upgrade_generic_from_sheet,
        backfill_from_revision=backfill_from_revision,
    ):
        if isinstance(context, dict):
            persisted = order_current_state_service.persist_current_state(
                order_id=normalized_order_id,
                state_json=context,
                draft_id=str(context.get("draft_id") or "").strip() or None,
                evidence_run_id=str(context.get("base_evidence_run_id") or "").strip() or None,
                template_version_id=str(context.get("template_version_id") or "").strip() or None,
            )
            if persisted is None:
                raise ValueError("current_sheet_publication_rejected")
        else:
            from src.services.workflow_attempt_guard_service import bind_current_sheet_input
            order_current_state_service.delete_current_state(
                normalized_order_id,
                source_context=bind_current_sheet_input({"order_id": normalized_order_id, "sheet_unavailable": True}, boundary_input),
            )
    if isinstance(context, dict):
        from src.services.workflow_attempt_guard_service import validate_current_sheet_input
        with session_scope() as session:
            validate_current_sheet_input(session, normalized_order_id, context)
    else:
        from src.services.workflow_attempt_guard_service import bind_current_sheet_input, validate_current_sheet_input
        with session_scope() as session:
            validate_current_sheet_input(session, normalized_order_id, bind_current_sheet_input(
                {"order_id": normalized_order_id, "sheet_unavailable": True}, boundary_input,
            ))
    return context


def get_current_sheet_context(
    order_id: str,
    *,
    refresh_draft_from_semantic: bool = True,
    upgrade_generic_from_sheet: bool = True,
    backfill_from_revision: bool = False,
) -> dict[str, Any] | None:
    normalized_order_id = str(order_id or "").strip()
    if not normalized_order_id:
        return None
    from src.services.workflow_attempt_guard_service import capture_current_sheet_input
    boundary_input = capture_current_sheet_input(normalized_order_id)
    if boundary_input.get("initial_saved_import") is not None:
        return _initial_saved_sheet_context(normalized_order_id, boundary_input)
    stopped, blocked_context = _current_sheet_template_read_boundary(normalized_order_id)
    if stopped:
        return _bind_blocked_current_sheet_context(normalized_order_id, blocked_context, boundary_input)
    if _current_sheet_context_uses_canonical_snapshot(
        refresh_draft_from_semantic=refresh_draft_from_semantic,
        upgrade_generic_from_sheet=upgrade_generic_from_sheet,
        backfill_from_revision=backfill_from_revision,
    ):
        persisted_payload = order_current_state_service.get_current_state_payload(normalized_order_id)
        if _persisted_current_state_is_reusable(
            persisted_payload,
            order_id=normalized_order_id,
            refresh_draft_from_semantic=refresh_draft_from_semantic,
        ):
            from src.services.workflow_attempt_guard_service import validate_current_sheet_input
            with session_scope() as session:
                validate_current_sheet_input(session, normalized_order_id, persisted_payload)
            return persisted_payload
    context = _build_current_sheet_context_uncached(
        normalized_order_id,
        refresh_draft_from_semantic=refresh_draft_from_semantic,
        upgrade_generic_from_sheet=upgrade_generic_from_sheet,
        backfill_from_revision=backfill_from_revision,
        allow_state_mutation=False,
    )
    from src.services.workflow_attempt_guard_service import bind_current_sheet_input, validate_current_sheet_input
    with session_scope() as session:
        validate_current_sheet_input(session, normalized_order_id, context if isinstance(context, dict) else bind_current_sheet_input(
            {"order_id": normalized_order_id, "sheet_unavailable": True}, boundary_input,
        ))
    return context


def _list_latest_completed_ocr_outputs(
    order_id: str,
    *,
    not_before: datetime | None = None,
    limit: int = 5,
) -> list[tuple[str, dict[str, Any]]]:
    raise LegacyOcrEvidenceFallbackDisabledError(
        "legacy OCR output discovery is disabled; use the owned output reference"
    )






@contextmanager
def _ocr_result_transaction():
    boundary = current_nonworkflow_execution()
    before = deepcopy(boundary)
    try:
        with session_scope() as session:
            yield session
    except BaseException:
        if boundary is not None:
            boundary.clear()
            boundary.update(before)
        raise


def _complete_ocr_rerun_in_session(session, order_id, job_id, evidence, *, error, metrics_patch, failure_metrics_override=False):
    if is_selected_pdf_failure(error) and evidence is not None:
        raise ValueError("selected_pdf_failure_cannot_adopt_evidence")
    if not _workflow_attempt_write_fence(session, job_id, order_id, source_failure=error):
        raise ValueError("reparse_attempt_superseded")
    job = session.get(OcrJob, job_id)
    if job is None:
        raise ValueError("ocr_job_not_found")
    if (job.metrics or {}).get("rerun_terminal_receipt") is not None:
        raise ValueError("ocr_rerun_already_terminal")
    evidence_id = evidence.get("id") if isinstance(evidence, dict) else None
    if not error and not evidence_id:
        raise ValueError("reparse_evidence_missing")
    execution = current_nonworkflow_execution()
    attempt = _workflow_ocr_attempt_id.get()
    revision = _workflow_ocr_revision.get()
    if attempt is not None:
        from src.services import order_workflow_v2_service
        completed, completion_error = order_workflow_v2_service.mark_ocr_run_completed(
            order_id, job_id=job_id, evidence_run_id=evidence_id, error=error,
            workflow_attempt_id=attempt, expected_revision=revision, write_session=session,
        )
        if completed is None or completion_error in {
            order_workflow_v2_service.WORKFLOW_REVISION_REQUIRED,
            order_workflow_v2_service.WORKFLOW_REVISION_CONFLICT,
        }:
            raise ValueError(completion_error or "workflow_completion_failed")
        if job.status not in {"done", "failed"}:
            raise ValueError(completion_error or "workflow_completion_failed")
        error = job.error_message if job.status == "failed" else None
    else:
        if not isinstance(execution, dict) or execution.get("job_id") != job_id:
            raise ValueError("ocr_execution_input_required")
        job.status = "failed" if error else "done"
        job.error_message = error
    job.updated_at = datetime.utcnow()
    metrics_patch = {
        key: value for key, value in metrics_patch.items()
        if not key.startswith(("workflow_", "nonworkflow_")) and key != "rerun_terminal_receipt"
    }
    metrics_patch["ocr_finished_at"] = job.updated_at.isoformat()
    started = _parse_iso_datetime_value((job.metrics or {}).get("ocr_started_at"))
    if started is not None:
        if started.tzinfo is not None:
            started = started.astimezone(timezone.utc).replace(tzinfo=None)
        metrics_patch["ocr_elapsed_seconds"] = round((job.updated_at - started).total_seconds(), 3)
    receipt = {
        "job_id": job_id, "order_id": order_id,
        "execution_id": execution.get("execution_id") if execution is not None else None,
        "workflow_attempt_id": attempt, "workflow_revision": revision,
        "evidence_run_id": evidence_id, "status": job.status, "error": error,
    }
    job.metrics = {
        **merge_own_job_metrics_patch(job.metrics, metrics_patch, own_outcome=True),
        "evidence_run_id": evidence_id, "adopted": False,
        "status": job.status, "error": error,
        "processing_stage": "rejected_review_saved" if error and not failure_metrics_override else metrics_patch.get("processing_stage", "evidence_ready"),
        "result_state": "review_required" if error and not failure_metrics_override else metrics_patch.get("result_state", "evidence_ready"),
        "rerun_terminal_receipt": deepcopy(receipt),
    }
    session.flush()
    return receipt


def _persist_ocr_rerun_completion(
    order_id, job_id, own_payload, *, error=None, metrics_patch=None,
    project_sheet=False, output_reference=None, source="ocr-rerun-reconcile",
    schema_version="v2_evidence_rerun", producer_version="ocr_pipeline_rerun_reconcile",
):
    if is_selected_pdf_failure(error):
        own_payload = None
    with _ocr_result_transaction() as session:
        if not _workflow_attempt_write_fence(session, job_id, order_id, source_failure=error):
            raise ValueError("reparse_attempt_superseded")
        job = session.get(OcrJob, job_id)
        if job is None or job.status in {"done", "completed", "success"} or (job.metrics or {}).get("rerun_terminal_receipt"):
            raise ValueError("ocr_rerun_already_terminal")
        evidence = None
        if isinstance(own_payload, dict):
            evidence = persist_ocr_evidence_run(
                order_id, own_payload, schema_version=schema_version,
                producer_version=producer_version,
                status="diagnostic_only" if error else str(own_payload.get("status") or "ready"),
                source=source, workflow_job_id=job_id, refresh_workflow=False,
                result_disposition="rejected" if error else "pipeline_result",
                write_session=session,
            )
            if not isinstance(evidence, dict) or not evidence.get("id"):
                raise ValueError("evidence_persist_failed")
        if not error:
            if evidence is None:
                raise ValueError("reparse_pipeline_result_missing")
            cache_result = _save_order_ocr_cache(
                order_id, {**own_payload, "_ocr_execution": deepcopy(evidence["payload_json"]["_ocr_execution"])},
                job_id=job_id, augment_hakodate_artifacts=False,
                preserve_existing_artifacts=False,
                persist_evidence=False, refresh_workflow=False, write_session=session,
            )
            if cache_result is None:
                raise ValueError("reparse_cache_persist_failed")
            if project_sheet:
                captured = _captured_reparse_read_input(order_id, write_session=session)
                if captured is None:
                    raise ValueError("reparse_start_input_missing")
                projected_bundle, projected_error = build_order_hakodate_projected_sheet(
                    order_id, strategy="hakodate", evidence_run_override=evidence,
                )
                sheet = projected_bundle.get("projected_sheet") if isinstance(projected_bundle, dict) else None
                if projected_error or not isinstance(sheet, dict):
                    raise ValueError(projected_error or "hakodate_projected_sheet_unavailable")
                blockers = [str(item).strip() for item in sheet.get("blockers", []) if str(item).strip()]
                current_draft = captured.get("draft")
                draft = _persist_sheet_draft_with_base_evidence(
                    order_id=order_id, draft_sheet_json=sheet,
                    draft_state="draft_blocked" if blockers else "draft_ready",
                    blockers=blockers, warnings=sheet.get("warnings"),
                    latest_patch_candidate_id=(current_draft or {}).get("latest_patch_candidate_id"),
                    edited_by="rerun-ocr-evidence-hakodate", evidence_run_override=evidence,
                    workflow_job_id=job_id, write_session=session,
                )
                if not isinstance(draft, dict) or draft.get("base_evidence_run_id") != evidence["id"]:
                    raise ValueError("own_draft_evidence_lineage_mismatch")
                metrics_patch = {
                    **(metrics_patch or {}), "projected_sheet_blockers": blockers,
                    "new_evidence_available": False,
                    "processing_stage": "draft_blocked" if blockers else "evidence_ready",
                    "result_state": "draft_blocked" if blockers else "evidence_ready",
                }
        if output_reference is not None:
            job.output_reference = output_reference
        if isinstance(own_payload, dict):
            job.template_id = own_payload.get("template_id")
        receipt = _complete_ocr_rerun_in_session(
            session, order_id, job_id, evidence, error=error,
            metrics_patch=metrics_patch or {},
        )
        result = deepcopy(evidence) if evidence is not None else {}
        result["terminal_receipt"] = receipt
    return result, receipt["error"]


def _reconcile_finished_ocr_rerun(order_id: str) -> bool:
    execution = current_nonworkflow_execution()
    if execution is None or execution.get("order_id") != order_id:
        return False
    job_id = execution.get("job_id")
    job = get_ocr_job(job_id)
    if not isinstance(job, dict) or job.get("order_id") != order_id or get_job_request_mode(job) != "ocr_rerun":
        return False
    metrics = job.get("metrics") or {}
    if metrics.get("workflow_attempt_id") is not None:
        return False
    receipt = metrics.get("rerun_terminal_receipt")
    if isinstance(receipt, dict):
        with session_scope() as session:
            if not _workflow_attempt_write_fence(session, job_id, order_id):
                return False
            current_job = session.get(OcrJob, job_id)
            return (
                receipt.get("job_id") == job_id
                and receipt.get("execution_id") == execution.get("execution_id")
                and current_job is not None and current_job.status == receipt.get("status")
                and (current_job.metrics or {}).get("rerun_terminal_receipt") == receipt
            )
    if job.get("status") in {"done", "completed", "success"}:
        return False
    output_ref = job.get("output_reference")
    payload = _load_pipeline_output_once(output_ref)
    if isinstance(payload, dict) and _output_is_pending(payload):
        return False
    state = _classify_owned_evidence_payload(payload) if isinstance(payload, dict) else {}
    error = None if state.get("persistable") else str(state.get("error") or "reparse_pipeline_result_missing")
    result, _error = _persist_ocr_rerun_completion(
        order_id, job_id, payload, error=error, output_reference=output_ref,
        metrics_patch={"request_mode": "ocr_rerun", "new_evidence_available": not bool(error)},
    )
    receipt = result.get("terminal_receipt")
    return (
        isinstance(receipt, dict) and receipt.get("job_id") == job_id
        and receipt.get("order_id") == order_id
        and receipt.get("execution_id") == execution.get("execution_id")
        and receipt.get("evidence_run_id") == result.get("id")
        and receipt.get("status") in {"done", "failed"}
    )


def reconcile_ocr_rerun_state(order_id: str) -> bool:
    return _reconcile_finished_ocr_rerun(order_id)


def _extract_reparse_request_kwargs_from_job(job: dict[str, Any] | None) -> dict[str, Any]:
    metrics = job.get("metrics") if isinstance(job, dict) else None
    metrics = metrics if isinstance(metrics, dict) else {}
    if not all(key in metrics for key in REPARSE_REQUEST_FIELDS.values()):
        raise ValueError("reparse_original_request_missing")
    return {name: deepcopy(metrics[key]) for name, key in REPARSE_REQUEST_FIELDS.items()}


def _pending_request_matches(metrics, receipt):
    try:
        return _extract_reparse_request_kwargs_from_job({"metrics": metrics}) == receipt.get("request_kwargs")
    except ValueError:
        return False


def _reconcile_finished_llm_reparse(
    order_id: str, *, job: dict[str, Any], output_ref: str, payload: dict[str, Any],
) -> bool:
    execution = current_nonworkflow_execution()
    job_id = job.get("id")
    if (
        execution is None or execution.get("job_id") != job_id
        or execution.get("order_id") != order_id
        or (job.get("metrics") or {}).get("workflow_attempt_id") is not None
    ):
        return False
    if not _payload_has_first_pass_ocr_content(payload):
        result, _error = _persist_ocr_rerun_completion(
            order_id, job_id, payload, error="first_pass_ocr_missing",
            output_reference=output_ref, metrics_patch={"request_mode": "llm_reparse"},
        )
    else:
        pending_receipt = (job.get("metrics") or {}).get("pending_receipt")
        try:
            request_kwargs = _extract_reparse_request_kwargs_from_job(job)
        except ValueError:
            return False
        if pending_receipt is not None:
            if (
                not is_own_pending_ocr_result(
                    {"outcome": "pending", "status": job.get("status"), "output_reference": output_ref, "pending_receipt": pending_receipt},
                    order_id=order_id, job_id=job_id, execution_id=execution.get("execution_id"),
                )
                or not isinstance(pending_receipt.get("request_kwargs"), dict)
                or set(pending_receipt["request_kwargs"]) != {"ocr_prompt", "prompt_preset", "ocr_provider", "ocr_model", "llm_assist"}
            ):
                return False
            with session_scope() as session:
                if not _workflow_attempt_write_fence(session, job_id, order_id):
                    return False
                current_job = session.get(OcrJob, job_id)
                if (
                    current_job is None
                    or (current_job.metrics or {}).get("pending_receipt") != pending_receipt
                    or not own_pipeline_delivery_matches(current_job, pending_receipt.get("input_reference"), output_ref)
                    or not _pending_request_matches(current_job.metrics, pending_receipt)
                ):
                    return False
            request_kwargs = deepcopy(pending_receipt["request_kwargs"])
        updated = update_job(
            job_id, status="recovering", output_reference=output_ref,
            metrics={"processing_stage": "ocr_pipeline", "result_state": "recovering"},
        )
        if updated is None:
            return False
        try:
            result, error = reparse_order(
                order_id, **request_kwargs,
                resume_first_pass_payload=payload, resume_first_pass_output_reference=output_ref,
                selected_document_id=(pending_receipt or {}).get("selected_document_id"),
                ocr_job_id=job_id, workflow_attempt_id=None, expected_workflow_revision=None,
            )
            if error is None and is_own_pending_ocr_result(
                result, order_id=order_id, job_id=job_id,
                execution_id=execution.get("execution_id"),
            ):
                return False
            if not isinstance((result or {}).get("terminal_receipt"), dict):
                if not error:
                    raise ValueError("llm_reparse_terminal_receipt_missing")
                result, _error = _persist_ocr_rerun_completion(
                    order_id, job_id, payload, error=error, output_reference=output_ref,
                    metrics_patch={"request_mode": "llm_reparse"},
                )
        except Exception as exc:
            result, _error = _persist_ocr_rerun_completion(
                order_id, job_id, payload, error=f"llm_reparse_resume_failed:{exc}",
                output_reference=output_ref, metrics_patch={"request_mode": "llm_reparse"},
            )
    receipt = (result or {}).get("terminal_receipt")
    own_evidence_id = (result or {}).get("reparse_evidence_run_id") or (result or {}).get("id")
    return (
        isinstance(receipt, dict) and receipt.get("job_id") == job_id
        and receipt.get("execution_id") == execution.get("execution_id")
        and receipt.get("evidence_run_id") == own_evidence_id
        and receipt.get("status") in {"done", "failed"}
    )


def reconcile_pending_workflow_reparse(job, pending_receipt):
    try:
        return _reconcile_pending_workflow_reparse_with_input(job, pending_receipt)
    except ValueError as exc:
        if not is_selected_pdf_failure(exc) or not isinstance(pending_receipt, dict):
            raise
        order_id, job_id = pending_receipt.get("order_id"), pending_receipt.get("job_id")
        with workflow_ocr_write_context(pending_receipt.get("workflow_attempt_id"), pending_receipt.get("workflow_revision"), job_id, order_id):
            try:
                result, _error = _persist_ocr_rerun_completion(order_id, job_id, None, error=str(exc))
            except ValueError:
                return False
        return isinstance((result or {}).get("terminal_receipt"), dict)


def _reconcile_pending_workflow_reparse_with_input(job, pending_receipt):
    """Resume only the immutable waiting receipt, never current queue tokens."""
    if not isinstance(job, dict) or not isinstance(pending_receipt, dict):
        return False
    order_id, job_id = pending_receipt.get("order_id"), pending_receipt.get("job_id")
    attempt, revision = pending_receipt.get("workflow_attempt_id"), pending_receipt.get("workflow_revision")
    output_ref = pending_receipt.get("output_reference")
    if (
        not order_id or job.get("id") != job_id or job.get("order_id") != order_id
        or not attempt or type(revision) is not int or not output_ref
        or get_job_request_mode(job) not in {"ocr_reparse", "llm_reparse"}
        or not isinstance(pending_receipt.get("request_kwargs"), dict)
        or set(pending_receipt["request_kwargs"]) != {"ocr_prompt", "prompt_preset", "ocr_provider", "ocr_model", "llm_assist"}
    ):
        return False
    with workflow_ocr_write_context(attempt, revision, job_id, order_id):
        with session_scope() as session:
            if not _workflow_attempt_write_fence(session, job_id, order_id):
                return False
            current_job = session.get(OcrJob, job_id)
            if (
                current_job is None or current_job.status != "awaiting_output"
                or (current_job.metrics or {}).get("pending_receipt") != pending_receipt
                or current_job.output_reference != output_ref
                or current_job.input_reference != pending_receipt.get("selected_input_reference")
                or not own_pipeline_delivery_matches(current_job, pending_receipt.get("input_reference"), output_ref)
                or not _pending_request_matches(current_job.metrics, pending_receipt)
            ):
                return False
        try:
            payload = _load_pipeline_output_with_retry(output_ref, wait_seconds_override=0)
        except OwnPipelineLineageError as exc:
            result, _error = _persist_ocr_rerun_completion(order_id, job_id, None, error=str(exc))
            return isinstance(result.get("terminal_receipt"), dict)
        if payload is None or _output_is_pending(payload):
            return False
        try:
            result, error = reparse_order(
                order_id, **deepcopy(pending_receipt["request_kwargs"]),
                resume_first_pass_payload=payload, resume_first_pass_output_reference=output_ref,
                selected_document_id=pending_receipt.get("selected_document_id"),
                ocr_job_id=job_id, workflow_attempt_id=attempt, expected_workflow_revision=revision,
            )
            if error is None and is_own_pending_ocr_result(
                result, order_id=order_id, job_id=job_id,
                workflow_attempt_id=attempt, workflow_revision=revision,
            ):
                return False
            if not isinstance((result or {}).get("terminal_receipt"), dict):
                result, error = _persist_ocr_rerun_completion(
                    order_id, job_id, payload,
                    error=error or "llm_reparse_terminal_receipt_missing",
                    output_reference=output_ref,
                )
        except Exception as exc:
            result, error = _persist_ocr_rerun_completion(
                order_id, job_id, payload, error=f"llm_reparse_resume_failed:{exc}",
                output_reference=output_ref,
            )
        receipt = (result or {}).get("terminal_receipt")
        return (
            isinstance(receipt, dict) and receipt.get("job_id") == job_id
            and receipt.get("order_id") == order_id
            and receipt.get("workflow_attempt_id") == attempt
            and receipt.get("workflow_revision") == revision
            and receipt.get("evidence_run_id") == ((result or {}).get("reparse_evidence_run_id") or (result or {}).get("id"))
            and receipt.get("status") in {"done", "failed"}
        )


def _resolve_message_id_for_ocr_job(job_id: str, *, order_id: str | None = None) -> str | None:
    execution_input = current_nonworkflow_execution()
    if execution_input is None or execution_input.get("job_id") != job_id or execution_input.get("order_id") != order_id:
        return None
    captured_order = execution_input.get("orders", {}).get(order_id, {}).get("order")
    return str(captured_order.get("message_id") or "").strip() or None if isinstance(captured_order, dict) else None


def _finalize_async_first_pass_side_effects(
    *,
    job_id: str,
    order_id: str | None,
    message_id: str | None,
) -> None:
    normalized_message_id = str(message_id or "").strip()
    if normalized_message_id:
        try:
            from src.services import ingest_job_service
            execution = current_nonworkflow_execution()
            settled = ingest_job_service.settle_ingest_ocr_terminal(execution) if isinstance(execution, dict) and execution.get("job_id") == job_id and execution.get("order_id") == order_id and (execution.get("ingest_lease") or {}).get("id") == normalized_message_id else None
        except Exception as exc:  # noqa: BLE001
            logger.warning(
                "Ingest job completion sync failed after OCR reconcile",
                job_id=job_id,
                message_id=normalized_message_id,
                error=str(exc),
            )
            settled = None
        try:
            from src.services.uploaded_pdf_service import mark_uploaded_pdf_completed_by_message_id_if_ready, schedule_uploaded_pdf_retry
            uploaded = settled["lease"].get("uploaded_lease") if settled is not None else None
            if uploaded is not None and settled["status"] == "done":
                mark_uploaded_pdf_completed_by_message_id_if_ready(normalized_message_id, lease=uploaded, completion=settled)
            elif uploaded is not None and settled["status"] == "failed":
                schedule_uploaded_pdf_retry(uploaded["id"], lease=uploaded, worker_instance=uploaded["lease_owner"],
                    error_code="ingest_failed", error_message=settled["error"], terminal=True)
        except Exception as exc:  # noqa: BLE001
            logger.warning(
                "Uploaded PDF completion sync failed after OCR reconcile",
                job_id=job_id,
                message_id=normalized_message_id,
                error=str(exc),
            )
    if order_id:
        try:
            workflow_state_service.refresh_workflow_state(order_id)
        except Exception as exc:  # noqa: BLE001
            logger.warning("Workflow state refresh failed after OCR job reconciliation", order_id=order_id, error=str(exc))


def finalize_first_pass_side_effects(
    *,
    job_id: str,
    order_id: str | None,
    message_id: str | None,
) -> None:
    _finalize_async_first_pass_side_effects(
        job_id=job_id,
        order_id=order_id,
        message_id=message_id,
    )


def reconcile_completed_ocr_job(job_id: str, *, execution_input: dict[str, Any] | None = None) -> bool:
    if not isinstance(execution_input, dict) or execution_input.get("job_id") != job_id:
        return False
    with nonworkflow_execution_context(execution_input):
        try:
            return _reconcile_completed_ocr_job_with_input(job_id)
        except ValueError as exc:
            if not is_selected_pdf_failure(exc):
                raise
            from src.services.ocr_job_service import complete_own_selected_pdf_failure
            return complete_own_selected_pdf_failure(job_id, str(exc)) is not None


def _reconcile_completed_ocr_job_with_input(job_id: str) -> bool:
    normalized_job_id = str(job_id or "").strip()
    if not normalized_job_id:
        return False
    job = get_ocr_job(normalized_job_id)
    if not isinstance(job, dict):
        return False
    output_ref = str(job.get("output_reference") or "").strip()
    if not output_ref:
        return False
    metrics = job.get("metrics")
    metrics = metrics if isinstance(metrics, dict) else {}
    request_mode = get_job_request_mode(job)
    execution_input = current_nonworkflow_execution()
    order_id = execution_input.get("order_id") if execution_input is not None else None
    if not order_id or job.get("order_id") != order_id:
        return False
    if request_mode == "ocr_reparse":
        waiting = metrics.get("pending_receipt")
        if not is_own_pending_ocr_result(
            {"outcome": "pending", "status": job.get("status"), "output_reference": output_ref, "pending_receipt": waiting},
            order_id=order_id, job_id=normalized_job_id, execution_id=execution_input.get("execution_id"),
        ):
            return False
    message_id = _resolve_message_id_for_ocr_job(normalized_job_id, order_id=order_id)
    payload = _load_pipeline_output_with_retry(output_ref, wait_seconds_override=0)
    if not isinstance(payload, dict) or _output_is_pending(payload):
        return False
    if request_mode in {"llm_reparse", "ocr_reparse"} and order_id:
        return _reconcile_finished_llm_reparse(
            order_id,
            job=job,
            output_ref=output_ref,
            payload=payload,
        )
    if request_mode == "ocr_rerun" and order_id:
        return _reconcile_finished_ocr_rerun(order_id)
    receipt = metrics.get("first_pass_terminal_receipt")
    if isinstance(receipt, dict):
        with session_scope() as session:
            if not _workflow_attempt_write_fence(session, normalized_job_id, order_id):
                return False
            current_job = session.get(OcrJob, normalized_job_id)
            return (
                receipt.get("job_id") == normalized_job_id
                and receipt.get("execution_id") == execution_input.get("execution_id")
                and current_job is not None
                and (current_job.metrics or {}).get("first_pass_terminal_receipt") == receipt
                and current_job.status == receipt.get("status")
            )
    application = execution_input.get("first_pass_application")
    if isinstance(application, dict):
        application_payload = parse_ingest_payload(application["payload"])
        attempts = application["ocr_attempts"]
    else:
        captured = execution_input["orders"].get(order_id)
        document = captured.get("document") if isinstance(captured, dict) else None
        if not isinstance(document, dict):
            return False
        application_payload = IngestEmailPayload(
            message_id=document["source_email_id"], pdf_uri=document["storage_uri"],
            received_at=datetime.fromisoformat(document["received_at"]),
            order_id=order_id, order_document_id=document["id"],
            facility_hint=captured["order"].get("facility_code"),
            week_hint=captured["order"].get("week_code"),
            facility_selection=(execution_input.get("ingest_lease") or {}).get("payload", {}).get("facility_selection"),
        )
        attempts = 0
    if application_payload.order_id != order_id:
        raise ValueError("first_pass_registered_input_changed")
    payload_state = _classify_owned_evidence_payload(payload)
    lines = None
    mapping_input = application.get("mapping_input") if isinstance(application, dict) else None
    mapping_error = None if isinstance(mapping_input, dict) else "first_pass_mapping_input_missing"
    if payload_state.get("persistable") and mapping_error is None:
        from src.services.ocr_job_service import own_pipeline_delivery_for_output
        from src.workers.ingest_worker import map_own_ingest_result

        delivery = own_pipeline_delivery_for_output(output_ref)
        from src.services.storage_service import load_selected_pdf_bytes

        start_pdf = processing_start_pdf_receipt()
        pdf_bytes = load_selected_pdf_bytes(start_pdf["storage_uri"], start_pdf)
        try:
            mapped = map_own_ingest_result(application_payload, pdf_bytes, payload, mapping_input)
            lines = mapped["lines"]
            payload = mapped["recognizer_result"]
            if lines is None:
                mapping_error = payload.get("error")
        except OCRPipelineOutputPendingError:
            raise
        except OwnPipelineLineageError:
            raise
        except Exception as exc:
            mapping_error = f"first_pass_mapping_failed:{exc}"
    if not payload_state.get("persistable"):
        lines = None
    applied = create_order_from_ingest(
        application_payload, lines=lines, ocr_attempts=attempts,
        document_status="success" if lines is not None else "error",
        error_message=None if lines is not None else mapping_error or "first_pass_result_not_applied",
        execution_input=execution_input, pipeline_result=payload,
        save_result_cache=True,
        mapping_policy=mapping_input["policy"] if isinstance(mapping_input, dict) else None,
    )
    receipt = applied.get("first_pass_terminal_receipt")
    evidence = applied.get("first_pass_evidence")
    if (
        not isinstance(receipt, dict) or not isinstance(evidence, dict)
        or receipt.get("job_id") != normalized_job_id
        or receipt.get("execution_id") != execution_input["execution_id"]
        or receipt.get("evidence_run_id") != evidence.get("id")
    ):
        raise ValueError("first_pass_terminal_receipt_missing")
    _finalize_async_first_pass_side_effects(
        job_id=normalized_job_id, order_id=order_id, message_id=message_id,
    )
    return True


def rerun_ocr_evidence_only(
    order_id: str,
    *,
    job_id: str | None = None,
    project_sheet: bool = True,
    refresh_workflow: bool = True,
    selected_document_id: str | None = None,
) -> tuple[Optional[dict], Optional[str]]:
    execution_input = current_nonworkflow_execution()
    if _workflow_ocr_attempt_id.get() is None and execution_input is None:
        if not job_id:
            return None, "workflow_job_required"
        try:
            execution_input = _capture_nonworkflow_order_execution(job_id, order_id, selected_document_id)
        except ValueError as exc:
            return None, str(exc)
    with nonworkflow_execution_context(execution_input):
        result, error = _rerun_ocr_evidence_only_with_input(
            order_id, job_id=job_id, project_sheet=project_sheet,
            refresh_workflow=refresh_workflow, selected_document_id=selected_document_id,
        )
        if error is None and is_own_pending_ocr_result(
            result, order_id=order_id, job_id=job_id,
            workflow_attempt_id=_workflow_ocr_attempt_id.get(), workflow_revision=_workflow_ocr_revision.get(),
            execution_id=(execution_input or {}).get("execution_id"),
        ):
            return result, None
        if isinstance(result, dict) and isinstance(result.get("terminal_receipt"), dict):
            return result, error
        if error:
            return _persist_ocr_rerun_completion(order_id, job_id, None, error=error)
        raise ValueError("ocr_rerun_terminal_receipt_missing")


def _rerun_ocr_evidence_only_with_input(
    order_id: str, *, job_id: str | None, project_sheet: bool,
    refresh_workflow: bool, selected_document_id: str | None,
) -> tuple[Optional[dict], Optional[str]]:
    normalized_order_id = str(order_id or "").strip()
    if not normalized_order_id:
        return None, "order_not_found"
    ocr_job_id = str(job_id or "").strip()
    if not ocr_job_id:
        return None, "workflow_job_required"
    with session_scope() as session:
        order_row = session.get(Order, normalized_order_id)
        if not isinstance(order_row, Order):
            return None, "order_not_found"
        document_uri, selected_document_metadata = _captured_order_document_selection(
            session,
            order_row,
            selected_document_id,
        )
        if selected_document_metadata.get("error"):
            return None, str(selected_document_metadata["error"])
        order = serialize_order(order_row, allow_unresolved_menu_amount=True)
    if not isinstance(order, dict):
        return None, "order_not_found"
    facility_id = str(order.get("facility") or "").strip() or None
    if not facility_id:
        return None, "facility_missing"
    document_uri = str(document_uri or "").strip()
    if not document_uri:
        return None, "document_not_found"

    workflow_template_version_id = str(order.get("template_version_id") or "").strip() or None
    with session_scope() as session:
        if not _workflow_attempt_write_fence(session, ocr_job_id, normalized_order_id):
            return None, "workflow_attempt_superseded"
    if _workflow_ocr_attempt_id.get() is None:
        update_job(
            ocr_job_id,
            status="running",
            input_reference=document_uri,
            error_message=None,
            order_id=normalized_order_id,
            template_version_id=workflow_template_version_id,
        )

    try:
        from src.services.storage_service import load_selected_pdf_bytes

        pdf_bytes = load_selected_pdf_bytes(document_uri)
    except Exception as exc:  # noqa: BLE001
        if is_selected_pdf_failure(exc):
            return _persist_ocr_rerun_completion(
                normalized_order_id, ocr_job_id, None, error=str(exc),
                metrics_patch={"processing_stage": "document_load", "result_state": "hard_failed"},
            )
        _update_reparse_job_progress(
            ocr_job_id,
            status="failed",
            processing_stage="document_load",
            result_state="hard_failed",
            error_message=f"document_load_failed:{exc}",
            metrics_patch={
                "error": "document_load_failed",
                "request_mode": "ocr_rerun",
                "confirmed_lines_retained": bool(order.get("lines_updated_at")),
            },
        )
        return None, "document_load_failed"

    facility_config = None
    try:
        facility_config = config_service.get_authored_facility_config(facility_id)
    except ValueError as exc:
        return None, str(exc)
    preferred_template_id, preferred_template_ids = _resolve_preferred_template_ids(facility_config)
    base_metrics_patch = {
        "request_mode": "ocr_rerun",
        "confirmed_lines_retained": bool(order.get("lines_updated_at")),
        **selected_document_metadata,
    }
    pipeline_metrics_patch = {
        **base_metrics_patch,
        "order_id": normalized_order_id,
        "facility_id": facility_id,
        "preferred_template_id": preferred_template_id,
        "preferred_template_ids": preferred_template_ids,
    }
    _update_reparse_job_progress(
        ocr_job_id,
        status="running",
        processing_stage="ocr_pipeline",
        result_state="processing",
        error_message=None,
        metrics_patch=base_metrics_patch,
    )

    def _hakodate_rerun_failure_payload(exc: Exception) -> dict[str, Any]:
        from src.services.hakodate_fixed_quad_registration_service import QuadEstimationError
        from src.hakodate_best_method_runtime.render_best_method_overlay_all_facilities import HakodateRecognizerCheckpointError
        from src.services.ocr_row_recovery_service import failure_details

        raw_message = str(exc).strip()
        if isinstance(exc, HakodateRecognizerCheckpointError):
            return {
                "error": "hakodate_recognizer_failed_after_checkpoint",
                "error_detail": str(exc.__cause__) if exc.__cause__ is not None else raw_message,
                "processing_stage": "recognition",
                "recognition_checkpoint": deepcopy(exc.checkpoint_reference),
                "recovery_action": "review_recognition_cells",
                "error_user_message": "文字認識で停止しました。保存したセル画像から確認・訂正できます。",
            }
        geometry_failure = failure_details(raw_message)
        if geometry_failure is not None:
            return geometry_failure
        if isinstance(exc, QuadEstimationError):
            return {
                "error": "quad_estimation_failed",
                "error_detail": raw_message,
                "error_user_message": "FAXの表外枠4点が自動判定の許容範囲を超えました。Step1.5で推定4点と許容範囲を目視確認し、OKまたは手動4点補正を行ってからOCRを再実行してください。",
                "recovery_action": "review_or_edit_quad",
                "processing_stage": "quad_estimation",
            }
        if "template_version" in raw_message or "template" in raw_message:
            return {
                "error": "template_resolution_failed",
                "error_detail": raw_message,
                "error_user_message": "施設テンプレートを解決できませんでした。Step1で施設テンプレートと施設区分列を確認してください。",
                "recovery_action": "review_facility_template",
                "processing_stage": "template_resolution",
            }
        return {
            "error": "hakodate_live_rerun_failed",
            "error_detail": raw_message,
            "error_user_message": "箱館方式のOCR処理中に失敗しました。詳細を確認し、PDF・施設・週次・テンプレート設定を確認してから再実行してください。",
            "recovery_action": "review_ocr_error",
            "processing_stage": "hakodate_live_pipeline",
        }

    try:
        output = _hakodate_canonical_payload_from_manifest_item(
            order_id=normalized_order_id, facility_id=facility_id,
            item={"source": "live_order_facility_source_workbook"},
            document_uri_override=document_uri,
            pdf_bytes_override=pdf_bytes,
        )
    except Exception as exc:
        failure = _hakodate_rerun_failure_payload(exc)
        return _persist_ocr_rerun_completion(
            order_id, ocr_job_id, None, error=str(failure["error"]),
            metrics_patch={**pipeline_metrics_patch, **failure},
            source="ocr-rerun-hakodate",
        )
    if not isinstance(output, dict):
        return _persist_ocr_rerun_completion(
            order_id, ocr_job_id, None, error="hakodate_live_rerun_invalid_output",
            metrics_patch=pipeline_metrics_patch, source="ocr-rerun-hakodate",
        )
    state = _classify_owned_evidence_payload(output)
    error = None if state.get("persistable") else str(state.get("error") or "evidence_unusable")
    runtime_metrics = output.get("metrics") if isinstance(output.get("metrics"), dict) else {}
    overlay = output.get("hakodate_overlay")
    output_reference = overlay.get("uri") if isinstance(overlay, dict) else None
    try:
        return _persist_ocr_rerun_completion(
            order_id, ocr_job_id, output, error=error, project_sheet=project_sheet and not error,
            output_reference=output_reference, source="ocr-rerun-hakodate",
            schema_version="v2_hakodate_evidence_rerun", producer_version="hakodate_best_method_pipeline",
            metrics_patch={
                **pipeline_metrics_patch, **runtime_metrics, "hakodate_live_pipeline": True,
                "new_evidence_available": not project_sheet and not error,
            },
        )
    except Exception as exc:
        # The caller transaction has rolled back before this diagnostic decision.
        return _persist_ocr_rerun_completion(
            order_id, ocr_job_id, output, error=str(exc),
            source="ocr-rerun-hakodate", metrics_patch=pipeline_metrics_patch,
            schema_version="v2_hakodate_evidence_rerun", producer_version="hakodate_best_method_pipeline",
        )


def switch_draft_to_latest_evidence(
    order_id: str,
    *,
    edited_by: str | None = None,
    synchronous_write_input: dict[str, Any] | None = None,
    evidence_run_override: dict[str, Any] | None = None,
    workflow_job_id: str | None = None,
) -> tuple[Optional[dict], Optional[str]]:
    captured_job_id = workflow_job_id or _workflow_ocr_job_id.get()
    if not captured_job_id:
        if synchronous_write_input is None:
            synchronous_write_input = _capture_synchronous_cache_write_input(order_id)
        if not isinstance(synchronous_write_input, dict):
            return None, "synchronous_input_missing"
        if evidence_run_override is not None and evidence_run_override != synchronous_write_input["evidence"]:
            return None, "synchronous_evidence_conflict"
        latest_evidence = synchronous_write_input["evidence"]
        current_draft = synchronous_write_input.get("draft")
    else:
        latest_evidence = evidence_run_override
        current_draft = get_latest_sheet_draft(order_id, backfill_from_revision=False, upgrade_generic_from_sheet=False)
    if not isinstance(latest_evidence, dict):
        return None, "evidence_not_found"
    latest_evidence_id = str(latest_evidence.get("id") or "").strip() or None
    if not latest_evidence_id:
        return None, "evidence_not_found"
    current_base_evidence_id = (
        str((current_draft or {}).get("base_evidence_run_id") or "").strip() or None
        if isinstance(current_draft, dict)
        else None
    )
    if current_base_evidence_id == latest_evidence_id and _draft_payload_has_hakodate_evidence_projection(current_draft):
        return current_draft, "already_current"

    latest_payload = latest_evidence.get("payload_json") if isinstance(latest_evidence, dict) else None
    if (
        isinstance(latest_payload, dict)
        and _payload_has_hakodate_target_cells(latest_payload)
        and _payload_has_hakodate_evidence_records(latest_payload, order_id=order_id)
    ):
        projected_bundle, projected_error = build_order_hakodate_projected_sheet(
            order_id,
            strategy="hakodate",
            evidence_run_override=latest_evidence,
            synchronous_write_input=synchronous_write_input,
        )
        if projected_error:
            return None, projected_error
        draft_payload = (
            projected_bundle.get("projected_sheet")
            if isinstance(projected_bundle, dict) and isinstance(projected_bundle.get("projected_sheet"), dict)
            else None
        )
    else:
        draft_payload, draft_error = _build_best_available_semantic_draft_with_error(
            order_id,
            use_saved_draft=False,
            evidence_run_override=latest_evidence,
        )
        if draft_error:
            return None, draft_error
    if not isinstance(draft_payload, dict):
        return None, "switch_draft_unavailable"

    persisted = _persist_sheet_draft_with_base_evidence(
        order_id=order_id,
        draft_sheet_json=draft_payload,
        draft_state="draft_blocked" if draft_payload.get("blockers") else "draft_ready",
        blockers=[str(item).strip() for item in (draft_payload.get("blockers") or []) if str(item).strip()],
        warnings=[str(item).strip() for item in (draft_payload.get("warnings") or []) if str(item).strip()],
        evidence_run_override=latest_evidence,
        edited_by=edited_by or "switch-evidence",
        synchronous_write_input=synchronous_write_input,
        workflow_job_id=captured_job_id,
    )
    if not isinstance(persisted, dict):
        return None, "switch_draft_failed"
    return persisted, None


def acknowledge_current_candidate_evidence(
    order_id: str,
    *,
    selected_by: str | None = None,
) -> tuple[Optional[dict], Optional[str]]:
    workflow_state = get_order_workflow_state(order_id, refresh=False)
    candidate_evidence_run_id = (
        str((workflow_state or {}).get("candidate_evidence_run_id") or "").strip()
        if isinstance(workflow_state, dict)
        else ""
    )
    if not candidate_evidence_run_id:
        return None, "candidate_not_found"
    decision = critical_decision_service.acknowledge_candidate_evidence(
        order_id,
        candidate_evidence_run_id,
        selected_by=selected_by or "operator",
    )
    if not isinstance(decision, dict):
        return None, "candidate_ack_failed"
    refreshed = workflow_state_service.refresh_workflow_state(
        order_id,
        include_candidate_preview=False,
    )
    if not isinstance(refreshed, dict):
        return None, "workflow_refresh_failed"
    return refreshed, None


def _acknowledge_current_candidate_after_authoritative_action(
    order_id: str,
    *,
    selected_by: str,
) -> Optional[dict]:
    workflow_state = get_order_workflow_state(order_id, refresh=True)
    candidate_evidence_run_id = (
        str((workflow_state or {}).get("candidate_evidence_run_id") or "").strip()
        if isinstance(workflow_state, dict)
        else ""
    )
    active_evidence_run_id = (
        str((workflow_state or {}).get("active_evidence_run_id") or "").strip()
        if isinstance(workflow_state, dict)
        else ""
    )
    acknowledgement_evidence_run_id = candidate_evidence_run_id or active_evidence_run_id
    if acknowledgement_evidence_run_id:
        decision = critical_decision_service.acknowledge_candidate_evidence(
            order_id,
            acknowledgement_evidence_run_id,
            selected_by=selected_by,
        )
        if not isinstance(decision, dict):
            raise RuntimeError("candidate_ack_failed")
        workflow_state = get_order_workflow_state(order_id, refresh=True)
    return workflow_state if isinstance(workflow_state, dict) else None


def get_candidate_draft_preview(order_id: str) -> tuple[Optional[dict], Optional[str]]:
    workflow_state = get_order_workflow_state(order_id, refresh=False)
    candidate_evidence_run_id = (
        str((workflow_state or {}).get("candidate_evidence_run_id") or "").strip()
        if isinstance(workflow_state, dict)
        else ""
    )
    if not candidate_evidence_run_id:
        workflow_state = get_order_workflow_state(order_id, refresh=True)
        candidate_evidence_run_id = (
            str((workflow_state or {}).get("candidate_evidence_run_id") or "").strip()
            if isinstance(workflow_state, dict)
            else ""
        )
    if not candidate_evidence_run_id:
        return None, "candidate_not_found"

    state = candidate_sheet_state(
        order_id,
        candidate_evidence_run_id=candidate_evidence_run_id,
    )
    preview_error = str(state.get("candidate_preview_error") or "").strip() or None
    preview_draft = state.get("candidate_preview_draft")
    if not isinstance(preview_draft, dict):
        return None, preview_error or "candidate_preview_unavailable"
    return preview_draft, None


def get_order_workflow_state(order_id: str, *, refresh: bool = False) -> Optional[dict]:
    if refresh:
        _reconcile_finished_ocr_rerun(order_id)
        return workflow_state_service.refresh_workflow_state(order_id)
    state = workflow_state_service.get_workflow_state(order_id)
    if state is not None:
        return state


def get_latest_patch_candidate(order_id: str) -> Optional[dict]:
    return patch_candidate_service.get_latest_patch_candidate(order_id)


def apply_patch_candidate_to_draft(
    order_id: str,
    *,
    candidate_id: str | None = None,
    applied_by: str | None = None,
) -> tuple[Optional[dict], Optional[str]]:
    result, error = patch_candidate_service.apply_patch_candidate_to_draft(
        order_id=order_id,
        patch_candidate_id=candidate_id,
        edited_by=applied_by,
    )
    if result is not None and error is None:
        try:
            workflow_state_service.refresh_workflow_state(order_id)
        except Exception as exc:  # noqa: BLE001
            logger.warning("Workflow state refresh failed after patch candidate apply", order_id=order_id, error=str(exc))
    return result, error


def get_order_candidate_resolution(order_id: str) -> Optional[dict]:
    state = get_order_workflow_state(order_id, refresh=False)
    if isinstance(state, dict):
        resolution = state.get("candidate_resolution")
        if isinstance(resolution, dict):
            return resolution
    order = get_order_by_id(order_id, allow_unresolved_menu_amount=True)
    evidence = _resolve_active_ocr_evidence_run(order_id)
    payload = evidence.get("payload_json") if isinstance(evidence, dict) else None
    return candidate_resolution_service.resolve_order_candidates(
        order_id=order_id,
        facility_code=str((order or {}).get("facility") or "").strip() or None,
        week_code=str((order or {}).get("week_value") or (order or {}).get("week") or "").strip() or None,
        received_at=(order or {}).get("received_at"),
        evidence_payload=payload if isinstance(payload, dict) else None,
    )


def _candidate_resolution_confidence_score(confidence: str | None) -> float | None:
    normalized = str(confidence or "").strip().lower()
    if normalized == "high":
        return 0.95
    if normalized == "medium":
        return 0.75
    if normalized == "low":
        return 0.45
    return None


def _candidate_column_mapping_is_payload_usable(
    resolution: dict[str, Any] | None,
    resolved_mapping: str | None,
) -> bool:
    if not isinstance(resolution, dict):
        return False
    normalized_mapping = str(resolved_mapping or "").strip()
    if not normalized_mapping:
        return False
    if ":" in normalized_mapping:
        return True
    if str(resolution.get("decision_source") or "").strip() == "position_fallback":
        return True
    for key in ("mapped_quantity_fields", "expected_quantity_fields"):
        value = resolution.get(key)
        if isinstance(value, list) and value:
            return True
    if resolution.get("partial_quantity_mapping") is not None:
        return True
    return False


def _augment_payload_with_candidate_resolution(
    order_id: str,
    payload: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if not isinstance(payload, dict):
        return payload
    candidate_resolution = get_order_candidate_resolution(order_id)
    resolutions = (
        candidate_resolution.get("resolutions")
        if isinstance(candidate_resolution, dict)
        else None
    )
    if not isinstance(resolutions, dict):
        return payload

    augmented = dict(payload)

    template_resolution = resolutions.get("template")
    if isinstance(template_resolution, dict):
        template_gate_state = candidate_resolution_service.get_resolution_gate_state(template_resolution)
        resolved_template_id = str(template_gate_state.get("resolved_value") or "").strip()
        existing_template_resolution = _get_template_resolution(augmented)
        existing_template_id = (
            str((existing_template_resolution or {}).get("resolved_template_id") or "").strip()
            if isinstance(existing_template_resolution, dict)
            else ""
        )
        if resolved_template_id and not existing_template_id:
            merged_template_resolution = dict(existing_template_resolution or {})
            merged_template_resolution["resolved_template_id"] = resolved_template_id
            merged_template_resolution.setdefault("matched_template_id", resolved_template_id)
            augmented["template_resolution"] = merged_template_resolution
            if resolved_template_id and not str(augmented.get("template_id") or "").strip():
                augmented["template_id"] = resolved_template_id

    column_mapping_resolution = resolutions.get("column_mapping")
    if isinstance(column_mapping_resolution, dict):
        mapping_gate_state = candidate_resolution_service.get_resolution_gate_state(column_mapping_resolution)
        resolved_mapping = str(mapping_gate_state.get("resolved_value") or "").strip()
        resolved_mapping_is_payload_usable = _candidate_column_mapping_is_payload_usable(
            column_mapping_resolution,
            resolved_mapping,
        )
        existing_mapping_resolution = augmented.get("column_mapping_resolution")
        existing_mapping_resolution = (
            existing_mapping_resolution if isinstance(existing_mapping_resolution, dict) else {}
        )
        existing_mapping_value = str(
            existing_mapping_resolution.get("resolved_value")
            or existing_mapping_resolution.get("resolved_column_mapping_id")
            or ""
        ).strip()
        decision_source = str(column_mapping_resolution.get("decision_source") or "").strip()
        should_merge_mapping_metadata = not existing_mapping_value and (
            (
                decision_source == "position_fallback"
                and mapping_gate_state.get("status") in {"resolved", "blocked", "choice_required"}
            )
            or (
                mapping_gate_state.get("status") == "resolved"
                and resolved_mapping_is_payload_usable
            )
        )
        if should_merge_mapping_metadata:
            merged_mapping_resolution = dict(existing_mapping_resolution)
            if resolved_mapping and resolved_mapping_is_payload_usable:
                merged_mapping_resolution["resolved_value"] = resolved_mapping
                merged_mapping_resolution["resolved_column_mapping_id"] = resolved_mapping
            merged_mapping_resolution["blocked"] = bool(mapping_gate_state.get("blocked"))
            merged_mapping_resolution["blocked_reasons"] = list(mapping_gate_state.get("blocked_reasons") or [])
            merged_mapping_resolution["requires_user_choice"] = bool(mapping_gate_state.get("requires_user_choice"))
            if decision_source:
                merged_mapping_resolution["decision_source"] = decision_source
            score = _candidate_resolution_confidence_score(column_mapping_resolution.get("confidence"))
            if score is not None and not isinstance(merged_mapping_resolution.get("confidence"), (int, float)):
                merged_mapping_resolution["confidence"] = score
            candidates = column_mapping_resolution.get("candidates")
            if isinstance(candidates, list) and candidates:
                merged_mapping_resolution["candidates"] = candidates
                augmented["column_mapping_candidates"] = candidates
            for key in (
                "partial_quantity_mapping",
                "mapped_quantity_fields",
                "expected_quantity_fields",
                "evidence_ref",
            ):
                value = column_mapping_resolution.get(key)
                if value not in (None, [], {}):
                    merged_mapping_resolution[key] = value
            augmented["column_mapping_resolution"] = merged_mapping_resolution

    return augmented


def list_order_critical_decisions(order_id: str, *, refresh_workflow: bool = False) -> list[dict[str, Any]]:
    if refresh_workflow:
        get_order_workflow_state(order_id, refresh=True)
    return [
        item
        for item in critical_decision_service.list_decisions(order_id)
        if not critical_decision_service.is_internal_decision_type(
            str(item.get("decision_type") or "").strip() if isinstance(item, dict) else "",
        )
    ]




def _materialize_current_sheet_record(
    order_id: str,
    *,
    draft_record: dict[str, Any] | None,
    draft_payload: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if isinstance(draft_record, dict):
        materialized_record = dict(draft_record)
        if isinstance(draft_payload, dict):
            materialized_record["draft_sheet_json"] = dict(draft_payload)
        return materialized_record
    if isinstance(draft_payload, dict):
        return _build_transient_draft_record(order_id, draft_payload)
    return None


def flatten_current_sheet_payload(
    order_id: str,
    draft_payload: dict[str, Any],
    *,
    include_meta: bool = True,
) -> dict[str, Any]:
    current_sheet_context = draft_payload if isinstance(draft_payload.get("draft_record"), dict) else None
    draft_record = (
        current_sheet_context.get("draft_record")
        if isinstance(current_sheet_context, dict)
        else draft_payload
    )
    draft_json = (
        current_sheet_context.get("draft_payload")
        if isinstance(current_sheet_context, dict) and isinstance(current_sheet_context.get("draft_payload"), dict)
        else (draft_record.get("draft_sheet_json") if isinstance(draft_record.get("draft_sheet_json"), dict) else {})
    )
    current_fields = (
        list(current_sheet_context.get("fields") or [])
        if isinstance(current_sheet_context, dict) and isinstance(current_sheet_context.get("fields"), list)
        else list(draft_json.get("fields") or [])
    )
    current_header = (
        list(current_sheet_context.get("header") or [])
        if isinstance(current_sheet_context, dict) and isinstance(current_sheet_context.get("header"), list)
        else list(draft_json.get("header") or [])
    )
    current_rows = (
        list(current_sheet_context.get("rows") or [])
        if isinstance(current_sheet_context, dict) and isinstance(current_sheet_context.get("rows"), list)
        else list(draft_json.get("rows") or [])
    )
    current_row_ids = (
        list(current_sheet_context.get("row_ids") or [])
        if isinstance(current_sheet_context, dict) and isinstance(current_sheet_context.get("row_ids"), list)
        else list(draft_json.get("row_ids") or [])
    )
    current_source = (
        str(current_sheet_context.get("source") or "").strip()
        if isinstance(current_sheet_context, dict)
        else ""
    )
    if not current_source:
        current_source = apply_gate_service.canonical_sheet_source(
            draft_json.get("source") or draft_record.get("draft_state") or "draft",
            has_persisted_draft=bool(str((draft_record or {}).get("id") or "").strip())
            and apply_gate_service.sheet_fields_are_semantic(current_fields)
            and bool(current_rows),
        )
    warnings = [
        str(item).strip()
        for item in (
            list(draft_json.get("warnings") or [])
            + list(draft_record.get("warnings_json") or [])
        )
        if str(item).strip()
    ]
    deduped_warnings: list[str] = []
    for item in warnings:
        if item not in deduped_warnings:
            deduped_warnings.append(item)
    menu_diagnostics = (
        dict(current_sheet_context.get("menu_diagnostics") or {})
        if isinstance(current_sheet_context, dict) and isinstance(current_sheet_context.get("menu_diagnostics"), dict)
        else dict(draft_json.get("menu_diagnostics") or {})
        if isinstance(draft_json.get("menu_diagnostics"), dict)
        else {}
    )
    menu_codes = [
        str(item).strip()
        for item in (menu_diagnostics.get("order_codes") or [])
        if str(item).strip()
    ]
    for item in menu_codes:
        if item not in deduped_warnings:
            deduped_warnings.append(item)
    lightweight_blockers: list[str] = []
    for item in (
        list(draft_json.get("blockers") or [])
        + list(draft_record.get("blockers_json") or [])
        + list((current_sheet_context or {}).get("blockers") or [])
        + menu_codes
    ):
        normalized = str(item).strip()
        if normalized and normalized not in lightweight_blockers:
            lightweight_blockers.append(normalized)
    resolved_week_id = (
        str((current_sheet_context or {}).get("resolved_week_id") or "").strip()
        or str(draft_json.get("resolved_week_id") or draft_json.get("week_id") or "").strip()
        or None
    )
    order_payload = (
        current_sheet_context.get("order_payload")
        if isinstance(current_sheet_context, dict) and isinstance(current_sheet_context.get("order_payload"), dict)
        else get_order_by_id(order_id, allow_unresolved_menu_amount=True)
    )
    base_payload: dict[str, Any] = dict(draft_json)
    base_payload.update(
        {
            "id": (draft_record or {}).get("id"),
            "order_id": order_id,
            "current_sheet_revision_id": (
                str((current_sheet_context or {}).get("current_sheet_revision_id") or "").strip()
                or _current_sheet_revision_id(order_id=order_id)
            ),
            "draft_state": (
                str((draft_record or {}).get("draft_state") or base_payload.get("draft_state") or "draft_ready").strip()
                or "draft_ready"
            ),
            "base_evidence_run_id": (
                str((draft_record or {}).get("base_evidence_run_id") or base_payload.get("base_evidence_run_id") or "").strip()
                or None
            ),
            "base_template_resolution_id": (
                str((draft_record or {}).get("base_template_resolution_id") or base_payload.get("base_template_resolution_id") or "").strip()
                or None
            ),
            "latest_patch_candidate_id": (draft_record or {}).get("latest_patch_candidate_id"),
            "edited_by": (draft_record or {}).get("edited_by"),
            "edited_at": (draft_record or {}).get("edited_at"),
            "created_at": (draft_record or {}).get("created_at"),
            "fields": current_fields,
            "header": current_header,
            "rows": current_rows,
            "row_ids": current_row_ids,
            "source": current_source or str(base_payload.get("source") or "").strip() or "draft",
            "resolved_week_id": resolved_week_id,
            "week_id": (
                str(base_payload.get("week_id") or "").strip()
                or resolved_week_id
            ),
            "facility_id": (
                str(base_payload.get("facility_id") or "").strip()
                or str((order_payload or {}).get("facility") or "").strip()
                or str((current_sheet_context or {}).get("facility_id") or "").strip()
                or None
            ),
            "menu_diagnostics": menu_diagnostics,
            "row_diagnostics": list(draft_json.get("row_diagnostics") or []) if isinstance(draft_json.get("row_diagnostics"), list) else [],
            "repair_mode": str(draft_json.get("repair_mode") or "").strip() or None,
            "repair_metadata": dict(draft_json.get("repair_metadata") or {}) if isinstance(draft_json.get("repair_metadata"), dict) else {},
            "seed_source": str(draft_json.get("seed_source") or "").strip() or None,
            "enrichment_source": str(draft_json.get("enrichment_source") or "").strip() or None,
            "warnings": deduped_warnings,
            "blockers": lightweight_blockers,
        }
    )
    if not include_meta:
        return base_payload
    workflow = workflow_state_service.project_workflow_state(
        order_id,
        current_sheet_context=current_sheet_context,
    )
    if not isinstance(workflow, dict) or not isinstance(workflow.get("apply_gate"), dict):
        raise ValueError("current_sheet_apply_gate_unavailable")
    evidence = _resolve_active_ocr_evidence_run(order_id)
    apply_gate = workflow.get("apply_gate") if isinstance(workflow, dict) else None
    canonical_order_week_id = (
        str((order_payload or {}).get("persisted_week_value") or "").strip()
        or str((order_payload or {}).get("week_value") or "").strip()
        or str((order_payload or {}).get("week") or "").strip()
        or None
    )
    return {
        **base_payload,
        "resolved_week_id": (
            resolved_week_id
            or canonical_order_week_id
        ),
        "week_id": (
            str(base_payload.get("week_id") or "").strip()
            or resolved_week_id
            or canonical_order_week_id
        ),
        "warnings": deduped_warnings,
        "blockers": lightweight_blockers,
        "review_state": (
            str((workflow or {}).get("state") or draft_record.get("draft_state") or "draft_ready").strip()
            if isinstance(workflow, dict) or draft_record.get("draft_state")
            else "draft_ready"
        ),
        "workflow_state": workflow,
        "apply_gate": apply_gate,
        "apply_blockers": list((apply_gate or {}).get("apply_blockers") or []) if isinstance(apply_gate, dict) else [],
        "confirm_blockers": list((apply_gate or {}).get("confirm_blockers") or []) if isinstance(apply_gate, dict) else [],
        "confirm_warnings": list((apply_gate or {}).get("confirm_warnings") or []) if isinstance(apply_gate, dict) else [],
        "critical_decisions": list((workflow or {}).get("critical_decisions") or []) if isinstance(workflow, dict) else [],
        "candidate_resolution": (workflow or {}).get("candidate_resolution") if isinstance(workflow, dict) else None,
        "evidence_run_id": (evidence or {}).get("id") if isinstance(evidence, dict) else None,
        "evidence_capabilities": (
            (evidence or {}).get("capabilities_json")
            if isinstance(evidence, dict)
            else {}
        ),
        "evidence_degraded_reasons": list((evidence or {}).get("degraded_reasons_json") or []) if isinstance(evidence, dict) else [],
    }


def _authoritative_surface_payload_from_current_sheet_context(
    order_id: str,
    current_sheet_context: dict[str, Any] | None,
) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    if not isinstance(current_sheet_context, dict):
        return None, None
    draft_payload = (
        current_sheet_context.get("draft_payload")
        if isinstance(current_sheet_context.get("draft_payload"), dict)
        else None
    )
    draft_record = (
        current_sheet_context.get("draft_record")
        if isinstance(current_sheet_context.get("draft_record"), dict)
        else None
    )
    current_sheet_record = _materialize_current_sheet_record(
        order_id,
        draft_record=draft_record,
        draft_payload=draft_payload,
    )
    surface_payload = flatten_current_sheet_payload(order_id, current_sheet_context)
    if not isinstance(surface_payload, dict):
        return None, current_sheet_record
    fields = [
        str(field).strip()
        for field in (surface_payload.get("fields") or [])
        if str(field).strip()
    ]
    source = str(surface_payload.get("source") or "").strip()
    rows = surface_payload.get("rows") if isinstance(surface_payload.get("rows"), list) else None
    if not fields or not source or rows is None:
        return None, current_sheet_record
    base_evidence_run_id = str(current_sheet_context.get("base_evidence_run_id") or "").strip()
    if base_evidence_run_id:
        surface_payload["evidence_run_id"] = base_evidence_run_id
        surface_payload["base_evidence_run_id"] = base_evidence_run_id
    surface_payload["ocr_job_id"] = f"OCR-{order_id}"
    return surface_payload, current_sheet_record


def _get_template_resolution(payload: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(payload, dict):
        return None
    resolution = payload.get("template_resolution")
    if not isinstance(resolution, dict):
        return None
    normalized = template_resolution_service.normalize_template_resolution_state(resolution)
    return normalized if isinstance(normalized, dict) else resolution




def _ocr_evidence_missing_artifacts(payload: dict[str, Any] | None) -> list[str]:
    return evidence_manifest_service.evidence_missing_artifacts(payload)


def _sheet_payload_mapping_block_reason(
    *,
    source: str,
    ocr_payload: dict[str, Any] | None,
    template: dict[str, Any] | None,
    evidence_missing: list[str] | None,
    template_blockers: list[str] | None,
) -> str | None:
    if not _source_uses_weekly_menu_shell(source):
        return None
    template_resolution = _get_template_resolution(ocr_payload)
    column_mapping_resolution = (
        ocr_payload.get("column_mapping_resolution")
        if isinstance(ocr_payload, dict)
        else None
    )
    strict_evidence_context = _sheet_uses_strict_evidence_context(ocr_payload)
    position_fallback_semantics_ready = position_column_mapping_service.payload_uses_ready_position_fallback(
        ocr_payload,
        template=template,
    )
    position_fallback_partial = position_column_mapping_service.payload_uses_partial_position_fallback(
        ocr_payload
    )
    position_fallback_requires_choice = position_column_mapping_service.payload_position_fallback_requires_choice(
        ocr_payload
    )
    position_fallback_current_sheet_ready = (
        position_fallback_semantics_ready or position_fallback_partial
    )
    position_fallback_decision_source = bool(
        isinstance(column_mapping_resolution, dict)
        and str(column_mapping_resolution.get("decision_source") or "").strip() == "position_fallback"
    )
    if position_fallback_requires_choice or position_fallback_decision_source:
        return "unresolved_template"
    if any(str(item or "").strip() for item in (template_blockers or [])):
        return "unresolved_template"
    missing = {str(item or "").strip() for item in (evidence_missing or []) if str(item or "").strip()}
    if strict_evidence_context and "template_resolution" in missing and not position_fallback_current_sheet_ready:
        return "unresolved_template"
    has_structured_table_rows = bool(
        isinstance(ocr_payload, dict)
        and (
            (isinstance(ocr_payload.get("table_rows"), list) and bool(ocr_payload.get("table_rows")))
            or (isinstance(ocr_payload.get("tables"), list) and bool(ocr_payload.get("tables")))
        )
    )
    reusable_template_semantics = _payload_has_reusable_semantic_quantity_rows(
        ocr_payload,
        template,
    )
    if not isinstance(template_resolution, dict):
        if position_fallback_current_sheet_ready or reusable_template_semantics:
            if ocr_evidence_service.payload_has_high_risk_numeric_issues(ocr_payload):
                return "numeric_review_required"
            return None
        if (
            isinstance(ocr_payload, dict)
            and str(ocr_payload.get("table_raw") or "").strip()
            and not has_structured_table_rows
            and not _raw_table_has_strong_template_quantity_semantics(ocr_payload, template)
        ):
            return "unresolved_template"
        return None
    # Weekly-menu rescue can only be trusted when quantity-column semantics are known.
    # Full row-edge metadata is useful for overlays, but Step2 quantity mapping only needs a
    # resolved template plus stable quantity column boundaries.
    if (
        not ocr_evidence_service.payload_has_quantity_column_semantics(ocr_payload)
        and not position_fallback_current_sheet_ready
        and not reusable_template_semantics
    ):
        return "unresolved_template"
    if ocr_evidence_service.payload_has_high_risk_numeric_issues(ocr_payload):
        return "numeric_review_required"
    return None


def _is_markdown_separator_cells(cells: list[str]) -> bool:
    if not cells:
        return False
    for cell in cells:
        token = str(cell or "").strip()
        if not token:
            continue
        if not re.fullmatch(r":?-{3,}:?", token):
            return False
    return True


def _extract_markdown_header_cells(markdown: str) -> list[str]:
    normalized = _normalize_table_raw_text(markdown)
    for raw_line in normalized.splitlines():
        line = str(raw_line or "").strip()
        if not line.startswith("|") or "|" not in line[1:]:
            continue
        cells = [str(cell or "").strip() for cell in line.strip("|").split("|")]
        if _is_markdown_separator_cells(cells):
            continue
        return cells
    return []


def _raw_table_has_strong_template_quantity_semantics(
    payload: dict[str, Any] | None,
    template: dict[str, Any] | None,
) -> bool:
    if not isinstance(payload, dict) or not isinstance(template, dict):
        return False
    table_raw = str(payload.get("table_raw") or "").strip()
    if not table_raw:
        return False
    parsed_rows = rows_from_markdown(table_raw, template) or []
    if not parsed_rows:
        return False
    fields = _get_row_fields(template)
    if not fields:
        return False
    quantity_fields = [field for field in fields if field.startswith("qty.")]
    if not quantity_fields:
        return False
    header_cells = _extract_markdown_header_cells(table_raw)
    if not header_cells:
        return False
    mapped_fields = {
        mapped
        for mapped in (_field_from_header(cell, set(fields)) for cell in header_cells)
        if isinstance(mapped, str) and mapped.strip()
    }
    structural_fields = {
        field for field in mapped_fields if field in {"date_mmdd", "date", "daypart", "menu", "menu_name"}
    }
    quantity_indexes = [idx for idx, field in enumerate(fields) if field.startswith("qty.")]
    populated_quantity_indexes = {
        idx
        for row in parsed_rows
        if isinstance(row, list)
        for idx in quantity_indexes
        if idx < len(row) and _parse_strict_numeric_cell(row[idx]) is not None
    }
    required_quantity_columns = 1 if len(quantity_fields) == 1 else 2
    return len(structural_fields) >= 3 and len(populated_quantity_indexes) >= required_quantity_columns


def _payload_has_reusable_semantic_quantity_rows(
    payload: dict[str, Any] | None,
    template: dict[str, Any] | None,
) -> bool:
    if not isinstance(payload, dict) or not isinstance(template, dict):
        return False
    fields = _get_row_fields(template)
    if not fields:
        return False
    rows = _extract_sheet_rows_from_payload(payload, template)
    if not rows:
        return False
    date_idx, daypart_idx, menu_idx, quantity_indexes = _resolve_structural_row_field_indexes(fields)
    if date_idx is None or daypart_idx is None or menu_idx is None or not quantity_indexes:
        return False
    structural_rows = 0
    quantity_rows = 0
    for row in rows:
        if not isinstance(row, list):
            continue
        if (
            date_idx < len(row)
            and daypart_idx < len(row)
            and menu_idx < len(row)
            and str(row[date_idx] or "").strip()
            and str(row[daypart_idx] or "").strip()
            and str(row[menu_idx] or "").strip()
        ):
            structural_rows += 1
        if any(
            quantity_idx < len(row) and _parse_strict_numeric_cell(row[quantity_idx]) is not None
            for quantity_idx in quantity_indexes
        ):
            quantity_rows += 1
    return structural_rows > 0 and quantity_rows > 0




def _sheet_uses_strict_evidence_context(payload: dict[str, Any] | None) -> bool:
    return bool(
        isinstance(payload, dict)
        and (
            "page_correction_artifacts" in payload
            or "page_correction" in payload
            or "template_resolution" in payload
            or "quantity_subgrid_passes" in payload
        )
    )


