def _load_order_ocr_cache_map(order_ids: list[str]) -> dict[str, dict[str, Any]]:
    normalized_ids = [str(item).strip() for item in (order_ids or []) if str(item).strip()]
    if not normalized_ids:
        return {}
    try:
        with session_scope() as session:
            rows = (
                session.execute(
                    select(OrderOcrCache).where(OrderOcrCache.order_id.in_(normalized_ids))
                )
                .scalars()
                .all()
            )
            return {
                cache.order_id: cache.payload
                for cache in rows
                if isinstance(cache.payload, dict)
            }
    except Exception as exc:  # noqa: BLE001
        logger.warning("Order OCR cache bulk load failed", order_ids=normalized_ids[:20], error=str(exc))
        return {}


def _parse_iso_datetime_value(value: object) -> datetime | None:
    if isinstance(value, datetime):
        return value
    text = str(value or "").strip()
    if not text:
        return None
    try:
        return datetime.fromisoformat(text)
    except Exception:
        return None


def _load_pipeline_output_with_retry(
    output_ref: str | None,
    *,
    wait_seconds_override: float | None = None,
) -> Optional[dict]:
    if not output_ref:
        return None
    if wait_seconds_override is None:
        try:
            wait_seconds = float(os.getenv("OCR_REPARSE_OUTPUT_WAIT_SECONDS", "90"))
        except ValueError:
            wait_seconds = 15.0
    else:
        wait_seconds = float(wait_seconds_override)
    try:
        poll_seconds = float(os.getenv("OCR_REPARSE_OUTPUT_POLL_SECONDS", "1.5"))
    except ValueError:
        poll_seconds = 1.5
    deadline = time.monotonic() + max(wait_seconds, 0.0)
    last_error = None
    while True:
        try:
            payload = load_bytes_from_uri(output_ref)
            parsed = json.loads(payload.decode("utf-8"))
            validate_own_pipeline_result(parsed, output_ref)
            if _output_is_pending(parsed):
                last_error = RuntimeError("ocr_output_pending")
                if time.monotonic() >= deadline:
                    break
                time.sleep(max(poll_seconds, 0.1))
                continue
            return parsed
        except OwnPipelineLineageError:
            raise
        except Exception as exc:  # noqa: BLE001
            last_error = exc
            if time.monotonic() >= deadline:
                break
            time.sleep(max(poll_seconds, 0.1))
    logger.warning("OCR output not ready after wait", output_reference=output_ref, error=str(last_error))
    return None


def _load_pipeline_output_once(output_ref: str | None) -> Optional[dict]:
    if not output_ref:
        return None
    try:
        payload = load_bytes_from_uri(output_ref)
        parsed = json.loads(payload.decode("utf-8"))
        validate_own_pipeline_result(parsed, output_ref)
    except OwnPipelineLineageError:
        raise
    except Exception as exc:  # noqa: BLE001
        logger.debug("OCR output single read failed", output_reference=output_ref, error=str(exc))
        return None
    return parsed if isinstance(parsed, dict) else None


def _resolve_order_fax_template(order_id: str) -> dict[str, Any] | None:
    try:
        return _read_order_authored_facility_config(order_id)["fax_template"]
    except ValueError:
        return None


def _extract_first_pass_payload_row_width(payload: dict[str, Any] | None) -> int | None:
    if not isinstance(payload, dict):
        return None
    candidate_widths: list[int] = []
    for key in ("rows", "table_rows"):
        rows = payload.get(key)
        if not isinstance(rows, list):
            continue
        for row in rows:
            if isinstance(row, list) and row:
                candidate_widths.append(len(row))
    tables = payload.get("tables")
    if isinstance(tables, list):
        for table in tables:
            if not isinstance(table, dict):
                continue
            rows = table.get("rows")
            if not isinstance(rows, list):
                continue
            for row in rows:
                if isinstance(row, list) and row:
                    candidate_widths.append(len(row))
    table_raw = str(payload.get("table_raw") or "").strip()
    if table_raw:
        header_cells = _extract_markdown_header_cells(table_raw)
        if header_cells:
            candidate_widths.append(len(header_cells))
    if not candidate_widths:
        return None
    return max(candidate_widths)


def _payload_schema_contract_fingerprint(payload: dict[str, Any] | None) -> str | None:
    if not isinstance(payload, dict):
        return None
    contract = payload.get("_template_field_schema")
    if not isinstance(contract, dict):
        return None
    fingerprint = str(contract.get("fingerprint") or "").strip()
    return fingerprint or None


def _payload_first_pass_schema_matches_template(
    payload: dict[str, Any] | None,
    template: dict[str, Any] | None,
) -> bool:
    if not isinstance(payload, dict) or not isinstance(template, dict):
        return True
    expected_contract = build_template_field_schema_contract(template)
    if not expected_contract:
        return True
    payload_fingerprint = _payload_schema_contract_fingerprint(payload)
    expected_fingerprint = str(expected_contract.get("fingerprint") or "").strip()
    if payload_fingerprint and expected_fingerprint:
        return payload_fingerprint == expected_fingerprint
    payload_fields = [
        str(field or "").strip()
        for field in (payload.get("fields") or [])
        if str(field or "").strip()
    ]
    if payload_fields:
        return payload_fields == list(expected_contract.get("fields") or [])
    observed_width = _extract_first_pass_payload_row_width(payload)
    if observed_width is None:
        return True
    return observed_width == int(expected_contract.get("field_count") or 0)


def _annotate_payload_with_template_field_schema(
    payload: dict[str, Any] | None,
    template: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if not isinstance(payload, dict) or not isinstance(template, dict):
        return payload
    if not _payload_first_pass_schema_matches_template(payload, template):
        return payload
    contract = build_template_field_schema_contract(template)
    if not contract:
        return payload
    enriched = dict(payload)
    enriched["_template_field_schema"] = contract
    return enriched


def _resolve_own_resume_first_pass(order_id, job_id, payload, template, *, output_reference=None, selected_input_reference=None):
    if not isinstance(payload, dict) or not _payload_has_first_pass_ocr_content(payload):
        return None, "own_first_pass_missing"
    with session_scope() as session:
        if not _workflow_attempt_write_fence(session, job_id, order_id):
            return None, "workflow_attempt_superseded"
        if selected_input_reference is not None:
            selected_job = session.get(OcrJob, job_id)
            if selected_job is None or selected_job.input_reference != selected_input_reference:
                return None, "own_first_pass_document_conflict"
        execution = payload.get("_ocr_execution")
        boundary = current_nonworkflow_execution()
        if isinstance(boundary, dict) and boundary.get("ingest_successor_id"):
            from src.services.ingest_delivery_successor_service import validate_resume
            if not validate_resume(session, boundary, payload, output_reference=output_reference):
                return None, "own_first_pass_successor_lineage_mismatch"
        elif isinstance(execution, dict):
            boundary = current_nonworkflow_execution()
            if (
                execution.get("job_id") != job_id
                or execution.get("workflow_attempt_id") != _workflow_ocr_attempt_id.get()
                or execution.get("workflow_revision") != _workflow_ocr_revision.get()
                or execution.get("nonworkflow_execution_id") != (boundary or {}).get("execution_id")
                or not execution.get("evidence_run_id")
            ):
                return None, "own_first_pass_lineage_mismatch"
            evidence = session.get(OrderOcrEvidenceRun, execution["evidence_run_id"])
            if evidence is None or evidence.order_id != order_id or evidence.payload_json != payload:
                return None, "own_first_pass_lineage_mismatch"
        else:
            job = session.get(OcrJob, job_id)
            if not output_reference or job is None or job.output_reference != output_reference or job.order_id != order_id:
                return None, "own_first_pass_lineage_missing"
            delivery = (job.metrics or {}).get("pipeline_delivery_receipt")
            if not isinstance(delivery, dict) or not own_pipeline_delivery_matches(job, delivery.get("input_reference"), output_reference):
                return None, "own_first_pass_delivery_mismatch"
            try:
                validate_own_pipeline_result(payload, output_reference, write_session=session)
            except OwnPipelineLineageError:
                return None, "own_first_pass_delivery_mismatch"
    if not _payload_first_pass_schema_matches_template(payload, template):
        return None, "own_first_pass_schema_incompatible"
    return _annotate_payload_with_template_field_schema(deepcopy(payload), template), None


def _load_existing_first_pass_payload_for_reparse(
    order_id: str,
    *,
    template: dict[str, Any] | None = None,
) -> tuple[dict[str, Any] | None, str | None]:
    job_id = _workflow_ocr_job_id.get()
    with session_scope() as session:
        if not job_id or not _workflow_attempt_write_fence(session, job_id, order_id):
            return None, "workflow_attempt_superseded"
        boundary = current_nonworkflow_execution()
        if boundary is not None:
            source = boundary.get("first_pass_source")
        else:
            job = session.get(OcrJob, job_id)
            source = (job.metrics or {}).get("first_pass_source") if job is not None else None
        if not isinstance(source, dict) or source.get("order_id") != order_id or not source.get("evidence_run_id"):
            return None, "first_pass_selected_input_missing"
        evidence = session.get(OrderOcrEvidenceRun, source["evidence_run_id"])
        if evidence is None or evidence.order_id != order_id:
            return None, "first_pass_selected_input_mismatch"
        values = {column.key: getattr(evidence, column.key) for column in evidence.__table__.columns}
        if captured_evidence_source(order_id, values) != source or not ocr_evidence_service.evidence_run_is_selectable(evidence):
            return None, "first_pass_selected_input_mismatch"
        payload = deepcopy(evidence.payload_json)
    if not _payload_has_first_pass_ocr_content(payload):
        return None, "first_pass_selected_input_missing"
    if not _payload_first_pass_schema_matches_template(payload, template):
        return None, "first_pass_selected_schema_incompatible"
    return _annotate_payload_with_template_field_schema(payload, template), None


def get_ocr_raw_text(order_id: str):
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return None, "order_not_found"
        message_id = order.message_id
    if _workflow_ocr_job_id.get() or current_nonworkflow_execution() is not None:
        raw_text = _load_pipeline_raw_text(order_id, message_id)
    else:
        # Operator projection reads its explicitly selected evidence, not a job
        # discovered from current/latest output filenames.
        selected = ocr_evidence_service.get_selected_evidence_run(order_id)
        payload = selected.get("payload_json") if isinstance(selected, dict) else None
        if not isinstance(payload, dict):
            return None, "ocr_raw_not_found"
        raw_text = payload.get("table_raw")
        if not isinstance(raw_text, str) or not raw_text.strip():
            raw_text = json.dumps(payload, ensure_ascii=False, indent=2)
    if not raw_text:
        return None, "ocr_raw_not_found"
    return {"order_id": order_id, "raw_text": raw_text}, None


def _coerce_table_cell(value: object) -> str:
    if value is None:
        return ""
    if isinstance(value, bool):
        return "1" if value else "0"
    if isinstance(value, (int, float)):
        if float(value).is_integer():
            return str(int(value))
        return str(value)
    return str(value)


def _normalize_header_token(value: str) -> str:
    normalized = value.strip().lower()
    normalized = re.sub(r"\s+", "", normalized)
    translation = str.maketrans(
        {
            "０": "0",
            "１": "1",
            "２": "2",
            "３": "3",
            "４": "4",
            "５": "5",
            "６": "6",
            "７": "7",
            "８": "8",
            "９": "9",
            "ｆ": "f",
            "Ｆ": "f",
        }
    )
    return normalized.translate(translation)


def _select_field(candidates: list[str], fields: set[str]) -> str | None:
    for candidate in candidates:
        if candidate in fields:
            return candidate
    return None


def _field_from_header(header: str, fields: set[str]) -> str | None:
    token = _normalize_header_token(header)
    if "備考" in token or "remarks" in token or "note" in token:
        return _select_field(["remarks", "note"], fields)
    if "献立" in token or "メニュー" in token or "menu" in token:
        return _select_field(["menu", "menu_name"], fields)
    if "日付" in token or token.startswith("日"):
        return _select_field(["date_mmdd", "date"], fields)
    if "区分" in token or "時間帯" in token:
        return _select_field(["daypart"], fields)
    if ("袋" in token or "bag" in token) and (
        "常食" in token or "regular" in token or "通常" in token or "常" in token
    ):
        return _select_field(["qty.regular_bag_x", "regular_bag_x"], fields)
    if "常食" in token or "regular" in token or "常" in token:
        if "3回" in token or "3回目" in token:
            return _select_field(["qty.change_2_x", "change_2_x"], fields)
        if "2回" in token or "2回目" in token:
            return _select_field(["qty.change_1_x", "change_1_x"], fields)
        if "1回" in token or "1回目" in token:
            return _select_field(["qty.regular_x", "regular_x"], fields)
        if "2f" in token:
            return _select_field(["qty.regular_2f", "regular_2f", "qty.regular_x", "regular_x"], fields)
        if "3f" in token:
            return _select_field(["qty.regular_3f", "regular_3f", "qty.regular_x", "regular_x"], fields)
        return _select_field(
            [
                "qty.regular_x",
                "regular_x",
                "qty.regular_2f",
                "regular_2f",
                "qty.regular_3f",
                "regular_3f",
            ],
            fields,
        )
    if "軟菜" in token or "soft" in token or "軟" in token:
        if "2f" in token:
            return _select_field(["qty.soft_2f", "soft_2f", "qty.soft_x", "soft_x"], fields)
        if "3f" in token:
            return _select_field(["qty.soft_3f", "soft_3f", "qty.soft_x", "soft_x"], fields)
        return _select_field(
            ["qty.soft_x", "soft_x", "qty.soft_2f", "soft_2f", "qty.soft_3f", "soft_3f"],
            fields,
        )
    if "ミキサ" in token or "mixer" in token or "ミキ" in token:
        if "2f" in token:
            return _select_field(["qty.mixer_2f", "mixer_2f", "qty.mixer_x", "mixer_x"], fields)
        if "3f" in token:
            return _select_field(["qty.mixer_3f", "mixer_3f", "qty.mixer_x", "mixer_x"], fields)
        return _select_field(
            [
                "qty.mixer_x",
                "mixer_x",
                "qty.mixer_2f",
                "mixer_2f",
                "qty.mixer_3f",
                "mixer_3f",
            ],
            fields,
        )
    if "職員" in token or "staff" in token:
        return _select_field(["qty.staff_x", "staff_x"], fields)
    if "お茶" in token or "tea" in token:
        return _select_field(["qty.tea_x", "tea_x"], fields)
    if "事業" in token or "business" in token:
        return _select_field(["qty.business_x", "business_x"], fields)
    if "通所" in token or "daycare" in token:
        return _select_field(["qty.daycare_x", "daycare_x"], fields)
    if "揚げ物禁" in header or "揚物禁" in header or "nofried" in token:
        return _select_field(["qty.no_fried_x", "no_fried_x"], fields)
    if "糖尿" in token or "diabetes" in token:
        return _select_field(["qty.diabetes_x", "diabetes_x", "qty.糖尿_x", "糖尿_x"], fields)
    if "妊娠" in token or "pregnancy" in token:
        return _select_field(["qty.pregnancy_x", "pregnancy_x"], fields)
    if ("ごま" in token or "ゴマ" in header or "sesame" in token) and (
        "アレル" in header or "allergy" in token
    ):
        return _select_field(["qty.sesame_allergy_x", "sesame_allergy_x"], fields)
    if (
        ("肉" in token or "meat" in token)
        and ("卵" in token or "玉子" in token or "egg" in token)
        and ("魚" in token or "鯖" in token or "さば" in token or "fish" in token)
    ) or "肉卵魚禁" in header:
        return _select_field(["qty.forbidden_other_x", "forbidden_other_x"], fields)
    if ("禁" in token and "肉" in token) or "nomeat" in token:
        return _select_field(
            ["qty.no_meat_x", "no_meat_x", "qty.no_meat_2f", "no_meat_2f", "qty.no_meat_3f", "no_meat_3f"],
            fields,
        )
    if ("禁" in token and "魚" in token) or "nofish" in token:
        return _select_field(
            ["qty.no_fish_x", "no_fish_x", "qty.no_fish_2f", "no_fish_2f", "qty.no_fish_3f", "no_fish_3f"],
            fields,
        )
    if "変更1" in header or "change1" in token:
        return _select_field(["qty.change_1_x", "change_1_x"], fields)
    if "変更2" in header or "change2" in token:
        return _select_field(["qty.change_2_x", "change_2_x"], fields)
    if token in {"-", "placeholder"}:
        return _select_field(["qty.placeholder_x", "placeholder_x"], fields)
    return None


def _get_row_fields(template: dict[str, Any]) -> list[str]:
    return fax_extractor._get_row_fields(template)


_SHEET_TRANSLATION = str.maketrans(
    {
        "０": "0",
        "１": "1",
        "２": "2",
        "３": "3",
        "４": "4",
        "５": "5",
        "６": "6",
        "７": "7",
        "８": "8",
        "９": "9",
        "ｆ": "f",
        "Ｆ": "f",
    }
)


def _normalize_sheet_text(value: object) -> str:
    if value is None:
        return ""
    text = str(value).strip()
    if not text:
        return ""
    text = text.translate(_SHEET_TRANSLATION)
    text = re.sub(r"[\s　]+", "", text)
    return text


def _normalize_sheet_date_key(value: object) -> str:
    text = _field_value_to_str(value).strip()
    if not text:
        return ""
    normalized = text.translate(_SHEET_TRANSLATION)
    full = re.search(r"(\d{4})[/-](\d{1,2})[/-](\d{1,2})", normalized)
    if full:
        month = int(full.group(2))
        day = int(full.group(3))
        return f"{month:02d}/{day:02d}"
    mmdd = re.search(r"(\d{1,2})[/-](\d{1,2})", normalized)
    if mmdd:
        month = int(mmdd.group(1))
        day = int(mmdd.group(2))
        return f"{month:02d}/{day:02d}"
    return ""


def _normalize_sheet_diet(value: object) -> str | None:
    token = _normalize_sheet_text(value).lower()
    if not token:
        return None
    if ("袋" in token or "bag" in token) and (
        "regular" in token or "常食" in token or "通常" in token or "常" in token
    ):
        return "regular_bag"
    if "regular" in token or "常食" in token or "通常" in token:
        return "regular"
    if "soft" in token or "軟菜" in token or "やわ" in token:
        return "soft"
    if "mixer" in token or "ミキサ" in token:
        return "mixer"
    if "daycare" in token or "通所" in token:
        return "daycare"
    if "staff" in token or "職員" in token:
        return "staff"
    if "nofried" in token or "揚げ物禁" in str(value or "") or "揚物禁" in str(value or ""):
        return "no_fried"
    if "tea" in token or "お茶" in token:
        return "tea"
    if "business" in token or "事業" in token:
        return "business"
    if "diabetes" in token or "糖尿" in token:
        return "diabetes"
    if "pregnancy" in token or "妊娠" in token:
        return "pregnancy"
    if ("ごま" in token or "ゴマ" in str(value or "") or "sesame" in token) and (
        "アレル" in str(value or "") or "allergy" in token
    ):
        return "sesame_allergy"
    if (
        ("肉" in token or "meat" in token)
        and ("卵" in token or "玉子" in token or "egg" in token)
        and ("魚" in token or "鯖" in token or "さば" in token or "fish" in token)
    ) or "肉卵魚禁" in str(value or ""):
        return "forbidden_other"
    if "nomeat" in token or ("禁" in token and "肉" in token):
        return "no_meat"
    if "nofish" in token or ("禁" in token and "魚" in token):
        return "no_fish"
    if "change1" in token or "変更1" in str(value or ""):
        return "change_1"
    if "change2" in token or "変更2" in str(value or ""):
        return "change_2"
    if token in {"-", "placeholder"}:
        return "placeholder"
    return token


def _normalize_sheet_area(value: object) -> str | None:
    token = _normalize_sheet_text(value).lower()
    if not token:
        return "X"
    if token in {"花", "hana"}:
        return "2F"
    if token in {"月", "tsuki"}:
        return "3F"
    if re.fullmatch(r"\d+", token):
        return f"{token}F"
    match = re.search(r"(\d)(?:f|階)", token)
    if match:
        return f"{match.group(1)}F"
    return token.upper()


def _quantity_meta_from_field(field: str) -> tuple[str | None, str | None]:
    token = _normalize_sheet_text(field).lower()
    raw_token = token
    if token.startswith("qty."):
        token = token[4:]
    token = token.replace(".", "_")
    # Quantity columns only. Avoid treating date/daypart/menu as quantity metadata.
    if not raw_token.startswith("qty.") and not re.search(
        r"(regular|常|soft|軟|mixer|ミキ|daycare|通所|staff|職員|nofried|揚|nomeat|nofish|禁)",
        token,
    ):
        return None, None
    area_match = re.search(r"(?:_|)(\d(?:f|階)|x)$", token)
    if not area_match:
        return None, None
    area_token = area_match.group(1)
    diet_token = token[: area_match.start(1)].rstrip("_")
    diet_lookup_token = diet_token or token
    if re.search(r"(?:^|_)no_?fish(?:_|$)", diet_lookup_token) or (
        "魚" in diet_lookup_token and "禁" in diet_lookup_token
    ):
        diet = "no_fish"
    elif re.search(r"(?:^|_)no_?meat(?:_|$)", diet_lookup_token) or (
        "肉" in diet_lookup_token and "禁" in diet_lookup_token
    ):
        diet = "no_meat"
    elif re.search(r"(?:^|_)no_?fried(?:_|$)", diet_lookup_token) or "揚" in diet_lookup_token:
        diet = "no_fried"
    elif re.search(r"(?:^|_)change_?1(?:_|$)", diet_lookup_token) or "変更1" in diet_lookup_token:
        diet = "change_1"
    elif re.search(r"(?:^|_)change_?2(?:_|$)", diet_lookup_token) or "変更2" in diet_lookup_token:
        diet = "change_2"
    elif re.search(r"(?:^|_)forbidden_?other(?:_|$)", diet_lookup_token):
        diet = "forbidden_other"
    else:
        diet = _normalize_sheet_diet(diet_lookup_token)
    area = _normalize_sheet_area(area_token)
    if not diet or not area:
        return None, None
    return diet, area


def _field_label(field: str) -> str:
    token = _normalize_sheet_text(field).lower()
    if token in {"date_mmdd", "date"} or token.startswith("date"):
        return "日付"
    if token in {"daypart", "meal", "time"}:
        return "区分"
    if token in {"menu", "menu_name"}:
        return "メニュー"
    if token in {"remarks", "note"}:
        return "備考"
    if token.startswith("post_menu."):
        column_letter = str(field or "").split(".", 1)[1].strip() if "." in str(field or "") else ""
        return f"空白列({column_letter})" if column_letter else "空白列"
    if token.startswith("aux."):
        return "補助列"
    diet, area = _quantity_meta_from_field(field)
    if diet and area:
        diet_label = {
            "regular": "常食",
            "regular_bag": "常食(袋分け)",
            "soft": "軟菜",
            "soft_mixer": "軟菜/ミキサー",
            "mixer": "ミキサー",
            "daycare": "通所",
            "staff": "職員",
            "no_fried": "禁食(揚げ物禁)",
            "no_meat": "禁食(肉禁)",
            "forbidden_other": "禁食(肉卵魚禁)",
            "no_fish": "禁食(魚禁)",
            "change_1": "変更1",
            "change_2": "変更2",
            "placeholder": "-",
            "unknown": "不明",
        }.get(diet, diet)
        if area == "X":
            return diet_label
        return f"{diet_label}{area}"
    return field




def _is_aux_sheet_field(field: object) -> bool:
    return str(field or "").strip().startswith("aux.")


def _is_sheet_note_field(field: object) -> bool:
    token = _normalize_sheet_text(field).lower()
    return token in {"remarks", "note"}


def _is_hakodate_spacer_sheet_field(field: object) -> bool:
    return _normalize_sheet_text(field).lower().startswith("post_menu.")


def _normalize_hakodate_sheet_field(field: object) -> str:
    token = str(field or "").strip()
    normalized_token = _normalize_sheet_text(token).lower()
    if normalized_token in {"qty.unknown_x", "unknown_x"}:
        return "qty.placeholder_x"
    if _normalize_sheet_text(token).lower() == "note":
        return "remarks"
    return token


def _sheet_header_from_template(
    fields: list[str],
    template: dict[str, Any] | None = None,
) -> list[str]:
    normalized_fields = [str(field).strip() for field in (fields or []) if str(field).strip()]
    if not normalized_fields:
        return []
    columns = template.get("columns") if isinstance(template, dict) else None
    if not isinstance(columns, list):
        return [_field_label(field) for field in normalized_fields]
    ordered = sorted(
        [col for col in columns if isinstance(col, dict)],
        key=lambda col: int(col.get("index") or 0),
    )
    header_by_field: dict[str, str] = {}
    for fallback_index, col in enumerate(ordered):
        field = fax_extractor._canonical_field_name_from_template_column(col, fallback_index=fallback_index)
        if not field or field in header_by_field:
            continue
        header = str(col.get("header") or "").strip()
        header_group = str(col.get("header_group") or "").strip()
        header_super_group = str(col.get("header_super_group") or "").strip()
        _diet, area = _quantity_meta_from_field(field)
        if header_group and header and area and area != "X":
            group_label = f"{header_super_group} {header_group}".strip() if header_super_group else header_group
            header_by_field[field] = f"{group_label}{header}"
        else:
            header_by_field[field] = header or header_group or header_super_group or _field_label(field)
    return [header_by_field.get(field, _field_label(field)) for field in normalized_fields]


def _row_fields_from_template(template: dict[str, Any]) -> list[str]:
    return fax_extractor._get_row_fields(template)


def _field_value_to_str(value: object) -> str:
    if value is None:
        return ""
    if isinstance(value, bool):
        return str(value)
    if isinstance(value, (int, float)):
        number = float(value)
        if number.is_integer():
            return str(int(number))
        return str(number)
    return str(value)


def _format_mmdd(value: object) -> str:
    parsed = _normalize_entry_date(value)
    if not parsed:
        return ""
    return f"{parsed.month:02d}/{parsed.day:02d}"


def _build_markdown_table_string(header: list[str], rows: list[list[str]]) -> str:
    normalized_header = [str(cell or "").strip() for cell in (header or [])]
    normalized_rows = [[_field_value_to_str(cell) for cell in row] for row in (rows or [])]
    if not normalized_header:
        width = max((len(row) for row in normalized_rows), default=0)
        normalized_header = [f"col{idx + 1}" for idx in range(max(width, 1))]
    padded_rows: list[list[str]] = []
    for row in normalized_rows:
        current = list(row[: len(normalized_header)])
        if len(current) < len(normalized_header):
            current.extend([""] * (len(normalized_header) - len(current)))
        padded_rows.append(current)
    header_line = f"| {' | '.join(normalized_header)} |"
    separator = f"| {' | '.join(['---'] * len(normalized_header))} |"
    body = [f"| {' | '.join(row)} |" for row in padded_rows]
    return "\\n".join([header_line, separator, *body])


def _is_llm_full_table_quantity_field(field: object) -> bool:
    token = str(field or "").strip()
    return bool(token.startswith("qty."))


def _is_llm_full_table_ignored_shell_field(field: object) -> bool:
    token = _normalize_sheet_text(field).lower()
    return token in {"remarks", "note"}


def _is_llm_full_table_mergeable_display_field(field: object) -> bool:
    return _is_aux_sheet_field(field)


def _is_llm_full_table_structural_anchor_field(field: object) -> bool:
    if (
        _is_llm_full_table_quantity_field(field)
        or _is_llm_full_table_ignored_shell_field(field)
        or _is_llm_full_table_mergeable_display_field(field)
    ):
        return False
    token = _normalize_sheet_text(field).lower()
    if token in {"date_mmdd", "date", "daypart", "menu", "menu_name"}:
        return True
    return bool(token)


def _validate_and_merge_reparse_full_table_candidate(
    *,
    baseline: dict[str, Any] | None,
    candidate_rows: object,
    candidate_returned_row_indexes: list[int] | None = None,
    candidate_returned_field_map: dict[int, set[str]] | None = None,
    authoritative_quantity_rows: list[list[str]] | None = None,
) -> tuple[list[list[str]], dict[str, Any]]:
    fields, header, baseline_rows, row_ids, baseline_source = _resolve_reparse_current_sheet_baseline_rows(baseline)
    if not fields or not baseline_rows:
        return [], {
            "error": "llm_full_table_baseline_missing",
            "detail": {
                "reason": "current_sheet_baseline_missing",
            },
        }

    normalized_baseline_rows = _sanitize_revision_rows(rows_payload=baseline_rows, fields=fields)
    normalized_baseline_rows, baseline_helper_stats = _canonicalize_block_helper_display_rows(
        rows=normalized_baseline_rows,
        fields=fields,
        header=header,
    )
    normalized_candidate_rows = _sanitize_revision_rows(rows_payload=candidate_rows, fields=fields)
    normalized_candidate_rows, candidate_helper_stats = _canonicalize_block_helper_display_rows(
        rows=normalized_candidate_rows,
        fields=fields,
        header=header,
    )
    detail: dict[str, Any] = {
        "baseline_source": baseline_source,
        "field_count": len(fields),
        "row_count_expected": len(normalized_baseline_rows),
        "row_count_actual": len(normalized_candidate_rows),
        "fields": list(fields),
        "header": list(header),
        "baseline_helper_reanchor_count": int((baseline_helper_stats or {}).get("helper_reanchor_count") or 0),
        "candidate_helper_reanchor_count": int((candidate_helper_stats or {}).get("helper_reanchor_count") or 0),
    }
    returned_row_index_set: set[int] | None = None
    if isinstance(candidate_returned_row_indexes, list):
        returned_row_index_set = set()
        for item in candidate_returned_row_indexes:
            try:
                row_index = int(item)
            except Exception:
                continue
            if 0 <= row_index < len(normalized_baseline_rows):
                returned_row_index_set.add(row_index)
        if returned_row_index_set:
            detail["returned_row_index_count"] = len(returned_row_index_set)
            detail["returned_row_indexes"] = sorted(returned_row_index_set)
    normalized_returned_field_map: dict[int, set[str]] = {}
    if isinstance(candidate_returned_field_map, dict):
        for row_index, fields_for_row in candidate_returned_field_map.items():
            try:
                normalized_row_index = int(row_index)
            except Exception:
                continue
            if normalized_row_index < 0 or normalized_row_index >= len(normalized_baseline_rows):
                continue
            if isinstance(fields_for_row, set):
                normalized_fields = {
                    str(field or "").strip()
                    for field in fields_for_row
                    if str(field or "").strip()
                }
            elif isinstance(fields_for_row, list):
                normalized_fields = {
                    str(field or "").strip()
                    for field in fields_for_row
                    if str(field or "").strip()
                }
            else:
                continue
            if normalized_fields:
                normalized_returned_field_map[normalized_row_index] = normalized_fields
    if normalized_returned_field_map:
        detail["returned_row_field_count"] = sum(len(item) for item in normalized_returned_field_map.values())
        detail["returned_row_fields"] = {
            str(idx): sorted(values)
            for idx, values in sorted(normalized_returned_field_map.items())
        }
    if len(normalized_candidate_rows) != len(normalized_baseline_rows):
        return [], {
            "error": "llm_full_table_row_count_mismatch",
            "detail": {
                **detail,
                "row_ids": row_ids,
            },
        }

    helper_conflicts = list((candidate_helper_stats or {}).get("helper_conflicts") or [])
    if helper_conflicts:
        return [], {
            "error": "llm_full_table_helper_column_conflict",
            "detail": {
                **detail,
                "helper_conflict_count": len(helper_conflicts),
                "helper_conflicts": helper_conflicts[:20],
            },
        }

    merged_rows = [list(row) for row in normalized_baseline_rows]
    quantity_changes: list[dict[str, Any]] = []
    display_changes: list[dict[str, Any]] = []
    invalid_quantities: list[dict[str, Any]] = []
    structural_drift: list[dict[str, Any]] = []
    ignored_shell_drift: list[dict[str, Any]] = []
    quantity_field_indexes = {
        idx
        for idx, field in enumerate(fields)
        if _is_llm_full_table_quantity_field(field)
    }
    mergeable_display_field_indexes = {
        idx
        for idx, field in enumerate(fields)
        if _is_llm_full_table_mergeable_display_field(field)
    }
    preserved_display_field_indexes = {
        idx
        for idx, semantic in _resolve_helper_column_semantics(fields=fields, header=header).items()
        if semantic in {"slot_label", "block_total"}
    }
    authoritative_quantity_requested = authoritative_quantity_rows is not None
    normalized_authoritative_quantity_rows: list[list[str]] = []
    authoritative_quantity_resets: list[dict[str, Any]] = []
    if isinstance(authoritative_quantity_rows, list):
        normalized_authoritative_quantity_rows = _sanitize_revision_rows(
            rows_payload=authoritative_quantity_rows,
            fields=fields,
        )
        if len(normalized_authoritative_quantity_rows) != len(normalized_baseline_rows):
            return [], {"error": "sheet_canonical_mismatch", "detail": detail}
    if authoritative_quantity_requested:
        for row_index in range(len(normalized_baseline_rows)):
            authoritative_row = (
                normalized_authoritative_quantity_rows[row_index]
                if row_index < len(normalized_authoritative_quantity_rows)
                else []
            )
            baseline_row = normalized_baseline_rows[row_index] if row_index < len(normalized_baseline_rows) else [""] * len(fields)
            row_id = row_ids[row_index] if row_index < len(row_ids) else f"sheet-row-{row_index + 1}"
            for col_index in quantity_field_indexes:
                authoritative_value = authoritative_row[col_index] if col_index < len(authoritative_row) else ""
                baseline_value = baseline_row[col_index] if col_index < len(baseline_row) else ""
                merged_rows[row_index][col_index] = authoritative_value
                if baseline_value != authoritative_value:
                    authoritative_quantity_resets.append(
                        {
                            "row_index": row_index,
                            "row_id": row_id,
                            "field": fields[col_index],
                            "old_text": baseline_value,
                            "new_text": authoritative_value,
                        }
                    )

    for row_index, candidate_row in enumerate(normalized_candidate_rows):
        if returned_row_index_set is not None and row_index not in returned_row_index_set:
            continue
        returned_fields_for_row = normalized_returned_field_map.get(row_index)
        baseline_row = normalized_baseline_rows[row_index] if row_index < len(normalized_baseline_rows) else [""] * len(fields)
        row_id = row_ids[row_index] if row_index < len(row_ids) else f"sheet-row-{row_index + 1}"
        for col_index, field in enumerate(fields):
            if returned_fields_for_row is not None and field not in returned_fields_for_row:
                continue
            baseline_value = baseline_row[col_index] if col_index < len(baseline_row) else ""
            candidate_value = candidate_row[col_index] if col_index < len(candidate_row) else ""
            if col_index in quantity_field_indexes:
                if candidate_value and not re.fullmatch(r"\d+", str(candidate_value)):
                    invalid_quantities.append(
                        {
                            "row_index": row_index,
                            "row_id": row_id,
                            "field": field,
                            "old_text": baseline_value,
                            "new_text": candidate_value,
                        }
                    )
                    continue
                merged_rows[row_index][col_index] = candidate_value
                if baseline_value != candidate_value:
                    quantity_changes.append(
                        {
                            "row_index": row_index,
                            "row_id": row_id,
                            "field": field,
                            "old_text": baseline_value,
                            "new_text": candidate_value,
                        }
                    )
                continue
            if col_index in mergeable_display_field_indexes:
                if col_index in preserved_display_field_indexes and baseline_value:
                    if baseline_value != candidate_value:
                        ignored_shell_drift.append(
                            {
                                "row_index": row_index,
                                "row_id": row_id,
                                "field": field,
                                "old_text": baseline_value,
                                "new_text": candidate_value,
                            }
                        )
                    continue
                merged_rows[row_index][col_index] = candidate_value
                if baseline_value != candidate_value:
                    display_changes.append(
                        {
                            "row_index": row_index,
                            "row_id": row_id,
                            "field": field,
                            "old_text": baseline_value,
                            "new_text": candidate_value,
                        }
                    )
                continue
            if baseline_value != candidate_value:
                drift_record = {
                    "row_index": row_index,
                    "row_id": row_id,
                    "field": field,
                    "old_text": baseline_value,
                    "new_text": candidate_value,
                }
                if _is_llm_full_table_ignored_shell_field(field):
                    ignored_shell_drift.append(drift_record)
                    continue
                structural_drift.append(
                    {
                        **drift_record,
                        "field_class": "structural_anchor" if _is_llm_full_table_structural_anchor_field(field) else "non_quantity",
                    }
                )

    if authoritative_quantity_requested:
        quantity_issues = _canonical_quantity_cell_issues(merged_rows, fields)
        if quantity_issues:
            return [], {
                "error": "sheet_ocr_review_required",
                "detail": {**detail, "cell_issues": quantity_issues},
            }
    if invalid_quantities:
        return [], {
            "error": "llm_full_table_invalid_quantity_text",
            "detail": {
                **detail,
                "invalid_quantity_count": len(invalid_quantities),
                "invalid_quantity_cells": invalid_quantities[:20],
            },
        }
    if structural_drift:
        return [], {
            "error": "llm_full_table_structural_drift",
            "detail": {
                **detail,
                "structural_drift_count": len(structural_drift),
                "structural_drift_cells": structural_drift[:20],
                "ignored_shell_drift_count": len(ignored_shell_drift),
                "ignored_shell_drift_cells": ignored_shell_drift[:20],
            },
        }

    return merged_rows, {
        "error": None,
        "detail": {
            **detail,
            "quantity_change_count": len(quantity_changes),
            "quantity_changes": quantity_changes[:40],
            "display_change_count": len(display_changes),
            "display_changes": display_changes[:40],
            "authoritative_quantity_reset_count": len(authoritative_quantity_resets),
            "authoritative_quantity_resets": authoritative_quantity_resets[:40],
            "ignored_shell_drift_count": len(ignored_shell_drift),
            "ignored_shell_drift_cells": ignored_shell_drift[:20],
        },
    }


def _build_reparse_authoritative_quantity_baseline_rows(
    *,
    baseline: dict[str, Any] | None,
    template: dict[str, Any] | None,
) -> tuple[list[list[str]], dict[str, int]]:
    if not isinstance(baseline, dict) or not isinstance(template, dict):
        return [], {}
    raw_output = baseline.get("raw_output")
    if not isinstance(raw_output, dict):
        return [], {}
    fields, _header, baseline_rows, _row_ids, _source = _resolve_reparse_current_sheet_baseline_rows(baseline)
    if not fields or not baseline_rows:
        return [], {}
    payload_rows = _extract_sheet_rows_from_payload_uncanonicalized(raw_output, template)
    if not payload_rows:
        return [], {}
    projected_rows, projection_stats = _project_payload_quantities_onto_sheet_row_lists(
        rows=baseline_rows,
        fields=fields,
        payload_rows=payload_rows,
        explicit_quantity_pairs=_resolved_quantity_source_target_pairs(raw_output, fields, template),
        strict_raw_ocr_only=True,
        template=template,
    )
    if projection_stats.get("unmapped"):
        raise _CanonicalOcrProjectionError("sheet_quantity_column_unmapped")
    if not any(int(value or 0) > 0 for value in projection_stats.values()):
        return [], projection_stats
    return projected_rows, projection_stats


_RAW_OCR_SNAPSHOT_KEYS = [
    "engine",
    "provider",
    "template_id",
    "facility_id",
    "table_raw",
    "rows",
    "pages",
    "tables",
    "cell_issues",
    "yomitoku_cell_issues",
    "roi_cell_issues",
    "roi_extraction",
    "roi_overlay_rows",
    "roi_overlay_policy",
    "warnings",
    "failed_cells",
    "combined",
    "classification",
    "classification_confidence",
    "metrics",
]


def _snapshot_raw_ocr_payload(payload: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(payload, dict):
        return {}
    snapshot: dict[str, Any] = {}
    for key in _RAW_OCR_SNAPSHOT_KEYS:
        if key in payload:
            snapshot[key] = payload.get(key)
    return snapshot


def _restore_payload_raw_ocr_surface(
    payload: dict[str, Any] | None,
    *,
    strip_legacy_surface: bool = False,
) -> dict[str, Any] | None:
    if not isinstance(payload, dict):
        return payload
    edited = payload.get("_edited_ocr")
    if not isinstance(edited, dict):
        if not strip_legacy_surface:
            return payload
        cleaned = dict(payload)
        changed = False
        if "edited_table" in cleaned:
            cleaned.pop("edited_table", None)
            changed = True
        if str(cleaned.get("ocr_source") or "").strip().lower() == "edited":
            cleaned.pop("ocr_source", None)
            changed = True
        return cleaned if changed else payload

    latest = _select_edited_sheet_revision(payload)
    latest_markdown = (
        _normalize_table_raw_text(str(latest.get("markdown") or "")).strip()
        if isinstance(latest, dict)
        else ""
    )
    current_table_raw = _normalize_table_raw_text(str(payload.get("table_raw") or "")).strip()
    surface_looks_edited = False
    if latest_markdown and current_table_raw and current_table_raw == latest_markdown:
        surface_looks_edited = True
    if str(payload.get("ocr_source") or "").strip().lower() == "edited":
        surface_looks_edited = True

    raw_output = edited.get("raw_output") if latest is not None else None
    restored = dict(payload)
    changed = False

    if isinstance(raw_output, dict) and raw_output:
        raw_snapshot = _snapshot_raw_ocr_payload(raw_output)
        if raw_snapshot:
            for key in _RAW_OCR_SNAPSHOT_KEYS:
                if key in raw_snapshot:
                    raw_value = raw_snapshot.get(key)
                    if restored.get(key) != raw_value:
                        restored[key] = raw_value
                        changed = True
                elif surface_looks_edited and key in restored:
                    restored.pop(key, None)
                    changed = True
    elif surface_looks_edited or strip_legacy_surface:
        for key in (
            "table_raw",
            "_table_raw_blocks",
            "_table_raw_non_table_lines",
            "_table_raw_original_chars",
            "_table_raw_unstructured_qty",
            "table_raw_truncated",
        ):
            if key in restored:
                restored.pop(key, None)
                changed = True

    if strip_legacy_surface or surface_looks_edited:
        if "edited_table" in restored:
            restored.pop("edited_table", None)
            changed = True
    if strip_legacy_surface and str(restored.get("ocr_source") or "").strip().lower() == "edited":
        restored.pop("ocr_source", None)
        changed = True

    return restored if changed else payload


