def _review_reason_message(code: object) -> str:
    normalized = str(code or "").strip()
    if not normalized:
        return ""
    return _REVIEW_REASON_MESSAGES.get(normalized, normalized.replace("_", " "))


def _review_reason_details(codes: list[str] | None, *, severity: str) -> list[dict[str, str]]:
    details: list[dict[str, str]] = []
    seen: set[str] = set()
    for code in codes or []:
        normalized = str(code or "").strip()
        if not normalized or normalized in seen:
            continue
        seen.add(normalized)
        details.append(
            {
                "code": normalized,
                "message": _review_reason_message(normalized),
                "severity": severity,
            }
        )
    return details


def _sheet_projection_status_payload(
    *,
    source: str,
    warnings: list[str],
    payload_mapping_block_reason: str | None,
    payload_rows_present: bool,
) -> dict[str, Any]:
    normalized_source = str(source or "").strip()
    normalized_reason = str(payload_mapping_block_reason or "").strip()
    warning_tokens = [str(item).strip() for item in (warnings or []) if str(item).strip()]
    if normalized_source.endswith("+ocr_payload"):
        return {
            "status": "applied",
            "reason_code": None,
            "reason_message": "",
        }
    if normalized_reason == "unresolved_template" or "sheet_payload_mapping_blocked_unresolved_template" in warning_tokens:
        return {
            "status": "blocked",
            "reason_code": "sheet_payload_mapping_blocked_unresolved_template",
            "reason_message": _review_reason_message("sheet_payload_mapping_blocked_unresolved_template"),
        }
    if normalized_reason == "numeric_review_required" or "sheet_payload_mapping_low_confidence" in warning_tokens:
        return {
            "status": "review_required",
            "reason_code": "sheet_payload_mapping_low_confidence",
            "reason_message": _review_reason_message("sheet_payload_mapping_low_confidence"),
        }
    if payload_rows_present and normalized_source == "weekly_menu":
        return {
            "status": "not_applied",
            "reason_code": "sheet_payload_not_projected",
            "reason_message": "OCR数量は取得できていますが、シートへの投影条件を満たさなかったため週次メニューの枠だけを表示しています。",
        }
    return {
        "status": "none",
        "reason_code": None,
        "reason_message": "",
    }


def _derive_reparse_status(
    *,
    order_id: str,
    ocr_status: str | None,
    has_saved_draft: bool,
    auto_apply_blocked: bool,
    last_reparse_error: str,
) -> str:
    normalized = str(ocr_status or "").strip().lower()
    if normalized in {"running", "pending", "stalled", "awaiting_output", "recovering"}:
        return "running"
    if auto_apply_blocked and has_saved_draft:
        return "blocked"
    if has_saved_draft:
        return "draft_ready"
    if normalized in {"failed", "error"} or last_reparse_error:
        return "failed"
    return "idle"


def _derive_review_stage(
    *,
    order_status: str | None,
    normalized_ocr_status: str,
    has_saved_draft: bool,
    draft_newer_than_lines: bool,
    auto_apply_blocked: bool,
    reparse_status: str,
    needs_human_review: bool,
) -> str:
    if reparse_status == "running" or normalized_ocr_status in {"running", "pending", "awaiting_output", "recovering"}:
        return "parsing"
    if needs_human_review:
        return "needs_human_review"
    if has_saved_draft and not draft_newer_than_lines and not auto_apply_blocked:
        return "drafting"
    if has_saved_draft or auto_apply_blocked or normalized_ocr_status in {"failed", "stalled"}:
        return "needs_human_review"
    if str(order_status or "").strip() == "確定":
        return "confirmed"
    if normalized_ocr_status in {"done", "success"}:
        return "confirmed"
    return "idle"


def get_order_review_summary(
    order_id: str,
    *,
    lines_updated_at: datetime | None = None,
    ocr_status: str | None = None,
    cached_payload: dict[str, Any] | None = None,
    ocr_metrics: dict[str, Any] | None = None,
    order_status: str | None = None,
    current_sheet_context: dict[str, Any] | None = None,
    sheet_gate: dict[str, Any] | None = None,
    current_sheet_context_supplied: bool = False,
) -> dict[str, Any]:
    payload = cached_payload if isinstance(cached_payload, dict) else _load_order_ocr_cache(order_id)
    draft_state = _extract_order_draft_state(order_id, payload, lines_updated_at=lines_updated_at)
    revision_count = 0
    revision_last_id = str(draft_state.get("draft_revision_id") or "").strip() or None
    edited = payload.get("_edited_ocr") if isinstance(payload, dict) else None
    cached_revisions = edited.get("revisions") if isinstance(edited, dict) else None
    if isinstance(cached_revisions, list):
        revision_count = len([item for item in cached_revisions if isinstance(item, dict)])
    try:
        persisted_revision_summary = ocr_revision_store.get_revision_summary(order_id)
    except Exception as exc:  # noqa: BLE001
        logger.warning("Persisted OCR revision summary lookup failed", order_id=order_id, error=str(exc))
        persisted_revision_summary = {}
    if isinstance(persisted_revision_summary, dict):
        persisted_count = int(persisted_revision_summary.get("count") or 0)
        if persisted_count > 0:
            revision_count = persisted_count
            revision_last_id = str(persisted_revision_summary.get("last_revision_id") or "").strip() or None
    normalized_ocr_status = str(ocr_status or "").strip().lower()
    metrics = ocr_metrics if isinstance(ocr_metrics, dict) else {}
    latest_revision = draft_state.get("latest_revision") if isinstance(draft_state.get("latest_revision"), dict) else None
    latest_rows = latest_revision.get("rows") if isinstance(latest_revision, dict) else None
    latest_draft_payload = (
        draft_state.get("latest_draft_payload")
        if isinstance(draft_state.get("latest_draft_payload"), dict)
        else None
    )
    latest_draft_rows = latest_draft_payload.get("rows") if isinstance(latest_draft_payload, dict) else None
    draft_row_count = (
        len(latest_rows)
        if isinstance(latest_rows, list) and latest_rows
        else len(latest_draft_rows)
        if isinstance(latest_draft_rows, list)
        else 0
    )
    apply_blockers: list[str] = []
    if draft_state["has_saved_draft"] and draft_row_count <= 0:
        apply_blockers.append("draft_rows_empty")
    confirm_blockers: list[str] = []
    confirm_warnings: list[str] = []
    if draft_state["draft_newer_than_lines"]:
        confirm_warnings.append("draft_newer_than_lines")
    if draft_state["auto_apply_blocked"]:
        confirm_warnings.append("auto_apply_blocked")
    reparse_debug = payload.get("_reparse_debug") if isinstance(payload, dict) else None
    last_reparse_error = (
        str(reparse_debug.get("error") or "").strip()
        if isinstance(reparse_debug, dict)
        else ""
    )
    if not last_reparse_error:
        last_reparse_error = str(metrics.get("error") or "").strip()
    processing_stage = str(metrics.get("processing_stage") or "").strip().lower() or None
    result_state = str(metrics.get("result_state") or "").strip().lower() or None
    confirmed_lines_retained = bool(metrics.get("confirmed_lines_retained"))
    if not result_state:
        if draft_state["has_saved_draft"] and draft_state["auto_apply_blocked"]:
            result_state = "draft_ready_blocked"
        elif normalized_ocr_status in {"failed", "empty", "stalled"}:
            result_state = "hard_failed"
        elif normalized_ocr_status in {"done", "success"} and lines_updated_at:
            result_state = "applied"
        elif normalized_ocr_status in {"running", "pending", "awaiting_output", "recovering"}:
            result_state = "processing"
    reparse_status = _derive_reparse_status(
        order_id=order_id,
        ocr_status=ocr_status,
        has_saved_draft=bool(draft_state["has_saved_draft"]),
        auto_apply_blocked=bool(draft_state["auto_apply_blocked"]),
        last_reparse_error=last_reparse_error,
    )
    can_apply_draft = bool(draft_state["has_saved_draft"]) and not apply_blockers
    can_confirm = not confirm_blockers
    review_state = "none"
    review_badges: list[str] = []
    if draft_state["has_saved_draft"]:
        review_state = (
            "draft_ready"
            if draft_state["auto_apply_blocked"] or draft_state["draft_newer_than_lines"]
            else "draft_saved"
        )
        review_badges.append("下書きあり")
        if draft_state["auto_apply_blocked"]:
            review_badges.append("自動反映保留")
        if draft_state["draft_newer_than_lines"]:
            review_badges.append("下書き未反映")
        if confirmed_lines_retained:
            review_badges.append("確定明細保持")
    elif normalized_ocr_status in {"failed", "stalled"}:
        review_state = "processing_failed"
        review_badges.append("OCR失敗")
    elif normalized_ocr_status in {"running", "pending", "awaiting_output", "recovering"}:
        review_state = "processing"
    if processing_stage and normalized_ocr_status in {"running", "pending", "awaiting_output", "recovering"}:
        review_badges.append(f"処理:{processing_stage}")
    review_stage = _derive_review_stage(
        order_status=order_status,
        normalized_ocr_status=normalized_ocr_status,
        has_saved_draft=bool(draft_state["has_saved_draft"]),
        draft_newer_than_lines=bool(draft_state["draft_newer_than_lines"]),
        auto_apply_blocked=bool(draft_state["auto_apply_blocked"]),
        reparse_status=reparse_status,
        needs_human_review=bool(apply_blockers or confirm_blockers or confirm_warnings),
    )
    apply_blocker_details = _review_reason_details(apply_blockers, severity="blocker")
    confirm_blocker_details = _review_reason_details(confirm_blockers, severity="blocker")
    confirm_warning_details = _review_reason_details(confirm_warnings, severity="warning")
    summary = {
        "current_sheet_revision_id": (
            str((current_sheet_context or {}).get("current_sheet_revision_id") or "").strip()
            or (None if current_sheet_context_supplied else _current_sheet_revision_id(order_id=order_id, payload=payload))
        ),
        "ocr_review_state": review_state,
        "ocr_review_stage": review_stage,
        "ocr_review_badges": review_badges,
        "ocr_has_saved_draft": draft_state["has_saved_draft"],
        "ocr_draft_updated_at": draft_state["draft_updated_at"],
        "ocr_draft_revision_id": draft_state["draft_revision_id"],
        "ocr_draft_row_count": draft_row_count,
        "ocr_draft_newer_than_lines": draft_state["draft_newer_than_lines"],
        "ocr_auto_apply_blocked": draft_state["auto_apply_blocked"],
        "ocr_reject_reasons": draft_state["reject_reasons"],
        "ocr_last_reparse_error": last_reparse_error or None,
        "ocr_reparse_status": reparse_status,
        "ocr_reparse_last_error_code": last_reparse_error or None,
        "ocr_can_apply_draft": can_apply_draft,
        "ocr_apply_blockers": apply_blockers,
        "ocr_apply_blocker_details": apply_blocker_details,
        "ocr_can_confirm": can_confirm,
        "ocr_confirm_blockers": confirm_blockers,
        "ocr_confirm_warnings": confirm_warnings,
        "ocr_confirm_blocker_details": confirm_blocker_details,
        "ocr_confirm_warning_details": confirm_warning_details,
        "ocr_processing_stage": processing_stage,
        "ocr_result_state": result_state,
        "ocr_confirmed_lines_retained": confirmed_lines_retained,
        "ocr_revision_count": revision_count,
        "ocr_revision_last_id": revision_last_id,
    }
    return _merge_order_review_summary_with_sheet_context(
        summary,
        order_status=order_status,
        ocr_status=ocr_status,
        current_sheet_context=current_sheet_context,
        sheet_gate=sheet_gate,
    )


def _merge_order_review_summary_with_sheet_context(
    summary: dict[str, Any],
    *,
    order_status: str | None = None,
    ocr_status: str | None = None,
    current_sheet_context: dict[str, Any] | None = None,
    sheet_gate: dict[str, Any] | None = None,
) -> dict[str, Any]:
    context = current_sheet_context if isinstance(current_sheet_context, dict) else {}
    gate = sheet_gate if isinstance(sheet_gate, dict) else {}
    if not context and not gate:
        return summary

    merged = dict(summary)
    order_has_no_applied_lines = context.get("order_payload", {}).get("lines_updated_at") is None if isinstance(context.get("order_payload"), dict) else False
    draft_record = context.get("draft_record") if isinstance(context.get("draft_record"), dict) else None
    resolved_rows = context.get("rows") if isinstance(context.get("rows"), list) else None
    if isinstance(resolved_rows, list):
        merged["ocr_draft_row_count"] = len(resolved_rows)
    if isinstance(draft_record, dict):
        edited_at = draft_record.get("edited_at")
        if edited_at:
            merged["ocr_draft_updated_at"] = edited_at
        draft_id = str(draft_record.get("id") or "").strip()
        if draft_id:
            merged["ocr_draft_revision_id"] = draft_id
    current_sheet_revision_id = str(context.get("current_sheet_revision_id") or "").strip()
    if current_sheet_revision_id:
        merged["current_sheet_revision_id"] = current_sheet_revision_id
    else:
        merged.pop("current_sheet_revision_id", None)
    apply_blockers = _dedupe_str_tokens(
        list(merged.get("ocr_apply_blockers") or [])
        + list(gate.get("apply_blockers") or [])
        + list(context.get("blockers") or [])
    )
    confirm_blockers = _dedupe_str_tokens(
        list(merged.get("ocr_confirm_blockers") or [])
        + list(gate.get("confirm_blockers") or [])
        + list(context.get("blockers") or [])
    )
    confirm_warnings = _dedupe_str_tokens(
        list(merged.get("ocr_confirm_warnings") or [])
        + list(gate.get("confirm_warnings") or [])
    )

    has_saved_draft = bool(merged.get("ocr_has_saved_draft"))
    draft_newer_than_lines = bool(merged.get("ocr_draft_newer_than_lines"))
    auto_apply_blocked = bool(merged.get("ocr_auto_apply_blocked"))
    context_has_pending_draft = bool(context.get("has_persisted_draft")) and (
        draft_newer_than_lines or auto_apply_blocked or order_has_no_applied_lines
    )
    if context_has_pending_draft:
        has_saved_draft = True
        merged["ocr_has_saved_draft"] = True
    normalized_ocr_status = str(ocr_status or "").strip().lower()
    reparse_status = str(merged.get("ocr_reparse_status") or "").strip()
    needs_human_review = bool(apply_blockers or confirm_blockers or confirm_warnings)

    review_state = str(merged.get("ocr_review_state") or "").strip() or "none"
    if has_saved_draft:
        if auto_apply_blocked or draft_newer_than_lines or needs_human_review:
            review_state = "draft_ready"
        else:
            review_state = "draft_saved"
    elif needs_human_review:
        review_state = "review_required"
    elif normalized_ocr_status in {"failed", "stalled"}:
        review_state = "processing_failed"
    elif normalized_ocr_status in {"running", "pending", "awaiting_output", "recovering"}:
        review_state = "processing"

    review_stage = _derive_review_stage(
        order_status=order_status,
        normalized_ocr_status=normalized_ocr_status,
        has_saved_draft=has_saved_draft,
        draft_newer_than_lines=draft_newer_than_lines,
        auto_apply_blocked=auto_apply_blocked,
        reparse_status=reparse_status,
        needs_human_review=needs_human_review,
    )
    if review_state == "review_required":
        review_stage = "needs_human_review"

    merged.update(
        {
            "ocr_review_state": review_state,
            "ocr_review_stage": review_stage,
            "ocr_can_apply_draft": has_saved_draft and not apply_blockers,
            "ocr_apply_blockers": apply_blockers,
            "ocr_apply_blocker_details": _review_reason_details(apply_blockers, severity="blocker"),
            "ocr_can_confirm": not confirm_blockers,
            "ocr_confirm_blockers": confirm_blockers,
            "ocr_confirm_warnings": confirm_warnings,
            "ocr_confirm_blocker_details": _review_reason_details(confirm_blockers, severity="blocker"),
            "ocr_confirm_warning_details": _review_reason_details(confirm_warnings, severity="warning"),
        }
    )
    if not merged.get("ocr_result_state") and has_saved_draft and needs_human_review:
        merged["ocr_result_state"] = "draft_ready_blocked"
    return merged


def _augment_sheet_review_payload(
    *,
    order_id: str,
    payload: dict[str, Any],
    lines_updated_at: datetime | None = None,
    ocr_payload: dict[str, Any] | None = None,
    ocr_metrics: dict[str, Any] | None = None,
    draft_sheet: dict[str, Any] | None = None,
    position_fallback_semantics_ready: bool = False,
) -> dict[str, Any]:
    enriched = dict(payload)
    current_sheet_revision_id = (
        _current_sheet_revision_id_from_payload(payload)
        or _current_sheet_revision_id(order_id=order_id, payload=ocr_payload)
        or _current_sheet_revision_id(order_id=order_id, payload=payload)
    )
    if current_sheet_revision_id:
        enriched["current_sheet_revision_id"] = current_sheet_revision_id
    warnings = [
        str(item).strip()
        for item in (payload.get("warnings") or [])
        if str(item).strip()
    ]
    rows = payload.get("rows") if isinstance(payload.get("rows"), list) else []
    source = str(payload.get("source") or "").strip()
    clean_saved_draft = apply_gate_service.has_clean_saved_draft(draft_sheet)
    authoritative_apply_gate = (
        dict(payload.get("apply_gate"))
        if isinstance(payload.get("apply_gate"), dict)
        else None
    )
    authoritative_workflow_state = (
        dict(payload.get("workflow_state"))
        if isinstance(payload.get("workflow_state"), dict)
        else None
    )
    authoritative_sheet_projection = bool(authoritative_apply_gate and authoritative_workflow_state)
    if authoritative_sheet_projection:
        deduped_warnings: list[str] = []
        for item in warnings:
            if item not in deduped_warnings:
                deduped_warnings.append(item)
        warnings = deduped_warnings
    else:
        warnings = apply_gate_service.filter_stale_issue_tokens(
            warnings,
            source=source,
            clean_saved_draft=clean_saved_draft,
            position_fallback_semantics_ready=position_fallback_semantics_ready,
        )
    enriched["warnings"] = list(warnings)
    draft_state = _extract_order_draft_state(order_id, ocr_payload, lines_updated_at=lines_updated_at)
    job = get_latest_order_job(order_id)
    menu_diagnostics = (
        dict(payload.get("menu_diagnostics") or {})
        if isinstance(payload.get("menu_diagnostics"), dict)
        else {}
    )
    menu_blockers = [
        str(item).strip()
        for item in (menu_diagnostics.get("order_codes") or [])
        if str(item).strip()
    ]
    has_semantic_fields = bool(payload.get("fields")) and not _draft_fields_look_generic(payload.get("fields"))
    if authoritative_sheet_projection:
        sheet_gate = authoritative_apply_gate or {}
        apply_blockers = [
            str(item).strip()
            for item in (
                list(sheet_gate.get("apply_blockers") or [])
                or list(sheet_gate.get("blockers") or [])
            )
            if str(item).strip()
        ]
        confirm_blockers = [
            str(item).strip()
            for item in (
                list(sheet_gate.get("confirm_blockers") or [])
                or list(sheet_gate.get("blockers") or [])
            )
            if str(item).strip()
        ]
        confirm_warnings = [
            str(item).strip()
            for item in (
                list(sheet_gate.get("confirm_warnings") or [])
                or list(sheet_gate.get("warnings") or [])
            )
            if str(item).strip()
        ]
        can_apply = bool(sheet_gate.get("can_apply"))
        can_confirm = bool(sheet_gate.get("can_confirm"))
    else:
        sheet_gate = apply_gate_service.evaluate_sheet_gate(
            rows=rows if isinstance(rows, list) else None,
            source=source,
            has_semantic_fields=has_semantic_fields,
            blockers=menu_blockers,
            warnings=warnings,
            draft_newer_than_lines=bool(draft_state["draft_newer_than_lines"]),
            auto_apply_blocked=bool(draft_state["auto_apply_blocked"]),
            reparse_status=(describe_ocr_job_state(job).get("status") if isinstance(job, dict) else None),
            clean_saved_draft=clean_saved_draft,
            position_fallback_semantics_ready=position_fallback_semantics_ready,
        )
        apply_blockers = list(sheet_gate.get("apply_blockers") or [])
        confirm_blockers = list(sheet_gate.get("confirm_blockers") or [])
        confirm_warnings = list(sheet_gate.get("confirm_warnings") or [])
        can_apply = apply_gate_service.gate_can_apply(
            apply_blockers=apply_blockers,
            confirm_warnings=confirm_warnings,
        )
        can_confirm = apply_gate_service.gate_can_confirm(
            confirm_blockers=confirm_blockers,
            confirm_warnings=confirm_warnings,
        )
    processing_stage = (
        str((ocr_metrics or {}).get("processing_stage") or "").strip().lower()
        if isinstance(ocr_metrics, dict)
        else ""
    )
    result_state = (
        str((ocr_metrics or {}).get("result_state") or "").strip().lower()
        if isinstance(ocr_metrics, dict)
        else ""
    )
    confirmed_lines_retained = bool((ocr_metrics or {}).get("confirmed_lines_retained")) if isinstance(ocr_metrics, dict) else False
    confirmed_line_count = 0
    try:
        with session_scope() as session:
            confirmed_line_count = int(
                session.execute(
                    select(func.count(OrderLine.id)).where(OrderLine.order_id == order_id)
                ).scalar_one()
                or 0
            )
    except Exception as exc:  # noqa: BLE001
        logger.warning("Failed to count confirmed order lines", order_id=order_id, error=str(exc))
    draft_line_count = len(rows)
    line_count_delta = draft_line_count - confirmed_line_count
    line_count_mismatch = line_count_delta != 0

    review_state = (
        str(payload.get("review_state") or "").strip()
        if authoritative_sheet_projection
        else "ready"
    )
    if not review_state:
        review_state = "ready"
        if draft_state["has_saved_draft"] and draft_state["auto_apply_blocked"]:
            review_state = "auto_apply_blocked"
        elif draft_state["has_saved_draft"] and draft_state["draft_newer_than_lines"]:
            review_state = "draft_ready"
        elif draft_state["has_saved_draft"]:
            review_state = "draft_saved"
        elif apply_blockers or confirm_blockers or confirm_warnings:
            review_state = "review_required"
    if (
        authoritative_sheet_projection
        and has_semantic_fields
        and not draft_state["has_saved_draft"]
        and (apply_blockers or confirm_blockers or confirm_warnings)
    ):
        review_state = "review_required"
    reparse_debug = ocr_payload.get("_reparse_debug") if isinstance(ocr_payload, dict) else None
    reparse_error = (
        str(reparse_debug.get("error") or "").strip()
        if isinstance(reparse_debug, dict)
        else ""
    )
    if not reparse_error and isinstance(ocr_metrics, dict):
        reparse_error = str(ocr_metrics.get("error") or "").strip()
    reparse_status = _derive_reparse_status(
        order_id=order_id,
        ocr_status=(ocr_metrics or {}).get("status") if isinstance(ocr_metrics, dict) else None,
        has_saved_draft=bool(draft_state["has_saved_draft"]),
        auto_apply_blocked=bool(draft_state["auto_apply_blocked"]),
        last_reparse_error=reparse_error,
    )
    review_stage = _derive_review_stage(
        order_status=None,
        normalized_ocr_status="done",
        has_saved_draft=bool(draft_state["has_saved_draft"]),
        draft_newer_than_lines=bool(draft_state["draft_newer_than_lines"]),
        auto_apply_blocked=bool(draft_state["auto_apply_blocked"]),
        reparse_status=reparse_status,
        needs_human_review=bool(apply_blockers or confirm_blockers or confirm_warnings),
    )
    if review_state == "review_required":
        review_stage = "needs_human_review"
    apply_blocker_details = _review_reason_details(apply_blockers, severity="blocker")
    confirm_blocker_details = _review_reason_details(confirm_blockers, severity="blocker")
    confirm_warning_details = _review_reason_details(confirm_warnings, severity="warning")

    enriched.update(
        {
            "review_state": review_state,
            "review_stage": review_stage,
            "can_apply": can_apply,
            "can_confirm": can_confirm,
            "apply_blockers": apply_blockers,
            "apply_blocker_details": apply_blocker_details,
            "confirm_blockers": confirm_blockers,
            "confirm_warnings": confirm_warnings,
            "confirm_blocker_details": confirm_blocker_details,
            "confirm_warning_details": confirm_warning_details,
            "has_saved_draft": draft_state["has_saved_draft"],
            "draft_updated_at": draft_state["draft_updated_at"],
            "draft_revision_id": draft_state["draft_revision_id"],
            "draft_newer_than_lines": draft_state["draft_newer_than_lines"],
            "auto_apply_blocked": draft_state["auto_apply_blocked"],
            "reject_reasons": draft_state["reject_reasons"],
            "reparse_status": reparse_status,
            "reparse_error": reparse_error or None,
            "reparse_last_error_code": reparse_error or None,
            "draft_line_count": draft_line_count,
            "confirmed_line_count": confirmed_line_count,
            "line_count_delta": line_count_delta,
            "line_count_mismatch": line_count_mismatch,
            "processing_stage": processing_stage or None,
            "result_state": result_state or None,
            "confirmed_lines_retained": confirmed_lines_retained,
        }
    )
    return enriched


def _normalize_structured_rows(
    *,
    header: object,
    rows_payload: object,
    template: dict[str, Any],
) -> list[list[str]]:
    if not isinstance(rows_payload, list):
        return []

    header_cells: list[str] = []
    if isinstance(header, list):
        header_cells = [_coerce_table_cell(cell) for cell in header]
    expected_fields = _get_row_fields(template)

    normalized_rows: list[list[str]] = []
    for row in rows_payload:
        normalized_row: list[str] = []
        if isinstance(row, list):
            normalized_row = [_coerce_table_cell(cell) for cell in row]
        elif isinstance(row, dict):
            if expected_fields:
                normalized_row = [_coerce_table_cell(row.get(field)) for field in expected_fields]
            elif header_cells:
                normalized_row = [_coerce_table_cell(row.get(col)) for col in header_cells]
            else:
                normalized_row = [_coerce_table_cell(value) for value in row.values()]
        if normalized_row and any(cell.strip() for cell in normalized_row):
            normalized_rows.append(normalized_row)
    if not normalized_rows:
        return []
    if not expected_fields:
        return normalized_rows

    field_count = len(expected_fields)
    if field_count and all(len(row) == field_count for row in normalized_rows):
        return normalized_rows

    mapped_indexes: dict[int, int] = {}
    if header_cells:
        fields_set = set(expected_fields)
        for idx, cell in enumerate(header_cells):
            field = _field_from_header(cell, fields_set)
            if not field:
                continue
            dest_idx = expected_fields.index(field)
            if dest_idx in mapped_indexes.values():
                continue
            mapped_indexes[idx] = dest_idx
    if not mapped_indexes and header_cells and len(header_cells) == field_count:
        mapped_indexes = {idx: idx for idx in range(field_count)}

    if mapped_indexes:
        aligned_rows: list[list[str]] = []
        for row in normalized_rows:
            output_row = [""] * field_count
            for src_idx, dst_idx in mapped_indexes.items():
                if src_idx < len(row):
                    output_row[dst_idx] = row[src_idx]
            if any(cell.strip() for cell in output_row):
                aligned_rows.append(output_row)
        if aligned_rows:
            return aligned_rows

    fallback_rows: list[list[str]] = []
    for row in normalized_rows:
        output_row = row[:field_count]
        if len(output_row) < field_count:
            output_row = output_row + [""] * (field_count - len(output_row))
        if any(cell.strip() for cell in output_row):
            fallback_rows.append(output_row)
    return fallback_rows


def apply_ocr_markdown(order_id: str, markdown: str):
    return apply_ocr_table(order_id, markdown=markdown, header=None, rows=None)


def apply_submitted_ocr_sheet(
    order_id: str,
    *,
    markdown: str | None = None,
    header: object = None,
    rows: object = None,
    ui_mode: str | None = None,
    fields: object = None,
    row_ids: object = None,
    expected_revision_id: str | None = None,
    expected_lines_updated_at: str | None = None,
    enforce_revision_guard: bool = False,
    enforce_lines_guard: bool = False,
    revision_meta: dict[str, Any] | None = None,
):
    synchronous_write_input = _capture_synchronous_cache_write_input(order_id)
    if synchronous_write_input is None:
        return None, "synchronous_input_missing"
    has_markdown = isinstance(markdown, str) and bool(markdown.strip())
    has_rows = isinstance(rows, list) and bool(rows)
    if not has_markdown and not has_rows:
        return None, "markdown_empty"

    captured_cache = synchronous_write_input["input_versions"]["cache"]
    current_payload = deepcopy(captured_cache["payload"]) if captured_cache is not None else None
    if enforce_revision_guard:
        revision_conflict = _sheet_revision_conflict_detail(
            order_id=order_id,
            expected_revision_id=expected_revision_id,
            payload=current_payload,
        )
        if revision_conflict is not None:
            return None, revision_conflict["error"]

    received_at = None
    facility_id = None
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return None, "order_not_found"
        if not order.facility_code:
            return None, "facility_missing"
        received_at = order.received_at or pd.Timestamp.utcnow()
        facility_id = order.facility_code

    facility_config = deepcopy(synchronous_write_input["configured_input"]["facility"])
    template = facility_config["fax_template"]

    source = "markdown"
    parsed_rows = _normalize_structured_rows(header=header, rows_payload=rows, template=template)
    if parsed_rows:
        source = "structured_rows"
    elif has_markdown:
        try:
            parsed_rows = rows_from_markdown(markdown or "", template) or []
        except _CanonicalOcrProjectionError as exc:
            return None, str(exc)
    if not parsed_rows:
        return None, "rows_empty"

    revision_fields: list[str] = []
    if isinstance(fields, list):
        revision_fields = [str(field).strip() for field in fields if str(field).strip()]
    if not revision_fields:
        revision_fields = _row_fields_from_template(template)
    max_width = max((len(row) for row in parsed_rows), default=0)
    if isinstance(header, list):
        max_width = max(max_width, len(header))
    if not revision_fields:
        revision_fields = [f"col{idx + 1}" for idx in range(max(max_width, 1))]
    elif len(revision_fields) < max_width:
        revision_fields.extend(
            [f"col{idx + 1}" for idx in range(len(revision_fields), max_width)]
        )

    revision_header: list[str] = []
    if isinstance(header, list):
        revision_header = [_coerce_table_cell(cell) for cell in header]
    if not revision_header:
        revision_header = [_field_label(field) for field in revision_fields]
    if len(revision_header) < len(revision_fields):
        revision_header.extend(
            [_field_label(field) for field in revision_fields[len(revision_header) :]]
        )

    revision_row_ids: list[str] = []
    if isinstance(row_ids, list):
        revision_row_ids = [str(item).strip() for item in row_ids if str(item).strip()]
    revision_row_count = len(rows) if isinstance(rows, list) else len(parsed_rows)
    if len(revision_row_ids) < revision_row_count:
        revision_row_ids.extend(
            [f"row-{idx + 1}" for idx in range(len(revision_row_ids), revision_row_count)]
        )

    revision_ui_mode = str(ui_mode or "").strip().lower()
    if not revision_ui_mode:
        revision_ui_mode = "sheet" if source == "structured_rows" else "legacy"
    save_result, save_error = save_ocr_sheet_exact(
        order_id,
        header=revision_header,
        rows=rows if isinstance(rows, list) else parsed_rows,
        fields=revision_fields,
        row_ids=revision_row_ids,
        ui_mode=revision_ui_mode,
        expected_revision_id=expected_revision_id,
        expected_lines_updated_at=expected_lines_updated_at,
        enforce_revision_guard=enforce_revision_guard,
        enforce_lines_guard=enforce_lines_guard,
        synchronous_write_input=synchronous_write_input,
        return_write_input=True,
    )
    if save_error:
        return None, save_error
    draft_record = save_result.get("draft") if isinstance(save_result, dict) else None
    serialized, apply_error = apply_latest_draft(
        order_id,
        draft_record=draft_record if isinstance(draft_record, dict) else None,
        source=source,
        expected_lines_updated_at=expected_lines_updated_at,
        enforce_lines_guard=enforce_lines_guard,
        synchronous_write_input=save_result["synchronous_write_input"],
    )
    if apply_error:
        return None, apply_error
    if isinstance(serialized, dict):
        revision = save_result.get("revision") if isinstance(save_result, dict) else None
        if isinstance(revision, dict):
            serialized["draft_revision"] = revision
    return serialized, None


def apply_ocr_table(
    order_id: str,
    *,
    markdown: str | None = None,
    header: object = None,
    rows: object = None,
    ui_mode: str | None = None,
    fields: object = None,
    row_ids: object = None,
    expected_revision_id: str | None = None,
    expected_lines_updated_at: str | None = None,
    enforce_revision_guard: bool = False,
    enforce_lines_guard: bool = False,
    revision_meta: dict[str, Any] | None = None,
):
    return apply_submitted_ocr_sheet(
        order_id,
        markdown=markdown,
        header=header,
        rows=rows,
        ui_mode=ui_mode,
        fields=fields,
        row_ids=row_ids,
        expected_revision_id=expected_revision_id,
        expected_lines_updated_at=expected_lines_updated_at,
        enforce_revision_guard=enforce_revision_guard,
        enforce_lines_guard=enforce_lines_guard,
        revision_meta=revision_meta,
    )


def save_ocr_sheet_exact(
    order_id: str,
    *,
    header: object = None,
    rows: object = None,
    fields: object = None,
    row_ids: object = None,
    ui_mode: str | None = None,
    expected_revision_id: str | None = None,
    expected_lines_updated_at: str | None = None,
    enforce_revision_guard: bool = False,
    enforce_lines_guard: bool = False,
    synchronous_write_input: dict[str, Any] | None = None,
    return_write_input: bool = False,
):
    if synchronous_write_input is None:
        synchronous_write_input = _capture_synchronous_cache_write_input(order_id)
    if synchronous_write_input is None:
        return None, "synchronous_input_missing"
    snapshot = _normalize_sheet_revision_snapshot(
        fields=fields,
        header=header,
        rows_payload=rows,
        row_ids=row_ids,
    )
    if not snapshot["rows"]:
        return None, "rows_empty"

    facility_id: str | None = None
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return None, "order_not_found"
        facility_id = order.facility_code

    captured_cache = synchronous_write_input["input_versions"]["cache"]
    current_payload = deepcopy(captured_cache["payload"]) if captured_cache is not None else None
    if enforce_revision_guard:
        revision_conflict = _sheet_revision_conflict_detail(
            order_id=order_id,
            expected_revision_id=expected_revision_id,
            payload=current_payload,
        )
        if revision_conflict is not None:
            return None, revision_conflict["error"]
    previous_revision = _select_order_sheet_revision(
        order_id=order_id,
        payload=current_payload,
        exact_only=False,
    )
    if isinstance(previous_revision, dict):
        before_digest = _sheet_digest(
            fields=previous_revision.get("fields"),
            header=previous_revision.get("header"),
            rows_payload=previous_revision.get("rows"),
            row_ids=previous_revision.get("row_ids"),
        )
    else:
        current_sheet, current_error = get_ocr_sheet(
            order_id, evidence_run_override=synchronous_write_input["evidence"],
            synchronous_write_input=synchronous_write_input,
        )
        if current_error or not isinstance(current_sheet, dict):
            before_digest = _sheet_digest(
                fields=snapshot["fields"],
                header=snapshot["header"],
                rows_payload=snapshot["rows"],
                row_ids=snapshot["row_ids"],
            )
        else:
            before_digest = _sheet_digest(
                fields=current_sheet.get("fields"),
                header=current_sheet.get("header"),
                rows_payload=current_sheet.get("rows"),
                row_ids=current_sheet.get("row_ids"),
            )
    after_digest = _sheet_digest(
        fields=snapshot["fields"],
        header=snapshot["header"],
        rows_payload=snapshot["rows"],
        row_ids=snapshot["row_ids"],
    )

    if enforce_lines_guard:
        latest_lines_updated_at: datetime | None = None
        with session_scope() as session:
            latest_order = session.get(Order, order_id)
            if not latest_order:
                return None, "order_not_found"
            latest_lines_updated_at = latest_order.lines_updated_at
        lines_conflict = _lines_timestamp_conflict_detail(
            current_lines_updated_at=latest_lines_updated_at,
            expected_lines_updated_at=expected_lines_updated_at,
        )
        if lines_conflict is not None:
            return None, lines_conflict["error"]

    resolved_ui_mode = str(ui_mode or "").strip().lower() or "sheet"
    captured_draft = synchronous_write_input.get("draft")
    current_draft_payload = (
        captured_draft.get("draft_sheet_json")
        if isinstance(captured_draft, dict)
        and isinstance(captured_draft.get("draft_sheet_json"), dict)
        else None
    )
    persisted_sheet_payload = dict(current_draft_payload) if isinstance(current_draft_payload, dict) else {}
    persisted_sheet_payload.pop("warnings", None)
    persisted_sheet_payload.pop("blockers", None)
    persisted_sheet_payload.pop("repair_mode", None)
    persisted_sheet_payload.pop("repair_metadata", None)
    persisted_sheet_payload.pop("projection_diagnostics", None)
    persisted_sheet_payload.pop("cell_issues", None)
    persisted_sheet_payload.pop("issue_summary", None)
    persisted_sheet_payload.pop("trace", None)
    persisted_sheet_payload.update(
        {
            "fields": snapshot["fields"],
            "header": snapshot["header"],
            "rows": snapshot["rows"],
            "row_ids": snapshot["row_ids"],
            "ui_mode": resolved_ui_mode,
            "source": "edited_sheet_exact",
            "warnings": [],
            "blockers": [],
        }
    )
    with session_scope() as write_session:
        next_write_input = _append_edited_ocr_revision(
            order_id=order_id,
            ui_mode=resolved_ui_mode,
            fields=snapshot["fields"],
            header=snapshot["header"],
            rows_payload=snapshot["rows"],
            row_ids=snapshot["row_ids"],
            before_digest=before_digest,
            after_digest=after_digest,
            revision_meta={
                "sheet_save_only": True,
                "sheet_save_mode": "exact",
                "review_state": "draft_ready",
                "review_blockers": [],
                "review_warnings": [],
            },
            synchronous_write_input=synchronous_write_input,
            write_session=write_session,
        )
        if next_write_input is None:
            write_session.rollback()
            return None, "synchronous_input_conflict"
        persisted_sheet_payload["ocr_revision_id"] = next_write_input["written_revision"]["revision_id"]
        persisted_draft = persist_sheet_draft(
            order_id=order_id,
            draft_sheet_json=persisted_sheet_payload,
            draft_state="draft_ready",
            blockers=[],
            warnings=[],
            evidence_run_id=synchronous_write_input["evidence_run_id"],
            synchronous_write_input=next_write_input,
            write_session=write_session,
        )
        if persisted_draft is None:
            write_session.rollback()
            return None, "synchronous_input_conflict"
    if not return_write_input:
        try:
            _acknowledge_current_candidate_after_authoritative_action(
                order_id,
                selected_by="save-ocr-sheet-exact",
            )
        except Exception as exc:  # noqa: BLE001
            logger.warning(
                "Workflow candidate acknowledgement failed after exact sheet save",
                order_id=order_id,
                error=str(exc),
            )
    record_event(
        "ocr_sheet_save",
        actor="system",
        target=order_id,
        fac=facility_id,
        metadata={
            "row_count": len(snapshot["rows"]),
            "changed": before_digest != after_digest,
            "mode": "exact",
        },
    )
    result = {
        "order_id": order_id,
        "revision": next_write_input["written_revision"],
        "draft": persisted_draft if isinstance(persisted_draft, dict) else None,
    }
    if return_write_input:
        next_write_input["written_draft"] = deepcopy(persisted_draft)
        result["synchronous_write_input"] = next_write_input
    return result, None


def _persist_reparse_diagnostics(
    order_id: str, own_payload: dict[str, Any] | None, job_id: str,
    diagnostics: dict[str, Any],
) -> dict[str, Any]:
    if not isinstance(own_payload, dict) or not job_id:
        raise ValueError("reparse_pipeline_result_missing")
    payload = deepcopy(own_payload)
    payload["_reparse_debug"] = deepcopy(diagnostics)
    with _ocr_result_transaction() as session:
        if not _workflow_attempt_write_fence(session, job_id, order_id):
            raise ValueError("reparse_attempt_superseded")
        evidence = persist_ocr_evidence_run(
            order_id, payload, schema_version="v2_reparse_pipeline_diagnostics",
            producer_version="reparse_pipeline_result", status="diagnostic_only",
            source="reparse-pipeline-result", workflow_job_id=job_id,
            refresh_workflow=False, result_disposition="rejected", write_session=session,
        )
        if not isinstance(evidence, dict) or not evidence.get("id"):
            raise ValueError("reparse_evidence_persist_failed")
        receipt = _complete_ocr_rerun_in_session(
            session, order_id, job_id, evidence,
            error=str(diagnostics.get("error") or "reparse_output_rejected"),
            metrics_patch=diagnostics,
        )
    return {
        "ocr_job_id": job_id, "reparse_evidence_run_id": evidence["id"],
        "workflow_attempt_id": _workflow_ocr_attempt_id.get(),
        "workflow_revision": _workflow_ocr_revision.get(), "adopted": False,
        "terminal_receipt": receipt,
    }


def _rejected_reparse_result(
    order_id: str, own_payload: dict[str, Any] | None, job_id: str,
    error: str, diagnostics: dict[str, Any] | None = None,
) -> tuple[dict[str, Any] | None, str]:
    try:
        result = _persist_reparse_diagnostics(
            order_id, own_payload, job_id, {**(diagnostics or {}), "error": error},
        )
        return result, error
    except Exception as exc:  # noqa: BLE001
        return None, f"{error}:{exc}"


def _save_reparse_candidate_as_draft(
    *,
    order_id: str,
    template: dict[str, Any],
    rows: list[list[str]],
    before_digest: str,
    raw_output_override: dict[str, Any] | None = None,
    workflow_job_id: str | None = None,
    review_state: str,
    review_blockers: list[str] | None = None,
    review_warnings: list[str] | None = None,
    diagnostics: dict[str, Any] | None = None,
) -> dict[str, Any]:
    normalized_job_id = str(workflow_job_id or "").strip()
    if not isinstance(raw_output_override, dict) or not normalized_job_id:
        raise ValueError("reparse_pipeline_result_missing")
    candidate_fields = _row_fields_from_template(template)
    candidate_header: list[str] | None = None
    if not candidate_fields:
        raise ValueError("reparse_candidate_template_fields_missing")
    if not candidate_header:
        candidate_header = _sheet_header_from_template(candidate_fields, template)
    sanitized_rows = _sanitize_semantic_sheet_rows(
        rows_payload=rows,
        fields=candidate_fields,
    )
    if not sanitized_rows:
        raise ValueError("reparse_candidate_rows_missing")
    candidate_row_ids = [f"draft-{idx + 1}" for idx in range(len(sanitized_rows))]
    after_digest = _sheet_digest(
        fields=candidate_fields,
        header=candidate_header,
        rows_payload=sanitized_rows,
        row_ids=candidate_row_ids,
    )
    own_payload = deepcopy(raw_output_override)
    own_payload["_reparse_debug"] = deepcopy(diagnostics or {})
    with _ocr_result_transaction() as write_session:
        if not _workflow_attempt_write_fence(write_session, normalized_job_id, order_id):
            raise ValueError("reparse_attempt_superseded")
        evidence = persist_ocr_evidence_run(
            order_id, own_payload,
            schema_version="v2_reparse_pipeline_result",
            producer_version="reparse_pipeline_result",
            status="ready" if _classify_owned_evidence_payload(own_payload).get("persistable") else "diagnostic_only",
            source="reparse-pipeline-result",
            workflow_job_id=normalized_job_id,
            refresh_workflow=False,
            result_disposition="rejected",
            write_session=write_session,
        )
        if not isinstance(evidence, dict) or not evidence.get("id"):
            raise ValueError("reparse_evidence_persist_failed")
        result = _persist_reparse_candidate_review(
            order_id=order_id, candidate_fields=candidate_fields,
            candidate_header=candidate_header, sanitized_rows=sanitized_rows,
            candidate_row_ids=candidate_row_ids, before_digest=before_digest,
            after_digest=after_digest, raw_output_override=raw_output_override,
            normalized_job_id=normalized_job_id, review_state=review_state,
            review_blockers=review_blockers, review_warnings=review_warnings,
            evidence=evidence, write_session=write_session,
        )
        result["terminal_receipt"] = _complete_ocr_rerun_in_session(
            write_session, order_id, normalized_job_id, evidence,
            error=str((diagnostics or {}).get("error") or "reparse_candidate_rejected"),
            metrics_patch=diagnostics or {},
        )
        return result


def _persist_reparse_candidate_review(
    *, order_id: str, candidate_fields: list[str], candidate_header: list[str],
    sanitized_rows: list[list[str]], candidate_row_ids: list[str],
    before_digest: str, after_digest: str, raw_output_override: dict[str, Any],
    normalized_job_id: str, review_state: str,
    review_blockers: list[str] | None, review_warnings: list[str] | None,
    evidence: dict[str, Any], write_session: Any,
) -> dict[str, Any]:
    archived = _append_edited_ocr_revision(
        order_id=order_id,
        ui_mode="sheet",
        fields=candidate_fields,
        header=candidate_header,
        rows_payload=sanitized_rows,
        row_ids=candidate_row_ids,
        before_digest=before_digest or after_digest,
        after_digest=after_digest,
        revision_meta={
            "sheet_save_only": True,
            "sheet_save_mode": "draft_candidate",
            "review_state": str(review_state or "draft_ready").strip() or "draft_ready",
            "review_blockers": [str(item).strip() for item in (review_blockers or []) if str(item).strip()],
            "review_warnings": [str(item).strip() for item in (review_warnings or []) if str(item).strip()],
            "draft_from_reparse_reject": True,
            "adopted": False,
            "base_evidence_run_id": evidence["id"],
            "raw_output_override": raw_output_override,
        },
        workflow_job_id=normalized_job_id,
        write_session=write_session,
    )
    if archived is None:
        raise ValueError("reparse_candidate_revision_persist_failed")
    candidate_draft = draft_sheet_service.persist_sheet_draft(
        order_id=order_id,
        draft_sheet_json={
            "source": "reparse_candidate",
            "fields": candidate_fields,
            "header": candidate_header,
            "rows": sanitized_rows,
            "row_ids": candidate_row_ids,
            "ui_mode": "sheet",
            "base_evidence_run_id": evidence["id"],
            "ocr_revision_id": archived["written_revision"]["revision_id"],
            "_ocr_execution": deepcopy(evidence["payload_json"]["_ocr_execution"]),
        },
        draft_state=str(review_state or "draft_ready").strip() or "draft_ready",
        blockers=[str(item).strip() for item in (review_blockers or []) if str(item).strip()],
        warnings=[str(item).strip() for item in (review_warnings or []) if str(item).strip()],
        edited_by="reparse-reject-candidate",
        base_evidence_run_id=evidence["id"],
        template_version_id=evidence["template_version_id"],
        workflow_job_id=normalized_job_id,
        workflow_attempt_id=_workflow_ocr_attempt_id.get(),
        expected_workflow_revision=_workflow_ocr_revision.get(),
        write_session=write_session,
    )
    if candidate_draft is None:
        raise ValueError("reparse_candidate_draft_persist_failed")
    return {
        "ocr_job_id": normalized_job_id,
        "reparse_evidence_run_id": evidence["id"],
        "workflow_attempt_id": _workflow_ocr_attempt_id.get(),
        "workflow_revision": _workflow_ocr_revision.get(),
        "review_draft": candidate_draft,
        "revision": archived["written_revision"],
        "adopted": False,
    }


def _build_revision_raw_output_override(
    *,
    fields: list[str],
    header: list[str],
    rows: list[list[str]],
    template: dict[str, Any] | None,
    provider: str | None = None,
) -> dict[str, Any]:
    normalized_rows = [list(row) for row in rows if isinstance(row, list)]
    payload: dict[str, Any] = {
        "table_raw": _build_markdown_table_string(header, normalized_rows),
        "rows": [list(row) for row in normalized_rows],
        "table_rows": [list(row) for row in normalized_rows],
    }
    if normalized_rows:
        structured_table = {
            "table_id": "revision_table",
            "page_index": 1,
            "rows": [list(row) for row in normalized_rows],
            "row_count": len(normalized_rows),
            "col_count": max((len(row) for row in normalized_rows), default=len(fields)),
        }
        payload["tables"] = [structured_table]
        payload["pages"] = [{"page_index": 1, "tables": [structured_table]}]
    template_id = ""
    if isinstance(template, dict):
        template_id = str(template.get("id") or template.get("template_id") or "").strip()
        facility_id = str(template.get("facility_id") or "").strip()
        if facility_id:
            payload["facility_id"] = facility_id
    if template_id:
        payload["template_id"] = template_id
    normalized_provider = str(provider or "").strip()
    if normalized_provider:
        payload["provider"] = normalized_provider
    return payload


def _publish_applied_reparse_revision(
    *,
    order_id: str,
    template: dict[str, Any] | None,
    previous_sheet_context: dict[str, Any] | None,
    current_sheet_context: dict[str, Any] | None,
    ocr_rows: list[list[str]] | None,
    raw_output_payload: dict[str, Any] | None = None,
    provider: str | None,
    llm_assist: bool,
    ocr_job_id: str | None = None,
    evidence_run_id: str | None = None,
    warning_reasons: list[str] | None = None,
    write_session: Any = None,
) -> dict[str, Any] | None:
    if not isinstance(template, dict):
        return
    fields = _row_fields_from_template(template)
    if not fields:
        return
    normalized_ocr_rows = _sanitize_semantic_sheet_rows(
        rows_payload=ocr_rows,
        fields=fields,
    )
    if not normalized_ocr_rows:
        return
    header = _sheet_header_from_template(fields, template)
    current_row_ids = [
        str(item).strip()
        for item in ((current_sheet_context or {}).get("row_ids") or [])
        if str(item).strip()
    ]
    if len(current_row_ids) < len(normalized_ocr_rows):
        current_row_ids.extend([f"ocr-row-{idx + 1}" for idx in range(len(current_row_ids), len(normalized_ocr_rows))])

    previous_rows = _sanitize_semantic_sheet_rows(
        rows_payload=(previous_sheet_context or {}).get("rows"),
        fields=fields,
    )
    previous_row_ids = [
        str(item).strip()
        for item in ((previous_sheet_context or {}).get("row_ids") or [])
        if str(item).strip()
    ]
    if len(previous_row_ids) < len(previous_rows):
        previous_row_ids.extend([f"prev-row-{idx + 1}" for idx in range(len(previous_row_ids), len(previous_rows))])
    if not previous_rows:
        previous_rows = [list(row) for row in normalized_ocr_rows]
        previous_row_ids = current_row_ids[: len(normalized_ocr_rows)]

    applied_rows = [list(row) for row in normalized_ocr_rows]
    applied_row_ids = current_row_ids[: len(applied_rows)]
    raw_output_override = _snapshot_raw_ocr_payload(raw_output_payload) if isinstance(raw_output_payload, dict) else {}
    if raw_output_override:
        applied_rows, _projection_stats = _project_payload_display_cells_onto_sheet_row_lists(
            rows=applied_rows,
            fields=fields,
            header=header,
            payload_rows=_extract_sheet_rows_from_payload_uncanonicalized(raw_output_override, template),
            raw_payload=raw_output_override,
            template=template,
        )
    applied_rows, _helper_stats = _canonicalize_block_helper_display_rows(
        rows=applied_rows,
        fields=fields,
        header=header,
    )

    before_digest = _sheet_digest(
        fields=fields,
        header=header,
        rows_payload=previous_rows or applied_rows,
        row_ids=previous_row_ids[: len(previous_rows)] if previous_rows else applied_row_ids[: len(applied_rows)],
    )
    after_digest = _sheet_digest(
        fields=fields,
        header=header,
        rows_payload=applied_rows,
        row_ids=applied_row_ids[: len(applied_rows)],
    )

    return _append_edited_ocr_revision(
        order_id=order_id,
        ui_mode="sheet",
        fields=fields,
        header=header,
        rows_payload=applied_rows,
        row_ids=applied_row_ids[: len(applied_rows)],
        before_digest=before_digest,
        after_digest=after_digest,
        revision_meta={
            "sheet_save_only": False,
            "sheet_save_mode": "pipeline_result",
            "review_state": "awaiting_selection",
            "review_blockers": [],
            "review_warnings": [str(item).strip() for item in (warning_reasons or []) if str(item).strip()],
            "lines_applied": True,
            "adopted": False,
            "base_evidence_run_id": evidence_run_id,
            "llm_assist": bool(llm_assist),
            "provider": str(provider or "").strip() or None,
            "raw_output_override": raw_output_override if raw_output_override else None,
        },
        workflow_job_id=ocr_job_id,
        write_session=write_session,
    )


def _parse_llm_review_confidence(value: object) -> float:
    text = str(value or "").strip()
    if not text:
        return 0.0
    try:
        parsed = float(text)
    except Exception:
        return 0.0
    if parsed < 0.0:
        return 0.0
    if parsed > 1.0:
        return 1.0
    return parsed


def _parse_llm_review_int(value: object) -> int | None:
    text = str(value or "").strip()
    if not text or not re.fullmatch(r"-?\d+", text):
        return None
    try:
        return int(text)
    except Exception:
        return None


def _merge_ocr_job_metrics(job_id: str, patch: dict[str, Any] | None = None) -> dict[str, Any]:
    # The job service merges this explicit patch only after validating/locking.
    return dict(patch) if isinstance(patch, dict) else {}


def _update_reparse_job_progress(
    job_id: str,
    *,
    status: str | None = None,
    processing_stage: str | None = None,
    result_state: str | None = None,
    error_message: str | None = None,
    metrics_patch: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    metrics = _merge_ocr_job_metrics(job_id, metrics_patch)
    if processing_stage is not None:
        metrics["processing_stage"] = str(processing_stage or "").strip() or None
    if result_state is not None:
        metrics["result_state"] = str(result_state or "").strip() or None
    metrics["stage_updated_at"] = datetime.utcnow().isoformat()
    updates: dict[str, Any] = {
        "metrics": metrics,
    }
    if status is not None:
        updates["status"] = status
    if error_message is not None or (status in {"done", "success"} and result_state in {"applied", "draft_ready_blocked"}):
        updates["error_message"] = error_message
    workflow_attempt_id = _workflow_ocr_attempt_id.get()
    if workflow_attempt_id or current_nonworkflow_execution() is not None:
        # Actual-result transactions own terminal status, not progress.
        if status in {"done", "failed", "error", "completed", "success"}:
            status = None
            error_message = None
            updates.pop("status", None)
            updates.pop("error_message", None)
    if workflow_attempt_id:
        updated, accepted = update_job_for_workflow_attempt(
            job_id,
            workflow_attempt_id,
            order_id=_workflow_ocr_order_id.get(),
            expected_workflow_revision=_workflow_ocr_revision.get(),
            **updates,
        )
        return updated if accepted else None
    return update_job(
        job_id,
        actual_order_id=(current_nonworkflow_execution() or {}).get("order_id"),
        **updates,
    )


def _build_reparse_request_metadata(
    *,
    ocr_prompt: str | None,
    prompt_preset: str | None,
    requested_provider: str | None,
    ocr_model: str | None,
    llm_assist: bool,
) -> dict[str, Any]:
    return {
        "reparse_ocr_prompt": ocr_prompt,
        "reparse_prompt_preset": prompt_preset,
        "reparse_requested_provider": requested_provider,
        "reparse_ocr_model": ocr_model,
        "reparse_llm_assist": llm_assist,
    }


def _read_reparse_output_recovery_grace_seconds() -> float:
    raw = (
        os.getenv("OCR_REPARSE_OUTPUT_RECOVERY_GRACE_SECONDS")
        or os.getenv("OCR_PIPELINE_TIMEOUT_SECONDS")
        or "600"
    )
    try:
        parsed = float(str(raw).strip())
    except Exception:
        parsed = 600.0
    return max(parsed, 30.0)


def _mark_reparse_job_awaiting_output(
    job_id: str,
    *,
    input_reference: str | None,
    output_reference: str | None,
    metrics_patch: dict[str, Any] | None = None,
    error_message: str = "ocr_output_pending",
    recovery_delay_seconds: float | None = None,
) -> dict[str, Any] | None:
    if not output_reference:
        return None
    execution = current_nonworkflow_execution()
    order_id = _workflow_ocr_order_id.get() or (execution or {}).get("order_id")
    if not order_id:
        return None
    now = datetime.utcnow()
    delay_seconds = (
        max(float(recovery_delay_seconds), 30.0)
        if recovery_delay_seconds is not None
        else _read_reparse_output_recovery_grace_seconds()
    )
    with _ocr_result_transaction() as session:
        if not _workflow_attempt_write_fence(session, job_id, order_id):
            return None
        job = session.get(OcrJob, job_id)
        if (
            job is None or job.status not in {"running", "pending", "awaiting_output", "recovering"}
            or (job.metrics or {}).get("rerun_terminal_receipt") is not None
        ):
            return None
        metrics = dict(job.metrics or {})
        delivery = metrics.get("pipeline_delivery_receipt")
        if not own_pipeline_delivery_matches(job, input_reference, output_reference):
            return None
        receipt = {
            "job_id": job_id, "order_id": order_id,
            "workflow_attempt_id": _workflow_ocr_attempt_id.get(),
            "workflow_revision": _workflow_ocr_revision.get(),
            "execution_id": (execution or {}).get("execution_id"),
            "selected_document_id": metrics.get("selected_document_id"),
            "request_kwargs": _extract_reparse_request_kwargs_from_job({"metrics": metrics}),
            "input_reference": input_reference, "output_reference": output_reference,
            "selected_input_reference": job.input_reference,
            "pipeline_delivery_receipt": deepcopy(delivery),
        }
        metrics = merge_own_job_metrics_patch(metrics, metrics_patch)
        metrics.update({
            "processing_stage": "ocr_pipeline", "result_state": "awaiting_output",
            "error": "ocr_output_pending", "output_reference": output_reference,
            "input_reference": input_reference,
            "awaiting_output_since": str(metrics.get("awaiting_output_since") or now.isoformat()),
            "next_recovery_at": (now + timedelta(seconds=delay_seconds)).isoformat(),
            "stage_updated_at": now.isoformat(), "pending_receipt": receipt,
        })
        job.status = "awaiting_output"
        job.output_reference = output_reference
        job.error_message = error_message
        job.metrics = metrics
        job.updated_at = now
        session.flush()
    return {"outcome": "pending", "status": "awaiting_output",
            "output_reference": output_reference, "pending_receipt": receipt}


def is_own_pending_ocr_result(result, *, order_id, job_id, workflow_attempt_id=None,
                              workflow_revision=None, execution_id=None):
    if not isinstance(result, dict) or result.get("outcome") != "pending":
        return False
    if not (
        (isinstance(workflow_attempt_id, str) and bool(workflow_attempt_id)
         and type(workflow_revision) is int and workflow_revision >= 1 and execution_id is None)
        or (workflow_attempt_id is None and workflow_revision is None
            and isinstance(execution_id, str) and bool(execution_id))
    ):
        return False
    receipt = result.get("pending_receipt")
    return (
        isinstance(receipt, dict) and result.get("terminal_receipt") is None
        and result.get("status") == "awaiting_output"
        and bool(receipt.get("output_reference"))
        and result.get("output_reference") == receipt.get("output_reference")
        and receipt.get("job_id") == job_id and receipt.get("order_id") == order_id
        and receipt.get("workflow_attempt_id") == workflow_attempt_id
        and receipt.get("workflow_revision") == workflow_revision
        and receipt.get("execution_id") == execution_id
    )


def _resolve_llm_review_baseline(
    *,
    order_id: str,
    payload: dict[str, Any],
    template: dict[str, Any],
    synchronous_write_input: dict[str, Any] | None = None,
) -> dict[str, Any]:
    captured_draft = (synchronous_write_input or {}).get("draft")
    current_sheet_context = (
        deepcopy(captured_draft.get("draft_sheet_json")) if isinstance(captured_draft, dict)
        else None
    ) if synchronous_write_input is not None else get_current_sheet_context(
        order_id,
        refresh_draft_from_semantic=True,
        upgrade_generic_from_sheet=True,
        backfill_from_revision=False,
    )
    if isinstance(captured_draft, dict) and isinstance(current_sheet_context, dict):
        current_sheet_context["draft_id"] = captured_draft["id"]
    if isinstance(current_sheet_context, dict):
        fields = [
            str(field).strip()
            for field in (current_sheet_context.get("fields") or [])
            if str(field).strip()
        ]
        rows = _sanitize_revision_rows(
            rows_payload=current_sheet_context.get("rows"),
            fields=fields,
        )
        row_ids = [
            str(item).strip()
            for item in (current_sheet_context.get("row_ids") or [])
            if str(item).strip()
        ]
        header = [str(cell or "").strip() for cell in (current_sheet_context.get("header") or [])]
        if fields and rows:
            if len(row_ids) < len(rows):
                row_ids.extend([f"row-{idx + 1}" for idx in range(len(row_ids), len(rows))])
            if len(header) < len(fields):
                header.extend([_field_label(field) for field in fields[len(header) :]])
            return {
                "fields": fields,
                "header": header,
                "rows": rows,
                "row_ids": row_ids[: len(rows)],
                "baseline_revision_id": str(current_sheet_context.get("draft_id") or "").strip() or None,
                "raw_output": _snapshot_raw_ocr_payload(payload),
                "baseline_source": "current_draft",
            }

    edited = payload.get("_edited_ocr")
    latest = None if synchronous_write_input is not None else _select_order_sheet_revision(order_id=order_id, payload=payload, exact_only=False)
    raw_output = edited.get("raw_output") if isinstance(edited, dict) else None
    if not isinstance(raw_output, dict):
        raw_output = _snapshot_raw_ocr_payload(payload)

    if isinstance(latest, dict):
        latest_llm_review = latest.get("llm_review")
        latest_output_payload = (
            latest_llm_review.get("output_payload")
            if isinstance(latest_llm_review, dict)
            else None
        )
        if isinstance(latest_output_payload, dict):
            raw_output = latest_output_payload
        fields = [str(field).strip() for field in (latest.get("fields") or []) if str(field).strip()]
        rows = _sanitize_revision_rows(rows_payload=latest.get("rows"), fields=fields)
        row_ids = [str(item).strip() for item in (latest.get("row_ids") or []) if str(item).strip()]
        header = [str(cell or "").strip() for cell in (latest.get("header") or [])]
        if len(row_ids) < len(rows):
            row_ids.extend([f"row-{idx + 1}" for idx in range(len(row_ids), len(rows))])
        if len(header) < len(fields):
            header.extend([_field_label(field) for field in fields[len(header) :]])
        return {
            "fields": fields,
            "header": header,
            "rows": rows,
            "row_ids": row_ids[: len(rows)],
            "baseline_revision_id": str(latest.get("revision_id") or "").strip() or None,
            "raw_output": raw_output,
            "baseline_source": "edited",
        }

    fields = _row_fields_from_template(template)
    rows = _extract_first_pass_rows_from_payload(payload, template)
    if not fields:
        width = max((len(row) for row in rows), default=0)
        fields = [f"col{idx + 1}" for idx in range(max(width, 1))]
    header = _sheet_header_from_template(fields, template)
    row_ids = [f"row-{idx + 1}" for idx in range(len(rows))]
    return {
        "fields": fields,
        "header": header,
        "rows": rows,
        "row_ids": row_ids,
        "baseline_revision_id": None,
        "raw_output": raw_output,
        "baseline_source": "yomitoku",
    }


