def _extract_llm_review_json_object(raw_text: object) -> dict[str, Any] | None:
    text = str(raw_text or "").strip()
    if not text:
        return None

    candidates: list[str] = []
    fenced = re.search(r"```(?:json)?\s*(\{.*?\})\s*```", text, flags=re.DOTALL)
    if fenced:
        candidates.append(fenced.group(1).strip())
    candidates.append(text)

    start = text.find("{")
    if start >= 0:
        depth = 0
        in_string = False
        escaped = False
        for idx in range(start, len(text)):
            char = text[idx]
            if in_string:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == '"':
                    in_string = False
                continue
            if char == '"':
                in_string = True
                continue
            if char == "{":
                depth += 1
                continue
            if char == "}":
                depth -= 1
                if depth == 0:
                    candidates.append(text[start : idx + 1].strip())
                    break

    seen: set[str] = set()
    for candidate in candidates:
        if not candidate or candidate in seen:
            continue
        seen.add(candidate)
        try:
            parsed = json.loads(candidate)
        except Exception:
            continue
        if isinstance(parsed, dict):
            return parsed
    return None


def _normalize_llm_review_json_value(value: object, *, depth: int = 0) -> Any:
    if depth >= 3:
        return _field_value_to_str(value)
    if value is None or isinstance(value, (bool, int, float)):
        return value
    if isinstance(value, str):
        return value.strip()
    if isinstance(value, list):
        normalized_items: list[Any] = []
        for item in value[:20]:
            normalized_item = _normalize_llm_review_json_value(item, depth=depth + 1)
            if normalized_item is not None:
                normalized_items.append(normalized_item)
        return normalized_items
    if isinstance(value, dict):
        normalized_dict: dict[str, Any] = {}
        for raw_key, raw_value in list(value.items())[:20]:
            key = str(raw_key or "").strip()
            if not key:
                continue
            normalized_value = _normalize_llm_review_json_value(raw_value, depth=depth + 1)
            if normalized_value is None:
                continue
            normalized_dict[key] = normalized_value
        return normalized_dict
    return _field_value_to_str(value)


def _normalize_llm_review_summary(value: object) -> dict[str, Any]:
    if isinstance(value, dict):
        normalized = _normalize_llm_review_json_value(value)
        if isinstance(normalized, dict):
            return normalized
    if isinstance(value, str) and value.strip():
        return {"text": value.strip()}
    return {}


def _normalize_llm_review_issue(item: object, *, issue_id: str) -> dict[str, Any] | None:
    if not isinstance(item, dict):
        return None
    row_id = str(item.get("row_id") or "").strip()
    field = str(item.get("field") or "").strip()
    if not row_id or not field:
        return None
    normalized: dict[str, Any] = {
        "issue_id": issue_id,
        "row_id": row_id,
        "field": field,
        "issue_code": str(item.get("issue_code") or item.get("status") or item.get("reason") or "review_required").strip()
        or "review_required",
        "status": str(item.get("status") or "").strip(),
        "current_text": _field_value_to_str(item.get("current_text")),
        "confidence": round(_parse_llm_review_confidence(item.get("confidence")), 4),
        "evidence": str(item.get("evidence") or "").strip(),
        "reason": str(item.get("reason") or "").strip(),
        "severity": str(item.get("severity") or "warning").strip() or "warning",
        "source": "llm_review",
    }
    table_id = str(item.get("table_id") or "").strip()
    if table_id:
        normalized["table_id"] = table_id
    page_index = _parse_llm_review_int(item.get("page_index"))
    if page_index is not None:
        normalized["page_index"] = page_index
    return normalized


def _normalize_llm_review_output_issue(
    item: object,
    *,
    issue_id: str,
    fields: list[str],
    row_ids: list[str],
    current_rows: list[list[str]],
) -> dict[str, Any] | None:
    if not isinstance(item, dict):
        return None
    field = str(item.get("field") or "").strip()
    if not field or field not in fields:
        return None
    row_id = str(item.get("row_id") or "").strip()
    row_index = _parse_llm_review_int(item.get("row_index"))
    if row_index is None:
        row_index = _parse_llm_review_int(item.get("source_row_index"))
    if not row_id and row_index is not None and 0 <= row_index < len(row_ids):
        row_id = row_ids[row_index]
    if not row_id:
        return None
    if row_index is None and row_id in row_ids:
        row_index = row_ids.index(row_id)
    normalized = _normalize_llm_review_issue(
        {
            **item,
            "row_id": row_id,
            "field": field,
        },
        issue_id=issue_id,
    )
    if not isinstance(normalized, dict):
        return None
    if row_index is not None and 0 <= row_index < len(current_rows):
        normalized["row_index"] = int(row_index)
        normalized["source_row_index"] = int(row_index)
        try:
            col_index = fields.index(field)
        except ValueError:
            col_index = None
        if col_index is not None:
            normalized["column_index"] = int(col_index)
            normalized["col_index"] = int(col_index)
            normalized.setdefault("current_text", current_rows[row_index][col_index])
    return normalized


def _normalize_llm_review_overwrite(item: object, *, issue_id: str) -> dict[str, Any] | None:
    if not isinstance(item, dict):
        return None
    row_id = str(item.get("row_id") or "").strip()
    field = str(item.get("field") or "").strip()
    if not row_id or not field:
        return None
    current_text = _field_value_to_str(item.get("current_text"))
    old_text = item.get("old_text")
    normalized: dict[str, Any] = {
        "issue_id": issue_id,
        "row_id": row_id,
        "field": field,
        "status": str(item.get("status") or "").strip(),
        "current_text": current_text,
        "old_text": _field_value_to_str(old_text if old_text is not None else current_text),
        "new_text": _field_value_to_str(item.get("new_text")),
        "confidence": round(_parse_llm_review_confidence(item.get("confidence")), 4),
        "evidence": str(item.get("evidence") or "").strip(),
        "reason": str(item.get("reason") or "").strip(),
        "source": "llm_review",
    }
    table_id = str(item.get("table_id") or "").strip()
    if table_id:
        normalized["table_id"] = table_id
    page_index = _parse_llm_review_int(item.get("page_index"))
    if page_index is not None:
        normalized["page_index"] = page_index
    return normalized


def _parse_llm_review_response(raw_text: object) -> dict[str, Any] | None:
    payload = _extract_llm_review_json_object(raw_text)
    if not isinstance(payload, dict):
        return None

    if any(key in payload for key in ("rows", "tables", "table_raw", "llm_review")) and "overwrites" not in payload:
        llm_review_payload = payload.get("llm_review") if isinstance(payload.get("llm_review"), dict) else {}
        return {
            "summary": _normalize_llm_review_summary(llm_review_payload or payload.get("summary")),
            "issues": [],
            "overwrites": [],
            "output_payload": payload,
        }

    issues_payload = payload.get("issues")
    if isinstance(issues_payload, dict):
        issues_payload = [issues_payload]
    if not isinstance(issues_payload, list):
        issues_payload = []

    overwrites_payload = payload.get("overwrites")
    if isinstance(overwrites_payload, dict):
        overwrites_payload = [overwrites_payload]
    if not isinstance(overwrites_payload, list):
        overwrites_payload = []

    issues: list[dict[str, Any]] = []
    overwrites: list[dict[str, Any]] = []
    generated_issue_seq = 0

    def _next_issue_id(raw_item: object) -> str:
        nonlocal generated_issue_seq
        if isinstance(raw_item, dict):
            existing = str(raw_item.get("issue_id") or "").strip()
            if existing:
                return existing
        generated_issue_seq += 1
        return f"llm-review-{generated_issue_seq}"

    for item in issues_payload:
        normalized = _normalize_llm_review_issue(item, issue_id=_next_issue_id(item))
        if normalized:
            issues.append(normalized)
    for item in overwrites_payload:
        normalized = _normalize_llm_review_overwrite(item, issue_id=_next_issue_id(item))
        if normalized:
            overwrites.append(normalized)

    return {
        "summary": _normalize_llm_review_summary(payload.get("summary")),
        "issues": issues,
        "overwrites": overwrites,
    }


def _prepare_llm_review_output_payload(
    *,
    payload: dict[str, Any],
    baseline: dict[str, Any],
    template: dict[str, Any],
    pdf_variant_requested: str,
    pdf_variant_used: str,
    pdf_variant_fallback_reason: str | None = None,
) -> dict[str, Any] | None:
    fields = [str(field).strip() for field in (baseline.get("fields") or []) if str(field).strip()]
    if not fields:
        return None
    header = [str(cell or "").strip() for cell in (baseline.get("header") or [])]
    if len(header) < len(fields):
        header.extend([_field_label(field) for field in fields[len(header) :]])
    baseline_rows = _sanitize_revision_rows(rows_payload=baseline.get("rows"), fields=fields)
    current_rows = _sanitize_revision_rows(rows_payload=payload.get("rows"), fields=fields)
    if not current_rows:
        current_rows = _extract_first_pass_rows_from_payload(payload, template)
    if not current_rows:
        return None

    normalized_payload = dict(payload)
    normalized_payload["rows"] = _build_llm_review_payload_rows(fields=fields, rows=current_rows)
    if not isinstance(normalized_payload.get("table_raw"), str) or not str(normalized_payload.get("table_raw") or "").strip():
        normalized_payload["table_raw"] = _build_markdown_table_string(header, current_rows)

    existing_tables = _collect_structured_tables_from_payload(normalized_payload)
    if not existing_tables:
        baseline_table = _collect_structured_tables_from_payload(
            baseline.get("raw_output") if isinstance(baseline.get("raw_output"), dict) else {}
        )
        template_table = baseline_table[0] if baseline_table else {}
        table_id = str(template_table.get("table_id") or "").strip() or "llm_review_table_1"
        page_index = _parse_llm_review_int(template_table.get("page_index"))
        normalized_payload["tables"] = [
            {
                "table_id": table_id,
                "page_index": page_index if page_index is not None else 1,
                "rows": [header, *current_rows],
            }
        ]

    llm_review_payload = normalized_payload.get("llm_review")
    llm_review_payload = dict(llm_review_payload) if isinstance(llm_review_payload, dict) else {}
    summary = _normalize_llm_review_summary(llm_review_payload or normalized_payload.get("summary"))
    status = str(
        llm_review_payload.get("status")
        or summary.get("status")
        or summary.get("review_status")
        or "verified"
    ).strip() or "verified"
    notes = str(llm_review_payload.get("notes") or summary.get("notes") or "").strip()
    needs_more_review = _llm_review_summary_needs_more_review(
        {
            **summary,
            "status": status,
            "needs_more_review": llm_review_payload.get("needs_more_review"),
        }
    )

    row_ids = _resolve_llm_review_row_ids(
        baseline_row_ids=[str(item) for item in (baseline.get("row_ids") or [])],
        row_count=len(current_rows),
    )
    raw_issue_candidates: list[object] = []
    for candidate in (
        llm_review_payload.get("issues"),
        normalized_payload.get("issues"),
        normalized_payload.get("cell_issues"),
    ):
        if isinstance(candidate, list):
            raw_issue_candidates.extend(candidate)
        elif isinstance(candidate, dict):
            raw_issue_candidates.append(candidate)
    normalized_issues: list[dict[str, Any]] = []
    for idx, item in enumerate(raw_issue_candidates, start=1):
        normalized = _normalize_llm_review_output_issue(
            item,
            issue_id=f"llm-review-{idx}",
            fields=fields,
            row_ids=row_ids,
            current_rows=current_rows,
        )
        if normalized:
            normalized_issues.append(normalized)

    issue_by_target = {
        (
            str(issue.get("row_id") or "").strip(),
            str(issue.get("field") or "").strip(),
        ): issue
        for issue in normalized_issues
    }
    applied_overwrites: list[dict[str, Any]] = []
    changed_targets: set[tuple[str, str]] = set()
    for row_index, row in enumerate(current_rows):
        row_id = row_ids[row_index] if row_index < len(row_ids) else f"row-{row_index + 1}"
        baseline_row = baseline_rows[row_index] if row_index < len(baseline_rows) else [""] * len(fields)
        for col_index, field in enumerate(fields):
            old_text = baseline_row[col_index] if col_index < len(baseline_row) else ""
            new_text = row[col_index] if col_index < len(row) else ""
            if old_text == new_text:
                continue
            changed_targets.add((row_id, field))
            issue = issue_by_target.get((row_id, field), {})
            overwrite = {
                "issue_id": str(issue.get("issue_id") or f"llm-review-change-{row_index + 1}-{col_index + 1}").strip(),
                "row_id": row_id,
                "row_index": int(row_index),
                "source_row_index": int(row_index),
                "field": field,
                "column_index": int(col_index),
                "col_index": int(col_index),
                "current_text": old_text,
                "old_text": old_text,
                "new_text": new_text,
                "status": str(issue.get("status") or "").strip(),
                "confidence": round(_parse_llm_review_confidence(issue.get("confidence")), 4),
                "evidence": str(issue.get("evidence") or "").strip(),
                "reason": str(issue.get("reason") or "").strip(),
                "source": "llm_review",
            }
            table_id = str(issue.get("table_id") or "").strip()
            if table_id:
                overwrite["table_id"] = table_id
            page_index = _parse_llm_review_int(issue.get("page_index"))
            if page_index is not None:
                overwrite["page_index"] = page_index
            applied_overwrites.append(overwrite)

    unresolved_issues = [
        issue
        for issue in normalized_issues
        if (str(issue.get("row_id") or "").strip(), str(issue.get("field") or "").strip()) not in changed_targets
    ]
    needs_more_review = bool(needs_more_review or unresolved_issues)
    llm_review_payload.update(
        {
            "status": status,
            "needs_more_review": needs_more_review,
            "notes": notes,
            "issues": unresolved_issues,
            "pdf_variant_requested": pdf_variant_requested,
            "pdf_variant_used": pdf_variant_used,
        }
    )
    if pdf_variant_fallback_reason:
        llm_review_payload["pdf_variant_fallback_reason"] = pdf_variant_fallback_reason
    normalized_payload["cell_issues"] = unresolved_issues
    normalized_payload["llm_review"] = llm_review_payload

    return {
        "summary": {
            **summary,
            "status": status,
            "needs_more_review": needs_more_review,
            "notes": notes,
        },
        "issues": unresolved_issues,
        "applied_overwrites": applied_overwrites,
        "rejected_overwrites": [],
        "rows": current_rows,
        "row_ids": row_ids,
        "output_payload": normalized_payload,
        "needs_more_review": needs_more_review,
    }


def _llm_review_summary_needs_more_review(summary: dict[str, Any] | None) -> bool:
    if not isinstance(summary, dict):
        return False
    direct = summary.get("needs_more_review")
    if isinstance(direct, bool):
        return direct
    status = str(summary.get("status") or summary.get("review_status") or "").strip().lower()
    return status in {"needs_review", "needs_more_review", "review_required", "unresolved"}


def _apply_llm_review_overwrites(
    *,
    fields: list[str],
    rows: list[list[str]],
    row_ids: list[str],
    issues: list[dict[str, Any]],
    overwrites: list[dict[str, Any]],
) -> dict[str, Any]:
    normalized_fields = [str(field).strip() for field in fields if str(field).strip()]
    if not normalized_fields:
        return {
            "rows": [],
            "applied_overwrites": [],
            "rejected_overwrites": [],
            "issues": list(issues or []),
            "needs_more_review": bool(issues),
        }

    updated_rows: list[list[str]] = []
    for row in rows:
        current = [_field_value_to_str(cell) for cell in list(row)[: len(normalized_fields)]]
        if len(current) < len(normalized_fields):
            current.extend([""] * (len(normalized_fields) - len(current)))
        updated_rows.append(current)

    resolved_row_ids: list[str] = []
    for idx in range(len(updated_rows)):
        row_id = str(row_ids[idx] if idx < len(row_ids) else "").strip()
        resolved_row_ids.append(row_id or f"row-{idx + 1}")

    row_index_by_id = {row_id: idx for idx, row_id in enumerate(resolved_row_ids) if row_id}
    field_index = {
        field: idx
        for idx, field in enumerate(normalized_fields)
        if field
    }
    min_confidence = _read_reparse_float_env(
        "OCR_LLM_REVIEW_OVERWRITE_MIN_CONFIDENCE",
        0.75,
        min_value=0.0,
    )
    applied: list[dict[str, Any]] = []
    rejected: list[dict[str, Any]] = []
    applied_issue_ids: set[str] = set()
    applied_targets: set[tuple[str, str]] = set()

    def _issue_with_mapping(item: dict[str, Any], *, reject_reason: str | None = None) -> dict[str, Any]:
        normalized = dict(item)
        row_id = str(item.get("row_id") or "").strip()
        field = str(item.get("field") or "").strip()
        target_row_index = row_index_by_id.get(row_id)
        target_col_index = field_index.get(field)
        if target_row_index is not None:
            normalized["source_row_index"] = int(target_row_index)
            normalized["row_index"] = int(target_row_index)
        if target_col_index is not None:
            normalized["column_index"] = int(target_col_index)
            normalized["col_index"] = int(target_col_index)
        if target_row_index is not None and target_col_index is not None:
            current_value = updated_rows[target_row_index][target_col_index]
            normalized.setdefault("current_text", current_value)
        if reject_reason:
            normalized["reject_reason"] = reject_reason
            normalized["issue_code"] = "overwrite_rejected"
            normalized.setdefault("reason", reject_reason)
            normalized.setdefault("severity", "warning")
        return normalized

    for overwrite in overwrites:
        row_id = str(overwrite.get("row_id") or "").strip()
        field = str(overwrite.get("field") or "").strip()
        reject_reason = ""
        target_row_index = row_index_by_id.get(row_id)
        if target_row_index is None:
            reject_reason = "row_id_not_found"
        target_col_index = field_index.get(field)
        if not reject_reason and target_col_index is None:
            reject_reason = "field_not_found"
        confidence = _parse_llm_review_confidence(overwrite.get("confidence"))
        if not reject_reason and confidence < min_confidence:
            reject_reason = "low_confidence"
        evidence = str(overwrite.get("evidence") or "").strip()
        if not reject_reason and not evidence:
            reject_reason = "missing_evidence"
        current_value = ""
        if not reject_reason and target_row_index is not None and target_col_index is not None:
            current_value = updated_rows[target_row_index][target_col_index]
            old_text = _field_value_to_str(overwrite.get("old_text"))
            if old_text != current_value:
                reject_reason = "old_text_mismatch"
            new_text = _field_value_to_str(overwrite.get("new_text"))
            if not reject_reason and field.startswith("qty.") and new_text and not re.fullmatch(r"\d+", new_text):
                reject_reason = "invalid_quantity_text"
        if reject_reason:
            rejected.append(_issue_with_mapping(overwrite, reject_reason=reject_reason))
            continue
        new_text = _field_value_to_str(overwrite.get("new_text"))
        updated_rows[target_row_index][target_col_index] = new_text
        applied_item = _issue_with_mapping(overwrite)
        applied_item["old_text"] = current_value
        applied_item["new_text"] = new_text
        applied.append(applied_item)
        issue_id = str(overwrite.get("issue_id") or "").strip()
        if issue_id:
            applied_issue_ids.add(issue_id)
        applied_targets.add((row_id, field))

    unresolved_issues: list[dict[str, Any]] = []
    for issue in issues:
        issue_id = str(issue.get("issue_id") or "").strip()
        issue_target = (
            str(issue.get("row_id") or "").strip(),
            str(issue.get("field") or "").strip(),
        )
        if issue_id and issue_id in applied_issue_ids:
            continue
        if issue_target in applied_targets:
            continue
        unresolved_issues.append(_issue_with_mapping(issue))
    unresolved_issues.extend(rejected)

    return {
        "rows": updated_rows,
        "row_ids": resolved_row_ids,
        "applied_overwrites": applied,
        "rejected_overwrites": rejected,
        "issues": unresolved_issues,
        "needs_more_review": bool(unresolved_issues),
    }


def _extract_corrected_pdf_uri_from_payload(payload: dict[str, Any] | None) -> str | None:
    if not isinstance(payload, dict):
        return None
    artifacts = payload.get("page_correction_artifacts")
    receipt = artifacts.get("corrected_pdf_receipt") if isinstance(artifacts, dict) else None
    uri = receipt.get("storage_uri") if isinstance(receipt, dict) else None
    if not isinstance(uri, str) or not uri:
        return None
    combined = payload.get("combined") if isinstance(payload.get("combined"), dict) else {}
    correction = payload.get("page_correction") if isinstance(payload.get("page_correction"), dict) else {}
    claims = {value for value in (
        payload.get("corrected_pdf_uri"), combined.get("corrected_pdf"),
        correction.get("corrected_pdf_uri"), artifacts.get("corrected_pdf_uri"),
    ) if isinstance(value, str) and value}
    if claims and claims != {uri}:
        raise ValueError("corrected_pdf_source_mismatch")
    return uri


def _resolve_llm_review_pdf_bytes(
    *,
    document_uri: str,
    payload: dict[str, Any] | None = None,
    requested_variant: str | None = None,
    selected_pdf_receipt: dict[str, Any] | None = None,
    original_pdf_bytes: bytes | None = None,
) -> tuple[bytes, dict[str, Any]]:
    from src.services.storage_service import load_selected_pdf_bytes, verify_selected_pdf_bytes
    receipt = selected_pdf_receipt if selected_pdf_receipt is not None else processing_start_pdf_receipt()
    if original_pdf_bytes is None:
        original_pdf_bytes = load_selected_pdf_bytes(document_uri, receipt)
    else:
        verify_selected_pdf_bytes(original_pdf_bytes, receipt)
    requested = "raw" if requested_variant is None else str(requested_variant).strip().lower()
    if requested not in {"raw", "corrected"}:
        raise ValueError("selected_pdf_variant_invalid")
    if requested == "corrected":
        corrected_pdf_uri = _extract_corrected_pdf_uri_from_payload(payload)
        artifacts = (payload or {}).get("page_correction_artifacts")
        derived = artifacts.get("corrected_pdf_receipt") if isinstance(artifacts, dict) else None
        if not isinstance(derived, dict) or not corrected_pdf_uri:
            raise ValueError("corrected_pdf_receipt_required")
        if derived.get("storage_uri") != corrected_pdf_uri or derived.get("source_sha256") != receipt.get("sha256"):
            raise ValueError("corrected_pdf_source_mismatch")
        corrected_pdf_bytes = load_selected_pdf_bytes(corrected_pdf_uri, {**derived, "parent": receipt})
        return corrected_pdf_bytes, {
            "requested": requested, "used": "corrected", "fallback_reason": None,
            "corrected_pdf_uri": corrected_pdf_uri,
        }
    return original_pdf_bytes, {
        "requested": requested,
        "used": "raw",
        "fallback_reason": None,
    }


def _resolve_reparse_llm_pdf_bytes(
    *,
    document_uri: str,
    payload: dict[str, Any] | None = None,
    original_pdf_bytes: bytes | None = None,
) -> tuple[bytes, dict[str, Any]]:
    artifacts = (payload or {}).get("page_correction_artifacts")
    declared = artifacts.get("recognition_input") if isinstance(artifacts, dict) else None
    if not isinstance(declared, dict):
        raise ValueError("recognition_input_receipt_required")
    receipt = processing_start_pdf_receipt()
    representation = declared.get("representation")
    if representation == "original_identity":
        if declared.get("receipt") != receipt:
            raise ValueError("recognition_input_source_mismatch")
        variant = "raw"
    elif representation == "corrected":
        if declared.get("receipt") != artifacts.get("corrected_pdf_receipt"):
            raise ValueError("recognition_input_source_mismatch")
        variant = "corrected"
    else:
        raise ValueError("recognition_input_representation_invalid")
    return _resolve_llm_review_pdf_bytes(
        document_uri=document_uri,
        payload=payload,
        requested_variant=variant,
        selected_pdf_receipt=receipt,
        original_pdf_bytes=original_pdf_bytes,
    )


def review_ocr_table_with_llm(
    order_id: str,
    *,
    provider: str | None = None,
    prompt: str | None = None,
    pdf_variant: str | None = None,
):
    synchronous_write_input = _capture_synchronous_cache_write_input(order_id)
    if synchronous_write_input is None:
        return None, "synchronous_input_missing"
    captured_order = synchronous_write_input["input_versions"]["order"]
    facility_id = str(captured_order.get("facility_code") or "").strip() or None
    document_uri = str(captured_order.get("document_uri") or "").strip() or None
    if not facility_id and not document_uri:
        return None, "order_not_found"
    if not facility_id:
        return None, "facility_missing"
    if not document_uri:
        return None, "document_missing"

    payload = synchronous_write_input["evidence"].get("payload_json")
    if not isinstance(payload, dict):
        return None, "ocr_payload_missing"
    facility_config = deepcopy(synchronous_write_input["configured_input"]["facility"])
    template = facility_config["fax_template"]
    if not facility_config:
        return None, "facility_not_found"
    if not isinstance(template, dict):
        return None, "template_unresolved"

    try:
        baseline = _resolve_llm_review_baseline(
            order_id=order_id, payload=payload, template=template,
            synchronous_write_input=synchronous_write_input,
        )
    except _CanonicalOcrProjectionError as exc:
        return None, str(exc)
    baseline_rows = baseline.get("rows") if isinstance(baseline, dict) else []
    baseline_fields = baseline.get("fields") if isinstance(baseline, dict) else []
    baseline_row_ids = baseline.get("row_ids") if isinstance(baseline, dict) else []
    baseline_header = baseline.get("header") if isinstance(baseline, dict) else []
    if not isinstance(baseline_rows, list) or not baseline_rows:
        return None, "rows_empty"
    if not isinstance(baseline_fields, list) or not baseline_fields:
        return None, "fields_empty"

    resolved_provider = _normalize_reparse_provider(provider)
    effective_provider = (
        resolved_provider
        or str(template.get("main_ocr_provider") or os.getenv("OCR_MAIN_PROVIDER") or "gemini").strip().lower()
    )
    if effective_provider not in {"openai", "gemini"}:
        effective_provider = "gemini"

    pdf_bytes, pdf_variant_meta = _resolve_llm_review_pdf_bytes(
        document_uri=document_uri,
        payload=payload,
        requested_variant=pdf_variant,
        selected_pdf_receipt=synchronous_write_input["selected_pdf_receipt"],
    )
    system_prompt, user_prompt = _build_llm_review_prompts(
        provider=effective_provider,
        template=template,
        baseline=baseline,
        pdf_variant_requested=str(pdf_variant_meta.get("requested") or "raw"),
        pdf_variant_used=str(pdf_variant_meta.get("used") or "raw"),
        pdf_variant_fallback_reason=(
            str(pdf_variant_meta.get("fallback_reason")).strip()
            if pdf_variant_meta.get("fallback_reason")
            else None
        ),
        prompt_override=prompt,
    )
    review_template = dict(template)
    review_template["main_ocr_provider"] = effective_provider
    review_template["_force_main_ocr_provider"] = effective_provider
    review_template["llm_quantity_only_mode"] = False
    review_template["main_ocr_row_fields"] = baseline_fields
    if effective_provider == "openai":
        review_template["openai_ocr_enabled"] = True
        review_template["openai_ocr_fallback_provider"] = "disabled"
        review_template["openai_ocr_prompt"] = system_prompt
        review_template["openai_ocr_user_prompt"] = user_prompt
    else:
        review_template["gemini_ocr_enabled"] = True
        review_template["gemini_ocr_fallback_provider"] = "disabled"
        review_template["gemini_ocr_prompt"] = system_prompt
        review_template["gemini_ocr_user_prompt"] = user_prompt
        review_template["gemini_ocr_response_schema"] = _build_llm_review_response_schema(
            [str(field) for field in baseline_fields]
        )

    extracted = extract_fax_data(
        pdf_bytes,
        review_template,
        facility_id=facility_id,
    )
    parsed_review = _parse_llm_review_response(getattr(extracted, "raw_text", None))
    if not isinstance(parsed_review, dict):
        return None, "llm_review_invalid_json"
    provider_debug = extracted.provider_debug if isinstance(extracted.provider_debug, dict) else {}
    model_name = str(provider_debug.get("model") or "").strip() or None
    prepared_payload = None
    if isinstance(parsed_review.get("output_payload"), dict):
        try:
            prepared_payload = _prepare_llm_review_output_payload(
                payload=parsed_review["output_payload"],
                baseline=baseline,
                template=template,
                pdf_variant_requested=str(pdf_variant_meta.get("requested") or "raw"),
                pdf_variant_used=str(pdf_variant_meta.get("used") or "raw"),
                pdf_variant_fallback_reason=(
                    str(pdf_variant_meta.get("fallback_reason")).strip()
                    if pdf_variant_meta.get("fallback_reason")
                    else None
                ),
            )
        except _CanonicalOcrProjectionError as exc:
            return None, str(exc)
        if prepared_payload is None:
            return None, "llm_review_invalid_json"
    if prepared_payload is None:
        prepared_payload = _apply_llm_review_overwrites(
            fields=baseline_fields,
            rows=[list(row) for row in baseline_rows if isinstance(row, list)],
            row_ids=[str(item) for item in baseline_row_ids],
            issues=parsed_review.get("issues") or [],
            overwrites=parsed_review.get("overwrites") or [],
        )
        prepared_payload["summary"] = parsed_review.get("summary") or {}
        prepared_payload["output_payload"] = None
    needs_more_review = bool(
        prepared_payload.get("needs_more_review")
        or _llm_review_summary_needs_more_review(prepared_payload.get("summary"))
    )
    review_mode = "llm_yomitoku_payload_review" if prepared_payload.get("output_payload") else "llm_verify_overwrite"
    review_meta = {
        "review_mode": review_mode,
        "llm_review": {
            "provider": effective_provider,
            "model": model_name,
            "summary": prepared_payload.get("summary") or {},
            "baseline_source": baseline.get("baseline_source"),
            "baseline_revision_id": baseline.get("baseline_revision_id"),
            "issues": prepared_payload.get("issues") or [],
            "proposed_overwrites": prepared_payload.get("applied_overwrites") or parsed_review.get("overwrites") or [],
            "applied_overwrites": prepared_payload.get("applied_overwrites") or [],
            "rejected_overwrites": prepared_payload.get("rejected_overwrites") or [],
            "applied_count": len(prepared_payload.get("applied_overwrites") or []),
            "rejected_count": len(prepared_payload.get("rejected_overwrites") or []),
            "needs_more_review": needs_more_review,
            "pdf_variant_requested": str(pdf_variant_meta.get("requested") or "raw"),
            "pdf_variant_used": str(pdf_variant_meta.get("used") or "raw"),
        },
    }
    if pdf_variant_meta.get("fallback_reason"):
        review_meta["llm_review"]["pdf_variant_fallback_reason"] = str(pdf_variant_meta["fallback_reason"])
    if isinstance(prepared_payload.get("output_payload"), dict):
        review_meta["llm_review"]["output_payload"] = prepared_payload["output_payload"]
    latest_draft = synchronous_write_input.get("draft")
    candidate_rows = prepared_payload.get("rows") or baseline_rows
    candidate_row_ids = prepared_payload.get("row_ids") or baseline_row_ids
    candidate_sheet_json = {
        "fields": list(baseline_fields),
        "header": list(baseline_header),
        "rows": [list(row) for row in candidate_rows if isinstance(row, list)],
        "row_ids": [str(item) for item in candidate_row_ids],
        "ui_mode": "sheet",
        "source": "llm_patch_candidate",
        "warnings": ["llm_patch_needs_review"] if needs_more_review else [],
    }
    latest_evidence = synchronous_write_input["evidence"]
    patch_candidate = patch_candidate_service.persist_patch_candidate(
        order_id=order_id,
        base_draft_id=(latest_draft or {}).get("id") if isinstance(latest_draft, dict) else None,
        base_evidence_run_id=(latest_evidence or {}).get("id") if isinstance(latest_evidence, dict) else None,
        provider=effective_provider,
        model=model_name,
        prompt_preset=None,
        baseline_source=review_meta["llm_review"].get("baseline_source"),
        baseline_revision_id=review_meta["llm_review"].get("baseline_revision_id"),
        candidate_state="proposed",
        summary_json={
            "llm_review": review_meta["llm_review"],
            "pdf_variant_requested": str(pdf_variant_meta.get("requested") or "raw"),
            "pdf_variant_used": str(pdf_variant_meta.get("used") or "raw"),
            "needs_more_review": needs_more_review,
        },
        issues_json=list(review_meta["llm_review"].get("issues") or []),
        patches_json={
            "applied_overwrites": prepared_payload.get("applied_overwrites") or [],
            "rejected_overwrites": prepared_payload.get("rejected_overwrites") or [],
        },
        proposed_draft_sheet_json=candidate_sheet_json,
        synchronous_write_input=synchronous_write_input,
    )
    if patch_candidate is None:
        return None, "llm_patch_candidate_persist_failed"
    try:
        workflow_state_service.refresh_workflow_state(order_id)
    except Exception as exc:  # noqa: BLE001
        logger.warning("Workflow state refresh failed after LLM review candidate persist", order_id=order_id, error=str(exc))
    return {
        "id": order_id,
        "patch_candidate": patch_candidate,
        "latest_patch_candidate_id": patch_candidate.get("id"),
        "draft": get_latest_sheet_draft(order_id, backfill_from_revision=False),
        "workflow_state": get_order_workflow_state(order_id, refresh=False),
        "llm_review": review_meta["llm_review"],
    }, None


def _signed_url_from_uri(uri: str | None) -> str | None:
    if not uri or not isinstance(uri, str):
        return None
    parsed = urlparse(uri)
    if parsed.scheme != "gs":
        return uri
    try:
        return generate_signed_url_from_uri(uri)
    except Exception as exc:  # noqa: BLE001
        logger.warning("Signed URL generation failed", uri=uri, error=str(exc))
        raise ValueError("storage_signed_url_failed") from exc


def _load_job_output(
    job: dict | None,
    label: str,
    *,
    wait_for_recovery: bool = False,
) -> Optional[dict]:
    if not job:
        return None
    output_ref = job.get("output_reference")
    if not output_ref:
        return None
    pending_job = _job_is_pending(job)
    try:
        payload = load_bytes_from_uri(output_ref)
        parsed = json.loads(payload.decode("utf-8"))
        validate_own_pipeline_result(parsed, output_ref)
        return parsed
    except Exception as exc:  # noqa: BLE001
        logger.warning(
            "OCR output load failed",
            job_id=job.get("id"),
            output_reference=output_ref,
            label=label,
            error=str(exc),
        )
        if pending_job or not wait_for_recovery:
            return None
        return _load_pipeline_output_with_retry(output_ref)


def _job_is_pending(job: dict | None) -> bool:
    if not job:
        return False
    status = str(job.get("status") or "").lower()
    if status in {"running", "pending", "queued", "awaiting_output", "recovering"}:
        return True
    error = job.get("error_message")
    if isinstance(error, str) and (
        "read operation timed out" in error.lower()
        or "ocr pipeline output not found" in error.lower()
    ):
        return True
    return False


def _output_is_pending(parsed: dict | None) -> bool:
    return is_ocr_pipeline_output_pending(parsed)


def _payload_has_first_pass_ocr_content(payload: dict | None) -> bool:
    if not isinstance(payload, dict):
        return False
    table_raw = payload.get("table_raw")
    if isinstance(table_raw, str) and table_raw.strip():
        return True
    for key in ("pages", "rows", "table_rows", "tables"):
        value = payload.get(key)
        if isinstance(value, list) and value:
            return True
    return False


def _payload_has_page_artifacts(payload: dict | None) -> bool:
    if not isinstance(payload, dict):
        return False
    pages = payload.get("pages")
    return isinstance(pages, list) and bool(pages)


def _attach_facility_candidates(parsed: dict) -> dict:
    if not isinstance(parsed, dict):
        return parsed
    candidate_texts: list[str] = []
    table_raw = parsed.get("table_raw")
    if isinstance(table_raw, str) and table_raw.strip():
        candidate_texts.append(table_raw)
    pages = parsed.get("pages")
    if isinstance(pages, list):
        for page in pages:
            if not isinstance(page, dict):
                continue
            markdown_text = page.get("markdown_text")
            if isinstance(markdown_text, str) and markdown_text.strip():
                candidate_texts.append(markdown_text)
    if not candidate_texts:
        return parsed
    candidates = config_service.match_facility_candidates("\n".join(candidate_texts))
    if not candidates:
        return parsed
    enriched = dict(parsed)
    enriched["facility_candidates"] = candidates
    return enriched


def _normalize_debug_timestamp(value: object) -> str | None:
    if isinstance(value, datetime):
        return value.isoformat()
    if isinstance(value, str) and value.strip():
        return value.strip()
    return None


def _sync_reparse_debug_from_job_metrics(
    parsed: dict[str, Any],
    job: dict[str, Any] | None,
) -> tuple[dict[str, Any], bool]:
    if not isinstance(parsed, dict) or not isinstance(job, dict):
        return parsed, False
    metrics = job.get("metrics")
    if not isinstance(metrics, dict):
        return parsed, False
    if not any(
        key in metrics
        for key in (
            "before_count",
            "after_count",
            "changed",
            "requested_provider",
            "llm_assist",
            "processing_stage",
            "result_state",
            "confirmed_lines_retained",
        )
    ):
        return parsed, False

    provider_raw = metrics.get("provider") or metrics.get("requested_provider")
    provider = str(provider_raw or "").strip()
    if not provider:
        return parsed, False
    job_status = str(job.get("status") or "").strip().lower()

    debug = parsed.get("_reparse_debug")
    next_debug = dict(debug) if isinstance(debug, dict) else {}
    changed = False

    def _set_value(key: str, value: object) -> None:
        nonlocal changed
        if next_debug.get(key) != value:
            next_debug[key] = value
            changed = True

    updated_at = _normalize_debug_timestamp(job.get("updated_at"))
    if updated_at:
        _set_value("updated_at", updated_at)
    _set_value("provider", provider)

    requested_provider = metrics.get("requested_provider")
    if isinstance(requested_provider, str) and requested_provider.strip():
        _set_value("requested_provider", requested_provider.strip())
    if isinstance(metrics.get("llm_assist"), bool):
        _set_value("llm_assist", bool(metrics.get("llm_assist")))
    if isinstance(metrics.get("changed"), bool):
        _set_value("changed", bool(metrics.get("changed")))
    if isinstance(metrics.get("pdf_variant_used"), str) and metrics.get("pdf_variant_used").strip():
        _set_value("pdf_variant_used", metrics.get("pdf_variant_used").strip())
    if isinstance(metrics.get("pdf_variant_fallback_reason"), str):
        normalized_pdf_variant_reason = metrics.get("pdf_variant_fallback_reason").strip() or None
        _set_value("pdf_variant_fallback_reason", normalized_pdf_variant_reason)
    if isinstance(metrics.get("finish_reason"), str) and metrics.get("finish_reason").strip():
        _set_value("finish_reason", metrics.get("finish_reason").strip())
    if isinstance(metrics.get("truncated_output"), bool):
        _set_value("truncated_output", bool(metrics.get("truncated_output")))
    if isinstance(metrics.get("rows_replaced_with_pipeline"), bool):
        _set_value("rows_replaced_with_pipeline", bool(metrics.get("rows_replaced_with_pipeline")))
    if isinstance(metrics.get("processing_stage"), str):
        normalized_stage = metrics.get("processing_stage").strip().lower() or None
        _set_value("processing_stage", normalized_stage)
    if isinstance(metrics.get("result_state"), str):
        normalized_result_state = metrics.get("result_state").strip().lower() or None
        _set_value("result_state", normalized_result_state)
    if isinstance(metrics.get("confirmed_lines_retained"), bool):
        _set_value("confirmed_lines_retained", bool(metrics.get("confirmed_lines_retained")))
    if isinstance(metrics.get("error"), str):
        normalized_error = metrics.get("error").strip() or None
        _set_value("error", normalized_error)
    elif job_status in {"done", "success"} and next_debug.get("error") not in {None, ""}:
        _set_value("error", None)
    reject_reasons = metrics.get("reject_reasons")
    if isinstance(reject_reasons, list):
        normalized_reasons = [str(item).strip() for item in reject_reasons if str(item).strip()]
        _set_value("reject_reasons", normalized_reasons[:20])
    elif job_status in {"done", "success"} and "reject_reasons" in next_debug:
        _set_value("reject_reasons", [])
    validation_detail = metrics.get("validation_detail")
    if "validation_detail" in metrics:
        normalized_validation_detail = validation_detail if isinstance(validation_detail, dict) else {}
        _set_value("validation_detail", normalized_validation_detail)
    elif job_status in {"done", "success"} and "validation_detail" in next_debug:
        _set_value("validation_detail", {})
    warning_reasons = metrics.get("warning_reasons")
    if isinstance(warning_reasons, list):
        normalized_warning_reasons = [str(item).strip() for item in warning_reasons if str(item).strip()]
        _set_value("warning_reasons", normalized_warning_reasons[:20])
    elif job_status in {"done", "success"} and "warning_reasons" in next_debug:
        _set_value("warning_reasons", [])
    warning_detail = metrics.get("warning_detail")
    if "warning_detail" in metrics:
        normalized_warning_detail = warning_detail if isinstance(warning_detail, dict) else {}
        _set_value("warning_detail", normalized_warning_detail)
    elif job_status in {"done", "success"} and "warning_detail" in next_debug:
        _set_value("warning_detail", {})
    llm_quantity_only_merge = metrics.get("llm_quantity_only_merge")
    if isinstance(llm_quantity_only_merge, dict) and llm_quantity_only_merge:
        _set_value("llm_quantity_only_merge", llm_quantity_only_merge)

    for key in ("row_count", "line_count", "before_count", "after_count"):
        value = metrics.get(key)
        if isinstance(value, (int, float)):
            _set_value(key, int(value))

    if not changed:
        return parsed, False

    enriched = dict(parsed)
    enriched["_reparse_debug"] = next_debug
    return enriched, True


def get_ocr_output(
    order_id: str,
    *,
    persist_cache: bool = False,
    include_legacy_edits: bool = True,
    allow_job_reconcile: bool = False,
):
    if allow_job_reconcile:
        raise LegacyOcrEvidenceFallbackDisabledError(
            "read-time OCR job reconciliation is disabled; use worker or explicit command recovery"
        )
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return None, "order_not_found"
        facility_id = str(order.facility_code or "").strip() or None
    active_evidence_payload = None
    active_evidence_run = None
    active_evidence_payload, active_evidence_run = _load_active_ocr_payload(order_id)
    job = get_latest_order_job(order_id)
    if _job_is_pending(job):
        return None, "ocr_output_pending"
    facility_template = _resolve_order_fax_template(order_id)
    active_evidence_payload = _annotate_payload_with_template_field_schema(
        active_evidence_payload,
        facility_template,
    )
    parsed = None
    order_job_pending = _job_is_pending(job)
    if (
        _payload_has_first_pass_ocr_content(active_evidence_payload)
        or _payload_has_hakodate_output_content(active_evidence_payload, order_id=order_id)
    ):
        parsed = active_evidence_payload
    if parsed is None:
        active_job = job
        if not active_job:
            return None, "ocr_job_not_found"
        if order_job_pending:
            return None, "ocr_output_pending"
        if _job_is_pending(active_job):
            return None, "ocr_output_pending"
        if active_job.get("output_reference"):
            return None, "ocr_evidence_recovery_required"
        return None, "ocr_output_not_found"
    if isinstance(parsed, dict):
        parsed = _sanitize_payload_table_raw(parsed)
        parsed = evidence_manifest_service.ensure_evidence_manifest(parsed)
        parsed = _restore_payload_raw_ocr_surface(
            parsed,
            strip_legacy_surface=not include_legacy_edits,
        )
    if isinstance(parsed, dict):
        parsed = _restore_payload_raw_ocr_surface(
            parsed,
            strip_legacy_surface=not include_legacy_edits,
        )
    metrics_job = job
    if isinstance(parsed, dict):
        parsed, synced = _sync_reparse_debug_from_job_metrics(parsed, metrics_job)
    parsed = evidence_manifest_service.ensure_evidence_manifest(parsed)
    parsed = _attach_facility_candidates(parsed)
    output_template = facility_template if isinstance(facility_template, dict) else None
    if isinstance(parsed, dict) and isinstance(output_template, dict):
        parsed = _annotate_payload_with_template_field_schema(parsed, output_template)
    return parsed, None


def _get_ocr_output_without_legacy_edits(
    order_id: str,
    *,
    persist_cache: bool = False,
):
    try:
        return get_ocr_output(
            order_id,
            persist_cache=persist_cache,
            include_legacy_edits=False,
        )
    except TypeError as exc:
        message = str(exc)
        if "unexpected keyword argument 'include_legacy_edits'" in message:
            try:
                return get_ocr_output(order_id, persist_cache=persist_cache)
            except TypeError as inner_exc:
                inner_message = str(inner_exc)
                if "unexpected keyword argument 'persist_cache'" in inner_message:
                    return get_ocr_output(order_id)
                raise
        raise


def _compact_ocr_preview_tables_for_page(
    page_payload: dict[str, Any],
    payload: dict[str, Any] | None,
) -> list[dict[str, Any]]:
    candidate_tables: list[dict[str, Any]] = []
    raw_tables = page_payload.get("tables")
    if isinstance(raw_tables, list):
        candidate_tables.extend(table for table in raw_tables if isinstance(table, dict))

    if not candidate_tables and isinstance(payload, dict):
        try:
            page_index = int(page_payload.get("page_index") or -1)
        except Exception:
            page_index = -1
        if page_index >= 0:
            for table_payload in _collect_structured_tables_from_payload(payload):
                if not isinstance(table_payload, dict):
                    continue
                try:
                    table_page_index = int(table_payload.get("page_index") or -1)
                except Exception:
                    table_page_index = -1
                if table_page_index == page_index:
                    candidate_tables.append(table_payload)

    compact_tables: list[dict[str, Any]] = []
    seen: set[tuple[str, int]] = set()
    for table_payload in candidate_tables:
        table_id = str(table_payload.get("table_id") or "").strip()
        try:
            table_page_index = int(table_payload.get("page_index") or -1)
        except Exception:
            table_page_index = -1
        dedupe_key = (table_id, table_page_index)
        if table_id and dedupe_key in seen:
            continue
        if table_id:
            seen.add(dedupe_key)
        rows = table_payload.get("rows")
        if not isinstance(rows, list):
            continue
        compact_rows = [list(row) for row in rows[:80] if isinstance(row, list)]
        if len(compact_rows) < 2:
            continue
        compact_tables.append(
            {
                "table_id": table_id or None,
                "page_index": table_payload.get("page_index"),
                "row_count": table_payload.get("row_count"),
                "col_count": table_payload.get("col_count"),
                "rows": compact_rows,
            }
        )
        if len(compact_tables) >= 2:
            break
    return compact_tables


def _describe_hakodate_overlay_blocker(code: object) -> str:
    normalized = str(code or "").strip()
    labels = {
        "hakodate_target_cell_map_missing": "Hakodate target cell map がありません。",
        "hakodate_ocr_evidence_missing": "Hakodate OCR quantity evidence がありません。",
        "hakodate_assignment_unavailable": "Hakodate assignment を生成できませんでした。",
        "hakodate_overlay_render_unavailable": "Hakodate overlay の描画に失敗しました。",
        "template_unresolved": "Hakodate template を解決できませんでした。",
        "facility_missing": "施設設定がないため Hakodate overlay を作れません。",
        "facility_not_found": "施設設定を取得できないため Hakodate overlay を作れません。",
    }
    return labels.get(normalized, normalized or "Hakodate overlay blocker")


def _compact_hakodate_assignment_for_client(assignment: object) -> dict[str, Any] | None:
    if not isinstance(assignment, dict):
        return None
    def _compact_metadata(value: object) -> dict[str, Any]:
        metadata = value if isinstance(value, dict) else {}
        if isinstance(metadata.get("metadata"), dict):
            metadata = metadata["metadata"]
        stats = metadata.get("recognizer_ink_stats") if isinstance(metadata.get("recognizer_ink_stats"), dict) else {}
        truth = metadata.get("truth") if isinstance(metadata.get("truth"), dict) else {}
        compact_truth: dict[str, Any] = {}
        for key in ("row_index", "field"):
            if key in truth:
                compact_truth[key] = truth.get(key)
        compact: dict[str, Any] = {}
        for key in (
            "field_label",
            "ocr_candidate",
            "recognizer_candidate",
            "recognizer_candidate_accepted",
            "source",
        ):
            if key in metadata:
                compact[key] = metadata.get(key)
        compact_stats = {
            key: stats.get(key)
            for key in ("ink_area", "kept_component_count")
            if key in stats
        }
        if compact_stats:
            compact["recognizer_ink_stats"] = compact_stats
        if compact_truth:
            compact["truth"] = compact_truth
        return compact

    def _compact_target_cell(item: object) -> dict[str, Any] | None:
        if not isinstance(item, dict):
            return None
        compact = {
            key: item.get(key)
            for key in (
                "target_cell_id",
                "region_id",
                "sheet_cell",
                "worksheet_row",
                "worksheet_col",
                "semantic_field",
                "field",
                "bbox",
                "center",
                "source",
            )
            if key in item
        }
        metadata = _compact_metadata(item.get("metadata"))
        if metadata:
            compact["metadata"] = metadata
        return compact

    def _compact_assignment_item(item: object) -> dict[str, Any] | None:
        if not isinstance(item, dict):
            return None
        return {
            key: item.get(key)
            for key in (
                "target_cell_id",
                "sheet_cell",
                "worksheet_row",
                "worksheet_col",
                "semantic_field",
                "assigned_value",
                "value_normalized",
                "value_text",
                "assignment_confidence",
                "assignment_state",
            )
            if key in item
        }

    def _compact_sheet_cell(item: object) -> dict[str, Any] | None:
        if not isinstance(item, dict):
            return None
        return {
            key: item.get(key)
            for key in (
                "sheet_cell",
                "worksheet_row",
                "worksheet_col",
                "semantic_field",
                "value_text",
                "value_normalized",
                "assignment_state",
                "assignment_confidence",
                "target_cell_id",
            )
            if key in item
        }

    sheet_output = assignment.get("sheet_output") if isinstance(assignment.get("sheet_output"), dict) else {}
    compact_sheet_output = {
        "blockers": list(sheet_output.get("blockers") or []),
        "warnings": list(sheet_output.get("warnings") or []),
    }
    cells = sheet_output.get("cells")
    if isinstance(cells, dict):
        compact_sheet_output["cells"] = {
            str(key): compact
            for key, value in cells.items()
            if (compact := _compact_sheet_cell(value)) is not None
        }
    target_cells = [
        compact
        for item in list(assignment.get("target_cells") or [])
        if (compact := _compact_target_cell(item)) is not None
    ]
    assignments = [
        compact
        for item in list(assignment.get("assignments") or [])
        if (compact := _compact_assignment_item(item)) is not None
    ]
    return {
        "status": assignment.get("status"),
        "strategy": assignment.get("strategy"),
        "quantity_assignment_strategy": assignment.get("quantity_assignment_strategy"),
        "blockers": list(assignment.get("blockers") or []),
        "warnings": list(assignment.get("warnings") or []),
        "metrics": assignment.get("metrics") if isinstance(assignment.get("metrics"), dict) else {},
        "target_cells": target_cells,
        "assignments": assignments,
        "sheet_output": compact_sheet_output,
    }


def _cache_hakodate_assignment_preview(
    *,
    order_id: str,
    cached_payload: object,
    fingerprint: str,
    assignment: object,
) -> dict[str, Any] | None:
    compact = _compact_hakodate_assignment_for_client(assignment)
    return compact


def _build_hakodate_overlay_preview(
    *,
    order_id: str,
    document_uri: str | None,
) -> dict[str, Any]:
    job_status = get_hakodate_pipeline_job_status(order_id)
    try:
        captured_input = _capture_synchronous_cache_write_input(order_id)
    except ValueError as exc:
        return {"status": "blocked", "blockers": [str(exc)], "overlay_url": None, "job_status": job_status}
    if captured_input is None:
        return {"status": "blocked", "blockers": ["synchronous_input_missing"], "overlay_url": None, "job_status": job_status}
    try:
        cached_payload, evidence_run_id, has_latest_hakodate_evidence = _load_latest_hakodate_overlay_source(order_id, captured_input=captured_input)
    except ocr_evidence_service.SelectedEvidenceRejected as exc:
        return {"status": "blocked", "blockers": [str(exc)], "overlay_url": None, "job_status": job_status}
    if not has_latest_hakodate_evidence:
        return {"status": "blocked", "blockers": ["hakodate_selected_evidence_invalid"], "overlay_url": None, "job_status": job_status}
    assignment, assignment_error = build_order_hakodate_assignment(
        order_id,
        strategy="hakodate",
        allow_artifact_repair=False,
        synchronous_write_input=captured_input,
    )
    if assignment_error:
        blockers = [assignment_error]
        return {
            "status": "blocked",
            "blockers": blockers,
            "message": " / ".join(_describe_hakodate_overlay_blocker(item) for item in blockers),
            "overlay_url": None,
            "job_status": job_status,
        }
    if not isinstance(assignment, dict):
        blockers = ["hakodate_assignment_unavailable"]
        return {
            "status": "blocked",
            "blockers": blockers,
            "message": " / ".join(_describe_hakodate_overlay_blocker(item) for item in blockers),
            "overlay_url": None,
            "job_status": job_status,
        }

    target_cells = assignment.get("target_cells") if isinstance(assignment.get("target_cells"), list) else []
    evidence_records = assignment.get("evidence_records") if isinstance(assignment.get("evidence_records"), list) else []
    required_blockers: list[str] = []
    if not target_cells:
        required_blockers.append("hakodate_target_cell_map_missing")
    if not evidence_records:
        required_blockers.append("hakodate_ocr_evidence_missing")
    if required_blockers:
        return {
            "status": "blocked",
            "blockers": required_blockers,
            "message": " / ".join(_describe_hakodate_overlay_blocker(item) for item in required_blockers),
            "overlay_url": None,
            "assignment": _compact_hakodate_assignment_for_client(assignment),
            "job_status": job_status,
        }

    overlay_fingerprint = _hakodate_overlay_fingerprint(
        target_cells=[
            item
            for item in target_cells
            if isinstance(item, dict)
        ],
        assignments=[
            item
            for item in (assignment.get("assignments") if isinstance(assignment.get("assignments"), list) else [])
            if isinstance(item, dict)
        ],
    )
    refreshed_payload, refreshed_evidence_run_id, refreshed_has_latest_hakodate_evidence = cached_payload, evidence_run_id, has_latest_hakodate_evidence
    refreshed_overlay = (
        refreshed_payload.get("hakodate_overlay")
        if isinstance(refreshed_payload, dict) and isinstance(refreshed_payload.get("hakodate_overlay"), dict)
        else None
    )
    refreshed_overlay_uri = str((refreshed_overlay or {}).get("uri") or "").strip()
    refreshed_overlay_producer = str((refreshed_overlay or {}).get("producer") or "").strip()
    refreshed_overlay_fingerprint = str((refreshed_overlay or {}).get("fingerprint") or "").strip()
    refreshed_overlay_version = str((refreshed_overlay or {}).get("version") or "").strip()
    if (
        refreshed_overlay_uri
        and refreshed_overlay_fingerprint == overlay_fingerprint
        and refreshed_overlay_producer == "hakodate_best_method_pipeline"
        and _hakodate_version_matches_current(
            refreshed_overlay_version,
        )
    ):
        refreshed_overlay_url = _signed_url_from_uri(refreshed_overlay_uri)
        if refreshed_overlay_url:
            compact_assignment = _cache_hakodate_assignment_preview(
                order_id=order_id,
                cached_payload=refreshed_payload,
                fingerprint=overlay_fingerprint,
                assignment=assignment,
            )
            return {
                "status": "ready",
                "blockers": list(assignment.get("blockers") or []),
                "message": "",
                "overlay_uri": refreshed_overlay_uri,
                "overlay_url": refreshed_overlay_url,
                "assignment": compact_assignment,
                "source_evidence_run_id": refreshed_evidence_run_id,
                "latest_hakodate_evidence": refreshed_has_latest_hakodate_evidence,
                "job_status": job_status,
            }
    blockers = ["hakodate_overlay_artifact_missing"]
    return {
        "status": "blocked",
        "blockers": blockers,
        "message": " / ".join(_describe_hakodate_overlay_blocker(item) for item in blockers),
        "overlay_url": None,
        "assignment": _compact_hakodate_assignment_for_client(assignment),
        "source_evidence_run_id": evidence_run_id,
        "latest_hakodate_evidence": has_latest_hakodate_evidence,
        "job_status": job_status,
    }


def get_ocr_pages(
    order_id: str,
    *,
    preview_only: bool = False,
    quantity_assignment_strategy: str | None = None,
):
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return None, "order_not_found"
        message_id = order.message_id
        facility_id = order.facility_code
        document_uri = order.document_uri
        raw_document_id = order.current_document_id
    if not facility_id:
        return None, "facility_unresolved"
    try:
        facility_config = _read_order_authored_facility_config(order_id, facility_id)
        facility_template = facility_config["fax_template"]
    except ValueError as exc:
        return None, str(exc)
    active_evidence_payload = None
    active_evidence_run = None
    active_evidence_payload, active_evidence_run = _load_active_ocr_payload(order_id)
    active_evidence_payload = _annotate_payload_with_template_field_schema(
        active_evidence_payload,
        facility_template,
    )
    job = get_latest_order_job(order_id)
    parsed = None
    parsed_source = ""
    order_job_pending = _job_is_pending(job)
    if _payload_has_page_artifacts(active_evidence_payload):
        parsed = active_evidence_payload
        parsed_source = "active_evidence"
    elif order_job_pending:
        return None, "ocr_output_pending"
    elif job and job.get("output_reference"):
        return None, "ocr_evidence_recovery_required"
    else:
        parsed = None
        parsed_source = "missing"
    if parsed is None:
        if order_job_pending:
            return None, "ocr_output_pending"
        if job and _job_is_pending(job):
            return None, "ocr_output_pending"
        if not document_uri:
            if not job:
                return None, "ocr_job_not_found"
            if job.get("output_reference"):
                return None, "ocr_evidence_recovery_required"
            return None, "ocr_output_not_found"
        if job and job.get("output_reference"):
            return None, "ocr_evidence_recovery_required"
        return None, "ocr_output_not_found"
    if isinstance(parsed, dict) and not _output_is_pending(parsed):
        parsed = evidence_manifest_service.ensure_evidence_manifest(parsed)
    pages_payload = parsed.get("pages")
    pages: list[dict[str, object]] = []
    if isinstance(pages_payload, list):
        for page in pages_payload:
            if not isinstance(page, dict):
                continue
            markdown_text = None
            markdown_uri = page.get("markdown_uri")
            compact_tables = _compact_ocr_preview_tables_for_page(page, parsed if isinstance(parsed, dict) else None)
            if isinstance(markdown_uri, str) and not preview_only:
                try:
                    markdown_text = load_bytes_from_uri(markdown_uri).decode("utf-8")
                except Exception:  # noqa: BLE001
                    markdown_text = None
            ocr_overlay_uri = page.get("ocr_overlay_uri")
            layout_overlay_uri = page.get("layout_overlay_uri")
            figure_uris = page.get("figure_uris") if isinstance(page.get("figure_uris"), list) else []
            signed_ocr_overlay_url = _signed_url_from_uri(ocr_overlay_uri)
            signed_layout_overlay_url = (
                None
                if preview_only
                else _signed_url_from_uri(layout_overlay_uri)
            )
            figure_urls = [] if preview_only else [_signed_url_from_uri(uri) for uri in figure_uris]
            if markdown_text and not preview_only:
                markdown_text = sign_published_figure_references(markdown_text, dict(zip(figure_uris, figure_urls)))
            pages.append(
                {
                    "page_index": page.get("page_index"),
                    "markdown_uri": None if preview_only else markdown_uri,
                    "markdown_text": markdown_text,
                    "ocr_overlay_uri": None if preview_only else ocr_overlay_uri,
                    "ocr_overlay_url": signed_ocr_overlay_url,
                    "layout_overlay_uri": None if preview_only else layout_overlay_uri,
                    "layout_overlay_url": signed_layout_overlay_url,
                    "figure_uris": [] if preview_only else figure_uris,
                    "figure_urls": figure_urls,
                    "tables": compact_tables,
                    "synthetic": bool(page.get("synthetic")) if "synthetic" in page else None,
                    "synthetic_source": page.get("synthetic_source"),
                    "pdf_variant_used": page.get("pdf_variant_used"),
                }
            )
    has_hakodate_output = _payload_has_hakodate_output_content(parsed if isinstance(parsed, dict) else None, order_id=order_id)
    if has_hakodate_output and not pages:
        pages = [
            {
                "page_index": 1,
                "markdown_uri": None,
                "markdown_text": None,
                "ocr_overlay_uri": None,
                "ocr_overlay_url": None,
                "layout_overlay_uri": None,
                "layout_overlay_url": None,
                "figure_uris": [],
                "figure_urls": [],
                "tables": [],
                "synthetic": True,
                "synthetic_source": "hakodate_overlay_only",
                "pdf_variant_used": None,
            }
        ]
    evidence_missing = _ocr_evidence_missing_artifacts(parsed if isinstance(parsed, dict) else None)
    if (not has_hakodate_output and "overlay_pages" in evidence_missing) or not pages:
        return None, "ocr_evidence_recovery_required"
    combined_urls: dict[str, str | None] = {}
    if not preview_only:
        combined = parsed.get("combined") if isinstance(parsed.get("combined"), dict) else {}
        combined_urls = {
            key: _signed_url_from_uri(value) for key, value in combined.items() if isinstance(value, str)
            and key != "raw_pdf"
        }
        if raw_document_id:
            from urllib.parse import quote
            combined_urls["raw_pdf"] = f"/api/orders/{quote(order_id, safe='')}/document?document_id={quote(raw_document_id, safe='')}"
    table_box = None
    table_units = None
    grid_column_edges = None
    grid_row_edges = None
    grid_detection_status = "ready"
    grid_detection_deferred_reason = None
    grid_params = {
        "grid_dpi": 300,
        "grid_line_scale": 30,
        "grid_line_scale_horizontal": 30,
        "grid_line_scale_vertical": 30,
        "grid_line_min_ratio": 0.6,
        "grid_line_merge_gap": 2,
        "grid_line_merge_tolerance": 0.02,
        "grid_expected_columns": 0,
        "grid_qty_gap_tolerance": 0.02,
        "grid_left_date_ratio": 0.2,
    }
    template = facility_template
    if isinstance(template, dict):
        table_box, table_units, grid_column_edges, grid_row_edges = _resolve_ocr_pages_grid_metadata(
            template=template,
            pages=pages,
            existing_table_box=table_box,
            existing_table_units=table_units,
            existing_grid_column_edges=grid_column_edges,
            existing_grid_row_edges=grid_row_edges,
            allow_expensive_detection=False,
        )
        for key in grid_params.keys():
            if key in template:
                grid_params[key] = template.get(key)
    missing_grid_parts: list[str] = []
    if not table_box:
        missing_grid_parts.append("table_box")
    if not grid_column_edges:
        missing_grid_parts.append("grid_column_edges")
    if not grid_row_edges:
        missing_grid_parts.append("grid_row_edges")
    if missing_grid_parts:
        grid_detection_status = "deferred"
        grid_detection_deferred_reason = f"missing_template_grid_metadata:{','.join(missing_grid_parts)}"
    requested_strategy = hakodate_assignment_service.normalize_quantity_assignment_strategy(
        quantity_assignment_strategy or "hakodate"
    )
    hakodate_preview = None
    if requested_strategy == "hakodate":
        hakodate_preview = _build_hakodate_overlay_preview(
            order_id=order_id,
            document_uri=str(document_uri or "").strip() or None,
        )
        hakodate_overlay_url = hakodate_preview.get("overlay_url")
        for page_index, page in enumerate(pages):
            if not isinstance(page, dict):
                continue
            # In Hakodate mode the backend-generated Hakodate overlay is the
            # only preview image source. Do not expose legacy/yomitoku overlay
            # URLs on this endpoint, otherwise old clients can accidentally
            # render the wrong image under the Hakodate UI.
            page["ocr_overlay_uri"] = None
            page["ocr_overlay_url"] = None
            page["hakodate_overlay_url"] = hakodate_overlay_url
            page["hakodate_overlay_uri"] = hakodate_preview.get("overlay_uri")
            page["hakodate_overlay_status"] = hakodate_preview.get("status")
            page["hakodate_overlay_blockers"] = list(hakodate_preview.get("blockers") or [])
            page["hakodate_overlay_message"] = hakodate_preview.get("message")

    page_indexes = [
        int(page.get("page_index"))
        for page in pages
        if isinstance(page, dict) and page.get("page_index") is not None
    ]
    active_page_index = page_indexes[0] if page_indexes else None
    return (
        {
            "order_id": order_id,
            "engine": parsed.get("engine"),
            "template_id": parsed.get("template_id"),
            "facility_id": parsed.get("facility_id"),
            "pages": pages,
            "page_count": len(pages),
            "active_page_index": active_page_index,
            "table_page_index": active_page_index,
            "combined": combined_urls,
            "table_box": table_box,
            "table_units": table_units,
            "grid_column_edges": grid_column_edges,
            "grid_row_edges": grid_row_edges,
            "grid_params": grid_params,
            "grid_detection_status": grid_detection_status,
            "grid_detection_deferred_reason": grid_detection_deferred_reason,
            "quantity_assignment_strategy": requested_strategy,
            "hakodate_overlay_status": hakodate_preview.get("status") if isinstance(hakodate_preview, dict) else None,
            "hakodate_overlay_blockers": (
                list(hakodate_preview.get("blockers") or [])
                if isinstance(hakodate_preview, dict)
                else []
            ),
            "hakodate_overlay_message": hakodate_preview.get("message") if isinstance(hakodate_preview, dict) else None,
            "hakodate_assignment": hakodate_preview.get("assignment") if isinstance(hakodate_preview, dict) else None,
        },
        None,
    )


def _parse_grid_table_box(template: dict[str, Any]) -> list[float] | None:
    raw_box = template.get("grid_table_box") or template.get("table_box")
    if not isinstance(raw_box, list) or len(raw_box) < 4:
        return None
    try:
        return [float(value) for value in raw_box[:4]]
    except (TypeError, ValueError):
        return None


def _parse_grid_edges(template: dict[str, Any], key: str) -> list[float] | None:
    raw_edges = template.get(key)
    if not isinstance(raw_edges, list) or len(raw_edges) < 2:
        return None
    try:
        return [float(value) for value in raw_edges]
    except (TypeError, ValueError):
        return None


def _expected_grid_columns(template: dict[str, Any]) -> int:
    try:
        expected = int(template.get("grid_expected_columns") or 0)
    except (TypeError, ValueError):
        expected = 0
    if expected >= 2:
        return expected
    grid_columns = template.get("grid_columns")
    if isinstance(grid_columns, list) and len(grid_columns) >= 2:
        return len(grid_columns)
    return 0


def _synthesize_grid_column_edges(table_box: list[float] | None, template: dict[str, Any]) -> list[float] | None:
    if not isinstance(table_box, list) or len(table_box) < 4:
        return None
    expected = _expected_grid_columns(template)
    if expected < 2:
        return None
    left = float(table_box[0])
    right = float(table_box[2])
    span = right - left
    if span <= 0:
        return None
    return [left + span * idx / expected for idx in range(expected + 1)]


def _detect_grid_from_page_overlay(
    pages: list[dict[str, object]],
    template: dict[str, Any],
) -> GridDetectionResult | None:
    overlay_candidates: list[str] = []
    for page in pages:
        for key in ("layout_overlay_uri", "ocr_overlay_uri"):
            uri = page.get(key)
            if isinstance(uri, str) and uri:
                overlay_candidates.append(uri)
    for uri in overlay_candidates:
        try:
            overlay_bytes = load_bytes_from_uri(uri)
            detected = detect_table_grid_image(overlay_bytes, template)
        except Exception:  # noqa: BLE001
            detected = None
        if detected:
            return detected
    return None


def _resolve_ocr_pages_grid_metadata(
    *,
    template: dict[str, Any],
    pages: list[dict[str, object]],
    existing_table_box: list[float] | None,
    existing_table_units: str | None,
    existing_grid_column_edges: list[float] | None,
    existing_grid_row_edges: list[float] | None,
    allow_expensive_detection: bool,
) -> tuple[list[float] | None, str | None, list[float] | None, list[float] | None]:
    table_box = existing_table_box or _parse_grid_table_box(template)
    units = existing_table_units
    if not units:
        raw_units = template.get("units")
        if isinstance(raw_units, str) and raw_units:
            units = raw_units
    column_edges = existing_grid_column_edges or _parse_grid_edges(template, "grid_column_edges")
    row_edges = existing_grid_row_edges or _parse_grid_edges(template, "grid_row_edges")

    if table_box and column_edges and row_edges:
        return table_box, units, column_edges, row_edges

    synthesized_edges = _synthesize_grid_column_edges(table_box, template)
    if table_box and synthesized_edges:
        return table_box, units, synthesized_edges, row_edges

    if allow_expensive_detection:
        detected_grid = _detect_grid_from_page_overlay(pages, template)
        if detected_grid:
            return (
                table_box or list(detected_grid.table_box),
                units,
                column_edges or list(detected_grid.column_edges),
                row_edges or list(detected_grid.row_edges),
            )

    return table_box, units, column_edges, row_edges


def _sheet_row_identity(date_value: object, daypart: object, menu_name: object) -> tuple[str, str, str]:
    parsed_date = _normalize_entry_date(date_value)
    date_key = parsed_date.isoformat() if parsed_date else ""
    daypart_key = _normalize_daypart_key(daypart)
    menu_key = _normalize_menu_text(str(menu_name or ""))
    return date_key, daypart_key, menu_key


def _build_sheet_fields_and_indexes(template: dict[str, Any]) -> tuple[list[str], dict[str, int]]:
    fields = _row_fields_from_template(template)
    index_map: dict[str, int] = {}
    for idx, field in enumerate(fields):
        index_map[field] = idx
    return fields, index_map


def _build_sheet_quantity_index(
    fields: list[str],
    *,
    template: dict[str, Any] | None = None,
    include_excluded: bool = True,
) -> dict[tuple[str, str | None], int]:
    quantity_index: dict[tuple[str, str | None], int] = {}
    identities = quantity_field_identities_for_fields(template, fields)
    for idx, field in enumerate(fields):
        if field not in identities:
            continue
        diet, area = identities[field]
        if not include_excluded and _is_excluded_aggregation_diet(diet):
            continue
        quantity_index[(diet, area)] = idx
    return quantity_index


def _validate_sheet_template_fields(fields: list[str], *, template: dict[str, Any] | None = None) -> str | None:
    if not fields:
        return "sheet_fields_not_found"
    seen: set[str] = set()
    quantity_columns = 0
    try:
        identities = quantity_field_identities_for_fields(template, fields)
    except ValueError as exc:
        return str(exc)
    for field in fields:
        token = str(field or "").strip()
        if not token:
            return "sheet_template_field_invalid"
        if token in seen:
            return "sheet_fields_duplicate"
        seen.add(token)
        if token in {"date_mmdd", "date", "daypart", "menu", "menu_name", "remarks", "note"}:
            continue
        if token.startswith("aux."):
            continue
        if _is_hakodate_spacer_sheet_field(token):
            continue
        if token not in identities:
            return "sheet_template_field_invalid"
        quantity_columns += 1
    if quantity_columns <= 0:
        return "sheet_quantity_columns_missing"
    return None


def _numeric_string_add(current: str, qty: float) -> str:
    base = 0.0
    if current:
        try:
            base = float(current)
        except Exception:
            base = 0.0
    value = base + qty
    if float(value).is_integer():
        return str(int(value))
    return str(value)


def _build_rows_from_menu_entries(
    *,
    entries: list[dict],
    fields: list[str],
    field_index: dict[str, int],
    header: list[str] | None = None,
    line_dates: set[date],
    source: str,
    payload_dates: set[date] | None = None,
    payload_row_count: int = 0,
    scope_anchor_date: date | None = None,
) -> tuple[list[dict[str, Any]], str]:
    should_filter_by_line_dates = _source_uses_weekly_menu_shell(source)
    filtered = list(entries)
    if should_filter_by_line_dates:
        scoped_entries = list(entries)
        normalized_line_dates = {item for item in line_dates if isinstance(item, date)}
        normalized_payload_dates = {item for item in (payload_dates or set()) if isinstance(item, date)}
        if normalized_line_dates and normalized_payload_dates:
            anchor_dates = _select_dominant_date_cluster(
                normalized_line_dates | normalized_payload_dates,
                max_gap_days=2,
                min_cluster_size=2,
                min_cluster_share=0.5,
            )
            candidate_entries = _filter_position_menu_entries_by_dates(
                entries,
                anchor_dates or (normalized_line_dates | normalized_payload_dates),
                min_anchor_dates=1,
            )
            if candidate_entries:
                scoped_entries = candidate_entries
        elif normalized_line_dates:
            candidate_entries = _filter_position_menu_entries_by_dates(
                entries,
                normalized_line_dates,
                min_anchor_dates=1,
            )
            if candidate_entries:
                scoped_entries = candidate_entries
        elif normalized_payload_dates:
            candidate_entries = _filter_position_menu_entries_by_dates(
                entries,
                normalized_payload_dates,
                min_anchor_dates=1 if int(payload_row_count or 0) > 0 else 2,
            )
            if candidate_entries:
                scoped_entries = candidate_entries
        if scoped_entries:
            filtered = scoped_entries
    if not filtered:
        return [], source
    date_field = next((field for field in fields if field.startswith("date")), None)
    daypart_field = "daypart" if "daypart" in field_index else None
    menu_field = "menu" if "menu" in field_index else ("menu_name" if "menu_name" in field_index else None)
    helper_semantics = _resolve_helper_column_semantics(fields=fields, header=header)
    slot_label_columns = [
        idx for idx, semantic in helper_semantics.items() if semantic == "slot_label"
    ]
    rows: list[dict[str, Any]] = []
    for idx, entry in enumerate(filtered):
        menu_date = entry.get("menu_date")
        daypart = entry.get("daypart_key")
        canonical_daypart = _normalize_daypart_key(daypart)
        menu_name = str(entry.get("menu_name") or "").strip()
        slot_label = normalize_aux_semantic_display_value(entry.get("category"), "slot_label")
        values = [""] * len(fields)
        if date_field:
            values[field_index[date_field]] = _format_mmdd(menu_date)
        if daypart_field:
            values[field_index[daypart_field]] = canonical_daypart or str(daypart or "")
        if menu_field:
            values[field_index[menu_field]] = menu_name
        if slot_label:
            for col_idx in slot_label_columns:
                if 0 <= col_idx < len(values):
                    values[col_idx] = slot_label
        row_id = hakodate_physical_menu_row_service.physical_row_id_from_entry(entry)
        rows.append(
            {
                "row_id": row_id,
                "physical_menu_row_id": row_id,
                "values": values,
                "identity": _sheet_row_identity(menu_date, daypart, menu_name),
                "sort_key": (
                    menu_date or date.min,
                    _daypart_sort_components(daypart)[0],
                    _daypart_sort_components(daypart)[1],
                    int(entry.get("source_order") or idx),
                    int(entry.get("slot_index") or 0),
                    idx,
                )
                if source.startswith("ocr_table_reconstructed")
                else (
                    int(entry.get("source_order") or idx),
                    int(entry.get("slot_index") or 0),
                    idx,
                )
                if source == "ocr_table"
                else (
                    menu_date or date.min,
                    _daypart_sort_components(daypart)[0],
                    _daypart_sort_components(daypart)[1],
                    int(entry.get("slot_index") or 0),
                    idx,
                ),
            }
        )
    rows.sort(key=lambda item: item.get("sort_key"))
    return rows, source






def _collect_dates_from_sheet_rows(
    rows: list[dict[str, Any]],
    *,
    fields: list[str],
    received_at: datetime,
    explicit_week: str | None = None,
) -> set[date]:
    require_explicit_ingest_week(explicit_week)
    if not rows or not fields:
        return set()
    date_idx = next((idx for idx, field in enumerate(fields) if field.startswith("date")), None)
    if date_idx is None:
        return set()
    dates: set[date] = set()
    for row in rows:
        values = row.get("values")
        if not isinstance(values, list) or date_idx >= len(values):
            continue
        raw = values[date_idx]
        parsed = parse_date_string(raw.isoformat() if isinstance(raw, date) else raw,
            received_at, explicit_week=explicit_week)
        if parsed:
            dates.add(parsed)
    return dates


def _collect_sheet_dates_from_rows(
    rows: list[list[Any]] | None, *, received_at: datetime, fields: list[str],
    explicit_week: str | None = None,
) -> set[date]:
    require_explicit_ingest_week(explicit_week)
    dates: set[date] = set()
    date_indexes = [index for index, field in enumerate(fields) if field.startswith("date")]
    for row in rows or []:
        if not isinstance(row, list):
            continue
        for index in date_indexes:
            if index >= len(row):
                continue
            raw = row[index]
            parsed = parse_date_string(raw.isoformat() if isinstance(raw, date) else raw, received_at, explicit_week=explicit_week)
            if parsed:
                dates.add(parsed)
    return dates


def _materialize_payload_page_markdown_text(payload: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(payload, dict):
        return payload
    pages = payload.get("pages")
    if not isinstance(pages, list):
        return payload
    materialized_pages: list[dict[str, Any]] = []
    payload_changed = False
    for page in pages:
        if not isinstance(page, dict):
            materialized_pages.append(page)
            continue
        page_payload = page
        markdown_text = page.get("markdown_text")
        normalized_text = str(markdown_text).strip() if isinstance(markdown_text, str) else ""
        if not normalized_text:
            markdown_uri = str(page.get("markdown_uri") or "").strip()
            if markdown_uri:
                try:
                    normalized_text = load_bytes_from_uri(markdown_uri).decode("utf-8").strip()
                except Exception:
                    normalized_text = ""
        if normalized_text and normalized_text != str(page.get("markdown_text") or "").strip():
            page_payload = dict(page)
            page_payload["markdown_text"] = normalized_text
            payload_changed = True
        materialized_pages.append(page_payload)
    if not payload_changed:
        return payload
    normalized = dict(payload)
    normalized["pages"] = materialized_pages
    return normalized


def _to_sheet_month_id(value: object) -> str | None:
    return sheet_week_service.to_sheet_month_id(value)


def _sheet_week_month_ids(value: object) -> list[str]:
    return sheet_week_service.sheet_week_month_ids(value)


def _shift_sheet_month_id(month_id: str, delta: int) -> str | None:
    return sheet_week_service.shift_sheet_month_id(month_id, delta)




def _collect_sheet_dates_from_payload(
    payload: dict[str, Any], received_at: datetime, template: dict[str, Any],
    *, explicit_week: str | None = None,
) -> list[date]:
    require_explicit_ingest_week(explicit_week)
    dates: list[date] = []
    seen: set[str] = set()

    def _push(raw: object) -> None:
        parsed = parse_date_string(raw.isoformat() if isinstance(raw, date) else raw,
            received_at, explicit_week=explicit_week)
        if not parsed:
            return
        key = parsed.isoformat()
        if key in seen:
            return
        seen.add(key)
        dates.append(parsed)

    for raw in fax_extractor.date_strings_from_row_source(payload, template):
        _push(raw)
    return dates


def _normalize_table_raw_text(value: str) -> str:
    text = value
    if "\\r\\n" in text or "\\n" in text or "\\r" in text:
        text = text.replace("\\r\\n", "\n").replace("\\n", "\n").replace("\\r", "\n")
    return text


def _extract_markdown_table_blocks(markdown: str) -> tuple[list[str], list[str]]:
    blocks: list[list[str]] = []
    current: list[str] = []
    non_table_lines: list[str] = []
    for raw_line in markdown.splitlines():
        line = raw_line.rstrip("\n")
        stripped = line.strip()
        if stripped.startswith("|"):
            current.append(line)
            continue
        if current:
            blocks.append(current)
            current = []
        if stripped:
            non_table_lines.append(stripped)
    if current:
        blocks.append(current)
    joined_blocks = ["\n".join(block) for block in blocks if len(block) >= 2]
    return joined_blocks, non_table_lines


def _extract_standalone_quantity_candidates(lines: list[str]) -> list[str]:
    if not lines:
        return []
    candidates: list[str] = []
    seen: set[str] = set()
    max_qty = max(_read_sheet_quantity_max_abs(), 1.0)

    for line in lines:
        token = line.strip()
        if not token:
            continue
        token = token.strip("|").strip()
        if not token:
            continue
        # Keep only standalone numeric lines to avoid dates/page numbers/noise.
        if not re.fullmatch(r"[+-]?\d{1,3}(?:\.\d+)?", token):
            continue
        try:
            value = float(token)
        except Exception:
            continue
        if value <= 0 or value > max_qty:
            continue
        normalized = str(int(value)) if value.is_integer() else str(value)
        if normalized in seen:
            continue
        seen.add(normalized)
        candidates.append(normalized)
    return candidates


def _sanitize_payload_table_raw(payload: dict[str, Any]) -> dict[str, Any]:
    payload = _materialize_payload_page_markdown_text(payload)
    if not isinstance(payload, dict):
        return payload
    markdown_candidates: list[str] = []
    table_raw = payload.get("table_raw")
    if isinstance(table_raw, str) and table_raw.strip():
        markdown_candidates.append(_normalize_table_raw_text(table_raw))
    pages = payload.get("pages")
    if isinstance(pages, list):
        for page in pages:
            if not isinstance(page, dict):
                continue
            markdown_text = page.get("markdown_text")
            if isinstance(markdown_text, str) and markdown_text.strip():
                markdown_candidates.append(_normalize_table_raw_text(markdown_text))
    if not markdown_candidates:
        return payload

    table_blocks: list[str] = []
    non_table_lines: list[str] = []
    seen_blocks: set[str] = set()
    for markdown in markdown_candidates:
        current_blocks, current_non_table_lines = _extract_markdown_table_blocks(markdown)
        non_table_lines.extend(current_non_table_lines)
        for block in current_blocks:
            normalized_block = _normalize_table_raw_text(block).strip()
            if not normalized_block or normalized_block in seen_blocks:
                continue
            seen_blocks.add(normalized_block)
            table_blocks.append(normalized_block)
    if not table_blocks:
        return payload

    sanitized = dict(payload)
    joined = "\n\n".join(table_blocks)
    sanitized["table_raw"] = joined
    sanitized["_table_raw_blocks"] = table_blocks
    original_table_raw = str(table_raw or "").strip()
    if joined.strip() != _normalize_table_raw_text(original_table_raw).strip():
        sanitized["table_raw_truncated"] = True
        sanitized["_table_raw_original_chars"] = len(original_table_raw)
        sanitized["_table_raw_non_table_lines"] = non_table_lines[:200]
        candidates = _extract_standalone_quantity_candidates(non_table_lines)
        if candidates:
            sanitized["_table_raw_unstructured_qty"] = candidates[:200]
    return sanitized


def _candidate_daypart_sequences_for_block_count(block_count: int) -> list[list[str]]:
    if block_count <= 0:
        return []
    canonical = ["朝", "昼", "夕"]
    if block_count <= len(canonical):
        candidates = [
            canonical[start : start + block_count]
            for start in range(0, len(canonical) - block_count + 1)
        ]
        if candidates:
            return candidates
    return [[canonical[min(idx, len(canonical) - 1)] for idx in range(block_count)]]


def _choose_canonical_daypart_sequence(
    *,
    supported_by_block: dict[int, str],
    block_count: int,
) -> list[str]:
    candidates = _candidate_daypart_sequences_for_block_count(block_count)
    if not candidates:
        return []

    def _score(sequence: list[str]) -> tuple[int, int]:
        mismatches = 0
        exact_matches = 0
        for block_idx, supported in supported_by_block.items():
            if block_idx >= len(sequence):
                mismatches += 1
                continue
            if sequence[block_idx] == supported:
                exact_matches += 1
            else:
                mismatches += 1
        return mismatches, -exact_matches

    return min(candidates, key=_score)


def _canonicalize_sheet_daypart_rows(
    *,
    rows: list[list[str]] | None,
    fields: list[str] | None,
) -> list[list[str]]:
    normalized_rows = [
        [_field_value_to_str(cell) for cell in row]
        for row in (rows or [])
        if isinstance(row, list)
    ]
    if not normalized_rows or not fields:
        return normalized_rows
    _date_idx, daypart_idx, _menu_idx, _quantity_indexes = _resolve_structural_row_field_indexes(fields)
    if daypart_idx is None:
        return normalized_rows
    for row in normalized_rows:
        if daypart_idx >= len(row):
            continue
        canonical = _canonical_daypart_key(row[daypart_idx])
        if canonical:
            row[daypart_idx] = canonical
    return normalized_rows


def _resolve_helper_column_semantics(
    *,
    fields: list[str] | None,
    header: list[str] | None,
) -> dict[int, str]:
    normalized_fields = [str(field or "").strip() for field in (fields or []) if str(field or "").strip()]
    if not normalized_fields:
        return {}
    normalized_header = [str(cell or "").strip() for cell in (header or [])]
    if len(normalized_header) < len(normalized_fields):
        normalized_header.extend(_field_label(field) for field in normalized_fields[len(normalized_header) :])
    semantics: dict[int, str] = {}
    for idx, field in enumerate(normalized_fields):
        if not _is_aux_sheet_field(field):
            continue
        semantic = classify_aux_header_semantic(normalized_header[idx] if idx < len(normalized_header) else "")
        if semantic:
            semantics[idx] = semantic
    return semantics


def _resolve_block_helper_column_indexes(
    *,
    fields: list[str] | None,
    header: list[str] | None,
) -> dict[int, str]:
    return _resolve_helper_column_semantics(fields=fields, header=header)


def _resolve_semantic_aux_display_value(
    *,
    current_value: object,
    candidate_value: object,
    semantic: str | None,
) -> str:
    normalized_semantic = str(semantic or "").strip().lower()
    if normalized_semantic == "slot_label":
        preserved_value = normalize_aux_semantic_display_value(current_value, normalized_semantic)
        candidate_normalized = normalize_aux_semantic_display_value(candidate_value, normalized_semantic)
        return preserved_value or candidate_normalized
    candidate_text = _field_value_to_str(candidate_value).strip()
    if candidate_text and candidate_text != "-":
        return candidate_text
    return _field_value_to_str(current_value).strip()


def _canonicalize_block_helper_display_rows(
    *,
    rows: list[list[str]] | None,
    fields: list[str] | None,
    header: list[str] | None,
) -> tuple[list[list[str]], dict[str, Any]]:
    normalized_rows = [
        [_field_value_to_str(cell) for cell in row]
        for row in (rows or [])
        if isinstance(row, list)
    ]
    normalized_fields = [str(field or "").strip() for field in (fields or []) if str(field or "").strip()]
    if not normalized_rows or not normalized_fields:
        return normalized_rows, {}
    helper_semantics = _resolve_block_helper_column_indexes(fields=normalized_fields, header=header)
    if not helper_semantics:
        return normalized_rows, {}

    date_idx, daypart_idx, menu_idx, _quantity_indexes = _resolve_structural_row_field_indexes(normalized_fields)
    blocks: list[dict[str, Any]] = []
    current_date_key = ""
    current_daypart_key = ""
    current_block_key: tuple[str, str] | None = None
    for row_idx, row in enumerate(normalized_rows):
        raw_date = row[date_idx] if date_idx is not None and date_idx < len(row) else ""
        raw_daypart = row[daypart_idx] if daypart_idx is not None and daypart_idx < len(row) else ""
        date_key = _normalize_sheet_date_key(raw_date)
        if date_key:
            current_date_key = date_key
        else:
            date_key = current_date_key
        daypart_key = _normalize_daypart_key(raw_daypart)
        if daypart_key:
            current_daypart_key = daypart_key
        else:
            daypart_key = current_daypart_key
        block_key = (date_key, daypart_key)
        if not any(block_key):
            block_key = (f"__row_{row_idx}", "")
        if current_block_key != block_key:
            blocks.append({"key": block_key, "row_indexes": [row_idx]})
            current_block_key = block_key
        else:
            row_indexes = blocks[-1].setdefault("row_indexes", [])
            if isinstance(row_indexes, list):
                row_indexes.append(row_idx)

    reanchors: list[dict[str, Any]] = []
    conflicts: list[dict[str, Any]] = []
    normalized_header = [str(cell or "").strip() for cell in (header or [])]
    if len(normalized_header) < len(normalized_fields):
        normalized_header.extend(_field_label(field) for field in normalized_fields[len(normalized_header) :])
    for col_idx, semantic in helper_semantics.items():
        if semantic != "block_total":
            continue
        field = normalized_fields[col_idx] if col_idx < len(normalized_fields) else f"aux.col_{col_idx}"
        header_text = normalized_header[col_idx] if col_idx < len(normalized_header) else _field_label(field)
        for block in blocks:
            row_indexes = [idx for idx in (block.get("row_indexes") or []) if isinstance(idx, int)]
            if not row_indexes:
                continue
            values_in_block: list[tuple[int, str]] = []
            distinct_values: list[str] = []
            for row_idx in row_indexes:
                row = normalized_rows[row_idx]
                cell_value = _field_value_to_str(row[col_idx] if col_idx < len(row) else "").strip()
                if not cell_value or cell_value == "-":
                    continue
                values_in_block.append((row_idx, cell_value))
                if cell_value not in distinct_values:
                    distinct_values.append(cell_value)
            if not values_in_block:
                continue
            anchor_row_idx = next(
                (
                    row_idx
                    for row_idx in row_indexes
                    if menu_idx is not None
                    and menu_idx < len(normalized_rows[row_idx])
                    and _normalize_sheet_text(normalized_rows[row_idx][menu_idx])
                ),
                row_indexes[0],
            )
            for row_idx in row_indexes:
                row = normalized_rows[row_idx]
                while len(row) <= col_idx:
                    row.append("")
                row[col_idx] = ""
            if len(distinct_values) > 1:
                conflicts.append(
                    {
                        "field": field,
                        "header": header_text,
                        "semantic": semantic,
                        "block_key": list(block.get("key") or []),
                        "row_indexes": row_indexes,
                        "values": distinct_values,
                    }
                )
                continue
            target_row_indexes = [
                row_idx
                for row_idx in row_indexes
                if menu_idx is not None
                and menu_idx < len(normalized_rows[row_idx])
                and _normalize_sheet_text(normalized_rows[row_idx][menu_idx])
            ]
            if not target_row_indexes:
                target_row_indexes = list(row_indexes)
            for target_row_idx in target_row_indexes:
                normalized_rows[target_row_idx][col_idx] = distinct_values[0]
            source_indexes = [row_idx for row_idx, _value in values_in_block]
            if source_indexes != target_row_indexes:
                reanchors.append(
                    {
                        "field": field,
                        "header": header_text,
                        "semantic": semantic,
                        "block_key": list(block.get("key") or []),
                        "source_row_indexes": source_indexes,
                        "target_row_indexes": target_row_indexes,
                        "value": distinct_values[0],
                    }
                )
    return normalized_rows, {
        "helper_reanchor_count": len(reanchors),
        "helper_reanchors": reanchors[:20],
        "helper_conflict_count": len(conflicts),
        "helper_conflicts": conflicts[:20],
    }


def _normalize_block_total_display_value(value: object) -> str:
    text = _field_value_to_str(value).strip()
    if not text or text == "-":
        return ""
    normalized = text.translate(_SHEET_TRANSLATION)
    digit_groups = re.findall(r"\d+", normalized)
    if not digit_groups:
        return ""
    if len(set(digit_groups)) == 1:
        return digit_groups[0]
    return ""


def _collect_existing_block_total_display_values(
    *,
    rows: list[list[str]] | None,
    blocks: list[dict[str, Any]] | None,
    block_total_columns: set[int] | None,
) -> dict[tuple[str, str, int], str]:
    normalized_rows = [list(row) for row in (rows or []) if isinstance(row, list)]
    normalized_blocks = [dict(block) for block in (blocks or []) if isinstance(block, dict)]
    normalized_columns = {int(col_idx) for col_idx in (block_total_columns or set()) if isinstance(col_idx, int)}
    if not normalized_rows or not normalized_blocks or not normalized_columns:
        return {}
    values_by_block: dict[tuple[str, str, int], str] = {}
    for block in normalized_blocks:
        block_key = block.get("key") or ("", "")
        date_key = str(block_key[0] or "")
        daypart_key = str(block_key[1] or "")
        row_indexes = [
            idx
            for idx in (block.get("row_indexes") or [])
            if isinstance(idx, int) and 0 <= idx < len(normalized_rows)
        ]
        if not row_indexes:
            continue
        for col_idx in normalized_columns:
            distinct_values: list[str] = []
            for row_idx in row_indexes:
                row = normalized_rows[row_idx]
                normalized_value = _normalize_block_total_display_value(
                    row[col_idx] if col_idx < len(row) else ""
                )
                if not normalized_value or normalized_value in distinct_values:
                    continue
                distinct_values.append(normalized_value)
            if len(distinct_values) == 1:
                values_by_block[(date_key, daypart_key, int(col_idx))] = distinct_values[0]
    return values_by_block


_BLOCK_TOTAL_DISPLAY_EXCLUDED_DIETS = {
    "no_meat",
    "no_fish",
    "no_fried",
    "change_1",
    "change_2",
    "placeholder",
    "sesame_allergy",
    "forbidden_other",
}


def _block_total_display_contributor_indexes(
    fields: list[str] | None,
    *, template: dict[str, Any] | None = None,
) -> list[int]:
    contributor_indexes: list[int] = []
    normalized_fields = [str(field or "").strip() for field in (fields or []) if str(field or "").strip()]
    identities = quantity_field_identities_for_fields(template, normalized_fields)
    for idx, field in enumerate(normalized_fields):
        identity = identities.get(field)
        if identity is None or identity[0] in _BLOCK_TOTAL_DISPLAY_EXCLUDED_DIETS:
            continue
        contributor_indexes.append(idx)
    return contributor_indexes


def _derive_block_total_display_value_from_rows(
    *,
    rows: list[list[str]] | None,
    contributor_indexes: list[int] | None,
) -> str:
    normalized_rows = [list(row) for row in (rows or []) if isinstance(row, list)]
    if not normalized_rows or not contributor_indexes:
        return ""
    max_total = 0.0
    found_total = False
    for row in normalized_rows:
        row_total = 0.0
        row_has_quantity = False
        for col_idx in contributor_indexes:
            if col_idx < 0 or col_idx >= len(row):
                continue
            parsed = _parse_strict_numeric_cell(row[col_idx])
            if parsed is None:
                continue
            row_total += float(parsed)
            row_has_quantity = True
        if not row_has_quantity:
            continue
        found_total = True
        if row_total > max_total:
            max_total = row_total
    if not found_total or max_total <= 0:
        return ""
    if float(max_total).is_integer():
        return str(int(max_total))
    return str(max_total)


def _build_contiguous_sheet_blocks(
    *,
    rows: list[list[str]] | None,
    fields: list[str] | None,
) -> list[dict[str, Any]]:
    normalized_rows = [
        [_field_value_to_str(cell) for cell in row]
        for row in (rows or [])
        if isinstance(row, list)
    ]
    normalized_fields = [str(field or "").strip() for field in (fields or []) if str(field or "").strip()]
    if not normalized_rows or not normalized_fields:
        return []
    date_idx, daypart_idx, _menu_idx, _quantity_indexes = _resolve_structural_row_field_indexes(normalized_fields)
    blocks: list[dict[str, Any]] = []
    current_date_key = ""
    current_daypart_key = ""
    current_key: tuple[str, str] | None = None
    for row_idx, row in enumerate(normalized_rows):
        raw_date = row[date_idx] if date_idx is not None and date_idx < len(row) else ""
        raw_daypart = row[daypart_idx] if daypart_idx is not None and daypart_idx < len(row) else ""
        date_key = _normalize_sheet_date_key(raw_date)
        if date_key:
            current_date_key = date_key
        else:
            date_key = current_date_key
        daypart_key = _normalize_daypart_key(raw_daypart)
        if daypart_key:
            current_daypart_key = daypart_key
        else:
            daypart_key = current_daypart_key
        block_key = (date_key, daypart_key)
        if current_key != block_key:
            blocks.append({"key": block_key, "row_indexes": [row_idx]})
            current_key = block_key
            continue
        blocks[-1]["row_indexes"].append(row_idx)
    return blocks


def _extract_structured_block_total_sequences_from_payload(
    *,
    payload: dict[str, Any] | None,
    template: dict[str, Any] | None,
    fields: list[str] | None,
    block_total_columns: set[int],
) -> list[dict[str, Any]]:
    if not isinstance(payload, dict) or not isinstance(template, dict):
        return []
    normalized_fields = [str(field or "").strip() for field in (fields or []) if str(field or "").strip()]
    if not normalized_fields or not block_total_columns:
        return []
    date_idx, _daypart_idx, _menu_idx, _quantity_indexes = _resolve_structural_row_field_indexes(normalized_fields)
    if date_idx is None:
        return []

    segments: list[dict[str, Any]] = []
    for table_payload in fax_extractor._collect_structured_tables(payload):
        if not isinstance(table_payload, dict):
            continue
        matrix = None
        raw_rows = table_payload.get("rows")
        if isinstance(raw_rows, list) and raw_rows:
            matrix = fax_extractor._normalize_table_matrix_rows(raw_rows)
        if matrix is None:
            raw_cells = table_payload.get("cells")
            if isinstance(raw_cells, list) and raw_cells:
                matrix = fax_extractor._matrix_from_structured_cells(
                    raw_cells,
                    row_count_hint=table_payload.get("row_count")
                    if isinstance(table_payload.get("row_count"), int)
                    else table_payload.get("n_row"),
                    col_count_hint=table_payload.get("col_count")
                    if isinstance(table_payload.get("col_count"), int)
                    else table_payload.get("n_col"),
                )
        if not matrix:
            continue
        normalized_matrix = fax_extractor._normalize_table_matrix_rows(matrix)
        observed_width = max((len(row) for row in normalized_matrix), default=0)
        if observed_width <= 0:
            continue
        explicit_mapped_indexes = fax_extractor._mapped_indexes_from_template_columns(
            template=template,
            fields=normalized_fields,
            observed_width=observed_width,
        )
        if not explicit_mapped_indexes:
            continue
        explicit_dest_to_source = {
            int(dest_idx): int(source_idx)
            for source_idx, dest_idx in explicit_mapped_indexes.items()
            if isinstance(source_idx, int) and isinstance(dest_idx, int)
        }
        date_source_idx = explicit_dest_to_source.get(int(date_idx))
        block_total_sources = {
            int(col_idx): explicit_dest_to_source.get(int(col_idx))
            for col_idx in block_total_columns
            if explicit_dest_to_source.get(int(col_idx)) is not None
        }
        if date_source_idx is None or not block_total_sources:
            continue

        pending_values_by_column: dict[int, list[str]] = {int(col_idx): [] for col_idx in block_total_sources}
        current_segment: dict[str, Any] | None = None
        for raw_row_index, row in enumerate(normalized_matrix):
            raw_date = row[date_source_idx] if date_source_idx < len(row) else ""
            date_key = _normalize_sheet_date_key(raw_date)
            row_totals = {
                int(col_idx): _normalize_block_total_display_value(
                    row[source_idx] if source_idx is not None and source_idx < len(row) else ""
                )
                for col_idx, source_idx in block_total_sources.items()
            }
            if date_key:
                if current_segment is not None:
                    segments.append(current_segment)
                current_segment = {
                    "raw_date": date_key,
                    "values_by_column": {
                        int(col_idx): list(values)
                        for col_idx, values in pending_values_by_column.items()
                    },
                    "source_row_indexes": [raw_row_index],
                }
                pending_values_by_column = {int(col_idx): [] for col_idx in block_total_sources}
            elif current_segment is None:
                for col_idx, total_value in row_totals.items():
                    if not total_value:
                        continue
                    pending_values = pending_values_by_column.setdefault(int(col_idx), [])
                    if not pending_values or pending_values[-1] != total_value:
                        pending_values.append(total_value)
                continue

            if current_segment is None:
                continue
            current_segment.setdefault("source_row_indexes", []).append(raw_row_index)
            values_by_column = current_segment.setdefault("values_by_column", {})
            for col_idx, total_value in row_totals.items():
                if not total_value:
                    continue
                current_values = values_by_column.setdefault(int(col_idx), [])
                if not current_values or current_values[-1] != total_value:
                    current_values.append(total_value)
        if current_segment is not None:
            segments.append(current_segment)
    return segments


def _overlay_structured_block_total_cells_onto_sheet_row_lists(
    *,
    rows: list[list[str]] | None,
    fields: list[str] | None,
    header: list[str] | None = None,
    raw_payload: dict[str, Any] | None = None,
    template: dict[str, Any] | None = None,
) -> tuple[list[list[str]], dict[str, Any]]:
    normalized_rows = [
        [_field_value_to_str(cell) for cell in row]
        for row in (rows or [])
        if isinstance(row, list)
    ]
    normalized_fields = [str(field or "").strip() for field in (fields or []) if str(field or "").strip()]
    if not normalized_rows or not normalized_fields or not isinstance(raw_payload, dict) or not isinstance(template, dict):
        return normalized_rows, {}
    if isinstance(raw_payload.get("_reparse_recognizer_result"), dict):
        _extract_sheet_rows_from_payload_uncanonicalized(raw_payload, template)
        return normalized_rows, {}
    helper_semantics = _resolve_block_helper_column_indexes(fields=normalized_fields, header=header)
    block_total_columns = {
        idx for idx, semantic in helper_semantics.items() if semantic == "block_total"
    }
    if not block_total_columns:
        return normalized_rows, {}

    canonical_blocks = _build_contiguous_sheet_blocks(rows=normalized_rows, fields=normalized_fields)
    if not canonical_blocks:
        return normalized_rows, {}
    existing_block_values = _collect_existing_block_total_display_values(
        rows=normalized_rows,
        blocks=canonical_blocks,
        block_total_columns=block_total_columns,
    )
    canonical_date_order: list[str] = []
    blocks_by_date: dict[str, list[dict[str, Any]]] = {}
    for block in canonical_blocks:
        block_key = block.get("key") or ("", "")
        date_key = str(block_key[0] or "")
        if not date_key:
            continue
        if date_key not in blocks_by_date:
            blocks_by_date[date_key] = []
            canonical_date_order.append(date_key)
        blocks_by_date[date_key].append(block)
    if not canonical_date_order:
        return normalized_rows, {}

    segments = _extract_structured_block_total_sequences_from_payload(
        payload=raw_payload,
        template=template,
        fields=normalized_fields,
        block_total_columns=block_total_columns,
    )

    assigned_by_date: dict[str, dict[int, list[str]]] = {}
    assignment_trace: list[dict[str, Any]] = []
    next_canonical_index = 0
    for segment in segments:
        raw_date = str(segment.get("raw_date") or "").strip()
        mapped_index: int | None = None
        if raw_date:
            for idx in range(next_canonical_index, len(canonical_date_order)):
                if canonical_date_order[idx] == raw_date:
                    mapped_index = idx
                    break
        if mapped_index is None:
            if next_canonical_index >= len(canonical_date_order):
                break
            mapped_index = next_canonical_index
        canonical_date = canonical_date_order[mapped_index]
        next_canonical_index = mapped_index + 1
        values_by_column = segment.get("values_by_column")
        if not isinstance(values_by_column, dict):
            continue
        assigned_by_date[canonical_date] = {
            int(col_idx): [str(value).strip() for value in values if str(value).strip()]
            for col_idx, values in values_by_column.items()
            if isinstance(values, list)
        }
        assignment_trace.append(
            {
                "raw_date": raw_date,
                "canonical_date": canonical_date,
                "values_by_column": assigned_by_date[canonical_date],
            }
        )

    if not assigned_by_date:
        assigned_by_date = {}

    overlaid_rows = [list(row) for row in normalized_rows]
    for col_idx in block_total_columns:
        for row in overlaid_rows:
            while len(row) <= col_idx:
                row.append("")
            row[col_idx] = ""

    assigned_cell_count = 0
    preserved_assignment_count = 0
    skipped_values: list[dict[str, Any]] = []
    derived_assignment_count = 0
    derived_assignments: list[dict[str, Any]] = []
    preserved_assignments: list[dict[str, Any]] = []
    contributor_indexes = _block_total_display_contributor_indexes(normalized_fields, template=template)
    for canonical_date, date_blocks in blocks_by_date.items():
        assigned_values = assigned_by_date.get(canonical_date) if isinstance(assigned_by_date.get(canonical_date), dict) else {}
        for col_idx in block_total_columns:
            block_values = [
                str(value).strip()
                for value in (assigned_values.get(int(col_idx)) or [])
                if str(value).strip()
            ]
            if len(block_values) > len(date_blocks):
                skipped_values.append(
                    {
                        "canonical_date": canonical_date,
                        "column_index": col_idx,
                        "values": block_values,
                        "block_count": len(date_blocks),
                    }
                )
        for block_index, block in enumerate(date_blocks):
            row_indexes = [
                idx
                for idx in (block.get("row_indexes") or [])
                if isinstance(idx, int) and 0 <= idx < len(overlaid_rows)
            ]
            if not row_indexes:
                continue
            derived_value = _derive_block_total_display_value_from_rows(
                rows=[overlaid_rows[idx] for idx in row_indexes],
                contributor_indexes=contributor_indexes,
            )
            block_key = block.get("key") or ("", "")
            block_date_key = str(block_key[0] or "")
            block_daypart_key = str(block_key[1] or "")
            for col_idx in block_total_columns:
                explicit_values = [
                    str(value).strip()
                    for value in (assigned_values.get(int(col_idx)) or [])
                    if str(value).strip()
                ]
                explicit_value = explicit_values[block_index] if block_index < len(explicit_values) else ""
                preserved_value = existing_block_values.get((block_date_key, block_daypart_key, int(col_idx)), "")
                final_value = explicit_value or derived_value or preserved_value
                if not final_value:
                    continue
                for target_row_index in row_indexes:
                    while len(overlaid_rows[target_row_index]) <= col_idx:
                        overlaid_rows[target_row_index].append("")
                    overlaid_rows[target_row_index][col_idx] = final_value
                if explicit_value:
                    assigned_cell_count += len(row_indexes)
                    continue
                if derived_value:
                    derived_assignment_count += len(row_indexes)
                    derived_assignments.append(
                        {
                            "canonical_date": canonical_date,
                            "block_key": list(block_key),
                            "column_index": col_idx,
                            "value": derived_value,
                            "row_indexes": row_indexes,
                        }
                    )
                    continue
                preserved_assignment_count += len(row_indexes)
                preserved_assignments.append(
                    {
                        "canonical_date": canonical_date,
                        "block_key": list(block_key),
                        "column_index": col_idx,
                        "value": preserved_value,
                        "row_indexes": row_indexes,
                    }
                )

    return overlaid_rows, {
        "structured_block_total_assignment_count": assigned_cell_count,
        "structured_block_total_assignments": assignment_trace[:20],
        "structured_block_total_skipped": skipped_values[:20],
        "derived_block_total_assignment_count": derived_assignment_count,
        "derived_block_total_assignments": derived_assignments[:20],
        "preserved_block_total_assignment_count": preserved_assignment_count,
        "preserved_block_total_assignments": preserved_assignments[:20],
    }


def _sanitize_semantic_sheet_rows(
    *,
    rows_payload: object,
    fields: list[str] | None,
) -> list[list[str]]:
    normalized_fields = [str(field or "").strip() for field in (fields or []) if str(field or "").strip()]
    sanitized: list[list[str]] = []
    if not isinstance(rows_payload, list):
        return sanitized
    for row in rows_payload:
        if not isinstance(row, list):
            continue
        current = [_field_value_to_str(cell) for cell in row]
        if normalized_fields and len(current) < len(normalized_fields):
            current.extend([""] * (len(normalized_fields) - len(current)))
        sanitized.append(current)
    if not sanitized or not normalized_fields or _draft_fields_look_generic(normalized_fields):
        return sanitized
    return _canonicalize_sheet_daypart_rows(rows=sanitized, fields=normalized_fields)




_CanonicalOcrProjectionError = fax_extractor.CanonicalOcrProjectionError


def _extract_sheet_rows_from_payload(payload: dict[str, Any], template: dict[str, Any]) -> list[list[str]]:
    fields = _get_row_fields(template)
    return _canonicalize_sheet_daypart_rows(
        rows=_extract_sheet_rows_from_payload_uncanonicalized(payload, template),
        fields=fields,
    )


def _extract_sheet_rows_from_payload_uncanonicalized(payload: dict[str, Any], template: dict[str, Any]) -> list[list[str]]:
    own_result = payload.get("_reparse_recognizer_result")
    if isinstance(own_result, dict):
        if own_result.get("fields") != _row_fields_from_template(template):
            raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
        own_rows = own_result.get("rows")
        if not isinstance(own_rows, list) or not own_rows or any(
            not isinstance(row, list) or len(row) != len(own_result["fields"])
            for row in own_rows
        ):
            raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
        return deepcopy(own_rows)
    fields = _get_row_fields(template)
    raw_rows = payload.get("rows")
    try:
        structured_tables = fax_extractor._collect_structured_tables(payload)
    except ValueError as exc:
        raise _CanonicalOcrProjectionError(str(exc)) from exc
    if not structured_tables and isinstance(raw_rows, list) and raw_rows:
        # Provider-normalized dictionaries bind quantities by authored field name,
        # not by a physical source-column offset (including sparse row patches).
        if all(isinstance(row, dict) for row in raw_rows):
            if not fields or any(
                "row_index" not in row and not any(
                    field in row or (
                        field.startswith("qty.") and isinstance(row.get("qty"), dict)
                        and field[4:] in row["qty"]
                    )
                    for field in fields
                )
                for row in raw_rows
            ):
                raise _CanonicalOcrProjectionError("sheet_quantity_column_unmapped")
            try:
                indexes = [int(row["row_index"]) for row in raw_rows if "row_index" in row]
            except (ValueError, TypeError):
                raise _CanonicalOcrProjectionError("sheet_canonical_mismatch") from None
            if any(index < 0 for index in indexes) or len(set(indexes)) != len(indexes):
                raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
            semantic_rows = fax_extractor._rows_from_payload(deepcopy(payload), template)
            if not semantic_rows:
                raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
            table_rows = payload.get("table_rows")
            if table_rows is not None and (
                not isinstance(table_rows, list)
                or any(not isinstance(row, list) or len(row) != len(fields) for row in table_rows)
                or [[_field_value_to_str(cell) for cell in row] for row in table_rows] != semantic_rows
            ):
                raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
            return semantic_rows
        if not fields or any(not isinstance(row, list) or len(row) != len(fields) for row in raw_rows):
            raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
        semantic_rows = [[_field_value_to_str(cell) for cell in row] for row in raw_rows]
        table_rows = payload.get("table_rows")
        if table_rows is not None and (
            not isinstance(table_rows, list)
            or any(not isinstance(row, list) or len(row) != len(fields) for row in table_rows)
            or [[_field_value_to_str(cell) for cell in row] for row in table_rows] != semantic_rows
        ):
            raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
        return semantic_rows
    if not structured_tables and payload.get("table_rows"):
        table_rows = payload["table_rows"]
        if not fields or not isinstance(table_rows, list) or any(
            not isinstance(row, list) or len(row) != len(fields) for row in table_rows
        ):
            raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
        return [[_field_value_to_str(cell) for cell in row] for row in table_rows]
    payload = _sanitize_payload_table_raw(payload)
    header = _sheet_header_from_template(fields, template)
    rows = _extract_sheet_rows_from_resolved_column_mapping(payload, template)
    if not rows:
        return []
    normalized_rows = [[_field_value_to_str(cell) for cell in row] for row in rows]
    normalized_rows, _helper_stats = _canonicalize_block_helper_display_rows(
        rows=normalized_rows,
        fields=fields,
        header=header,
    )
    return normalized_rows








def _parse_resolved_column_mapping_pairs(
    payload: dict[str, Any],
    fields: list[str],
) -> list[tuple[int, str]]:
    return fax_extractor._parse_resolved_column_mapping_pairs(payload, fields)






def _overlay_payload_aux_cells_onto_sheet_rows(
    *,
    rows: list[dict[str, Any]] | None,
    fields: list[str] | None,
    header: list[str] | None = None,
    payload_rows: list[list[str]] | None,
    raw_payload: dict[str, Any] | None = None,
    template: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    cloned_rows = [dict(item) for item in (rows or []) if isinstance(item, dict)]
    normalized_fields = [str(field or "").strip() for field in (fields or []) if str(field or "").strip()]
    normalized_payload_rows = [
        [_field_value_to_str(cell) for cell in row]
        for row in (payload_rows or [])
        if isinstance(row, list)
    ]
    if not cloned_rows or not normalized_fields or not normalized_payload_rows:
        return cloned_rows
    normalized_payload_rows, _helper_stats = _canonicalize_block_helper_display_rows(
        rows=normalized_payload_rows,
        fields=normalized_fields,
        header=header,
    )
    aux_columns = [
        idx
        for idx, field in enumerate(normalized_fields)
        if _is_aux_sheet_field(field)
    ]
    if not aux_columns:
        return cloned_rows
    helper_semantics = _resolve_helper_column_semantics(fields=normalized_fields, header=header)
    block_total_columns = {
        idx for idx, semantic in helper_semantics.items() if semantic == "block_total"
    }
    row_mapping, _stage_counts, _mapping_stage = _build_payload_row_mapping_by_menu_priority(
        rows=cloned_rows,
        fields=normalized_fields,
        payload_rows=normalized_payload_rows,
        quantity_index=None,
        template=template,
    )
    if not row_mapping:
        return cloned_rows
    for row_idx, payload_idx in row_mapping.items():
        if row_idx < 0 or row_idx >= len(cloned_rows):
            continue
        if payload_idx < 0 or payload_idx >= len(normalized_payload_rows):
            continue
        values = cloned_rows[row_idx].get("values")
        if not isinstance(values, list):
            values = []
        payload_row = normalized_payload_rows[payload_idx]
        for col_idx in block_total_columns:
            while len(values) <= col_idx:
                values.append("")
            values[col_idx] = ""
        for col_idx in aux_columns:
            while len(values) <= col_idx:
                values.append("")
            semantic = helper_semantics.get(col_idx)
            if semantic == "slot_label":
                candidate_value = payload_row[col_idx] if col_idx < len(payload_row) else ""
                values[col_idx] = _resolve_semantic_aux_display_value(
                    current_value=values[col_idx],
                    candidate_value=candidate_value,
                    semantic=semantic,
                )
                continue
            if col_idx >= len(payload_row):
                continue
            aux_value = _field_value_to_str(payload_row[col_idx]).strip()
            if not aux_value or aux_value == "-":
                continue
            values[col_idx] = aux_value
        cloned_rows[row_idx]["values"] = values
    if isinstance(raw_payload, dict) and isinstance(template, dict):
        normalized_row_lists = [
            list(row.get("values") or [])
            for row in cloned_rows
        ]
        normalized_row_lists, _structured_helper_stats = _overlay_structured_block_total_cells_onto_sheet_row_lists(
            rows=normalized_row_lists,
            fields=normalized_fields,
            header=header,
            raw_payload=raw_payload,
            template=template,
        )
        for row_idx, values in enumerate(normalized_row_lists):
            if row_idx >= len(cloned_rows):
                break
            cloned_rows[row_idx]["values"] = values
    return cloned_rows


def _project_payload_display_cells_onto_sheet_row_lists(
    *,
    rows: list[list[str]] | None,
    fields: list[str] | None,
    header: list[str] | None = None,
    payload_rows: list[list[str]] | None,
    raw_payload: dict[str, Any] | None = None,
    template: dict[str, Any] | None = None,
) -> tuple[list[list[str]], dict[str, int]]:
    normalized_rows = [
        [_field_value_to_str(cell) for cell in row]
        for row in (rows or [])
        if isinstance(row, list)
    ]
    normalized_fields = [str(field or "").strip() for field in (fields or []) if str(field or "").strip()]
    normalized_payload_rows = [
        [_field_value_to_str(cell) for cell in row]
        for row in (payload_rows or [])
        if isinstance(row, list)
    ]
    if not normalized_rows or not normalized_fields or not normalized_payload_rows:
        return normalized_rows, {}
    normalized_payload_rows, _helper_stats = _canonicalize_block_helper_display_rows(
        rows=normalized_payload_rows,
        fields=normalized_fields,
        header=header,
    )
    quantity_index = _build_sheet_quantity_index(normalized_fields, template=template)
    if not quantity_index:
        return normalized_rows, {}
    quantity_columns = sorted(set(quantity_index.values()))
    display_columns = [
        idx
        for idx, field in enumerate(normalized_fields)
        if _is_aux_sheet_field(field) or _is_sheet_note_field(field)
    ]
    if not display_columns:
        return normalized_rows, {}
    helper_semantics = _resolve_block_helper_column_indexes(fields=normalized_fields, header=header)
    block_total_columns = {
        idx for idx, semantic in helper_semantics.items() if semantic == "block_total"
    }
    projected_rows, projection_stats = _project_payload_quantities_onto_sheet_row_lists(
        rows=normalized_rows,
        fields=normalized_fields,
        payload_rows=normalized_payload_rows,
        strict_raw_ocr_only=True,
        template=template,
    )
    resolved_rows: list[list[str]] = []
    for row_idx, row in enumerate(normalized_rows):
        resolved = list(row)
        for col_idx in block_total_columns:
            if 0 <= col_idx < len(resolved):
                resolved[col_idx] = ""
        values = projected_rows[row_idx] if row_idx < len(projected_rows) else None
        if isinstance(values, list):
            for col_idx in display_columns:
                if col_idx >= len(values):
                    continue
                display_value = _field_value_to_str(values[col_idx]).strip()
                if not display_value or display_value == "-":
                    continue
                while len(resolved) <= col_idx:
                    resolved.append("")
                resolved[col_idx] = display_value
        resolved_rows.append(resolved)
    resolved_rows, _structured_helper_stats = _overlay_structured_block_total_cells_onto_sheet_row_lists(
        rows=resolved_rows,
        fields=normalized_fields,
        header=header,
        raw_payload=raw_payload,
        template=template,
    )
    return resolved_rows, projection_stats


def _resolved_quantity_source_target_pairs(
    payload: dict[str, Any],
    fields: list[str],
    template: dict[str, Any],
) -> list[tuple[int, int]]:
    if fields != _get_row_fields(template):
        raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
    # Projection has already resolved physical bindings or semantic field names.
    _extract_sheet_rows_from_payload_uncanonicalized(payload, template)
    return [(idx, idx) for idx, field in enumerate(fields) if field.startswith("qty.")]






def _extract_sheet_rows_from_resolved_column_mapping(
    payload: dict[str, Any],
    template: dict[str, Any],
) -> list[list[str]]:
    return fax_extractor.rows_from_explicit_physical_payload(payload, template)


def _extract_first_pass_rows_from_payload(
    payload: dict[str, Any],
    template: dict[str, Any],
) -> list[list[str]]:
    return _extract_sheet_rows_from_payload(payload, template)




def _resolve_payload_sheet_template(
    payload: dict[str, Any],
    template: dict[str, Any] | None,
    *,
    allow_payload_template_override: bool = True,
) -> dict[str, Any]:
    resolved = template if isinstance(template, dict) else {}
    if not allow_payload_template_override:
        return resolved
    if not isinstance(payload, dict):
        return resolved
    template_id = payload.get("template_id")
    if not isinstance(template_id, str):
        classification = payload.get("classification")
        if isinstance(classification, dict):
            template_id = classification.get("matched_template_id")
    template_id = str(template_id or "").strip()
    if not template_id:
        return resolved
    if resolved.get("template_id") == template_id:
        return resolved
    return resolved


def _collect_structured_tables_from_payload(payload: dict[str, Any] | None) -> list[dict[str, Any]]:
    if not isinstance(payload, dict):
        return []
    if payload.get("pipeline_mode") == "structured_v2":
        try:
            return fax_extractor._collect_structured_tables(payload)
        except ValueError as exc:
            raise _CanonicalOcrProjectionError(str(exc)) from exc
    tables: list[dict[str, Any]] = []
    seen: set[tuple[str, int]] = set()

    def _push(table_payload: object) -> None:
        if not isinstance(table_payload, dict):
            return
        table_id = str(table_payload.get("table_id") or "").strip()
        try:
            page_index = int(table_payload.get("page_index") or -1)
        except Exception:
            page_index = -1
        key = (table_id, page_index)
        if table_id and key in seen:
            return
        if table_id:
            seen.add(key)
        tables.append(table_payload)

    raw_tables = payload.get("tables")
    if isinstance(raw_tables, list):
        for table_payload in raw_tables:
            _push(table_payload)
    pages = payload.get("pages")
    if isinstance(pages, list):
        for page_payload in pages:
            if not isinstance(page_payload, dict):
                continue
            page_tables = page_payload.get("tables")
            if not isinstance(page_tables, list):
                continue
            for table_payload in page_tables:
                _push(table_payload)
    return tables


def _canonical_quantity_cell_issues(
    rows: list[list[str]],
    fields: list[str],
) -> list[dict[str, Any]]:
    issues: list[dict[str, Any]] = []
    for row_index, row in enumerate(rows):
        for column_index, field in enumerate(fields):
            if field != "qty" and not field.startswith("qty."):
                continue
            raw = _field_value_to_str(row[column_index]) if column_index < len(row) else ""
            if not raw.strip() or _parse_strict_numeric_cell(raw) is not None:
                continue
            issues.append({
                "row_index": row_index,
                "column_index": column_index,
                "field": field,
                "issue_code": "review_required",
                "severity": "warning",
                "source": "ocr_payload",
                "raw": raw,
                "value": raw,
            })
    return issues


def _collect_raw_payload_cell_issues(
    payload: dict[str, Any] | None,
    template: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    if not isinstance(payload, dict):
        return []
    candidates: list[object] = []
    for key in ("cell_issues", "yomitoku_cell_issues", "roi_cell_issues"):
        value = payload.get(key)
        if isinstance(value, list):
            candidates.extend(value)
    roi_extraction = payload.get("roi_extraction")
    if isinstance(roi_extraction, dict):
        roi_issues = roi_extraction.get("cell_issues")
        if isinstance(roi_issues, list):
            candidates.extend(roi_issues)
    edited = payload.get("_edited_ocr")
    latest = edited.get("latest") if isinstance(edited, dict) else None
    llm_review = latest.get("llm_review") if isinstance(latest, dict) else None
    if isinstance(llm_review, dict):
        for key in ("issues", "rejected_overwrites"):
            value = llm_review.get(key)
            if isinstance(value, list):
                candidates.extend(value)
    if isinstance(payload.get("_reparse_recognizer_result"), dict):
        _extract_sheet_rows_from_payload_uncanonicalized(payload, template or {})
    else:
        candidates.extend(
            structured_cell_issues_from_payload(
                payload,
                template or {},
                allow_payload_template_override=False,
            )
        )
    if template:
        candidates.extend(_canonical_quantity_cell_issues(
            _extract_sheet_rows_from_payload_uncanonicalized(payload, template),
            _get_row_fields(template),
        ))

    collected: list[dict[str, Any]] = []
    seen: set[str] = set()
    for issue in candidates:
        if not isinstance(issue, dict):
            continue
        try:
            dedupe_key = json.dumps(issue, ensure_ascii=False, sort_keys=True)
        except TypeError:
            dedupe_key = str(issue)
        if dedupe_key in seen:
            continue
        seen.add(dedupe_key)
        collected.append(dict(issue))
    return collected


def _sheet_identity_from_values(
    row: list[str],
    *,
    date_idx: int | None,
    daypart_idx: int | None,
    menu_idx: int | None,
) -> tuple[str, str, str]:
    date_value = row[date_idx] if date_idx is not None and date_idx < len(row) else ""
    daypart_value = row[daypart_idx] if daypart_idx is not None and daypart_idx < len(row) else ""
    menu_value = row[menu_idx] if menu_idx is not None and menu_idx < len(row) else ""
    return _sheet_row_identity(date_value, daypart_value, menu_value)


def _extract_payload_cell_issues(
    payload: dict[str, Any] | None,
    template: dict[str, Any] | None,
) -> list[dict[str, Any]]:
    if not isinstance(payload, dict):
        return []
    template = _resolve_payload_sheet_template(
        payload,
        template,
        allow_payload_template_override=False,
    )
    if not isinstance(template, dict) or not template:
        return []

    raw_issues = _collect_raw_payload_cell_issues(payload, template)
    if not raw_issues:
        return []

    fields, field_index = _build_sheet_fields_and_indexes(template)
    if not fields:
        return []
    payload_rows = _extract_first_pass_rows_from_payload(payload, template)
    date_idx = field_index.get("date_mmdd")
    if date_idx is None:
        date_idx = field_index.get("date")
    daypart_idx = field_index.get("daypart")
    menu_idx = field_index.get("menu")
    if menu_idx is None:
        menu_idx = field_index.get("menu_name")

    issues: list[dict[str, Any]] = []
    for issue in raw_issues:
        if not isinstance(issue, dict):
            continue
        field = str(issue.get("field") or "").strip()
        column_index = issue.get("column_index")
        try:
            resolved_column_index = int(column_index) if column_index is not None else None
        except Exception:
            resolved_column_index = None
        if not field:
            col_key = str(issue.get("col") or "").strip()
            if col_key:
                field = f"qty.{col_key}"
        if field:
            resolved_column_index = field_index.get(field, resolved_column_index)
        if resolved_column_index is None:
            try:
                fallback_column_index = int(column_index) if column_index is not None else -1
            except Exception:
                fallback_column_index = -1
            if 0 <= fallback_column_index < len(fields):
                resolved_column_index = fallback_column_index
        if resolved_column_index is None:
            continue
        if not field and 0 <= resolved_column_index < len(fields):
            field = fields[resolved_column_index]
        try:
            source_row_index = int(
                issue.get("source_row_index")
                if issue.get("source_row_index") is not None
                else issue.get("row_index")
                if issue.get("row_index") is not None
                else -1
            )
        except Exception:
            source_row_index = -1
        source_identity = ("", "", "")
        if 0 <= source_row_index < len(payload_rows):
            source_identity = _sheet_identity_from_values(
                payload_rows[source_row_index],
                date_idx=date_idx,
                daypart_idx=daypart_idx,
                menu_idx=menu_idx,
            )
        normalized = {
            "source_row_index": source_row_index,
            "column_index": resolved_column_index,
            "field": field,
            "issue_code": str(issue.get("issue_code") or issue.get("reason") or "review_required").strip(),
            "severity": str(issue.get("severity") or "warning").strip() or "warning",
            "source": str(issue.get("source") or "ocr_payload").strip() or "ocr_payload",
            "route": str(issue.get("route") or "").strip(),
            "row_key": str(issue.get("row_key") or "").strip(),
            "col": str(issue.get("col") or "").strip(),
            "date_key": source_identity[0],
            "daypart_key": source_identity[1],
            "menu_key": source_identity[2],
        }
        for key in (
            "confidence",
            "votes",
            "value",
            "max_allowed",
            "raw",
            "reason",
            "bbox",
            "text",
            "page_index",
            "table_id",
            "row_span",
            "col_span",
        ):
            if key in issue:
                normalized[key] = issue.get(key)
        raw_texts = issue.get("raw_texts")
        if isinstance(raw_texts, list):
            normalized["raw_texts"] = [str(text) for text in raw_texts if str(text).strip()][:5]
        issues.append(normalized)
    return issues


def _extract_payload_unstructured_quantity_candidates(payload: dict[str, Any] | None) -> list[str]:
    if not isinstance(payload, dict):
        return []
    collected: list[str] = []
    seen: set[str] = set()

    def _push(items: list[str]) -> None:
        for item in items:
            token = str(item or "").strip()
            if not token or token in seen:
                continue
            seen.add(token)
            collected.append(token)

    raw_candidates = payload.get("_table_raw_unstructured_qty")
    if isinstance(raw_candidates, list):
        _push([str(item) for item in raw_candidates if str(item).strip()])

    non_table_lines = payload.get("_table_raw_non_table_lines")
    if isinstance(non_table_lines, list):
        _push(_extract_standalone_quantity_candidates([str(item) for item in non_table_lines]))

    scan_texts: list[str] = []
    for key in ("raw_text", "text", "markdown_text"):
        value = payload.get(key)
        if isinstance(value, str) and value.strip():
            scan_texts.append(value)
    pages = payload.get("pages")
    if isinstance(pages, list):
        for page in pages:
            if not isinstance(page, dict):
                continue
            text = page.get("markdown_text")
            if isinstance(text, str) and text.strip():
                scan_texts.append(text)
    if scan_texts:
        lines: list[str] = []
        for text in scan_texts:
            lines.extend(text.splitlines())
        _push(_extract_standalone_quantity_candidates(lines))
    return collected


def _build_sheet_lines_from_ocr_payload(
    *,
    payload: dict[str, Any],
    template: dict[str, Any],
    received_at: datetime,
    week_id: str | None,
    facility_id: str | None,
    quantity_rules: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    explicit_week = require_explicit_ingest_week(week_id)
    sheet_rows = _extract_first_pass_rows_from_payload(payload, template)
    if not sheet_rows:
        sheet_rows = _extract_sheet_rows_from_payload(payload, template)
    if not sheet_rows:
        return []
    policy = config_service.load_ingest_policy()
    effective_quantity_rules = (
        dict(quantity_rules)
        if isinstance(quantity_rules, dict)
        else dict(policy.get("quantity_rules", {}))
    )
    effective_quantity_rules["rows_are_body_only"] = True
    date_candidates = _collect_sheet_dates_from_payload(payload, received_at, template, explicit_week=explicit_week)
    default_date = min(date_candidates) if date_candidates else None
    lines = parse_order_lines(
        sheet_rows,
        template,
        received_at,
        effective_quantity_rules,
        default_date=default_date,
        tokens=[],
        grid=None,
        pdf_bytes=None,
        date_policy=policy,
        explicit_week=explicit_week,
    )
    if not lines:
        return []
    if week_id:
        # Current-sheet quantities may only use OCR/Gemini/user values when the
        # originating OCR row already carries a usable menu identity. Do not
        # rewrite menu/date/daypart by source-row position or weekly-menu slot
        # order here; that reintroduces non-OCR synthetic quantities.
        min_ratio = float(policy.get("menu_match_min_ratio", 0.72))
        lines = _apply_menu_matching(lines, week_id, facility_id, min_ratio)
    return lines


def _resolve_sheet_week_id(
    *,
    current_week_id: str | None,
    received_at: datetime,
    order_lines: list[dict[str, Any]],
    ocr_payload: dict[str, Any] | None,
    facility_id: str | None,
    week_hints: list[str] | None = None,
) -> str | None:
    if _workflow_ocr_job_id.get() or current_nonworkflow_execution() is not None:
        boundary = current_nonworkflow_execution()
        captured_order_id = _workflow_ocr_order_id.get() or (boundary or {}).get("order_id")
        captured = _captured_reparse_read_input(captured_order_id) if captured_order_id else None
        if captured is None:
            return None
        return _resolve_reparse_own_week(
            captured_week=captured["order"].get("week_code"),
            received_at=received_at, lines=order_lines, own_payload=ocr_payload,
        )
    return _normalize_sheet_week_value(current_week_id)


def _apply_order_line_quantities_to_sheet_rows(
    *,
    rows: list[dict[str, Any]],
    fields: list[str],
    quantity_index: dict[tuple[str, str | None], int],
    order_lines: list[Any],
) -> None:
    def _line_value(line: Any, key: str):
        if isinstance(line, dict):
            return line.get(key)
        return getattr(line, key, None)

    if not rows or not fields:
        return
    has_daypart_field = "daypart" in fields
    note_field = "remarks" if "remarks" in fields else ("note" if "note" in fields else None)
    note_idx = fields.index(note_field) if note_field else None
    lookup_exact: dict[tuple[str, str, str], dict[str, Any]] = {}
    lookup_date_menu: dict[tuple[str, str], dict[str, Any]] = {}
    for row in rows:
        identity = row.get("identity")
        if not isinstance(identity, tuple) or len(identity) != 3:
            continue
        lookup_exact[identity] = row
        lookup_date_menu[(identity[0], identity[2])] = row

    for line in order_lines:
        line_qty_corrected = _line_value(line, "quantity_corrected")
        line_qty_original = _line_value(line, "quantity_original")
        line_diet_type = _line_value(line, "diet_type")
        line_area_id = _line_value(line, "area_id")
        line_date = _line_value(line, "date")
        line_daypart = _line_value(line, "daypart")
        line_menu_name = _line_value(line, "menu_name")
        line_change_note = _line_value(line, "change_note")
        qty = line_qty_corrected if line_qty_corrected is not None else line_qty_original
        if qty is None:
            continue
        try:
            qty_float = float(qty)
        except Exception:
            continue
        diet_key, area_key = authored_quantity_identity(line_diet_type, line_area_id)
        col_idx = _resolve_quantity_column_index(
            quantity_index=quantity_index,
            diet_key=diet_key,
            area_key=area_key,
        )
        if col_idx is None:
            continue
        identity = _sheet_row_identity(line_date, line_daypart, line_menu_name)
        target = lookup_exact.get(identity)
        if not target and not has_daypart_field:
            target = lookup_date_menu.get((identity[0], identity[2]))
        if not target:
            continue
        values = target.get("values")
        if not isinstance(values, list):
            continue
        while len(values) <= col_idx:
            values.append("")
        values[col_idx] = _numeric_string_add(str(values[col_idx] or ""), qty_float)
        if note_idx is not None and line_change_note:
            while len(values) <= note_idx:
                values.append("")
            current_note = str(values[note_idx] or "")
            if line_change_note not in current_note:
                values[note_idx] = (
                    f"{current_note} / {line_change_note}".strip(" /")
                    if current_note
                    else str(line_change_note)
                )






def _count_non_empty_quantity_cells_for_row_indexes(
    *,
    rows: list[dict[str, Any]],
    quantity_index: dict[tuple[str, str | None], int],
    row_indexes: set[int],
) -> int:
    if not rows or not quantity_index or not row_indexes:
        return 0
    quantity_columns = sorted(set(quantity_index.values()))
    count = 0
    for row_idx in sorted(row_indexes):
        if row_idx < 0 or row_idx >= len(rows):
            continue
        values = rows[row_idx].get("values")
        if not isinstance(values, list):
            continue
        for col_idx in quantity_columns:
            if col_idx < len(values) and str(values[col_idx] or "").strip():
                count += 1
    return count


def _count_source_row_alignment_penalty_cells(
    *,
    base_rows: list[dict[str, Any]],
    rows_by_source_index: list[dict[str, Any]],
    fields: list[str],
    quantity_index: dict[tuple[str, str | None], int],
    order_lines: list[Any],
) -> int:
    if not base_rows or not rows_by_source_index or not fields or not quantity_index or not order_lines:
        return 0

    def _line_value(line: Any, key: str):
        if isinstance(line, dict):
            return line.get(key)
        return getattr(line, key, None)

    has_daypart_field = "daypart" in fields
    mismatched_row_indexes: set[int] = set()
    invalid_source_row_penalty = 0
    for line in order_lines:
        qty_corrected = _line_value(line, "quantity_corrected")
        qty_original = _line_value(line, "quantity_original")
        qty = qty_corrected if qty_corrected is not None else qty_original
        if qty is None:
            continue
        try:
            float(qty)
        except Exception:
            continue
        diet_key, area_key = authored_quantity_identity(
            _line_value(line, "diet_type"), _line_value(line, "area_id"),
        )
        if not diet_key:
            continue
        col_idx = _resolve_quantity_column_index(
            quantity_index=quantity_index,
            diet_key=diet_key,
            area_key=area_key,
        )
        if col_idx is None:
            continue
        source_idx_raw = _line_value(line, "source_row_index")
        try:
            source_row_index = int(source_idx_raw) if source_idx_raw is not None else None
        except Exception:
            source_row_index = None
        if source_row_index is None:
            continue
        if source_row_index < 0 or source_row_index >= len(base_rows):
            invalid_source_row_penalty += 1
            continue
        target_identity = base_rows[source_row_index].get("identity")
        if not isinstance(target_identity, tuple) or len(target_identity) != 3:
            continue
        line_identity = _sheet_row_identity(
            _line_value(line, "date"),
            _line_value(line, "daypart"),
            _line_value(line, "menu_name"),
        )
        if not line_identity[0] or not line_identity[2]:
            continue
        if has_daypart_field and not line_identity[1]:
            continue
        same_identity = target_identity == line_identity
        if not same_identity and not has_daypart_field:
            same_identity = target_identity[0] == line_identity[0] and target_identity[2] == line_identity[2]
        if same_identity:
            continue
        mismatched_row_indexes.add(source_row_index)
    return invalid_source_row_penalty + _count_non_empty_quantity_cells_for_row_indexes(
        rows=rows_by_source_index,
        quantity_index=quantity_index,
        row_indexes=mismatched_row_indexes,
    )


def _parse_sheet_fill_decision(value: object) -> bool | None:
    if isinstance(value, bool):
        return bool(value)
    text = str(value or "").strip().lower()
    if not text:
        return None
    if text in {"1", "true", "yes", "allow", "allowed", "approve", "approved", "ok"}:
        return True
    if text in {"0", "false", "no", "deny", "denied", "reject", "rejected"}:
        return False
    return None


def _build_sheet_trace_rows(
    *,
    rows: list[dict[str, Any]],
    fields: list[str],
    quantity_index: dict[tuple[str, str | None], int],
    source: str,
    mapped_mode: str,
    quantity_value_source: str | None = None,
) -> list[list[str]]:
    quantity_columns = set(quantity_index.values())
    source_token = "none"
    if _source_uses_weekly_menu_shell(source):
        source_token = "weekly_menu"
    elif source.startswith("ocr_table"):
        source_token = "ocr_table"

    trace_rows: list[list[str]] = []
    for row in rows:
        values = row.get("values")
        if not isinstance(values, list):
            values = []
        current: list[str] = []
        for col_idx, field in enumerate(fields):
            value = str(values[col_idx] or "").strip() if col_idx < len(values) else ""
            if col_idx in quantity_columns:
                if not value:
                    current.append("none")
                elif mapped_mode == "payload_row":
                    current.append("ocr_payload")
                elif mapped_mode in {"identity", "source_row"} and quantity_value_source in {
                    "order_lines",
                    "ocr_payload",
                }:
                    current.append(str(quantity_value_source))
                else:
                    current.append("unknown")
                continue

            if not value:
                current.append("none")
                continue
            if str(field).startswith("date") or field in {"daypart", "menu", "menu_name"}:
                current.append(source_token)
                continue
            if field in {"remarks", "note"}:
                if mapped_mode == "payload_row":
                    current.append("ocr_payload")
                elif mapped_mode in {"identity", "source_row"} and quantity_value_source in {
                    "order_lines",
                    "ocr_payload",
                }:
                    current.append(str(quantity_value_source))
                else:
                    current.append("unknown")
                continue
            current.append(source_token)
        trace_rows.append(current)
    return trace_rows


def _build_sheet_quantity_cell_metadata_rows(
    *,
    rows: list[dict[str, Any]],
    fields: list[str],
    quantity_index: dict[tuple[str, str | None], int],
    mapped_mode: str,
    quantity_value_source: str | None = None,
    shell_projection_stats: dict[str, Any] | None = None,
) -> tuple[list[list[str]], list[list[str]]]:
    quantity_columns = set(quantity_index.values())
    exact_target_row_indexes = {
        int(item)
        for item in ((shell_projection_stats or {}).get("exact_target_row_indexes") or [])
        if isinstance(item, int) or (isinstance(item, str) and item.isdigit())
    }
    ordered_target_row_indexes = {
        int(item)
        for item in ((shell_projection_stats or {}).get("ordered_target_row_indexes") or [])
        if isinstance(item, int) or (isinstance(item, str) and item.isdigit())
    }

    confidence_rows: list[list[str]] = []
    provenance_rows: list[list[str]] = []
    for row_idx, row in enumerate(rows):
        values = row.get("values")
        if not isinstance(values, list):
            values = []
        confidence_row: list[str] = []
        provenance_row: list[str] = []
        for col_idx, _field in enumerate(fields):
            value = str(values[col_idx] or "").strip() if col_idx < len(values) else ""
            if col_idx not in quantity_columns or not value:
                confidence_row.append("")
                provenance_row.append("")
                continue
            if mapped_mode == "raw_ocr_block":
                if row_idx in exact_target_row_indexes:
                    confidence_row.append("high")
                    provenance_row.append("ocr_payload_exact")
                elif row_idx in ordered_target_row_indexes:
                    confidence_row.append("medium")
                    provenance_row.append("ocr_payload_ordered")
                else:
                    confidence_row.append("low")
                    provenance_row.append("ocr_payload_unresolved")
                continue
            if mapped_mode in {"identity", "source_row"} and quantity_value_source == "ocr_payload":
                confidence_row.append("high")
                provenance_row.append(
                    "ocr_payload_identity" if mapped_mode == "identity" else "ocr_payload_source_row"
                )
                continue
            confidence_row.append("")
            provenance_row.append("")
        confidence_rows.append(confidence_row)
        provenance_rows.append(provenance_row)
    return confidence_rows, provenance_rows


def _empty_ocr_numeric_cell_summary() -> dict[str, int]:
    return {
        "raw_ocr_numeric_count": 0,
        "accepted_count": 0,
        "deterministic_candidate_count": 0,
        "weak_candidate_count": 0,
        "unresolved_count": 0,
    }


def _hakodate_ocr_confidence_tier(confidence: object) -> str:
    score = hakodate_ocr_evidence_service.normalize_ocr_confidence(confidence)
    if score is None:
        return ""
    if score >= 0.90:
        return "high"
    if score >= 0.15:
        return "medium"
    if score >= 0.05:
        return "low"
    return ""


def _hakodate_ocr_classification_for_confidence(confidence: object) -> str:
    tier = _hakodate_ocr_confidence_tier(confidence)
    if tier == "high":
        return "accepted"
    if tier == "medium":
        return "deterministic_candidate"
    if tier == "low":
        return "weak_candidate"
    return "unresolved"


def _hakodate_ocr_placement_basis_for_confidence(confidence: object) -> str:
    classification = _hakodate_ocr_classification_for_confidence(confidence)
    if classification == "accepted":
        return "hakodate_ocr_strict_threshold"
    if classification == "deterministic_candidate":
        return "hakodate_ocr_assisted_threshold"
    if classification == "weak_candidate":
        return "hakodate_ocr_suggestion_threshold"
    return "hakodate_ocr_below_threshold"


def _build_ocr_numeric_cell_item(
    *,
    classification: str,
    value: str,
    confidence_tier: str,
    placement_basis: str,
    read_basis: str,
    source_row_index: int,
    source_col_index: int,
    target_row_index: int | None = None,
    target_col_index: int | None = None,
    date_key: str = "",
    daypart_key: str = "",
    menu_key: str = "",
    reason: str | None = None,
) -> dict[str, Any]:
    item: dict[str, Any] = {
        "classification": str(classification or "").strip(),
        "value": str(value or "").strip(),
        "confidence_tier": str(confidence_tier or "").strip(),
        "placement_basis": str(placement_basis or "").strip(),
        "read_basis": str(read_basis or "").strip(),
        "source_row_index": int(source_row_index),
        "source_col_index": int(source_col_index),
        "date_key": str(date_key or "").strip(),
        "daypart_key": str(daypart_key or "").strip(),
        "menu_key": str(menu_key or "").strip(),
    }
    if target_row_index is not None:
        item["target_row_index"] = int(target_row_index)
    if target_col_index is not None:
        item["target_col_index"] = int(target_col_index)
    if reason:
        item["reason"] = str(reason).strip()
    return item


def _build_payload_numeric_row_items(
    *,
    payload_rows: list[list[str]],
    fields: list[str],
    quantity_columns: list[int],
) -> list[dict[str, Any]]:
    if not payload_rows or not fields or not quantity_columns:
        return []
    date_idx, daypart_idx, menu_idx = _resolve_sheet_field_indexes(fields)
    current_date_key = ""
    group_position_by_date: dict[str, int] = {}
    items: list[dict[str, Any]] = []
    for payload_row_index, payload_row in enumerate(payload_rows):
        if not isinstance(payload_row, list):
            continue
        candidate_date_key = _normalize_sheet_date_key(_safe_row_get(payload_row, date_idx))
        if candidate_date_key:
            current_date_key = candidate_date_key
        raw_daypart = _field_value_to_str(_safe_row_get(payload_row, daypart_idx))
        numeric_cells: list[dict[str, Any]] = []
        for source_col_index in quantity_columns:
            if source_col_index < 0 or source_col_index >= len(payload_row):
                continue
            value = _field_value_to_str(payload_row[source_col_index])
            if _parse_sheet_quantity_cell(value) is None:
                continue
            numeric_cells.append(
                {
                    "source_col_index": int(source_col_index),
                    "value": value,
                }
            )
        if not numeric_cells:
            continue
        date_key = current_date_key
        group_position = int(group_position_by_date.get(date_key, 0))
        group_position_by_date[date_key] = group_position + 1
        items.append(
            {
                "payload_row_index": int(payload_row_index),
                "date_key": date_key,
                "daypart_key": _normalize_daypart_key(raw_daypart),
                "menu_key": _field_value_to_str(_safe_row_get(payload_row, menu_idx)),
                "menu_norm": _normalize_menu_text(_safe_row_get(payload_row, menu_idx)),
                "group_position": group_position,
                "numeric_cells": numeric_cells,
            }
        )
    return items


def _build_weekly_menu_numeric_cell_items(
    *,
    rows: list[dict[str, Any]],
    fields: list[str],
    payload_rows: list[list[str]],
    template: dict[str, Any],
    shell_projection_stats: dict[str, Any] | None = None,
    cell_provenance_rows: list[list[str]] | None = None,
) -> tuple[list[dict[str, Any]], dict[str, int]]:
    summary = _empty_ocr_numeric_cell_summary()
    if not rows or not fields or not payload_rows:
        return [], summary
    quantity_columns = _template_quantity_column_indexes(template)
    if not quantity_columns:
        return [], summary

    payload_items = _build_payload_numeric_row_items(
        payload_rows=payload_rows,
        fields=fields,
        quantity_columns=quantity_columns,
    )
    if not payload_items:
        return [], summary

    summary["raw_ocr_numeric_count"] = sum(
        len(item.get("numeric_cells") or [])
        for item in payload_items
    )
    accepted_mappings_by_payload_row: dict[int, dict[str, Any]] = {}
    for mapping in (shell_projection_stats or {}).get("accepted_payload_mappings") or []:
        if not isinstance(mapping, dict):
            continue
        payload_row_index = mapping.get("payload_row_index")
        target_row_index = mapping.get("target_row_index")
        mapping_type = str(mapping.get("mapping_type") or "").strip()
        if not isinstance(payload_row_index, int) or not isinstance(target_row_index, int):
            continue
        if payload_row_index < 0 or target_row_index < 0:
            continue
        accepted_mappings_by_payload_row[int(payload_row_index)] = {
            "target_row_index": int(target_row_index),
            "mapping_type": mapping_type or "exact",
        }

    lookup_exact: dict[tuple[str, str, str], int] = {}
    lookup_date_menu: dict[tuple[str, str], list[int]] = {}
    date_idx, daypart_idx, menu_idx = _resolve_sheet_field_indexes(fields)
    shell_groups = _build_weekly_menu_shell_date_groups(rows=rows, fields=fields)
    shell_group_by_date = {
        str(group.get("date_key") or ""): group
        for group in shell_groups
        if str(group.get("date_key") or "").strip()
    }
    for row_index, row in enumerate(rows):
        values = row.get("values")
        if not isinstance(values, list):
            continue
        identity = (
            _normalize_sheet_date_key(_safe_row_get(values, date_idx)),
            _normalize_daypart_key(_safe_row_get(values, daypart_idx)),
            _normalize_menu_text(_safe_row_get(values, menu_idx)),
        )
        if not any(identity):
            continue
        lookup_exact[identity] = int(row_index)
        if identity[0] and identity[2]:
            lookup_date_menu.setdefault((identity[0], identity[2]), []).append(int(row_index))

    classified_source_cells: set[tuple[int, int]] = set()
    reserved_overlay_targets: set[tuple[int, int]] = set()
    classified_target_cells: set[tuple[int, int]] = set()
    items: list[dict[str, Any]] = []

    def _append_item(
        *,
        payload_item: dict[str, Any],
        numeric_cell: dict[str, Any],
        classification: str,
        confidence_tier: str,
        placement_basis: str,
        target_row_index: int | None = None,
        reason: str | None = None,
    ) -> None:
        payload_row_index = int(payload_item.get("payload_row_index") or 0)
        source_col_index = int(numeric_cell.get("source_col_index") or 0)
        source_key = (payload_row_index, source_col_index)
        if source_key in classified_source_cells:
            return
        target_col_index = source_col_index
        resolved_classification = classification
        resolved_target_row_index = target_row_index
        resolved_reason = str(reason or "").strip() or None
        if resolved_classification in {"deterministic_candidate", "weak_candidate"}:
            if resolved_target_row_index is None:
                resolved_classification = "unresolved"
                resolved_reason = resolved_reason or "target_row_missing"
            elif not (0 <= resolved_target_row_index < len(rows)):
                resolved_classification = "unresolved"
                resolved_target_row_index = None
                resolved_reason = resolved_reason or "target_row_out_of_range"
            else:
                values = rows[resolved_target_row_index].get("values")
                current_value = _field_value_to_str(_safe_row_get(values, target_col_index))
                if current_value:
                    resolved_classification = "unresolved"
                    resolved_target_row_index = None
                    resolved_reason = resolved_reason or "target_cell_occupied"
                elif (resolved_target_row_index, target_col_index) in reserved_overlay_targets:
                    resolved_classification = "unresolved"
                    resolved_target_row_index = None
                    resolved_reason = resolved_reason or "overlay_target_conflict"
                else:
                    reserved_overlay_targets.add((resolved_target_row_index, target_col_index))
        item = _build_ocr_numeric_cell_item(
            classification=resolved_classification,
            value=str(numeric_cell.get("value") or ""),
            confidence_tier=confidence_tier,
            placement_basis=placement_basis,
            read_basis="direct_payload_numeric_cell",
            source_row_index=payload_row_index,
            source_col_index=source_col_index,
            target_row_index=resolved_target_row_index,
            target_col_index=target_col_index if resolved_target_row_index is not None else None,
            date_key=str(payload_item.get("date_key") or ""),
            daypart_key=str(payload_item.get("daypart_key") or ""),
            menu_key=str(payload_item.get("menu_norm") or payload_item.get("menu_key") or ""),
            reason=resolved_reason,
        )
        items.append(item)
        classified_source_cells.add(source_key)
        if resolved_target_row_index is not None and target_col_index is not None:
            classified_target_cells.add((resolved_target_row_index, target_col_index))
        summary_key = (
            "accepted_count"
            if resolved_classification == "accepted"
            else "deterministic_candidate_count"
            if resolved_classification == "deterministic_candidate"
            else "weak_candidate_count"
            if resolved_classification == "weak_candidate"
            else "unresolved_count"
        )
        summary[summary_key] += 1

    for payload_item in payload_items:
        payload_row_index = int(payload_item.get("payload_row_index") or 0)
        accepted_mapping = accepted_mappings_by_payload_row.get(payload_row_index)
        if accepted_mapping:
            mapping_type = str(accepted_mapping.get("mapping_type") or "exact").strip()
            confidence_tier = "high" if mapping_type == "exact" else "medium"
            placement_basis = "weekly_menu_exact" if mapping_type == "exact" else "weekly_menu_ordered"
            for numeric_cell in payload_item.get("numeric_cells") or []:
                _append_item(
                    payload_item=payload_item,
                    numeric_cell=numeric_cell,
                    classification="accepted",
                    confidence_tier=confidence_tier,
                    placement_basis=placement_basis,
                    target_row_index=int(accepted_mapping.get("target_row_index") or 0),
                )
            continue

        date_key = str(payload_item.get("date_key") or "")
        daypart_key = str(payload_item.get("daypart_key") or "")
        menu_norm = str(payload_item.get("menu_norm") or "")
        exact_target_row_index: int | None = None
        date_menu_target_row_index: int | None = None
        weak_target_row_index_by_col: dict[int, int] = {}
        if date_key and menu_norm:
            exact_target_row_index = lookup_exact.get((date_key, daypart_key, menu_norm))
            date_menu_candidates = lookup_date_menu.get((date_key, menu_norm)) or []
            if len(date_menu_candidates) == 1:
                date_menu_target_row_index = int(date_menu_candidates[0])
        shell_group = shell_group_by_date.get(date_key)
        shell_group_row_indexes = [
            int(item)
            for item in (shell_group or {}).get("row_indexes") or []
            if isinstance(item, int) and 0 <= item < len(rows)
        ]
        for numeric_cell in payload_item.get("numeric_cells") or []:
            source_col_index = int(numeric_cell.get("source_col_index") or 0)
            numeric_value = _field_value_to_str(numeric_cell.get("value"))
            current_exact_value = (
                _field_value_to_str(_safe_row_get(rows[exact_target_row_index].get("values"), source_col_index))
                if exact_target_row_index is not None and 0 <= exact_target_row_index < len(rows)
                else ""
            )
            current_date_menu_value = (
                _field_value_to_str(_safe_row_get(rows[date_menu_target_row_index].get("values"), source_col_index))
                if date_menu_target_row_index is not None and 0 <= date_menu_target_row_index < len(rows)
                else ""
            )
            if exact_target_row_index is not None and current_exact_value == numeric_value and numeric_value:
                _append_item(
                    payload_item=payload_item,
                    numeric_cell=numeric_cell,
                    classification="accepted",
                    confidence_tier="high",
                    placement_basis="identity_current_match",
                    target_row_index=exact_target_row_index,
                )
                continue
            if (
                exact_target_row_index is None
                and date_menu_target_row_index is not None
                and current_date_menu_value == numeric_value
                and numeric_value
            ):
                _append_item(
                    payload_item=payload_item,
                    numeric_cell=numeric_cell,
                    classification="accepted",
                    confidence_tier="medium",
                    placement_basis="date_menu_current_match",
                    target_row_index=date_menu_target_row_index,
                )
                continue
            if exact_target_row_index is not None:
                _append_item(
                    payload_item=payload_item,
                    numeric_cell=numeric_cell,
                    classification="deterministic_candidate",
                    confidence_tier="medium",
                    placement_basis="identity_unique",
                    target_row_index=exact_target_row_index,
                )
                continue
            if date_menu_target_row_index is not None:
                _append_item(
                    payload_item=payload_item,
                    numeric_cell=numeric_cell,
                    classification="deterministic_candidate",
                    confidence_tier="medium",
                    placement_basis="date_menu_unique",
                    target_row_index=date_menu_target_row_index,
                )
                continue
            if source_col_index not in weak_target_row_index_by_col and shell_group_row_indexes:
                blank_row_indexes = [
                    row_index
                    for row_index in shell_group_row_indexes
                    if not _field_value_to_str(
                        _safe_row_get(rows[row_index].get("values"), source_col_index),
                    )
                ]
                if len(blank_row_indexes) == 1:
                    weak_target_row_index_by_col[source_col_index] = int(blank_row_indexes[0])
            weak_target_row_index = weak_target_row_index_by_col.get(source_col_index)
            if weak_target_row_index is not None:
                _append_item(
                    payload_item=payload_item,
                    numeric_cell=numeric_cell,
                    classification="weak_candidate",
                    confidence_tier="low",
                    placement_basis="date_group_blank_unique",
                    target_row_index=weak_target_row_index,
                )
                continue
            _append_item(
                payload_item=payload_item,
                numeric_cell=numeric_cell,
                classification="unresolved",
                confidence_tier="low",
                placement_basis="unresolved",
                reason="target_not_proven",
            )

    provenance_acceptance_map = {
        "ocr_payload_exact": ("high", "weekly_menu_exact"),
        "ocr_payload_ordered": ("medium", "weekly_menu_ordered"),
        "ocr_payload_identity": ("high", "identity_current_match"),
        "ocr_payload_source_row": ("medium", "source_row_current_match"),
    }
    if cell_provenance_rows:
        for row_index, row in enumerate(rows):
            values = row.get("values")
            if not isinstance(values, list):
                continue
            provenance_row = (
                cell_provenance_rows[row_index]
                if row_index < len(cell_provenance_rows) and isinstance(cell_provenance_rows[row_index], list)
                else []
            )
            date_key = _normalize_sheet_date_key(_safe_row_get(values, date_idx))
            daypart_key = _normalize_daypart_key(_safe_row_get(values, daypart_idx))
            menu_key = _normalize_menu_text(_safe_row_get(values, menu_idx))
            for target_col_index in quantity_columns:
                target_key = (row_index, target_col_index)
                if target_key in classified_target_cells:
                    continue
                value = _field_value_to_str(_safe_row_get(values, target_col_index))
                if not value:
                    continue
                provenance = _field_value_to_str(_safe_row_get(provenance_row, target_col_index))
                confidence_and_basis = provenance_acceptance_map.get(provenance)
                if confidence_and_basis is None:
                    continue
                confidence_tier, placement_basis = confidence_and_basis
                items.append(
                    _build_ocr_numeric_cell_item(
                        classification="accepted",
                        value=value,
                        confidence_tier=confidence_tier,
                        placement_basis=placement_basis,
                        read_basis="current_sheet_ocr_provenance",
                        source_row_index=row_index,
                        source_col_index=target_col_index,
                        target_row_index=row_index,
                        target_col_index=target_col_index,
                        date_key=date_key,
                        daypart_key=daypart_key,
                        menu_key=menu_key,
                    )
                )
                classified_target_cells.add(target_key)
                summary["accepted_count"] += 1
                summary["raw_ocr_numeric_count"] += 1
    return items, summary


def _collect_sheet_row_dates_from_identity(rows: list[dict[str, Any]]) -> set[date]:
    dates: set[date] = set()
    for row in rows:
        identity = row.get("identity")
        if not isinstance(identity, tuple) or len(identity) != 3:
            continue
        date_key = str(identity[0] or "").strip()
        if not date_key:
            continue
        try:
            dates.add(date.fromisoformat(date_key))
        except Exception:
            continue
    return dates


def _collect_missing_weekly_menu_dates(
    *,
    entries: list[dict[str, Any]],
    rows: list[dict[str, Any]],
    line_dates: set[date],
) -> list[date]:
    if len(line_dates) < 2 or not entries or not rows:
        return []
    entry_dates = sorted(
        {
            item.get("menu_date")
            for item in entries
            if isinstance(item, dict) and isinstance(item.get("menu_date"), date)
        }
    )
    if not entry_dates:
        return []
    entry_date_set = set(entry_dates)
    matched_line_dates = sorted({item for item in line_dates if item in entry_date_set})
    if len(matched_line_dates) < 2:
        return []
    min_date = matched_line_dates[0]
    max_date = matched_line_dates[-1]
    span_days = (max_date - min_date).days
    if span_days <= 1 or span_days > 10:
        return []
    expected_dates = {item for item in entry_dates if min_date <= item <= max_date}
    if not expected_dates:
        return []
    sheet_dates = _collect_sheet_row_dates_from_identity(rows)
    missing = sorted(expected_dates - sheet_dates)
    return missing




def _resolve_quantity_column_index(
    *,
    quantity_index: dict[tuple[str, str | None], int],
    diet_key: str | None,
    area_key: str | None,
) -> int | None:
    identity = authored_quantity_identity(diet_key, area_key)
    if identity not in quantity_index:
        raise ValueError("quantity_template_identity_unknown")
    return quantity_index[identity]


def _clone_sheet_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    cloned: list[dict[str, Any]] = []
    for row in rows:
        copied = dict(row)
        values = row.get("values")
        copied["values"] = list(values) if isinstance(values, list) else []
        cloned.append(copied)
    return cloned


def _parse_sheet_quantity_cell(value: object) -> float | None:
    if value is None:
        return None
    text = str(value).strip()
    if not text:
        return None
    normalized = (
        text.replace("<br>", " ")
        .replace("<br/>", " ")
        .replace("<br />", " ")
        .translate(_SHEET_TRANSLATION)
    )
    compact = re.sub(r"[\s　]+", "", normalized)
    compact = compact.replace(",", "").replace("，", "")
    compact = compact.replace("．", ".").replace("。", ".")
    # Accept only pure numeric cells (with optional surrounding brackets).
    # Avoid parsing tokens from free text such as "副23" or "No.23".
    compact = compact.strip("()[]（）")
    if re.fullmatch(r"-?\d+\.", compact):
        compact = compact[:-1]
    if not re.fullmatch(r"-?\d+(?:\.\d+)?", compact):
        # Limited OCR single-glyph rescue for quantity columns only.
        # Keep this intentionally narrow to avoid false positives.
        single_char_map = {
            "o": "0",
            "O": "0",
            "〇": "0",
            "○": "0",
            "l": "1",
            "I": "1",
            "|": "1",
            "s": "5",
            "S": "5",
            "B": "8",
            "g": "9",
            "q": "9",
            "Q": "9",
        }
        if len(compact) == 1 and compact in single_char_map:
            compact = single_char_map[compact]
    if not re.fullmatch(r"-?\d+(?:\.\d+)?", compact):
        return None
    token = compact
    try:
        parsed = float(token)
    except Exception:
        return None
    # Meal counts are integers. OCR often emits split digits as "2.1"/"1.5";
    # when the token is a single-digit decimal pair, restore it as two digits.
    if not float(parsed).is_integer():
        if re.fullmatch(r"\d\.\d", token):
            parsed = float(token.replace(".", ""))
        else:
            return None
    return _coerce_sheet_quantity_upper_bound(parsed)






def _resolve_sheet_field_indexes(fields: list[str]) -> tuple[int | None, int | None, int | None]:
    date_idx = next((idx for idx, field in enumerate(fields) if str(field).startswith("date")), None)
    daypart_idx = fields.index("daypart") if "daypart" in fields else None
    if "menu" in fields:
        menu_idx = fields.index("menu")
    elif "menu_name" in fields:
        menu_idx = fields.index("menu_name")
    else:
        menu_idx = None
    return date_idx, daypart_idx, menu_idx


def _safe_row_get(values: list[Any], idx: int | None) -> str:
    if idx is None or idx < 0 or idx >= len(values):
        return ""
    return _field_value_to_str(values[idx])




def _authored_sheet_identity_value_copy(
    values: list[Any], *,
    indexes: tuple[int | None, int | None, int | None], template: dict[str, Any] | None,
    previous: list[Any] | None = None, authored_identity: tuple | None = None,
) -> list[Any]:
    if not isinstance(values, list) or any(index is None for index in indexes):
        raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
    date_idx, daypart_idx, _ = indexes
    copied = list(values)
    if authored_identity is not None:
        if not isinstance(authored_identity, tuple) or len(authored_identity) != 3:
            raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
        for index, authored in zip(indexes, authored_identity):
            if _safe_row_get(copied, index).strip():
                continue
            while len(copied) <= index:
                copied.append("")
            copied[index] = authored
    roles = (template or {}).get("fill_forward_roles", [])
    if not isinstance(roles, list) or any(not isinstance(role, str) for role in roles):
        raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
    if not _safe_row_get(copied, date_idx).strip() and "date" in roles and previous is not None:
        while len(copied) <= date_idx:
            copied.append("")
        copied[date_idx] = _safe_row_get(previous, date_idx)

    current_date = _explicit_sheet_date_parts(_safe_row_get(copied, date_idx))
    if _safe_row_get(copied, date_idx).strip() and current_date is None:
        raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
    previous_date = _explicit_sheet_date_parts(_safe_row_get(previous, date_idx)) if previous is not None else None
    if (not _safe_row_get(copied, daypart_idx).strip() and "daypart" in roles
            and previous is not None and current_date is not None
            and previous_date is not None and current_date[:3] == previous_date[:3]):
        while len(copied) <= daypart_idx:
            copied.append("")
        copied[daypart_idx] = _safe_row_get(previous, daypart_idx)
    return copied


def _build_canonical_payload_row_mapping(
    *,
    rows: list[dict[str, Any]],
    fields: list[str],
    payload_rows: list[list[str]],
    template: dict[str, Any] | None = None,
) -> tuple[dict[int, int], dict[str, int], dict[int, str]]:
    stage_counts = {"exact": 0, "partial": 0, "neighbor": 0, "row_index": 0}
    if not rows or not payload_rows:
        return {}, stage_counts, {}
    date_idx, daypart_idx, menu_idx = _resolve_sheet_field_indexes(fields)
    if any(idx is None for idx in (date_idx, daypart_idx, menu_idx)):
        raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")

    def _identity(values: list[Any]) -> tuple[str, str, str]:
        raw_date = _field_value_to_str(_safe_row_get(values, date_idx)).translate(_SHEET_TRANSLATION)
        date_tokens = set(re.findall(r"(?<!\d)(?:(\d{4})[/-])?(\d{1,2})[/-](\d{1,2})(?!\d)", raw_date))
        if len(date_tokens) != 1:
            raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
        raw_daypart = _safe_row_get(values, daypart_idx)
        daypart = _canonical_daypart_key(raw_daypart)
        if not daypart:
            raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
        identity = (
            _normalize_sheet_date_key(_safe_row_get(values, date_idx)),
            daypart,
            _normalize_menu_text(_safe_row_get(values, menu_idx)),
        )
        if not all(identity):
            raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
        return identity

    def _year(values: list[Any]) -> str:
        raw_date = _field_value_to_str(_safe_row_get(values, date_idx)).translate(_SHEET_TRANSLATION)
        match = re.search(r"(\d{4})[/-]\d{1,2}[/-]\d{1,2}", raw_date)
        return match.group(1) if match else ""

    def _resolved_identity_copies(
        values_rows: list[Any],
        *,
        authored_identities: list[Any] | None = None,
        skip_empty: bool = False,
    ) -> list[tuple[int, tuple[str, str, str], str]]:
        resolved: list[tuple[int, tuple[str, str, str], str]] = []
        previous_values = None
        for row_idx, values in enumerate(values_rows):
            if not isinstance(values, list):
                raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
            if skip_empty and not any(_field_value_to_str(cell).strip() for cell in values):
                continue
            authored_identity = authored_identities[row_idx] if authored_identities is not None else None
            identity_values = _authored_sheet_identity_value_copy(
                values, indexes=(date_idx, daypart_idx, menu_idx),
                template=template, previous=previous_values, authored_identity=authored_identity,
            )
            authored_values = None
            if authored_identity is not None:
                if not isinstance(authored_identity, tuple) or len(authored_identity) != 3:
                    raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
                authored_values = [""] * len(fields)
                for idx, authored in zip((date_idx, daypart_idx, menu_idx), authored_identity):
                    authored_values[idx] = authored
            identity = _identity(identity_values)
            year = _year(identity_values)
            if authored_values is not None:
                if identity != _identity(authored_values):
                    raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
                authored_year = _year(authored_values)
                if year and authored_year and year != authored_year:
                    raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
            previous_values = identity_values
            resolved.append((row_idx, identity, year))
        return resolved

    target_indexes: dict[tuple[str, str, str], list[int]] = {}
    target_years: dict[int, str] = {}
    for row_idx, identity, year in _resolved_identity_copies(
        [row.get("values") for row in rows],
        authored_identities=[row.get("identity") for row in rows],
    ):
        target_indexes.setdefault(identity, []).append(row_idx)
        target_years[row_idx] = year

    source_indexes: dict[tuple[str, str, str], list[int]] = {}
    source_years: dict[int, str] = {}
    for payload_idx, identity, year in _resolved_identity_copies(payload_rows, skip_empty=True):
        source_indexes.setdefault(identity, []).append(payload_idx)
        source_years[payload_idx] = year

    mapping: dict[int, int] = {}
    for identity, payload_indexes in source_indexes.items():
        target_candidates = target_indexes.get(identity, [])
        if len(payload_indexes) != 1 or len(target_candidates) != 1:
            raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
        payload_idx = payload_indexes[0]
        row_idx = target_candidates[0]
        if source_years[payload_idx] and target_years[row_idx] and source_years[payload_idx] != target_years[row_idx]:
            raise _CanonicalOcrProjectionError("sheet_canonical_mismatch")
        mapping[row_idx] = payload_idx
    stage_counts["exact"] = len(mapping)
    return mapping, stage_counts, {row_idx: "exact" for row_idx in mapping}


def _build_payload_row_mapping_by_menu_priority(
    *,
    rows: list[dict[str, Any]],
    fields: list[str],
    payload_rows: list[list[str]],
    quantity_index: dict[tuple[str, str | None], int] | None = None,
    template: dict[str, Any] | None = None,
) -> tuple[dict[int, int], dict[str, int], dict[int, str]]:
    return _build_canonical_payload_row_mapping(rows=rows, fields=fields, payload_rows=payload_rows, template=template)












def _select_trusted_payload_quantity_columns(
    *,
    payload_rows: list[list[str]],
    quantity_columns: list[int],
) -> tuple[list[int], dict[int, int], dict[int, int]]:
    parsed_hits: dict[int, int] = {col_idx: 0 for col_idx in quantity_columns}
    non_empty_hits: dict[int, int] = {col_idx: 0 for col_idx in quantity_columns}
    if not payload_rows or not quantity_columns:
        return list(quantity_columns), parsed_hits, non_empty_hits

    for payload_row in payload_rows:
        if not isinstance(payload_row, list):
            continue
        for col_idx in quantity_columns:
            if col_idx >= len(payload_row):
                continue
            raw = _field_value_to_str(payload_row[col_idx]).strip()
            if not raw:
                continue
            non_empty_hits[col_idx] = int(non_empty_hits.get(col_idx, 0)) + 1
            qty = _parse_sheet_quantity_cell(payload_row[col_idx])
            if qty is None:
                continue
            parsed_hits[col_idx] = int(parsed_hits.get(col_idx, 0)) + 1

    # Numeric coverage is diagnostic, never authority to discard a bound column.
    return list(quantity_columns), parsed_hits, non_empty_hits






def _transcribe_bound_quantity_cell(values: list[Any], col_idx: int, raw: Any) -> None:
    if col_idx < 0:
        raise _CanonicalOcrProjectionError("sheet_quantity_column_unmapped")
    while len(values) <= col_idx:
        values.append("")
    # Blank and uncertain recognizer text remain distinct from a missing binding.
    values[col_idx] = _field_value_to_str(raw)




def _build_payload_row_mapping_by_row_index_numeric_only(
    *,
    rows: list[dict[str, Any]],
    fields: list[str],
    payload_rows: list[list[str]],
    quantity_columns: list[int],
    allow_row_index_fallback: bool = False,
    template: dict[str, Any] | None = None,
) -> tuple[dict[int, int], dict[str, int], dict[int, str]]:
    return _build_canonical_payload_row_mapping(rows=rows, fields=fields, payload_rows=payload_rows, template=template)


def _overlay_payload_structural_cells_from_sheet_rows(
    *,
    rows: list[dict[str, Any]],
    fields: list[str],
    payload_rows: list[list[str]],
) -> list[list[str]]:
    if not rows or not payload_rows:
        return [
            list(payload_row) if isinstance(payload_row, list) else []
            for payload_row in payload_rows
        ]
    date_idx, daypart_idx, menu_idx = _resolve_sheet_field_indexes(fields)
    overlay_indexes = [
        idx for idx in (date_idx, daypart_idx, menu_idx) if idx is not None and idx >= 0
    ]
    if not overlay_indexes:
        return [
            list(payload_row) if isinstance(payload_row, list) else []
            for payload_row in payload_rows
        ]
    aligned_rows: list[list[str]] = []
    for row_idx, payload_row in enumerate(payload_rows):
        normalized_row = list(payload_row) if isinstance(payload_row, list) else []
        if row_idx < len(rows):
            values = rows[row_idx].get("values")
            if isinstance(values, list):
                for col_idx in overlay_indexes:
                    while len(normalized_row) <= col_idx:
                        normalized_row.append("")
                    normalized_row[col_idx] = _safe_row_get(values, col_idx)
        aligned_rows.append(normalized_row)
    return aligned_rows


def _apply_payload_quantities_numeric_only(
    *,
    rows: list[dict[str, Any]],
    fields: list[str],
    quantity_index: dict[tuple[str, str | None], int],
    payload_rows: list[list[str]],
    payload_unstructured_qty: list[str] | None = None,
    allow_heuristics: bool = False,
    enable_daypart_consensus: bool = True,
    explicit_quantity_pairs: list[tuple[int, int]] | None = None,
    overlay_structural_fields_from_sheet_rows: bool = False,
    allow_row_index_fallback: bool = False,
    allow_span_copy: bool = True,
    template: dict[str, Any] | None = None,
) -> dict[str, int]:
    stage_counts = {
        "exact": 0,
        "partial": 0,
        "neighbor": 0,
        "row_index": 0,
        "loose_cell": 0,
        "gap_fill": 0,
        "unstructured": 0,
        "cluster_fill": 0,
        "span_copy": 0,
    }
    if not rows or not fields or not payload_rows:
        return stage_counts

    quantity_columns = sorted(set(quantity_index.values()))
    if not quantity_columns:
        return stage_counts
    working_payload_rows = payload_rows
    if overlay_structural_fields_from_sheet_rows:
        working_payload_rows = _overlay_payload_structural_cells_from_sheet_rows(
            rows=rows,
            fields=fields,
            payload_rows=payload_rows,
        )
    immutable_columns = {
        idx
        for idx, field in enumerate(fields)
        if str(field).startswith("date") or field in {"daypart", "menu", "menu_name"}
    }
    aux_columns = [
        idx
        for idx, field in enumerate(fields)
        if idx not in immutable_columns and idx not in quantity_columns and _is_aux_sheet_field(field)
    ]
    note_columns = [
        idx
        for idx, field in enumerate(fields)
        if idx not in immutable_columns and idx not in quantity_columns and _is_sheet_note_field(field)
    ]
    explicit_quantity_pairs = [
        (int(source_col_idx), int(target_col_idx))
        for source_col_idx, target_col_idx in (explicit_quantity_pairs or [])
        if int(target_col_idx) in quantity_columns
    ]
    if explicit_quantity_pairs:
        payload_quantity_columns = sorted({source_col_idx for source_col_idx, _target_col_idx in explicit_quantity_pairs})
        mapped_quantity_columns = sorted({target_col_idx for _source_col_idx, target_col_idx in explicit_quantity_pairs})
        quantity_hits = {target_col_idx: 0 for target_col_idx in mapped_quantity_columns}
        for payload_row in working_payload_rows:
            if not isinstance(payload_row, list):
                continue
            for source_col_idx, target_col_idx in explicit_quantity_pairs:
                if source_col_idx >= len(payload_row):
                    continue
                if _parse_sheet_quantity_cell(payload_row[source_col_idx]) is None:
                    continue
                quantity_hits[target_col_idx] = int(quantity_hits.get(target_col_idx, 0)) + 1
    else:
        trusted_quantity_columns, quantity_hits, _quantity_non_empty_hits = _select_trusted_payload_quantity_columns(
            payload_rows=working_payload_rows,
            quantity_columns=quantity_columns,
        )
        payload_quantity_columns = list(trusted_quantity_columns)
        mapped_quantity_columns = list(trusted_quantity_columns)
        if not mapped_quantity_columns:
            mapped_quantity_columns = list(quantity_columns)
            payload_quantity_columns = list(mapped_quantity_columns)
    row_mapping, mapping_counts, _mapping_stage = _build_payload_row_mapping_by_row_index_numeric_only(
        rows=rows,
        fields=fields,
        payload_rows=payload_rows,
        quantity_columns=payload_quantity_columns,
        allow_row_index_fallback=allow_row_index_fallback,
        template=template,
    )
    for key, value in mapping_counts.items():
        stage_counts[key] = int(value)
    mapped_payload_indexes = set(row_mapping.values())
    stage_counts["unmapped"] = sum(
        1 for payload_idx, payload_row in enumerate(payload_rows)
        if payload_idx not in mapped_payload_indexes and any(
            source_col_idx < len(payload_row)
            and _field_value_to_str(payload_row[source_col_idx]).strip()
            for source_col_idx in payload_quantity_columns
        )
    )
    for row_idx, payload_idx in row_mapping.items():
        if row_idx < 0 or row_idx >= len(rows):
            continue
        if payload_idx < 0 or payload_idx >= len(working_payload_rows):
            continue
        payload_row = working_payload_rows[payload_idx]
        if not isinstance(payload_row, list):
            continue
        target = rows[row_idx]
        values = target.get("values")
        if not isinstance(values, list):
            continue

        quantity_pairs = (
            list(explicit_quantity_pairs)
            if explicit_quantity_pairs
            else [(col_idx, col_idx) for col_idx in mapped_quantity_columns]
        )
        for source_col_idx, target_col_idx in quantity_pairs:
            if source_col_idx < 0 or source_col_idx >= len(payload_row):
                raise _CanonicalOcrProjectionError("sheet_quantity_column_unmapped")
            _transcribe_bound_quantity_cell(values, target_col_idx, payload_row[source_col_idx])

        for col_idx in aux_columns:
            if col_idx >= len(payload_row):
                continue
            aux_value = _field_value_to_str(payload_row[col_idx]).strip()
            if not aux_value or aux_value == "-":
                continue
            while len(values) <= col_idx:
                values.append("")
            values[col_idx] = aux_value

    return stage_counts


def _project_payload_quantities_onto_sheet_row_lists(
    *,
    rows: list[list[str]] | None,
    fields: list[str] | None,
    payload_rows: list[list[str]] | None,
    explicit_quantity_pairs: list[tuple[int, int]] | None = None,
    strict_raw_ocr_only: bool = False,
    template: dict[str, Any] | None = None,
) -> tuple[list[list[str]], dict[str, int]]:
    normalized_rows = [
        [_field_value_to_str(cell) for cell in row]
        for row in (rows or [])
        if isinstance(row, list)
    ]
    normalized_fields = [str(field or "").strip() for field in (fields or []) if str(field or "").strip()]
    normalized_payload_rows = [
        [_field_value_to_str(cell) for cell in row]
        for row in (payload_rows or [])
        if isinstance(row, list)
    ]
    if not normalized_rows or not normalized_fields or not normalized_payload_rows:
        return normalized_rows, {}
    quantity_index = _build_sheet_quantity_index(normalized_fields, template=template)
    if not quantity_index:
        return normalized_rows, {}
    quantity_columns = sorted(set(quantity_index.values()))
    projected_rows: list[dict[str, Any]] = []
    for row in normalized_rows:
        scratch = list(row)
        for col_idx in quantity_columns:
            if 0 <= col_idx < len(scratch):
                scratch[col_idx] = ""
        projected_rows.append({"values": scratch})
    projection_stats = _apply_payload_quantities_numeric_only(
        rows=projected_rows,
        fields=normalized_fields,
        quantity_index=quantity_index,
        payload_rows=normalized_payload_rows,
        payload_unstructured_qty=[],
        allow_heuristics=False,
        enable_daypart_consensus=False,
        explicit_quantity_pairs=explicit_quantity_pairs,
        overlay_structural_fields_from_sheet_rows=True,
        allow_row_index_fallback=False,
        allow_span_copy=not strict_raw_ocr_only,
        template=template,
    )
    resolved_rows: list[list[str]] = []
    for row_idx, original_row in enumerate(normalized_rows):
        values = projected_rows[row_idx].get("values") if row_idx < len(projected_rows) else None
        if isinstance(values, list):
            resolved_rows.append([_field_value_to_str(cell) for cell in values])
        else:
            resolved_rows.append(list(original_row))
    return resolved_rows, projection_stats




def _build_weekly_menu_shell_date_groups(
    *,
    rows: list[dict[str, Any]],
    fields: list[str],
) -> list[dict[str, Any]]:
    if not rows or not fields:
        return []
    date_idx, daypart_idx, menu_idx = _resolve_sheet_field_indexes(fields)
    groups: list[dict[str, Any]] = []
    current_group: dict[str, Any] | None = None
    current_block: dict[str, Any] | None = None
    for row_idx, row in enumerate(rows):
        values = row.get("values")
        if not isinstance(values, list):
            continue
        date_key = _normalize_sheet_date_key(_safe_row_get(values, date_idx))
        daypart_key = _normalize_daypart_key(_safe_row_get(values, daypart_idx))
        menu_norm = _normalize_menu_text(_safe_row_get(values, menu_idx))
        if not date_key or not daypart_key:
            continue
        if current_group is None or current_group.get("date_key") != date_key:
            current_group = {
                "date_key": date_key,
                "row_indexes": [],
                "menu_norms": set(),
                "blocks": [],
            }
            groups.append(current_group)
            current_block = None
        current_group["row_indexes"].append(row_idx)
        if menu_norm:
            current_group["menu_norms"].add(menu_norm)
        if current_block is None or current_block.get("daypart_key") != daypart_key:
            current_block = {
                "daypart_key": daypart_key,
                "row_indexes": [],
                "menus": [],
            }
            current_group["blocks"].append(current_block)
        current_block["row_indexes"].append(row_idx)
        current_block["menus"].append(menu_norm)
    return groups






def _apply_payload_quantity_row_to_shell_row(
    *,
    row: dict[str, Any],
    payload_row: list[str],
    quantity_columns: list[int],
) -> int:
    values = row.get("values")
    if not isinstance(values, list):
        return 0
    applied_cells = 0
    for col_idx in quantity_columns:
        if col_idx < 0 or col_idx >= len(payload_row):
            raise _CanonicalOcrProjectionError("sheet_quantity_column_unmapped")
        _transcribe_bound_quantity_cell(values, col_idx, payload_row[col_idx])
        applied_cells += 1
    return applied_cells


def _project_payload_quantities_onto_weekly_menu_shell(
    *,
    rows: list[dict[str, Any]],
    fields: list[str],
    payload_rows: list[list[str]],
    template: dict[str, Any],
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    cloned_rows = _clone_sheet_rows(rows)
    if not cloned_rows or not fields or not payload_rows:
        return cloned_rows, {}
    quantity_columns = _template_quantity_column_indexes(template)
    if not quantity_columns:
        return cloned_rows, {}
    row_mapping, _counts, _stages = _build_canonical_payload_row_mapping(
        rows=cloned_rows, fields=fields, payload_rows=payload_rows,
        template=template,
    )
    mapped_cell_count = 0
    date_idx, _daypart_idx, _menu_idx = _resolve_sheet_field_indexes(fields)
    date_keys: set[str] = set()
    accepted_payload_mappings: list[dict[str, Any]] = []
    for row_idx, payload_idx in row_mapping.items():
        payload_row = payload_rows[payload_idx]
        mapped_cell_count += _apply_payload_quantity_row_to_shell_row(
            row=cloned_rows[row_idx], payload_row=payload_row, quantity_columns=quantity_columns,
        )
        target = cloned_rows[row_idx]
        target_date = _safe_row_get(target["values"], date_idx)
        if not _field_value_to_str(target_date).strip() and isinstance(target.get("identity"), tuple):
            target_date = target["identity"][0]
        date_keys.add(_normalize_sheet_date_key(target_date))
        accepted_payload_mappings.append({
            "payload_row_index": payload_idx,
            "target_row_index": row_idx,
            "mapping_type": "exact",
        })
    return cloned_rows, {
        "mapped_date_group_count": len(date_keys),
        "unresolved_date_group_count": 0,
        "date_group_mappings": [
            {"payload_date_key": key, "shell_date_key": key, "reason": "exact"}
            for key in sorted(date_keys)
        ],
        "unresolved_payload_dates": [],
        "exact_row_count": len(row_mapping),
        "ordered_row_count": 0,
        "mapped_row_count": len(row_mapping),
        "mapped_cell_count": mapped_cell_count,
        "overflow_row_count": 0,
        "exact_target_row_indexes": list(row_mapping)[:200],
        "ordered_target_row_indexes": [],
        "unmapped_payload_row_indexes": [],
        "accepted_payload_mappings": accepted_payload_mappings[:400],
    }


def _summarize_order_line_source_row_mapping(
    *,
    base_rows: list[dict[str, Any]],
    quantity_index: dict[tuple[str, str | None], int],
    order_lines: list[Any],
) -> dict[str, int]:
    def _line_value(line: Any, key: str):
        if isinstance(line, dict):
            return line.get(key)
        return getattr(line, key, None)

    summary = {
        "eligible_line_count": 0,
        "matched_source_row_count": 0,
        "mismatched_source_row_count": 0,
        "missing_source_row_count": 0,
        "invalid_identity_line_count": 0,
    }
    if not base_rows or not quantity_index or not order_lines:
        return summary

    for line in order_lines:
        qty_corrected = _line_value(line, "quantity_corrected")
        qty_original = _line_value(line, "quantity_original")
        qty = qty_corrected if qty_corrected is not None else qty_original
        if qty is None:
            continue
        try:
            float(qty)
        except Exception:
            continue
        diet_key, area_key = authored_quantity_identity(
            _line_value(line, "diet_type"), _line_value(line, "area_id"),
        )
        if not diet_key:
            continue
        col_idx = _resolve_quantity_column_index(
            quantity_index=quantity_index,
            diet_key=diet_key,
            area_key=area_key,
        )
        if col_idx is None:
            continue
        summary["eligible_line_count"] += 1

        line_identity = _build_canonical_menu_key(
            menu_date=_line_value(line, "date"),
            daypart=_line_value(line, "daypart"),
            menu_name=_line_value(line, "menu_name"),
        )
        if line_identity is None:
            summary["invalid_identity_line_count"] += 1
            continue

        source_idx_raw = _line_value(line, "source_row_index")
        try:
            source_idx = int(source_idx_raw) if source_idx_raw is not None else None
        except Exception:
            source_idx = None
        if source_idx is None or source_idx < 0 or source_idx >= len(base_rows):
            summary["missing_source_row_count"] += 1
            continue

        target_identity = base_rows[source_idx].get("identity")
        if isinstance(target_identity, tuple) and len(target_identity) == 3 and target_identity == line_identity:
            summary["matched_source_row_count"] += 1
        else:
            summary["mismatched_source_row_count"] += 1

    return summary


def _should_prefer_source_row_candidate(
    *,
    identity_count: int,
    source_row_count: int,
    source_row_summary: dict[str, int] | None,
) -> bool:
    if source_row_count <= identity_count:
        return False
    if not isinstance(source_row_summary, dict):
        return False
    if int(source_row_summary.get("eligible_line_count") or 0) <= 0:
        return False
    if int(source_row_summary.get("mismatched_source_row_count") or 0) > 0:
        return False
    if int(source_row_summary.get("missing_source_row_count") or 0) > 0:
        return False
    if int(source_row_summary.get("invalid_identity_line_count") or 0) > 0:
        return False
    return True


def build_recoverable_ocr_sheet_payload(
    order_id: str,
    error_code: str,
    *,
    use_saved_draft: bool = True,
    evidence_run_override: dict[str, Any] | None = None,
    allow_current_surface_short_circuit: bool = True,
) -> tuple[dict[str, Any] | None, str | None]:
    # Compatibility arguments cannot authorize reconstruction from another source.
    return get_ocr_sheet(
        order_id, use_saved_draft=use_saved_draft,
        evidence_run_override=evidence_run_override,
    )


def get_ocr_sheet(
    order_id: str,
    *,
    use_saved_draft: bool = True,
    evidence_run_override: dict[str, Any] | None = None,
    prefer_order_lines: bool = True,
    synchronous_write_input: dict[str, Any] | None = None,
):
    with session_scope() as session:
        from src.services.initial_saved_import_service import get_binding
        from src.services.initial_saved_source_service import current_sheet_payload
        imported = get_binding(session, order_id)
        if imported is not None and evidence_run_override is None:
            return current_sheet_payload(imported["snapshot"]), None
        if session.get(Order, order_id) is None:
            return None, "order_not_found"
    if _unresolved_order_week_context(order_id) is not None:
        return None, "week_unresolved"
    try:
        if use_saved_draft and evidence_run_override is None:
            context = get_current_sheet_context(order_id)
            if not isinstance(context, dict):
                return None, "sheet_unavailable"
            if context.get("draft_payload") is None or context.get("sheet_unavailable"):
                return None, next(iter(context.get("blockers") or []), "sheet_unavailable")
            payload, _record = _authoritative_surface_payload_from_current_sheet_context(order_id, context)
            if payload is None:
                return None, "sheet_unavailable"
            gate = payload.get("apply_gate")
            if not isinstance(gate, dict) or any(type(gate.get(key)) is not bool for key in ("can_apply", "can_confirm")):
                return None, "current_sheet_apply_gate_unavailable"
            payload.update({key: gate[key] for key in ("can_apply", "can_confirm")})
            payload["apply_blocker_details"] = _review_reason_details(payload["apply_blockers"], severity="blocker")
            payload["confirm_blocker_details"] = _review_reason_details(payload["confirm_blockers"], severity="blocker")
            payload["confirm_warning_details"] = _review_reason_details(payload["confirm_warnings"], severity="warning")
            from src.services.workflow_attempt_guard_service import validate_current_sheet_input
            with session_scope() as session:
                validate_current_sheet_input(session, order_id, context)
            if synchronous_write_input is not None:
                captured = _capture_synchronous_cache_write_input(order_id)
                if captured is None or any(
                    not snapshots_equal(value, synchronous_write_input.get(key))
                    for key, value in captured.items()
                ):
                    return None, "synchronous_input_conflict"
            return payload, None if payload is not None else "sheet_unavailable"
        from src.services.order_workflow_v2_service import build_sheet_from_ocr_evidence
        projected, error = build_sheet_from_ocr_evidence(
            order_id, evidence_run_override=evidence_run_override,
            synchronous_write_input=synchronous_write_input,
        )
        return (deepcopy(projected["sheet"]), None) if projected is not None else (None, error)
    except ValueError as exc:
        return None, str(exc)


def export_ocr_sheet_label(
    order_id: str,
    *,
    output_path: str | Path | None = None,
    output_dir: str | Path | None = None,
):
    sheet, error = get_ocr_sheet(order_id)
    if error:
        return None, error
    if not isinstance(sheet, dict):
        return None, "sheet_missing"
    if output_path is not None:
        resolved_path = Path(output_path)
    else:
        if output_dir is not None:
            base_dir = Path(output_dir)
        else:
            base_dir = Path(__file__).resolve().parents[2] / "tests" / "fixtures" / "ocr_sheet_corpus" / "manual_labels"
        resolved_path = base_dir / f"{order_id}.expected_sheet.json"
    resolved_path.parent.mkdir(parents=True, exist_ok=True)
    resolved_path.write_text(
        json.dumps(sheet, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    return {
        "order_id": order_id,
        "output_path": str(resolved_path),
        "sheet": sheet,
    }, None


def get_ocr_edit_history(order_id: str):
    try:
        with session_scope() as session:
            if session.get(Order, order_id) is None:
                return None, "order_not_found"
        diagnostics = _load_ocr_history_diagnostics(order_id)
        revisions, raw_output = _load_order_sheet_revisions(
            order_id=order_id, payload=diagnostics["cache"]["payload"], limit=20,
        )
    except Exception as exc:  # noqa: BLE001
        logger.warning("OCR history load failed", order_id=order_id, error=str(exc))
        return None, "ocr_history_load_failed"
    raw_output_source = "order_ocr_cache._edited_ocr.raw_output" if raw_output is not None else None
    latest_evidence = diagnostics["latest_evidence"]["record"]
    if not revisions and raw_output is None and isinstance(latest_evidence, dict):
        raw_output = latest_evidence.get("payload_json")
        raw_output_source = "order_ocr_evidence_runs.payload_json"
    latest = revisions[-1] if revisions else None
    reparse_job = get_latest_order_job(order_id)
    reparse_state = None
    latest_reparse_attempt = None
    if isinstance(reparse_job, dict):
        metrics = reparse_job.get("metrics")
        metrics = metrics if isinstance(metrics, dict) else {}
        request_mode = get_job_request_mode(reparse_job)
        if request_mode in {"ocr_rerun", "ocr_reparse", "llm_reparse"}:
            reparse_state = describe_ocr_job_state(reparse_job)
            latest_reparse_attempt = {
                "job_id": str(reparse_job.get("id") or "").strip() or None,
                "status": str(reparse_job.get("status") or "").strip() or None,
                "error_message": str(reparse_job.get("error_message") or "").strip() or None,
                "updated_at": _normalize_debug_timestamp(reparse_job.get("updated_at")),
                "request_mode": request_mode,
                "processing_stage": str(metrics.get("processing_stage") or "").strip() or None,
                "result_state": str(metrics.get("result_state") or "").strip() or None,
                "requested_provider": str(metrics.get("requested_provider") or "").strip() or None,
                "provider": str(metrics.get("provider") or metrics.get("effective_provider") or "").strip() or None,
            }
    return {
        "order_id": order_id,
        "latest": latest,
        "revisions": revisions,
        "raw_output": raw_output,
        "raw_output_source": raw_output_source,
        "diagnostics": diagnostics,
        "reparse_state": reparse_state,
        "latest_reparse_attempt": latest_reparse_attempt,
    }, None


def get_order_history(order_id: str, limit: int = 100):
    normalized_limit = max(1, min(int(limit), 500))
    order_payload: dict[str, Any] | None = None
    audit_rows: list[dict[str, Any]] = []
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return None, "order_not_found"
        order_payload = {
            "facility_code": order.facility_code,
            "week_code": order.week_code,
            "received_at": order.received_at.isoformat() if order.received_at else None,
            "lines_updated_at": order.lines_updated_at.isoformat() if order.lines_updated_at else None,
        }
        targets = {order_id, f"OCR-{order_id}"}
        if order.message_id:
            targets.add(f"OCR-{order.message_id}")
        rows = (
            session.execute(
                select(AuditLog)
                .where(AuditLog.target.in_(sorted(targets)))
                .order_by(AuditLog.created_at.desc())
                .limit(normalized_limit)
            )
            .scalars()
            .all()
        )
        audit_rows = [
            {
                "id": row.id,
                "actor": row.actor,
                "action": row.action,
                "target": row.target,
                "facility": row.fac,
                "week": row.wek,
                "metadata": row.metadata_json if isinstance(row.metadata_json, dict) else row.metadata_json,
                "created_at": row.created_at.isoformat() if row.created_at else None,
            }
            for row in rows
        ]

    items: list[dict[str, Any]] = []
    if order_payload and order_payload.get("received_at"):
        items.append(
            {
                "id": f"synthetic-created-{order_id}",
                "actor": "system",
                "action": "order_created",
                "target": order_id,
                "facility": order_payload.get("facility_code"),
                "week": order_payload.get("week_code"),
                "metadata": {"source": "synthetic"},
                "created_at": order_payload.get("received_at"),
            }
        )
    if order_payload and order_payload.get("lines_updated_at"):
        items.append(
            {
                "id": f"synthetic-lines-{order_id}",
                "actor": "system",
                "action": "order_lines_update",
                "target": order_id,
                "facility": order_payload.get("facility_code"),
                "week": order_payload.get("week_code"),
                "metadata": {"source": "synthetic"},
                "created_at": order_payload.get("lines_updated_at"),
            }
        )
    try:
        diagnostics = _load_ocr_history_diagnostics(order_id)
        revisions, _ = _load_order_sheet_revisions(
            order_id=order_id, payload=diagnostics["cache"]["payload"], limit=min(normalized_limit, 100),
        )
    except Exception as exc:  # noqa: BLE001
        logger.warning("Order history load failed", order_id=order_id, error=str(exc))
        return None, "order_history_load_failed"
    for revision in revisions:
        if not isinstance(revision, dict):
            continue
        created_at = revision.get("edited_at")
        if not isinstance(created_at, str) or not created_at:
            continue
        revision_id = str(revision.get("revision_id") or "").strip()
        if not revision_id:
            continue
        is_candidate = bool(
            revision.get("workflow_job_id") or revision.get("draft_from_reparse_reject")
            or revision.get("auto_apply_blocked") or revision.get("adopted") is False
        )
        items.append(
            {
                "id": revision_id,
                "actor": "system",
                "action": "ocr_candidate_review" if is_candidate else "ocr_sheet_save",
                "target": order_id,
                "facility": order_payload.get("facility_code") if order_payload else None,
                "week": order_payload.get("week_code") if order_payload else None,
                "metadata": {
                    "source": "order_ocr_revisions",
                    "ui_mode": revision.get("ui_mode"),
                    "row_count": revision.get("row_count"),
                    "changed": revision.get("changed"),
                    "base_evidence_run_id": revision.get("base_evidence_run_id"),
                    "workflow_job_id": revision.get("workflow_job_id"),
                    "workflow_attempt_id": revision.get("workflow_attempt_id"),
                    "workflow_revision": revision.get("workflow_revision"),
                    "adopted": False if is_candidate else None,
                },
                "created_at": created_at,
            }
        )

    for row in audit_rows:
        items.append(row)
    items.sort(key=lambda item: str(item.get("created_at") or ""), reverse=True)
    items = items[:normalized_limit]
    return {
        "order_id": order_id,
        "items": items,
        "diagnostics": diagnostics,
    }, None


def _hakodate_skeleton_rows_from_baseline(baseline: dict[str, Any] | None) -> list[dict[str, Any]]:
    if not isinstance(baseline, dict):
        return []
    fields = [str(field).strip() for field in (baseline.get("fields") or []) if str(field).strip()]
    rows = [list(row) for row in (baseline.get("rows") or []) if isinstance(row, list)]
    row_ids = [str(item).strip() for item in (baseline.get("row_ids") or []) if str(item).strip()]
    if not fields or not rows:
        return []

    def _index(*candidates: str) -> int | None:
        for candidate in candidates:
            if candidate in fields:
                return fields.index(candidate)
        return None

    date_idx = _index("date", "date_mmdd")
    daypart_idx = _index("daypart")
    menu_idx = _index("menu_name", "menu")
    skeleton: list[dict[str, Any]] = []
    for row_index, row in enumerate(rows):
        row_id = row_ids[row_index] if row_index < len(row_ids) else f"row-{row_index + 1}"

        def _cell(idx: int | None) -> str:
            if idx is None or idx >= len(row):
                return ""
            return str(row[idx] or "").strip()

        skeleton.append(
            {
                "row_id": row_id,
                "date": _cell(date_idx),
                "daypart": _cell(daypart_idx),
                "menu_name": _cell(menu_idx),
            }
        )
    return skeleton


def _first_hakodate_payload_list(payload: dict[str, Any], paths: list[tuple[str, ...]]) -> list[dict[str, Any]]:
    if not any(path[0] in payload for path in paths):
        return []
    canonical = None
    for index, path in enumerate(paths):
        current: Any = payload
        for key in path:
            if not isinstance(current, dict) or key not in current:
                current = ...
                break
            current = current[key]
        if current is ...:
            if index == 0:
                raise ValueError("hakodate_canonical_representation_missing")
            continue
        if not isinstance(current, list) or any(not isinstance(item, dict) for item in current):
            raise ValueError("hakodate_canonical_representation_invalid")
        if index == 0:
            canonical = current
        elif not snapshots_equal(current, canonical):
            raise ValueError("hakodate_own_artifact_representations_conflict")
    return deepcopy(canonical)


def _extract_hakodate_target_cells_from_payload(payload: dict[str, Any] | None) -> list[dict[str, Any]]:
    if not isinstance(payload, dict):
        return []
    raw_cells = _first_hakodate_payload_list(
        payload,
        [
            ("hakodate_preprocessing", "target_cell_map"),
            ("hakodate_preprocessing", "target_cells"),
            ("hakodate_target_cell_map",),
        ],
    )
    cells: list[dict[str, Any]] = []
    for cell in raw_cells:
        source = str(cell.get("source") or "").strip()
        if source == "order_document_grid":
            raise ValueError("hakodate_target_source_invalid")
        cells.append(cell)
    return cells


def _hakodate_evidence_source_allowed(record: dict[str, Any]) -> bool:
    return ocr_evidence_service.hakodate_evidence_record_allowed(record)


def _extract_hakodate_ocr_evidence_records_from_payload(
    payload: dict[str, Any] | None,
    *,
    order_id: str,
) -> list[dict[str, Any]]:
    if not isinstance(payload, dict):
        return []
    raw_records = _first_hakodate_payload_list(
        payload,
        [
            ("hakodate_ocr_evidence", "records"),
            ("hakodate_ocr_evidence_records",),
        ],
    )
    if not raw_records:
        return []
    if any(not _hakodate_evidence_source_allowed(item) for item in raw_records):
        raise ValueError("hakodate_evidence_source_invalid")
    if any(not isinstance(item.get("evidence_id"), str) or not item["evidence_id"].strip() for item in raw_records):
        raise ValueError("hakodate_own_record_identity_missing")
    return raw_records


def _build_hakodate_evidence_assignment_from_payload(
    *,
    order_id: str,
    facility_id: str | None,
    template_id: str | None,
    payload: dict[str, Any] | None,
    facility_config: dict[str, Any],
) -> dict[str, Any]:
    target_cells = _extract_hakodate_target_cells_from_payload(payload)
    evidence_records = _extract_hakodate_ocr_evidence_records_from_payload(payload, order_id=order_id)
    blockers: list[str] = []
    pipeline = (payload or {}).get("hakodate_canonical_pipeline")
    if isinstance(pipeline, dict) and pipeline.get("version") != HAKODATE_CANONICAL_PIPELINE_VERSION:
        blockers.append("hakodate_canonical_version_required")
    if not target_cells:
        blockers.append("hakodate_target_cell_map_missing")
    if not evidence_records:
        blockers.append("hakodate_ocr_evidence_missing")
    allowed_fields: set[str] = set()
    if facility_id:
        try:
            config_service._validate_authored_facility_config(facility_config, template_id)
        except ValueError as exc:
            blockers.append(str(exc))
            facility_config = None
        fax_template = facility_config.get("fax_template") if isinstance(facility_config, dict) else None
        if isinstance(fax_template, dict):
            allowed_fields = {
                str(field or "").strip()
                for field in _row_fields_from_template(fax_template)
                if str(field or "").strip()
            }
    else:
        blockers.append("facility_unresolved")
    if allowed_fields and target_cells:
        target_fields = {
            field
            for cell in target_cells
            for field in _hakodate_target_cell_field_candidates(cell)
            if field
        }
        unmapped_fields = sorted(field for field in target_fields if field not in allowed_fields)
        if unmapped_fields:
            blockers.append("hakodate_target_field_unmapped")

    assignment_result = (
        hakodate_ocr_evidence_service.assign_evidence_to_target_cells(
            evidence_records=evidence_records,
            target_cells=target_cells,
        )
        if target_cells and evidence_records and not blockers
        else {
            "assignments": [],
            "unassigned_evidence": [],
            "blockers": [],
            "summary": {
                "target_cell_count": len(target_cells),
                "evidence_count": len(evidence_records),
                "assigned_target_count": 0,
                "conflict_target_count": 0,
                "unassigned_evidence_count": 0,
                "blocker_count": 0,
            },
        }
    )
    sheet_output = hakodate_ocr_evidence_service.sheet_output_from_assigned_results(
        assignments=list(assignment_result.get("assignments") or []),
        blockers=list(blockers) + list(assignment_result.get("blockers") or []),
        unassigned_evidence=list(assignment_result.get("unassigned_evidence") or []),
    )
    output_blockers = list(sheet_output.get("blockers") or [])
    assigned_count = int((assignment_result.get("summary") or {}).get("assigned_target_count") or 0)
    status = "auto_assignable" if assigned_count > 0 and not output_blockers else "blocked"
    if assigned_count > 0 and output_blockers:
        status = "review_required"
    return {
        "version": "2",
        "strategy": "hakodate",
        "assignment_mode": "ocr_evidence",
        "status": status,
        "blockers": output_blockers,
        "warnings": ["hakodate_ocr_evidence_assignment"],
        "order_id": order_id,
        "facility_id": facility_id,
        "template_id": template_id,
        "target_cells": target_cells,
        "evidence_records": evidence_records,
        "assignments": list(assignment_result.get("assignments") or []),
        "unassigned_evidence": list(assignment_result.get("unassigned_evidence") or []),
        "sheet_output": sheet_output,
        "metrics": {
            **dict(assignment_result.get("summary") or {}),
            "target_cell_count": len(target_cells),
            "evidence_count": len(evidence_records),
            "sheet_cell_count": int((sheet_output.get("summary") or {}).get("cell_count") or 0),
            "sheet_blocker_count": len(output_blockers),
        },
    }


def _hakodate_sheet_identity(date_value: object, daypart: object, menu_name: object) -> tuple[str, str, str]:
    parsed_date = _normalize_entry_date(date_value)
    date_key = f"{parsed_date.month:02d}/{parsed_date.day:02d}" if parsed_date else ""
    return date_key, _normalize_daypart_key(daypart), _normalize_menu_text(str(menu_name or ""))


def _hakodate_target_cell_field_candidates(cell: dict[str, Any]) -> list[str]:
    metadata = cell.get("metadata") if isinstance(cell.get("metadata"), dict) else {}
    truth = metadata.get("truth") if isinstance(metadata.get("truth"), dict) else {}
    logical_targets = cell.get("logical_targets") if isinstance(cell.get("logical_targets"), list) else []
    candidates: list[str] = []
    for candidate in (
        cell.get("semantic_field"),
        cell.get("field"),
    ):
        field = _normalize_hakodate_sheet_field(candidate)
        if field:
            candidates.append(field)
    for target in logical_targets:
        if not isinstance(target, dict):
            continue
        for candidate in (
            target.get("semantic_field"),
            target.get("field"),
        ):
            field = _normalize_hakodate_sheet_field(candidate)
            if field:
                candidates.append(field)
    truth_field = _normalize_hakodate_sheet_field(truth.get("field"))
    if truth_field:
        candidates.append(truth_field)
    deduped: list[str] = []
    for field in candidates:
        if field and field not in deduped:
            deduped.append(field)
    return deduped


def _hakodate_projection_field_for_cell(
    cell: dict[str, Any],
    *,
    field_index: dict[str, int],
) -> str:
    for field in _hakodate_target_cell_field_candidates(cell):
        if field in field_index:
            return field
        if _is_hakodate_spacer_sheet_field(field):
            for placeholder_field in ("qty.unknown_x", "qty.placeholder_x"):
                if placeholder_field in field_index:
                    return placeholder_field
    return ""


def _hakodate_projection_row_for_cell(
    cell: dict[str, Any],
    *,
    row_count: int | None = None,
) -> int | None:
    sheet_cell = str(cell.get("sheet_cell") or cell.get("target_cell_id") or "").strip()
    match = re.fullmatch(r"[A-Z]+([0-9]+)", sheet_cell)
    if match:
        row_index = int(match.group(1)) - 11
        if row_index < 0:
            return None
        if row_count is None or row_index < row_count:
            return row_index
        return None
    metadata = cell.get("metadata") if isinstance(cell.get("metadata"), dict) else {}
    truth = metadata.get("truth") if isinstance(metadata.get("truth"), dict) else {}
    try:
        truth_row_index = int(truth.get("row_index"))
    except Exception:
        truth_row_index = -1
    if truth_row_index >= 0:
        if row_count is None or truth_row_index < row_count:
            return truth_row_index
        return None
    return None


def _hakodate_base_row_identity_index(
    *,
    fields: list[str],
    rows: list[list[Any]],
) -> tuple[dict[tuple[str, str, str], int], dict[tuple[str, str], int | None]]:
    field_index = {str(field or "").strip(): idx for idx, field in enumerate(fields) if str(field or "").strip()}
    date_idx = field_index.get("date_mmdd", field_index.get("date"))
    daypart_idx = field_index.get("daypart")
    menu_idx = field_index.get("menu_name", field_index.get("menu"))
    if date_idx is None or daypart_idx is None or menu_idx is None:
        return {}, {}
    result: dict[tuple[str, str, str], int] = {}
    partial: dict[tuple[str, str], int | None] = {}
    for row_index, row in enumerate(rows):
        identity = _hakodate_sheet_identity(
            row[date_idx] if date_idx < len(row) else "",
            row[daypart_idx] if daypart_idx < len(row) else "",
            row[menu_idx] if menu_idx < len(row) else "",
        )
        if all(identity) and identity not in result:
            result[identity] = row_index
            partial_key = (identity[0], identity[2])
            if partial_key in partial:
                partial[partial_key] = None
            else:
                partial[partial_key] = row_index
    return result, partial


def _hakodate_projection_row_from_logical_identity(
    cell: dict[str, Any],
    *,
    row_identity_index: dict[tuple[str, str, str], int],
    partial_row_identity_index: dict[tuple[str, str], int | None],
) -> tuple[int | None, bool]:
    candidates: list[dict[str, Any]] = [cell]
    metadata = cell.get("metadata") if isinstance(cell.get("metadata"), dict) else {}
    logical_targets = metadata.get("logical_targets") if isinstance(metadata.get("logical_targets"), list) else []
    candidates.extend(item for item in logical_targets if isinstance(item, dict))
    saw_partial_identity = False
    for candidate in candidates:
        identity = _hakodate_sheet_identity(
            candidate.get("date"),
            candidate.get("daypart"),
            candidate.get("menu_name"),
        )
        if not any(identity):
            continue
        if identity[0] and identity[2] and not identity[1]:
            partial_match = partial_row_identity_index.get((identity[0], identity[2]))
            if partial_match is not None:
                return partial_match, True
            saw_partial_identity = True
            continue
        if not all(identity):
            saw_partial_identity = True
            continue
        return row_identity_index.get(identity), True
    return None, saw_partial_identity


def _hakodate_target_field_label(cell: dict[str, Any], field: str) -> str:
    metadata = cell.get("metadata") if isinstance(cell.get("metadata"), dict) else {}
    for source in (cell, metadata):
        label = str(source.get("field_label") or "").strip()
        if label:
            return label
    logical_targets = cell.get("logical_targets") if isinstance(cell.get("logical_targets"), list) else []
    for target in logical_targets:
        if not isinstance(target, dict):
            continue
        label = str(target.get("field_label") or "").strip()
        if label:
            return label
    return _field_label(field)


def _hakodate_physical_post_menu_fields(target_cells: list[Any]) -> list[tuple[str, str]]:
    by_col: dict[int, tuple[str, str]] = {}
    for cell in target_cells:
        if not isinstance(cell, dict):
            continue
        try:
            worksheet_col = int(cell.get("worksheet_col") or 0)
        except Exception:
            worksheet_col = 0
        if worksheet_col <= 0 or worksheet_col in by_col:
            continue
        field = ""
        for candidate in _hakodate_target_cell_field_candidates(cell):
            if candidate:
                field = candidate
                break
        if not field:
            continue
        by_col[worksheet_col] = (field, _hakodate_target_field_label(cell, field))
    fields: list[tuple[str, str]] = []
    seen: set[str] = set()
    for _worksheet_col, (field, label) in sorted(by_col.items()):
        if field in seen:
            continue
        seen.add(field)
        fields.append((field, label))
    return fields


def _align_hakodate_sheet_payload_to_target_cells(
    sheet: dict[str, Any],
    target_cells: list[Any],
) -> dict[str, Any]:
    physical_fields = _hakodate_physical_post_menu_fields(target_cells)
    if not physical_fields or not any(_is_hakodate_spacer_sheet_field(field) for field, _label in physical_fields):
        return sheet
    fields = [str(field or "").strip() for field in (sheet.get("fields") or [])]
    if not fields:
        return sheet
    menu_index = fields.index("menu") if "menu" in fields else (fields.index("menu_name") if "menu_name" in fields else -1)
    if menu_index < 0:
        return sheet
    header = [str(value or "") for value in (sheet.get("header") or [])]
    old_header_by_field = {
        field: header[idx] if idx < len(header) and str(header[idx] or "").strip() else _field_label(field)
        for idx, field in enumerate(fields)
    }
    labels_by_field = {field: label for field, label in physical_fields if field}
    prefix = fields[: menu_index + 1]
    existing_after_menu = fields[menu_index + 1 :]
    next_after_menu: list[str] = []
    for field, _label in physical_fields:
        if field and field not in prefix and field not in next_after_menu:
            next_after_menu.append(field)
    for field in existing_after_menu:
        if field and field not in next_after_menu:
            next_after_menu.append(field)
    next_fields = prefix + next_after_menu
    if next_fields == fields:
        return sheet

    old_index = {field: idx for idx, field in enumerate(fields)}
    next_rows: list[list[str]] = []
    for row in (sheet.get("rows") or []):
        if not isinstance(row, list):
            continue
        next_row: list[str] = []
        for field in next_fields:
            source_index = old_index.get(field)
            next_row.append(str(row[source_index] if source_index is not None and source_index < len(row) else ""))
        next_rows.append(next_row)

    aligned = dict(sheet)
    aligned["fields"] = next_fields
    aligned["header"] = [
        labels_by_field.get(field)
        or old_header_by_field.get(field)
        or _field_label(field)
        for field in next_fields
    ]
    aligned["rows"] = next_rows
    warnings = list(aligned.get("warnings") or [])
    if "hakodate_spacer_columns_preserved" not in warnings:
        warnings.append("hakodate_spacer_columns_preserved")
    aligned["warnings"] = warnings
    return aligned


def _apply_hakodate_sheet_output_to_sheet_payload(
    *,
    base_sheet: dict[str, Any],
    assignment: dict[str, Any],
    facility_config: dict[str, Any] | None = None,
    week_sheet_name: str | None = None,
) -> dict[str, Any]:
    projected = deepcopy(base_sheet)
    fields = [str(field or "").strip() for field in (projected.get("fields") or [])]
    rows = [list(row) for row in (projected.get("rows") or []) if isinstance(row, list)]
    column_count = max(len(fields), max((len(row) for row in rows), default=0), 1)
    cell_confidence_rows = [
        ["" for _ in range(column_count)]
        for _ in range(len(rows))
    ]
    cell_score_rows = [
        ["" for _ in range(column_count)]
        for _ in range(len(rows))
    ]
    cell_provenance_rows = [
        ["" for _ in range(column_count)]
        for _ in range(len(rows))
    ]
    field_index = {field: idx for idx, field in enumerate(fields) if field}
    row_identity_index, partial_row_identity_index = _hakodate_base_row_identity_index(fields=fields, rows=rows)
    sheet_output = assignment.get("sheet_output") if isinstance(assignment.get("sheet_output"), dict) else {}
    cells = sheet_output.get("cells") if isinstance(sheet_output, dict) else {}
    target_cells = assignment.get("target_cells") if isinstance(assignment.get("target_cells"), list) else []
    target_by_sheet_cell = {
        str(target.get("sheet_cell") or target.get("target_cell_id") or "").strip(): target
        for target in target_cells
        if isinstance(target, dict) and str(target.get("sheet_cell") or target.get("target_cell_id") or "").strip()
    }
    cleared: list[dict[str, Any]] = []
    if target_cells:
        cleared_slots: set[tuple[int, int]] = set()
        for target in target_cells:
            if not isinstance(target, dict):
                continue
            logical_targets = target.get("logical_targets") if isinstance(target.get("logical_targets"), list) else []
            identity_sources = [target, *[item for item in logical_targets if isinstance(item, dict)]]
            for identity_source in identity_sources:
                source_for_field = dict(identity_source)
                source_for_field.setdefault("semantic_field", target.get("semantic_field") or target.get("field"))
                source_for_field.setdefault("worksheet_col", target.get("worksheet_col"))
                field = _hakodate_projection_field_for_cell(
                    source_for_field,
                    field_index=field_index,
                )
                col_index = field_index.get(field)
                if col_index is None:
                    continue
                source_for_row = dict(identity_source)
                source_for_row.setdefault("sheet_cell", target.get("sheet_cell") or target.get("target_cell_id"))
                source_for_row.setdefault("worksheet_row", target.get("worksheet_row"))
                row_index = _hakodate_projection_row_for_cell(
                    source_for_row,
                    row_count=len(rows),
                )
                if row_index is None or (row_index, col_index) in cleared_slots:
                    continue
                cleared_slots.add((row_index, col_index))
                while len(rows[row_index]) < len(fields):
                    rows[row_index].append("")
                previous = rows[row_index][col_index]
                rows[row_index][col_index] = ""
                if str(previous or "").strip():
                    cleared.append(
                        {
                            "row_index": row_index,
                            "field": field,
                            "previous": previous,
                            "reason": "hakodate_target_cell_reset",
                        }
                )
    applied: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    deferred: list[dict[str, Any]] = []
    ignored: list[dict[str, Any]] = []
    ocr_numeric_cell_items: list[dict[str, Any]] = []
    ocr_numeric_cell_summary = _empty_ocr_numeric_cell_summary()
    for sheet_cell, cell in sorted((cells or {}).items()):
        if not isinstance(cell, dict):
            continue
        cell = dict(cell)
        cell.setdefault("sheet_cell", sheet_cell)
        source_target = target_by_sheet_cell.get(str(sheet_cell or "").strip())
        if isinstance(source_target, dict):
            merged_cell = dict(cell)
            merged_cell.setdefault("sheet_cell", sheet_cell)
            for key in ("date", "daypart", "menu_name", "semantic_field", "field", "worksheet_row", "worksheet_col"):
                if not str(merged_cell.get(key) or "").strip() and source_target.get(key) is not None:
                    merged_cell[key] = source_target.get(key)
            if isinstance(source_target.get("metadata"), dict) and not isinstance(merged_cell.get("metadata"), dict):
                    merged_cell["metadata"] = dict(source_target.get("metadata") or {})
            cell = merged_cell
        raw_value = cell.get("value_normalized")
        if raw_value is None:
            raw_value = cell.get("value_text")
        value = str(raw_value if raw_value is not None else "").strip()
        if cell.get("assignment_state") not in {"assigned", "blank", "blank_evidence"}:
            skipped.append({**cell, "skip_reason": "assignment_state_unresolved", "value": value})
            continue
        try:
            value = hakodate_ocr_evidence_service.validate_assigned_ocr_value(cell)
            role = hakodate_ocr_evidence_service.authored_cell_role(cell)
        except ValueError as exc:
            skipped.append({**cell, "skip_reason": str(exc), "value": value})
            continue
        logical_row_index, has_logical_identity = _hakodate_projection_row_from_logical_identity(
            cell,
            row_identity_index=row_identity_index,
            partial_row_identity_index=partial_row_identity_index,
        )
        if not has_logical_identity:
            skipped.append({**cell, "skip_reason": "logical_row_identity_missing", "value": value})
            continue
        if logical_row_index is None:
            skipped.append({**cell, "skip_reason": "logical_row_identity_not_found", "value": value})
            continue
        field = _hakodate_projection_field_for_cell(
            cell,
            field_index=field_index,
        )
        col_index = field_index.get(field)
        if col_index is None:
            skipped.append({**cell, "skip_reason": "field_not_found", "value": value})
            continue
        row_index = logical_row_index
        while len(rows[row_index]) < len(fields):
            rows[row_index].append("")
        while len(cell_confidence_rows) <= row_index:
            cell_confidence_rows.append(["" for _ in range(column_count)])
            cell_score_rows.append(["" for _ in range(column_count)])
            cell_provenance_rows.append(["" for _ in range(column_count)])
        while len(cell_confidence_rows[row_index]) < column_count:
            cell_confidence_rows[row_index].append("")
            cell_score_rows[row_index].append("")
            cell_provenance_rows[row_index].append("")
        previous = rows[row_index][col_index]
        confidence = cell.get("assignment_confidence")
        classification = _hakodate_ocr_classification_for_confidence(confidence)
        confidence_tier = _hakodate_ocr_confidence_tier(confidence)
        placement_basis = _hakodate_ocr_placement_basis_for_confidence(confidence)
        if value and role == "quantity":
            ocr_numeric_cell_summary["raw_ocr_numeric_count"] += 1
            summary_key = (
                "accepted_count"
                if classification == "accepted"
                else "deterministic_candidate_count"
                if classification == "deterministic_candidate"
                else "weak_candidate_count"
                if classification == "weak_candidate"
                else "unresolved_count"
            )
            ocr_numeric_cell_summary[summary_key] += 1
            ocr_numeric_cell_items.append(
                _build_ocr_numeric_cell_item(
                    classification=classification,
                    value=value,
                    confidence_tier=confidence_tier or "low",
                    placement_basis=placement_basis,
                    read_basis="hakodate_cell_ocr_confidence_threshold",
                    source_row_index=row_index,
                    source_col_index=col_index,
                    target_row_index=row_index if classification != "unresolved" else None,
                    target_col_index=col_index if classification != "unresolved" else None,
                    date_key=str(cell.get("date") or ""),
                    daypart_key=str(cell.get("daypart") or ""),
                    menu_key=str(cell.get("menu_name") or ""),
                    reason=None if classification != "unresolved" else "below_suggestion_threshold",
                )
            )
        if classification == "accepted":
            rows[row_index][col_index] = value
            if col_index < len(cell_confidence_rows[row_index]):
                cell_confidence_rows[row_index][col_index] = confidence_tier
                cell_score_rows[row_index][col_index] = confidence
                cell_provenance_rows[row_index][col_index] = "hakodate_ocr_strict_threshold"
            applied.append(
                {
                    "sheet_cell": sheet_cell,
                    "row_index": row_index,
                    "field": field,
                    "previous": previous,
                    "value": value,
                    "confidence_tier": confidence_tier,
                    "classification": classification,
                    "assignment_cell": cell,
                }
            )
            continue
        deferred.append(
            {
                **cell,
                "defer_reason": "hakodate_ocr_confidence_below_strict_threshold",
                "row_index": row_index,
                "field": field,
                "value": value,
                "confidence_tier": confidence_tier,
                "classification": classification,
            }
        )
    if facility_config is None:
        raise ValueError("hakodate_projection_config_required")
    # Explicit logical targets have already been expanded by the evidence service.
    projected["rows"] = rows
    projected["fields"] = fields
    projected["cell_confidence_rows"] = cell_confidence_rows
    projected["cell_score_rows"] = cell_score_rows
    projected["cell_provenance_rows"] = cell_provenance_rows
    projected["ocr_numeric_cell_items"] = ocr_numeric_cell_items
    projected["ocr_numeric_cell_summary"] = ocr_numeric_cell_summary
    projected["source"] = "hakodate_ocr_evidence_sheet"
    projected["quantity_assignment_strategy"] = "hakodate"
    projected["hakodate_projection_version"] = HAKODATE_EVIDENCE_PROJECTION_VERSION
    projected["hakodate_assignment_status"] = assignment.get("status")
    projected["hakodate_assignment_mode"] = assignment.get("assignment_mode")
    projected["hakodate_evidence_projection"] = {
        "version": HAKODATE_EVIDENCE_PROJECTION_VERSION,
        "applied": applied,
        "skipped": skipped,
        "deferred": deferred,
        "ignored": ignored,
        "cleared": cleared,
        "metrics": {
            "assignment_count": len(cells or {}),
            "applied_count": len(applied),
            "skipped_count": len(skipped),
            "deferred_count": len(deferred),
            "ignored_count": len(ignored),
            "cleared_legacy_cell_count": len(cleared),
            "expanded_cell_same_daypart_filled_count": 0,
        },
    }
    blockers = list(assignment.get("blockers") or [])
    if skipped or any(item["value"] != "" for item in deferred):
        blockers.append("hakodate_sheet_projection_incomplete")
    projected["blockers"] = sorted(set(str(item) for item in blockers if str(item).strip()))
    projected["warnings"] = sorted(
        set(
            [
                *(str(item) for item in (projected.get("warnings") or []) if str(item).strip()),
                *(str(item) for item in (assignment.get("warnings") or []) if str(item).strip()),
            ]
        )
    )
    projected["review_state"] = "blocked" if projected["blockers"] else str(assignment.get("status") or "review_required")
    return projected


def _build_hakodate_weekly_menu_base_sheet(order_id: str, *, synchronous_write_input: dict[str, Any] | None = None, processing_read_input: dict[str, Any] | None = None) -> tuple[dict[str, Any] | None, str | None]:
    original_input = synchronous_write_input if synchronous_write_input is not None else processing_read_input
    if not isinstance(original_input, dict):
        return None, "hakodate_captured_config_required"
    if synchronous_write_input is not None:
        input_versions = original_input.get("input_versions")
        original_order = input_versions.get("order") if isinstance(input_versions, dict) else None
    else:
        original_order = original_input.get("order")
    if not isinstance(original_order, dict):
        return None, "hakodate_captured_config_required"
    if original_order.get("id") != order_id:
        return None, "hakodate_original_expectation_required"
    facility_id, week_id, received_at = original_order.get("facility_code"), original_order.get("week_code"), original_order.get("received_at")
    if not facility_id:
        return None, "facility_missing"
    if not week_id:
        return None, "week_unresolved"
    if isinstance(received_at, str):
        try:
            received_at = datetime.fromisoformat(received_at)
        except ValueError:
            return None, "processing_start_received_at_invalid"
    if not isinstance(received_at, datetime):
        return None, "processing_start_received_at_required"
    facility_config = deepcopy(((original_input or {}).get("configured_input") or {}).get("facility"))
    if not isinstance(facility_config, dict) or facility_config.get("facility_id") != facility_id:
        return None, "hakodate_captured_config_required"
    template = facility_config.get("fax_template")
    if not isinstance(template, dict):
        return None, "template_unresolved"
    effective_template_id = template.get("template_id")
    try:
        config_service._validate_authored_facility_config(facility_config, effective_template_id)
    except ValueError as exc:
        return None, str(exc)
    fields, field_index = _build_sheet_fields_and_indexes(template)
    field_error = _validate_sheet_template_fields(fields, template=template)
    if field_error:
        return None, field_error
    header = _sheet_header_from_template(fields, template)
    if not isinstance(original_input, dict) or not isinstance(original_input.get("physical_menu_entries"), list):
        return None, "physical_menu_start_input_missing"
    entries = deepcopy(original_input["physical_menu_entries"])
    if not entries:
        return None, "menu_entries_missing"
    row_items, source = _build_rows_from_menu_entries(
        entries=entries,
        fields=fields,
        field_index=field_index,
        header=header,
        line_dates=set(),
        source="weekly_menu",
        payload_dates=set(),
        payload_row_count=0,
        scope_anchor_date=received_at.date(),
    )
    rows = [
        list(item.get("values") or [])
        for item in row_items
        if isinstance(item, dict) and isinstance(item.get("values"), list)
    ]
    if not rows:
        return None, "menu_entries_missing"
    original_physical_ids = hakodate_physical_menu_row_service.physical_row_ids_from_entries(entries)
    physical_row_ids = [item["physical_menu_row_id"] for item in row_items]
    if len(physical_row_ids) != len(original_physical_ids) or set(physical_row_ids) != set(original_physical_ids):
        return None, "physical_menu_rows_unresolved"
    physical_row_count = len(physical_row_ids)
    if physical_row_count <= 0:
        return None, "physical_menu_rows_unresolved"
    return {
        "order_id": order_id,
        "facility_id": facility_id,
        "week_id": week_id,
        "template_id": effective_template_id or str(template.get("template_id") or "").strip() or None,
        "fields": fields,
        "header": header,
        "rows": rows,
        "row_ids": [item["row_id"] for item in row_items],
        "physical_menu_row_ids": physical_row_ids,
        "physical_menu_row_count": physical_row_count,
        "source": f"hakodate_{source}_template",
        "warnings": [],
        "blockers": [],
        "review_state": "review_required",
    }, None


def build_order_hakodate_assignment(
    order_id: str,
    *,
    strategy: str | None = None,
    grid_params: Optional[dict] = None,
    allow_artifact_repair: bool = True,
    evidence_run_override: dict[str, Any] | None = None,
    persist_artifact_repair: bool = True,
    synchronous_write_input: dict[str, Any] | None = None,
    expected_revision: int | None = None,
) -> tuple[dict[str, Any] | None, str | None]:
    job_owned = _workflow_ocr_job_id.get() is not None or current_nonworkflow_execution() is not None
    operator_write = allow_artifact_repair and persist_artifact_repair and not job_owned
    if operator_write:
        if expected_revision is None:
            return None, "workflow_revision_required"
        if type(expected_revision) is not int or expected_revision < 1:
            return None, "workflow_revision_invalid"
        with session_scope() as session:
            state = session.get(OrderWorkflowState, order_id)
            if state is None or state.revision != expected_revision:
                return None, "workflow_revision_conflict"
            if synchronous_write_input is None:
                synchronous_write_input = _capture_synchronous_cache_write_input(order_id, write_session=session)
        if synchronous_write_input is not None and synchronous_write_input.get("workflow_revision") != expected_revision:
            return None, "workflow_revision_conflict"
    if (
        synchronous_write_input is None and allow_artifact_repair
        and persist_artifact_repair and not job_owned
    ):
        return None, "synchronous_input_missing"
    _ = strategy
    _ = grid_params
    if not allow_artifact_repair and synchronous_write_input is None and not job_owned:
        try:
            synchronous_write_input = _capture_synchronous_cache_write_input(order_id)
        except ValueError as exc:
            return None, str(exc)
        if synchronous_write_input is None:
            return None, "synchronous_input_missing"
    captured_config = (synchronous_write_input or {}).get("configured_input")
    processing_input = processing_start_read_input() if job_owned else None
    if captured_config is None and job_owned:
        from src.services.workflow_attempt_guard_service import processing_start_configured_input
        captured_config = processing_start_configured_input()
    if not allow_artifact_repair and synchronous_write_input is not None:
        try:
            _validate_selected_hakodate_artifacts(synchronous_write_input["evidence"], synchronous_write_input)
        except ValueError as exc:
            return None, str(exc)
    if synchronous_write_input is not None and "hakodate_base_sheet" not in synchronous_write_input:
        base_sheet, base_error = _build_hakodate_weekly_menu_base_sheet(order_id, synchronous_write_input=synchronous_write_input)
        if base_error:
            return None, base_error
        synchronous_write_input["hakodate_base_sheet"] = deepcopy(base_sheet)
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return None, "order_not_found"
        facility_id = str(order.facility_code or "").strip() or None
        week_code = str(order.week_code or "").strip() or None
    if synchronous_write_input is not None:
        original_order = synchronous_write_input["input_versions"]["order"]
        facility_id, week_code = original_order["facility_code"], original_order["week_code"]
    elif processing_input is not None:
        facility_id, week_code = processing_input["order"]["facility_code"], processing_input["order"]["week_code"]
    if not facility_id:
        return None, "facility_missing"

    selected_evidence = evidence_run_override
    if selected_evidence is None and processing_input is not None:
        selected_evidence = processing_input.get("evidence")
    if isinstance(synchronous_write_input, dict):
        if selected_evidence is not None and selected_evidence != synchronous_write_input["evidence"]:
            return None, "synchronous_evidence_conflict"
        selected_evidence = synchronous_write_input["evidence"]
    if selected_evidence is not None:
        if selected_evidence.get("order_id") != order_id or not isinstance(selected_evidence.get("payload_json"), dict):
            return None, "evidence_lineage_missing"
        payload = deepcopy(selected_evidence["payload_json"])
    else:
        return None, "evidence_lineage_missing"
    facility_config, template, effective_template_id, template_error = _resolve_effective_sheet_template(
        order_id=order_id,
        facility_id=facility_id,
        ocr_payload=payload,
        log_context="Hakodate assignment template lookup failed",
        facility_config=(captured_config or {}).get("facility"),
    )
    if not facility_config:
        return None, template_error or "facility_not_found"
    if not isinstance(template, dict):
        return None, template_error or "template_unresolved"

    template_to_use = dict(template)
    template_to_use["facility_id"] = facility_id
    month_id, week_start, week_end = sheet_week_service.parse_sheet_week_value(week_code)
    if week_start and week_end:
        template_to_use["hakodate_week_sheet_name"] = order_form_service._format_week_sheet_name(week_start, week_end)  # noqa: SLF001
    elif month_id:
        template_to_use["hakodate_week_sheet_name"] = str(week_code or "").strip()

    requested_strategy = hakodate_assignment_service.normalize_quantity_assignment_strategy(strategy)
    repaired_own_result = False
    try:
        needs_artifact_repair = allow_artifact_repair and (
            requested_strategy == "hakodate"
            or not _payload_has_hakodate_target_cells(payload)
            or not _payload_has_hakodate_evidence_records(payload, order_id=order_id)
        )
    except ValueError as exc:
        return None, str(exc)
    if needs_artifact_repair:
        repaired_payload = _augment_hakodate_ocr_payload_artifacts(
            order_id=order_id,
            payload=payload,
            template=template_to_use,
            force_hakodate=requested_strategy == "hakodate",
            selected_pdf_receipt=(synchronous_write_input or {}).get("selected_pdf_receipt"),
            configured_input=captured_config,
            synchronous_write_input=synchronous_write_input,
        )
        if (repaired_payload.get("hakodate_canonical_pipeline") or {}).get("status") == "blocked":
            return None, "hakodate_artifact_repair_failed"
        if (
            _payload_has_hakodate_target_cells(repaired_payload)
            and _payload_has_hakodate_evidence_records(repaired_payload, order_id=order_id)
        ):
            payload = repaired_payload
            repaired_own_result = True
            if persist_artifact_repair:
                saved = _save_order_ocr_cache(
                    order_id,
                    payload,
                    job_id=_workflow_ocr_job_id.get(),
                    synchronous_write_input=synchronous_write_input,
                    augment_hakodate_artifacts=False,
                    preserve_existing_artifacts=False,
                    persist_evidence=False,
                    refresh_workflow=False,
                )
                if saved is None:
                    return None, "workflow_revision_conflict" if operator_write else "synchronous_input_conflict"
        else:
            return None, "hakodate_artifact_repair_failed"

    if synchronous_write_input is not None or job_owned:
        try:
            if synchronous_write_input is not None and not repaired_own_result:
                _validate_selected_hakodate_artifacts(selected_evidence, synchronous_write_input)
            else:
                receipt = (synchronous_write_input or {}).get("selected_pdf_receipt") or processing_start_pdf_receipt()
                _validate_hakodate_owned_artifacts(payload, _hakodate_owned_source(captured_config, receipt, synchronous_write_input))
        except ValueError as exc:
            return None, str(exc)
    try:
        baseline = _resolve_llm_review_baseline(
            order_id=order_id,
            payload=payload,
            template=template_to_use,
        )
    except _CanonicalOcrProjectionError as exc:
        return None, str(exc)
    skeleton_rows = _hakodate_skeleton_rows_from_baseline(baseline)
    assignment = _build_hakodate_evidence_assignment_from_payload(
        order_id=order_id,
        facility_id=facility_id,
        template_id=effective_template_id or str(template_to_use.get("template_id") or "").strip() or None,
        payload=payload,
        facility_config=facility_config,
    )
    assignment["baseline_source"] = baseline.get("baseline_source") if isinstance(baseline, dict) else None
    assignment["baseline_row_count"] = len(skeleton_rows)
    assignment["quantity_assignment_strategy"] = assignment.get("strategy")
    if not allow_artifact_repair and synchronous_write_input is not None:
        try:
            current_authority = _capture_synchronous_cache_write_input(order_id)
        except ValueError as exc:
            return None, str(exc)
        if current_authority is None or any(not snapshots_equal(synchronous_write_input.get(key), value) for key, value in current_authority.items()):
            return None, "synchronous_input_conflict"
    return assignment, None


def build_order_hakodate_template_candidate(
    order_id: str,
) -> tuple[dict[str, Any] | None, str | None]:
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return None, "order_not_found"
        facility_id = str(order.facility_code or "").strip() or None
    if not facility_id:
        return None, "facility_missing"

    payload = _load_order_ocr_cache(order_id)
    payload = payload if isinstance(payload, dict) else {}
    facility_config, template, effective_template_id, template_error = _resolve_effective_sheet_template(
        order_id=order_id,
        facility_id=facility_id,
        ocr_payload=payload,
        log_context="Hakodate template candidate lookup failed",
    )
    if not facility_config:
        return None, template_error or "facility_not_found"
    if not isinstance(template, dict):
        return None, template_error or "template_unresolved"

    template_to_use = dict(template)
    template_to_use["facility_id"] = facility_id
    try:
        baseline = _resolve_llm_review_baseline(
            order_id=order_id,
            payload=payload,
            template=template_to_use,
        )
    except _CanonicalOcrProjectionError as exc:
        return None, str(exc)
    skeleton_rows = _hakodate_skeleton_rows_from_baseline(baseline)
    candidate = hakodate_assignment_service.build_facility_template_regeneration_candidate(
        template_to_use,
        facility_id=facility_id,
        skeleton_rows=skeleton_rows,
    )
    candidate["order_id"] = order_id
    candidate["facility_id"] = facility_id
    candidate["template_id"] = effective_template_id or template_to_use.get("template_id")
    candidate["baseline_source"] = baseline.get("baseline_source") if isinstance(baseline, dict) else None
    candidate["baseline_row_count"] = len(skeleton_rows)
    return candidate, None


def approve_order_hakodate_template_candidate(
    order_id: str,
) -> tuple[dict[str, Any] | None, str | None]:
    _ = order_id
    return None, "legacy_hakodate_template_candidate_approval_removed"


def clone_order_for_hakodate_audit(
    order_id: str,
) -> tuple[dict[str, Any] | None, str | None]:
    source_id = str(order_id or "").strip()
    if not source_id:
        return None, "order_not_found"
    created_order: dict[str, Any] | None = None
    clone_id = _make_order_id()
    with session_scope() as session:
        source = session.get(Order, source_id)
        if not source:
            return None, "order_not_found"
        while session.get(Order, clone_id):
            clone_id = _make_order_id()
        now = datetime.utcnow()
        clone = Order(
            id=clone_id,
            facility_code=source.facility_code,
            week_code=source.week_code,
            status="要確認",
            current_document_id=source.current_document_id,
            superseded_document_ids=[],
            document_uri=source.document_uri,
            message_id=f"HKD-AUDIT:{source.id}:{now.strftime('%Y%m%d%H%M%S')}:{uuid4().hex[:6]}",
            received_at=source.received_at or now,
            lines_updated_at=source.lines_updated_at,
            archived_at=None,
            archived_by=None,
        )
        session.add(clone)
        for line in source.lines or []:
            session.add(
                OrderLine(
                    id=_make_line_id(),
                    order_id=clone_id,
                    line_id=line.line_id,
                    date=line.date,
                    daypart=line.daypart,
                    menu_name=line.menu_name,
                    diet_type=line.diet_type,
                    area_id=line.area_id,
                    bag_type=line.bag_type,
                    quantity_original=line.quantity_original,
                    quantity_corrected=line.quantity_corrected,
                    change_note=line.change_note,
                )
            )
        snapshot = session.execute(
            select(OrderMenuSnapshot).where(OrderMenuSnapshot.order_id == source_id)
        ).scalar_one_or_none()
        if snapshot:
            session.add(
                OrderMenuSnapshot(
                    id=f"OMS{uuid4().hex[:10]}",
                    order_id=clone_id,
                    snapshot_json=deepcopy(snapshot.snapshot_json),
                    created_at=now,
                )
            )
        cache = session.get(OrderOcrCache, source_id)
        if cache and isinstance(cache.payload, dict):
            payload = deepcopy(cache.payload)
            audit_meta = dict(payload.get("hakodate_audit") or {})
            audit_meta.update(
                {
                    "source_order_id": source_id,
                    "cloned_order_id": clone_id,
                    "cloned_at": now.isoformat(),
                    "purpose": "hakodate_non_destructive_comparison",
                }
            )
            payload["hakodate_audit"] = audit_meta
            session.add(
                OrderOcrCache(
                    order_id=clone_id,
                    payload=payload,
                    updated_at=now,
                )
            )
        session.flush()
        session.refresh(clone)
        created_order = serialize_order(clone, allow_unresolved_menu_amount=True)
    _invalidate_orders_cache()
    try:
        workflow = workflow_state_service.refresh_workflow_state(clone_id)
    except Exception as exc:  # noqa: BLE001
        logger.warning("Workflow state refresh failed after Hakodate audit clone", order_id=clone_id, error=str(exc))
        workflow = None
    return {
        "source_order_id": source_id,
        "cloned_order_id": clone_id,
        "order": created_order,
        "workflow_state": workflow,
        "copied": {
            "order": True,
            "lines": True,
            "ocr_cache": True,
            "drafts": False,
            "evidence_runs": False,
            "current_state": False,
        },
    }, None


def build_order_hakodate_projected_sheet(
    order_id: str,
    *,
    strategy: str | None = None,
    grid_params: Optional[dict] = None,
    evidence_run_override: dict[str, Any] | None = None,
    expected_revision: int | None = None,
    synchronous_write_input: dict[str, Any] | None = None,
) -> tuple[dict[str, Any] | None, str | None]:
    if evidence_run_override is None and _workflow_ocr_job_id.get() is None and synchronous_write_input is None:
        if expected_revision is None:
            return None, "workflow_revision_required"
        if type(expected_revision) is not int or expected_revision < 1:
            return None, "workflow_revision_invalid"
        with session_scope() as session:
            workflow = session.get(OrderWorkflowState, order_id)
            if workflow is None or workflow.revision != expected_revision:
                return None, "workflow_revision_conflict"
            synchronous_write_input = _capture_synchronous_cache_write_input(order_id, write_session=session)
        if synchronous_write_input is None:
            return None, "synchronous_input_missing"
    processing_input = processing_start_read_input() if synchronous_write_input is None and _workflow_ocr_job_id.get() is not None else None
    if synchronous_write_input is None and processing_input is None:
        return None, "synchronous_input_missing"
    if synchronous_write_input is not None and "hakodate_base_sheet" in synchronous_write_input:
        sheet, sheet_error = deepcopy(synchronous_write_input["hakodate_base_sheet"]), None
    else:
        sheet, sheet_error = _build_hakodate_weekly_menu_base_sheet(order_id, synchronous_write_input=synchronous_write_input, processing_read_input=processing_input)
    if sheet_error or not isinstance(sheet, dict):
        return None, sheet_error or "sheet_unavailable"
    if synchronous_write_input is not None:
        synchronous_write_input["hakodate_base_sheet"] = deepcopy(sheet)
    assignment, assignment_error = build_order_hakodate_assignment(
        order_id,
        strategy=strategy,
        grid_params=grid_params,
        evidence_run_override=evidence_run_override,
        persist_artifact_repair=evidence_run_override is None,
        expected_revision=expected_revision,
        synchronous_write_input=synchronous_write_input,
    )
    if assignment_error:
        return None, assignment_error
    if not isinstance(assignment, dict):
        return None, "assignment_unavailable"
    projected = _apply_hakodate_sheet_output_to_sheet_payload(
        base_sheet=sheet,
        assignment=assignment,
        facility_config=(synchronous_write_input or processing_input)["configured_input"]["facility"],
    )
    if isinstance(evidence_run_override, dict):
        projected["base_evidence_run_id"] = evidence_run_override.get("id")
    projection = projected.get("hakodate_evidence_projection")
    metrics = projection.get("metrics") if isinstance(projection, dict) else {}
    return {
        "order_id": order_id,
        "assignment": assignment,
        "projected_sheet": projected,
        "applied": list((projection or {}).get("applied") or []) if isinstance(projection, dict) else [],
        "skipped": list((projection or {}).get("skipped") or []) if isinstance(projection, dict) else [],
        "metrics": {
            "assignment_count": int((metrics or {}).get("assignment_count") or 0),
            "applied_count": int((metrics or {}).get("applied_count") or 0),
            "skipped_count": int((metrics or {}).get("skipped_count") or 0),
        },
    }, None


def _summarize_sheet_quantity_payload(payload: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(payload, dict):
        return {
            "available": False,
            "fields_count": 0,
            "rows_count": 0,
            "quantity_column_count": 0,
            "quantity_cell_count": 0,
        }
    fields = [str(field or "") for field in (payload.get("fields") or [])]
    rows = payload.get("rows") if isinstance(payload.get("rows"), list) else []
    quantity_indexes = [
        idx
        for idx, field in enumerate(fields)
        if field.startswith("qty.") or field.startswith("quantity")
    ]
    quantity_cell_count = 0
    for row in rows:
        if not isinstance(row, list):
            continue
        for idx in quantity_indexes:
            if idx < len(row) and str(row[idx] or "").strip():
                quantity_cell_count += 1
    return {
        "available": True,
        "source": payload.get("source"),
        "review_state": payload.get("review_state"),
        "can_apply": payload.get("can_apply"),
        "can_confirm": payload.get("can_confirm"),
        "warnings": list(payload.get("warnings") or []),
        "apply_blockers": list(payload.get("apply_blockers") or []),
        "confirm_blockers": list(payload.get("confirm_blockers") or []),
        "fields_count": len(fields),
        "rows_count": len(rows),
        "quantity_column_count": len(quantity_indexes),
        "quantity_cell_count": quantity_cell_count,
    }


def _summarize_hakodate_assignment_payload(payload: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(payload, dict):
        return {"available": False}
    assignments = payload.get("assignments") if isinstance(payload.get("assignments"), list) else []
    review_candidates = payload.get("review_candidates") if isinstance(payload.get("review_candidates"), list) else []
    rejected_candidates = payload.get("rejected_candidates") if isinstance(payload.get("rejected_candidates"), list) else []
    return {
        "available": True,
        "status": payload.get("status"),
        "strategy": payload.get("strategy"),
        "quantity_assignment_strategy": payload.get("quantity_assignment_strategy"),
        "blockers": list(payload.get("blockers") or []),
        "warnings": list(payload.get("warnings") or []),
        "template_signature": (
            payload.get("template_signature")
            if isinstance(payload.get("template_signature"), dict)
            else None
        ),
        "metrics": payload.get("metrics") if isinstance(payload.get("metrics"), dict) else {},
        "assignments_count": len(assignments),
        "review_candidates_count": len(review_candidates),
        "rejected_candidates_count": len(rejected_candidates),
        "assignment_sample": assignments[:20],
        "review_candidate_sample": review_candidates[:20],
    }


def build_order_quantity_assignment_comparison(
    order_id: str,
    *,
    strategy: str | None = None,
    grid_params: Optional[dict] = None,
    expected_revision: int | None = None,
) -> tuple[dict[str, Any] | None, str | None]:
    if expected_revision is None:
        return None, "workflow_revision_required"
    if type(expected_revision) is not int or expected_revision < 1:
        return None, "workflow_revision_invalid"
    with session_scope() as session:
        state = session.get(OrderWorkflowState, order_id)
        if state is None or state.revision != expected_revision:
            return None, "workflow_revision_conflict"
        synchronous_write_input = _capture_synchronous_cache_write_input(order_id, write_session=session)
    if synchronous_write_input is None:
        return None, "synchronous_input_missing"
    with session_scope() as session:
        if not session.get(Order, order_id):
            return None, "order_not_found"

    legacy_payload, legacy_error = get_ocr_sheet(order_id, synchronous_write_input=synchronous_write_input)
    hakodate_payload, hakodate_error = build_order_hakodate_assignment(
        order_id,
        strategy=strategy,
        grid_params=grid_params,
        synchronous_write_input=synchronous_write_input,
        expected_revision=expected_revision,
    )
    if hakodate_error:
        return None, hakodate_error
    return (
        {
            "order_id": order_id,
            "legacy": {
                "error": legacy_error,
                "summary": _summarize_sheet_quantity_payload(
                    legacy_payload if isinstance(legacy_payload, dict) else None
                ),
            },
            "hakodate": {
                "error": hakodate_error,
                "summary": _summarize_hakodate_assignment_payload(
                    hakodate_payload if isinstance(hakodate_payload, dict) else None
                ),
            },
        },
        None,
    )


def detect_order_grid(
    order_id: str,
    table_box: Optional[list[float]] = None,
    grid_params: Optional[dict] = None,
):
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return None, "order_not_found", None
        document_uri = order.document_uri
        facility_id = order.facility_code
        if not document_uri:
            return None, "document_missing", None
        if not facility_id:
            return None, "facility_unresolved", None
        try:
            selected_pdf_receipt = capture_selected_pdf_receipt(session, order)
            configured_input = _capture_selected_order_config(session, order)
        except ValueError as exc:
            return None, str(exc), {"reason": str(exc)}
    if not document_uri:
        return None, "document_missing", None
    if not facility_id:
        return None, "facility_unresolved", None
    template = deepcopy(configured_input["facility"]["fax_template"])
    if not isinstance(template, dict) or not template:
        return None, "template_not_found", None
    override_box = None
    if isinstance(table_box, list) and len(table_box) >= 4:
        try:
            override_box = [float(value) for value in table_box[:4]]
        except (TypeError, ValueError):
            override_box = None
    template_to_use = dict(template)
    if override_box:
        template_to_use["grid_table_box"] = override_box
        template_to_use["table_box"] = override_box
    grid_source = None
    if isinstance(grid_params, dict) and grid_params:
        for key, value in grid_params.items():
            if not key.startswith("grid_"):
                continue
            if value is None:
                continue
            if key == "grid_auto_table_box":
                if isinstance(value, bool):
                    template_to_use[key] = value
                elif isinstance(value, str):
                    template_to_use[key] = value.strip().lower() in {"1", "true", "yes", "on"}
                continue
            if key == "grid_auto_use_raw_edges":
                if isinstance(value, bool):
                    template_to_use[key] = value
                elif isinstance(value, str):
                    template_to_use[key] = value.strip().lower() in {"1", "true", "yes", "on"}
                continue
            if key == "grid_source":
                if isinstance(value, str):
                    grid_source = value.strip().lower()
                continue
            if key in {
                "grid_dpi",
                "grid_line_scale",
                "grid_line_scale_horizontal",
                "grid_line_scale_vertical",
                "grid_line_merge_gap",
                "grid_expected_columns",
            }:
                try:
                    parsed = int(value)
                except (TypeError, ValueError):
                    continue
                if parsed < 0:
                    continue
                template_to_use[key] = parsed
                continue
            try:
                parsed = float(value)
            except (TypeError, ValueError):
                continue
            template_to_use[key] = parsed
    try:
        import cv2  # noqa: F401
    except Exception:  # noqa: BLE001
        return None, "grid_not_found", {"reason": "grid_detector_unavailable"}
    try:
        from src.services.storage_service import load_selected_pdf_bytes
        pdf_bytes = load_selected_pdf_bytes(document_uri, selected_pdf_receipt)
    except Exception:  # noqa: BLE001
        return None, "document_load_failed", None
    if grid_source not in {None, "pdf"}:
        return None, "grid_source_receipt_required", {"reason": "unverified_derived_grid_source"}
    try:
        selected_page = _authored_geometry_page({"facility": {"fax_template": template}})
    except ValueError as exc:
        return None, str(exc), {"reason": str(exc)}
    import fitz
    with fitz.open(stream=pdf_bytes, filetype="pdf") as selected_document:
        if selected_page > selected_document.page_count:
            return None, "selected_pdf_page_invalid", {"reason": "authored_page_absent"}
    template_to_use["page"] = selected_page
    grid = detect_table_grid(pdf_bytes, template_to_use)
    source = "pdf"
    if not grid:
        table_box = template_to_use.get("grid_table_box") or template_to_use.get("table_box") or [0, 0, 1, 1]
        try:
            table_box = [float(value) for value in table_box[:4]]
        except (TypeError, ValueError):
            table_box = [0, 0, 1, 1]
        expected = int(template_to_use.get("grid_expected_columns", 0) or 0)
        if expected <= 0:
            grid_columns = template_to_use.get("grid_columns") or []
            expected = len(grid_columns)
        reason = "grid_not_found"
        if isinstance(table_box, list) and any(value > 1.5 for value in table_box):
            reason = "table_box_units_mismatch"
        elif expected <= 1:
            reason = "expected_columns_missing"
        return None, "grid_not_found", {"reason": reason, "expected_columns": expected, "table_box": table_box}
    return (
        {
            "table_box": grid.table_box,
            "grid_column_edges": grid.column_edges,
            "grid_row_edges": grid.row_edges,
            "confidence": grid.confidence,
            "fallback": False,
            "source": source,
            "table_units": "normalized",
        },
        None,
        None,
    )


class RemovedOcrProviderError(ValueError):
    pass


def _normalize_reparse_provider(value: str | None) -> str | None:
    if not value:
        return None
    normalized = str(value).strip().lower()
    if normalized in {"pipeline", "openai", "gemini"}:
        return normalized
    if normalized == "tesseract":
        raise RemovedOcrProviderError("ocr_provider=tesseract has been removed")
    return None


def _build_reparse_quality_metadata(
    *,
    requested_provider: str | None,
    effective_provider: str | None,
    llm_assist: bool,
    auto_fallback_applied: bool,
    feedback_retry_depth: int,
) -> dict[str, Any]:
    normalized_requested = _normalize_reparse_provider(requested_provider)
    normalized_effective = _normalize_reparse_provider(effective_provider)
    is_llm_reparse = bool(
        llm_assist
        or normalized_requested in {"openai", "gemini"}
        or normalized_effective in {"openai", "gemini"}
    )
    if auto_fallback_applied:
        reparse_origin = "auto_fallback"
    elif llm_assist:
        reparse_origin = "llm_assist"
    elif normalized_requested in {"openai", "gemini"}:
        reparse_origin = "provider_override"
    else:
        reparse_origin = "standard"
    return {
        "request_mode": "llm_reparse" if is_llm_reparse else "ocr_reparse",
        "requested_provider": normalized_requested or None,
        "effective_provider": normalized_effective or None,
        "llm_assist": bool(llm_assist),
        "quality_track": "llm_reparse" if is_llm_reparse else "non_llm_reparse",
        "reparse_origin": reparse_origin,
        "feedback_retry_depth": max(0, int(feedback_retry_depth)),
    }


def _resolve_explicit_reparse_inference_provider(
    *,
    requested_provider: str | None,
    llm_assist: bool,
    template: dict[str, Any],
) -> str | None:
    normalized_requested = _normalize_reparse_provider(requested_provider)
    if normalized_requested in {"openai", "gemini"}:
        return normalized_requested
    if not llm_assist:
        return normalized_requested

    configured = str(
        template.get("main_ocr_provider")
        or os.getenv("OCR_MAIN_PROVIDER")
        or ""
    ).strip().lower()
    if configured in {"openai", "gemini"}:
        return configured

    return normalized_requested




def _is_llm_finish_reason_truncated(value: object) -> bool:
    if not isinstance(value, str):
        return False
    token = value.strip().upper().replace("-", "_").replace(" ", "_")
    if token in {"MAX_TOKENS", "MAX_OUTPUT_TOKENS", "MAX_OUTPUT_TOKEN", "LENGTH"}:
        return True
    return token.startswith("MAX_")


def _extract_llm_finish_reason(extracted: object | None) -> str | None:
    if extracted is None:
        return None
    provider_debug = getattr(extracted, "provider_debug", None)
    if not isinstance(provider_debug, dict):
        return None
    finish_reason = provider_debug.get("finish_reason")
    if not isinstance(finish_reason, str):
        return None
    normalized = finish_reason.strip()
    return normalized or None


def _is_truncated_llm_output(extracted: object | None) -> bool:
    if extracted is None:
        return False
    provider_debug = getattr(extracted, "provider_debug", None)
    if not isinstance(provider_debug, dict):
        return False
    if bool(provider_debug.get("recovered_truncated_json")):
        return True
    return _is_llm_finish_reason_truncated(provider_debug.get("finish_reason"))


def _truncate_assist_text(value: str, max_chars: int = 6000) -> str:
    text = str(value or "")
    if len(text) <= max_chars:
        return text
    return f"{text[:max_chars]}\n...(truncated)"


def _looks_like_generated_reparse_prompt(value: object) -> bool:
    text = str(value or "").strip()
    if not text:
        return False
    markers = (
        "Second-pass repair mode:",
        "Second-pass OCR repair mode:",
        "Current sheet/baseline rows shown to the user:",
        "Structural block anchor summary:",
        "Evaluator feedback from previous OCR draft:",
        "Automatic fallback context:",
        "Date block layout summary:",
        "Suspicious blank-edge placement hints from the current OCR draft:",
    )
    return any(marker in text for marker in markers)


def _compact_prompt_tables(pipeline_output: dict[str, Any] | None) -> list[dict[str, Any]]:
    if not isinstance(pipeline_output, dict):
        return []
    collected: list[dict[str, Any]] = []
    seen_table_ids: set[str] = set()

    def _push(table_payload: object) -> None:
        if not isinstance(table_payload, dict):
            return
        table_id = str(table_payload.get("table_id") or "").strip()
        if table_id and table_id in seen_table_ids:
            return
        if table_id:
            seen_table_ids.add(table_id)
        rows = table_payload.get("rows")
        cells = table_payload.get("cells")
        entry: dict[str, Any] = {
            "table_id": table_id,
            "page_index": table_payload.get("page_index"),
            "row_count": table_payload.get("row_count"),
            "col_count": table_payload.get("col_count"),
        }
        if isinstance(rows, list) and rows:
            entry["rows_preview"] = rows[:12]
        if isinstance(cells, list) and cells:
            compact_cells: list[dict[str, Any]] = []
            for cell in cells[:24]:
                if not isinstance(cell, dict):
                    continue
                compact_cells.append(
                    {
                        "row_index": cell.get("row_index"),
                        "col_index": cell.get("col_index"),
                        "row_span": cell.get("row_span"),
                        "col_span": cell.get("col_span"),
                        "text": cell.get("text"),
                        "bbox": cell.get("bbox"),
                    }
                )
            if compact_cells:
                entry["cells_preview"] = compact_cells
        if entry.get("rows_preview") or entry.get("cells_preview"):
            collected.append(entry)

    top_tables = pipeline_output.get("tables")
    if isinstance(top_tables, list):
        for table_payload in top_tables[:6]:
            _push(table_payload)
    pages = pipeline_output.get("pages")
    if isinstance(pages, list):
        for page_payload in pages[:4]:
            if not isinstance(page_payload, dict):
                continue
            page_tables = page_payload.get("tables")
            if not isinstance(page_tables, list):
                continue
            for table_payload in page_tables[:4]:
                _push(table_payload)
    return collected[:6]


def _compact_prompt_quantity_subgrid_passes(
    pipeline_output: dict[str, Any] | None,
) -> list[dict[str, Any]]:
    if not isinstance(pipeline_output, dict):
        return []
    raw_passes = pipeline_output.get("quantity_subgrid_passes")
    if not isinstance(raw_passes, list):
        return []
    collected: list[dict[str, Any]] = []
    for item in raw_passes[:4]:
        if not isinstance(item, dict):
            continue
        entry: dict[str, Any] = {}
        for key in (
            "page_index",
            "table_index",
            "body_start_row",
            "menu_col_index",
            "quantity_start_col_index",
            "row_count",
            "quantity_col_count",
            "crop_box_norm",
        ):
            value = item.get(key)
            if value is not None:
                entry[key] = value
        table_raw = item.get("table_raw")
        if isinstance(table_raw, str) and table_raw.strip():
            entry["table_raw"] = _truncate_assist_text(table_raw.strip(), max_chars=4000)
        tables = item.get("tables")
        if isinstance(tables, list) and tables:
            compact_tables: list[dict[str, Any]] = []
            for table in tables[:2]:
                if not isinstance(table, dict):
                    continue
                compact_table: dict[str, Any] = {
                    "table_id": table.get("table_id"),
                    "page_index": table.get("page_index"),
                    "row_count": table.get("row_count"),
                    "col_count": table.get("col_count"),
                }
                rows = table.get("rows")
                if isinstance(rows, list) and rows:
                    compact_table["rows_preview"] = [list(row) for row in rows[:20] if isinstance(row, list)]
                if compact_table.get("rows_preview"):
                    compact_tables.append(compact_table)
            if compact_tables:
                entry["tables"] = compact_tables
        normalized_rows = item.get("normalized_rows")
        if isinstance(normalized_rows, list) and normalized_rows:
            entry["normalized_rows_preview"] = [
                list(row) for row in normalized_rows[:20] if isinstance(row, list)
            ]
        normalization_patches = item.get("normalization_patches")
        if isinstance(normalization_patches, list) and normalization_patches:
            entry["normalization_patches"] = [
                {
                    "row_index": patch.get("row_index"),
                    "col_index": patch.get("col_index"),
                    "original_text": patch.get("original_text"),
                    "normalized_text": patch.get("normalized_text"),
                    "prev_neighbor": patch.get("prev_neighbor"),
                    "next_neighbor": patch.get("next_neighbor"),
                }
                for patch in normalization_patches[:40]
                if isinstance(patch, dict)
            ]
        if entry:
            collected.append(entry)
    return collected


def _compact_prompt_cell_issues(
    pipeline_output: dict[str, Any] | None,
    template: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    if not isinstance(pipeline_output, dict):
        return []
    raw_issues = _collect_raw_payload_cell_issues(pipeline_output, template)
    compact: list[dict[str, Any]] = []
    for issue in raw_issues[:60]:
        compact.append(
            {
                "table_id": issue.get("table_id"),
                "source_row_index": issue.get("source_row_index", issue.get("row_index")),
                "column_index": issue.get("column_index"),
                "field": issue.get("field"),
                "issue_code": issue.get("issue_code"),
                "severity": issue.get("severity"),
                "bbox": issue.get("bbox"),
                "text": issue.get("text"),
                "value": issue.get("value"),
                "row_span": issue.get("row_span"),
                "col_span": issue.get("col_span"),
                "max_allowed": issue.get("max_allowed"),
                "source": issue.get("source"),
            }
        )
    return compact


def _build_llm_assist_baseline_rows(
    baseline: dict[str, Any] | None,
) -> list[dict[str, Any]]:
    if not isinstance(baseline, dict):
        return []
    fields = [str(field).strip() for field in (baseline.get("fields") or []) if str(field).strip()]
    rows = [list(row) for row in (baseline.get("rows") or []) if isinstance(row, list)]
    row_ids = [str(item).strip() for item in (baseline.get("row_ids") or []) if str(item).strip()]
    if not fields or not rows:
        return []
    return _build_llm_review_prompt_rows(
        fields=fields,
        rows=rows,
        row_ids=row_ids,
    )


def _resolve_reparse_current_sheet_baseline_rows(
    baseline: dict[str, Any] | None,
) -> tuple[list[str], list[str], list[list[str]], list[str], str]:
    if not isinstance(baseline, dict):
        return [], [], [], [], ""
    source = str(baseline.get("baseline_source") or "").strip() or "sheet"
    if source.endswith("_structure"):
        return [], [], [], [], source
    fields = [str(field).strip() for field in (baseline.get("fields") or []) if str(field).strip()]
    rows = [list(row) for row in (baseline.get("rows") or []) if isinstance(row, list)]
    if not fields or not rows:
        return [], [], [], [], source
    header = [str(cell or "").strip() for cell in (baseline.get("header") or [])]
    if len(header) < len(fields):
        header.extend([_field_label(field) for field in fields[len(header) :]])
    row_ids = [str(item).strip() for item in (baseline.get("row_ids") or []) if str(item).strip()]
    if len(row_ids) < len(rows):
        row_ids.extend([f"sheet-row-{idx + 1}" for idx in range(len(row_ids), len(rows))])
    return fields, header[: len(fields)], rows, row_ids[: len(rows)], source


def _resolve_reparse_baseline_rows_for_structure(
    baseline: dict[str, Any] | None,
) -> tuple[list[str], list[list[str]], list[str], str]:
    if not isinstance(baseline, dict):
        return [], [], [], ""
    structure_fields = baseline.get("structure_fields")
    fields = [
        str(field or "").strip()
        for field in ((structure_fields if isinstance(structure_fields, list) and structure_fields else baseline.get("fields")) or [])
        if str(field or "").strip()
    ]
    if not fields:
        return [], [], [], ""
    structural_rows = [
        list(row)
        for row in ((baseline.get("structural_rows") or baseline.get("structure_rows")) or [])
        if isinstance(row, list)
    ]
    structural_row_ids = [
        str(item).strip()
        for item in ((baseline.get("structural_row_ids") or baseline.get("structure_row_ids")) or [])
        if str(item).strip()
    ]
    structural_source = str(
        baseline.get("structural_baseline_source") or baseline.get("structure_source") or ""
    ).strip()
    if structural_rows:
        if len(structural_row_ids) < len(structural_rows):
            structural_row_ids.extend(
                [f"structural-row-{idx + 1}" for idx in range(len(structural_row_ids), len(structural_rows))]
            )
        return fields, structural_rows, structural_row_ids[: len(structural_rows)], structural_source or "structure"

    rows = [list(row) for row in (baseline.get("rows") or []) if isinstance(row, list)]
    row_ids = [str(item).strip() for item in (baseline.get("row_ids") or []) if str(item).strip()]
    if len(row_ids) < len(rows):
        row_ids.extend([f"sheet-row-{idx + 1}" for idx in range(len(row_ids), len(rows))])
    return fields, rows, row_ids[: len(rows)], str(baseline.get("baseline_source") or "").strip() or "sheet"


def _build_llm_assist_structural_rows(
    baseline: dict[str, Any] | None,
) -> list[dict[str, Any]]:
    fields, rows, row_ids, _source = _resolve_reparse_baseline_rows_for_structure(baseline)
    if not fields or not rows:
        return []
    return _build_llm_review_prompt_rows(
        fields=fields,
        rows=rows,
        row_ids=row_ids,
    )


def _build_reparse_current_sheet_markdown_anchor(
    baseline: dict[str, Any] | None,
) -> str:
    fields, header, rows, row_ids, _source = _resolve_reparse_current_sheet_baseline_rows(baseline)
    if not fields or not rows:
        return ""
    markdown_rows: list[list[str]] = []
    for idx, row in enumerate(rows):
        row_id = row_ids[idx] if idx < len(row_ids) else f"sheet-row-{idx + 1}"
        markdown_rows.append([row_id, *[_field_value_to_str(cell) for cell in row]])
    return _build_markdown_table_string(["row_id", *header], markdown_rows)


def _resolve_structural_row_field_indexes(
    fields: list[str] | None,
) -> tuple[int | None, int | None, int | None, list[int]]:
    normalized_fields = [str(field or "").strip() for field in (fields or [])]
    if not normalized_fields:
        return None, None, None, []
    date_idx = next(
        (
            idx
            for idx, field in enumerate(normalized_fields)
            if _normalize_sheet_text(field).lower().startswith("date")
        ),
        None,
    )
    daypart_idx = next(
        (
            idx
            for idx, field in enumerate(normalized_fields)
            if _normalize_sheet_text(field).lower() in {"daypart", "meal", "time"}
        ),
        None,
    )
    menu_idx = next(
        (
            idx
            for idx, field in enumerate(normalized_fields)
            if _normalize_sheet_text(field).lower() in {"menu", "menuname", "menu_name"}
        ),
        None,
    )
    quantity_indexes = [
        idx
        for idx, field in enumerate(normalized_fields)
        if str(field or "").strip().startswith("qty.")
    ]
    return date_idx, daypart_idx, menu_idx, quantity_indexes


def _build_structural_row_key(
    *,
    row: list[str],
    fields: list[str] | None,
) -> tuple[str, str, str] | None:
    date_idx, daypart_idx, menu_idx, _ = _resolve_structural_row_field_indexes(fields)
    if menu_idx is None or menu_idx >= len(row):
        return None
    menu_key = _normalize_sheet_text(row[menu_idx])
    if not menu_key:
        return None
    raw_date = row[date_idx] if date_idx is not None and date_idx < len(row) else ""
    raw_daypart = row[daypart_idx] if daypart_idx is not None and daypart_idx < len(row) else ""
    return (
        _normalize_sheet_date_key(raw_date),
        _normalize_daypart_key(raw_daypart),
        menu_key,
    )


def _build_reparse_block_anchor_hints(
    *,
    structural_fields: list[str] | None,
    structural_rows: list[list[str]],
    first_pass_fields: list[str] | None = None,
    first_pass_rows: list[list[str]] | None = None,
) -> dict[str, Any]:
    normalized_rows = [list(row) for row in structural_rows if isinstance(row, list)]
    if not normalized_rows:
        return {}

    date_idx, daypart_idx, _menu_idx, quantity_indexes = _resolve_structural_row_field_indexes(structural_fields)
    structural_blank_hint_enabled = False
    if quantity_indexes:
        for row in normalized_rows:
            has_structural_quantity = False
            for col_idx in quantity_indexes:
                if col_idx < 0 or col_idx >= len(row):
                    continue
                if _parse_strict_numeric_cell(row[col_idx]) is not None:
                    has_structural_quantity = True
                    break
            if has_structural_quantity:
                structural_blank_hint_enabled = True
                break
    blocks: list[dict[str, Any]] = []
    current_block: dict[str, Any] | None = None
    for row_idx, row in enumerate(normalized_rows):
        raw_date = row[date_idx] if date_idx is not None and date_idx < len(row) else ""
        raw_daypart = row[daypart_idx] if daypart_idx is not None and daypart_idx < len(row) else ""
        block_date = _normalize_sheet_date_key(raw_date) or str(raw_date or "").strip()
        block_daypart = _normalize_daypart_key(raw_daypart) or str(raw_daypart or "").strip()
        block_key = (block_date, block_daypart)
        has_quantity = False
        for col_idx in quantity_indexes:
            if col_idx < 0 or col_idx >= len(row):
                continue
            if _parse_strict_numeric_cell(row[col_idx]) is not None:
                has_quantity = True
                break
        if current_block is None or current_block.get("key") != block_key:
            current_block = {
                "key": block_key,
                "date_mmdd": block_date,
                "daypart": block_daypart,
                "row_start": row_idx,
                "row_end": row_idx,
                "row_count": 1,
            }
            if structural_blank_hint_enabled:
                current_block["blank_quantity_row_indexes"] = ([] if has_quantity else [row_idx])
            blocks.append(current_block)
            continue
        current_block["row_end"] = row_idx
        current_block["row_count"] = int(current_block.get("row_count") or 0) + 1
        if structural_blank_hint_enabled and not has_quantity:
            blank_indexes = current_block.get("blank_quantity_row_indexes")
            if isinstance(blank_indexes, list):
                blank_indexes.append(row_idx)

    unmatched_structural_row_indexes: list[int] = []
    matched_reference_key_count = 0
    reference_key_count = 0
    reference_alignment_weak = False
    normalized_first_rows = [list(row) for row in (first_pass_rows or []) if isinstance(row, list)]
    if normalized_first_rows:
        resolved_first_fields = list(first_pass_fields or structural_fields or [])
        first_keys = [
            key
            for key in (
                _build_structural_row_key(row=row, fields=resolved_first_fields)
                for row in normalized_first_rows
            )
            if key is not None
        ]
        reference_key_count = len(first_keys)
        if first_keys:
            first_idx = 0
            for row_idx, row in enumerate(normalized_rows):
                structure_key = _build_structural_row_key(row=row, fields=structural_fields)
                if structure_key is None:
                    continue
                if first_idx < len(first_keys) and structure_key == first_keys[first_idx]:
                    first_idx += 1
                    matched_reference_key_count += 1
                    continue
                unmatched_structural_row_indexes.append(row_idx)
            match_ratio = (
                float(matched_reference_key_count) / float(reference_key_count)
                if reference_key_count > 0
                else 0.0
            )
            if matched_reference_key_count <= 0 or match_ratio < 0.5:
                reference_alignment_weak = True
                unmatched_structural_row_indexes = []

    structural_blank_anchor_row_indexes: list[int] = []
    if structural_blank_hint_enabled:
        for block in blocks:
            blank_indexes = block.get("blank_quantity_row_indexes")
            if isinstance(blank_indexes, list):
                structural_blank_anchor_row_indexes.extend(
                    int(item)
                    for item in blank_indexes
                    if isinstance(item, int) or (isinstance(item, str) and item.isdigit())
                )
        structural_blank_anchor_row_indexes = sorted(set(structural_blank_anchor_row_indexes))

    compact_blocks: list[dict[str, Any]] = []
    for block in blocks[:48]:
        compact_block = {
            "date_mmdd": block.get("date_mmdd"),
            "daypart": block.get("daypart"),
            "row_start": block.get("row_start"),
            "row_end": block.get("row_end"),
            "row_count": block.get("row_count"),
        }
        blank_indexes = block.get("blank_quantity_row_indexes")
        if isinstance(blank_indexes, list) and blank_indexes:
            compact_block["blank_quantity_row_indexes"] = [int(idx) for idx in blank_indexes[:24]]
        compact_blocks.append(compact_block)
    return {
        "blocks": compact_blocks,
        "unmatched_structural_row_indexes": unmatched_structural_row_indexes[:160],
        "structural_blank_anchor_row_indexes": structural_blank_anchor_row_indexes[:160],
        "reference_alignment_weak": bool(reference_alignment_weak),
        "matched_reference_key_count": int(matched_reference_key_count),
        "reference_key_count": int(reference_key_count),
        "reference_key_match_ratio": (
            round(float(matched_reference_key_count) / float(reference_key_count), 4)
            if reference_key_count > 0
            else None
        ),
    }


def _normalize_prompt_block_date(value: object) -> str:
    normalized = _normalize_entry_date(value)
    if isinstance(normalized, date):
        return normalized.strftime("%m/%d")
    return str(value or "").strip()


def _prompt_row_value(row: dict[str, Any], *keys: str) -> str:
    for key in keys:
        value = str(row.get(key) or "").strip()
        if value:
            return value
    return ""


def _summarize_prompt_row_blocks(
    prompt_rows: list[dict[str, Any]] | None,
) -> list[dict[str, Any]]:
    rows = [dict(row) for row in (prompt_rows or []) if isinstance(row, dict)]
    if not rows:
        return []
    blocks: list[dict[str, Any]] = []
    current: dict[str, Any] | None = None
    for idx, row in enumerate(rows):
        date_label = _normalize_prompt_block_date(
            _prompt_row_value(row, "date_mmdd", "date", "menu_date")
        )
        daypart_raw = _prompt_row_value(row, "daypart")
        daypart = _normalize_daypart_key(daypart_raw) or daypart_raw
        menu_name = _prompt_row_value(row, "menu_name", "menu")
        key = (date_label, daypart)
        if current and current.get("_key") == key:
            current["row_end"] = idx
            current["row_count"] = int(current.get("row_count") or 0) + 1
            if menu_name:
                current_menus = current.setdefault("_menus", [])
                if menu_name not in current_menus and len(current_menus) < 4:
                    current_menus.append(menu_name)
            continue
        current = {
            "_key": key,
            "_menus": [menu_name] if menu_name else [],
            "row_start": idx,
            "row_end": idx,
            "row_count": 1,
            "date_mmdd": date_label,
            "daypart": daypart,
        }
        blocks.append(current)
    summarized: list[dict[str, Any]] = []
    for block in blocks:
        entry = {
            "row_start": int(block.get("row_start") or 0),
            "row_end": int(block.get("row_end") or 0),
            "row_count": int(block.get("row_count") or 0),
            "date_mmdd": str(block.get("date_mmdd") or ""),
            "daypart": str(block.get("daypart") or ""),
        }
        menus = [str(item).strip() for item in block.get("_menus", []) if str(item).strip()]
        if menus:
            entry["menu_examples"] = menus[:4]
        summarized.append(entry)
    return summarized


def _summarize_prompt_date_blocks(
    prompt_rows: list[dict[str, Any]] | None,
) -> list[dict[str, Any]]:
    blocks = _summarize_prompt_row_blocks(prompt_rows)
    if not blocks:
        return []
    summarized: list[dict[str, Any]] = []
    current: dict[str, Any] | None = None
    for block in blocks:
        if not isinstance(block, dict):
            continue
        date_mmdd = str(block.get("date_mmdd") or "").strip()
        row_start = block.get("row_start")
        row_end = block.get("row_end")
        row_count = block.get("row_count")
        daypart = str(block.get("daypart") or "").strip()
        if not isinstance(row_start, int) or not isinstance(row_end, int):
            continue
        if current is None or current.get("date_mmdd") != date_mmdd:
            current = {
                "date_mmdd": date_mmdd,
                "row_start": row_start,
                "row_end": row_end,
                "row_count": int(row_count or 0),
                "sub_blocks": [
                    {
                        "daypart": daypart,
                        "row_start": row_start,
                        "row_end": row_end,
                        "row_count": int(row_count or 0),
                    }
                ],
            }
            summarized.append(current)
            continue
        current["row_end"] = row_end
        current["row_count"] = int(current.get("row_count") or 0) + int(row_count or 0)
        sub_blocks = current.setdefault("sub_blocks", [])
        if isinstance(sub_blocks, list):
            sub_blocks.append(
                {
                    "daypart": daypart,
                    "row_start": row_start,
                    "row_end": row_end,
                    "row_count": int(row_count or 0),
                }
            )
    return summarized


def _summarize_tabular_row_blocks(
    rows: list[list[str]] | None,
    *,
    date_index: int = 0,
    daypart_index: int = 1,
    menu_index: int = 2,
) -> list[dict[str, Any]]:
    prompt_rows: list[dict[str, Any]] = []
    for idx, row in enumerate(rows or []):
        if not isinstance(row, list):
            continue
        prompt_rows.append(
            {
                "row_id": f"row-{idx + 1}",
                "date_mmdd": row[date_index] if date_index < len(row) else "",
                "daypart": row[daypart_index] if daypart_index < len(row) else "",
                "menu_name": row[menu_index] if menu_index < len(row) else "",
            }
        )
    return _summarize_prompt_row_blocks(prompt_rows)


def _summarize_tabular_date_blocks(
    rows: list[list[str]] | None,
    *,
    date_index: int = 0,
    daypart_index: int = 1,
    menu_index: int = 2,
) -> list[dict[str, Any]]:
    prompt_rows: list[dict[str, Any]] = []
    for idx, row in enumerate(rows or []):
        if not isinstance(row, list):
            continue
        prompt_rows.append(
            {
                "row_id": f"row-{idx + 1}",
                "date_mmdd": row[date_index] if date_index < len(row) else "",
                "daypart": row[daypart_index] if daypart_index < len(row) else "",
                "menu_name": row[menu_index] if menu_index < len(row) else "",
            }
        )
    return _summarize_prompt_date_blocks(prompt_rows)


def _collect_candidate_blank_edge_hints(
    *,
    candidate_rows: list[list[str]] | None,
    quantity_columns: list[dict[str, str | int]] | None,
    date_blocks: list[dict[str, Any]] | None,
) -> list[dict[str, Any]]:
    normalized_rows = [list(row) for row in (candidate_rows or []) if isinstance(row, list)]
    if not normalized_rows:
        return []
    quantity_indexes: list[int] = []
    for column in quantity_columns or []:
        try:
            col_idx = int(column.get("index"))  # type: ignore[arg-type]
        except Exception:
            continue
        if col_idx >= 0:
            quantity_indexes.append(col_idx)
    if not quantity_indexes:
        return []

    hints: list[dict[str, Any]] = []
    for block in date_blocks or []:
        if not isinstance(block, dict):
            continue
        row_start = block.get("row_start")
        row_end = block.get("row_end")
        if not isinstance(row_start, int) or not isinstance(row_end, int):
            continue
        if row_start < 0 or row_end < row_start:
            continue
        row_indexes = list(range(row_start, min(row_end, len(normalized_rows) - 1) + 1))
        if not row_indexes:
            continue
        filled_row_indexes: list[int] = []
        blank_row_indexes: list[int] = []
        for row_idx in row_indexes:
            row = normalized_rows[row_idx]
            has_numeric = False
            for col_idx in quantity_indexes:
                if col_idx < len(row) and _parse_strict_numeric_cell(row[col_idx]) is not None:
                    has_numeric = True
                    break
            if has_numeric:
                filled_row_indexes.append(row_idx)
            else:
                blank_row_indexes.append(row_idx)
        if not filled_row_indexes or not blank_row_indexes:
            continue
        leading_blank_count = 0
        for row_idx in row_indexes:
            if row_idx in blank_row_indexes:
                leading_blank_count += 1
                continue
            break
        trailing_blank_count = 0
        for row_idx in reversed(row_indexes):
            if row_idx in blank_row_indexes:
                trailing_blank_count += 1
                continue
            break
        if trailing_blank_count <= 0 or leading_blank_count > 0:
            continue
        hint = {
            "date_mmdd": block.get("date_mmdd"),
            "row_start": row_start,
            "row_end": row_end,
            "filled_row_indexes": filled_row_indexes[:40],
            "blank_row_indexes": blank_row_indexes[:40],
            "trailing_blank_row_indexes": row_indexes[-trailing_blank_count:][:20],
            "pattern": "trailing_blank_run_after_filled_rows",
            "note": "Verify that blank rows were not rotated to the end of the date block.",
        }
        sub_blocks = block.get("sub_blocks")
        if isinstance(sub_blocks, list) and sub_blocks:
            hint["sub_blocks"] = sub_blocks[:8]
        hints.append(hint)
    return hints


def _compact_llm_reparse_audit_feedback(audit_result: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(audit_result, dict) or not audit_result:
        return None
    compact = {
        "status": str(audit_result.get("status") or "").strip().lower() or None,
        "provider": str(audit_result.get("actual_provider") or audit_result.get("provider") or "").strip() or None,
        "model": str(audit_result.get("model") or "").strip() or None,
        "issue_count": int(audit_result.get("issue_count") or 0),
        "blocking_issue_count": int(audit_result.get("blocking_issue_count") or 0),
        "issues": [dict(item) for item in (audit_result.get("issues") or [])[:12] if isinstance(item, dict)],
        "blocking_issues": [
            dict(item) for item in (audit_result.get("blocking_issues") or [])[:8] if isinstance(item, dict)
        ],
    }
    error = str(audit_result.get("error") or "").strip()
    if error:
        compact["error"] = error
    threshold = audit_result.get("threshold")
    if isinstance(threshold, dict) and threshold:
        compact["threshold"] = dict(threshold)
    return compact


def _resolve_reparse_llm_baseline(
    *, order_id: str, template: dict[str, Any],
    fallback_payload: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    captured = _captured_reparse_read_input(order_id)
    if captured is None or not isinstance(fallback_payload, dict):
        return None
    return _resolve_llm_review_baseline(
        order_id=order_id, payload=fallback_payload, template=template,
        synchronous_write_input=captured,
    )




def _build_llm_assist_prompt(
    *,
    provider: str,
    template: dict,
    pipeline_output: dict | None,
    llm_assist: bool,
    prompt_preset: str | None = None,
    failure_context: dict[str, Any] | None = None,
    baseline: dict[str, Any] | None = None,
    evaluator_feedback: dict[str, Any] | None = None,
    draft_rows_override: list[list[str]] | None = None,
    draft_rows_label: str | None = None,
    first_pass_rows_override: list[list[str]] | None = None,
) -> str | None:
    prompt_key = "openai_ocr_prompt" if provider == "openai" else "gemini_ocr_prompt"
    base_custom = str(template.get(prompt_key) or "").strip()
    sections: list[str] = []
    if base_custom and not _looks_like_generated_reparse_prompt(base_custom):
        sections.append(f"Facility-specific instruction:\n{base_custom}")
    if llm_assist:
        preset_text = _build_llm_assist_preset_instruction(prompt_preset)
        if preset_text:
            sections.append(f"Operator-selected focus preset:\n{preset_text}")
        first_pass_rows = [list(row) for row in (first_pass_rows_override or []) if isinstance(row, list)]
        if not first_pass_rows and isinstance(pipeline_output, dict):
            first_pass_rows = _extract_first_pass_rows_from_payload(pipeline_output, template)
            if not first_pass_rows:
                first_pass_rows = _extract_sheet_rows_from_payload(pipeline_output, template)
        structural_fields = (
            [str(field).strip() for field in (baseline.get("structure_fields") or []) if str(field).strip()]
            if isinstance(baseline, dict)
            else []
        )
        if not structural_fields and isinstance(baseline, dict):
            structural_fields = [
                str(field).strip() for field in (baseline.get("fields") or []) if str(field).strip()
            ]
        structural_rows = (
            [list(row) for row in (baseline.get("structure_rows") or []) if isinstance(row, list)]
            if isinstance(baseline, dict)
            else []
        )
        if not structural_rows and isinstance(baseline, dict):
            structural_rows = [list(row) for row in (baseline.get("rows") or []) if isinstance(row, list)]
        block_anchor_hints = _build_reparse_block_anchor_hints(
            structural_fields=structural_fields,
            structural_rows=structural_rows,
            first_pass_fields=_row_fields_from_template(template) or structural_fields,
            first_pass_rows=first_pass_rows,
        )
        sections.append(
            "Second-pass repair mode:\n"
            "- Treat the first-pass yomitoku output as the baseline draft.\n"
            "- Treat the current sheet/baseline rows as the row structure shown to the user; existing quantities may be stale and must be re-verified against the fax.\n"
            "- Use the fax image to repair or confirm that draft, not to replace the whole table unnecessarily.\n"
            "- Determine each date/daypart block's quantity pattern first, then emit only the row-level patches needed against the current sheet.\n"
            "- The current sheet's canonical daypart blocks are 朝/昼/夕.\n"
            "- Fax-side 区分/category tokens may be aliases, sublabels, continuation marks, OCR noise, or blanks rather than literal 朝/昼/夕 values.\n"
            "- Treat fax-side 区分/category tokens such as 主, 副, 汁, タ, VE, MO, 品, A/B, single letters, and blank cells as auxiliary within-block hints unless the fax clearly shows a new canonical 朝/昼/夕 boundary.\n"
            "- The output quantity columns are only the target qty.* columns from the current sheet.\n"
            "- Fax-side numeric columns with no clear target header match (for example totals, subtotal/helper columns, '#'-style helper columns, symbols, or facility-only extra columns) must be ignored rather than shifted into the nearest target column.\n"
            "- Never shift a contiguous run of quantities left or right just to populate more target columns.\n"
            "- If the fax only supports some target quantity columns for a row, fill only those supported targets and leave the remaining target columns blank.\n"
            "- Keep row order stable.\n"
            "- row_index is the structural row position from the current sheet; blank rows still consume row indexes.\n"
            "- Return sparse row patches only.\n"
            "- Omit unchanged rows entirely.\n"
            "- In each returned row object, include row_index plus only the mutable fields that must change.\n"
            "- Omit unchanged fields inside a returned row object.\n"
            "- To explicitly blank a mutable cell, include that field with empty string.\n"
            "- Do not return structural anchor fields such as date/daypart/menu; the current sheet already owns them.\n"
            "- Display-only helper cells include operator-configured helper columns such as 合計 or 副区分; keep them in their own columns and never reinterpret them as qty.* targets.\n"
            "- Block-level helper columns such as 合計 belong to the whole date/daypart block, not to an arbitrary sibling row.\n"
            "- When a block-level helper value appears once within a date/daypart block, place it only on the first structural row of that block and leave the remaining rows blank.\n"
            "- If a block-level helper column shows conflicting values inside one date/daypart block, leave that helper column blank for the block instead of guessing.\n"
            "- remarks is mutable only when the fax shows text in the actual 備考/notes cell.\n"
            "- Do not create new remarks from side notes, allergy notes, prohibited-diet annotations, or margin text when the current sheet remarks cell is blank.\n"
            "- Fill missing cells when readable; keep empty string when unreadable.\n"
            "- It is valid for some rows to remain blank across all quantity columns.\n"
            "- Do not compress blank rows out of the output, even when the first visible quantity appears later in the block.\n"
            "- If evaluator feedback identifies one structural drift example, re-check every date/daypart block for the same pattern before returning JSON.\n"
            "- Do NOT fill a row unless a quantity is directly visible for that row or an explicit visual span clearly covers that row.\n"
            "- When the sheet contains more structural rows than first-pass OCR, preserve the structural rows and insert blank quantity rows where evidence is missing.\n"
            "- If a handwritten quantity is unreadable, infer only from nearby recognized quantities within the same date/daypart block when continuity is clear; otherwise keep empty string.\n"
            "- Continuity is never clear across a block boundary or across blank-anchor structural rows.\n"
            "- Keep blank-anchor structural rows at their exact row indexes; never rotate them to the end of a block.\n"
            "- Leading blank rows inside a date/daypart block may be intentional; keep them at the start of that block unless direct row-level evidence says otherwise.\n"
            "- Do not trade missing blank rows for extra repeated quantities later in the block.\n"
            "- If a parenthesis/bracket mark spans multiple quantity cells with one number, copy that number to every covered cell.\n"
            "- If arrows/vertical range lines indicate a number applies to a span, copy that number to all cells in that span.\n"
            "- Never extend a quantity into visually separate rows above or below the marked block.\n"
            "- Apply copying/inference only within the clearly indicated range.\n"
            "- Quantity cells must contain digits only.\n"
            "- Structured table cells and suspicious-cell diagnostics are provided below; use them when deciding what to repair.\n"
            "- Return strict JSON only."
        )
        if isinstance(failure_context, dict) and failure_context:
            try:
                failure_text = json.dumps(failure_context, ensure_ascii=False)
            except TypeError:
                failure_text = str(failure_context)
            sections.append(
                "Automatic fallback context:\n"
                "The first-pass yomitoku/pipeline OCR did not produce parseable order lines.\n"
                f"{_truncate_assist_text(failure_text, max_chars=4000)}"
            )
        baseline_rows = _build_llm_assist_baseline_rows(baseline)
        structural_prompt_rows = _build_llm_assist_structural_rows(baseline)
        baseline_date_ranges = _summarize_prompt_date_blocks(structural_prompt_rows or baseline_rows)
        if baseline_rows:
            baseline_source = (
                str(baseline.get("baseline_source") or "").strip()
                if isinstance(baseline, dict)
                else ""
            )
            baseline_revision_id = (
                str(baseline.get("baseline_revision_id") or "").strip()
                if isinstance(baseline, dict)
                else ""
            )
            baseline_sections = [
                "Current sheet/baseline rows shown to the user:\n"
                f"{_truncate_assist_text(json.dumps(baseline_rows[:80], ensure_ascii=False), max_chars=5000)}"
            ]
            if baseline_source:
                baseline_sections.append(f"Current baseline source: {baseline_source}")
            if baseline_revision_id:
                baseline_sections.append(f"Current baseline revision_id: {baseline_revision_id}")
            sections.append("\n".join(baseline_sections))
            current_sheet_markdown = _build_reparse_current_sheet_markdown_anchor(baseline)
            if current_sheet_markdown:
                sections.append(
                    "Current sheet markdown anchor (leading row_id column is anchor-only; do not include row_id in output JSON):\n"
                    f"{_truncate_assist_text(current_sheet_markdown, max_chars=7000)}"
                )
            baseline_block_ranges = _summarize_prompt_row_blocks(structural_prompt_rows or baseline_rows)
            if baseline_block_ranges:
                sections.append(
                    "Row block boundaries from structural sheet/baseline:\n"
                    f"{_truncate_assist_text(json.dumps(baseline_block_ranges[:80], ensure_ascii=False), max_chars=5000)}"
                )
                sections.append(
                    "Block boundary rules:\n"
                    "- Treat each consecutive date/daypart block above as a hard row boundary.\n"
                    "- Keep every quantity inside its own block.\n"
                    "- If a block has no direct visual quantity evidence, keep the whole block blank.\n"
                    "- Never start the next block's quantity before that block begins.\n"
                    "- Never let one handwritten number continue past the end row of its marked block."
                )
                sections.append(
                    "Daypart/category normalization rules:\n"
                    "- A change in fax-side 区分/category token alone is not enough to move a row into another canonical block.\n"
                    "- When fax-side 区分/category tokens are blank, noisy, or facility-specific, anchor rows by current-sheet order, neighboring menu names, and quantity continuity inside the same canonical block.\n"
                    "- Prefer the current-sheet 朝/昼/夕 block unless the fax explicitly shows a different canonical boundary.\n"
                    "- Do not move fax-side side notes or forbidden-diet annotations into the remarks column unless the current-sheet row already has that same note.\n"
                    "- For labeled side-note counts such as 肉4, 魚5, or 揚げ物6, map the number only to the semantically matching target column when that label is explicit and singular.\n"
                    "- If a side-note label is compound, facility-specific, or has no clear target qty.* column, do not force it into the nearest quantity column."
                )
        if baseline_date_ranges:
            sections.append(
                "Date block layout summary:\n"
                f"{_truncate_assist_text(json.dumps(baseline_date_ranges[:80], ensure_ascii=False), max_chars=5000)}"
            )
            sections.append(
                "Date block rules:\n"
                "- Inside each date block, preserve the exact order of its sub-blocks.\n"
                "- Blank sub-blocks may appear at the start, middle, or end of a date block.\n"
                "- Do NOT rotate a blank sub-block to the end of a date block just because later rows have quantities.\n"
                "- If the first visible quantity for a date block appears below the top rows, keep all earlier structural rows blank.\n"
                "- Never shift a lower handwritten quantity upward into earlier rows of the same date block.\n"
                "- If a sequence of blank-anchor rows exists before a visible handwritten quantity, keep that full sequence blank.\n"
                "- If one or more blank rows appear before the next visible handwritten number, those earlier rows must stay blank.\n"
                "- Never pull the next meal block's number upward just to remove blank rows.\n"
                "- A later meal block's quantity must never overwrite an earlier meal block's filled rows."
            )
        if structural_prompt_rows:
            structure_source = ""
            if isinstance(baseline, dict):
                structure_source = str(
                    baseline.get("structural_baseline_source")
                    or baseline.get("structure_source")
                    or ""
                ).strip()
            structure_sections = [
                "Structural sheet rows for blank-anchor preservation:\n"
                f"{_truncate_assist_text(json.dumps(structural_prompt_rows[:80], ensure_ascii=False), max_chars=5000)}"
            ]
            if structure_source:
                structure_sections.append(f"Structural baseline source: {structure_source}")
            sections.append("\n".join(structure_sections))
        block_ranges = block_anchor_hints.get("blocks")
        if isinstance(block_ranges, list) and block_ranges:
            sections.append(
                "Structural block anchor summary:\n"
                f"{_truncate_assist_text(json.dumps(block_ranges[:80], ensure_ascii=False), max_chars=5000)}"
            )
        if bool(block_anchor_hints.get("reference_alignment_weak")):
            sections.append(
                "Reference row alignment warning:\n"
                "- First-pass row keys are too noisy to use as row-index anchors.\n"
                "- Use only the structural date/daypart block boundaries from the current sheet.\n"
                "- Do not infer blank-anchor row indexes from the noisy first-pass rows."
            )
        unmatched_structural_row_indexes = block_anchor_hints.get("unmatched_structural_row_indexes")
        if not unmatched_structural_row_indexes:
            unmatched_structural_row_indexes = block_anchor_hints.get("structural_blank_anchor_row_indexes")
        if isinstance(unmatched_structural_row_indexes, list) and unmatched_structural_row_indexes:
            sections.append(
                "Blank-anchor structural row indexes:\n"
                f"{_truncate_assist_text(json.dumps(unmatched_structural_row_indexes[:120], ensure_ascii=False), max_chars=2000)}\n"
                "- These structural rows were not matched by first-pass OCR.\n"
                "- Keep them blank unless the fax shows direct row-level evidence.\n"
                "- Never backfill them from the next block."
            )
        if baseline_rows and first_pass_rows and len(baseline_rows) > len(first_pass_rows):
            sections.append(
                "Structural row preservation hint:\n"
                f"- Current sheet rows: {len(baseline_rows)}.\n"
                f"- First-pass yomitoku rows: {len(first_pass_rows)}.\n"
                "- Missing structural rows are not a license to copy neighboring quantities.\n"
                "- Keep quantity cells empty on unmatched structural rows unless the fax shows a direct mark or explicit span for them."
            )
        if baseline_rows:
            baseline_quantity_columns = [
                column
                for column in _template_quantity_columns(template)
                if isinstance(column, dict)
            ]
            candidate_blank_hint_rows = (
                [list(row) for row in (draft_rows_override or []) if isinstance(row, list)]
                or first_pass_rows
            )
            trailing_blank_hints = _collect_candidate_blank_edge_hints(
                candidate_rows=candidate_blank_hint_rows,
                quantity_columns=baseline_quantity_columns,
                date_blocks=baseline_date_ranges,
            )
            if trailing_blank_hints:
                sections.append(
                    "Suspicious blank-edge placement hints from the current OCR draft:\n"
                    f"{_truncate_assist_text(json.dumps(trailing_blank_hints[:40], ensure_ascii=False), max_chars=4000)}\n"
                    "- These are suspicious only; verify against the fax image before changing rows.\n"
                    "- If a blank run belongs earlier in the date block, move it back to the correct structural rows."
                )
        compact_feedback = _compact_llm_reparse_audit_feedback(evaluator_feedback)
        feedback_issue_codes: set[str] = set()
        if compact_feedback:
            feedback_issue_codes = {
                _normalize_audit_issue_code(item.get("issue_code"))
                for item in (compact_feedback.get("issues") or [])
                if isinstance(item, dict)
            }
            sections.append(
                "Evaluator feedback from previous OCR draft:\n"
                f"{_truncate_assist_text(json.dumps(compact_feedback, ensure_ascii=False), max_chars=6000)}"
            )
            feedback_row_indexes = sorted(
                {
                    int(item.get("row_index"))
                    for item in (compact_feedback.get("issues") or [])
                    if isinstance(item, dict)
                    and item.get("row_index") is not None
                    and str(item.get("row_index")).strip().lstrip("-").isdigit()
                    and int(item.get("row_index")) >= 0
                }
            )
            if feedback_row_indexes:
                sections.append(
                    "Evaluator row-index repair hints:\n"
                    f"{_truncate_assist_text(json.dumps(feedback_row_indexes[:120], ensure_ascii=False), max_chars=2000)}\n"
                    "- Re-check these rows first against the fax image.\n"
                    "- If evaluator feedback marks overextended_span or missing_blank_anchor_rows on a row, keep that row blank unless the fax shows direct row-level evidence.\n"
                    "- Do not fix an earlier flagged row by pulling the next block's quantity upward."
                )
        structure_sensitive_mode = bool(
            feedback_issue_codes
            & {
                "unexpected_dense_fill",
                "missing_blank_anchor_rows",
                "overextended_span",
                "date_anchor_drift",
                "invalid_numeric_spike",
            }
        ) or bool(isinstance(unmatched_structural_row_indexes, list) and unmatched_structural_row_indexes)
        if draft_rows_override:
            draft_label = str(draft_rows_label or "").strip() or "Previous OCR draft rows"
            try:
                draft_rows_text = json.dumps(draft_rows_override[:120], ensure_ascii=False)
            except TypeError:
                draft_rows_text = ""
            if draft_rows_text:
                sections.append(
                    f"{draft_label}:\n"
                    f"{_truncate_assist_text(draft_rows_text, max_chars=6000)}"
                )
        if isinstance(pipeline_output, dict):
            table_raw = pipeline_output.get("table_raw")
            if isinstance(table_raw, str) and table_raw.strip() and not structure_sensitive_mode:
                sections.append(
                    "First-pass yomitoku markdown:\n"
                    f"{_truncate_assist_text(table_raw.strip(), max_chars=7000)}"
                )
            if first_pass_rows:
                try:
                    rows_text = json.dumps(first_pass_rows[:80], ensure_ascii=False)
                except TypeError:
                    rows_text = ""
                if rows_text:
                    sections.append(
                        "First-pass yomitoku structured rows:\n"
                        f"{_truncate_assist_text(rows_text, max_chars=4000)}"
                    )
            quantity_subgrid_passes = _compact_prompt_quantity_subgrid_passes(pipeline_output)
            if quantity_subgrid_passes:
                sections.append(
                    "Quantity-only second pass on the numeric subgrid:\n"
                    "- This OCR pass sees only the quantity band on the right side of the table.\n"
                    "- It intentionally omits left-side notes, helper marks, and most row anchors.\n"
                    "- Use it to verify numeric patterns and repeated quantities.\n"
                    "- Prefer normalized_rows_preview when it is present; those rows keep the same quantity-grid shape but apply conservative digit-only normalization using neighboring rows.\n"
                    "- normalization_patches show where non-digit OCR text was converted into digits because surrounding numeric evidence matched.\n"
                    "- Do NOT derive date/daypart/menu anchors from this quantity-only pass.\n"
                    "- Keep row anchors from the structural current sheet and first-pass baseline.\n"
                    f"{_truncate_assist_text(json.dumps(quantity_subgrid_passes, ensure_ascii=False), max_chars=8000)}"
                )
            if structure_sensitive_mode:
                sections.append(
                    "Block-anchored repair mode:\n"
                    "- First-pass markdown/cell dumps are omitted here because structural drift was detected.\n"
                    "- Rely on structural sheet rows, block boundaries, quantity-only numeric-band OCR, and evaluator feedback before copying any quantity."
                )
            else:
                tables = _compact_prompt_tables(pipeline_output)
                if tables:
                    sections.append(
                        "First-pass yomitoku structured tables/cells:\n"
                        f"{_truncate_assist_text(json.dumps(tables, ensure_ascii=False), max_chars=10000)}"
                    )
                issues = _compact_prompt_cell_issues(pipeline_output, template)
                if issues:
                    sections.append(
                        "Suspicious first-pass cells (review before changing):\n"
                        f"{_truncate_assist_text(json.dumps(issues, ensure_ascii=False), max_chars=6000)}"
                    )
    if not sections:
        return None
    return "\n\n".join(sections)


def _build_llm_assist_preset_instruction(prompt_preset: str | None) -> str | None:
    normalized = str(prompt_preset or "").strip().lower()
    if not normalized or normalized == "freeform":
        return None
    preset_map = {
        "numeric_verification": (
            "- Primary goal: verify quantity digits before changing structure.\n"
            "- Compare neighboring quantity cells, repeated spans, and quantity-only OCR before editing a number.\n"
            "- Do not rewrite date/daypart/menu anchors unless the fax clearly contradicts them.\n"
            "- When uncertain, keep the structural row and leave the quantity blank instead of forcing a guess."
        ),
        "column_missing": (
            "- Primary goal: recover partially clipped or missing quantity columns.\n"
            "- Focus on whether leftmost/rightmost quantity columns are visible, truncated, or shifted.\n"
            "- Infer a missing quantity only when the fax shows direct evidence for that column or a clearly indicated repeated span.\n"
            "- Do not swap stable columns just to fill a gap."
        ),
        "row_alignment": (
            "- Primary goal: preserve row/block alignment across date and daypart boundaries.\n"
            "- Treat blank-anchor rows and block boundaries as hard constraints.\n"
            "- Prefer leaving quantities blank over shifting them into earlier or later rows.\n"
            "- Re-check every row in the same block if one row looks rotated or offset."
        ),
        "special_diet_semantics": (
            "- Primary goal: protect special diet semantics and prohibited-diet columns.\n"
            "- Pay extra attention to 肉禁, 魚禁, 糖尿, お茶, 袋分け, 常食(袋分け) and similar specialty columns.\n"
            "- Do not merge specialty quantities into regular columns.\n"
            "- If a specialty column is ambiguous, keep it unresolved instead of copying a regular quantity."
        ),
        "merged_cell_quantity_spans": (
            "- Primary goal: resolve quantity cells that visually span multiple menu rows or adjacent quantity cells.\n"
            "- Treat merged numeric cells, braces, repeated spans, and vertically centered handwritten numbers as span evidence.\n"
            "- First determine the exact covered rows inside the same date/daypart block, then copy the quantity to every row in that span.\n"
            "- Never carry a merged quantity across a date boundary, daypart boundary, blank-anchor row, or into a different diet column.\n"
            "- If the covered span is ambiguous, keep the affected quantity cells blank instead of shifting the number up or down."
        ),
    }
    return preset_map.get(normalized)


def _resolve_provider_model_name(
    *,
    provider: str,
    template: dict[str, Any],
) -> str:
    normalized_provider = str(provider or "").strip().lower()
    if normalized_provider == "gemini":
        return (
            str(template.get("gemini_ocr_model") or "").strip()
            or os.getenv("GEMINI_OCR_MODEL", "").strip()
            or "gemini-2.5-flash"
        )
    if normalized_provider == "openai":
        return (
            str(template.get("openai_ocr_model") or "").strip()
            or os.getenv("OPENAI_OCR_MODEL", "").strip()
            or "gpt-4.1-mini"
        )
    return ""


def _resolve_repair_focus_locations(
    *,
    current_rows: list[list[str]],
    expected_row_count: int,
    quality_detail: dict[str, Any] | None,
) -> tuple[list[int], list[int]]:
    normalized_rows = [list(row) for row in current_rows if isinstance(row, list)]
    focus_rows: set[int] = set()
    focus_columns: set[int] = set()

    if expected_row_count > 0 and len(normalized_rows) < expected_row_count:
        focus_rows.update(range(len(normalized_rows), expected_row_count))

    if not isinstance(quality_detail, dict):
        return sorted(focus_rows)[:80], sorted(focus_columns)[:40]

    for key in ("invalid_line_indexes", "source_row_mismatches", "source_row_missing"):
        values = quality_detail.get(key)
        if not isinstance(values, list):
            continue
        for value in values:
            try:
                idx = int(value)
            except Exception:
                continue
            if idx >= 0:
                focus_rows.add(idx)

    anomaly_rows = quality_detail.get("suspicious_row_indexes")
    if isinstance(anomaly_rows, list):
        for value in anomaly_rows:
            try:
                idx = int(value)
            except Exception:
                continue
            if idx >= 0:
                focus_rows.add(idx)

    column_anomalies = quality_detail.get("column_anomalies")
    if isinstance(column_anomalies, list):
        for item in column_anomalies:
            if not isinstance(item, dict):
                continue
            idx_raw = item.get("index")
            try:
                idx = int(idx_raw)
            except Exception:
                continue
            if idx >= 0:
                focus_columns.add(idx)

    return sorted(focus_rows)[:80], sorted(focus_columns)[:40]


def _build_flash_repair_summary(
    *,
    current_rows: list[list[str]],
    template: dict[str, Any],
    expected_row_count: int,
    quality_error: str,
    quality_detail: dict[str, Any] | None,
    first_pass_model: str | None,
    target_model: str | None,
) -> dict[str, Any]:
    normalized_rows = [list(row) for row in current_rows if isinstance(row, list)]
    row_count = len(normalized_rows)
    quantity_indexes = _template_quantity_column_indexes(template)
    non_empty_counts = _quantity_column_non_empty_counts(
        rows=normalized_rows,
        quantity_indexes=quantity_indexes,
    )
    rows_all_blank: list[int] = []
    if quantity_indexes:
        for row_idx, row in enumerate(normalized_rows):
            has_numeric_qty = False
            for col_idx in quantity_indexes:
                if col_idx < 0 or col_idx >= len(row):
                    continue
                if _parse_strict_numeric_cell(row[col_idx]) is not None:
                    has_numeric_qty = True
                    break
            if not has_numeric_qty:
                rows_all_blank.append(row_idx)

    focus_rows, focus_columns = _resolve_repair_focus_locations(
        current_rows=normalized_rows,
        expected_row_count=expected_row_count,
        quality_detail=quality_detail,
    )
    return {
        "quality_error": str(quality_error or ""),
        "first_pass_model": str(first_pass_model or "") or None,
        "target_model": str(target_model or "") or None,
        "expected_row_count": int(expected_row_count) if expected_row_count > 0 else None,
        "first_pass_row_count": int(row_count),
        "focus_row_indexes": focus_rows,
        "focus_quantity_column_indexes": focus_columns,
        "quantity_non_empty_by_column": {str(idx): int(non_empty_counts.get(idx, 0)) for idx in quantity_indexes},
        "rows_all_quantity_blank": rows_all_blank[:80],
        "quality_detail": quality_detail or {},
    }


def _should_use_gemini_pro_repair_pass(
    *,
    provider: str,
    template: dict[str, Any],
    quality_error: str,
) -> tuple[bool, str]:
    if provider != "gemini":
        return False, ""
    if quality_error not in {"sheet_row_coverage_low", "sheet_row_overfill", "sheet_column_anomaly"}:
        return False, ""
    enabled = str(
        os.getenv("OCR_REPARSE_ENABLE_GEMINI_PRO_ON_QUALITY_FAIL", "1")
    ).strip().lower() not in {"0", "false", "no", "off"}
    if not enabled:
        return False, ""

    first_pass_model = _resolve_provider_model_name(provider=provider, template=template)
    if "flash" not in first_pass_model.lower():
        return False, first_pass_model

    repair_model = (
        str(template.get("gemini_ocr_repair_model") or "").strip()
        or os.getenv("OCR_REPARSE_GEMINI_REPAIR_MODEL", "").strip()
        or "gemini-2.5-pro"
    )
    if repair_model.lower() == first_pass_model.lower():
        return False, repair_model
    return True, repair_model


def _build_quantity_only_repair_prompts(
    *,
    provider: str,
    template: dict[str, Any],
    current_rows: list[list[str]],
    expected_row_count: int,
    quality_error: str,
    quality_detail: dict[str, Any] | None,
    first_pass_model: str | None = None,
    target_model: str | None = None,
    baseline_rows: list[list[str]] | None = None,
    baseline_fields: list[str] | None = None,
    structural_rows: list[list[str]] | None = None,
    structural_fields: list[str] | None = None,
    evaluator_feedback: dict[str, Any] | None = None,
) -> tuple[str, str]:
    prompt_key = "openai_ocr_prompt" if provider == "openai" else "gemini_ocr_prompt"
    user_key = "openai_ocr_user_prompt" if provider == "openai" else "gemini_ocr_user_prompt"
    base_system_prompt = str(template.get(prompt_key) or "").strip()
    base_user_prompt = str(template.get(user_key) or "").strip()
    row_fields = [
        str(field)
        for field in (template.get("main_ocr_row_fields") or [])
        if isinstance(field, str) and str(field).strip()
    ]
    quantity_fields = [field for field in row_fields if field.startswith("qty.")]
    quantity_list = ", ".join(quantity_fields) if quantity_fields else "qty.*"

    missing_indexes: list[int] = []
    if expected_row_count > 0:
        current_count = len([row for row in current_rows if isinstance(row, list)])
        if current_count < expected_row_count:
            missing_indexes = list(range(current_count, expected_row_count))

    detail_text = ""
    if isinstance(quality_detail, dict) and quality_detail:
        try:
            detail_text = json.dumps(quality_detail, ensure_ascii=False)
        except Exception:
            detail_text = ""
    rows_hint = _truncate_assist_text(
        json.dumps(current_rows[:200], ensure_ascii=False),
        max_chars=12000,
    )
    normalized_baseline_rows = [list(row) for row in (baseline_rows or []) if isinstance(row, list)]
    normalized_structural_rows = [list(row) for row in (structural_rows or []) if isinstance(row, list)]
    resolved_structural_rows = normalized_structural_rows or normalized_baseline_rows
    resolved_structural_fields = list(structural_fields or baseline_fields or row_fields)
    block_anchor_hints = _build_reparse_block_anchor_hints(
        structural_fields=resolved_structural_fields,
        structural_rows=resolved_structural_rows,
        first_pass_fields=row_fields or baseline_fields or resolved_structural_fields,
        first_pass_rows=current_rows,
    )
    baseline_rows_hint = ""
    if normalized_baseline_rows:
        baseline_rows_hint = _truncate_assist_text(
            json.dumps(normalized_baseline_rows[:200], ensure_ascii=False),
            max_chars=12000,
        ) or ""
    baseline_block_ranges = _summarize_tabular_row_blocks(normalized_baseline_rows)
    baseline_block_ranges_hint = ""
    if baseline_block_ranges:
        baseline_block_ranges_hint = _truncate_assist_text(
            json.dumps(baseline_block_ranges[:120], ensure_ascii=False),
            max_chars=6000,
        ) or ""
    flash_summary = _build_flash_repair_summary(
        current_rows=current_rows,
        template=template,
        expected_row_count=expected_row_count,
        quality_error=quality_error,
        quality_detail=quality_detail,
        first_pass_model=first_pass_model,
        target_model=target_model,
    )
    summary_text = _truncate_assist_text(
        json.dumps(flash_summary, ensure_ascii=False),
        max_chars=6000,
    )
    focus_rows = flash_summary.get("focus_row_indexes") if isinstance(flash_summary, dict) else []
    focus_cols = flash_summary.get("focus_quantity_column_indexes") if isinstance(flash_summary, dict) else []
    focus_rows_hint = ", ".join(str(idx) for idx in (focus_rows or [])[:40]) if focus_rows else "none"
    focus_cols_hint = ", ".join(str(idx) for idx in (focus_cols or [])[:20]) if focus_cols else "none"
    missing_hint = (
        ", ".join(str(idx) for idx in missing_indexes[:40]) if missing_indexes else "none"
    )
    hard_rules = (
        "Second-pass OCR repair mode:\n"
        "- Use fax image as the primary source of truth.\n"
        "- Start from first-pass (Flash) output as a draft and correct only with visible evidence.\n"
        "- Treat the current sheet/baseline rows as the user-visible structural context.\n"
        "- Determine each date/daypart block's quantity pattern first, then emit only the row-level patches needed against the current sheet.\n"
        "- row_index is the structural row position from the current sheet; blank rows still consume row indexes.\n"
        "- Return sparse row patches only.\n"
        "- Omit unchanged rows entirely.\n"
        "- In each returned row object, include row_index plus only the mutable fields that must change.\n"
        "- Omit unchanged fields inside a returned row object.\n"
        "- To explicitly blank a mutable cell, include that field with empty string.\n"
        "- Do not return structural anchor fields such as date/daypart/menu; the current sheet already owns them.\n"
        "- Keep quantity columns independent and never swap values across columns.\n"
        "- Quantity fields must be digits only; unreadable cells must be empty string.\n"
        "- It is valid for some rows to remain blank across all quantity columns.\n"
        "- Do not compress blank rows out of the output, even when the first visible quantity appears later in the block.\n"
        "- If evaluator feedback identifies one structural drift example, re-check every date/daypart block for the same pattern before returning JSON.\n"
        "- Do NOT fill a row unless a quantity is directly visible for that row or an explicit visual span clearly covers that row.\n"
        "- Existing quantities in the current sheet may be stale; use them only as structural context unless the fax confirms them.\n"
        "- If the current sheet/baseline leaves a row blank, keep it blank unless the fax shows direct row-level evidence for that row.\n"
        "- If structural rows are missing from first-pass OCR, insert blank rows where evidence is missing instead of copying neighboring quantities.\n"
        "- Infer unreadable quantities only within the same date/daypart block.\n"
        "- Continuity is never clear across a block boundary or across unmatched structural row indexes.\n"
        "- Keep blank-anchor structural rows at their exact row indexes; never rotate them to the end of a block.\n"
        "- Copy numbers across cells only when explicit span marks exist.\n"
        "- Treat each consecutive date/daypart block from the current sheet as a hard boundary.\n"
        "- If a block has no direct visual quantity evidence, leave the whole block blank.\n"
        "- Treat unmatched structural row indexes as blank anchors unless the fax shows direct row-level evidence.\n"
        "- Never extend one handwritten number into visually separate rows above or below the marked block.\n"
        "- If a visible number starts below blank rows, keep those blank rows empty instead of pulling that number upward.\n"
        "- If consecutive meal blocks each have their own handwritten number, stop the earlier number before the next block begins.\n"
        "- Return strict JSON only."
    )
    if expected_row_count > 0:
        hard_rules += (
            f"\n- Output EXACTLY {expected_row_count} table body rows."
            f"\n- row_index must be continuous 0..{max(expected_row_count - 1, 0)} with no gaps."
            f"\n- Missing row indexes from first pass: {missing_hint}."
            "\n- Missing row indexes are rows to re-check carefully; if the fax does not show a number for them, leave their quantity cells empty."
            "\n- Do not invent extra rows or duplicate row indexes to make the output denser."
        )
    if quantity_fields:
        hard_rules += (
            "\n- Quantity keys (left-to-right mapping) must stay exactly this order:\n"
            f"{quantity_list}"
        )
    hard_rules += (
        f"\n- Recheck focus row indexes first: {focus_rows_hint}."
        f"\n- Recheck focus quantity column indexes first: {focus_cols_hint}."
    )

    system_sections: list[str] = []
    if base_system_prompt:
        system_sections.append(base_system_prompt)
    system_sections.append(hard_rules)

    user_sections: list[str] = []
    if base_user_prompt:
        user_sections.append(base_user_prompt)
    user_sections.append(
        "First-pass OCR candidate rows (for repair hint only):\n"
        f"{rows_hint}"
    )
    if baseline_rows_hint:
        user_sections.append(
            "Current sheet/baseline rows shown to the user:\n"
            f"{baseline_rows_hint}"
        )
    if baseline_block_ranges_hint:
        user_sections.append(
            "Current sheet block boundaries:\n"
            f"{baseline_block_ranges_hint}"
        )
    unmatched_structural_row_indexes = block_anchor_hints.get("unmatched_structural_row_indexes")
    if not unmatched_structural_row_indexes:
        unmatched_structural_row_indexes = block_anchor_hints.get("structural_blank_anchor_row_indexes")
    if isinstance(unmatched_structural_row_indexes, list) and unmatched_structural_row_indexes:
        user_sections.append(
            "Blank-anchor structural row indexes:\n"
            f"{_truncate_assist_text(json.dumps(unmatched_structural_row_indexes[:120], ensure_ascii=False), max_chars=2000)}"
        )
    if summary_text:
        user_sections.append(
            "Failure focus locations and first-pass inference summary:\n"
            f"{summary_text}"
        )
    compact_feedback = _compact_llm_reparse_audit_feedback(evaluator_feedback)
    if compact_feedback:
        user_sections.append(
            "Evaluator feedback from previous OCR draft:\n"
            f"{_truncate_assist_text(json.dumps(compact_feedback, ensure_ascii=False), max_chars=6000)}"
        )
    if detail_text:
        user_sections.append(
            "First-pass quality issue detail:\n"
            f'{{"error":"{quality_error}","detail":{detail_text}}}'
        )
    user_sections.append(
        "Repair the extraction and return JSON only. Do not output explanations."
    )

    return "\n\n".join(system_sections), "\n\n".join(user_sections)


def _parse_audit_int(value: object) -> int | None:
    if value is None:
        return None
    text = str(value).strip()
    if not text:
        return None
    if not re.fullmatch(r"-?\d+", text):
        return None
    try:
        return int(text)
    except Exception:
        return None


def _parse_audit_confidence(value: object) -> float:
    if value is None:
        return 0.0
    text = str(value).strip()
    if not text:
        return 0.0
    try:
        parsed = float(text)
    except Exception:
        return 0.0
    if parsed < 0.0:
        return 0.0
    if parsed > 1.0:
        return 1.0
    return parsed


def _normalize_audit_issue_code(value: object) -> str:
    normalized = str(value or "").strip().lower()
    normalized = normalized.replace("-", "_").replace(" ", "_")
    normalized = re.sub(r"[^a-z0-9_]+", "", normalized)
    return normalized


def _parse_llm_reparse_audit_issues(
    *,
    rows: list[list[str]],
    fields: list[str],
) -> list[dict[str, Any]]:
    if not rows or not fields:
        return []
    field_index = {field: idx for idx, field in enumerate(fields)}
    allowed_issue_codes = {
        "row_count_shortfall",
        "week_scope_mismatch",
        "date_anchor_drift",
        "mirrored_sibling_columns",
        "column_swap",
        "invalid_numeric_spike",
        "all_quantity_blank",
        "unexpected_dense_fill",
        "overextended_span",
        "missing_blank_anchor_rows",
    }
    issues: list[dict[str, Any]] = []
    for row in rows:
        if not isinstance(row, list):
            continue
        issue_code = _normalize_audit_issue_code(
            row[field_index["issue_code"]]
            if "issue_code" in field_index and field_index["issue_code"] < len(row)
            else ""
        )
        severity = str(
            row[field_index["severity"]]
            if "severity" in field_index and field_index["severity"] < len(row)
            else ""
        ).strip().lower()
        evidence = str(
            row[field_index["evidence"]]
            if "evidence" in field_index and field_index["evidence"] < len(row)
            else ""
        ).strip()
        reason = str(
            row[field_index["reason"]]
            if "reason" in field_index and field_index["reason"] < len(row)
            else ""
        ).strip()
        row_index = _parse_audit_int(
            row[field_index["row_index"]]
            if "row_index" in field_index and field_index["row_index"] < len(row)
            else None
        )
        column_index = _parse_audit_int(
            row[field_index["column_index"]]
            if "column_index" in field_index and field_index["column_index"] < len(row)
            else None
        )
        confidence = _parse_audit_confidence(
            row[field_index["confidence"]]
            if "confidence" in field_index and field_index["confidence"] < len(row)
            else None
        )
        if issue_code and issue_code not in allowed_issue_codes and not reason and not evidence:
            continue
        if not issue_code and not reason:
            continue
        issue: dict[str, Any] = {
            "issue_code": issue_code or "unknown_issue",
            "severity": severity or "medium",
            "confidence": round(confidence, 4),
            "evidence": evidence,
            "reason": reason,
        }
        if row_index is not None:
            issue["row_index"] = int(row_index)
        if column_index is not None:
            issue["column_index"] = int(column_index)
        issues.append(issue)
    return issues


def _resolve_llm_audit_provider(
    *,
    primary_provider: str,
    template: dict[str, Any],
) -> str:
    normalized_primary = str(primary_provider or "").strip().lower()
    if normalized_primary not in {"gemini", "openai"}:
        normalized_primary = "gemini"

    def _alternate(provider: str) -> str:
        return "openai" if provider == "gemini" else "gemini"

    configured = (
        str(template.get("llm_audit_provider") or "").strip().lower()
        or str(os.getenv("OCR_REPARSE_AUDIT_PROVIDER", "alternate")).strip().lower()
    )
    if configured in {"", "same", "alternate", "other", "cross", "opposite"}:
        return _alternate(normalized_primary)
    if configured in {"gemini", "openai"}:
        if configured == normalized_primary:
            # Enforce cross-model verification to avoid self-approval.
            return _alternate(normalized_primary)
        return configured
    return _alternate(normalized_primary)


def _has_openai_api_key() -> bool:
    return bool(str(os.getenv("OPENAI_API_KEY", "")).strip())


def _has_gemini_api_key() -> bool:
    return bool(
        str(os.getenv("GEMINI_API_KEY", "")).strip()
        or str(os.getenv("GOOGLE_API_KEY", "")).strip()
    )


def _resolve_gemini_audit_model(
    *,
    primary_provider: str,
    primary_model: str,
    template: dict[str, Any],
) -> str:
    configured = str(
        template.get("gemini_ocr_audit_model")
        or os.getenv("OCR_REPARSE_GEMINI_AUDIT_MODEL", "")
    ).strip()
    if configured:
        candidate = configured
    else:
        primary_model_lower = str(primary_model or "").strip().lower()
        if primary_provider == "gemini" and "flash" in primary_model_lower:
            candidate = "gemini-2.5-pro"
        elif primary_provider == "gemini" and "pro" in primary_model_lower:
            candidate = "gemini-2.5-flash"
        else:
            candidate = (
                str(os.getenv("GEMINI_OCR_MODEL", "")).strip()
                or "gemini-2.5-flash"
            )
    if (
        primary_provider == "gemini"
        and candidate.strip().lower() == str(primary_model or "").strip().lower()
    ):
        if "flash" in candidate.lower():
            return "gemini-2.5-pro"
        if "pro" in candidate.lower():
            return "gemini-2.5-flash"
    return candidate


def _build_llm_reparse_audit_prompts(
    *,
    candidate_rows: list[list[str]],
    reference_rows: list[list[str]] | None,
    quantity_columns: list[dict[str, str | int]],
    expected_row_count: int,
    baseline_rows: list[list[str]] | None = None,
    block_anchor_hints: dict[str, Any] | None = None,
) -> tuple[str, str, list[str]]:
    fields = [
        "issue_code",
        "severity",
        "row_index",
        "column_index",
        "confidence",
        "evidence",
        "reason",
    ]
    current_sheet_date_ranges = (
        _summarize_tabular_date_blocks(baseline_rows)
        if isinstance(baseline_rows, list)
        else []
    )
    candidate_blank_edge_hints = _collect_candidate_blank_edge_hints(
        candidate_rows=candidate_rows,
        quantity_columns=quantity_columns,
        date_blocks=current_sheet_date_ranges,
    )
    system_prompt = (
        "You are an OCR quality auditor for Japanese fax order sheets.\n"
        "Your task is defect finding only. Do NOT correct OCR rows.\n"
        "Use the fax image as primary evidence and candidate OCR rows as a draft.\n"
        "Return strict JSON only with shape:\n"
        '{"facility_name":"", "date_strings":[], "rows":[{"issue_code":"","severity":"","row_index":"","column_index":"","confidence":"","evidence":"","reason":""}]}\n'
        "If no clear defect is found, return rows as [].\n"
        "Rules:\n"
        "- issue_code should be one of: row_count_shortfall, week_scope_mismatch, date_anchor_drift, mirrored_sibling_columns, column_swap, invalid_numeric_spike, all_quantity_blank, unexpected_dense_fill, overextended_span, missing_blank_anchor_rows.\n"
        "- severity should be one of: critical, high, medium, low.\n"
        "- confidence must be 0.00-1.00.\n"
        "- evidence must quote concrete visual evidence from the image (short text).\n"
        "- row_index/column_index should be digits when identifiable, otherwise empty string.\n"
        "- Treat current_sheet_block_ranges as hard structural boundaries between date/daypart blocks.\n"
        "- Treat current_sheet_date_ranges as ordered parent blocks that contain those date/daypart sub-blocks.\n"
        "- Treat blank_anchor_row_indexes_hint as rows that should stay blank unless direct row-level evidence exists.\n"
        "- Flag unexpected_dense_fill when quantities are copied into rows without direct visual evidence.\n"
        "- Flag missing_blank_anchor_rows when rows that should remain blank are filled.\n"
        "- Flag missing_blank_anchor_rows when blank-anchor rows are rotated to the tail of a block instead of staying at their hinted row indexes.\n"
        "- Flag overextended_span when one handwritten number is copied beyond the visually covered block or across a current_sheet_block_ranges boundary.\n"
        "- When checking overextended_span, reject upward propagation from lower rows into earlier blank-anchor rows.\n"
        "- Flag overextended_span when a lower handwritten quantity is shifted upward into earlier rows of the same date block.\n"
        "- Never output markdown or explanations."
    )
    blank_anchor_row_indexes_hint = []
    if isinstance(block_anchor_hints, dict):
        raw_blank_anchor_hint = block_anchor_hints.get("unmatched_structural_row_indexes") or []
        if isinstance(raw_blank_anchor_hint, list):
            blank_anchor_row_indexes_hint = raw_blank_anchor_hint[:160]
        if not blank_anchor_row_indexes_hint:
            fallback_blank_anchor_hint = block_anchor_hints.get("structural_blank_anchor_row_indexes") or []
            if isinstance(fallback_blank_anchor_hint, list):
                blank_anchor_row_indexes_hint = fallback_blank_anchor_hint[:160]
    user_payload = {
        "expected_row_count": int(expected_row_count) if expected_row_count > 0 else None,
        "candidate_rows": candidate_rows[:260],
        "reference_rows_hint": (reference_rows or [])[:120],
        "current_sheet_rows_hint": (baseline_rows or [])[:120],
        "current_sheet_date_ranges": current_sheet_date_ranges[:80],
        "current_sheet_block_ranges": (
            (block_anchor_hints or {}).get("blocks")
                if isinstance(block_anchor_hints, dict)
                else _summarize_tabular_row_blocks(baseline_rows)
            ),
        "blank_anchor_row_indexes_hint": blank_anchor_row_indexes_hint,
        "candidate_blank_edge_hints": candidate_blank_edge_hints[:40],
        "quantity_columns": quantity_columns,
    }
    user_prompt = (
        "Audit the OCR candidate rows and list only defects with evidence.\n"
        f"{_truncate_assist_text(json.dumps(user_payload, ensure_ascii=False), max_chars=18000)}"
    )
    return system_prompt, user_prompt, fields


def _run_llm_reparse_audit(
    *,
    pdf_bytes: bytes,
    provider: str,
    template: dict[str, Any],
    facility_id: str | None,
    preferred_template_id: str | None,
    candidate_rows: list[list[str]],
    reference_rows: list[list[str]] | None,
    expected_row_count: int,
    baseline_rows: list[list[str]] | None = None,
) -> dict[str, Any] | None:
    if provider not in {"gemini", "openai"}:
        return None
    if not _read_reparse_bool_env("OCR_REPARSE_ENABLE_LLM_AUDIT_GATE", True):
        return None

    primary_provider = str(provider or "").strip().lower()
    primary_model = _resolve_provider_model_name(
        provider=primary_provider,
        template=template,
    )
    quantity_columns = _template_quantity_columns(template)
    template_fields = _row_fields_from_template(template)
    block_anchor_hints = _build_reparse_block_anchor_hints(
        structural_fields=template_fields,
        structural_rows=[list(row) for row in (baseline_rows or []) if isinstance(row, list)],
        first_pass_fields=template_fields,
        first_pass_rows=candidate_rows,
    )
    requested_audit_provider = _resolve_llm_audit_provider(
        primary_provider=provider,
        template=template,
    )
    audit_provider = str(requested_audit_provider or "").strip().lower() or "gemini"
    fail_closed = _read_reparse_bool_env("OCR_REPARSE_LLM_AUDIT_FAIL_CLOSED", False)
    provider_switch_reason: str | None = None
    if audit_provider == "openai" and not _has_openai_api_key():
        if _has_gemini_api_key():
            audit_provider = "gemini"
            provider_switch_reason = "openai_api_key_missing_fallback_gemini"
        else:
            return {
                "status": "fail" if fail_closed else "unknown",
                "provider": requested_audit_provider,
                "requested_provider": requested_audit_provider,
                "actual_provider": None,
                "provider_switch_reason": "openai_api_key_missing",
                "model": None,
                "issue_count": 0,
                "blocking_issue_count": 0,
                "issues": [],
                "blocking_issues": [],
                "error": "openai_api_key_missing",
            }
    elif audit_provider == "gemini" and not _has_gemini_api_key():
        if _has_openai_api_key():
            audit_provider = "openai"
            provider_switch_reason = "gemini_api_key_missing_fallback_openai"
        else:
            return {
                "status": "fail" if fail_closed else "unknown",
                "provider": requested_audit_provider,
                "requested_provider": requested_audit_provider,
                "actual_provider": None,
                "provider_switch_reason": "gemini_api_key_missing",
                "model": None,
                "issue_count": 0,
                "blocking_issue_count": 0,
                "issues": [],
                "blocking_issues": [],
                "error": "gemini_api_key_missing",
            }

    system_prompt, user_prompt, row_fields = _build_llm_reparse_audit_prompts(
        candidate_rows=candidate_rows,
        reference_rows=reference_rows,
        baseline_rows=baseline_rows,
        quantity_columns=quantity_columns,
        expected_row_count=expected_row_count,
        block_anchor_hints=block_anchor_hints,
    )

    audit_template = dict(template)
    audit_template["main_ocr_provider"] = audit_provider
    audit_template["_force_main_ocr_provider"] = audit_provider
    audit_template["llm_quantity_only_mode"] = False
    audit_template["main_ocr_row_fields"] = row_fields
    if audit_provider == "openai":
        audit_template["openai_ocr_enabled"] = True
        audit_template["openai_ocr_prompt"] = system_prompt
        audit_template["openai_ocr_user_prompt"] = user_prompt
        model_override = str(
            audit_template.get("openai_ocr_audit_model")
            or os.getenv("OCR_REPARSE_OPENAI_AUDIT_MODEL", "")
        ).strip()
        if model_override:
            audit_template["openai_ocr_model"] = model_override
    else:
        audit_template["gemini_ocr_enabled"] = True
        audit_template["gemini_ocr_prompt"] = system_prompt
        audit_template["gemini_ocr_user_prompt"] = user_prompt
        model_override = _resolve_gemini_audit_model(
            primary_provider=primary_provider,
            primary_model=primary_model,
            template=audit_template,
        )
        if model_override:
            audit_template["gemini_ocr_model"] = model_override

    min_confidence = _read_reparse_float_env(
        "OCR_REPARSE_LLM_AUDIT_MIN_CONFIDENCE",
        0.75,
        min_value=0.0,
    )
    if min_confidence > 1.0:
        min_confidence = 1.0
    blocking_codes = {
        _normalize_audit_issue_code(token)
        for token in str(
            os.getenv(
                "OCR_REPARSE_LLM_AUDIT_BLOCKING_CODES",
                (
                    "row_count_shortfall,week_scope_mismatch,date_anchor_drift,"
                    "mirrored_sibling_columns,column_swap,invalid_numeric_spike,all_quantity_blank,"
                    "unexpected_dense_fill,overextended_span,missing_blank_anchor_rows"
                ),
            )
        ).split(",")
        if str(token).strip()
    }
    template_blocking_codes = template.get("llm_audit_blocking_codes")
    if isinstance(template_blocking_codes, (list, tuple, set)):
        blocking_codes |= {
            _normalize_audit_issue_code(token)
            for token in template_blocking_codes
            if str(token).strip()
        }
    ignored_blocking_codes: set[str] = set()
    template_non_blocking_codes = template.get("llm_audit_non_blocking_codes")
    if isinstance(template_non_blocking_codes, (list, tuple, set)):
        ignored_blocking_codes = {
            _normalize_audit_issue_code(token)
            for token in template_non_blocking_codes
            if str(token).strip()
        }
        blocking_codes -= ignored_blocking_codes
    blocking_severity = {
        str(token).strip().lower()
        for token in str(
            os.getenv("OCR_REPARSE_LLM_AUDIT_BLOCKING_SEVERITY", "critical,high")
        ).split(",")
        if str(token).strip()
    }

    try:
        extracted = extract_fax_data(
            pdf_bytes,
            audit_template,
            facility_id=facility_id,
            preferred_template_id=preferred_template_id,
        )
        provider_debug = (
            extracted.provider_debug
            if isinstance(extracted.provider_debug, dict)
            else {}
        )
        actual_provider = str(
            extracted.ocr_provider
            or provider_debug.get("provider")
            or audit_provider
        ).strip().lower()
        if actual_provider.endswith("_fallback_pipeline"):
            return {
                "status": "fail" if fail_closed else "unknown",
                "provider": audit_provider,
                "requested_provider": requested_audit_provider,
                "actual_provider": actual_provider,
                "provider_switch_reason": provider_switch_reason,
                "model": str(provider_debug.get("model") or "").strip() or None,
                "issue_count": 0,
                "blocking_issue_count": 0,
                "issues": [],
                "blocking_issues": [],
                "error": "audit_provider_fallback_pipeline",
            }

        parsed_rows = [list(row) for row in (extracted.table_rows or []) if isinstance(row, list)]
        issues = _parse_llm_reparse_audit_issues(
            rows=parsed_rows,
            fields=row_fields,
        )
        blocking_issues: list[dict[str, Any]] = []
        for issue in issues:
            evidence = str(issue.get("evidence") or "").strip()
            if not evidence:
                continue
            confidence = float(issue.get("confidence") or 0.0)
            if confidence < min_confidence:
                continue
            issue_code = _normalize_audit_issue_code(issue.get("issue_code"))
            severity = str(issue.get("severity") or "").strip().lower()
            if issue_code in ignored_blocking_codes:
                continue
            if issue_code in blocking_codes or severity in blocking_severity:
                blocking_issues.append(issue)
        status = "pass"
        if blocking_issues:
            status = "fail"
        elif issues:
            status = "unknown"
        return {
            "status": status,
            "provider": audit_provider,
            "requested_provider": requested_audit_provider,
            "actual_provider": actual_provider,
            "provider_switch_reason": provider_switch_reason,
            "model": str(provider_debug.get("model") or "").strip() or None,
            "issue_count": len(issues),
            "blocking_issue_count": len(blocking_issues),
            "issues": issues[:40],
            "blocking_issues": blocking_issues[:20],
            "threshold": {
                "min_confidence": min_confidence,
                "blocking_codes": sorted(token for token in blocking_codes if token),
                "blocking_severity": sorted(token for token in blocking_severity if token),
            },
        }
    except OCRPipelineOutputPendingError:
        raise
    except Exception as exc:  # noqa: BLE001
        return {
            "status": "fail" if fail_closed else "unknown",
            "provider": audit_provider,
            "requested_provider": requested_audit_provider,
            "actual_provider": None,
            "provider_switch_reason": provider_switch_reason,
            "model": None,
            "issue_count": 0,
            "blocking_issue_count": 0,
            "issues": [],
            "blocking_issues": [],
            "error": str(exc),
            "threshold": {
                "min_confidence": min_confidence,
                "blocking_codes": sorted(token for token in blocking_codes if token),
                "blocking_severity": sorted(token for token in blocking_severity if token),
            },
        }


def _evaluate_reparse_line_count_regression(
    *,
    provider: str,
    llm_quantity_only_active: bool,
    before_count: int,
    after_count: int,
) -> tuple[str | None, dict[str, Any] | None]:
    if provider not in {"gemini", "openai"}:
        return None, None
    if not llm_quantity_only_active:
        return None, None
    if before_count <= 0:
        return None, None

    min_before = _read_reparse_int_env(
        "OCR_REPARSE_LINE_COUNT_GUARD_MIN_BEFORE",
        24,
        min_value=1,
    )
    if before_count < min_before:
        return None, None

    min_ratio = _read_reparse_float_env(
        "OCR_REPARSE_LINE_COUNT_MIN_RATIO",
        0.70,
        min_value=0.0,
    )
    if min_ratio > 1.0:
        min_ratio = 1.0
    max_drop_abs = _read_reparse_int_env(
        "OCR_REPARSE_LINE_COUNT_MAX_DROP_ABS",
        24,
        min_value=1,
    )
    ratio = float(after_count) / float(before_count) if before_count > 0 else 1.0
    drop_abs = max(before_count - after_count, 0)
    detail = {
        "before_count": int(before_count),
        "after_count": int(after_count),
        "line_count_ratio": round(ratio, 4),
        "drop_abs": int(drop_abs),
        "min_ratio": float(min_ratio),
        "max_drop_abs": int(max_drop_abs),
        "min_before_count": int(min_before),
    }
    if ratio < min_ratio and drop_abs > max_drop_abs:
        detail["quality_issue"] = "line_count_regression"
        return "sheet_line_count_regression", detail
    return None, detail


def _build_reparse_quantity_rules(
    base_rules: dict[str, Any] | None,
    *,
    strict_llm_quantity: bool,
) -> dict[str, Any]:
    rules = dict(base_rules or {})
    if not strict_llm_quantity:
        return rules
    rules["zero_as_empty"] = False
    rules["strict_numeric_quantity_cell"] = True
    # LLM quantity-only mode can intentionally omit non-quantity columns.
    # Keep these rows for quality/blocker evaluation only; legacy
    # source_row_index-based date/daypart/menu restoration is disabled.
    rules["allow_blank_structure_rows"] = True
    # LLM quantity-only rows already represent table-body row indexes.
    # Do not skip template header rows again when parsing them.
    rules["rows_are_body_only"] = True
    if rules.get("max_quantity_abs") is None:
        rules["max_quantity_abs"] = _read_sheet_quantity_max_abs()
    return rules


def _resolve_reparse_prompt_text(
    *,
    provider: str | None,
    template: dict[str, Any],
    user_prompt: str | None,
) -> str | None:
    normalized_provider = str(provider or "").strip().lower()
    system_prompt = ""
    provider_user_prompt = ""
    if normalized_provider == "openai":
        system_prompt = str(template.get("openai_ocr_prompt") or "").strip()
        provider_user_prompt = str(template.get("openai_ocr_user_prompt") or "").strip()
    elif normalized_provider == "gemini":
        system_prompt = str(template.get("gemini_ocr_prompt") or "").strip()
        provider_user_prompt = str(template.get("gemini_ocr_user_prompt") or "").strip()
    explicit_user_prompt = user_prompt.strip() if isinstance(user_prompt, str) else ""
    resolved_user_prompt = provider_user_prompt or explicit_user_prompt
    parts: list[str] = []
    if system_prompt:
        parts.append(f"[system]\n{system_prompt}")
    if resolved_user_prompt:
        parts.append(f"[user]\n{resolved_user_prompt}")
    if not parts:
        return None
    return "\n\n".join(parts)


def _debug_text_max_chars() -> int:
    raw = str(os.getenv("OCR_REPARSE_DEBUG_MAX_CHARS", "20000")).strip()
    try:
        value = int(raw)
    except ValueError:
        return 20000
    return min(max(value, 2000), 120000)


def _truncate_debug_text(value: object, *, max_chars: int) -> str | None:
    if not isinstance(value, str):
        return None
    text = value.strip()
    if not text:
        return None
    if len(text) <= max_chars:
        return text
    trimmed = text[:max_chars].rstrip()
    omitted = len(text) - len(trimmed)
    return f"{trimmed}\n...[truncated {omitted} chars]"


def _compact_debug_rows(rows: object, *, max_rows: int = 8, max_cells: int = 16) -> list[list[str]]:
    if not isinstance(rows, list):
        return []
    compact: list[list[str]] = []
    for row in rows[:max_rows]:
        if isinstance(row, list):
            compact.append([str(cell or "") for cell in row[:max_cells]])
        elif isinstance(row, dict):
            values: list[str] = []
            for key, value in list(row.items())[:max_cells]:
                values.append(f"{key}={value}")
            compact.append(values)
    return compact


def _compact_debug_lines(lines: object, *, max_lines: int = 20) -> list[dict[str, Any]]:
    if not isinstance(lines, list):
        return []
    compact: list[dict[str, Any]] = []
    for line in lines[:max_lines]:
        if not isinstance(line, dict):
            continue
        compact.append(_compact_line_debug_item(line))
    return compact


def _resolve_llm_audit_cluster_fill_decision(llm_audit: dict[str, Any] | None) -> str | None:
    if not isinstance(llm_audit, dict) or not llm_audit:
        return None
    for candidate in (
        llm_audit.get("sheet_cluster_fill_decision"),
        llm_audit.get("order_line_cluster_fill_decision"),
        llm_audit.get("sheet_fill_decision"),
    ):
        parsed = _parse_sheet_fill_decision(candidate)
        if parsed is None:
            continue
        return "allow" if parsed else "deny"
    audit_status = str(llm_audit.get("status") or "").strip().lower()
    if audit_status == "fail":
        return "deny"
    return None


def _llm_reparse_audit_requires_second_pass(llm_audit: dict[str, Any] | None) -> bool:
    if not isinstance(llm_audit, dict) or not llm_audit:
        return False
    status = str(llm_audit.get("status") or "").strip().lower()
    if status == "fail":
        return True
    try:
        if int(llm_audit.get("blocking_issue_count") or 0) > 0:
            return True
    except Exception:
        pass
    try:
        if int(llm_audit.get("issue_count") or 0) > 0:
            return True
    except Exception:
        pass
    return False


def _llm_reparse_audit_issue_codes(llm_audit: dict[str, Any] | None) -> set[str]:
    if not isinstance(llm_audit, dict) or not llm_audit:
        return set()
    issue_codes: set[str] = set()
    for item in (llm_audit.get("issues") or []):
        if not isinstance(item, dict):
            continue
        code = _normalize_audit_issue_code(item.get("issue_code"))
        if code:
            issue_codes.add(code)
    return issue_codes


def _llm_reparse_audit_requires_structural_repair_prompt(
    llm_audit: dict[str, Any] | None,
) -> bool:
    issue_codes = _llm_reparse_audit_issue_codes(llm_audit)
    if not issue_codes:
        return False
    return bool(
        issue_codes
        & {
            "unexpected_dense_fill",
            "missing_blank_anchor_rows",
            "overextended_span",
            "date_anchor_drift",
        }
    )


def _augment_llm_reparse_audit_with_structural_feedback(
    *,
    llm_audit: dict[str, Any] | None,
    candidate_rows: list[list[str]] | None,
    template: dict[str, Any],
    baseline_fields: list[str] | None,
    baseline_structure_rows: list[list[str]] | None,
    reference_rows: list[list[str]] | None,
    reference_fields: list[str] | None,
) -> dict[str, Any] | None:
    if not isinstance(llm_audit, dict) or not llm_audit:
        return llm_audit
    if str(llm_audit.get("provider_switch_reason") or "").strip():
        return llm_audit
    normalized_rows = [list(row) for row in (candidate_rows or []) if isinstance(row, list)]
    if not normalized_rows:
        return llm_audit
    structural_rows = [list(row) for row in (baseline_structure_rows or []) if isinstance(row, list)]
    if not structural_rows:
        return llm_audit
    structural_fields = [str(field).strip() for field in (baseline_fields or []) if str(field).strip()]
    if not structural_fields:
        return llm_audit
    reference_row_values = [list(row) for row in (reference_rows or []) if isinstance(row, list)]
    normalized_reference_fields = [str(field).strip() for field in (reference_fields or []) if str(field).strip()]
    quantity_columns = [col for col in _template_quantity_columns(template) if isinstance(col, dict)]
    if not quantity_columns:
        return llm_audit
    try:
        default_column_index = int(quantity_columns[0].get("index"))
    except Exception:
        default_column_index = 3
    existing_issues = [dict(item) for item in (llm_audit.get("issues") or []) if isinstance(item, dict)]
    existing_keys = {
        (
            _normalize_audit_issue_code(item.get("issue_code")),
            _parse_audit_int(item.get("row_index")),
            _parse_audit_int(item.get("column_index")),
        )
        for item in existing_issues
    }
    block_anchor_hints = _build_reparse_block_anchor_hints(
        structural_fields=structural_fields,
        structural_rows=structural_rows,
        first_pass_fields=normalized_reference_fields or structural_fields,
        first_pass_rows=reference_row_values,
    )
    blank_anchor_row_indexes = block_anchor_hints.get("unmatched_structural_row_indexes")
    if not blank_anchor_row_indexes:
        blank_anchor_row_indexes = block_anchor_hints.get("structural_blank_anchor_row_indexes")
    normalized_blank_anchor_rows = [
        int(item)
        for item in (blank_anchor_row_indexes or [])
        if str(item).strip().lstrip("-").isdigit()
    ]
    quantity_indexes: list[int] = []
    for column in quantity_columns:
        try:
            col_idx = int(column.get("index"))
        except Exception:
            continue
        if col_idx >= 0:
            quantity_indexes.append(col_idx)
    offending_rows: list[int] = []
    for row_index in normalized_blank_anchor_rows:
        if row_index < 0 or row_index >= len(normalized_rows):
            continue
        row = normalized_rows[row_index]
        has_numeric = False
        for col_idx in quantity_indexes:
            if col_idx < len(row) and _parse_strict_numeric_cell(row[col_idx]) is not None:
                has_numeric = True
                break
        if has_numeric:
            offending_rows.append(row_index)
    structural_date_blocks = _summarize_tabular_date_blocks(structural_rows)
    signature_groups: dict[tuple[tuple[str, int], ...], list[dict[str, Any]]] = {}
    for block in structural_date_blocks:
        if not isinstance(block, dict):
            continue
        sub_blocks = block.get("sub_blocks")
        if not isinstance(sub_blocks, list) or not sub_blocks:
            continue
        signature: tuple[tuple[str, int], ...] = tuple(
            (
                str(item.get("daypart") or "").strip(),
                int(item.get("row_count") or 0),
            )
            for item in sub_blocks
            if isinstance(item, dict)
        )
        if not signature:
            continue
        row_start = block.get("row_start")
        row_end = block.get("row_end")
        if not isinstance(row_start, int) or not isinstance(row_end, int) or row_end < row_start:
            continue
        block_rows = normalized_rows[row_start : row_end + 1]
        if not block_rows:
            continue
        leading_blank_count = 0
        any_filled = False
        for row in block_rows:
            has_numeric = False
            for col_idx in quantity_indexes:
                if col_idx < len(row) and _parse_strict_numeric_cell(row[col_idx]) is not None:
                    has_numeric = True
                    any_filled = True
                    break
            if has_numeric:
                break
            leading_blank_count += 1
        if not any_filled:
            continue
        signature_groups.setdefault(signature, []).append(
            {
                "row_start": row_start,
                "row_end": row_end,
                "leading_blank_count": leading_blank_count,
            }
        )
    for group in signature_groups.values():
        if len(group) < 3:
            continue
        counts: dict[int, int] = {}
        for item in group:
            count = int(item.get("leading_blank_count") or 0)
            counts[count] = counts.get(count, 0) + 1
        majority_count = None
        majority_frequency = 0
        for count, frequency in counts.items():
            if frequency > majority_frequency:
                majority_count = count
                majority_frequency = frequency
        if majority_count is None or majority_count <= 0 or majority_frequency < 2:
            continue
        if majority_frequency * 2 <= len(group):
            continue
        for item in group:
            row_start = int(item.get("row_start") or 0)
            leading_blank_count = int(item.get("leading_blank_count") or 0)
            if leading_blank_count >= majority_count:
                continue
            for row_index in range(row_start + leading_blank_count, row_start + majority_count):
                if 0 <= row_index < len(normalized_rows):
                    offending_rows.append(row_index)
    offending_rows = sorted(set(offending_rows))
    if not offending_rows:
        return llm_audit
    augmented_issues = list(existing_issues)
    for row_index in offending_rows[:80]:
        for issue_code, reason in (
            (
                "missing_blank_anchor_rows",
                "Keep this structural row blank unless the fax shows direct row-level evidence.",
            ),
            (
                "unexpected_dense_fill",
                "Do not fill structurally blank rows unless the fax shows explicit row-local evidence.",
            ),
        ):
            key = (issue_code, row_index, default_column_index)
            if key in existing_keys:
                continue
            existing_keys.add(key)
            augmented_issues.append(
                {
                    "issue_code": issue_code,
                    "severity": "high",
                    "row_index": row_index,
                    "column_index": default_column_index,
                    "confidence": 0.99,
                    "evidence": "Structural blank-anchor row was filled by the current OCR candidate.",
                    "reason": reason,
                }
            )
    if len(augmented_issues) == len(existing_issues):
        return llm_audit
    augmented = dict(llm_audit)
    augmented["issues"] = augmented_issues
    augmented["issue_count"] = len(augmented_issues)
    blocking_issues = [dict(item) for item in (augmented.get("blocking_issues") or []) if isinstance(item, dict)]
    blocking_keys = {
        (
            _normalize_audit_issue_code(item.get("issue_code")),
            _parse_audit_int(item.get("row_index")),
            _parse_audit_int(item.get("column_index")),
        )
        for item in blocking_issues
    }
    for item in augmented_issues:
        severity = str(item.get("severity") or "").strip().lower()
        if severity not in {"high", "critical"}:
            continue
        key = (
            _normalize_audit_issue_code(item.get("issue_code")),
            _parse_audit_int(item.get("row_index")),
            _parse_audit_int(item.get("column_index")),
        )
        if key in blocking_keys:
            continue
        blocking_keys.add(key)
        blocking_issues.append(dict(item))
    augmented["blocking_issues"] = blocking_issues
    augmented["blocking_issue_count"] = len(blocking_issues)
    augmented["status"] = "fail"
    return augmented


def _build_deterministic_llm_reparse_feedback(
    *,
    candidate_rows: list[list[str]] | None,
    template: dict[str, Any],
    baseline_fields: list[str] | None,
    baseline_rows: list[list[str]] | None,
    reference_rows: list[list[str]] | None,
    expected_row_count: int,
) -> dict[str, Any] | None:
    normalized_candidate_rows = [list(row) for row in (candidate_rows or []) if isinstance(row, list)]
    normalized_baseline_rows = [list(row) for row in (baseline_rows or []) if isinstance(row, list)]
    normalized_reference_rows = [list(row) for row in (reference_rows or []) if isinstance(row, list)]
    normalized_baseline_fields = [str(field).strip() for field in (baseline_fields or []) if str(field).strip()]
    if not normalized_candidate_rows and not normalized_baseline_rows:
        return None

    quantity_columns = [column for column in _template_quantity_columns(template) if isinstance(column, dict)]
    quantity_indexes: list[int] = []
    for column in quantity_columns:
        try:
            index = int(column.get("index"))
        except Exception:
            continue
        if index >= 0:
            quantity_indexes.append(index)

    issues: list[dict[str, Any]] = []
    if expected_row_count > 0 and len(normalized_candidate_rows) < expected_row_count:
        issues.append(
            {
                "issue_code": "row_count_shortfall",
                "severity": "high",
                "confidence": 0.99,
                "evidence": f"candidate_rows={len(normalized_candidate_rows)} expected_rows={int(expected_row_count)}",
                "reason": "Current sheet structural rows exceed first-pass OCR row coverage.",
            }
        )
    if normalized_candidate_rows and quantity_indexes:
        has_numeric_quantity = False
        for row in normalized_candidate_rows:
            for col_idx in quantity_indexes:
                if col_idx < len(row) and _parse_strict_numeric_cell(row[col_idx]) is not None:
                    has_numeric_quantity = True
                    break
            if has_numeric_quantity:
                break
        if not has_numeric_quantity:
            issues.append(
                {
                    "issue_code": "all_quantity_blank",
                    "severity": "high",
                    "confidence": 0.99,
                    "evidence": "Candidate OCR rows contain no readable quantity digits.",
                    "reason": "Keep structural anchors and re-check every quantity cell against the fax image.",
                }
            )

    feedback: dict[str, Any] = {
        "status": "pass",
        "provider": "deterministic",
        "requested_provider": "deterministic",
        "actual_provider": "deterministic",
        "model": "deterministic-structural-feedback",
        "issue_count": len(issues),
        "blocking_issue_count": 0,
        "issues": issues,
        "blocking_issues": [],
        "threshold": {"mode": "deterministic_structural_feedback"},
    }
    feedback = _augment_llm_reparse_audit_with_structural_feedback(
        llm_audit=feedback,
        candidate_rows=normalized_candidate_rows,
        template=template,
        baseline_fields=normalized_baseline_fields,
        baseline_structure_rows=normalized_baseline_rows,
        reference_rows=normalized_reference_rows,
        reference_fields=normalized_baseline_fields,
    ) or feedback
    normalized_issues = [dict(item) for item in (feedback.get("issues") or []) if isinstance(item, dict)]
    blocking_issues = [
        dict(item)
        for item in (feedback.get("blocking_issues") or [])
        if isinstance(item, dict)
    ]
    if not blocking_issues:
        blocking_issues = [
            dict(item)
            for item in normalized_issues
            if str(item.get("severity") or "").strip().lower() in {"high", "critical"}
        ]
    feedback["issues"] = normalized_issues
    feedback["blocking_issues"] = blocking_issues
    feedback["issue_count"] = len(normalized_issues)
    feedback["blocking_issue_count"] = len(blocking_issues)
    if blocking_issues:
        feedback["status"] = "fail"
    elif normalized_issues:
        feedback["status"] = "unknown"
    else:
        feedback["status"] = "pass"
    return feedback


def _run_optional_llm_reparse_audit(
    *,
    job_id: str,
    processing_stage: str,
    pdf_bytes: bytes,
    provider: str,
    template: dict[str, Any],
    facility_id: str | None,
    preferred_template_id: str | None,
    candidate_rows: list[list[str]],
    reference_rows: list[list[str]] | None,
    baseline_rows: list[list[str]] | None,
    expected_row_count: int,
    metrics_patch: dict[str, Any] | None = None,
    result_state: str = "processing",
) -> dict[str, Any] | None:
    try:
        audit_timeout_seconds = _read_reparse_float_env(
            "OCR_REPARSE_LLM_AUDIT_TIMEOUT_SECONDS",
            60.0,
            min_value=5.0,
        )
        return _run_reparse_with_heartbeat(
            job_id,
            processing_stage=processing_stage,
            result_state=result_state,
            metrics_patch=metrics_patch,
            timeout_marks_job_failed=False,
            timeout_seconds_override=audit_timeout_seconds,
            func=lambda: _run_llm_reparse_audit(
                pdf_bytes=pdf_bytes,
                provider=provider,
                template=template,
                facility_id=facility_id,
                preferred_template_id=preferred_template_id,
                candidate_rows=candidate_rows,
                reference_rows=reference_rows,
                baseline_rows=baseline_rows,
                expected_row_count=expected_row_count,
            ),
        )
    except OCRPipelineOutputPendingError:
        raise
    except Exception as exc:  # noqa: BLE001
        logger.warning(
            "Optional LLM reparse audit skipped stage={} provider={} error={}",
            processing_stage,
            provider,
            str(exc),
        )
        return {
            "status": "unknown",
            "provider": provider,
            "requested_provider": provider,
            "actual_provider": None,
            "provider_switch_reason": "optional_audit_error",
            "model": None,
            "issue_count": 0,
            "blocking_issue_count": 0,
            "issues": [],
            "blocking_issues": [],
            "error": str(exc),
            "threshold": {"mode": "optional_llm_reparse_audit"},
        }


def _build_reparse_debug_payload(
    *,
    provider: str | None,
    requested_provider: str | None,
    llm_assist: bool,
    rows: list[list[str]],
    lines_count: int,
    before_count: int,
    after_count: int,
    changed: bool | None,
    date_strings: list[str] | None = None,
    extracted: object | None = None,
    parsed_output: dict | None = None,
    error: str | None = None,
    request_prompt: str | None = None,
    normalized_lines: list[dict[str, Any]] | None = None,
    reject_reasons: list[str] | None = None,
    validation_detail: dict[str, Any] | None = None,
    warning_reasons: list[str] | None = None,
    warning_detail: dict[str, Any] | None = None,
    llm_quantity_only_merge: dict[str, Any] | None = None,
    structural_row_projection: dict[str, Any] | None = None,
    llm_cost: dict[str, Any] | None = None,
    llm_audit: dict[str, Any] | None = None,
    pdf_variant_used: str | None = None,
    pdf_variant_fallback_reason: str | None = None,
    quality_metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    raw_limit = _debug_text_max_chars()
    payload: dict[str, Any] = {
        "updated_at": datetime.utcnow().isoformat(),
        "provider": provider or None,
        "requested_provider": requested_provider or None,
        "llm_assist": bool(llm_assist),
        "row_count": len(rows or []),
        "line_count": int(lines_count),
        "before_count": int(before_count),
        "after_count": int(after_count),
        "changed": changed if isinstance(changed, bool) else None,
        "error": (error or "").strip() or None,
        "date_strings": [str(item).strip() for item in (date_strings or []) if str(item).strip()][:40],
        "sample_rows": _compact_debug_rows(rows),
        "normalized_lines": _compact_debug_lines(normalized_lines or []),
    }
    prompt_text = _truncate_debug_text(request_prompt, max_chars=raw_limit)
    if prompt_text:
        payload["request_prompt"] = prompt_text
    if isinstance(reject_reasons, list):
        reasons = [str(item).strip() for item in reject_reasons if str(item).strip()]
        if reasons:
            payload["reject_reasons"] = reasons[:20]
    if isinstance(validation_detail, dict) and validation_detail:
        payload["validation_detail"] = validation_detail
    if isinstance(warning_reasons, list):
        reasons = [str(item).strip() for item in warning_reasons if str(item).strip()]
        if reasons:
            payload["warning_reasons"] = reasons[:20]
    if isinstance(warning_detail, dict) and warning_detail:
        payload["warning_detail"] = warning_detail
    if isinstance(llm_quantity_only_merge, dict) and llm_quantity_only_merge:
        payload["llm_quantity_only_merge"] = llm_quantity_only_merge
    if isinstance(structural_row_projection, dict) and structural_row_projection:
        payload["structural_row_projection"] = structural_row_projection
    if isinstance(llm_cost, dict) and llm_cost:
        payload["llm_cost"] = llm_cost
    if isinstance(llm_audit, dict) and llm_audit:
        payload["llm_audit"] = llm_audit
        cluster_fill_decision = _resolve_llm_audit_cluster_fill_decision(llm_audit)
        if cluster_fill_decision:
            payload["order_line_cluster_fill_decision"] = cluster_fill_decision
    if isinstance(pdf_variant_used, str) and pdf_variant_used.strip():
        payload["pdf_variant_used"] = pdf_variant_used.strip()
    if isinstance(pdf_variant_fallback_reason, str) and pdf_variant_fallback_reason.strip():
        payload["pdf_variant_fallback_reason"] = pdf_variant_fallback_reason.strip()
    if isinstance(quality_metadata, dict) and quality_metadata:
        for key, value in quality_metadata.items():
            if value is None:
                continue
            payload[key] = value
    provider_debug = getattr(extracted, "provider_debug", None) if extracted is not None else None
    if isinstance(provider_debug, dict) and provider_debug:
        payload["provider_debug"] = provider_debug

    raw_text: str | None = None
    if extracted is not None:
        raw_text = _truncate_debug_text(getattr(extracted, "raw_text", None), max_chars=raw_limit)
    if raw_text is None and isinstance(parsed_output, dict):
        raw_text = _truncate_debug_text(parsed_output.get("table_raw"), max_chars=raw_limit)
    if raw_text:
        payload["raw_text"] = raw_text
    return payload


def reparse_order(
    order_id: str,
    ocr_prompt: str | None = None,
    prompt_preset: str | None = None,
    ocr_provider: str | None = None,
    ocr_model: str | None = None,
    llm_assist: bool = False,
    auto_fallback_context: dict[str, Any] | None = None,
    evaluator_feedback: dict[str, Any] | None = None,
    feedback_retry_depth: int = 0,
    draft_rows_override: list[list[str]] | None = None,
    draft_rows_label: str | None = None,
    resume_first_pass_payload: dict[str, Any] | None = None,
    resume_first_pass_output_reference: str | None = None,
    selected_document_id: str | None = None,
    workflow_attempt_id: str | None = None,
    expected_workflow_revision: int | None = None,
    ocr_job_id: str | None = None,
    _original_request: dict[str, Any] | None = None,
):
    if (workflow_attempt_id is None) != (expected_workflow_revision is None):
        return None, "workflow_attempt_required"
    if not str(ocr_job_id or "").strip():
        return None, "workflow_job_required"
    execution_input = current_nonworkflow_execution()
    if workflow_attempt_id is None and execution_input is None:
        if resume_first_pass_payload is not None:
            return None, "ocr_execution_input_required"
        try:
            execution_input = _capture_nonworkflow_order_execution(ocr_job_id, order_id, selected_document_id)
        except ValueError as exc:
            return None, str(exc)
    with nonworkflow_execution_context(execution_input), workflow_ocr_write_context(workflow_attempt_id, expected_workflow_revision, ocr_job_id, order_id):
        if execution_input is not None and execution_input.get("selected_pdf_error"):
            return None, execution_input["selected_pdf_error"]
        original_request = deepcopy(_original_request) if _original_request is not None else {
            "ocr_prompt": ocr_prompt, "prompt_preset": prompt_preset,
            "ocr_provider": ocr_provider, "ocr_model": ocr_model, "llm_assist": llm_assist,
        }
        if not capture_own_reparse_request(ocr_job_id, original_request):
            return None, "reparse_original_request_conflict"
        try:
            return _reparse_order_with_attempt(
                order_id,
                ocr_prompt=ocr_prompt,
                prompt_preset=prompt_preset,
                ocr_provider=ocr_provider,
                ocr_model=ocr_model,
                llm_assist=llm_assist,
                auto_fallback_context=auto_fallback_context,
                evaluator_feedback=evaluator_feedback,
                feedback_retry_depth=feedback_retry_depth,
                draft_rows_override=draft_rows_override,
                draft_rows_label=draft_rows_label,
                resume_first_pass_payload=resume_first_pass_payload,
                resume_first_pass_output_reference=resume_first_pass_output_reference,
                selected_document_id=selected_document_id,
                workflow_attempt_id=workflow_attempt_id,
                ocr_job_id=ocr_job_id,
                original_request=original_request,
            )
        except _CanonicalOcrProjectionError as exc:
            _update_reparse_job_progress(
                ocr_job_id, status="failed", processing_stage="inference",
                result_state="hard_failed", error_message=str(exc),
                metrics_patch={"error": str(exc)},
            )
            return None, str(exc)


def _reparse_order_with_attempt(
    order_id: str,
    ocr_prompt: str | None = None,
    prompt_preset: str | None = None,
    ocr_provider: str | None = None,
    ocr_model: str | None = None,
    llm_assist: bool = False,
    auto_fallback_context: dict[str, Any] | None = None,
    evaluator_feedback: dict[str, Any] | None = None,
    feedback_retry_depth: int = 0,
    draft_rows_override: list[list[str]] | None = None,
    draft_rows_label: str | None = None,
    resume_first_pass_payload: dict[str, Any] | None = None,
    resume_first_pass_output_reference: str | None = None,
    selected_document_id: str | None = None,
    workflow_attempt_id: str | None = None,
    ocr_job_id: str | None = None,
    original_request: dict[str, Any] | None = None,
):
    selected_document_requested = bool(str(selected_document_id or "").strip())
    before_count = 0
    before_digest = ""
    existing_week_code = None
    existing_lines_updated_at: datetime | None = None
    existing_template_version_id: str | None = None
    existing_document_uri: str | None = None
    facility_week_hint: str | None = None
    global_week_hint: str | None = None
    existing_line_anchors: list[dict[str, Any]] = []
    previous_current_sheet_context: dict[str, Any] | None = None
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return None, "order_not_found"
        if not order.facility_code:
            return None, "facility_missing"
        if not order.document_uri:
            return None, "document_missing"
        facility_id = order.facility_code
        document_uri, selected_document_metadata = _captured_order_document_selection(
            session,
            order,
            selected_document_id,
        )
        if selected_document_metadata.get("error"):
            return None, str(selected_document_metadata["error"])
        if not document_uri:
            return None, "document_missing"
        existing_document_uri = str(document_uri or "").strip() or None
        received_at = order.received_at or pd.Timestamp.utcnow()
        message_id = order.message_id
        existing_week_code = order.week_code
        existing_lines_updated_at = order.lines_updated_at
        existing_template_version_id = str(order.template_version_id or "").strip() or None
        captured_read_input = _captured_reparse_read_input(order_id, write_session=session)
        if captured_read_input is None:
            return None, "reparse_start_input_missing"
        existing_week_code = require_explicit_ingest_week(captured_read_input["order"].get("week_code"))
        captured_received_at = captured_read_input["order"].get("received_at")
        if not captured_received_at:
            return None, "reparse_start_input_missing"
        received_at = datetime.fromisoformat(captured_received_at)
        existing_lines = [
            OrderLine(**{**values, "date": _parse_date_value(values.get("date"))})
            for values in captured_read_input.get("lines", [])
        ]
        before_count = len(existing_lines)
        before_digest = _line_digest(
            [
                {
                    "date": line.date.isoformat() if line.date else None,
                    "daypart": line.daypart,
                    "menu_name": line.menu_name,
                    "diet_type": line.diet_type,
                    "area_id": line.area_id,
                    "bag_type": line.bag_type,
                    "quantity_original": line.quantity_original,
                    "quantity_corrected": line.quantity_corrected,
                    "change_note": line.change_note,
                }
                for line in existing_lines
            ]
        )
        existing_line_anchors = [
            {
                "date": line.date,
                "daypart": line.daypart,
                "menu_name": line.menu_name,
            }
            for line in existing_lines
        ]
    captured_draft = captured_read_input.get("draft")
    previous_current_sheet_context = deepcopy(captured_draft.get("draft_sheet_json")) if isinstance(captured_draft, dict) else None
    existing_anchor_dates = _collect_line_dates_for_position_scope(existing_line_anchors)
    stable_existing_anchor_scope = len(existing_anchor_dates) >= 2

    configured_input = captured_read_input.get("configured_input")
    if not isinstance(configured_input, dict):
        return None, "reparse_configured_input_missing"
    facility_config = deepcopy(configured_input["facility"])
    policy = deepcopy(configured_input["policy"])
    template = facility_config["fax_template"]
    template_to_use = dict(template)
    try:
        requested_provider = _normalize_reparse_provider(ocr_provider)
    except RemovedOcrProviderError as exc:
        return None, str(exc)
    inference_provider = _resolve_explicit_reparse_inference_provider(
        requested_provider=requested_provider,
        llm_assist=bool(llm_assist),
        template=template_to_use,
    )
    if inference_provider:
        template_to_use["main_ocr_provider"] = inference_provider
        template_to_use["_force_main_ocr_provider"] = inference_provider
        if inference_provider == "openai":
            template_to_use["openai_ocr_enabled"] = True
        elif inference_provider == "gemini":
            template_to_use["gemini_ocr_enabled"] = True
    if isinstance(ocr_model, str) and ocr_model.strip():
        if inference_provider == "openai":
            template_to_use["openai_ocr_model"] = ocr_model.strip()
        elif inference_provider == "gemini":
            template_to_use["gemini_ocr_model"] = ocr_model.strip()
    main_provider = str(
        inference_provider
        or os.getenv("OCR_MAIN_PROVIDER")
        or template_to_use.get("main_ocr_provider")
        or "pipeline"
    ).lower()
    auto_fallback_applied = isinstance(auto_fallback_context, dict) and bool(auto_fallback_context)
    auto_fallback_from_provider = (
        str(auto_fallback_context.get("from_provider") or "").strip().lower()
        if auto_fallback_applied
        else None
    )
    auto_fallback_reason = (
        str(auto_fallback_context.get("reason") or "").strip() or None
        if auto_fallback_applied
        else None
    )
    reparse_request_metadata = _build_reparse_request_metadata(
        ocr_prompt=ocr_prompt,
        prompt_preset=prompt_preset,
        requested_provider=requested_provider,
        ocr_model=ocr_model,
        llm_assist=bool(llm_assist),
    )

    def _current_reparse_quality_metadata() -> dict[str, Any]:
        return {
            **_build_reparse_quality_metadata(
                requested_provider=requested_provider,
                effective_provider=main_provider,
                llm_assist=bool(llm_assist),
                auto_fallback_applied=bool(auto_fallback_applied),
                feedback_retry_depth=feedback_retry_depth,
            ),
            **reparse_request_metadata,
            **selected_document_metadata,
        }

    llm_full_table_requested = bool(
        llm_assist and (inference_provider in {"openai", "gemini"} or main_provider in {"openai", "gemini"})
    )
    llm_quantity_only_requested = bool(
        (not llm_full_table_requested)
        and (
            llm_assist
            or inference_provider in {"openai", "gemini"}
            or main_provider in {"openai", "gemini"}
        )
    )
    requires_first_pass_context = bool(
        llm_assist
        or inference_provider in {"openai", "gemini"}
        or (ocr_prompt and main_provider in {"openai", "gemini"})
    )
    if llm_quantity_only_requested:
        template_to_use["llm_quantity_only_mode"] = True
    if llm_assist or inference_provider in {"openai", "gemini"} or main_provider in {"openai", "gemini"}:
        template_to_use["openai_ocr_fallback_provider"] = "none"
        template_to_use["gemini_ocr_fallback_provider"] = "none"
    existing_first_pass_payload = None
    if resume_first_pass_payload is not None:
        existing_first_pass_payload, own_input_error = _resolve_own_resume_first_pass(
            order_id, ocr_job_id, resume_first_pass_payload, template_to_use,
            output_reference=resume_first_pass_output_reference,
            selected_input_reference=document_uri if selected_document_requested else None,
        )
        if own_input_error:
            return _rejected_reparse_result(order_id, resume_first_pass_payload, ocr_job_id, own_input_error)
    elif requires_first_pass_context and not selected_document_requested:
        existing_first_pass_payload, selected_input_error = _load_existing_first_pass_payload_for_reparse(
            order_id,
            template=template_to_use,
        )
        if selected_input_error:
            return None, selected_input_error
    reused_first_pass_payload = isinstance(existing_first_pass_payload, dict)

    document_uri = existing_document_uri
    if not document_uri:
        return None, "document_missing"
    from src.services.storage_service import load_selected_pdf_bytes

    pdf_bytes = load_selected_pdf_bytes(document_uri)
    llm_input_pdf_bytes = pdf_bytes
    llm_input_pdf_meta: dict[str, Any] = {
        "requested": "raw",
        "used": "raw",
        "fallback_reason": None,
    }
    normalized_ocr_job_id = str(ocr_job_id or "").strip()
    ocr_job_id = normalized_ocr_job_id
    workflow_template_version_id = existing_template_version_id
    with session_scope() as session:
        if not _workflow_attempt_write_fence(session, ocr_job_id, order_id):
            return None, "workflow_attempt_superseded"
    if _workflow_ocr_attempt_id.get() is None:
        job_updates: dict[str, Any] = {
            "status": "running",
            "error_message": None,
            "template_id": None,
            "input_reference": document_uri,
            "order_id": order_id,
            "template_version_id": workflow_template_version_id,
            # Always cut the stale first-pass artifact off the shared reparse job row.
            "output_reference": (
                str(resume_first_pass_output_reference or "").strip() or None
                if reused_first_pass_payload
                else None
            ),
            # Keep explicit reparse identity on the job row so read paths cannot
            # misclassify the active attempt as a normal first-pass job.
            "metrics": {
                **_current_reparse_quality_metadata(),
                "status": "running",
                "processing_stage": "queued",
                "result_state": "processing",
                "confirmed_lines_retained": bool(before_count > 0),
            },
        }
        update_job(ocr_job_id, **job_updates)
    preferred_template_id, preferred_template_ids = _resolve_preferred_template_ids(facility_config)
    fresh_llm_first_pass_required = bool(
        not reused_first_pass_payload
        and (
            llm_assist
            or inference_provider in {"openai", "gemini"}
            or main_provider in {"openai", "gemini"}
        )
    )
    pipeline_output_ref: str | None = None
    pipeline_output_payload: dict | None = existing_first_pass_payload if reused_first_pass_payload else None
    current_pipeline_result = bool(
        resume_first_pass_payload is not None
        and pipeline_output_payload.get("engine") == "yomitoku"
    )
    if reused_first_pass_payload:
        logger.info("Reparse reusing cached first-pass OCR payload order_id={}", order_id)
        if resume_first_pass_output_reference:
            _update_ocr_execution_job(
                ocr_job_id,
                output_reference=str(resume_first_pass_output_reference).strip() or None,
                input_reference=document_uri,
                error_message=None,
            )
        _update_reparse_job_progress(
            ocr_job_id,
            status="running",
            processing_stage="first_pass_reused",
            result_state="processing",
            error_message=None,
            metrics_patch={
                "reused_first_pass": True,
                "pipeline_run_skipped": True,
                **_current_reparse_quality_metadata(),
            },
        )
    else:
        _update_reparse_job_progress(
            ocr_job_id,
            status="running",
            processing_stage="ocr_pipeline",
            result_state="processing",
            error_message=None,
        )
        if fresh_llm_first_pass_required or main_provider == "pipeline":
            try:
                pipeline_output_payload = _run_reparse_with_heartbeat(
                    ocr_job_id,
                    processing_stage="ocr_pipeline",
                    result_state="processing",
                    metrics_patch={
                        "confirmed_lines_retained": bool(before_count > 0),
                        **_current_reparse_quality_metadata(),
                    },
                    func=lambda: run_ocr_pipeline(
                        pdf_bytes=pdf_bytes,
                        job_id=ocr_job_id,
                        facility_id=facility_id,
                        input_reference=document_uri,
                        preferred_template_id=preferred_template_id,
                        preferred_template_ids=preferred_template_ids,
                        force_upload=True,
                        wait_for_output=True,
                    ),
                )
                if isinstance(pipeline_output_payload, dict):
                    current_pipeline_result = True
                    pipeline_output_ref = str(pipeline_output_payload.get("output_reference") or "").strip() or None
                    _update_ocr_execution_job(
                        ocr_job_id,
                        status="running",
                        template_id=pipeline_output_payload.get("template_id"),
                        output_reference=pipeline_output_ref,
                        error_message=None,
                    )
            except OCRPipelineOutputPendingError as exc:
                pipeline_output_ref = str(exc.output_reference or "").strip() or None
                pending_result = _mark_reparse_job_awaiting_output(
                    ocr_job_id,
                    input_reference=exc.input_reference,
                    output_reference=pipeline_output_ref,
                    metrics_patch={
                        "confirmed_lines_retained": bool(before_count > 0),
                        "preferred_template_id": preferred_template_id,
                        "preferred_template_ids": preferred_template_ids,
                        "first_pass_wait_seconds": float(exc.timeout_seconds),
                        "reused_first_pass": False,
                        "pipeline_run_skipped": False,
                        **_current_reparse_quality_metadata(),
                    },
                    recovery_delay_seconds=float(exc.timeout_seconds),
                )
                return (pending_result, None) if pending_result is not None else (None, "ocr_pending_write_rejected")
        else:
            pipeline_output_ref = _run_roi_ocr_pipeline(
                job_id=ocr_job_id,
                pdf_bytes=pdf_bytes,
                facility_id=facility_id,
                input_reference=document_uri,
                preferred_template_id=preferred_template_id,
                preferred_template_ids=preferred_template_ids,
            )
    pipeline_rows_for_rescue: list[list[str]] = []
    pipeline_anchor_dates: set[date] = set()
    position_entries_for_existing_week: list[dict] = []
    expected_weekly_row_count = 0
    llm_reparse_baseline: dict[str, Any] | None = None
    llm_pre_inference_audit: dict[str, Any] | None = None
    resolved_draft_rows_override = [list(row) for row in (draft_rows_override or []) if isinstance(row, list)]
    resolved_draft_rows_label = draft_rows_label
    if existing_week_code:
        if stable_existing_anchor_scope:
            position_entries_for_existing_week = _build_position_entries_for_lines(
                week_id=existing_week_code,
                lines=existing_line_anchors,
                facility_id=facility_id,
            )
        if not position_entries_for_existing_week:
            position_entries_for_existing_week = _build_position_menu_entries_safe(existing_week_code, facility_id)
        expected_weekly_row_count = len(position_entries_for_existing_week)
    if requires_first_pass_context:
        llm_wait_seconds: float | None = None
        if not isinstance(pipeline_output_payload, dict):
            if llm_assist:
                try:
                    llm_wait_seconds = float(
                        os.getenv("OCR_REPARSE_LLM_FIRST_PASS_WAIT_SECONDS", os.getenv("OCR_PIPELINE_TIMEOUT_SECONDS", "600"))
                    )
                except ValueError:
                    llm_wait_seconds = 600.0
            pipeline_output_payload = _load_pipeline_output_with_retry(
                pipeline_output_ref,
                wait_seconds_override=llm_wait_seconds,
            )
        if not _payload_has_first_pass_ocr_content(pipeline_output_payload):
            if fresh_llm_first_pass_required and pipeline_output_ref and (
                pipeline_output_payload is None or _output_is_pending(pipeline_output_payload)
            ):
                wait_seconds_value = llm_wait_seconds if llm_wait_seconds is not None else _read_reparse_output_recovery_grace_seconds()
                pending_result = _mark_reparse_job_awaiting_output(
                    ocr_job_id,
                    input_reference=document_uri,
                    output_reference=pipeline_output_ref,
                    metrics_patch={
                        "first_pass_wait_seconds": wait_seconds_value,
                        "preferred_template_id": preferred_template_id,
                        "preferred_template_ids": preferred_template_ids,
                        "reused_first_pass": False,
                        "pipeline_run_skipped": False,
                        "confirmed_lines_retained": bool(before_count > 0),
                        **_current_reparse_quality_metadata(),
                    },
                    recovery_delay_seconds=wait_seconds_value,
                )
                return (pending_result, None) if pending_result is not None else (None, "ocr_pending_write_rejected")
        if not _payload_has_first_pass_ocr_content(pipeline_output_payload):
            _update_reparse_job_progress(
                ocr_job_id,
                status="failed",
                processing_stage="first_pass_missing",
                result_state="hard_failed",
                error_message="first_pass_ocr_missing",
                metrics_patch={
                    "error": "first_pass_ocr_missing",
                    "reused_first_pass": bool(reused_first_pass_payload),
                    "pipeline_run_skipped": bool(reused_first_pass_payload),
                    "confirmed_lines_retained": bool(before_count > 0),
                    **_current_reparse_quality_metadata(),
                },
            )
            try:
                rejected_result = _persist_reparse_diagnostics(
                    order_id, pipeline_output_payload, ocr_job_id,
                    {"error": "first_pass_ocr_missing"},
                )
            except Exception as exc:  # noqa: BLE001
                return None, str(exc)
            return rejected_result, "first_pass_ocr_missing"
        if isinstance(pipeline_output_payload, dict):
            pipeline_rows_for_rescue = _extract_first_pass_rows_from_payload(
                pipeline_output_payload,
                template_to_use,
            )
            if not pipeline_rows_for_rescue:
                pipeline_rows_for_rescue = _extract_sheet_rows_from_payload(
                    pipeline_output_payload,
                    template_to_use,
                )
            pipeline_anchor_dates = {
                item
                for item in _collect_sheet_dates_from_payload(pipeline_output_payload, received_at, template_to_use, explicit_week=require_explicit_ingest_week(existing_week_code))
                if isinstance(item, date)
            }
            if position_entries_for_existing_week and not stable_existing_anchor_scope:
                payload_dates = set(pipeline_anchor_dates)
                if payload_dates:
                    scoped_entries = _filter_position_menu_entries_by_dates(
                        position_entries_for_existing_week,
                        payload_dates,
                        min_anchor_dates=1,
                    )
                    if scoped_entries:
                        expected_weekly_row_count = len(scoped_entries)
            expected_weekly_row_count = _resolve_llm_expected_row_count(
                menu_expected_row_count=expected_weekly_row_count,
                pipeline_rows=pipeline_rows_for_rescue,
                anchor_date_count=len(pipeline_anchor_dates),
            )
        llm_reparse_baseline = _resolve_reparse_llm_baseline(
            order_id=order_id,
            template=template_to_use,
            fallback_payload=pipeline_output_payload,
        )
        if llm_full_table_requested:
            baseline_fields, _baseline_header, baseline_rows, _baseline_row_ids, _baseline_source = (
                _resolve_reparse_current_sheet_baseline_rows(llm_reparse_baseline)
            )
            if not baseline_fields or not baseline_rows:
                _update_reparse_job_progress(
                    ocr_job_id,
                    status="failed",
                    processing_stage="baseline_missing",
                    result_state="hard_failed",
                    error_message="llm_full_table_baseline_missing",
                    metrics_patch={
                        "error": "llm_full_table_baseline_missing",
                        "reused_first_pass": bool(reused_first_pass_payload),
                        "pipeline_run_skipped": bool(reused_first_pass_payload),
                        "confirmed_lines_retained": bool(before_count > 0),
                        **_current_reparse_quality_metadata(),
                    },
                )
                return _rejected_reparse_result(
                    order_id, pipeline_output_payload, ocr_job_id, "llm_full_table_baseline_missing",
                )
            template_to_use["llm_full_table_mode"] = True
            template_to_use["llm_full_table_expected_row_count"] = len(baseline_rows)
            template_to_use.pop("llm_quantity_only_mode", None)
        llm_pdf_payload = (
            pipeline_output_payload
            if isinstance(pipeline_output_payload, dict)
            else None
        )
        llm_input_pdf_bytes, llm_input_pdf_meta = _resolve_reparse_llm_pdf_bytes(
            document_uri=document_uri,
            payload=llm_pdf_payload if isinstance(llm_pdf_payload, dict) else None,
            original_pdf_bytes=pdf_bytes,
        )
        effective_provider = inference_provider or main_provider
        if effective_provider in {"openai", "gemini"}:
            baseline_reference_fields, baseline_reference_rows, _, _ = _resolve_reparse_baseline_rows_for_structure(
                llm_reparse_baseline
            )
            audit_reference_rows = baseline_reference_rows or [
                list(row) for row in pipeline_rows_for_rescue if isinstance(row, list)
            ]
            audit_expected_row_count = _resolve_llm_expected_row_count(
                menu_expected_row_count=expected_weekly_row_count,
                pipeline_rows=pipeline_rows_for_rescue,
                observed_rows=baseline_reference_rows,
                anchor_date_count=len(pipeline_anchor_dates),
            )
            if pipeline_rows_for_rescue:
                llm_pre_inference_audit = _build_deterministic_llm_reparse_feedback(
                    candidate_rows=[list(row) for row in pipeline_rows_for_rescue if isinstance(row, list)],
                    template=template_to_use,
                    baseline_fields=baseline_reference_fields,
                    baseline_rows=baseline_reference_rows,
                    reference_rows=audit_reference_rows,
                    expected_row_count=audit_expected_row_count,
                )
            if ocr_prompt and ocr_prompt.strip():
                if effective_provider == "openai":
                    template_to_use["openai_ocr_user_prompt"] = ocr_prompt.strip()
                else:
                    template_to_use["gemini_ocr_user_prompt"] = ocr_prompt.strip()
            assist_prompt = _build_llm_assist_prompt(
                provider=effective_provider,
                template=template_to_use,
                pipeline_output=pipeline_output_payload,
                llm_assist=llm_assist,
                prompt_preset=prompt_preset,
                failure_context=auto_fallback_context,
                baseline=llm_reparse_baseline,
                evaluator_feedback=(
                    evaluator_feedback
                    if isinstance(evaluator_feedback, dict) and evaluator_feedback
                    else llm_pre_inference_audit
                ),
                draft_rows_override=resolved_draft_rows_override,
                draft_rows_label=resolved_draft_rows_label,
                first_pass_rows_override=[list(row) for row in pipeline_rows_for_rescue if isinstance(row, list)],
            )
            if assist_prompt:
                if effective_provider == "openai":
                    template_to_use["openai_ocr_prompt"] = assist_prompt
                    template_to_use["openai_ocr_enabled"] = True
                else:
                    template_to_use["gemini_ocr_prompt"] = assist_prompt
                    template_to_use["gemini_ocr_enabled"] = True
    effective_prompt = _resolve_reparse_prompt_text(
        provider=main_provider,
        template=template_to_use,
        user_prompt=ocr_prompt,
    )
    date_strings = []
    rows = []
    tokens = []
    grid = None
    extracted_data = None
    main_ocr_error: str | None = None
    llm_finish_reason: str | None = None
    llm_truncated_output = False
    llm_rows_replaced_with_pipeline = False
    llm_quantity_only_active = False
    llm_full_table_active = bool(template_to_use.get("llm_full_table_mode"))
    llm_full_table_merge_stats: dict[str, Any] | None = None
    preparse_validation_error: str | None = None
    preparse_validation_detail: dict[str, Any] | None = None
    llm_quantity_only_merge_stats: dict[str, int] = {}
    reparse_quality_error: str | None = None
    reparse_quality_detail: dict[str, Any] | None = None
    llm_repair_pass_applied = False
    llm_repair_pass_reason: str | None = None
    llm_repair_pass_error: str | None = None
    llm_primary_model: str | None = None
    llm_repair_pass_model: str | None = None
    llm_feedback_second_pass_applied = False
    llm_feedback_second_pass_error: str | None = None
    reparse_cost_info: dict[str, Any] | None = None
    llm_audit_result: dict[str, Any] | None = None
    llm_second_pass_audit: dict[str, Any] | None = None
    blank_anchor_realign: dict[str, Any] | None = None
    structural_row_projection: dict[str, Any] | None = None
    quantity_sanitize_stats: dict[str, int] | None = None

    try:
        _update_reparse_job_progress(
            ocr_job_id,
            status="running",
            processing_stage="inference",
            result_state="processing",
            metrics_patch=_current_reparse_quality_metadata(),
        )
        extracted = _run_reparse_with_heartbeat(
            ocr_job_id,
            processing_stage="inference",
            result_state="processing",
            metrics_patch=_current_reparse_quality_metadata(),
            func=lambda: extract_fax_data(
                llm_input_pdf_bytes if main_provider in {"openai", "gemini"} else pdf_bytes,
                template_to_use,
                facility_id=facility_id,
                preferred_template_id=preferred_template_id,
                own_pipeline_payload=pipeline_output_payload if current_pipeline_result else None,
            ),
        )
        if extracted.own_pipeline_payload is not None:
            pipeline_output_payload = extracted.own_pipeline_payload
            pipeline_output_ref = pipeline_output_payload.get("output_reference")
            current_pipeline_result = True
            extracted.table_rows = _extract_sheet_rows_from_payload_uncanonicalized(
                pipeline_output_payload, template_to_use,
            )
        extracted_data = extracted
        actual_provider = str(extracted.ocr_provider or "").strip().lower()
        if llm_assist and actual_provider.endswith("_fallback_pipeline"):
            _update_reparse_job_progress(
                ocr_job_id,
                status="failed",
                processing_stage="inference",
                result_state="hard_failed",
                error_message="llm_provider_fallback_pipeline",
                metrics_patch={
                    "error": "llm_provider_fallback_pipeline",
                    "actual_provider": actual_provider,
                    "requested_provider": requested_provider or None,
                    "reused_first_pass": bool(reused_first_pass_payload),
                    "pipeline_run_skipped": bool(reused_first_pass_payload),
                    "confirmed_lines_retained": bool(before_count > 0),
                    **_current_reparse_quality_metadata(),
                },
            )
            return _rejected_reparse_result(
                order_id, pipeline_output_payload, ocr_job_id, "llm_provider_fallback_pipeline",
                {"actual_provider": actual_provider, "rows": deepcopy(extracted.table_rows)},
            )
        if extracted.ocr_provider:
            main_provider = extracted.ocr_provider
            effective_prompt = _resolve_reparse_prompt_text(
                provider=main_provider,
                template=template_to_use,
                user_prompt=ocr_prompt,
            )
        strict_llm_quantity = bool(
            llm_assist
            or inference_provider in {"openai", "gemini"}
            or main_provider in {"openai", "gemini"}
        )
        reparse_quantity_rules = _build_reparse_quantity_rules(
            policy.get("quantity_rules", {}),
            strict_llm_quantity=strict_llm_quantity,
        )
        date_strings = extracted.date_strings or []
        rows = extracted.table_rows or []
        tokens = extracted.tokens or []
        grid = extracted.grid
        provider_debug = extracted.provider_debug if isinstance(extracted.provider_debug, dict) else {}
        llm_primary_model = str(provider_debug.get("model") or "").strip() or None
        rows_for_quantity_quality = [list(row) for row in rows if isinstance(row, list)]
        if not llm_primary_model and main_provider in {"openai", "gemini"}:
            resolved_model = _resolve_provider_model_name(
                provider=main_provider,
                template=template_to_use,
            )
            llm_primary_model = resolved_model or None
        llm_quantity_only_active = bool(provider_debug.get("quantity_only_mode"))
        if not llm_quantity_only_active:
            llm_quantity_only_active = _rows_look_like_quantity_only(
                rows=[list(row) for row in rows if isinstance(row, list)],
                template=template_to_use,
                rows_are_body_only=bool(provider_debug.get("quantity_only_mode")),
            )
        if llm_full_table_active:
            llm_quantity_only_active = False
        if llm_quantity_only_active:
            provider_debug["quantity_only_mode"] = True
            extracted.provider_debug = provider_debug
        merge_with_pipeline_enabled = _read_reparse_bool_env(
            "OCR_REPARSE_ENABLE_PIPELINE_QUANTITY_MERGE",
            False,
        )
        if llm_quantity_only_active and pipeline_rows_for_rescue and merge_with_pipeline_enabled:
            merged_rows, merge_stats = _merge_llm_quantity_only_rows_with_pipeline(
                llm_rows=[list(row) for row in rows if isinstance(row, list)],
                pipeline_rows=[list(row) for row in pipeline_rows_for_rescue if isinstance(row, list)],
                template=template_to_use,
            )
            if merge_stats.get("quantity_cells_updated", 0) > 0:
                rows = merged_rows
                llm_quantity_only_merge_stats = merge_stats
                provider_debug["quantity_only_merge"] = merge_stats
                extracted.provider_debug = provider_debug
        elif llm_quantity_only_active and pipeline_rows_for_rescue and not merge_with_pipeline_enabled:
            provider_debug["quantity_only_merge_disabled"] = True
            extracted.provider_debug = provider_debug
        if llm_quantity_only_active and pipeline_rows_for_rescue and isinstance(llm_reparse_baseline, dict):
            rows_for_quantity_quality = [list(row) for row in rows if isinstance(row, list)]
            baseline_fields, baseline_structure_rows, _, _ = _resolve_reparse_baseline_rows_for_structure(
                llm_reparse_baseline
            )
            realigned_rows, blank_anchor_realign = _realign_quantity_only_rows_to_structural_blank_anchors(
                rows=[list(row) for row in rows if isinstance(row, list)],
                template=template_to_use,
                structural_fields=baseline_fields,
                structural_rows=baseline_structure_rows,
                reference_rows=[list(row) for row in pipeline_rows_for_rescue if isinstance(row, list)],
                reference_fields=_row_fields_from_template(template_to_use) or baseline_fields,
            )
            if isinstance(blank_anchor_realign, dict) and blank_anchor_realign:
                rows = realigned_rows
                provider_debug["blank_anchor_realign"] = blank_anchor_realign
                extracted.provider_debug = provider_debug
            should_project_rows = _should_project_quantity_rows_to_structural_rows(
                rows=[list(row) for row in rows if isinstance(row, list)],
                structural_rows=baseline_structure_rows,
                template=template_to_use,
            )
            if should_project_rows:
                projected_rows, projected_stats = _project_quantity_only_rows_onto_structural_rows(
                    rows=[list(row) for row in rows if isinstance(row, list)],
                    template=template_to_use,
                    structural_fields=baseline_fields,
                    structural_rows=baseline_structure_rows,
                )
                if isinstance(projected_stats, dict) and projected_stats:
                    rows = projected_rows
                    structural_row_projection = projected_stats
                    provider_debug["structural_row_projection"] = projected_stats
                    extracted.provider_debug = provider_debug
        llm_finish_reason = _extract_llm_finish_reason(extracted)
        llm_truncated_output = (
            main_provider in {"openai", "gemini"} and _is_truncated_llm_output(extracted)
        )
        if llm_truncated_output:
            reason = llm_finish_reason or "truncated_output"
            main_ocr_error = f"{main_provider}_output_truncated:{reason}"
            if llm_full_table_active:
                provider_debug = extracted.provider_debug if isinstance(extracted.provider_debug, dict) else {}
                provider_debug = dict(provider_debug)
                provider_debug["truncated_output_blocked"] = True
                provider_debug["truncated_output_reason"] = reason
                extracted.provider_debug = provider_debug
                preparse_validation_error = "llm_full_table_truncated_output"
                preparse_validation_detail = {
                    "finish_reason": reason,
                    "row_count": len(rows),
                    "expected_row_count": expected_weekly_row_count,
                }
            elif pipeline_rows_for_rescue:
                logger.warning(
                    "Discarding truncated LLM OCR rows and using pipeline rows provider={} reason={} llm_rows={} pipeline_rows={}",
                    main_provider,
                    reason,
                    len(rows),
                    len(pipeline_rows_for_rescue),
                )
                rows = pipeline_rows_for_rescue
                tokens = []
                llm_rows_replaced_with_pipeline = True
            else:
                rows = []
                tokens = []
        if (
            main_provider in {"openai", "gemini"}
            and not llm_rows_replaced_with_pipeline
            and expected_weekly_row_count > 0
            and len(rows) < expected_weekly_row_count
            and len(pipeline_rows_for_rescue) >= expected_weekly_row_count
            and not (
                llm_quantity_only_active
                and bool(reparse_quantity_rules.get("allow_blank_structure_rows"))
            )
        ):
            main_ocr_error = (
                f"{main_provider}_row_shortfall:{len(rows)}/{expected_weekly_row_count}"
            )
            if llm_full_table_active:
                logger.warning(
                    "Retaining LLM full-table OCR row shortfall provider={} llm_rows={} expected_rows={} returned rows stay baseline-bounded",
                    main_provider,
                    len(rows),
                    expected_weekly_row_count,
                )
                provider_debug = (
                    extracted.provider_debug if isinstance(extracted.provider_debug, dict) else {}
                )
                provider_debug = dict(provider_debug)
                provider_debug["row_shortfall_retained"] = True
                provider_debug["row_shortfall_expected"] = expected_weekly_row_count
                provider_debug["row_shortfall_actual"] = len(rows)
                extracted.provider_debug = provider_debug
            else:
                logger.warning(
                    "LLM OCR row count shortfall; using pipeline rows provider={} llm_rows={} expected_rows={} pipeline_rows={}",
                    main_provider,
                    len(rows),
                    expected_weekly_row_count,
                    len(pipeline_rows_for_rescue),
                )
                rows = pipeline_rows_for_rescue
                tokens = []
                llm_rows_replaced_with_pipeline = True

        if (
            main_provider in {"openai", "gemini"}
            and llm_quantity_only_active
            and not llm_rows_replaced_with_pipeline
        ):
            expected_weekly_row_count = _resolve_llm_expected_row_count(
                menu_expected_row_count=expected_weekly_row_count,
                pipeline_rows=pipeline_rows_for_rescue,
                anchor_date_count=len(pipeline_anchor_dates),
            )
            quality_error, quality_detail = _evaluate_quantity_only_rows_quality(
                rows=rows_for_quantity_quality,
                template=template_to_use,
                expected_row_count=expected_weekly_row_count,
                reference_rows=pipeline_rows_for_rescue,
            )
            reparse_quality_error = quality_error
            reparse_quality_detail = quality_detail

            repair_enabled = str(
                os.getenv("OCR_REPARSE_ENABLE_REPAIR_PASS", "1")
            ).strip().lower() not in {"0", "false", "no", "off"}
            if repair_enabled and reparse_quality_error in {"sheet_row_coverage_low", "sheet_row_overfill", "sheet_column_anomaly"}:
                repair_template = dict(template_to_use)
                target_repair_model = _resolve_provider_model_name(
                    provider=main_provider,
                    template=repair_template,
                )
                use_pro_repair, pro_repair_model = _should_use_gemini_pro_repair_pass(
                    provider=main_provider,
                    template=repair_template,
                    quality_error=reparse_quality_error,
                )
                if use_pro_repair:
                    repair_template["gemini_ocr_model"] = pro_repair_model
                    target_repair_model = pro_repair_model
                llm_repair_pass_model = str(target_repair_model or "").strip() or None
                baseline_fields, baseline_structure_rows, _, _ = _resolve_reparse_baseline_rows_for_structure(
                    llm_reparse_baseline
                )
                repair_system_prompt, repair_user_prompt = _build_quantity_only_repair_prompts(
                    provider=main_provider,
                    template=repair_template,
                    current_rows=[list(row) for row in rows if isinstance(row, list)],
                    baseline_rows=baseline_structure_rows,
                    baseline_fields=baseline_fields,
                    structural_rows=baseline_structure_rows,
                    structural_fields=baseline_fields,
                    expected_row_count=expected_weekly_row_count,
                    quality_error=reparse_quality_error,
                    quality_detail=reparse_quality_detail,
                    first_pass_model=llm_primary_model,
                    target_model=llm_repair_pass_model,
                )
                if main_provider == "openai":
                    repair_template["openai_ocr_prompt"] = repair_system_prompt
                    repair_template["openai_ocr_user_prompt"] = repair_user_prompt
                    repair_template["openai_ocr_enabled"] = True
                else:
                    repair_template["gemini_ocr_prompt"] = repair_system_prompt
                    repair_template["gemini_ocr_user_prompt"] = repair_user_prompt
                    repair_template["gemini_ocr_enabled"] = True
                try:
                    repaired_extracted = _run_reparse_with_heartbeat(
                        ocr_job_id,
                        processing_stage="inference",
                        result_state="processing",
                        metrics_patch=_current_reparse_quality_metadata(),
                        func=lambda: extract_fax_data(
                            llm_input_pdf_bytes,
                            repair_template,
                            facility_id=facility_id,
                            preferred_template_id=preferred_template_id,
                        ),
                    )
                    repaired_rows = repaired_extracted.table_rows or []
                    repaired_tokens = repaired_extracted.tokens or []
                    repaired_date_strings = repaired_extracted.date_strings or date_strings
                    repaired_grid = repaired_extracted.grid or grid
                    repaired_rows_for_quality = [
                        list(row) for row in repaired_rows if isinstance(row, list)
                    ]
                    repaired_quality_error, repaired_quality_detail = _evaluate_quantity_only_rows_quality(
                        rows=repaired_rows_for_quality,
                        template=repair_template,
                        expected_row_count=expected_weekly_row_count,
                        reference_rows=pipeline_rows_for_rescue,
                    )
                    use_repaired = _is_reparse_quality_improved(
                        before_error=reparse_quality_error,
                        before_detail=reparse_quality_detail,
                        after_error=repaired_quality_error,
                        after_detail=repaired_quality_detail,
                    )
                    if use_repaired:
                        rows = [list(row) for row in repaired_rows if isinstance(row, list)]
                        rows_for_quantity_quality = repaired_rows_for_quality
                        tokens = repaired_tokens
                        date_strings = repaired_date_strings
                        grid = repaired_grid
                        extracted_data = repaired_extracted
                        reparse_quality_error = repaired_quality_error
                        reparse_quality_detail = repaired_quality_detail
                        llm_finish_reason = _extract_llm_finish_reason(repaired_extracted)
                        llm_truncated_output = _is_truncated_llm_output(repaired_extracted)
                        llm_repair_pass_applied = True
                        llm_repair_pass_reason = quality_error
                        template_to_use = repair_template
                        repaired_debug = (
                            repaired_extracted.provider_debug
                            if isinstance(repaired_extracted.provider_debug, dict)
                            else {}
                        )
                        repaired_model = str(repaired_debug.get("model") or "").strip()
                        if repaired_model:
                            llm_repair_pass_model = repaired_model
                        effective_prompt = _resolve_reparse_prompt_text(
                            provider=main_provider,
                            template=repair_template,
                            user_prompt=ocr_prompt,
                        )
                except OCRPipelineOutputPendingError:
                    raise
                except Exception as exc:  # noqa: BLE001
                    llm_repair_pass_error = str(exc)
                    logger.warning(
                        "Reparse repair pass failed provider={} error={}",
                        main_provider,
                        llm_repair_pass_error,
                    )
        if (
            main_provider in {"openai", "gemini"}
            and rows
            and not llm_rows_replaced_with_pipeline
        ):
            _, baseline_reference_rows, _, _ = _resolve_reparse_baseline_rows_for_structure(llm_reparse_baseline)
            audit_reference_rows = baseline_reference_rows or [
                list(row) for row in pipeline_rows_for_rescue if isinstance(row, list)
            ]
            audit_expected_row_count = _resolve_llm_expected_row_count(
                menu_expected_row_count=expected_weekly_row_count,
                pipeline_rows=pipeline_rows_for_rescue,
                observed_rows=[list(row) for row in rows if isinstance(row, list)],
                anchor_date_count=len(pipeline_anchor_dates),
            )
            llm_second_pass_audit = _run_optional_llm_reparse_audit(
                job_id=ocr_job_id,
                processing_stage="validation",
                pdf_bytes=llm_input_pdf_bytes,
                provider=main_provider,
                template=template_to_use,
                facility_id=facility_id,
                preferred_template_id=preferred_template_id,
                candidate_rows=[list(row) for row in rows if isinstance(row, list)],
                reference_rows=audit_reference_rows,
                baseline_rows=baseline_reference_rows,
                expected_row_count=audit_expected_row_count,
                metrics_patch=_current_reparse_quality_metadata(),
                result_state="processing",
            )
            llm_second_pass_audit = _augment_llm_reparse_audit_with_structural_feedback(
                llm_audit=llm_second_pass_audit,
                candidate_rows=[list(row) for row in rows if isinstance(row, list)],
                template=template_to_use,
                baseline_fields=_resolve_reparse_baseline_rows_for_structure(llm_reparse_baseline)[0],
                baseline_structure_rows=baseline_reference_rows,
                reference_rows=[list(row) for row in pipeline_rows_for_rescue if isinstance(row, list)],
                reference_fields=_row_fields_from_template(template_to_use) or _resolve_reparse_baseline_rows_for_structure(llm_reparse_baseline)[0],
            )
            if _llm_reparse_audit_requires_second_pass(llm_second_pass_audit):
                second_pass_template = dict(template_to_use)
                baseline_fields, baseline_structure_rows, _, _ = _resolve_reparse_baseline_rows_for_structure(
                    llm_reparse_baseline
                )
                use_structural_repair_prompt = (
                    llm_quantity_only_active
                    and _llm_reparse_audit_requires_structural_repair_prompt(llm_second_pass_audit)
                )
                if use_structural_repair_prompt:
                    second_pass_model = _resolve_provider_model_name(
                        provider=main_provider,
                        template=second_pass_template,
                    )
                    repair_system_prompt, repair_user_prompt = _build_quantity_only_repair_prompts(
                        provider=main_provider,
                        template=second_pass_template,
                        current_rows=[list(row) for row in rows if isinstance(row, list)],
                        baseline_rows=baseline_structure_rows,
                        baseline_fields=baseline_fields,
                        structural_rows=baseline_structure_rows,
                        structural_fields=baseline_fields,
                        expected_row_count=expected_weekly_row_count,
                        quality_error="sheet_structural_drift",
                        quality_detail={"evaluator_feedback": llm_second_pass_audit or {}},
                        first_pass_model=llm_primary_model,
                        target_model=second_pass_model,
                        evaluator_feedback=llm_second_pass_audit,
                    )
                    if main_provider == "openai":
                        second_pass_template["openai_ocr_prompt"] = repair_system_prompt
                        second_pass_template["openai_ocr_user_prompt"] = repair_user_prompt
                        second_pass_template["openai_ocr_enabled"] = True
                    else:
                        second_pass_template["gemini_ocr_prompt"] = repair_system_prompt
                        second_pass_template["gemini_ocr_user_prompt"] = repair_user_prompt
                        second_pass_template["gemini_ocr_enabled"] = True
                else:
                    second_pass_prompt = _build_llm_assist_prompt(
                        provider=main_provider,
                        template=second_pass_template,
                        pipeline_output=pipeline_output_payload,
                        llm_assist=True,
                        prompt_preset=prompt_preset,
                        failure_context=auto_fallback_context,
                        baseline=llm_reparse_baseline,
                        evaluator_feedback=llm_second_pass_audit,
                        draft_rows_override=[list(row) for row in rows if isinstance(row, list)],
                        draft_rows_label="First LLM inference candidate rows",
                        first_pass_rows_override=[list(row) for row in pipeline_rows_for_rescue if isinstance(row, list)],
                    )
                    if second_pass_prompt:
                        if main_provider == "openai":
                            second_pass_template["openai_ocr_prompt"] = second_pass_prompt
                            second_pass_template["openai_ocr_enabled"] = True
                            if ocr_prompt and ocr_prompt.strip():
                                second_pass_template["openai_ocr_user_prompt"] = ocr_prompt.strip()
                        else:
                            second_pass_template["gemini_ocr_prompt"] = second_pass_prompt
                            second_pass_template["gemini_ocr_enabled"] = True
                            if ocr_prompt and ocr_prompt.strip():
                                second_pass_template["gemini_ocr_user_prompt"] = ocr_prompt.strip()
                try:
                    second_extracted = _run_reparse_with_heartbeat(
                        ocr_job_id,
                        processing_stage="inference",
                        result_state="processing",
                        metrics_patch=_current_reparse_quality_metadata(),
                        func=lambda: extract_fax_data(
                            llm_input_pdf_bytes,
                            second_pass_template,
                            facility_id=facility_id,
                            preferred_template_id=preferred_template_id,
                        ),
                    )
                    second_rows = [list(row) for row in (second_extracted.table_rows or []) if isinstance(row, list)]
                    if second_rows:
                        rows = second_rows
                        tokens = second_extracted.tokens or []
                        date_strings = second_extracted.date_strings or date_strings
                        grid = second_extracted.grid or grid
                        extracted_data = second_extracted
                        llm_finish_reason = _extract_llm_finish_reason(second_extracted)
                        llm_truncated_output = _is_truncated_llm_output(second_extracted)
                        llm_feedback_second_pass_applied = True
                        second_debug = (
                            second_extracted.provider_debug
                            if isinstance(second_extracted.provider_debug, dict)
                            else {}
                        )
                        second_model = str(second_debug.get("model") or "").strip()
                        if second_model:
                            llm_repair_pass_model = second_model
                        template_to_use = second_pass_template
                        effective_prompt = _resolve_reparse_prompt_text(
                            provider=main_provider,
                            template=second_pass_template,
                            user_prompt=ocr_prompt,
                        )
                except OCRPipelineOutputPendingError:
                    raise
                except Exception as exc:  # noqa: BLE001
                    llm_feedback_second_pass_error = str(exc)
                    logger.warning(
                        "Reparse evaluator-guided second pass failed provider={} error={}",
                        main_provider,
                        llm_feedback_second_pass_error,
                    )
        if main_provider in {"openai", "gemini"}:
            final_debug = (
                extracted_data.provider_debug
                if extracted_data is not None and isinstance(extracted_data.provider_debug, dict)
                else {}
            )
            final_model = llm_repair_pass_model or llm_primary_model
            if not final_model and isinstance(final_debug, dict):
                final_model = str(final_debug.get("model") or "").strip() or None
            reparse_cost_info = _estimate_reparse_llm_cost(
                provider=main_provider,
                model=final_model,
                provider_debug=final_debug,
            )
            if reparse_cost_info:
                if isinstance(final_debug, dict):
                    final_debug = dict(final_debug)
                    final_debug["cost_estimate"] = reparse_cost_info
                    if extracted_data is not None:
                        extracted_data.provider_debug = final_debug
                if reparse_cost_info.get("over_soft_limit"):
                    logger.warning(
                        "Reparse LLM estimated cost over soft limit",
                        order_id=order_id,
                        provider=main_provider,
                        model=final_model,
                        estimated_cost_usd=reparse_cost_info.get("estimated_cost_usd"),
                        soft_limit_usd=reparse_cost_info.get("soft_limit_usd"),
                    )
        sample_row_text = ""
        if rows:
            try:
                sample_row_text = str(rows[0])[:320]
            except Exception:
                sample_row_text = ""
        logger.info(
            "Reparse extracted OCR rows provider={} rows={} dates={} tokens={} sample_row={}",
            main_provider,
            len(rows),
            len(date_strings),
            len(tokens),
            sample_row_text,
        )
        _maybe_dump_reparse_debug(order_id, message_id, extracted_data, tokens)
    except OCRPipelineOutputPendingError as exc:
        pending_result = _mark_reparse_job_awaiting_output(
            ocr_job_id, input_reference=exc.input_reference, output_reference=exc.output_reference,
            metrics_patch=_current_reparse_quality_metadata(), recovery_delay_seconds=exc.timeout_seconds,
        )
        return (pending_result, None) if pending_result is not None else (None, "ocr_pending_write_rejected")
    except Exception as exc:  # noqa: BLE001
        main_ocr_error = str(exc)
        logger.warning("Main OCR reparse failed (provider={}): {}", main_provider, str(exc))
        detailed_main_ocr_failure = f"main_ocr_failed:{main_provider}"
        if main_ocr_error.strip():
            detailed_main_ocr_failure = f"{detailed_main_ocr_failure}:{main_ocr_error.strip()}"
        llm_upstream_failure = bool(
            llm_assist
            or inference_provider in {"openai", "gemini"}
            or main_provider in {"openai", "gemini"}
        )
        if llm_upstream_failure:
            _update_reparse_job_progress(
                ocr_job_id,
                status="failed",
                processing_stage="inference",
                result_state="hard_failed",
                error_message=detailed_main_ocr_failure,
                metrics_patch={
                    **_current_reparse_quality_metadata(),
                    "error": detailed_main_ocr_failure,
                    "upstream_error_detail": main_ocr_error.strip() or None,
                    "confirmed_lines_retained": bool(before_count > 0),
                },
            )
            _maybe_dump_reparse_debug(
                order_id,
                message_id,
                None,
                [],
                None,
                error=detailed_main_ocr_failure,
            )
        else:
            _update_reparse_job_progress(
                ocr_job_id,
                status="failed",
                processing_stage="inference",
                result_state="hard_failed",
                error_message=detailed_main_ocr_failure,
                metrics_patch={
                    **_current_reparse_quality_metadata(),
                    "error": detailed_main_ocr_failure,
                    "upstream_error_detail": main_ocr_error.strip() or None,
                    "confirmed_lines_retained": bool(before_count > 0),
                },
            )
        try:
            rejected_result = _persist_reparse_diagnostics(
                order_id, pipeline_output_payload, ocr_job_id,
                {"error": detailed_main_ocr_failure, "provider": main_provider},
            )
        except Exception as persist_error:  # noqa: BLE001
            return None, f"{detailed_main_ocr_failure}:{persist_error}"
        return rejected_result, detailed_main_ocr_failure

    default_date = None
    if date_strings:
        parsed_dates = []
        for raw in date_strings:
            parsed = parse_date_string(raw, received_at, policy=policy, explicit_week=require_explicit_ingest_week(existing_week_code))
            if parsed:
                parsed_dates.append(parsed)
        if parsed_dates:
            default_date = min(parsed_dates)
    strict_llm_quantity = bool(
        llm_assist
        or inference_provider in {"openai", "gemini"}
        or main_provider in {"openai", "gemini"}
    )
    reparse_quantity_rules = _build_reparse_quantity_rules(
        policy.get("quantity_rules", {}),
        strict_llm_quantity=strict_llm_quantity,
    )
    if (
        main_provider in {"openai", "gemini"}
        and llm_quantity_only_active
        and rows
        and pipeline_rows_for_rescue
        and isinstance(llm_reparse_baseline, dict)
    ):
        baseline_fields, baseline_structure_rows, _, _ = _resolve_reparse_baseline_rows_for_structure(
            llm_reparse_baseline
        )
        final_realigned_rows, final_blank_anchor_realign = _realign_quantity_only_rows_to_structural_blank_anchors(
            rows=[list(row) for row in rows if isinstance(row, list)],
            template=template_to_use,
            structural_fields=baseline_fields,
            structural_rows=baseline_structure_rows,
            reference_rows=[list(row) for row in pipeline_rows_for_rescue if isinstance(row, list)],
            reference_fields=_row_fields_from_template(template_to_use) or baseline_fields,
        )
        if isinstance(final_blank_anchor_realign, dict) and final_blank_anchor_realign:
            rows = final_realigned_rows
            blank_anchor_realign = final_blank_anchor_realign
            if extracted_data is not None:
                extracted_data.table_rows = [list(row) for row in final_realigned_rows]
                provider_debug = (
                    extracted_data.provider_debug if isinstance(extracted_data.provider_debug, dict) else {}
                )
                provider_debug = dict(provider_debug)
                provider_debug["blank_anchor_realign"] = final_blank_anchor_realign
                extracted_data.provider_debug = provider_debug
        should_project_rows = _should_project_quantity_rows_to_structural_rows(
            rows=[list(row) for row in rows if isinstance(row, list)],
            structural_rows=baseline_structure_rows,
            template=template_to_use,
        )
        if should_project_rows:
            projected_rows, projected_stats = _project_quantity_only_rows_onto_structural_rows(
                rows=[list(row) for row in rows if isinstance(row, list)],
                template=template_to_use,
                structural_fields=baseline_fields,
                structural_rows=baseline_structure_rows,
            )
            if isinstance(projected_stats, dict) and projected_stats:
                rows = projected_rows
                structural_row_projection = projected_stats
                if extracted_data is not None:
                    extracted_data.table_rows = [list(row) for row in projected_rows]
                    provider_debug = (
                        extracted_data.provider_debug if isinstance(extracted_data.provider_debug, dict) else {}
                    )
                    provider_debug = dict(provider_debug)
                    provider_debug["structural_row_projection"] = projected_stats
                    extracted_data.provider_debug = provider_debug
    if main_provider in {"openai", "gemini"} and not preparse_validation_error:
        try:
            raw_recognizer = fax_extractor.require_raw_recognizer_payload(
                getattr(extracted_data, "recognizer_payload", None),
            )
        except ValueError as exc:
            preparse_validation_error = str(exc)
        else:
            # Validate the returned source, not aligned/merged presentation rows.
            quantity_rows = fax_extractor._rows_from_pipeline_payload(
                deepcopy(raw_recognizer), template_to_use,
            ) or []
            quantity_issues = _canonical_quantity_cell_issues(
                quantity_rows, _row_fields_from_template(template_to_use),
            )
            if not quantity_rows:
                preparse_validation_error = "lines_empty"
            elif quantity_issues:
                preparse_validation_error = "sheet_ocr_review_required"
                preparse_validation_detail = {"cell_issues": quantity_issues}
    if llm_full_table_active and not preparse_validation_error:
        candidate_returned_row_indexes = None
        candidate_returned_field_map = None
        authoritative_quantity_rows = None
        authoritative_quantity_projection = None
        if (
            extracted_data is not None
            and isinstance(extracted_data.provider_debug, dict)
            and isinstance(extracted_data.provider_debug.get("returned_row_indexes"), list)
        ):
            candidate_returned_row_indexes = [
                int(item)
                for item in extracted_data.provider_debug.get("returned_row_indexes")
                if str(item).strip().isdigit()
            ]
        if (
            extracted_data is not None
            and isinstance(extracted_data.provider_debug, dict)
            and isinstance(extracted_data.provider_debug.get("returned_row_fields"), dict)
        ):
            candidate_returned_field_map = {}
            for row_index, fields_for_row in extracted_data.provider_debug.get("returned_row_fields").items():
                try:
                    normalized_row_index = int(row_index)
                except Exception:
                    continue
                if not isinstance(fields_for_row, list):
                    continue
                normalized_fields = {
                    str(field or "").strip()
                    for field in fields_for_row
                    if str(field or "").strip()
                }
                if normalized_fields:
                    candidate_returned_field_map[normalized_row_index] = normalized_fields
        latest_draft_for_reparse = captured_read_input.get("draft")
        preserve_current_quantity_baseline = apply_gate_service.has_clean_saved_draft(latest_draft_for_reparse)
        quantity_projection_error = None
        if not preserve_current_quantity_baseline:
            try:
                authoritative_quantity_rows, authoritative_quantity_projection = _build_reparse_authoritative_quantity_baseline_rows(
                    baseline=llm_reparse_baseline,
                    template=template_to_use if isinstance(template_to_use, dict) else None,
                )
            except _CanonicalOcrProjectionError as exc:
                quantity_projection_error = str(exc)
        if quantity_projection_error:
            merged_rows = []
            llm_full_table_result = {"error": quantity_projection_error, "detail": {}}
        else:
            merged_rows, llm_full_table_result = _validate_and_merge_reparse_full_table_candidate(
                baseline=llm_reparse_baseline,
                candidate_rows=rows,
                candidate_returned_row_indexes=candidate_returned_row_indexes,
                candidate_returned_field_map=candidate_returned_field_map,
                authoritative_quantity_rows=authoritative_quantity_rows,
            )
        llm_full_table_merge_stats = dict(llm_full_table_result.get("detail") or {})
        if isinstance(authoritative_quantity_projection, dict) and authoritative_quantity_projection:
            llm_full_table_merge_stats["authoritative_quantity_projection"] = authoritative_quantity_projection
        provider_debug = (
            extracted_data.provider_debug if extracted_data is not None and isinstance(extracted_data.provider_debug, dict) else {}
        )
        provider_debug = dict(provider_debug)
        provider_debug["llm_full_table_mode"] = True
        provider_debug["llm_full_table_merge"] = llm_full_table_merge_stats
        if extracted_data is not None:
            extracted_data.provider_debug = provider_debug
        if llm_full_table_result.get("error"):
            preparse_validation_error = str(llm_full_table_result.get("error") or "").strip() or None
            preparse_validation_detail = llm_full_table_merge_stats or {}
        else:
            rows = [list(row) for row in merged_rows]
            if extracted_data is not None:
                extracted_data.table_rows = [list(row) for row in rows]
    lines = parse_order_lines(
        rows,
        template_to_use,
        received_at,
        reparse_quantity_rules,
        default_date=default_date,
        tokens=tokens,
        grid=grid.__dict__ if grid else None,
        pdf_bytes=llm_input_pdf_bytes if main_provider in {"openai", "gemini"} else pdf_bytes,
        date_policy=policy,
        explicit_week=require_explicit_ingest_week(existing_week_code),
    ) if not preparse_validation_error else []
    if not isinstance(pipeline_output_payload, dict) and pipeline_output_ref:
        pipeline_output_payload = _load_pipeline_output_with_retry(pipeline_output_ref)
    parsed_output_for_debug = deepcopy(pipeline_output_payload) if isinstance(pipeline_output_payload, dict) else None
    if isinstance(parsed_output_for_debug, dict):
        parsed_output_for_debug["_reparse_recognizer_result"] = {
            "pdf_receipt": deepcopy(getattr(
                llm_input_pdf_bytes if main_provider in {"openai", "gemini"} else pdf_bytes,
                "selected_pdf_receipt", None,
            )),
            "fields": _row_fields_from_template(template_to_use),
            "header": _sheet_header_from_template(_row_fields_from_template(template_to_use), template_to_use),
            "rows": deepcopy(rows), "date_strings": deepcopy(date_strings),
            "provider": main_provider,
            "provider_debug": deepcopy(getattr(extracted_data, "provider_debug", None)),
            "raw_recognizer_payload": deepcopy(getattr(extracted_data, "recognizer_payload", None)),
        }
    provider_fallback_blocked = False
    if (
        not lines
        and not preparse_validation_error
        and not llm_assist
        and main_provider not in {"openai", "gemini"}
        and not auto_fallback_applied
    ):
        provider_fallback_blocked = True
    if not lines and preparse_validation_error in {None, "lines_empty"}:
        sample_row = rows[0] if rows else None
        effective_provider = main_provider or "unknown"
        requested_provider_label = requested_provider or ""
        lines_empty_error = "provider_fallback_blocked" if provider_fallback_blocked else "lines_empty"
        if requested_provider_label and effective_provider != requested_provider_label:
            lines_empty_error = (
                f"lines_empty:provider_fallback:{requested_provider_label}->{effective_provider}"
            )
        sample_row_text = ""
        if sample_row is not None:
            try:
                sample_row_text = str(sample_row)[:320]
            except Exception:
                sample_row_text = ""
        logger.warning(
            "No lines extracted provider={} requested={} row_count={} sample_row={}",
            main_provider,
            requested_provider,
            len(rows),
            sample_row_text,
        )
        debug_payload = _build_reparse_debug_payload(
            provider=effective_provider,
            requested_provider=requested_provider_label or None,
            llm_assist=bool(llm_assist),
            rows=rows,
            lines_count=0,
            before_count=before_count,
            after_count=0,
            changed=False,
            date_strings=date_strings,
            extracted=extracted_data,
            parsed_output=parsed_output_for_debug,
            error=main_ocr_error,
            request_prompt=effective_prompt,
            normalized_lines=lines,
            reject_reasons=[lines_empty_error],
            llm_quantity_only_merge=llm_quantity_only_merge_stats or None,
            structural_row_projection=structural_row_projection,
            llm_cost=reparse_cost_info,
            llm_audit=llm_audit_result,
            pdf_variant_used=str(llm_input_pdf_meta.get("used") or "raw"),
            pdf_variant_fallback_reason=(
                str(llm_input_pdf_meta.get("fallback_reason") or "").strip() or None
            ),
            quality_metadata=_current_reparse_quality_metadata(),
        )
        if auto_fallback_applied:
            debug_payload["auto_fallback"] = dict(auto_fallback_context or {})
        if isinstance(llm_pre_inference_audit, dict) and llm_pre_inference_audit:
            debug_payload["llm_pre_inference_audit"] = llm_pre_inference_audit
        if isinstance(llm_second_pass_audit, dict) and llm_second_pass_audit:
            debug_payload["llm_second_pass_audit"] = llm_second_pass_audit
        if llm_feedback_second_pass_applied:
            debug_payload["llm_feedback_second_pass_applied"] = True
        if llm_feedback_second_pass_error:
            debug_payload["llm_feedback_second_pass_error"] = llm_feedback_second_pass_error
        if isinstance(blank_anchor_realign, dict) and blank_anchor_realign:
            debug_payload["blank_anchor_realign"] = blank_anchor_realign
        try:
            context_conflict = _order_context_conflict_detail(
                order_id=order_id,
                expected_facility_code=facility_id,
                expected_week_code=existing_week_code,
                expected_document_uri=document_uri,
                expected_lines_updated_at=existing_lines_updated_at,
            )
            if context_conflict is not None:
                _update_reparse_job_progress(
                    ocr_job_id,
                    status="failed",
                    processing_stage="stale_context",
                    result_state="hard_failed",
                    error_message="stale_order_context",
                    metrics_patch={
                        "error": "stale_order_context",
                        "context_conflict": context_conflict,
                        "confirmed_lines_retained": bool(before_count > 0),
                        **_current_reparse_quality_metadata(),
                    },
                )
                return None, "stale_order_context"
        except Exception as exc:  # noqa: BLE001
            logger.warning("Failed to save OCR debug cache on lines_empty", error=str(exc))
        _update_reparse_job_progress(
            ocr_job_id,
            status="failed",
            processing_stage="line_parse",
            result_state="hard_failed",
            error_message=lines_empty_error,
            metrics_patch={
                "provider": effective_provider,
                "requested_provider": requested_provider_label or None,
                "row_count": len(rows),
                "line_count": 0,
                "llm_assist": bool(llm_assist),
                "finish_reason": llm_finish_reason,
                "truncated_output": bool(llm_truncated_output),
                "rows_replaced_with_pipeline": bool(llm_rows_replaced_with_pipeline),
                "llm_quantity_only_merge": llm_quantity_only_merge_stats or None,
                "structural_row_projection": structural_row_projection or None,
                "primary_model": llm_primary_model,
                "repair_pass_applied": bool(llm_repair_pass_applied),
                "repair_pass_reason": llm_repair_pass_reason,
                "repair_pass_error": llm_repair_pass_error,
                "repair_pass_model": llm_repair_pass_model,
                "quality_error": reparse_quality_error,
                "quality_detail": reparse_quality_detail or {},
                "before_count": before_count,
                "after_count": 0,
                "changed": False,
                "error": lines_empty_error,
                "reject_reasons": [lines_empty_error],
                "llm_cost": reparse_cost_info or None,
                "llm_audit": llm_audit_result or None,
                "llm_pre_inference_audit": llm_pre_inference_audit or None,
                "llm_second_pass_audit": llm_second_pass_audit or None,
                "reused_first_pass": bool(reused_first_pass_payload),
                "pipeline_run_skipped": bool(reused_first_pass_payload),
                "llm_feedback_second_pass_applied": bool(llm_feedback_second_pass_applied),
                "llm_feedback_second_pass_error": llm_feedback_second_pass_error,
                "blank_anchor_realign": blank_anchor_realign or None,
                "auto_fallback_applied": bool(auto_fallback_applied),
                "auto_fallback_from_provider": auto_fallback_from_provider,
                "auto_fallback_reason": auto_fallback_reason,
                "pdf_variant_used": str(llm_input_pdf_meta.get("used") or "raw"),
                "pdf_variant_fallback_reason": (
                    str(llm_input_pdf_meta.get("fallback_reason") or "").strip() or None
                ),
                "confirmed_lines_retained": bool(before_count > 0),
                **_current_reparse_quality_metadata(),
            },
        )
        try:
            rejected_result = _persist_reparse_diagnostics(
                order_id, parsed_output_for_debug, ocr_job_id, debug_payload,
            )
        except Exception as exc:  # noqa: BLE001
            return None, str(exc)
        return rejected_result, lines_empty_error
    min_ratio = float(policy.get("menu_match_min_ratio", 0.72))
    week_resolution_lines: list[dict[str, Any]] = []
    for line in lines:
        if not isinstance(line, dict):
            continue
        normalized = dict(line)
        normalized["date"] = _parse_date_value(normalized.get("date"))
        week_resolution_lines.append(normalized)
    line_dates = [
        line.get("date")
        for line in week_resolution_lines
        if isinstance(line.get("date"), date)
    ]
    derived_week_id = month_id_from_dates(line_dates, received_at, policy, explicit_week=existing_week_code) if line_dates else None
    week_payload = parsed_output_for_debug if isinstance(parsed_output_for_debug, dict) else None
    week_id = _resolve_reparse_own_week(
        captured_week=existing_week_code,
        received_at=received_at,
        lines=week_resolution_lines,
        own_payload=week_payload,
    )
    if not week_id:
        return _rejected_reparse_result(order_id, week_payload, ocr_job_id, "week_unresolved")
    pipeline_payload_dates: set[date] = set()
    if isinstance(week_payload, dict):
        pipeline_payload_dates = {
            item
            for item in _collect_sheet_dates_from_payload(week_payload, received_at, template_to_use, explicit_week=require_explicit_ingest_week(existing_week_code))
            if isinstance(item, date)
        }
    reparse_position_entries = _build_reparse_position_menu_entries(
        week_id=week_id,
        template=template_to_use,
        facility_id=facility_id,
        lines=week_resolution_lines,
        rows=[list(row) for row in rows if isinstance(row, list)],
        parsed_output=week_payload,
        existing_lines=existing_line_anchors,
        extra_payload_dates=pipeline_payload_dates,
        received_at=received_at,
    )
    if "rows_for_quantity_quality" not in locals():
        rows_for_quantity_quality = [list(row) for row in rows if isinstance(row, list)]
    quantity_only_validation_enabled = bool(
        main_provider in {"openai", "gemini"}
        and llm_quantity_only_active
        and not llm_rows_replaced_with_pipeline
        and _rows_look_like_quantity_only(
            rows=[list(row) for row in rows_for_quantity_quality if isinstance(row, list)],
            template=template_to_use,
            rows_are_body_only=bool(reparse_quantity_rules.get("rows_are_body_only")),
        )
    )
    if (
        main_provider in {"openai", "gemini"}
        and llm_quantity_only_active
        and not llm_rows_replaced_with_pipeline
    ):
        week_menu_row_count = len(_build_position_menu_entries_safe(week_id, facility_id)) if week_id else 0
        quality_anchor_dates = {
            item
            for item in _collect_line_dates_for_position_scope(week_resolution_lines)
            if isinstance(item, date)
        } | pipeline_payload_dates
        quality_expected_row_count = _resolve_llm_expected_row_count(
            menu_expected_row_count=len(reparse_position_entries),
            fallback_expected_row_count=expected_weekly_row_count or week_menu_row_count,
            pipeline_rows=pipeline_rows_for_rescue,
            observed_rows=rows_for_quantity_quality,
            anchor_date_count=len(quality_anchor_dates),
        )
        if quality_expected_row_count > 0:
            if quantity_only_validation_enabled:
                reparse_quality_error, reparse_quality_detail = _evaluate_quantity_only_rows_quality(
                    rows=rows_for_quantity_quality,
                    template=template_to_use,
                    expected_row_count=quality_expected_row_count,
                    reference_rows=pipeline_rows_for_rescue,
                )
            llm_audit_result = _run_optional_llm_reparse_audit(
                job_id=ocr_job_id,
                processing_stage="validation",
                pdf_bytes=llm_input_pdf_bytes,
                provider=main_provider,
                template=template_to_use,
                facility_id=facility_id,
                preferred_template_id=preferred_template_id,
                candidate_rows=[list(row) for row in rows if isinstance(row, list)],
                reference_rows=[list(row) for row in pipeline_rows_for_rescue if isinstance(row, list)],
                baseline_rows=_resolve_reparse_baseline_rows_for_structure(llm_reparse_baseline)[1],
                expected_row_count=quality_expected_row_count,
                metrics_patch=_current_reparse_quality_metadata(),
                result_state="processing",
            )
            llm_audit_result = _augment_llm_reparse_audit_with_structural_feedback(
                llm_audit=llm_audit_result,
                candidate_rows=[list(row) for row in rows if isinstance(row, list)],
                template=template_to_use,
                baseline_fields=_resolve_reparse_baseline_rows_for_structure(llm_reparse_baseline)[0],
                baseline_structure_rows=_resolve_reparse_baseline_rows_for_structure(llm_reparse_baseline)[1],
                reference_rows=[list(row) for row in pipeline_rows_for_rescue if isinstance(row, list)],
                reference_fields=_row_fields_from_template(template_to_use) or _resolve_reparse_baseline_rows_for_structure(llm_reparse_baseline)[0],
            )
    if week_id:
        lines = _apply_menu_matching(lines, week_id, facility_id, min_ratio)
    lines, quantity_sanitize_stats = _sanitize_reparse_line_quantities(lines)
    if quantity_sanitize_stats and (
        quantity_sanitize_stats.get("quantity_adjusted", 0) > 0
        or quantity_sanitize_stats.get("quantity_dropped", 0) > 0
        or quantity_sanitize_stats.get("lines_dropped", 0) > 0
    ):
        logger.info(
            "Reparse quantity sanitize applied order_id={} adjusted={} dropped={} lines_dropped={} max_abs={}",
            order_id,
            quantity_sanitize_stats.get("quantity_adjusted", 0),
            quantity_sanitize_stats.get("quantity_dropped", 0),
            quantity_sanitize_stats.get("lines_dropped", 0),
            quantity_sanitize_stats.get("max_abs_qty"),
        )
    _update_reparse_job_progress(
        ocr_job_id,
        status="running",
        processing_stage="validation",
        result_state="processing",
        metrics_patch=_current_reparse_quality_metadata(),
    )
    validation_error = preparse_validation_error
    validation_detail = dict(preparse_validation_detail or {}) if isinstance(preparse_validation_detail, dict) else None
    if not validation_error:
        validation_error, validation_detail = _validate_reparse_lines_against_weekly_menu(
            lines=lines,
            week_id=week_id,
            facility_id=facility_id,
            ocr_rows=rows,
            template=template_to_use,
            entries_override=reparse_position_entries if reparse_position_entries else None,
            rows_are_body_only=bool(reparse_quantity_rules.get("rows_are_body_only")),
        )
    date_anchor_error: str | None = None
    date_anchor_detail: dict[str, Any] | None = None
    blank_anchor_error: str | None = None
    blank_anchor_detail: dict[str, Any] | None = None
    blank_anchor_validation_enabled = bool(quantity_only_validation_enabled and pipeline_rows_for_rescue)
    if blank_anchor_validation_enabled:
        baseline_fields, baseline_structure_rows, _, _ = _resolve_reparse_baseline_rows_for_structure(
            llm_reparse_baseline
        )
        blank_anchor_error, blank_anchor_detail = _validate_reparse_blank_anchor_drift(
            lines=lines,
            structural_fields=baseline_fields,
            structural_rows=baseline_structure_rows,
            reference_rows=[list(row) for row in pipeline_rows_for_rescue if isinstance(row, list)],
            reference_fields=_row_fields_from_template(template_to_use) or baseline_fields,
        )
    if (
        main_provider in {"openai", "gemini"}
        and llm_quantity_only_active
        and existing_line_anchors
    ):
        date_anchor_error, date_anchor_detail = _validate_reparse_date_anchor_stability(
            previous_lines=existing_line_anchors,
            candidate_lines=lines,
        )
    if not validation_error and date_anchor_error:
        validation_error = date_anchor_error
        validation_detail = date_anchor_detail or {}
    if not validation_error and blank_anchor_error:
        validation_error = blank_anchor_error
        validation_detail = blank_anchor_detail or {}
    if not validation_error and reparse_quality_error:
        validation_error = reparse_quality_error
        validation_detail = reparse_quality_detail or {}
    structural_projection_error, structural_projection_detail = (
        _validate_structural_projection_requires_manual_review(
            llm_quantity_only_active=llm_quantity_only_active,
            structural_row_projection=structural_row_projection,
        )
    )
    if not validation_error and structural_projection_error:
        validation_error = structural_projection_error
        validation_detail = structural_projection_detail or {}
    line_count_error, line_count_detail = _evaluate_reparse_line_count_regression(
        provider=main_provider,
        llm_quantity_only_active=llm_quantity_only_active,
        before_count=before_count,
        after_count=len(lines),
    )
    if not validation_error and line_count_error:
        validation_error = line_count_error
        validation_detail = line_count_detail or {}
    if (
        isinstance(llm_audit_result, dict)
        and str(llm_audit_result.get("status") or "").lower() == "fail"
    ):
        if main_provider in {"openai", "gemini"} and feedback_retry_depth < 1:
            logger.info(
                "Retrying reparse with evaluator feedback order_id={} provider={} depth={}",
                order_id,
                main_provider,
                feedback_retry_depth + 1,
            )
            return reparse_order(
                order_id,
                ocr_prompt=ocr_prompt,
                ocr_provider=main_provider,
                llm_assist=True,
                auto_fallback_context=auto_fallback_context,
                evaluator_feedback=llm_audit_result,
                feedback_retry_depth=feedback_retry_depth + 1,
                draft_rows_override=[list(row) for row in rows if isinstance(row, list)],
                draft_rows_label="Previous failed LLM inference candidate rows",
                workflow_attempt_id=workflow_attempt_id,
                expected_workflow_revision=_workflow_ocr_revision.get(),
                ocr_job_id=ocr_job_id,
                _original_request=original_request,
            )
        if not validation_error:
            validation_error = "sheet_llm_audit_failed"
            validation_detail = {
                "quality_issue": "llm_audit",
                "llm_audit": llm_audit_result,
            }
    if (
        not validation_error
        and isinstance(reparse_cost_info, dict)
        and _read_reparse_bool_env("OCR_REPARSE_COST_ENFORCE_HARD_LIMIT", True)
        and bool(reparse_cost_info.get("over_hard_limit"))
    ):
        validation_error = "llm_cost_limit_exceeded"
        validation_detail = {
            "estimated_cost_usd": reparse_cost_info.get("estimated_cost_usd"),
            "hard_limit_usd": reparse_cost_info.get("hard_limit_usd"),
            "soft_limit_usd": reparse_cost_info.get("soft_limit_usd"),
            "provider": reparse_cost_info.get("provider"),
            "model": reparse_cost_info.get("model"),
            "usage": reparse_cost_info.get("usage"),
            "pricing": reparse_cost_info.get("pricing"),
        }
    validation_warning_reasons: list[str] = []
    validation_warning_detail: dict[str, Any] | None = None
    if validation_error and not preparse_validation_error and _is_soft_warning_validation_error(validation_error):
        normalized_warning = str(validation_error).strip()
        if normalized_warning:
            validation_warning_reasons = [normalized_warning]
        validation_warning_detail = validation_detail if isinstance(validation_detail, dict) else {}
        logger.warning(
            "Reparse validation warned but accepted",
            order_id=order_id,
            provider=main_provider,
            warning_reasons=validation_warning_reasons,
            detail=validation_warning_detail,
        )
        validation_error = None
        validation_detail = None

    if validation_error:
        logger.warning(
            "Reparse validation rejected",
            order_id=order_id,
            provider=main_provider,
            validation_error=validation_error,
            detail=validation_detail,
        )
        debug_payload = _build_reparse_debug_payload(
            provider=main_provider,
            requested_provider=requested_provider or None,
            llm_assist=bool(llm_assist),
            rows=rows,
            lines_count=len(lines),
            before_count=before_count,
            after_count=len(lines),
            changed=None,
            date_strings=date_strings,
            extracted=extracted_data,
            parsed_output=parsed_output_for_debug,
            error=validation_error,
            request_prompt=effective_prompt,
            normalized_lines=lines,
            reject_reasons=[validation_error],
            validation_detail=validation_detail,
            llm_quantity_only_merge=llm_quantity_only_merge_stats or None,
            llm_cost=reparse_cost_info,
            llm_audit=llm_audit_result,
            pdf_variant_used=str(llm_input_pdf_meta.get("used") or "raw"),
            pdf_variant_fallback_reason=(
                str(llm_input_pdf_meta.get("fallback_reason") or "").strip() or None
            ),
            quality_metadata=_current_reparse_quality_metadata(),
        )
        if auto_fallback_applied:
            debug_payload["auto_fallback"] = dict(auto_fallback_context or {})
        if isinstance(llm_pre_inference_audit, dict) and llm_pre_inference_audit:
            debug_payload["llm_pre_inference_audit"] = llm_pre_inference_audit
        if isinstance(llm_second_pass_audit, dict) and llm_second_pass_audit:
            debug_payload["llm_second_pass_audit"] = llm_second_pass_audit
        if llm_feedback_second_pass_applied:
            debug_payload["llm_feedback_second_pass_applied"] = True
        if llm_feedback_second_pass_error:
            debug_payload["llm_feedback_second_pass_error"] = llm_feedback_second_pass_error
        if isinstance(blank_anchor_realign, dict) and blank_anchor_realign:
            debug_payload["blank_anchor_realign"] = blank_anchor_realign
        rejected_result = None
        try:
            if rows and isinstance(rows, list) and isinstance(parsed_output_for_debug, dict):
                rejected_result = _save_reparse_candidate_as_draft(
                    order_id=order_id,
                    template=template_to_use,
                    rows=[list(row) for row in rows if isinstance(row, list)],
                    before_digest=before_digest,
                    raw_output_override=parsed_output_for_debug,
                    workflow_job_id=ocr_job_id,
                    review_state="auto_apply_blocked",
                    review_blockers=[validation_error],
                    review_warnings=validation_warning_reasons,
                    diagnostics=debug_payload,
                )
            else:
                rejected_result = _persist_reparse_diagnostics(
                    order_id, parsed_output_for_debug, ocr_job_id, debug_payload,
                )
        except Exception as exc:  # noqa: BLE001
            logger.warning("Reparse rejected result persist failed", order_id=order_id, error=str(exc))
            return _rejected_reparse_result(
                order_id, parsed_output_for_debug, ocr_job_id, str(exc), debug_payload,
            )
        _update_reparse_job_progress(
            ocr_job_id,
            status="failed",
            processing_stage="rejected_review_saved" if rows else "validation",
            result_state="draft_ready_blocked" if rows else "hard_failed",
            error_message=validation_error,
            metrics_patch={
                "provider": main_provider,
                "requested_provider": requested_provider or None,
                "row_count": len(rows),
                "line_count": len(lines),
                "llm_assist": bool(llm_assist),
                "finish_reason": llm_finish_reason,
                "truncated_output": bool(llm_truncated_output),
                "rows_replaced_with_pipeline": bool(llm_rows_replaced_with_pipeline),
                "llm_quantity_only_merge": llm_quantity_only_merge_stats or None,
                "structural_row_projection": structural_row_projection or None,
                "before_count": before_count,
                "after_count": len(lines),
                "changed": False,
                "error": validation_error,
                "reject_reasons": [validation_error],
                "validation_detail": validation_detail or {},
                "primary_model": llm_primary_model,
                "repair_pass_applied": bool(llm_repair_pass_applied),
                "repair_pass_reason": llm_repair_pass_reason,
                "repair_pass_error": llm_repair_pass_error,
                "repair_pass_model": llm_repair_pass_model,
                "quality_error": reparse_quality_error,
                "quality_detail": reparse_quality_detail or {},
                "llm_cost": reparse_cost_info or None,
                "llm_audit": llm_audit_result or None,
                "llm_pre_inference_audit": llm_pre_inference_audit or None,
                "llm_second_pass_audit": llm_second_pass_audit or None,
                "llm_feedback_second_pass_applied": bool(llm_feedback_second_pass_applied),
                "llm_feedback_second_pass_error": llm_feedback_second_pass_error,
                "blank_anchor_realign": blank_anchor_realign or None,
                "auto_fallback_applied": bool(auto_fallback_applied),
                "auto_fallback_from_provider": auto_fallback_from_provider,
                "auto_fallback_reason": auto_fallback_reason,
                "pdf_variant_used": str(llm_input_pdf_meta.get("used") or "raw"),
                "pdf_variant_fallback_reason": (
                    str(llm_input_pdf_meta.get("fallback_reason") or "").strip() or None
                ),
                "confirmed_lines_retained": bool(before_count > 0),
                **_current_reparse_quality_metadata(),
            },
        )
        return rejected_result, validation_error
    lines = _ensure_unique_line_ids(lines)
    after_digest = _line_digest(lines)
    after_count = len(lines)
    reparse_changed = before_digest != after_digest

    _update_reparse_job_progress(
        ocr_job_id,
        status="running",
        processing_stage="apply",
        result_state="processing",
        metrics_patch=_current_reparse_quality_metadata(),
    )
    reparse_debug = _build_reparse_debug_payload(
        provider=main_provider,
        requested_provider=requested_provider or None,
        llm_assist=bool(llm_assist),
        rows=rows,
        lines_count=after_count,
        before_count=before_count,
        after_count=after_count,
        changed=reparse_changed,
        date_strings=date_strings,
        extracted=extracted_data,
        parsed_output=parsed_output_for_debug,
        error=main_ocr_error,
        request_prompt=effective_prompt,
        normalized_lines=lines,
        validation_detail=reparse_quality_detail,
        warning_reasons=validation_warning_reasons or None,
        warning_detail=validation_warning_detail or None,
        llm_quantity_only_merge=llm_quantity_only_merge_stats or None,
        structural_row_projection=structural_row_projection,
        llm_cost=reparse_cost_info,
        llm_audit=llm_audit_result,
        pdf_variant_used=str(llm_input_pdf_meta.get("used") or "raw"),
        pdf_variant_fallback_reason=(
            str(llm_input_pdf_meta.get("fallback_reason") or "").strip() or None
        ),
        quality_metadata=_current_reparse_quality_metadata(),
    )
    if auto_fallback_applied:
        reparse_debug["auto_fallback"] = dict(auto_fallback_context or {})
    if isinstance(llm_pre_inference_audit, dict) and llm_pre_inference_audit:
        reparse_debug["llm_pre_inference_audit"] = llm_pre_inference_audit
    if isinstance(llm_second_pass_audit, dict) and llm_second_pass_audit:
        reparse_debug["llm_second_pass_audit"] = llm_second_pass_audit
    if llm_feedback_second_pass_applied:
        reparse_debug["llm_feedback_second_pass_applied"] = True
    if llm_feedback_second_pass_error:
        reparse_debug["llm_feedback_second_pass_error"] = llm_feedback_second_pass_error
    if isinstance(blank_anchor_realign, dict) and blank_anchor_realign:
        reparse_debug["blank_anchor_realign"] = blank_anchor_realign
    terminal_metrics = {
            "provider": main_provider,
            "requested_provider": requested_provider or None,
            "row_count": len(rows),
            "line_count": after_count,
            "llm_assist": bool(llm_assist),
            "finish_reason": llm_finish_reason,
            "truncated_output": bool(llm_truncated_output),
            "rows_replaced_with_pipeline": bool(llm_rows_replaced_with_pipeline),
            "llm_quantity_only_merge": llm_quantity_only_merge_stats or None,
            "primary_model": llm_primary_model,
            "repair_pass_applied": bool(llm_repair_pass_applied),
            "repair_pass_reason": llm_repair_pass_reason,
            "repair_pass_error": llm_repair_pass_error,
            "repair_pass_model": llm_repair_pass_model,
            "quality_error": reparse_quality_error,
            "quality_detail": reparse_quality_detail or {},
            "warning_reasons": validation_warning_reasons or [],
            "warning_detail": validation_warning_detail or {},
            "llm_cost": reparse_cost_info or None,
            "llm_audit": llm_audit_result or None,
            "llm_pre_inference_audit": llm_pre_inference_audit or None,
            "llm_second_pass_audit": llm_second_pass_audit or None,
            "reused_first_pass": bool(reused_first_pass_payload),
            "pipeline_run_skipped": bool(reused_first_pass_payload),
            "llm_feedback_second_pass_applied": bool(llm_feedback_second_pass_applied),
            "llm_feedback_second_pass_error": llm_feedback_second_pass_error,
            "blank_anchor_realign": blank_anchor_realign or None,
            "structural_row_projection": structural_row_projection or None,
            "before_count": before_count,
            "after_count": after_count,
            "before_digest": before_digest,
            "after_digest": after_digest,
            "changed": reparse_changed,
            "auto_fallback_applied": bool(auto_fallback_applied),
            "auto_fallback_from_provider": auto_fallback_from_provider,
            "auto_fallback_reason": auto_fallback_reason,
            "pdf_variant_used": str(llm_input_pdf_meta.get("used") or "raw"),
            "pdf_variant_fallback_reason": (
                str(llm_input_pdf_meta.get("fallback_reason") or "").strip() or None
            ),
            "confirmed_lines_retained": False,
            **_current_reparse_quality_metadata(),
        }
    own_pipeline_payload = parsed_output_for_debug
    if own_pipeline_payload is None and pipeline_output_ref:
        own_pipeline_payload = _load_pipeline_output_with_retry(pipeline_output_ref)
    if not isinstance(own_pipeline_payload, dict):
        return None, "reparse_pipeline_result_missing"
    with _ocr_result_transaction() as session:
        if not _workflow_attempt_write_fence(session, ocr_job_id, order_id):
            return None, "workflow_attempt_superseded"
        order = session.get(Order, order_id)
        if order is None:
            return None, "order_not_found"
        context_conflict = _order_context_conflict_detail(
            order_id=order_id, expected_facility_code=facility_id,
            expected_week_code=existing_week_code, expected_document_uri=document_uri,
            expected_lines_updated_at=existing_lines_updated_at,
        )
        if context_conflict is not None:
            return None, "stale_order_context"
        persisted_evidence = persist_ocr_evidence_run(
            order_id, own_pipeline_payload, schema_version="v2_reparse_pipeline_result",
            producer_version="reparse_pipeline_result", source="reparse-pipeline-result",
            workflow_job_id=ocr_job_id, refresh_workflow=False,
            result_disposition="accepted", write_session=session,
        )
        if not isinstance(persisted_evidence, dict) or not persisted_evidence.get("id"):
            raise ValueError("reparse_evidence_persist_failed")
        reparse_evidence_run_id = persisted_evidence["id"]
        session.execute(delete(OrderLine).where(OrderLine.order_id == order.id))
        for line in lines:
            session.add(
                OrderLine(
                    id=line.get("id") or _make_line_id(),
                    order_id=order.id,
                    line_id=line.get("line_id"),
                    date=_parse_date_value(line.get("date")),
                    daypart=line.get("daypart"),
                    menu_name=line.get("menu_name"),
                    diet_type=line.get("diet_type"),
                    area_id=line.get("area_id"),
                    bag_type=line.get("bag_type"),
                    quantity_original=line.get("quantity_original"),
                    quantity_corrected=line.get("quantity_corrected"),
                    change_note=line.get("change_note"),
                )
            )
        order.lines_updated_at = datetime.utcnow()
        resolved_week_has_menu = bool(week_id and _build_position_menu_entries_safe(week_id, facility_id, session=session))
        update_week_code_to = (
            (_normalize_auto_week_value_for_order(order, week_id) or week_id)
            if week_id and resolved_week_has_menu
            else (
                (_normalize_auto_week_value_for_order(order, derived_week_id) or derived_week_id)
                if derived_week_id and week_id == derived_week_id
                else None
            )
        )
        current_week_code = _normalize_sheet_week_candidate(order.week_code)
        if update_week_code_to:
            _apply_system_managed_order_week_code(order, update_week_code_to)
        elif not current_week_code and week_id:
            _apply_system_managed_order_week_code(order, week_id)
        session.flush()
        session.refresh(order)
        execution_input = current_nonworkflow_execution()
        if execution_input is not None:
            advance_nonworkflow_order_input(session, execution_input, order)
        serialized = serialize_order(order, allow_unresolved_menu_amount=True)
        written_week = order.week_code
        cache_payload = deepcopy(own_pipeline_payload)
        cache_payload["_ocr_execution"] = deepcopy(persisted_evidence["payload_json"]["_ocr_execution"])
        cache_payload["_reparse_debug"] = reparse_debug
        cache_saved = _save_order_ocr_cache(
            order_id, cache_payload, job_id=ocr_job_id, persist_evidence=False,
            preserve_existing_artifacts=False, refresh_workflow=False, write_session=session,
        )
        if cache_saved is None:
            raise ValueError("reparse_cache_persist_failed")
        published = _publish_applied_reparse_revision(
            order_id=order_id, template=template_to_use,
            previous_sheet_context=previous_current_sheet_context,
            current_sheet_context={"row_ids": list((previous_current_sheet_context or {}).get("row_ids") or [])},
            ocr_rows=[list(row) for row in rows if isinstance(row, list)],
            raw_output_payload=cache_payload, provider=main_provider,
            llm_assist=bool(llm_assist), ocr_job_id=ocr_job_id,
            evidence_run_id=reparse_evidence_run_id, warning_reasons=validation_warning_reasons,
            write_session=session,
        )
        if published is None:
            raise ValueError("reparse_revision_persist_failed")
        serialized["terminal_receipt"] = _complete_ocr_rerun_in_session(
            session, order_id, ocr_job_id, persisted_evidence,
            error=None, metrics_patch=terminal_metrics,
        )
    try:
        record_event(
            "order_reparse", actor="system", target=order_id,
            fac=facility_id, wek=written_week, metadata={"line_count": len(lines)},
        )
    except Exception as exc:
        logger.warning("Reparse event failed after terminal commit", order_id=order_id, error=str(exc))
    serialized["reparse"] = {
        "before_count": before_count, "after_count": after_count,
        "before_digest": before_digest, "after_digest": after_digest,
        "provider": main_provider, "changed": reparse_changed,
        "warning_reasons": validation_warning_reasons or [],
        "warning_detail": validation_warning_detail or {},
        "llm_cost": reparse_cost_info or None, "adopted": False,
    }
    serialized["ocr_job_id"] = ocr_job_id
    serialized["reparse_evidence_run_id"] = reparse_evidence_run_id
    serialized["workflow_attempt_id"] = _workflow_ocr_attempt_id.get()
    serialized["workflow_revision"] = _workflow_ocr_revision.get()
    return serialized, serialized["terminal_receipt"]["error"]


def _maybe_dump_reparse_debug(
    order_id: str,
    message_id: Optional[str],
    extracted,
    tokens: list[dict],
    grid: Optional[object] = None,
    error: Optional[str] = None,
) -> None:
    dump_dir = os.getenv("OCR_DEBUG_DUMP_DIR")
    if not dump_dir:
        return
    try:
        path = Path(dump_dir) / f"ocr_reparse_{order_id}.json"
        raw_text = getattr(extracted, "raw_text", None) if extracted else None
        provider_debug = getattr(extracted, "provider_debug", None) if extracted else None
        data = {
            "order_id": order_id,
            "message_id": message_id,
            "ocr_provider": getattr(extracted, "ocr_provider", None),
            "ocr_error": error,
            "date_strings": getattr(extracted, "date_strings", []) if extracted else [],
            "token_count": len(tokens or []),
            "tokens": tokens,
            "raw_text": raw_text,
            "provider_debug": provider_debug if isinstance(provider_debug, dict) else None,
            "grid": (
                {
                    "table_box": grid.table_box,
                    "column_edges": grid.column_edges,
                    "row_edges": grid.row_edges,
                    "confidence": grid.confidence,
                }
                if grid
                else None
            ),
        }
        path.write_text(json.dumps(data, ensure_ascii=True, indent=2), encoding="utf-8")
        logger.info("Reparse OCR debug dumped", path=str(path))
    except Exception:  # noqa: BLE001
        logger.exception("Failed to dump reparse OCR debug data")


def set_facility(
    order_id: str,
    facility_code: str,
    *,
    expected_current_facility: str | None = None,
    enforce_conflict_guard: bool = False,
    refresh_current_sheet: bool = False,
) -> bool | tuple[bool, str | None]:
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return (False, "order_not_found") if enforce_conflict_guard else False
        if enforce_conflict_guard:
            conflict = _selection_conflict_detail(
                field="facility",
                current_value=order.facility_code,
                expected_value=expected_current_facility,
                desired_value=facility_code,
            )
            if conflict is not None:
                return False, conflict["error"]
        if str(order.facility_code or "").strip() == str(facility_code or "").strip():
            return (True, None) if enforce_conflict_guard else True
        order.facility_code = facility_code
        logger.info("Order facility set", order_id=order_id, facility_code=facility_code)
        record_event(
            "order_facility_set",
            actor="system",
            target=order_id,
            fac=facility_code,
            wek=order.week_code,
        )
    _invalidate_orders_cache()
    order_current_state_service.delete_current_state(order_id)
    if refresh_current_sheet:
        try:
            _rebuild_current_sheet_for_facility_schema(
                order_id,
                edited_by="facility-selection-refresh",
            )
        except Exception as exc:  # noqa: BLE001
            logger.warning("Current sheet rebuild failed after facility update", order_id=order_id, error=str(exc))
    try:
        workflow_state_service.refresh_workflow_state(order_id)
    except Exception as exc:  # noqa: BLE001
        logger.warning("Workflow state refresh failed after facility update", order_id=order_id, error=str(exc))
    return (True, None) if enforce_conflict_guard else True


def set_week(
    order_id: str,
    week_code: str,
    *,
    expected_current_week: str | None = None,
    enforce_conflict_guard: bool = False,
    allow_non_calendar_exception: bool = False,
) -> bool | tuple[bool, str | None]:
    normalized_week = _normalize_sheet_week_value(week_code)
    if not normalized_week:
        raise ValueError("week_code_invalid")
    is_explicit_exception_range = "@" in normalized_week
    normalized_expected_week = (
        _normalize_sheet_week_value(expected_current_week)
        or str(expected_current_week or "").strip()
        or None
    )
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return (False, "order_not_found") if enforce_conflict_guard else False
        if not allow_non_calendar_exception and not is_explicit_exception_range:
            normalized_week = _normalize_auto_week_value_for_order(order, normalized_week) or normalized_week
        if enforce_conflict_guard:
            conflict = _week_selection_conflict_detail(
                order=order,
                expected_value=normalized_expected_week,
                desired_value=normalized_week,
            )
            if conflict is not None:
                return False, conflict["error"]
        if (_normalize_sheet_week_value(order.week_code) or order.week_code or "") == normalized_week:
            return (True, None) if enforce_conflict_guard else True
        order.week_code = normalized_week
        logger.info("Order week set", order_id=order_id, week_code=normalized_week)
        record_event(
            "order_week_set",
            actor="system",
            target=order_id,
            fac=order.facility_code,
            wek=normalized_week,
        )
    _invalidate_orders_cache()
    order_current_state_service.delete_current_state(order_id)
    try:
        workflow_state_service.refresh_workflow_state(order_id)
    except Exception as exc:  # noqa: BLE001
        logger.warning("Workflow state refresh failed after week update", order_id=order_id, error=str(exc))
    return (True, None) if enforce_conflict_guard else True


def choose_critical_decision(
    order_id: str,
    decision_type: str,
    selected_value: str,
    *,
    selected_by: str | None = None,
) -> tuple[dict[str, Any] | None, str | None]:
    latest_evidence = _resolve_active_ocr_evidence_run(order_id)
    if not isinstance(latest_evidence, dict):
        return None, "selected_ocr_evidence_missing"
    current_evidence_run_id = str((latest_evidence or {}).get("id") or "").strip() or None
    current_decision = critical_decision_service.get_latest_decision(order_id, decision_type)
    if isinstance(current_decision, dict):
        base_evidence_run_id = str(current_decision.get("base_evidence_run_id") or "").strip() or None
        if base_evidence_run_id and current_evidence_run_id and base_evidence_run_id != current_evidence_run_id:
            return None, "decision_stale"
    chosen = critical_decision_service.choose_decision(
        order_id,
        decision_type,
        selected_value,
        selected_by=selected_by,
        current_evidence_run_id=current_evidence_run_id,
    )
    if not isinstance(chosen, dict):
        return None, "decision_not_found"
    normalized_type = str(decision_type or "").strip().lower()
    if normalized_type == "facility":
        result = set_facility(order_id, selected_value)
        if result is False or result == (False, None):
            return None, "facility_update_failed"
    elif normalized_type == "week":
        try:
            result = set_week(order_id, selected_value)
        except ValueError:
            return None, "week_invalid"
        if result is False or result == (False, None):
            return None, "week_update_failed"
    order_current_state_service.delete_current_state(order_id)
    try:
        workflow = workflow_state_service.refresh_workflow_state(order_id)
    except Exception as exc:  # noqa: BLE001
        logger.warning("Workflow state refresh failed after critical choice", order_id=order_id, error=str(exc))
        workflow = None
    return {
        "decision": chosen,
        "workflow_state": workflow,
    }, None


def save_order_facility_template_columns(
    order_id: str,
    columns: list[dict[str, Any]] | None,
) -> tuple[dict[str, Any] | None, str | None]:
    _ = order_id, columns
    return None, "legacy_facility_template_columns_removed"


def set_status(order_id: str, status: str) -> bool:
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return False
        order.status = status
        logger.info("Order status set", order_id=order_id, status=status)
        return True
